def _repo_root() -> Path:
    return Path.cwd()


_GOAL_RUNTIME_MODULE: Optional[Any] = None


def _goal_runtime_module() -> Any:
    global _GOAL_RUNTIME_MODULE
    if _GOAL_RUNTIME_MODULE is not None:
        return _GOAL_RUNTIME_MODULE
    _GOAL_RUNTIME_MODULE = importlib.import_module("run_goal_intake")
    return _GOAL_RUNTIME_MODULE


def _coerce_positive_int(value: Any) -> Optional[int]:
    if value is None:
        return None
    try:
        parsed = int(str(value).strip())
    except Exception:
        return None
    if parsed <= 0:
        return None
    return parsed


def _coerce_exon_label_int(value: Any) -> Optional[int]:
    """Convert an explicit exon number without reinterpreting a description."""
    return exon_number(value)


def _coerce_standard_exon_constraint_label(value: Any) -> Optional[int]:
    return exon_number(value)


def _chemistry_recommendation_payload(value: Any) -> Dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    recommendation = value.get("recommendation")
    if isinstance(recommendation, dict):
        return recommendation
    return value


def _normalized_chemistry_label(value: Any) -> str:
    from aso_chemistry import require_native_linkage_identity
    require_native_linkage_identity(value)
    from aso_chemistry import chemistry_label
    recommendation = _chemistry_recommendation_payload(value)
    label = value if isinstance(value, str) else (
        recommendation.get("CHEMISTRY") or recommendation.get("chemistry")
        or recommendation.get("profile") or recommendation.get("name")
    )
    return chemistry_label(label) or ""


def _chemistry_platform(value: Any) -> str:
    recommendation = _chemistry_recommendation_payload(value)
    platform = str(recommendation.get("platform") or "").strip()
    if platform:
        return platform
    label = _normalized_chemistry_label(value)
    runtime = _goal_runtime_module()
    platform_fn = getattr(runtime, "_chemistry_platform_for_label", None)
    if callable(platform_fn):
        try:
            return str(platform_fn(label) or "")
        except Exception:
            pass
    from aso_chemistry import gapmer_architecture, STERIC_SUGARS
    if gapmer_architecture(label):
        return "gapmer"
    if label in STERIC_SUGARS:
        return "steric_blocker"
    return ""


def _chemistry_length(value: Any) -> Optional[int]:
    recommendation = _chemistry_recommendation_payload(value)
    length = _coerce_positive_int(recommendation.get("length"))
    if length is not None:
        return length
    label = _normalized_chemistry_label(value)
    runtime = _goal_runtime_module()
    length_fn = getattr(runtime, "_chemistry_length_for_label", None)
    if callable(length_fn):
        try:
            return _coerce_positive_int(length_fn(label))
        except Exception:
            return None
    from aso_chemistry import gapmer_architecture, STERIC_SUGARS
    architecture = gapmer_architecture(label)
    if architecture:
        return architecture.length
    if label in STERIC_SUGARS:
        return 20
    return None


def _chemistry_group_id(value: Any) -> str:
    label = _normalized_chemistry_label(value) or _chemistry_platform(value) or "chemistry"
    length = _chemistry_length(value)
    parts = [label]
    if length is not None:
        parts.append(str(length))
    return re.sub(r"[^a-z0-9]+", "_", "_".join(parts).lower()).strip("_") or "chemistry"


def _chemistry_payload_from_label(
    label: Any,
    *,
    rationale: str = "",
    source: str = "",
) -> Dict[str, Any]:
    normalized = _normalized_chemistry_label(label)
    if not normalized:
        return {}
    recommendation: Dict[str, Any] = {
        "CHEMISTRY": normalized,
        "platform": _chemistry_platform(normalized),
        "length": _chemistry_length(normalized),
    }
    if rationale:
        recommendation["rationale"] = rationale
    payload: Dict[str, Any] = {"recommendation": recommendation}
    if source:
        payload["source"] = source
    return payload


def _canonicalize_chemistry_payload(value: Any, *, source_hint: str = "") -> Dict[str, Any]:
    from aso_chemistry import canonical_chemistry_configuration
    recommendation = canonical_chemistry_configuration(value)
    if not recommendation:
        return {}
    payload = {"recommendation": recommendation}
    source = source_hint or (str(value.get("source") or "").strip() if isinstance(value, dict) else "")
    if source:
        payload["source"] = source
    if isinstance(value, dict) and isinstance(value.get("chemical_requirements"), list):
        from .chemical_requirements import require_native_requirement_capabilities, requirement_configuration_errors
        requirements = value["chemical_requirements"]
        require_native_requirement_capabilities(requirements)
        errors = requirement_configuration_errors(requirements, recommendation)
        if errors:
            raise ValueError("; ".join(errors))
        payload["chemical_requirements"] = deepcopy(requirements)
    if isinstance(value, dict) and isinstance(value.get("mechanism_review"), dict):
        from .chemistry_mechanism import recommendation_digest
        if value["mechanism_review"].get("recommendation_sha256") == recommendation_digest(payload):
            payload["mechanism_review"] = deepcopy(value["mechanism_review"])
    return payload


def _fallback_chemistry_payload(modality: str, goal: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    deferred = _unselected_chemistry_payload(goal)
    if deferred:
        return deferred
    constraints = (goal or {}).get("constraints") or {}
    if (goal or {}).get("chemistry") or (isinstance(constraints, dict) and constraints.get("chemistry")):
        raise ValueError("Explicit chemistry could not be resolved. Retain its description for clarification; a default would change the requested molecule.")
    modality_norm = str(modality or "").strip().lower()
    intent = str((goal or {}).get("intent") or "").strip().lower() if isinstance(goal, dict) else ""
    if modality_norm == "gapmer" or intent == "knockdown":
        return _chemistry_payload_from_label(
            "5-10-5",
            rationale="Default gapmer chemistry applied because no explicit per-program chemistry was available.",
            source="fallback",
        )
    return _chemistry_payload_from_label(
        "steric-hindrance",
        rationale="Default steric blocker chemistry applied because no explicit per-program chemistry was available.",
        source="fallback",
    )


def _requested_oligo_length(goal: Optional[Dict[str, Any]]) -> Optional[int]:
    if not isinstance(goal, dict):
        return None
    candidates: List[Any] = []
    for container in (
        goal,
        goal.get("constraints") if isinstance(goal.get("constraints"), dict) else {},
        goal.get("sequence_constraints") if isinstance(goal.get("sequence_constraints"), dict) else {},
        goal.get("candidate_parameters") if isinstance(goal.get("candidate_parameters"), dict) else {},
        goal.get("chemistry") if isinstance(goal.get("chemistry"), dict) else {},
    ):
        if not isinstance(container, dict):
            continue
        for key in (
            "aso_length_nt",
            "oligo_length_nt",
            "length_nt",
            "tile_length",
            "tile_len",
            "aso_length",
            "oligo_length",
            "length",
            "chemistry_length",
        ):
            if key in container:
                candidates.append(container.get(key))
        recommendation = container.get("recommendation")
        if isinstance(recommendation, dict):
            for key in ("length", "length_nt", "aso_length_nt", "oligo_length_nt"):
                if key in recommendation:
                    candidates.append(recommendation.get(key))
    for candidate in candidates:
        length = _coerce_positive_int(candidate)
        if length is not None:
            return length
    return None


def _has_chemistry_policy_conflict(goal: Any) -> bool:
    return (
        isinstance(goal, dict)
        and goal.get("chemistry_policy") == "leave_unspecified"
        and bool(goal.get("chemistry"))
        and _normalized_chemistry_label(goal["chemistry"]) != "unspecified"
    )


def _chemistry_policy_conflicts(structured_goal: Any) -> Dict[str, Dict[str, Any]]:
    """Identify contradictory declarations without choosing the user's intent.

    Check each declaration scope independently. A program's explicit chemistry
    overrides an inherited deferral, and a program's deferral clears inherited
    chemistry; those supported overrides are not contradictions.
    """
    if not isinstance(structured_goal, dict):
        return {}
    scopes = [("", structured_goal)]
    programs = structured_goal.get("design_programs")
    if isinstance(programs, list):
        scopes.extend((f"design_programs[{index}].", program)
                      for index, program in enumerate(programs)
                      if isinstance(program, dict))
    conflicts = {}
    for prefix, scope in scopes:
        if _has_chemistry_policy_conflict(scope):
            policy_path = prefix + "chemistry_policy"
            conflicts[policy_path] = {
                "reason": (
                    "Explicit chemistry conflicts with leave_unspecified in the same scope. "
                    "Resolve from user evidence: preserve requested chemistry when selection "
                    "is allowed, or remove unsupported chemistry when the user explicitly "
                    "defers it. Do not silently choose between these instructions."
                ),
                "chemistry_path": prefix + "chemistry",
                "policy_path": policy_path,
                "explicit_chemistry": deepcopy(scope["chemistry"]),
            }
    return conflicts


def _unselected_chemistry_payload(goal: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Honor a typed nonselection instruction, separately from missing input."""
    if not isinstance(goal, dict) or goal.get("chemistry_policy") != "leave_unspecified":
        return {}
    if _has_chemistry_policy_conflict(goal):
        raise ValueError("Explicit chemistry conflicts with chemistry_policy=leave_unspecified; resolve the goal before design.")
    return {"recommendation": {
        "CHEMISTRY": "unspecified", "platform": "",
        "length": _requested_oligo_length(goal) or 20,
        "rationale": "Base-sequence design only; chemical architecture and synthesis platform remain unspecified as requested.",
    }, "source": "explicit_chemistry_policy"}


def _apply_requested_length_to_chemistry_payload(
    payload: Dict[str, Any],
    requested_length: Optional[int],
) -> Dict[str, Any]:
    if not isinstance(payload, dict) or not requested_length:
        return payload
    from aso_chemistry import gapmer_architecture
    architecture = gapmer_architecture(_normalized_chemistry_label(payload))
    profile_length = architecture.length if architecture else None
    if profile_length is not None and profile_length != requested_length:
        raise ValueError(
            f"Selected gapmer architecture requires {profile_length} nt, but the requested "
            f"oligo length is exactly {requested_length} nt. Resolve this chemistry/length "
            "conflict before constructing molecules; do not silently relabel the architecture."
        )
    patched = deepcopy(payload)
    recommendation = patched.setdefault("recommendation", {})
    if not isinstance(recommendation, dict):
        recommendation = {}
        patched["recommendation"] = recommendation
    existing_length = _coerce_positive_int(recommendation.get("length"))
    if existing_length is not None and existing_length != requested_length:
        patched["requested_length_override"] = {
            "requested_length_nt": requested_length,
            "model_recommended_length_nt": existing_length,
        }
    recommendation["length"] = requested_length
    return patched


def _design_goal_for_program(
    structured_goal: Dict[str, Any],
    program: Optional[Dict[str, Any]],
    runtime: Any,
) -> Dict[str, Any]:
    design_program_goal_copy = getattr(runtime, "_design_program_goal_copy", None)
    if callable(design_program_goal_copy) and isinstance(program, dict):
        try:
            goal = design_program_goal_copy(structured_goal, program)
        except Exception:
            goal = deepcopy(structured_goal)
    else:
        goal = deepcopy(structured_goal)
    if not isinstance(goal, dict):
        goal = deepcopy(structured_goal)
    goal.pop("design_programs", None)
    return goal


def _run_chemistry_agent_for_goal(chemistry_agent_obj: Any, goal: Dict[str, Any]) -> Dict[str, Any]:
    from aso_chemistry import require_native_linkage_identity
    require_native_linkage_identity(goal)
    deferred = _unselected_chemistry_payload(goal)
    if deferred:
        return deferred
    if chemistry_agent_obj is None or not isinstance(goal, dict):
        return {}
    from .chemistry_contracts import (
        chemistry_contract_errors, chemistry_selection_schema, compile_chemistry_proposal, ChemistryResolutionError,
    )
    from .chemistry_mechanism import (
        chemistry_mechanism_audit_agent, chemistry_mechanism_errors, recommendation_digest,
        chemistry_finding_adjudicator, finding_adjudication_schema, adjudication_contract_errors,
        mechanism_audit_schema,
    )
    requested_length = _requested_oligo_length(goal)
    from .chemical_requirements import (requirement_sources, requirement_schema,
        validate_requirement_response, chemical_requirement_agent, require_native_requirement_capabilities,
        requirement_configuration_errors)
    sources = requirement_sources(goal)
    requirements = []
    if sources:
        recording_schema = requirement_schema(sources)
        recorder = _agent_with_strict_output_schema(chemical_requirement_agent,
            schema_name="aso_chemical_requirements", schema=recording_schema)
        recording_input = {"sources": sources, "output_schema": recording_schema}
        for recording_attempt in range(3):
            recorded = run_async_from_sync(lambda: Runner.run(recorder, input=json.dumps(recording_input, ensure_ascii=False), max_steps=6))
            try:
                requirements = validate_requirement_response(json.loads(recorded.final_output) if isinstance(recorded.final_output, str) else recorded.final_output, sources)
                break
            except Exception as exc:
                if recording_attempt == 2:
                    raise ChemistryResolutionError("chemistry_requirements_unresolved: " + str(exc)) from exc
                recording_input["output_contract_feedback"] = {"previous_response": recorded.final_output, "error": str(exc)}
        try:
            require_native_requirement_capabilities(requirements)
        except ValueError as exc:
            raise ChemistryResolutionError("unsupported_chemistry: " + str(exc)) from exc
    schema = chemistry_selection_schema(requested_length)
    if isinstance(chemistry_agent_obj, Agent):
        chemistry_agent_obj = _agent_with_strict_output_schema(
            chemistry_agent_obj, schema_name="aso_chemical_architecture", schema=schema)
    prompt: Dict[str, Any] = {"structured_goal": goal,
                              "exact_requested_length_nt": requested_length,
                              "recorded_chemical_requirements": requirements,
                              "output_schema": schema}
    history = []
    canonical = None
    audit_feedback = None
    for attempt in range(3):
        errors = []
        if canonical is None:
            try:
                chem_task = run_async_from_sync(lambda: Runner.run(
                    chemistry_agent_obj, input=json.dumps(prompt, ensure_ascii=False), max_steps=6,
                ))
            except Exception as exc:
                raise ChemistryResolutionError("chemistry_selection_call_failed: " + type(exc).__name__) from exc
            raw = chem_task.final_output
            try:
                chem_payload = json.loads(raw) if isinstance(raw, str) else raw
            except (TypeError, ValueError):
                chem_payload = {}
            try:
                chem_payload = compile_chemistry_proposal(chem_payload)
                errors = chemistry_contract_errors(chem_payload, requested_length, native_modality=goal.get("modality"), native_design=True)
                if not errors:
                    errors.extend(requirement_configuration_errors(requirements, chem_payload["recommendation"]))
            except ChemistryResolutionError:
                raise
            except (ValueError, TypeError) as exc:
                errors = [str(exc)]
            if not errors and _normalized_chemistry_label(chem_payload) == "unspecified":
                errors.append("Chemistry nonselection requires an explicit leave_unspecified goal policy.")
        if not errors:
            if canonical is None:
                canonical = _canonicalize_chemistry_payload(chem_payload, source_hint="chemistry_agent")
            adjudication = None
            try:
                audit_schema = mechanism_audit_schema(canonical)
                audit_agent = _agent_with_strict_output_schema(
                    chemistry_mechanism_audit_agent,
                    schema_name="aso_chemistry_mechanism_findings",
                    schema=audit_schema,
                )
                audit_input = {"structured_goal": goal, "chemistry": canonical,
                               "output_schema": audit_schema}
                if audit_feedback is not None:
                    audit_input["output_contract_feedback"] = audit_feedback
                audit = run_async_from_sync(lambda: Runner.run(
                    audit_agent,
                    input=json.dumps(audit_input, ensure_ascii=False),
                    max_steps=6,
                ))
                errors = chemistry_mechanism_errors(audit.final_output, canonical)
                try:
                    body = json.loads(audit.final_output) if isinstance(audit.final_output, str) else audit.final_output
                except (TypeError, ValueError):
                    body = None
                if errors and not all(error.startswith("Mechanism consistency:") for error in errors):
                    # A malformed checker response says nothing about the proposal.
                    # Repair the checker within the SAME three-attempt budget,
                    # preserving the selected chemistry and its exact rationale.
                    history.append({"attempt": attempt + 1, "stage": "mechanism_check_contract",
                                    "validation_errors": list(errors)})
                    audit_feedback = {"attempt": attempt + 1, "previous_response": audit.final_output,
                                      "validation_errors": list(errors)}
                    continue
                issues = body.get("issues") if isinstance(body, dict) else None
                # Only structurally valid, source-quoted findings are eligible
                # for adjudication; malformed checks cannot certify a proposal.
                if (errors and isinstance(issues, list) and issues
                        and all(error.startswith("Mechanism consistency:") for error in errors)):
                    adjudication_schema = finding_adjudication_schema(issues)
                    judge = _agent_with_strict_output_schema(chemistry_finding_adjudicator,
                        schema_name="aso_chemistry_finding_adjudication", schema=adjudication_schema)
                    adjudication = run_async_from_sync(lambda: _run_schema_validated_agent_once(
                        agent=judge, prompt=json.dumps({"structured_goal": goal, "chemistry": canonical,
                            "issues": issues, "output_schema": adjudication_schema}, ensure_ascii=False),
                        schema=adjudication_schema, error_prefix="chemistry_finding_adjudication",
                        contract_validator=lambda result: _json_schema_validation_errors(result, adjudication_schema)
                            or adjudication_contract_errors(result, issues)))
                    if adjudication.get("error"):
                        raise ValueError(str(adjudication))
                    errors = ["Mechanism consistency: " + issues[item["finding_index"]]["reason"]
                              for item in adjudication["decisions"] if item["decision"] == "uphold"]
            except Exception as exc:
                # An unavailable checker is not evidence that the completed
                # chemistry proposal should be regenerated for a better answer.
                raise ChemistryResolutionError("chemistry_mechanism_check_unavailable: " + type(exc).__name__) from exc
            if not errors:
                if requirements:
                    canonical["chemical_requirements"] = deepcopy(requirements)
                canonical["mechanism_review"] = {
                    "recommendation_sha256": recommendation_digest(canonical),
                    "check": "same_model_mechanism_consistency",
                    "independent_validation": False,
                }
                if adjudication is not None:
                    canonical["mechanism_review"]["finding_adjudication"] = adjudication
                return canonical
        history.append({"attempt": attempt + 1, "validation_errors": list(errors)})
        prompt["output_contract_feedback"] = {
            "attempt": attempt + 1, "previous_response": raw,
            "validation_errors": errors,
            "instruction": "Repair these exact chemistry/length/scope/mechanism conflicts in place. "
                           "Retain compatible decisions and return the complete recommendation JSON.",
        }
        canonical = None
        audit_feedback = None
    raise ChemistryResolutionError("chemistry_contract_unresolved: " + json.dumps(history, ensure_ascii=False))


def _assign_job_chemistry(job: Optional[Dict[str, Any]], chemistry_payload: Any) -> None:
    if not isinstance(job, dict):
        return
    canonical = _canonicalize_chemistry_payload(chemistry_payload)
    if not canonical:
        for key in ("chemistry", "chemistry_label", "chemistry_platform", "chemistry_length", "chemistry_group_id"):
            job.pop(key, None)
        return
    job["chemistry"] = deepcopy(canonical)
    job["chemistry_label"] = _normalized_chemistry_label(canonical)
    job["chemistry_platform"] = _chemistry_platform(canonical)
    job["chemistry_length"] = _chemistry_length(canonical)
    job["chemistry_group_id"] = _chemistry_group_id(canonical)


def _build_modality_chemistry_summary(
    modality: str,
    programs: List[Dict[str, Any]],
    by_program: Dict[str, Dict[str, Any]],
) -> Dict[str, Any]:
    program_summaries: List[Dict[str, Any]] = []
    signatures: Set[Tuple[str, str, Optional[int]]] = set()
    first_payload: Dict[str, Any] = {}
    for program in programs:
        program_id = str(program.get("program_id") or "").strip()
        if not program_id:
            continue
        payload = _canonicalize_chemistry_payload(by_program.get(program_id))
        if not payload:
            continue
        if not first_payload:
            first_payload = payload
        label = _normalized_chemistry_label(payload)
        platform = _chemistry_platform(payload)
        length = _chemistry_length(payload)
        signatures.add((label, platform, length))
        summary = {
            "program_id": program_id,
            "label": program.get("label"),
            "chemistry": label,
            "platform": platform,
            "length": length,
        }
        source = str(payload.get("source") or "").strip()
        if source:
            summary["source"] = source
        program_summaries.append({key: value for key, value in summary.items() if value not in (None, "", [], {})})
    if not program_summaries:
        return {}
    summary: Dict[str, Any] = {
        "modality": modality,
        "program_count": len(program_summaries),
        "mixed": len(signatures) > 1,
        "programs": program_summaries,
    }
    if len(signatures) == 1 and isinstance(first_payload.get("recommendation"), dict):
        summary["recommendation"] = deepcopy(first_payload.get("recommendation"))
    return summary


def _ensure_program_chemistry_profiles(
    *,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    modality: str = "",
) -> Dict[str, Any]:
    runtime = _goal_runtime_module()
    chemistry_agent_obj = getattr(runtime, "chemistry_agent", None)
    existing_profiles = (
        final_payload.get("chemistry_profiles")
        if isinstance(final_payload.get("chemistry_profiles"), dict)
        else structured_goal.get("chemistry_profiles")
    )
    profiles = deepcopy(existing_profiles) if isinstance(existing_profiles, dict) else {}
    by_program = profiles.get("by_program") if isinstance(profiles.get("by_program"), dict) else {}
    by_modality = profiles.get("by_modality") if isinstance(profiles.get("by_modality"), dict) else {}
    current_chemistry = structured_goal.get("chemistry")
    if "goal_chemistry_input" not in profiles:
        profiles["goal_chemistry_input"] = deepcopy(current_chemistry)
    elif current_chemistry not in (
        profiles.get("goal_chemistry_input"), profiles.get("goal_chemistry_summary")
    ):
        # A changed explicit input invalidates selections made from the old one.
        profiles["goal_chemistry_input"] = deepcopy(current_chemistry)
        by_program, by_modality = {}, {}
    input_goal = deepcopy(structured_goal)
    if profiles["goal_chemistry_input"] is None:
        input_goal.pop("chemistry", None)
    else:
        input_goal["chemistry"] = deepcopy(profiles["goal_chemistry_input"])
    # The top-level selected chemistry is a presentation summary. It must never
    # become a new input to a sibling program, including one of the same modality.
    input_goal.pop("chemistry_profiles", None)

    modalities: List[str] = []
    if modality:
        modalities = [str(modality).strip().lower()]
    else:
        seen_modalities: Set[str] = set()
        for program in _design_programs(structured_goal):
            program_modality = _program_modality(program)
            if program_modality and program_modality not in seen_modalities:
                seen_modalities.add(program_modality)
                modalities.append(program_modality)
        for candidate in ("steric", "gapmer"):
            if candidate not in seen_modalities and _get_design_jobs(final_payload, candidate):
                seen_modalities.add(candidate)
                modalities.append(candidate)

    for modality_key in modalities:
        programs = _design_programs(structured_goal, modality_key)
        for program in programs:
            program_id = str(program.get("program_id") or "").strip()
            if not program_id:
                continue
            goal_for_program = _design_goal_for_program(input_goal, program, runtime)
            payload = _unselected_chemistry_payload(goal_for_program) or _canonicalize_chemistry_payload(by_program.get(program_id))
            if not payload:
                payload = _canonicalize_chemistry_payload(program.get("chemistry"), source_hint="program_configured")
                if not payload:
                    payload = _canonicalize_chemistry_payload(goal_for_program.get("chemistry"), source_hint="goal_configured")
                if not payload:
                    payload = _run_chemistry_agent_for_goal(chemistry_agent_obj, goal_for_program)
                if not payload:
                    payload = _fallback_chemistry_payload(modality_key, goal_for_program)
            if payload:
                if not goal_for_program:
                    goal_for_program = _design_goal_for_program(input_goal, program, runtime)
                requested_length = _requested_oligo_length(goal_for_program) or _requested_oligo_length(structured_goal)
                payload = _apply_requested_length_to_chemistry_payload(payload, requested_length)
                from aso_chemistry import require_chemistry_length, require_modality_chemistry
                require_chemistry_length(_normalized_chemistry_label(payload), _chemistry_length(payload))
                require_modality_chemistry(modality_key, _normalized_chemistry_label(payload))
                by_program[program_id] = deepcopy(payload)

        modality_summary = _build_modality_chemistry_summary(modality_key, programs, by_program)
        if not modality_summary:
            default_payload = _unselected_chemistry_payload(input_goal) or _canonicalize_chemistry_payload(input_goal.get("chemistry"), source_hint="goal_configured")
            if not default_payload:
                default_payload = _run_chemistry_agent_for_goal(chemistry_agent_obj, input_goal)
            if not default_payload:
                default_payload = _fallback_chemistry_payload(modality_key, input_goal)
            modality_summary = {
                "modality": modality_key,
                "program_count": 0,
                "mixed": False,
            }
            if isinstance(default_payload.get("recommendation"), dict):
                modality_summary["recommendation"] = deepcopy(default_payload.get("recommendation"))
        by_modality[modality_key] = modality_summary

        jobs = _get_design_jobs(final_payload, modality_key)
        fallback_payload = _canonicalize_chemistry_payload(input_goal.get("chemistry"), source_hint="goal_configured")
        for job in jobs:
            program = _design_program_for_job(structured_goal, modality_key, job)
            payload = {}
            if isinstance(program, dict):
                program_id = str(program.get("program_id") or "").strip()
                if program_id:
                    payload = _canonicalize_chemistry_payload(by_program.get(program_id))
            if not payload:
                payload = _canonicalize_chemistry_payload(job.get("chemistry"), source_hint="job_configured")
            if not payload:
                recommendation = modality_summary.get("recommendation") if isinstance(modality_summary, dict) else None
                if isinstance(recommendation, dict):
                    payload = {"recommendation": deepcopy(recommendation), "source": "modality_default"}
            if not payload:
                payload = fallback_payload or _fallback_chemistry_payload(modality_key, input_goal)
            _assign_job_chemistry(job, payload)

    profiles["by_program"] = by_program
    profiles["by_modality"] = by_modality

    selected_payload = _unselected_chemistry_payload(structured_goal) or _canonicalize_chemistry_payload(structured_goal.get("chemistry"), source_hint="goal_configured")
    if not selected_payload:
        for program in _design_programs(structured_goal):
            program_id = str(program.get("program_id") or "").strip()
            if not program_id:
                continue
            selected_payload = _canonicalize_chemistry_payload(by_program.get(program_id))
            if selected_payload:
                break
    if not selected_payload and len(by_modality) == 1:
        only_summary = next(iter(by_modality.values()))
        recommendation = only_summary.get("recommendation") if isinstance(only_summary, dict) else None
        if isinstance(recommendation, dict):
            selected_payload = {"recommendation": deepcopy(recommendation), "source": "modality_default"}
    resolved_lengths = {_chemistry_length(value) for value in by_program.values() if _chemistry_length(value)}
    if selected_payload and len(resolved_lengths) == 1:
        selected_payload = _apply_requested_length_to_chemistry_payload(selected_payload, next(iter(resolved_lengths)))
    if selected_payload:
        structured_goal["chemistry"] = deepcopy(selected_payload)
        final_payload["chemistry"] = deepcopy(selected_payload)
    profiles["goal_chemistry_summary"] = deepcopy(structured_goal.get("chemistry"))
    structured_goal["chemistry_profiles"] = deepcopy(profiles)
    final_payload["chemistry_profiles"] = deepcopy(profiles)
    return profiles


def _offtarget_timeout_seconds(structured_goal: Optional[Dict[str, Any]] = None) -> Optional[int]:
    if os.environ.get("ASO_OFFTARGET_TIMEOUT_SEC", "").strip().casefold() == "none":
        return None
    timeout_default = _coerce_positive_int(os.environ.get("ASO_OFFTARGET_TIMEOUT_SEC")) or 240
    if not isinstance(structured_goal, dict):
        return timeout_default
    settings_raw = structured_goal.get("off_target_expression") or structured_goal.get("cellxgene") or {}
    settings = settings_raw if isinstance(settings_raw, dict) else {}
    timeout_override = _coerce_positive_int(
        settings.get("timeout_sec") or settings.get("tool_timeout_sec") or settings.get("cellxgene_timeout_sec")
    )
    return timeout_override or timeout_default


def _target_context_to_text(value: Any) -> str:
    if value in (None, "", [], {}):
        return ""
    if isinstance(value, dict):
        chunks: List[str] = []
        for field in (
            "description",
            "target_context",
            "context",
            "tissue",
            "cell_type",
            "cell_line",
            "disease",
            "model",
            "experimental_system",
            "assay",
        ):
            nested = value.get(field)
            text = _target_context_to_text(nested) if isinstance(nested, (dict, list)) else str(nested or "").strip()
            if text and text not in chunks:
                chunks.append(text)
        if chunks:
            return "; ".join(chunks)
        try:
            return json.dumps(value, ensure_ascii=False, sort_keys=True)
        except Exception:
            return str(value).strip()
    if isinstance(value, list):
        chunks = [_target_context_to_text(item) for item in value]
        return "; ".join(chunk for chunk in chunks if chunk)
    return str(value or "").strip()


def _target_context_text_validation_issue(target_context: Any) -> str:
    # This boundary validates structure, not natural-language meaning.  Semantic
    # adequacy is owned by the evidence-backed completeness reviewer and goal
    # auditor.  A keyword list here rejects valid terminology, spelling variants,
    # and future biological contexts while creating an impossible repair loop:
    # the auditor can restore the exact user evidence yet the validator still
    # calls that same value missing.
    return "" if _target_context_to_text(target_context).strip() else "target_context_missing"


def _offtarget_expression_target_context(structured_goal: Optional[Dict[str, Any]]) -> str:
    if not isinstance(structured_goal, dict):
        return ""
    settings_raw = structured_goal.get("off_target_expression") or structured_goal.get("cellxgene") or {}
    settings = settings_raw if isinstance(settings_raw, dict) else {}
    settings_context = _target_context_to_text(settings.get("target_context"))
    goal_context = _target_context_to_text(structured_goal.get("target_context"))
    if settings_context and not _target_context_text_validation_issue(settings_context):
        return settings_context
    if goal_context:
        return goal_context
    return settings_context


def _target_context_validation_issue(structured_goal: Optional[Dict[str, Any]]) -> str:
    return _target_context_text_validation_issue(_offtarget_expression_target_context(structured_goal))


def _target_context_clarification_question(structured_goal: Optional[Dict[str, Any]]) -> str:
    gene = ""
    species = ""
    if isinstance(structured_goal, dict):
        gene = str(structured_goal.get("gene_symbol") or structured_goal.get("gene_id") or "").strip()
        species = str(structured_goal.get("species") or "").strip()
    prefix = "Please provide the biological target context for this ASO design"
    if gene or species:
        label = " ".join(part for part in (species, gene) if part).strip()
        prefix += f" ({label})"
    return (
        prefix
        + ": tissue and/or cell type, plus disease/model/experimental system if relevant. "
        "If you genuinely want a broad baseline context, state that explicitly."
    )


def _offtarget_expression_worker(initial_filter_json_path: str, structured_goal_json: str, output_queue: Any) -> None:
    try:
        result = annotate_off_target_expression(
            initial_filter_json_path=initial_filter_json_path,
            structured_goal_json=structured_goal_json,
        )
        output_queue.put({"result": result})
    except Exception as exc:
        output_queue.put({"error": f"off_target_expression_failed: {exc}"})


def _run_offtarget_expression_with_timeout(
    *,
    initial_filter_json_path: str,
    structured_goal: Dict[str, Any],
) -> Dict[str, Any]:
    timeout_sec = _offtarget_timeout_seconds(structured_goal)
    structured_goal_json = json.dumps(structured_goal or {}, ensure_ascii=False)
    start_method = "fork" if "fork" in mp.get_all_start_methods() else "spawn"
    ctx = mp.get_context(start_method)
    output_queue = ctx.Queue(maxsize=1)
    worker = ctx.Process(
        target=_offtarget_expression_worker,
        args=(initial_filter_json_path, structured_goal_json, output_queue),
        daemon=True,
    )
    worker.start()
    # Drain before joining: Queue's feeder can otherwise block process exit on
    # a result larger than the pipe buffer. None explicitly disables deadlines.
    from queue import Empty
    deadline = time.monotonic() + timeout_sec if timeout_sec is not None else None
    payload: Any = None
    try:
        while True:
            remaining = None if deadline is None else deadline - time.monotonic()
            if remaining is not None and remaining <= 0:
                worker.terminate()
                worker.join(5)
                if worker.is_alive():
                    worker.kill()
                    worker.join(1)
                return {"error": f"off_target_expression_timeout: exceeded {timeout_sec}s",
                        "timeout_sec": timeout_sec}
            try:
                payload = output_queue.get(timeout=min(0.1, remaining) if remaining is not None else 0.1)
                break
            except Empty:
                if not worker.is_alive():
                    break
        worker.join()
    finally:
        try:
            output_queue.close()
        except Exception:
            pass

    if not isinstance(payload, dict):
        if worker.exitcode not in (0, None):
            return {"error": f"off_target_expression_worker_exited_nonzero: {worker.exitcode}"}
        return {"error": "off_target_expression_worker_no_result"}
    if payload.get("error"):
        return {"error": str(payload.get("error"))}
    result = payload.get("result")
    if not isinstance(result, dict):
        return {"error": "off_target_expression_invalid"}
    return result


def _timestamp() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _read_json(path: Path) -> Dict[str, Any]:
    with path.open("r", encoding="utf-8") as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict):
        raise ValueError(f"State file is not a JSON object: {path}")
    return payload


def _atomic_write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_name(f".{path.name}.tmp")
    try:
        with tmp_path.open("w", encoding="utf-8") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    finally:
        try:
            if tmp_path.exists():
                tmp_path.unlink()
        except Exception:
            pass


def _prune_snapshot_dir(snapshot_dir: Path, keep_last: int = 6) -> int:
    removed = 0
    try:
        snapshots = sorted(snapshot_dir.glob("*.json"))
    except Exception:
        return removed
    excess = max(0, len(snapshots) - max(0, int(keep_last)))
    for snapshot_path in snapshots[:excess]:
        try:
            snapshot_path.unlink()
            removed += 1
        except Exception:
            continue
    return removed


def _write_json(path: Path, payload: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload["updated_at"] = _timestamp()
    _atomic_write_text(
        path,
        json.dumps(payload, ensure_ascii=False, indent=2),
    )


def _run_path(run_dir: Any, *parts: str) -> Path:
    return resolve_run_path(run_dir, *parts)


def _write_run_path(run_dir: Any, *parts: str) -> Path:
    return canonical_run_path(run_dir, *parts)


def _glob_run_paths(run_dir: Any, pattern: str) -> List[Path]:
    root = Path(run_dir).expanduser()
    parts = Path(pattern).parts
    patterns = [pattern]
    if parts:
        mapped = canonical_relparts(*parts)
        if mapped:
            mapped_pattern = str(Path(*mapped))
            if mapped_pattern not in patterns:
                patterns.append(mapped_pattern)
    matches: List[Path] = []
    seen: Set[str] = set()
    for item in patterns:
        for path in root.glob(item):
            key = str(path)
            if key in seen:
                continue
            seen.add(key)
            matches.append(path)
    return matches


def _expand_known_artifact_paths(root: Path, selected: List[Path]) -> List[str]:
    expanded: List[str] = []
    seen: Set[str] = set()
    for path in selected:
        try:
            parts = path.relative_to(root).parts
        except Exception:
            parts = (path.name,)
        if not parts:
            continue
        for candidate in iter_run_path_candidates(root, *parts):
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            expanded.append(key)
    return expanded


def _event(state: Dict[str, Any], phase: str, message: str, level: str = "info") -> None:
    events = state.setdefault("events", [])
    if not isinstance(events, list):
        events = []
        state["events"] = events
    events.append(
        {
            "ts": _timestamp(),
            "phase": phase,
            "level": level,
            "message": message,
        }
    )
    # Keep recent history bounded.
    if len(events) > 200:
        del events[:-200]


_RENAMED_GOAL_DIR_RE = re.compile(r"^(goal_\d+)_GOAL$")


def _resolve_renamed_goal_state_path(path: Path) -> Optional[Path]:
    """Follow goal_*_GOAL -> goal_*_<GENE> renames for a nested agentic state path."""
    match_index: Optional[int] = None
    prefix = ""
    for idx, part in enumerate(path.parts):
        match = _RENAMED_GOAL_DIR_RE.match(part)
        if not match:
            continue
        match_index = idx
        prefix = match.group(1)
        break
    if match_index is None or not prefix:
        return None
    parent = Path(*path.parts[:match_index]) if match_index > 0 else Path(".")
    if not parent.is_dir():
        return None
    suffix_parts = path.parts[match_index + 1 :]
    old_name = path.parts[match_index]
    try:
        siblings = [
            child
            for child in parent.iterdir()
            if child.is_dir() and child.name.startswith(f"{prefix}_") and child.name != old_name
        ]
    except OSError:
        return None
    found: List[Path] = []
    for sibling in siblings:
        candidate = sibling.joinpath(*suffix_parts) if suffix_parts else sibling
        if candidate.exists():
            found.append(candidate)
            continue
        if suffix_parts and str(suffix_parts[0]).startswith("agentic_"):
            relocated = sibling.joinpath(ARTIFACTS_DIRNAME, CONTROLLER_DIRNAME, *suffix_parts)
            if relocated.exists():
                found.append(relocated)
    if not found:
        return None
    found.sort(key=lambda item: item.stat().st_mtime if item.exists() else 0, reverse=True)
    return found[0]


def _state_path_to_obj(state_path: str) -> Path:
    path = Path(state_path).expanduser()
    if not path.is_absolute():
        path = (_repo_root() / path).resolve()
    if path.exists():
        return path
    relocated = _resolve_renamed_goal_state_path(path)
    if relocated is not None:
        return relocated
    return path


def _load_state(state_path: str) -> Dict[str, Any]:
    path = _state_path_to_obj(state_path)
    if not path.exists():
        raise FileNotFoundError(f"run state not found: {path}")
    try:
        state = _read_json(path)
        if isinstance(state, dict):
            _ensure_v2_request_metadata(state)
        return state
    except json.JSONDecodeError:
        snapshot_dir = path.parent / "state_snapshots"
        if snapshot_dir.exists():
            for snapshot_path in sorted(snapshot_dir.glob("*.json"), reverse=True):
                try:
                    recovered = _read_json(snapshot_path)
                except Exception:
                    continue
                recovered["_state_recovered_from_snapshot"] = str(snapshot_path)
                if isinstance(recovered, dict):
                    _ensure_v2_request_metadata(recovered)
                return recovered
        raise


def _save_state(state_path: str, state: Dict[str, Any], snapshot_reason: str = "update") -> None:
    path = _state_path_to_obj(state_path)
    reason_slug = re.sub(r"[^a-z0-9]+", "_", (snapshot_reason or "update").strip().lower()).strip("_") or "update"
    snapshot_seq = int(state.get("snapshot_seq") or 0) + 1
    snapshot_dir = path.parent / "state_snapshots"
    snapshot_dir.mkdir(parents=True, exist_ok=True)
    snapshot_path = snapshot_dir / f"{snapshot_seq:04d}_{reason_slug}.json"
    state["snapshot_seq"] = snapshot_seq
    state["last_snapshot_path"] = str(snapshot_path)
    state["last_snapshot_reason"] = snapshot_reason
    _ensure_v2_request_metadata(state)
    try:
        state["planning"] = _derive_next_actions(state)
    except Exception:
        pass
    run_dir = state.get("run_dir")
    task_index = state.get("task_index")
    if isinstance(run_dir, str) and run_dir.strip() and isinstance(task_index, dict) and task_index:
        try:
            task_index_path = _write_run_path(run_dir.strip(), "task_index.json")
            ensure_run_parent(task_index_path)
            task_index_path.write_text(
                json.dumps(task_index, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
        except Exception:
            pass
    payload_json = json.dumps(state, ensure_ascii=False, indent=2)
    state["updated_at"] = _timestamp()
    payload_json = json.dumps(state, ensure_ascii=False, indent=2)
    try:
        _atomic_write_text(path, payload_json)
    except OSError as exc:
        if exc.errno == errno.ENOSPC and _prune_snapshot_dir(snapshot_dir, keep_last=2):
            _atomic_write_text(path, payload_json)
        else:
            raise
    try:
        _atomic_write_text(snapshot_path, payload_json)
    except OSError as exc:
        if exc.errno == errno.ENOSPC:
            _prune_snapshot_dir(snapshot_dir, keep_last=4)
        else:
            raise
    else:
        _prune_snapshot_dir(snapshot_dir, keep_last=20)


def _agentic_progress_signature(state_path: Optional[str]) -> Optional[Tuple[Any, ...]]:
    if not isinstance(state_path, str) or not state_path.strip():
        return None
    try:
        payload = _read_json(_state_path_to_obj(state_path))
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    routing = payload.get("routing") if isinstance(payload.get("routing"), dict) else {}
    jobs = routing.get("jobs") if isinstance(routing.get("jobs"), list) else []
    routing_signature: List[Tuple[str, int, int]] = []
    for job in jobs[:32]:
        if not isinstance(job, dict):
            continue
        routing_signature.append(
            (
                str(job.get("job_id") or "").strip(),
                int(job.get("next_goal_index") or 0),
                int(job.get("total_steps") or 0),
            )
        )
    last_tool_raw = payload.get("last_tool")
    last_tool_name = ""
    last_tool_status = ""
    if isinstance(last_tool_raw, dict):
        last_tool_name = str(last_tool_raw.get("tool") or "").strip()
        last_tool_status = str(last_tool_raw.get("status") or "").strip()
    else:
        last_tool_name = str(last_tool_raw or "").strip()
        history = payload.get("tool_history") if isinstance(payload.get("tool_history"), list) else []
        for entry in reversed(history):
            if not isinstance(entry, dict):
                continue
            if str(entry.get("tool") or "").strip() == last_tool_name:
                last_tool_status = str(entry.get("status") or "").strip()
                break
    active_runner = payload.get("active_runner") if isinstance(payload.get("active_runner"), dict) else {}
    return (
        int(payload.get("snapshot_seq") or 0),
        str(payload.get("updated_at") or ""),
        str(payload.get("status") or ""),
        str(payload.get("phase") or ""),
        last_tool_name,
        last_tool_status,
        str(active_runner.get("tool") or ""),
        int(active_runner.get("pid") or 0),
        str(active_runner.get("heartbeat_at") or ""),
        int(routing.get("job_index") or 0),
        int(routing.get("total_jobs") or 0),
        tuple(routing_signature),
    )


def _run_agentic_pipeline_to_terminal(
    *,
    run_agentic_pipeline: Any,
    user_request: str,
    existing_state_path: Optional[str],
    clarification_answers: Optional[List[Dict[str, Any]]],
    clarification_answer_summary: str,
    flags: Dict[str, Any],
    max_steps: int,
) -> Dict[str, Any]:
    current_state_path = str(existing_state_path or "").strip() or None
    pending_answers = deepcopy(clarification_answers) if isinstance(clarification_answers, list) else None
    pending_summary = str(clarification_answer_summary or "").strip()
    reference_data_root = ""
    if not reference_data_root and current_state_path:
        try:
            state_payload = _read_json(_state_path_to_obj(current_state_path))
            if isinstance(state_payload, dict):
                reference_data_root = str(state_payload.get("reference_data_root") or "").strip()
        except Exception:
            reference_data_root = ""
    if reference_data_root:
        _apply_reference_data_root_choice(reference_data_root)
    controller_pass_limit = max(64, int(max_steps) * 4)
    controller_stall_limit = 3
    controller_passes = 0
    controller_stalled_passes = 0
    last_progress_signature = _agentic_progress_signature(current_state_path)
    agentic_result: Dict[str, Any] = {}

    while controller_passes < controller_pass_limit:
        controller_passes += 1
        agentic_result = run_agentic_pipeline(
            user_request=user_request,
            skip_router=bool(flags.get("skip_router", False)),
            skip_ensembl_check=bool(flags.get("skip_ensembl_check", False)),
            router_max_steps=int(flags.get("router_max_steps") or 25),
            router_log_tool_calls=bool(flags.get("router_log_tool_calls", False)),
            router_debug_dir=str(flags.get("router_debug_dir") or "").strip(),
            router_print_summary=bool(flags.get("router_print_summary", False)),
            existing_state_path=current_state_path,
            clarification_answers=pending_answers,
            clarification_answer_summary=pending_summary,
            max_steps=max_steps,
        )
        status = str(agentic_result.get("status") or "").strip().lower()
        if status != "in_progress":
            return agentic_result
        state_path_for_resume = str(agentic_result.get("state_path") or "").strip()
        if not state_path_for_resume:
            break
        current_state_path = state_path_for_resume
        progress_signature = _agentic_progress_signature(current_state_path)
        if progress_signature is not None and progress_signature == last_progress_signature:
            controller_stalled_passes += 1
        else:
            controller_stalled_passes = 0
            last_progress_signature = progress_signature
        if controller_stalled_passes >= controller_stall_limit:
            break
        pending_answers = None
        pending_summary = ""

    agentic_result = dict(agentic_result)
    agentic_result["status"] = "fatal"
    if controller_stalled_passes >= controller_stall_limit:
        agentic_result["error"] = {
            "kind": "controller_stalled_no_progress",
            "message": f"Controller remained in_progress without state progress for {controller_stall_limit} consecutive passes.",
            "controller_stall_limit": controller_stall_limit,
        }
    else:
        agentic_result["error"] = {
            "kind": "controller_pass_limit_exceeded",
            "message": f"Controller remained in_progress after {controller_pass_limit} passes.",
            "controller_pass_limit": controller_pass_limit,
        }
    return agentic_result


def _next_stage_attempt(state: Dict[str, Any], stage_name: str) -> int:
    attempts = state.get("stage_attempts")
    if not isinstance(attempts, dict):
        attempts = {}
        state["stage_attempts"] = attempts
    current = int(attempts.get(stage_name) or 0)
    nxt = current + 1
    attempts[stage_name] = nxt
    return nxt


def _max_stage_retries(state: Dict[str, Any]) -> int:
    policy = state.get("retry_policy")
    if not isinstance(policy, dict):
        return 1
    try:
        value = int(policy.get("max_stage_retries", 1))
    except Exception:
        value = 1
    return max(0, value)


def _max_external_service_retries(state: Dict[str, Any]) -> int:
    policy = state.get("retry_policy")
    if not isinstance(policy, dict):
        policy = {}
    try:
        value = int(policy.get("max_external_service_retries", 8))
    except Exception:
        value = 8
    return max(_max_stage_retries(state), value)


def _is_retryable_ensembl_service_error(exc: BaseException) -> bool:
    if isinstance(exc, EnsemblServiceError):
        return bool(getattr(exc, "retryable", True))
    return False


def _ensembl_resolution_failure_details(exc: BaseException, run_dir: str) -> Dict[str, Any]:
    details: Dict[str, Any] = {"run_dir": run_dir}
    if isinstance(exc, FrozenDependencyUnavailableError):
        details["failure_class"] = "infrastructure"
        details["failure_reason"] = "frozen_dependency_unavailable"
        details["retryable_external_service"] = False
        details["external_service"] = "local_reference_bundle"
        return details
    if _is_retryable_ensembl_service_error(exc):
        details["failure_class"] = "infrastructure"
        details["failure_reason"] = "external_service_unavailable"
        details["retryable_external_service"] = True
        details["external_service"] = "ensembl"
    return details


def _error_has_retryable_external_service(error: Any) -> bool:
    if not isinstance(error, dict):
        return False
    if "retryable_external_service" in error:
        return _coerce_bool(error.get("retryable_external_service")) is True
    if error.get("isoform_resolution_error") not in (None, ""):
        return True
    if str(error.get("kind") or "").strip() == "gene_preflight_unavailable":
        return True
    child_result = error.get("child_result")
    if isinstance(child_result, dict):
        if _error_has_retryable_external_service(child_result.get("last_error")):
            return True
        if _error_has_retryable_external_service(child_result.get("error")):
            return True
    return False


def _external_service_can_retry(
    state: Dict[str, Any],
    error: Any,
    stage_name: str,
) -> bool:
    return bool(
        _error_has_retryable_external_service(error)
        and _stage_attempt_count(state, stage_name) <= _max_external_service_retries(state)
    )


def _record_replay_command(
    state: Dict[str, Any],
    *,
    stage: str,
    attempt: int,
    command: List[str],
    result: Dict[str, Any],
    log_path: str,
) -> None:
    replay = state.get("replay")
    if not isinstance(replay, dict):
        replay = {}
        state["replay"] = replay
    commands = replay.get("commands")
    if not isinstance(commands, list):
        commands = []
        replay["commands"] = commands
    commands.append(
        {
            "ts": _timestamp(),
            "stage": stage,
            "attempt": attempt,
            "command": command,
            "returncode": result.get("returncode"),
            "elapsed_sec": result.get("elapsed_sec"),
            "log_path": log_path,
        }
    )
    if len(commands) > 300:
        del commands[:-300]


def _write_stage_log(state_dir: Path, filename: str, command: List[str], result: Dict[str, Any]) -> str:
    path = state_dir / filename
    lines = [
        f"timestamp: {_timestamp()}",
        f"command: {' '.join(command)}",
        f"returncode: {result.get('returncode')}",
        f"elapsed_sec: {result.get('elapsed_sec')}",
        "",
        "STDOUT:",
        result.get("stdout", ""),
        "",
        "STDERR:",
        result.get("stderr", ""),
    ]
    path.write_text("\n".join(lines), encoding="utf-8")
    return str(path)


def _extract_run_dir(text: str) -> Optional[str]:
    matches = re.findall(r"GOAL_INTAKE_RUN_DIR:\s*(.+)", text)
    if matches:
        return matches[-1].strip()
    return None


def _discover_core_artifacts(run_dir: str) -> Dict[str, Any]:
    run_path = Path(run_dir).expanduser()
    artifacts = {
        "goal_intake_json": str(_run_path(run_path, "goal_intake.json")),
        "structured_goal_json": str(_run_path(run_path, "structured_goal.json")),
        "request_envelope_json": str(_run_path(run_path, "request_envelope.json")),
        "report_md": str(_run_path(run_path, "report.md")),
        "report_html": str(_run_path(run_path, "report.html")),
        "composite_report_md": str(_run_path(run_path, "composite_report.md")),
        "composite_report_json": str(_run_path(run_path, "composite_report.json")),
        "task_index_json": str(_run_path(run_path, "task_index.json")),
        "strategy_router_summary_json": str(_run_path(run_path, "strategy_router_summary.json")),
        "steric_regions_bed": str(_run_path(run_path, "steric_regions.bed")),
        "tiling_config_json": str(_run_path(run_path, "tiling_config.json")),
        "tiling_dir": str(_run_path(run_path, "tiling")),
        "tiling_results_json": str(_run_path(run_path, "tiling", "tiles.json")),
        "initial_filtering_json": str(_run_path(run_path, "tiling", "initial_filtering_tiles.json")),
        "steric_uniqueness_json": str(_run_path(run_path, "tiling", "steric_scored_uniqueness.json")),
        "steric_scored_tiles_json": str(_run_path(run_path, "tiling", "scored_tiles.json")),
        "steric_uniqueness_csv": str(_run_path(run_path, "tiling", "steric_uniqueness_ranked.csv")),
        "strategy_routes_dir": str(_run_path(run_path, "strategy_routes")),
        "strategy_router_debug_dir": str(_run_path(run_path, "strategy_router_debug")),
        "splicing_eval_csv": str(_run_path(run_path, "splice_site_comparisons.csv")),
        "generated_aso_set_json": str(_run_path(run_path, "generated_aso_set.json")),
        "generated_filter_trace_json": str(_run_path(run_path, "generated_filter_trace.json")),
    }
    exists = {key: Path(path).exists() for key, path in artifacts.items()}
    context = _goal_payload_context(str(run_path))
    final_payload = context.get("final_payload") if isinstance(context, dict) else {}
    structured_goal = context.get("structured_goal") if isinstance(context, dict) else {}
    if not isinstance(final_payload, dict):
        final_payload = {}
    if not isinstance(structured_goal, dict):
        structured_goal = {}
    tiling_results = final_payload.get("tiling_results") if isinstance(final_payload.get("tiling_results"), dict) else {}
    gapmer_results = (
        final_payload.get("gapmer_tiling_results")
        if isinstance(final_payload.get("gapmer_tiling_results"), dict)
        else {}
    )
    splice_transformer = (
        tiling_results.get("splice_transformer")
        if isinstance(tiling_results, dict) and isinstance(tiling_results.get("splice_transformer"), dict)
        else {}
    )
    steric_uniqueness_jobs = _steric_jobs_requiring_uniqueness(final_payload, structured_goal)
    steric_router_jobs = _steric_jobs_requiring_splice_router(final_payload, structured_goal)
    per_job_routing_present = bool(
        steric_router_jobs
        and _design_results_cover_for_jobs(
            final_payload,
            "steric",
            "strategy_router_summary_json",
            steric_router_jobs,
        )
    )
    stage_markers = {
        "has_steric_rows": bool(isinstance(final_payload.get("steric_bed"), dict) and final_payload.get("steric_bed", {}).get("rows")),
        "has_tiling_config": bool(
            isinstance(final_payload.get("tiling_config"), dict)
            or bool(exists.get("tiling_config_json"))
        ),
        "has_gapmer_regions": bool(
            isinstance(final_payload.get("gapmer_region_bed"), dict)
            and isinstance(final_payload.get("gapmer_region_bed", {}).get("rows"), list)
            and bool(final_payload.get("gapmer_region_bed", {}).get("rows"))
        ),
        "has_tiling_results": bool(isinstance(tiling_results, dict) and tiling_results and not tiling_results.get("error")),
        "has_steric_collect": bool(isinstance(tiling_results, dict) and tiling_results.get("json_path")),
        "has_steric_initial_filtering": bool(
            isinstance(tiling_results, dict)
            and isinstance(tiling_results.get("initial_filtering"), dict)
            and isinstance(tiling_results.get("initial_filtering", {}).get("passed"), dict)
            and tiling_results.get("initial_filtering", {}).get("passed", {}).get("path")
        ),
        "has_steric_expression": bool(
            isinstance(tiling_results, dict)
            and isinstance(tiling_results.get("initial_filtering"), dict)
            and isinstance(tiling_results.get("initial_filtering", {}).get("off_target_expression"), dict)
        ),
        "has_steric_uniqueness": bool(
            (
                isinstance(tiling_results, dict)
                and (
                    tiling_results.get("uniqueness_scored_path")
                    or tiling_results.get("uniqueness_csv")
                )
            )
            or (
                bool(steric_uniqueness_jobs)
                and _design_results_cover_for_jobs(
                    final_payload,
                    "steric",
                    "uniqueness_scored_path",
                    steric_uniqueness_jobs,
                )
            )
        ),
        "has_steric_scoring": bool(
            tiling_results.get("initial_filtering")
            or tiling_results.get("uniqueness_scored_path")
            or tiling_results.get("scored_tiles_path")
        ),
        "has_splice_eval": bool(
            isinstance(splice_transformer, dict)
            and splice_transformer
            and not splice_transformer.get("skipped")
            and (splice_transformer.get("path") or splice_transformer.get("evaluated") or tiling_results.get("scored_tiles_path"))
        ),
        "has_gapmer_tiling": bool(isinstance(gapmer_results, dict) and gapmer_results and not gapmer_results.get("error")),
        "has_gapmer_scoring": bool(
            isinstance(gapmer_results, dict)
            and (
                gapmer_results.get("uniqueness_scored_path")
                or gapmer_results.get("scored_tiles_path")
                or gapmer_results.get("uniqueness_csv")
            )
        ),
        "has_report_payload": bool(isinstance(final_payload.get("report_payload"), dict)),
        "has_report_markdown": bool(exists.get("report_md")),
        "has_report_html": bool(exists.get("report_html")),
        "has_routing": bool(
            _run_path(run_path, "strategy_router_summary.json").exists()
            or per_job_routing_present
        ),
    }
    return {"paths": artifacts, "exists": exists, "markers": stage_markers}


def _mark_last_tool(state: Dict[str, Any], tool_name: str, result_status: Optional[str] = None) -> None:
    state["last_tool"] = tool_name
    history = state.get("tool_history")
    if not isinstance(history, list):
        history = []
        state["tool_history"] = history
    entry: Dict[str, Any] = {"ts": _timestamp(), "tool": tool_name}
    if result_status:
        entry["status"] = result_status
    history.append(entry)
    if len(history) > 400:
        del history[:-400]


def _design_jobs_key(modality: str) -> str:
    return f"{str(modality or '').strip().lower()}_design_jobs"


def _design_results_key(modality: str) -> str:
    modality_key = str(modality or "").strip().lower()
    if modality_key == "gapmer":
        return "gapmer_tiling_results_by_job"
    return "steric_tiling_results_by_job"


def _program_modality(program: Any) -> str:
    if not isinstance(program, dict):
        return ""
    return str(program.get("modality") or "").strip().lower()


def _design_programs(structured_goal: Optional[Dict[str, Any]], modality: str = "") -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    raw_programs = structured_goal.get("design_programs")
    if not isinstance(raw_programs, list):
        return []
    modality_norm = str(modality or "").strip().lower()
    programs: List[Dict[str, Any]] = []
    for idx, program in enumerate(raw_programs, start=1):
        if not isinstance(program, dict):
            continue
        program_modality = _program_modality(program)
        if modality_norm and program_modality != modality_norm:
            continue
        program_copy = dict(program)
        if not str(program_copy.get("program_id") or "").strip():
            program_copy["program_id"] = f"{program_modality or modality_norm or 'program'}_{idx:02d}"
        if not str(program_copy.get("label") or "").strip():
            fallback_label = program_copy.get("objective") or program_copy.get("program_id")
            if fallback_label:
                program_copy["label"] = str(fallback_label)
        inferred_site_kind = _infer_design_program_site_kind(program_copy)
        if inferred_site_kind and not str(program_copy.get("site_kind") or "").strip():
            program_copy["site_kind"] = inferred_site_kind
        programs.append(program_copy)
    return programs


def _design_program_modalities(structured_goal: Optional[Dict[str, Any]]) -> Set[str]:
    return {
        _program_modality(program)
        for program in _design_programs(structured_goal)
        if _program_modality(program)
    }


def _design_programs_are_gapmer_only(structured_goal: Optional[Dict[str, Any]]) -> bool:
    modalities = _design_program_modalities(structured_goal)
    return bool(modalities) and "gapmer" in modalities and "steric" not in modalities


def _has_splice_objective_signal(payload: Any) -> bool:
    if not isinstance(payload, dict):
        return False
    splice_objective = payload.get("splice_objective")
    if isinstance(splice_objective, dict) and any(value not in (None, "", [], {}) for value in splice_objective.values()):
        return True
    for key in (
        "splice_isoform_objectives",
        "splice_site_plan",
        "site_direction_hints",
        "explicit_splice_targets",
    ):
        value = payload.get(key)
        if isinstance(value, list) and value:
            return True
    return False


def _isoform_objective_label(objective: Optional[Dict[str, Any]]) -> str:
    if not isinstance(objective, dict):
        return ""
    return str(
        objective.get("isoform_label")
        or objective.get("transcript_label")
        or objective.get("transcript_id")
        or ""
    ).strip()


def _looks_like_direct_isoform_identifier(value: Any) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    if text.upper().startswith("SNAPGENE::"):
        return True
    base = text.split(".", 1)[0]
    return bool(re.fullmatch(r"(?:ENS[A-Z]*T\d+|N[MR]_\d+|X[MR]_\d+)", base, flags=re.IGNORECASE))


def _normalize_steric_targeting_policy(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "explicit": "explicit_user_region",
        "explicit_user": "explicit_user_region",
        "explicit_region": "explicit_user_region",
        "specific": "explicit_user_region",
        "specific_region": "explicit_user_region",
        "user_region": "explicit_user_region",
        "user_specified": "explicit_user_region",
        "explicit_user_site_window": "explicit_user_region",
        "user_site_window": "explicit_user_region",
        "site_window": "explicit_user_region",
        "default": "default_exploratory",
        "exploratory": "default_exploratory",
        "default_explore": "default_exploratory",
        "exploratory_default": "default_exploratory",
        "auto_explore": "default_exploratory",
        "derived": "exploratory_derived",
        "derived_exploratory": "exploratory_derived",
        "auto_derived": "exploratory_derived",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"explicit_user_region", "default_exploratory", "exploratory_derived"} else ""


def _normalize_design_program_site_kind(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "3ss": "acceptor",
        "acceptor_site": "acceptor",
        "splice_acceptor": "acceptor",
        "5ss": "donor",
        "donor_site": "donor",
        "splice_donor": "donor",
        "splice_site": "both",
        "junction": "both",
        "both_sites": "both",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"acceptor", "donor", "both"} else ""


def _infer_design_program_site_kind(program: Any) -> str:
    if not isinstance(program, dict):
        return ""
    explicit = _normalize_design_program_site_kind(program.get("site_kind") or program.get("site"))
    if explicit:
        return explicit
    fields = (
        "program_id",
        "label",
        "job_id",
        "job_label",
        "route_id",
        "objective",
        "target_region",
        "site_context",
        "target_site",
        "description",
        "notes",
    )
    text = " ".join(str(program.get(key) or "") for key in fields).lower()
    if not text.strip():
        return ""
    acceptor_signal = bool(
        re.search(r"\bacceptor\b|\b3ss\b|3\s*['’]?\s*splice|splice\s*acceptor", text)
    )
    donor_signal = bool(
        re.search(r"\bdonor\b|\b5ss\b|5\s*['’]?\s*splice|splice\s*donor", text)
    )
    if acceptor_signal and donor_signal:
        return "both"
    if acceptor_signal:
        return "acceptor"
    if donor_signal:
        return "donor"
    return ""


def _normalize_design_program_site_context(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "site": "site_window",
        "window": "site_window",
        "splice_site": "site_window",
        "splice_window": "site_window",
        "junction_window": "site_window",
        "upstream_intronic": "upstream_intron",
        "intronic_upstream": "upstream_intron",
        "upstream_intron_window": "upstream_intron",
        "downstream_intronic": "downstream_intron",
        "intronic_downstream": "downstream_intron",
        "downstream_intron_window": "downstream_intron",
        "exonic": "exon_body",
        "exonic_side": "exon_body",
        "exon": "exon_body",
        "exon_window": "exon_body",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"site_window", "upstream_intron", "downstream_intron", "exon_body"} else ""


def _steric_targeting_policy(
    request_meta: Optional[Dict[str, Any]],
    *,
    fallback_goal: Optional[Dict[str, Any]] = None,
) -> str:
    if isinstance(request_meta, dict):
        for key in ("targeting_policy", "steric_targeting_policy"):
            normalized = _normalize_steric_targeting_policy(request_meta.get(key))
            if normalized:
                return normalized
    if isinstance(fallback_goal, dict):
        for key in ("steric_targeting_policy", "targeting_policy"):
            normalized = _normalize_steric_targeting_policy(fallback_goal.get(key))
            if normalized:
                return normalized
    return ""


def _steric_program_has_explicit_region_fields(program: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(program, dict):
        return False
    if _normalize_target_region(program.get("target_region")):
        return True
    region_constraints = program.get("region_constraints")
    if isinstance(region_constraints, list) and region_constraints:
        return True
    explicit_targets = program.get("explicit_splice_targets")
    return bool(isinstance(explicit_targets, list) and explicit_targets)


def _normalize_isoform_objective_direction(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "up": "increase",
        "increase_abundance": "increase",
        "promote": "increase",
        "higher": "increase",
        "down": "decrease",
        "decrease_abundance": "decrease",
        "reduce": "decrease",
        "lower": "decrease",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"increase", "decrease"} else ""


def _normalize_isoform_objective_role(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "bad": "pathogenic",
        "disease": "pathogenic",
        "harmful": "pathogenic",
        "deleterious": "pathogenic",
        "unwanted": "pathogenic",
        "desired": "beneficial",
        "protective": "beneficial",
        "good": "beneficial",
        "background": "context",
        "neutral": "context",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"beneficial", "pathogenic", "context"} else ""


def _has_explicit_decrease_signal_for_isoform(
    structured_goal: Optional[Dict[str, Any]],
    isoform_label: str,
) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    isoform_label_norm = str(isoform_label or "").strip()
    if not isoform_label_norm:
        return False

    for hint in structured_goal.get("site_direction_hints") or []:
        if not isinstance(hint, dict):
            continue
        hint_label = _isoform_objective_label(hint)
        if hint_label != isoform_label_norm:
            continue
        desired_delta = _normalize_isoform_objective_direction(hint.get("desired_delta") or hint.get("direction"))
        if desired_delta == "decrease":
            return True

    for target in structured_goal.get("explicit_splice_targets") or []:
        if not isinstance(target, dict):
            continue
        target_label = _isoform_objective_label(target)
        if target_label != isoform_label_norm:
            continue
        desired_delta = _normalize_isoform_objective_direction(target.get("desired_delta") or target.get("direction"))
        if desired_delta == "decrease":
            return True

    return False


def _splice_switch_gapmer_target_has_direct_signal(
    structured_goal: Optional[Dict[str, Any]],
    objective: Optional[Dict[str, Any]],
) -> bool:
    isoform_label = _isoform_objective_label(objective)
    if not isoform_label:
        return False
    if _has_explicit_decrease_signal_for_isoform(structured_goal, isoform_label):
        return True
    if _looks_like_direct_isoform_identifier(isoform_label):
        return True
    if isinstance(objective, dict):
        for key in ("transcript_id", "transcript_label"):
            if _looks_like_direct_isoform_identifier(objective.get(key)):
                return True
    return False


def _splice_modulation_isoform_conversion_policy(
    structured_goal: Optional[Dict[str, Any]],
    raw_programs: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    policy = {
        "enabled": False,
        "priority": "",
        "mechanism_specified": False,
        "objective_count": 0,
    }
    if not isinstance(structured_goal, dict):
        return policy
    intent = str(structured_goal.get("intent") or "").strip().lower()
    if intent != "splice_modulation":
        return policy

    objectives = (
        structured_goal.get("splice_isoform_objectives")
        if isinstance(structured_goal.get("splice_isoform_objectives"), list)
        else []
    )
    distinct_labels: Set[str] = set()
    increase_count = 0
    decrease_count = 0
    for objective in objectives:
        if not isinstance(objective, dict):
            continue
        label = str(
            objective.get("isoform_label")
            or objective.get("transcript_label")
            or objective.get("transcript_id")
            or ""
        ).strip()
        if label:
            distinct_labels.add(label)
        direction = _normalize_isoform_objective_direction(
            objective.get("desired_abundance") or objective.get("direction") or objective.get("goal")
        )
        if direction == "increase":
            increase_count += 1
        elif direction == "decrease":
            decrease_count += 1

    if len(distinct_labels) < 2 or increase_count == 0 or decrease_count == 0:
        return policy

    mechanism_specified = False
    if str(structured_goal.get("mechanism") or "").strip():
        mechanism_specified = True
    elif _coerce_bool((structured_goal.get("junction_gapmers") or {}).get("enabled")) is True:
        mechanism_specified = True
    else:
        programs = raw_programs if isinstance(raw_programs, list) else []
        for program in programs:
            if not isinstance(program, dict):
                continue
            modality = _program_modality(program)
            if modality == "gapmer":
                mechanism_specified = True
                break
            if modality == "steric":
                program_policy = _steric_targeting_policy(program, fallback_goal=structured_goal)
                if program_policy and program_policy != "default_exploratory":
                    mechanism_specified = True
                    break
                if _steric_program_has_explicit_region_fields(program):
                    mechanism_specified = True
                    break
        if not mechanism_specified:
            top_level_policy = _steric_targeting_policy(None, fallback_goal=structured_goal)
            explicit_targets = structured_goal.get("explicit_splice_targets")
            if top_level_policy == "explicit_user_region":
                mechanism_specified = True
            elif _normalize_target_region(structured_goal.get("target_region")):
                mechanism_specified = True
            elif isinstance(explicit_targets, list) and explicit_targets:
                mechanism_specified = True

    policy["enabled"] = True
    policy["priority"] = "secondary" if mechanism_specified else "primary"
    policy["mechanism_specified"] = mechanism_specified
    policy["objective_count"] = len(distinct_labels)
    return policy


def _splice_switching_gapmer_targets(
    structured_goal: Optional[Dict[str, Any]],
    *,
    require_direct_signal: bool = False,
) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    objectives = (
        structured_goal.get("splice_isoform_objectives")
        if isinstance(structured_goal.get("splice_isoform_objectives"), list)
        else []
    )
    targets: List[Dict[str, Any]] = []
    seen_labels: Set[str] = set()
    for objective in objectives:
        if not isinstance(objective, dict):
            continue
        if objective.get("objective_scope") in {"default_exon_context", "aggregate_class"}:
            # A structural reference locates an exon; its inclusion direction
            # does not authorize depletion of the whole reference transcript.
            # Aggregate classes need their own explicitly scoped design program.
            continue
        isoform_label = _isoform_objective_label(objective)
        if not isoform_label or isoform_label in seen_labels:
            continue
        direction = _normalize_isoform_objective_direction(
            objective.get("desired_abundance") or objective.get("direction") or objective.get("goal")
        )
        role = _normalize_isoform_objective_role(objective.get("role"))
        if direction != "decrease" and role != "pathogenic":
            continue
        if require_direct_signal and not _splice_switch_gapmer_target_has_direct_signal(structured_goal, objective):
            continue
        seen_labels.add(isoform_label)
        targets.append(
            {
                "isoform_label": isoform_label,
                "direction": direction or "decrease",
                "role": role or "context",
                "rationale": str(objective.get("rationale") or "").strip(),
            }
        )
    return targets


def _isoform_resolution_status_by_label(
    structured_goal: Optional[Dict[str, Any]],
) -> Tuple[Dict[str, str], bool]:
    """Return resolution status for isoform labels known to the current goal."""
    statuses: Dict[str, str] = {}
    if not isinstance(structured_goal, dict):
        return statuses, False

    isoform_transcripts = (
        structured_goal.get("isoform_transcripts")
        if isinstance(structured_goal.get("isoform_transcripts"), dict)
        else {}
    )
    for label, entry in isoform_transcripts.items():
        label_text = str(label or "").strip()
        if label_text:
            statuses[label_text] = "resolved"
        if isinstance(entry, dict):
            transcript_id = str(entry.get("transcript_id") or entry.get("id") or "").strip()
            if transcript_id:
                statuses.setdefault(transcript_id, "resolved")

    pending_items = (
        structured_goal.get("pending_isoform_transcript_confirmations")
        if isinstance(structured_goal.get("pending_isoform_transcript_confirmations"), list)
        else []
    )
    for item in pending_items:
        if not isinstance(item, dict):
            continue
        label = str(item.get("isoform_label") or "").strip()
        if label and label not in statuses:
            statuses[label] = "pending"

    unresolved = structured_goal.get("unresolved_isoforms")
    unresolved_details = (
        structured_goal.get("unresolved_isoform_details")
        if isinstance(structured_goal.get("unresolved_isoform_details"), dict)
        else {}
    )
    unresolved_labels: Set[str] = set()
    if isinstance(unresolved, dict):
        unresolved_labels.update(str(label).strip() for label in unresolved.keys() if str(label).strip())
        unresolved_details = {**unresolved, **unresolved_details}
    elif isinstance(unresolved, list):
        unresolved_labels.update(str(label).strip() for label in unresolved if str(label).strip())
    for label in unresolved_details.keys():
        label_text = str(label or "").strip()
        if label_text:
            unresolved_labels.add(label_text)
    for label in unresolved_labels:
        if statuses.get(label) == "resolved":
            continue
        detail = str(unresolved_details.get(label) or "").strip().lower()
        statuses[label] = "skipped" if "skip" in detail or "omit" in detail else "unresolved"

    confirmations = (
        structured_goal.get("isoform_transcript_confirmations")
        if isinstance(structured_goal.get("isoform_transcript_confirmations"), list)
        else []
    )
    for item in confirmations:
        if not isinstance(item, dict):
            continue
        label = str(item.get("isoform_label") or "").strip()
        if not label or statuses.get(label) == "resolved":
            continue
        decision = str(item.get("decision") or "").strip().lower()
        if decision in {"skip", "omit"}:
            statuses[label] = "skipped"
        elif decision == "upload":
            statuses[label] = "unresolved"
        elif decision in {"accept", "user_selected"} and (
            item.get("transcript_id") or item.get("suggested_transcript_id")
        ):
            statuses.setdefault(label, "pending")

    has_context = bool(
        isoform_transcripts
        or pending_items
        or unresolved
        or unresolved_details
        or confirmations
    )
    return statuses, has_context


def _splice_switch_gapmer_support_policy(
    structured_goal: Optional[Dict[str, Any]],
    raw_programs: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    policy = _splice_modulation_isoform_conversion_policy(structured_goal, raw_programs)
    support = {
        "enabled": False,
        "priority": str(policy.get("priority") or ""),
        "mechanism_specified": bool(policy.get("mechanism_specified")),
        "objective_count": int(policy.get("objective_count") or 0),
        "target_isoforms": [],
        "omitted_target_isoforms": [],
        "reason": "",
    }
    if not policy.get("enabled"):
        support["reason"] = "not_isoform_conversion"
        return support
    explicit_gapmer_programs = [
        program
        for program in (raw_programs if isinstance(raw_programs, list) else [])
        if isinstance(program, dict)
        and _program_modality(program) == "gapmer"
        and str(program.get("selection_source") or "").strip().lower() != "splice_switching_pathogenic_isoform"
    ]
    if not explicit_gapmer_programs:
        support["reason"] = "gapmer_not_requested"
        return support
    targets = _splice_switching_gapmer_targets(structured_goal, require_direct_signal=True)
    if not targets:
        support["reason"] = "no_explicit_direct_decrease_targets"
        return support
    statuses, has_resolution_context = _isoform_resolution_status_by_label(structured_goal)
    eligible_targets: List[Dict[str, Any]] = []
    omitted: List[Dict[str, str]] = []
    for target in targets:
        label = str(target.get("isoform_label") or "").strip()
        status = statuses.get(label, "unknown")
        if status == "resolved" or not has_resolution_context:
            eligible_targets.append(target)
        else:
            omitted.append({"isoform_label": label, "status": status})
    if not eligible_targets:
        support["reason"] = "target_isoform_unresolved_or_skipped"
        support["omitted_target_isoforms"] = omitted
        return support
    support["enabled"] = True
    support["target_isoforms"] = [
        str(target.get("isoform_label") or "").strip()
        for target in eligible_targets
        if str(target.get("isoform_label") or "").strip()
    ]
    support["omitted_target_isoforms"] = omitted
    support["reason"] = "splice_switching_support"
    return support


def _effective_gapmer_design_programs(structured_goal: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    programs = _design_programs(structured_goal, "gapmer")
    if not programs:
        return []
    support_policy = _splice_switch_gapmer_support_policy(structured_goal, _design_programs(structured_goal))
    allowed_targets = {
        str(label).strip()
        for label in support_policy.get("target_isoforms") or []
        if str(label).strip()
    }
    effective: List[Dict[str, Any]] = []
    for program in programs:
        if not isinstance(program, dict):
            continue
        selection_source = str(program.get("selection_source") or "").strip().lower()
        if selection_source == "splice_switching_pathogenic_isoform":
            isoform_label = str(program.get("isoform_label") or "").strip()
            if not support_policy.get("enabled"):
                continue
            if allowed_targets and isoform_label and isoform_label not in allowed_targets:
                continue
        effective.append(program)
    return effective


def _program_is_conditional_gapmer_fallback(program: Any) -> bool:
    if not isinstance(program, dict) or _program_modality(program) != "gapmer":
        return False
    execution_policy = (
        program.get("execution_policy")
        if isinstance(program.get("execution_policy"), dict)
        else {}
    )
    if (
        str(execution_policy.get("role") or "").strip().lower() == "fallback"
        and str(execution_policy.get("activation_condition") or "")
        .strip()
        .lower()
        == "no_viable_primary_routes"
    ):
        return True
    text = " ".join(
        str(program.get(key) or "")
        for key in (
            "program_id",
            "label",
            "objective",
            "notes",
            "success_criteria_notes",
            "selection_source",
            "fallback_condition",
        )
    ).lower()
    if "fallback" in text:
        return True
    priority = _coerce_positive_int(program.get("priority"))
    if priority is not None and priority > 1 and "primary" not in text:
        return True
    return bool("if" in text and "splice" in text and "viable" in text)


def _routing_policy_from_goal(
    structured_goal: Optional[Dict[str, Any]],
    route_summary: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Project declared program control flow into a canonical routing policy."""

    programs = _design_programs(structured_goal)
    if not programs:
        return {}
    primary_program: Optional[Dict[str, Any]] = None
    fallback_program: Optional[Dict[str, Any]] = None
    for program in programs:
        if not isinstance(program, dict):
            continue
        execution_policy = (
            program.get("execution_policy")
            if isinstance(program.get("execution_policy"), dict)
            else {}
        )
        role = str(execution_policy.get("role") or "").strip().lower()
        activation_condition = str(
            execution_policy.get("activation_condition") or ""
        ).strip().lower()
        if role == "primary" and primary_program is None:
            primary_program = program
        elif (
            role == "fallback"
            and activation_condition == "no_viable_primary_routes"
            and fallback_program is None
        ):
            fallback_program = program

    if primary_program is None:
        primary_program = next(
            (
                program
                for program in programs
                if isinstance(program, dict)
                and not _program_is_conditional_gapmer_fallback(program)
            ),
            None,
        )
    if fallback_program is None:
        fallback_program = next(
            (
                program
                for program in programs
                if _program_is_conditional_gapmer_fallback(program)
            ),
            None,
        )

    primary_modality = _program_modality(primary_program)
    if not primary_modality:
        return {}
    policy: Dict[str, Any] = {"primary_modality": primary_modality}
    fallback_modality = _program_modality(fallback_program)
    if fallback_modality:
        viable_primary_routes = _route_summary_has_viable_steric_candidates(
            route_summary
        )
        policy["conditional_fallback"] = {
            "modality": fallback_modality,
            "activation_condition": "no_viable_primary_routes",
            "activated": not viable_primary_routes,
            "activation_reason": (
                "no_viable_primary_routes"
                if not viable_primary_routes
                else "viable_primary_routes_available"
            ),
        }
    return policy


def _gapmer_programs_are_conditional_fallback_only(structured_goal: Optional[Dict[str, Any]]) -> bool:
    programs = _effective_gapmer_design_programs(structured_goal)
    return bool(programs) and all(_program_is_conditional_gapmer_fallback(program) for program in programs)


def _route_summary_has_viable_steric_candidates(summary: Any) -> bool:
    if not isinstance(summary, dict):
        return False
    goals = summary.get("goals")
    if isinstance(goals, list):
        for goal in goals:
            if isinstance(goal, dict) and _coerce_positive_int(goal.get("count")):
                return True
    jobs = summary.get("jobs")
    if isinstance(jobs, list):
        for job in jobs:
            if isinstance(job, dict) and _coerce_positive_int(job.get("selected_tile_count")):
                return True
    steps = summary.get("steps")
    if isinstance(steps, list):
        for step in steps:
            if not isinstance(step, dict):
                continue
            result = step.get("result")
            if isinstance(result, dict) and _coerce_positive_int(result.get("count")):
                return True
    return False


def _run_has_viable_steric_routes(run_dir: str) -> bool:
    run_path = Path(run_dir).expanduser()
    summary_path = _run_path(run_path, "strategy_router_summary.json")
    if summary_path.exists():
        try:
            summary = json.loads(summary_path.read_text(encoding="utf-8"))
        except Exception:
            summary = {}
        if _route_summary_has_viable_steric_candidates(summary):
            return True
    routes_dir = _run_path(run_path, "strategy_routes")
    if routes_dir.exists():
        for csv_path in routes_dir.glob("*.route.csv"):
            try:
                with csv_path.open(newline="", encoding="utf-8") as handle:
                    reader = csv.reader(handle)
                    next(reader, None)
                    if next(reader, None) is not None:
                        return True
            except Exception:
                continue
    return False


def _run_attempted_steric_routing(run_dir: str) -> bool:
    run_path = Path(run_dir).expanduser()
    return bool(_run_path(run_path, "strategy_router_summary.json").exists() or any(_run_path(run_path, "strategy_routes").glob("*.route.csv")))


def _run_needs_conditional_gapmer_fallback(run_dir: str) -> bool:
    if not _run_attempted_steric_routing(run_dir):
        return False
    return not _run_has_viable_steric_routes(run_dir)


def _synthesize_splice_switch_gapmer_programs(
    structured_goal: Optional[Dict[str, Any]],
    raw_programs: Optional[List[Dict[str, Any]]] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    plan = {
        "enabled": False,
        "synthesized_program_count": 0,
        "target_isoforms": [],
        "reason": "",
    }
    if not isinstance(structured_goal, dict):
        return [], plan

    policy = _splice_switch_gapmer_support_policy(
        structured_goal,
        raw_programs if isinstance(raw_programs, list) else None,
    )
    if not policy.get("enabled"):
        plan["reason"] = str(policy.get("reason") or "not_isoform_conversion")
        if policy.get("omitted_target_isoforms"):
            plan["omitted_target_isoforms"] = deepcopy(policy.get("omitted_target_isoforms"))
        return [], plan

    targets = _splice_switching_gapmer_targets(structured_goal, require_direct_signal=True)
    if not targets:
        plan["reason"] = "no_explicit_direct_decrease_targets"
        return [], plan
    allowed_targets = {
        str(label).strip()
        for label in policy.get("target_isoforms") or []
        if str(label).strip()
    }
    if policy.get("omitted_target_isoforms"):
        plan["omitted_target_isoforms"] = deepcopy(policy.get("omitted_target_isoforms"))
    targets = [
        target
        for target in targets
        if str(target.get("isoform_label") or "").strip() in allowed_targets
    ]
    if not targets:
        plan["reason"] = str(policy.get("reason") or "target_isoform_unresolved_or_skipped")
        return [], plan

    beneficial_labels: List[str] = []
    for objective in structured_goal.get("splice_isoform_objectives") or []:
        if not isinstance(objective, dict):
            continue
        isoform_label = str(
            objective.get("isoform_label")
            or objective.get("transcript_label")
            or objective.get("transcript_id")
            or ""
        ).strip()
        if not isoform_label:
            continue
        direction = _normalize_isoform_objective_direction(
            objective.get("desired_abundance") or objective.get("direction") or objective.get("goal")
        )
        role = _normalize_isoform_objective_role(objective.get("role"))
        if direction == "increase" or role == "beneficial":
            beneficial_labels.append(isoform_label)

    reference_catalog = structured_goal.get("isoform_transcripts")
    if not isinstance(reference_catalog, dict):
        reference_catalog = {}
    reference_resolver = getattr(_goal_runtime_module(), "_declared_reference_isoform_labels", None)

    def target_identity(*references: Any) -> Optional[Tuple[str, str]]:
        declared = {str(value).strip().casefold() for value in references if str(value or "").strip()}
        matches = reference_resolver(reference_catalog, *references) if callable(reference_resolver) else set()
        if len(matches) == 1:
            return ("resolved", str(next(iter(matches))))
        if not matches and len(declared) == 1:
            return ("declared", next(iter(declared)))
        return None  # Conflicting or ambiguous references cannot establish equivalence.

    existing_targets: Set[Tuple[str, str]] = set()
    for program in raw_programs if isinstance(raw_programs, list) else []:
        if not isinstance(program, dict) or _program_modality(program) != "gapmer":
            continue
        identity = target_identity(program.get("isoform_label"), program.get("transcript_id"))
        if identity is not None:
            existing_targets.add(identity)
        # An explicitly requested cohort already provides knockdown support
        # for each verified member. Do not synthesize duplicate member jobs.
        if _gapmer_program_declares_cohort(program):
            for reference in program.get("transcript_ids") or []:
                member = target_identity(reference)
                if member is not None:
                    existing_targets.add(member)

    synthesized: List[Dict[str, Any]] = []
    for idx, target in enumerate(targets, start=1):
        isoform_label = str(target.get("isoform_label") or "").strip()
        if not isoform_label or target_identity(isoform_label) in existing_targets:
            continue
        beneficial_summary = ", ".join(beneficial_labels[:3])
        if len(beneficial_labels) > 3:
            beneficial_summary = f"{beneficial_summary} +{len(beneficial_labels) - 3} more"
        note_bits = [
            "Synthesized gapmer support for splice switching.",
            "Rank target-specific tiles while retaining the requested protection constraints for other isoforms.",
        ]
        if beneficial_summary:
            note_bits.append(f"Isoforms requested for protection: {beneficial_summary}.")
        rationale = str(target.get("rationale") or "").strip()
        if rationale:
            note_bits.append(f"Objective rationale: {rationale}.")
        inherited_chemistry = structured_goal.get("chemistry")
        chemistry_policy = structured_goal.get("chemistry_policy")
        if chemistry_policy == "leave_unspecified":
            derived_chemistry = "unspecified"
        elif not inherited_chemistry or _chemistry_platform(_canonicalize_chemistry_payload(inherited_chemistry)) == "steric_blocker":
            derived_chemistry = "gapmer"
        else:
            # Preserve an explicit compatible architecture or unresolved input
            # for normal chemistry resolution; do not replace it with a default.
            derived_chemistry = deepcopy(inherited_chemistry)
        synthesized.append(
            {
                "program_id": f"gapmer_pathogenic_isoform_{idx:02d}",
                "label": f"Gapmer knockdown of {isoform_label}",
                "modality": "gapmer",
                "intent": "knockdown",
                "objective": f"Gapmer tiling across the transcript requested for reduction: {isoform_label}",
                "isoform_label": isoform_label,
                "run_splice_eval": False,
                "run_splice_router": False,
                "gapmer_uniqueness_mode": "pathogenic_preferred",
                "gapmer_target_role": explicit_biological_role(target.get("role")),
                "chemistry": derived_chemistry,
                "chemistry_policy": "leave_unspecified" if chemistry_policy == "leave_unspecified" else "select",
                "notes": " ".join(bit for bit in note_bits if bit),
                "selection_source": "splice_switching_pathogenic_isoform",
                "priority": "secondary",
            }
        )

    plan["enabled"] = True
    plan["synthesized_program_count"] = len(synthesized)
    plan["target_isoforms"] = [str(target.get("isoform_label") or "") for target in targets if str(target.get("isoform_label") or "").strip()]
    plan["reason"] = "splice_switching_support"
    if policy.get("priority"):
        plan["steric_priority"] = policy.get("priority")
    return synthesized, plan


def _ensure_splice_switch_gapmer_programs(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    if not isinstance(structured_goal, dict):
        return {}
    raw_programs = (
        deepcopy(structured_goal.get("design_programs"))
        if isinstance(structured_goal.get("design_programs"), list)
        else []
    )
    base_programs = [
        dict(program)
        for program in raw_programs
        if isinstance(program, dict)
        and str(program.get("selection_source") or "").strip().lower() != "splice_switching_pathogenic_isoform"
    ]
    synthesized, plan = _synthesize_splice_switch_gapmer_programs(structured_goal, base_programs)
    updated_programs = base_programs + synthesized
    removed_synthetic = len(updated_programs) != len(raw_programs)
    if synthesized or removed_synthetic:
        structured_goal["design_programs"] = updated_programs
        if isinstance(final_payload, dict):
            final_payload["design_programs"] = deepcopy(updated_programs)
    if isinstance(final_payload, dict):
        if plan.get("enabled") or plan.get("reason") == "target_isoform_unresolved_or_skipped":
            final_payload["splice_switch_gapmer_plan"] = deepcopy(plan)
        else:
            final_payload.pop("splice_switch_gapmer_plan", None)
    if plan.get("enabled") or plan.get("reason") == "target_isoform_unresolved_or_skipped":
        structured_goal["splice_switch_gapmer_plan"] = deepcopy(plan)
    else:
        structured_goal.pop("splice_switch_gapmer_plan", None)
    return plan


def _program_is_exploratory_steric(program: Optional[Dict[str, Any]]) -> bool:
    if _program_modality(program) != "steric":
        return False
    policy = _normalize_steric_targeting_policy(
        (program or {}).get("targeting_policy") or (program or {}).get("steric_targeting_policy")
    )
    return policy in {"default_exploratory", "exploratory_derived"}


def _synthesize_top_level_explicit_steric_program(
    structured_goal: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return None
    explicit_targets = (
        deepcopy(structured_goal.get("explicit_splice_targets"))
        if isinstance(structured_goal.get("explicit_splice_targets"), list)
        else []
    )
    target_region = _normalize_target_region(structured_goal.get("target_region"))
    if not explicit_targets and not target_region:
        return None

    label = str(
        structured_goal.get("target_context")
        or structured_goal.get("objective")
        or structured_goal.get("gene_symbol")
        or "User-specified steric splice modulation"
    ).strip() or "User-specified steric splice modulation"
    objective = "User-specified steric splice-modulation target"
    if target_region:
        objective = f"User-specified steric splice-modulation target in {target_region}"
    elif explicit_targets:
        objective = "User-specified steric splice-modulation target from explicit splice targets"

    program: Dict[str, Any] = {
        "program_id": "steric_explicit_primary",
        "label": label,
        "modality": "steric",
        "intent": str(structured_goal.get("intent") or "splice_modulation").strip().lower() or "splice_modulation",
        "objective": objective,
        "targeting_policy": "explicit_user_region",
        "run_splice_eval": _design_request_requires_splice_eval(None, fallback_goal=structured_goal),
        "run_splice_router": _design_request_requires_splice_router(None, fallback_goal=structured_goal),
        "notes": "Synthesized from top-level explicit steric targeting so exploratory splice windows can be added without dropping the user-specified mechanism.",
    }
    if target_region:
        program["target_region"] = target_region
    if explicit_targets:
        program["explicit_splice_targets"] = explicit_targets
    for key in ("desired_effect", "exon_label", "focus_exons_only"):
        if structured_goal.get(key) not in (None, "", []):
            program[key] = deepcopy(structured_goal.get(key))
    if structured_goal.get("chemistry") not in (None, "", [], {}):
        program["chemistry"] = deepcopy(structured_goal.get("chemistry"))
    flanks = structured_goal.get("flanks")
    if isinstance(flanks, dict) and flanks:
        program["flanks"] = deepcopy(flanks)
    return program


def _collect_exploratory_splice_site_entries(structured_goal: Optional[Dict[str, Any]]) -> Tuple[List[Dict[str, Any]], str]:
    if not isinstance(structured_goal, dict):
        return [], ""

    sources: List[Tuple[str, Any]] = []
    splice_site_plan = structured_goal.get("splice_site_plan")
    if not (isinstance(splice_site_plan, list) and splice_site_plan):
        splice_site_plan = _repair_splice_site_plan_from_resolved_isoforms(structured_goal)
    if isinstance(splice_site_plan, list) and splice_site_plan:
        sources.append(("splice_site_plan", splice_site_plan))

    strategy_analysis = (
        structured_goal.get("splice_strategy_analysis")
        if isinstance(structured_goal.get("splice_strategy_analysis"), dict)
        else {}
    )
    context_payload = (
        strategy_analysis.get("context_payload")
        if isinstance(strategy_analysis.get("context_payload"), dict)
        else {}
    )
    strategy_sites: List[Dict[str, Any]] = []
    for key in ("unique_splice_sites", "shared_splice_sites"):
        raw_sites = context_payload.get(key)
        if isinstance(raw_sites, list):
            strategy_sites.extend(site for site in raw_sites if isinstance(site, dict))
    if strategy_sites:
        sources.append(("splice_strategy_analysis", strategy_sites))

    isoform_transcripts = (
        structured_goal.get("isoform_transcripts")
        if isinstance(structured_goal.get("isoform_transcripts"), dict)
        else {}
    )
    if isinstance(isoform_transcripts, dict) and isoform_transcripts:
        transcript_sites: List[Dict[str, Any]] = []
        uniqueness_hint = "unique" if len(isoform_transcripts) == 1 else None
        for iso_label, payload in isoform_transcripts.items():
            if not isinstance(payload, dict):
                continue
            sites = payload.get("sites") if isinstance(payload.get("sites"), list) else []
            chrom_hint = payload.get("chrom") or payload.get("metadata", {}).get("seq_region_name")
            strand_hint = payload.get("strand") or payload.get("metadata", {}).get("strand") or "+"
            for site in sites:
                if not isinstance(site, dict):
                    continue
                chrom = str(site.get("chrom") or chrom_hint or "").strip()
                strand = str(site.get("strand") or strand_hint or "+").strip() or "+"
                exon_index = site.get("exon_index")
                for site_kind in ("acceptor", "donor"):
                    position = site.get(site_kind)
                    if not isinstance(position, int):
                        continue
                    if not bool(site.get(f"{site_kind}_plan_ok", True)):
                        continue
                    transcript_sites.append(
                        {
                            "chrom": chrom,
                            "position": int(position),
                            "site": site_kind,
                            "strand": strand,
                            "label": f"{site_kind}@{int(position)}",
                            "exon_index": exon_index if isinstance(exon_index, int) else None,
                            "uniqueness": uniqueness_hint,
                            "delta_direction": None,
                            "isoform_label": str(iso_label),
                        }
                    )
        if transcript_sites:
            sources.append(("isoform_transcripts", transcript_sites))

    for source_name, raw_entries in sources:
        entries: List[Dict[str, Any]] = []
        seen: Set[Tuple[str, int, str, str]] = set()
        for raw in raw_entries if isinstance(raw_entries, list) else []:
            if not isinstance(raw, dict):
                continue
            chrom = str(raw.get("chrom") or raw.get("chromosome") or "").strip()
            site = str(raw.get("site") or "").strip().lower()
            position = raw.get("position")
            strand = str(raw.get("strand") or "+").strip() or "+"
            if not chrom or site not in {"acceptor", "donor"} or not isinstance(position, int):
                continue
            exon_indices = raw.get("exon_indices") if isinstance(raw.get("exon_indices"), dict) else {}
            exon_values = sorted({int(value) for value in exon_indices.values() if isinstance(value, int)})
            exon_index = raw.get("exon_index")
            if not isinstance(exon_index, int) and len(exon_values) == 1:
                exon_index = exon_values[0]
            key = (chrom, int(position), site, strand)
            if key in seen:
                continue
            seen.add(key)
            entries.append(
                {
                    **{key: deepcopy(raw[key]) for key in (
                        "source", "explicit_start", "explicit_end",
                        "isoform_abundance_objectives", "delta_per_isoform_scope",
                        "directional_evidence_status", "directional_evidence_note",
                    ) if key in raw},
                    "chrom": chrom,
                    "position": int(position),
                    "site": site,
                    "strand": strand,
                    "label": f"{site}@{int(position)}",
                    "exon_index": exon_index if isinstance(exon_index, int) else None,
                    "uniqueness": str(raw.get("uniqueness") or "").strip().lower()
                    or None,
                    "delta_direction": str(raw.get("delta_direction") or "")
                    .strip()
                    .lower()
                    or None,
                    "delta_per_isoform": dict(raw.get("delta_per_isoform"))
                    if isinstance(raw.get("delta_per_isoform"), dict)
                    else {},
                    "present_in": list(raw.get("present_in"))
                    if isinstance(raw.get("present_in"), list)
                    else [],
                    "absent_in": list(raw.get("absent_in"))
                    if isinstance(raw.get("absent_in"), list)
                    else [],
                    "exon_indices": dict(exon_indices) if exon_indices else {},
                    "isoform_label": str(raw.get("isoform_label") or "").strip()
                    or None,
                    "covers_all_isoforms": bool(raw.get("covers_all_isoforms"))
                    if isinstance(raw.get("covers_all_isoforms"), bool)
                    else None,
                    "pathogenic_isoforms": (
                        list(raw.get("pathogenic_isoforms"))
                        if isinstance(raw.get("pathogenic_isoforms"), list)
                        else []
                    ),
                    "beneficial_isoforms": (
                        list(raw.get("beneficial_isoforms"))
                        if isinstance(raw.get("beneficial_isoforms"), list)
                        else []
                    ),
                    "neutral_isoforms": (
                        list(raw.get("neutral_isoforms"))
                        if isinstance(raw.get("neutral_isoforms"), list)
                        else []
                    ),
                    "net_effect_hint": str(raw.get("net_effect_hint") or "")
                    .strip()
                    .lower()
                    or None,
                    "conflict_between_objectives": bool(
                        raw.get("conflict_between_objectives")
                    ),
                    "unique_to_pathogenic": bool(raw.get("unique_to_pathogenic")),
                    "unique_to_beneficial": bool(raw.get("unique_to_beneficial")),
                }
            )
        if entries:
            return entries, source_name
    return [], ""


def _exploratory_site_label(entry: Optional[Dict[str, Any]]) -> str:
    if not isinstance(entry, dict):
        return ""
    label = str(
        entry.get("canonical_label")
        or entry.get("label")
        or entry.get("site_label")
        or entry.get("label_hint")
        or ""
    ).strip()
    if label:
        return label
    site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
    position = entry.get("position")
    if site_kind in {"acceptor", "donor"} and isinstance(position, int):
        return f"{site_kind}@{int(position)}"
    return ""


def _exploratory_relevant_isoforms(structured_goal: Optional[Dict[str, Any]]) -> Set[str]:
    if not isinstance(structured_goal, dict):
        return set()
    labels: List[str] = []
    objectives = (
        structured_goal.get("splice_isoform_objectives")
        if isinstance(structured_goal.get("splice_isoform_objectives"), list)
        else []
    )
    for objective in objectives:
        if not isinstance(objective, dict):
            continue
        label = str(
            objective.get("isoform_label")
            or objective.get("transcript_label")
            or objective.get("transcript_id")
            or ""
        ).strip()
        if label:
            labels.append(label)
    if not labels:
        isoform_transcripts = (
            structured_goal.get("isoform_transcripts")
            if isinstance(structured_goal.get("isoform_transcripts"), dict)
            else {}
        )
        labels.extend(str(label).strip() for label in isoform_transcripts.keys() if str(label).strip())
    return set(labels)


def _exploratory_site_isoforms(entry: Optional[Dict[str, Any]]) -> Set[str]:
    if not isinstance(entry, dict):
        return set()
    labels: Set[str] = set()
    for source in (
        entry.get("present_in"),
        entry.get("absent_in"),
        entry.get("pathogenic_isoforms"),
        entry.get("beneficial_isoforms"),
        entry.get("neutral_isoforms"),
        entry.get("shared_isoforms"),
        entry.get("unique_isoforms"),
    ):
        if not isinstance(source, list):
            continue
        for item in source:
            text = str(item or "").strip()
            if text:
                labels.add(text)
    exon_indices = entry.get("exon_indices")
    if isinstance(exon_indices, dict):
        for iso_label in exon_indices.keys():
            text = str(iso_label or "").strip()
            if text:
                labels.add(text)
    isoform_label = str(entry.get("isoform_label") or "").strip()
    if isoform_label:
        labels.add(isoform_label)
    return labels


def _program_isoform_identity_aliases(
    structured_goal: Optional[Dict[str, Any]],
    base_program: Optional[Dict[str, Any]],
) -> Set[str]:
    """Return exact, typed labels/IDs that identify one intervention branch."""

    if not isinstance(base_program, dict):
        return set()
    aliases = {
        str(base_program.get(field) or "").strip().casefold()
        for field in ("isoform_label", "transcript_id")
        if str(base_program.get(field) or "").strip()
    }
    if not aliases and isinstance(structured_goal, dict):
        reference = structured_goal.get("default_exon_context_reference")
        reference = reference if isinstance(reference, dict) else {}

        def _exon_labels(item: Dict[str, Any]) -> Set[str]:
            labels: Set[str] = set()
            for field in ("exon_label", "exon_labels"):
                raw = item.get(field)
                values = raw if isinstance(raw, (list, tuple)) else [raw]
                labels.update(str(value).strip() for value in values if value is not None)
            return labels

        program_exons = _exon_labels(base_program)
        desired_delta = str(base_program.get("desired_delta") or "").strip().lower()
        objectives = structured_goal.get("splice_isoform_objectives")
        objectives = objectives if isinstance(objectives, list) else []
        default_match = any(
            isinstance(objective, dict)
            and objective.get("objective_scope") == "default_exon_context"
            and program_exons.issubset(_exon_labels(objective))
            and str(objective.get("desired_abundance") or "").strip().lower() == desired_delta
            for objective in objectives
        )
        transcripts = structured_goal.get("isoform_transcripts") or {}
        entry = transcripts.get(reference.get("isoform_label")) if isinstance(transcripts, dict) else None
        if (
            program_exons and desired_delta in {"increase", "decrease"} and default_match
            and program_exons.issubset(_exon_labels(reference))
            and isinstance(entry, dict) and entry.get("transcript_id") == reference.get("transcript_id")
        ):
            aliases.add(str(reference["isoform_label"]).strip().casefold())
    if not aliases or not isinstance(structured_goal, dict):
        return aliases

    transcript_ids = (
        structured_goal.get("isoform_transcript_ids")
        if isinstance(structured_goal.get("isoform_transcript_ids"), dict)
        else {}
    )
    transcripts = (
        structured_goal.get("isoform_transcripts")
        if isinstance(structured_goal.get("isoform_transcripts"), dict)
        else {}
    )
    for raw_label in set(transcript_ids) | set(transcripts):
        label = str(raw_label or "").strip()
        if not label:
            continue
        raw_id = transcript_ids.get(raw_label)
        transcript = transcripts.get(raw_label)
        transcript_id = str(
            raw_id
            or (transcript.get("transcript_id") if isinstance(transcript, dict) else "")
            or ""
        ).strip()
        related = {label.casefold()}
        if transcript_id:
            related.add(transcript_id.casefold())
        # Native reference lookup may key splice evidence by the stable ID
        # while a user-locked program correctly retains its exact version.
        # Bridge only the version attested by this resolved transcript; never
        # strip an arbitrary requested version to make an unsupported match.
        metadata = transcript.get("metadata") if isinstance(transcript, dict) else None
        if isinstance(metadata, dict):
            versioned_id = str(metadata.get("versioned_id") or "").strip()
            if re.fullmatch(r"(?:ENS[A-Z]*T\d+|[NX][MR]_\d+)\.\d+", versioned_id, flags=re.IGNORECASE):
                stable_id, version = versioned_id.rsplit(".", 1)
                attested_ids = {stable_id.casefold(), versioned_id.casefold()}
                metadata_id = str(metadata.get("id") or transcript_id).strip()
                metadata_version = metadata.get("version")
                if (
                    transcript_id.casefold() in attested_ids
                    and metadata_id.casefold() in attested_ids
                    and (metadata_version is None or str(metadata_version) == version)
                ):
                    related.add(versioned_id.casefold())
        if aliases.intersection(related):
            aliases.update(related)
    return aliases


def _exploratory_site_matches_program_scope(
    entry: Optional[Dict[str, Any]],
    *,
    identity_aliases: Set[str],
    desired_delta: str,
) -> bool:
    """Match a resolved splice site to one typed route identity and direction.

    A named route may consume only evidence explicitly attached to that route's
    isoform/transcript.  Unscoped sites remain available to unscoped exploratory
    programs, but are not guessed into a named branch.
    """

    if not isinstance(entry, dict) or not identity_aliases:
        return not identity_aliases

    per_isoform = (
        entry.get("delta_per_isoform")
        if isinstance(entry.get("delta_per_isoform"), dict)
        else {}
    )
    matching_directions = {
        str(direction or "").strip().lower()
        for label, direction in per_isoform.items()
        if str(label or "").strip().casefold() in identity_aliases
    }
    matching_directions.discard("")
    if matching_directions:
        return not desired_delta or desired_delta in matching_directions

    present_identities: Set[str] = set()
    for source in (
        entry.get("present_in"),
        entry.get("pathogenic_isoforms"),
        entry.get("beneficial_isoforms"),
        entry.get("neutral_isoforms"),
    ):
        if isinstance(source, list):
            present_identities.update(
                str(item or "").strip().casefold()
                for item in source
                if str(item or "").strip()
            )
    present_identities.update(
        str(item or "").strip().casefold()
        for item in (
            entry.get("exon_indices").keys()
            if isinstance(entry.get("exon_indices"), dict)
            else []
        )
        if str(item or "").strip()
    )
    isoform_label = str(entry.get("isoform_label") or "").strip()
    if isoform_label:
        present_identities.add(isoform_label.casefold())
    if not identity_aliases.intersection(present_identities):
        return False

    entry_delta = str(entry.get("delta_direction") or "").strip().lower()
    if desired_delta and entry_delta in {"increase", "decrease"}:
        return entry_delta == desired_delta
    return True


def _explicit_target_route_binding(
    entry: Dict[str, Any],
    structured_goal: Dict[str, Any],
    base_program: Dict[str, Any],
    identity_aliases: Set[str],
    desired_delta: str,
) -> Optional[Dict[str, Any]]:
    """Bind a supplied hypothetical feature to its route, not to reference annotation.

    The materializer deliberately gives an altered transcript a distinct identity.
    Its anchors can still serve the user's route when the actual explicit target,
    model provenance, requested feature, coordinates and direction attest the link.
    Do not add the altered model as a general alias for the reference transcript.
    """
    if entry.get("source") != "explicit_splice_target" or not identity_aliases:
        return None
    targets = structured_goal.get("explicit_splice_targets")
    transcripts = structured_goal.get("isoform_transcripts")
    if not isinstance(targets, list) or not isinstance(transcripts, dict):
        return None
    program_labels = set()
    for key in ("exon_label", "exon_labels"):
        value = base_program.get(key)
        values = value if isinstance(value, list) else [value]
        program_labels.update(str(v).strip().casefold() for v in values if v is not None)
    for target in targets:
        if not isinstance(target, dict):
            continue
        model_label = str(target.get("isoform_label") or "").strip()
        model = transcripts.get(model_label)
        metadata = model.get("metadata") if isinstance(model, dict) else None
        if not isinstance(metadata, dict) or metadata.get("explicit_target_modified") is not True:
            continue
        if metadata.get("source") != "explicit_splice_target_modified":
            continue
        base_ids = {str(metadata.get(k) or "").strip().casefold()
                    for k in ("base_transcript_id", "base_isoform_label")}
        target_ids = {str(target.get(k) or "").strip().casefold()
                      for k in ("transcript_id", "base_isoform_label")}
        if not identity_aliases.intersection(base_ids).intersection(target_ids):
            continue
        target_label = target.get("requested_exon_label", target.get("exon_label"))
        if program_labels and str(target_label or "").strip().casefold() not in program_labels:
            continue
        start, end = _coerce_positive_int(target.get("start")), _coerce_positive_int(target.get("end"))
        if start is None or end is None or start == end:
            continue
        start, end = min(start, end), max(start, end)
        strand = str(target.get("strand") or "").strip()
        if strand not in {"+", "-"} or entry.get("strand") != strand:
            continue
        if not (_chrom_aliases(target.get("chrom")) & _chrom_aliases(entry.get("chrom"))):
            continue
        if (entry.get("explicit_start"), entry.get("explicit_end")) != (start, end):
            continue
        anchor = start if (entry.get("site") == "acceptor") == (strand == "+") else end
        if entry.get("position") != anchor:
            continue
        target_delta = str(target.get("desired_delta") or "").strip().lower()
        if desired_delta not in {"increase", "decrease"} or desired_delta != target_delta:
            continue
        if not _exploratory_site_matches_program_scope(
            entry, identity_aliases={model_label.casefold()}, desired_delta=desired_delta,
        ):
            continue
        return {
            "model_identity": model_label,
            "base_transcript_id": metadata.get("base_transcript_id"),
            "requested_feature": target_label,
            "chrom": target.get("chrom"), "start": start, "end": end, "strand": strand,
            "desired_delta": desired_delta,
            "source": "explicit_user_target_in_modified_transcript_model",
            "reference_annotation_verified": False,
        }
    return None


def _program_isoform_abundance_directions(structured_goal, base_program):
    """Keep an isoform's abundance separate from the program's splice event.

    Inclusion of a normal segment may decrease an unwanted shortened isoform.
    The typed outcome attached to that identity controls identity admission;
    the program's event direction is preserved for structural interpretation.
    """
    identities = _program_isoform_identity_aliases(structured_goal, base_program)
    directions = set()
    for objective in structured_goal.get('splice_isoform_objectives') or []:
        if not isinstance(objective, dict) or objective.get('objective_scope') in {'default_exon_context', 'aggregate_class'}:
            continue
        if identities & _program_isoform_identity_aliases(structured_goal, objective):
            value = objective.get('desired_abundance')
            if value in {'increase', 'decrease'}:
                directions.add(value)
    for target in structured_goal.get('evaluation_targets') or []:
        if not isinstance(target, dict) or target.get('target_type') not in {'isoform', 'transcript', 'isoform_cohort'}:
            continue
        if identities & _program_isoform_identity_aliases(structured_goal, target):
            value = target.get('desired_delta')
            if value in {'increase', 'decrease'}:
                directions.add(value)
    return directions


def _scope_exploratory_sites_to_program(
    *,
    structured_goal: Dict[str, Any],
    site_entries: List[Dict[str, Any]],
    base_program: Optional[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    identity_aliases = _program_isoform_identity_aliases(
        structured_goal,
        base_program,
    )
    if not identity_aliases:
        return [dict(entry) for entry in site_entries if isinstance(entry, dict)]
    desired_delta = str((base_program or {}).get("desired_delta") or "").strip().lower()
    abundance_directions = _program_isoform_abundance_directions(structured_goal, base_program)
    if len(abundance_directions) > 1:
        return []  # Contradictory outcomes remain unresolved.
    identity_direction = next(iter(abundance_directions), desired_delta)
    scoped = []
    for entry in site_entries:
        if _exploratory_site_matches_program_scope(
            entry,
            identity_aliases=identity_aliases,
            desired_delta=identity_direction,
        ):
            scoped.append(dict(entry))
            continue
        binding = _explicit_target_route_binding(
            entry, structured_goal, base_program or {}, identity_aliases, desired_delta,
        )
        if binding:
            scoped.append({**entry, "explicit_target_route_binding": binding})
    return scoped


def _chrom_aliases(chrom_value: Any) -> Set[str]:
    text = str(chrom_value or "").strip()
    if not text:
        return set()
    aliases = {text}
    if text.lower().startswith("chr"):
        aliases.add(text[3:])
    else:
        aliases.add(f"chr{text}")
    return {alias for alias in aliases if alias}


def _exploratory_site_is_non_conserved(
    entry: Optional[Dict[str, Any]],
    *,
    relevant_isoforms: Set[str],
) -> bool:
    if not isinstance(entry, dict):
        return False
    if isinstance(entry.get("covers_all_isoforms"), bool):
        return not bool(entry.get("covers_all_isoforms"))

    present_labels = {
        text
        for text in (
            str(item or "").strip()
            for item in (entry.get("present_in") if isinstance(entry.get("present_in"), list) else [])
        )
        if text
    }
    absent_labels = {
        text
        for text in (
            str(item or "").strip()
            for item in (entry.get("absent_in") if isinstance(entry.get("absent_in"), list) else [])
        )
        if text
    }
    if relevant_isoforms:
        if absent_labels & relevant_isoforms:
            return True
        if present_labels:
            return not relevant_isoforms.issubset(present_labels)
        observed_labels = _exploratory_site_isoforms(entry) & relevant_isoforms
        if observed_labels:
            return not relevant_isoforms.issubset(observed_labels)

    uniqueness = str(entry.get("uniqueness") or "").strip().lower()
    if uniqueness == "unique":
        return True
    if str(entry.get("net_effect_hint") or "").strip().lower() in {
        "pathogenic_only",
        "beneficial_only",
        "conflict_between_objectives",
        "shared_with_beneficial",
        "pathogenic_shared",
        "beneficial_shared",
    }:
        return True
    if bool(entry.get("unique_to_pathogenic")) or bool(entry.get("unique_to_beneficial")):
        return True
    return False


def _exploratory_anchor_candidate_entries(
    *,
    structured_goal: Dict[str, Any],
    site_entries: List[Dict[str, Any]],
    base_program: Optional[Dict[str, Any]] = None,
) -> Tuple[List[Dict[str, Any]], str]:
    relevant_isoforms = _exploratory_relevant_isoforms(structured_goal)
    base_routing_candidates = None
    if (
        isinstance(base_program, dict)
        and not _program_is_exploratory_steric(base_program)
        and isinstance(base_program.get("routing_candidate_sites"), list)
    ):
        base_routing_candidates = base_program.get("routing_candidate_sites")
    site_entries_by_label = {
        _exploratory_site_label(entry): dict(entry)
        for entry in site_entries
        if isinstance(entry, dict) and _exploratory_site_label(entry)
    }
    named_route = bool(_program_isoform_identity_aliases(structured_goal, base_program))

    focused_anchor_entries: List[Dict[str, Any]] = []
    seen_focused_labels: Set[str] = set()
    for source in (
        base_routing_candidates,
        (
            ((structured_goal.get("splice_strategy_analysis") or {}).get("context_payload") or {}).get("steric_site_candidates")
            if isinstance((structured_goal.get("splice_strategy_analysis") or {}).get("context_payload"), dict)
            else None
        ),
        structured_goal.get("steric_site_candidates") if isinstance(structured_goal.get("steric_site_candidates"), list) else None,
    ):
        if not isinstance(source, list):
            continue
        for raw_entry in source:
            if isinstance(raw_entry, dict):
                label = _exploratory_site_label(raw_entry)
            else:
                label = str(raw_entry or "").strip()
            if not label or label in seen_focused_labels:
                continue
            if named_route and label not in site_entries_by_label:
                # site_entries has already been filtered by the route's typed
                # identity, direction, and site kind. Global strategy candidates
                # must not reintroduce another route's anchors through fallback.
                continue
            candidate = dict(site_entries_by_label.get(label) or (raw_entry if isinstance(raw_entry, dict) else {}))
            if not candidate:
                site_kind, position = _routing_label_site_parts(label)
                if site_kind and isinstance(position, int):
                    candidate = {
                        "label": label,
                        "site": site_kind,
                        "position": int(position),
                    }
            if not candidate:
                continue
            candidate.setdefault("label", label)
            if relevant_isoforms and not _exploratory_site_is_non_conserved(candidate, relevant_isoforms=relevant_isoforms):
                continue
            seen_focused_labels.add(label)
            focused_anchor_entries.append(candidate)
    route_signal_entries = [
        dict(entry)
        for entry in site_entries
        if _exploratory_site_is_non_conserved(entry, relevant_isoforms=relevant_isoforms)
        and _splice_entry_has_route_signal(entry)
    ]
    if focused_anchor_entries:
        merged_focused = list(focused_anchor_entries)
        added_route_signal = False
        for entry in route_signal_entries:
            label = _exploratory_site_label(entry)
            if not label or label in seen_focused_labels:
                continue
            seen_focused_labels.add(label)
            merged_focused.append(entry)
            added_route_signal = True
        return (
            merged_focused,
            "steric_site_candidates_plus_objective_route_signal_sites" if added_route_signal else "steric_site_candidates",
        )

    if route_signal_entries:
        return route_signal_entries, "objective_route_signal_sites"

    directional_entries = [
        dict(entry)
        for entry in site_entries
        if str(entry.get("delta_direction") or "").strip().lower() in {"increase", "decrease"}
    ]
    if directional_entries:
        return directional_entries, "directional_splice_sites"

    non_conserved_entries = [
        dict(entry)
        for entry in site_entries
        if _exploratory_site_is_non_conserved(entry, relevant_isoforms=relevant_isoforms)
    ]
    if non_conserved_entries:
        return non_conserved_entries[:3], "non_conserved_context_splice_sites"

    return [dict(entry) for entry in site_entries if isinstance(entry, dict)], "all_splice_sites"


def _exploratory_entry_overlaps_window(entry: Optional[Dict[str, Any]], window: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(entry, dict) or not isinstance(window, dict):
        return False
    chrom = str(entry.get("chrom") or "").strip()
    window_chrom = str(window.get("chrom") or "").strip()
    position = entry.get("position")
    if not chrom or not window_chrom or not isinstance(position, int):
        return False
    if not (_chrom_aliases(chrom) & _chrom_aliases(window_chrom)):
        return False
    try:
        start = int(window.get("start") or 0)
        end = int(window.get("end") or 0)
    except Exception:
        return False
    return start <= int(position) <= end


def _expand_exploratory_windows_with_local_sites(
    windows: List[Dict[str, Any]],
    site_entries: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    expanded: List[Dict[str, Any]] = []
    for window in windows:
        if not isinstance(window, dict):
            continue
        anchor_entries = window.get("site_entries") if isinstance(window.get("site_entries"), list) else []
        overlapping_entries = [
            dict(entry)
            for entry in site_entries
            if _exploratory_entry_overlaps_window(entry, window)
        ]
        if not overlapping_entries:
            overlapping_entries = [dict(entry) for entry in anchor_entries if isinstance(entry, dict)]
        overlapping_entries.sort(
            key=lambda entry: (
                int(entry.get("position") or 0),
                str(entry.get("site") or entry.get("site_kind") or ""),
                _exploratory_site_label(entry),
            )
        )
        window_copy = dict(window)
        window_copy["anchor_site_entries"] = [dict(entry) for entry in anchor_entries if isinstance(entry, dict)]
        window_copy["site_entries"] = overlapping_entries
        expanded.append(window_copy)
    return expanded


def _exploratory_window_flanks(
    *,
    structured_goal: Dict[str, Any],
    base_program: Optional[Dict[str, Any]] = None,
    default_bp: int = 200,
) -> Tuple[int, int]:
    for source in (
        base_program.get("flanks") if isinstance(base_program, dict) else None,
        structured_goal.get("flanks"),
    ):
        if not isinstance(source, dict):
            continue
        up_val = _coerce_positive_int(source.get("up"))
        down_val = _coerce_positive_int(source.get("down"))
        if up_val is not None or down_val is not None:
            return max(1, up_val or default_bp), max(1, down_val or default_bp)
    return default_bp, default_bp


def _merge_exploratory_site_windows(
    site_entries: List[Dict[str, Any]],
    *,
    up_bp: int,
    down_bp: int,
) -> List[Dict[str, Any]]:
    windows_by_chrom: Dict[str, List[Dict[str, Any]]] = {}
    for entry in site_entries:
        if not isinstance(entry, dict):
            continue
        chrom = str(entry.get("chrom") or "").strip()
        position = entry.get("position")
        if not chrom or not isinstance(position, int):
            continue
        start = max(1, int(position) - up_bp)
        end = max(start + 1, int(position) + down_bp)
        windows_by_chrom.setdefault(chrom, []).append(
            {
                "chrom": chrom,
                "start": start,
                "end": end,
                "strand_set": {str(entry.get("strand") or "+").strip() or "+"},
                "site_entries": [dict(entry)],
            }
        )

    merged_windows: List[Dict[str, Any]] = []
    for chrom, windows in windows_by_chrom.items():
        windows.sort(key=lambda item: (int(item["start"]), int(item["end"])))
        current: Optional[Dict[str, Any]] = None
        for window in windows:
            if current is None:
                current = window
                continue
            if int(window["start"]) <= int(current["end"]):
                current["end"] = max(int(current["end"]), int(window["end"]))
                current["strand_set"] = set(current["strand_set"]).union(set(window["strand_set"]))
                current["site_entries"].extend(window["site_entries"])
            else:
                merged_windows.append(current)
                current = window
        if current is not None:
            merged_windows.append(current)

    for idx, window in enumerate(merged_windows, start=1):
        site_entries_window = window.get("site_entries") if isinstance(window.get("site_entries"), list) else []
        site_labels = [
            str(entry.get("label") or f"{entry.get('site')}@{entry.get('position')}")
            for entry in site_entries_window
            if isinstance(entry, dict)
        ]
        site_kinds = sorted(
            {
                str(entry.get("site") or "").strip().lower()
                for entry in site_entries_window
                if isinstance(entry, dict) and str(entry.get("site") or "").strip().lower() in {"acceptor", "donor"}
            }
        )
        if site_kinds == ["acceptor"]:
            site_kind = "acceptor"
        elif site_kinds == ["donor"]:
            site_kind = "donor"
        else:
            site_kind = "both"
        strand_set = set(window.get("strand_set") or set())
        strand = next(iter(strand_set)) if len(strand_set) == 1 else "."
        window["window_index"] = idx
        window["site_labels"] = site_labels
        window["site_kind"] = site_kind
        window["strand"] = strand or "+"
    return merged_windows


def _derive_exploratory_steric_programs(
    *,
    structured_goal: Dict[str, Any],
    base_program: Optional[Dict[str, Any]] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    all_site_entries, source_name = _collect_exploratory_splice_site_entries(
        structured_goal
    )
    site_entries = list(all_site_entries)
    site_entries = _scope_exploratory_sites_to_program(
        structured_goal=structured_goal,
        site_entries=site_entries,
        base_program=base_program,
    )
    requested_site_kind = _infer_design_program_site_kind(base_program) if isinstance(base_program, dict) else ""
    if requested_site_kind in {"acceptor", "donor"}:
        site_entries = [
            entry
            for entry in site_entries
            if isinstance(entry, dict)
            and str(entry.get("site") or entry.get("site_kind") or "").strip().lower() == requested_site_kind
        ]
    if not site_entries:
        identities = _program_isoform_identity_aliases(
            structured_goal,
            base_program,
        )
        if identities and all_site_entries:
            return [], {
                "status": "unresolved_named_route_scope",
                "source": source_name or "splice_context",
                "program_id": str((base_program or {}).get("program_id") or "").strip()
                or None,
                "identities": sorted(identities),
                "desired_delta": str((base_program or {}).get("desired_delta") or "")
                .strip()
                .lower()
                or None,
                "site_kind": requested_site_kind or None,
            }
        return [], {}

    anchor_entries, anchor_source = _exploratory_anchor_candidate_entries(
        structured_goal=structured_goal,
        site_entries=site_entries,
        base_program=base_program,
    )
    if not anchor_entries:
        return [], {}

    up_bp, down_bp = _exploratory_window_flanks(structured_goal=structured_goal, base_program=base_program)
    merged_windows = _merge_exploratory_site_windows(anchor_entries, up_bp=up_bp, down_bp=down_bp)
    merged_windows = _expand_exploratory_windows_with_local_sites(merged_windows, site_entries)
    if not merged_windows:
        return [], {}

    base = dict(base_program) if isinstance(base_program, dict) else {}
    base_label = str(
        base.get("label")
        or base.get("objective")
        or structured_goal.get("target_context")
        or "Exploratory steric splice window"
    ).strip()
    base_objective = str(base.get("objective") or "").strip()
    base_program_id = str(base.get("program_id") or "").strip() or "steric_exploratory"
    run_splice_eval = _design_request_requires_splice_eval(base, fallback_goal=structured_goal)
    run_splice_router = _design_request_requires_splice_router(base, fallback_goal=structured_goal)
    desired_effect = base.get("desired_effect") if base.get("desired_effect") is not None else structured_goal.get("desired_effect")
    exon_label = base.get("exon_label") if isinstance(base.get("exon_label"), int) else structured_goal.get("exon_label")
    focus_exons_only = _coerce_bool(base.get("focus_exons_only"))
    if focus_exons_only is None:
        focus_exons_only = _coerce_bool(structured_goal.get("focus_exons_only"))

    aggregated_rows: List[List[Any]] = []
    aggregated_site_labels: List[str] = []
    site_kind_values: Set[str] = set()
    window_summaries: List[Dict[str, Any]] = []
    for idx, window in enumerate(merged_windows, start=1):
        window_site_entries = window.get("site_entries") if isinstance(window.get("site_entries"), list) else []
        anchor_site_entries = window.get("anchor_site_entries") if isinstance(window.get("anchor_site_entries"), list) else []
        site_labels = list(
            dict.fromkeys(
                _exploratory_site_label(entry)
                for entry in window_site_entries
                if isinstance(entry, dict) and _exploratory_site_label(entry)
            )
        )
        anchor_site_labels = list(
            dict.fromkeys(
                _exploratory_site_label(entry)
                for entry in anchor_site_entries
                if isinstance(entry, dict) and _exploratory_site_label(entry)
            )
        )
        short_site_labels = anchor_site_labels or site_labels
        short_sites = ", ".join(short_site_labels[:3])
        if len(short_site_labels) > 3:
            short_sites = f"{short_sites} +{len(short_site_labels) - 3} more"
        short_sites = short_sites or f"window_{idx:02d}"
        region_label = _slugify_job_id(f"{base_program_id}_explore_{idx:02d}", "steric_region")
        aggregated_rows.append(
            [
                str(window.get("chrom") or ""),
                max(0, int(window.get("start") or 1) - 1),
                int(window.get("end") or 1),
                region_label,
                0,
                str(window.get("strand") or "+"),
            ]
        )
        aggregated_site_labels.extend(str(label) for label in site_labels if str(label).strip())
        window_site_kinds = sorted(
            {
                str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
                for entry in window_site_entries
                if isinstance(entry, dict) and str(entry.get("site") or entry.get("site_kind") or "").strip().lower() in {"acceptor", "donor"}
            }
        )
        if window_site_kinds == ["acceptor"]:
            site_kind = "acceptor"
        elif window_site_kinds == ["donor"]:
            site_kind = "donor"
        else:
            site_kind = "both"
        if site_kind in {"acceptor", "donor", "both"}:
            site_kind_values.add(site_kind)
        window_summaries.append(
            {
                "window_index": idx,
                "label_hint": short_sites,
                "site_labels": list(site_labels),
                "anchor_site_labels": list(anchor_site_labels),
                "site_kind": site_kind or "both",
                "chrom": str(window.get("chrom") or ""),
                "start": int(window.get("start") or 0),
                "end": int(window.get("end") or 0),
                "strand": str(window.get("strand") or "+"),
            }
        )

    if not aggregated_rows:
        return [], {}

    unique_site_labels = list(dict.fromkeys(aggregated_site_labels))
    anchor_site_labels = list(
        dict.fromkeys(
            _exploratory_site_label(entry)
            for entry in anchor_entries
            if isinstance(entry, dict) and _exploratory_site_label(entry)
        )
    )
    anchor_site_records = [
        {
            "chrom": str(entry.get("chrom") or "").strip(),
            "position": int(entry["position"]),
            "site_kind": str(entry.get("site") or entry.get("site_kind") or "")
            .strip()
            .lower(),
            "strand": str(entry.get("strand") or "+").strip() or "+",
        }
        for entry in anchor_entries
        if isinstance(entry, dict)
        and str(entry.get("chrom") or "").strip()
        and isinstance(entry.get("position"), int)
        and str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
        in {"acceptor", "donor"}
    ]
    base_routing_candidates = None
    if not _program_is_exploratory_steric(base) and isinstance(base.get("routing_candidate_sites"), list):
        base_routing_candidates = base.get("routing_candidate_sites")
    routing_candidate_labels: List[str] = []
    seen_routing_labels: Set[str] = set()
    for source in (
        base_routing_candidates,
        (
            ((structured_goal.get("splice_strategy_analysis") or {}).get("context_payload") or {}).get("steric_site_candidates")
            if isinstance((structured_goal.get("splice_strategy_analysis") or {}).get("context_payload"), dict)
            else None
        ),
        structured_goal.get("steric_site_candidates") if isinstance(structured_goal.get("steric_site_candidates"), list) else None,
    ):
        if not isinstance(source, list):
            continue
        for entry in source:
            if isinstance(entry, dict):
                label = str(
                    entry.get("canonical_label")
                    or entry.get("label")
                    or entry.get("site_label")
                    or entry.get("label_hint")
                    or ""
                ).strip()
            else:
                label = str(entry or "").strip()
            if not label or label in seen_routing_labels or label not in unique_site_labels:
                continue
            seen_routing_labels.add(label)
            routing_candidate_labels.append(label)
    for label in anchor_site_labels:
        if label in seen_routing_labels:
            continue
        if unique_site_labels and label not in unique_site_labels:
            continue
        seen_routing_labels.add(label)
        routing_candidate_labels.append(label)
    if not routing_candidate_labels:
        routing_candidate_labels = list(anchor_site_labels or unique_site_labels)
    if site_kind_values == {"acceptor"}:
        site_kind = "acceptor"
    elif site_kind_values == {"donor"}:
        site_kind = "donor"
    else:
        site_kind = "both"

    window_preview = ", ".join(
        summary.get("label_hint") or f"window_{idx:02d}"
        for idx, summary in enumerate(window_summaries[:3], start=1)
    )
    if len(window_summaries) > 3:
        window_preview = f"{window_preview} +{len(window_summaries) - 3} more"
    objective = base_objective or (
        f"Exploratory steric splice-modulation windows covering {window_preview or len(window_summaries)} regions"
    )
    note_bits = [
        "Derived exploratory steric windows from non-conserved splice-site anchors and local overlapping splice sites.",
        f"Source={source_name or 'splice_context'}.",
        f"Anchor_source={anchor_source or 'splice_context'}.",
        f"Window_count={len(window_summaries)}.",
        f"Anchor_sites={', '.join(anchor_site_labels)}." if anchor_site_labels else "",
        f"Candidate_sites={', '.join(unique_site_labels)}." if unique_site_labels else "",
    ]
    # A derived targeting window is still the same requested program. Start
    # from the audited program so derivation cannot erase explicit constraints
    # or semantics; overwrite only fields that this materialization computes.
    derived_program: Dict[str, Any] = deepcopy(base)
    derived_program.update(
        {
            "program_id": f"{base_program_id}_explore",
            "label": base_label,
            "modality": "steric",
            "intent": str(
                base.get("intent")
                or structured_goal.get("intent")
                or "splice_modulation"
            )
            .strip()
            .lower()
            or "splice_modulation",
            "objective": objective,
            "run_splice_eval": run_splice_eval,
            "run_splice_router": run_splice_router,
            "site_kind": site_kind,
            "site_context": "site_window",
            "targeting_policy": "exploratory_derived",
            "region_rows": aggregated_rows,
            "candidate_sites": unique_site_labels,
            "routing_candidate_sites": routing_candidate_labels,
            "anchor_sites": anchor_site_labels,
            "anchor_site_records": anchor_site_records,
            "window_summaries": window_summaries,
            "parent_program_id": str(base.get("program_id") or "").strip() or None,
            "selection_source": source_name or "splice_context",
            "notes": " ".join(bit for bit in note_bits if bit),
        }
    )
    for shared_key in (
        "region_constraints",
        "rbp_binding",
        "motif_tiling",
        "aso_overlap_requirement",
        "strand_mode",
        "target_level",
        "chemistry",
    ):
        shared_value = deepcopy(base.get(shared_key))
        if shared_value in (None, "", [], {}):
            shared_value = deepcopy(structured_goal.get(shared_key))
        if shared_value not in (None, "", [], {}):
            derived_program[shared_key] = shared_value
    if desired_effect:
        derived_program["desired_effect"] = desired_effect
    if isinstance(exon_label, int):
        derived_program["exon_label"] = int(exon_label)
    if focus_exons_only is not None:
        derived_program["focus_exons_only"] = bool(focus_exons_only)

    derivation_meta = {
        "source": source_name or "splice_context",
        "anchor_source": anchor_source or "splice_context",
        "window_count": len(merged_windows),
        "site_count": len(unique_site_labels),
        "site_labels": list(unique_site_labels),
        "anchor_site_count": len(anchor_site_labels),
        "anchor_site_labels": list(anchor_site_labels),
        "anchor_site_records": deepcopy(anchor_site_records),
        "up_bp": up_bp,
        "down_bp": down_bp,
        "parent_program_id": str(base.get("program_id") or "").strip() or None,
        "targeting_policy": "exploratory_derived",
    }
    explicit_bindings = []
    for entry in anchor_entries:
        binding = entry.get("explicit_target_route_binding")
        if isinstance(binding, dict) and binding not in explicit_bindings:
            explicit_bindings.append(deepcopy(binding))
    if explicit_bindings:
        derived_program["explicit_target_model_bindings"] = explicit_bindings
        derivation_meta["explicit_target_model_bindings"] = deepcopy(explicit_bindings)
    return [derived_program], derivation_meta


def _canonical_splice_anchor_signature(
    program: Optional[Dict[str, Any]],
) -> Tuple[Tuple[str, int, str, str], ...]:
    """Return the typed splice anchors actually selected for one design route."""

    if not isinstance(program, dict):
        return ()
    raw_records = (
        program.get("anchor_site_records")
        if isinstance(program.get("anchor_site_records"), list)
        else []
    )
    anchors: Set[Tuple[str, int, str, str]] = set()
    for record in raw_records:
        if not isinstance(record, dict):
            continue
        chrom = str(record.get("chrom") or "").strip().casefold()
        if chrom.startswith("chr"):
            chrom = chrom[3:]
        position = record.get("position")
        site_kind = (
            str(record.get("site_kind") or record.get("site") or "").strip().lower()
        )
        strand = str(record.get("strand") or "+").strip() or "+"
        if chrom and isinstance(position, int) and site_kind in {"acceptor", "donor"}:
            anchors.add((chrom, int(position), site_kind, strand))
    return tuple(sorted(anchors))


def _opposing_named_splice_route_collisions(
    structured_goal: Optional[Dict[str, Any]],
    programs: Any,
) -> List[Dict[str, Any]]:
    """Detect distinct opposing isoform routes collapsed onto identical anchors."""

    if not isinstance(structured_goal, dict) or not isinstance(programs, list):
        return []
    scoped_routes: List[Dict[str, Any]] = []
    for program in programs:
        if not isinstance(program, dict) or _program_modality(program) != "steric":
            continue
        direction = str(program.get("desired_delta") or "").strip().lower()
        abundance_directions = _program_isoform_abundance_directions(structured_goal, program)
        if len(abundance_directions) == 1:
            direction = next(iter(abundance_directions))
        identities = _program_isoform_identity_aliases(structured_goal, program)
        anchors = _canonical_splice_anchor_signature(program)
        if direction not in {"increase", "decrease"} or not identities or not anchors:
            continue
        scoped_routes.append(
            {
                "program_id": str(program.get("program_id") or "").strip(),
                "label": str(program.get("label") or "").strip(),
                "direction": direction,
                "identities": sorted(identities),
                "anchors": anchors,
            }
        )

    collisions: List[Dict[str, Any]] = []
    for left_index, left in enumerate(scoped_routes):
        for right in scoped_routes[left_index + 1 :]:
            if left["direction"] == right["direction"]:
                continue
            if set(left["identities"]).intersection(right["identities"]):
                continue
            if left["anchors"] != right["anchors"]:
                continue
            collisions.append(
                {
                    "left_program_id": left["program_id"],
                    "left_label": left["label"],
                    "left_direction": left["direction"],
                    "left_identities": left["identities"],
                    "right_program_id": right["program_id"],
                    "right_label": right["label"],
                    "right_direction": right["direction"],
                    "right_identities": right["identities"],
                    "anchors": [
                        {
                            "chrom": chrom,
                            "position": position,
                            "site_kind": site_kind,
                            "strand": strand,
                        }
                        for chrom, position, site_kind, strand in left["anchors"]
                    ],
                }
            )
    return collisions


def _slugify_job_id(value: Any, prefix: str) -> str:
    slug = re.sub(r"[^A-Za-z0-9]+", "_", str(value or "").strip()).strip("_").lower()
    if not slug:
        slug = prefix
    if not slug.startswith(prefix):
        slug = f"{prefix}_{slug}"
    return slug[:96]


def _normalize_region_rows(rows: Any) -> List[List[Any]]:
    normalized: List[List[Any]] = []
    if not isinstance(rows, list):
        return normalized
    for idx, row in enumerate(rows, start=1):
        if not isinstance(row, list) or len(row) < 3:
            continue
        try:
            start0 = int(row[1])
            end = int(row[2])
        except Exception:
            continue
        if end <= start0:
            continue
        chrom = str(row[0]) if row[0] is not None else ""
        label = str(row[3]) if len(row) > 3 and row[3] is not None else f"region_{idx}"
        score = row[4] if len(row) > 4 else 0
        strand = row[5] if len(row) > 5 else "+"
        normalized.append([chrom, start0, end, label, score, strand])
    return normalized


def _sanitize_region_rows_for_tiling(
    rows: Any,
    *,
    prefix: str,
    label_override: str = "",
) -> List[List[Any]]:
    sanitized: List[List[Any]] = []
    normalized_rows = _normalize_region_rows(rows)
    for idx, row in enumerate(normalized_rows, start=1):
        row_copy = list(row[:6])
        raw_label = label_override or str(row_copy[3] or f"{prefix}_{idx}")
        row_copy[3] = _slugify_job_id(raw_label, prefix)
        sanitized.append(row_copy)
    return sanitized


def _region_row_identity(row: List[Any]) -> Tuple[str, int, int, str]:
    normalized = _normalize_region_rows([row])
    if not normalized:
        return ("", 0, 0, "+")
    first = normalized[0]
    strand = str(first[5] or "+").strip() if len(first) > 5 else "+"
    if strand not in {"+", "-"}:
        strand = "+"
    return (
        str(first[0] or "").strip(),
        int(first[1]),
        int(first[2]),
        strand,
    )


def _region_rows_signature(rows: Any) -> Tuple[Tuple[str, int, int, str], ...]:
    identities = {_region_row_identity(row) for row in _normalize_region_rows(rows)}
    identities.discard(("", 0, 0, "+"))
    return tuple(sorted(identities))


def _dedupe_region_rows(rows: Any) -> List[List[Any]]:
    deduped: List[List[Any]] = []
    seen: Set[Tuple[str, int, int, str]] = set()
    for row in _normalize_region_rows(rows):
        identity = _region_row_identity(row)
        if identity in seen:
            continue
        seen.add(identity)
        deduped.append(row)
    return deduped


def _apply_shared_region_constraints(
    *,
    runtime: Any,
    structured_goal: Dict[str, Any],
    base_rows: Any,
    output_space: str,
    program: Optional[Dict[str, Any]] = None,
    base_overlap_requirement: str = "",
) -> Tuple[List[List[Any]], Dict[str, Any]]:
    normalized_rows = _normalize_region_rows(base_rows)
    from .mature_steric import uses_mature_rna, compile_regions
    if output_space == 'genomic' and uses_mature_rna(program):
        return compile_regions(runtime, structured_goal, program, normalized_rows)
    apply_constraints = getattr(runtime, "_apply_region_constraints_to_rows", None)
    if not callable(apply_constraints):
        return normalized_rows, {}
    constrained_rows, constraint_meta = apply_constraints(
        structured_goal,
        normalized_rows,
        output_space=output_space,
        program=program,
    )
    if not isinstance(constrained_rows, list):
        constrained_rows = normalized_rows
    if not isinstance(constraint_meta, dict):
        constraint_meta = {}
    # A program's reference feature and its nominated binding sites have
    # independent predicates. For example, an ASO can overlap a short site
    # while still having to fit completely inside an annotated UTR. Keep
    # that base predicate when a pooled result is filtered back to this job;
    # replacing the site's overlap rule would instead overconstrain it.
    filters = constraint_meta.get("tile_constraint_filters")
    if normalized_rows and filters and base_overlap_requirement in {
        "any_overlap", "full_containment", "contains_feature"
    }:
        base_filter = {
            "rows": deepcopy(normalized_rows),
            "operator": "intersect",
            "aso_overlap_requirement": base_overlap_requirement,
            "minimum_overlap_bp": 1,
        }
        constraint_meta = deepcopy(constraint_meta)
        constraint_meta["base_region_filter"] = base_filter
        constraint_meta["tile_constraint_filters"].append(deepcopy(base_filter))
    return _dedupe_region_rows(constrained_rows), constraint_meta


def _materialized_exon_entry_is_empty(entry: Any) -> bool:
    if not isinstance(entry, dict):
        return False
    if str(entry.get("source_type") or "").strip() != "exon":
        return False
    return not (
        _normalize_region_rows(entry.get("materialized_rows"))
        or _normalize_region_rows(entry.get("materialized_cdna_rows"))
    )


def _refresh_empty_exon_region_constraints(
    *,
    runtime: Any,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    run_dir: str,
    isoform_transcripts: Optional[Dict[str, Dict[str, Any]]] = None,
    iso_label_primary: Optional[str] = None,
) -> bool:
    """Refresh stale exon constraints after transcript structures become available."""
    if not isinstance(structured_goal, dict):
        return False
    materialized = structured_goal.get("materialized_region_constraints")
    if not isinstance(materialized, dict):
        return False
    materialize_entry = getattr(runtime, "_materialize_region_constraint_entry", None)
    if not callable(materialize_entry):
        return False

    isoforms = isoform_transcripts if isinstance(isoform_transcripts, dict) else structured_goal.get("isoform_transcripts")
    if not isinstance(isoforms, dict) or not isoforms:
        return False
    if not iso_label_primary:
        select_primary = getattr(runtime, "_select_constraint_primary_isoform", None)
        if callable(select_primary):
            try:
                iso_label_primary, isoforms = select_primary(structured_goal, isoforms)
            except Exception:
                iso_label_primary = next(iter(isoforms.keys()), None)
        else:
            iso_label_primary = next(iter(isoforms.keys()), None)

    changed = False

    def _refresh_entries(entries: Any) -> Any:
        nonlocal changed
        if not isinstance(entries, list):
            return entries
        refreshed_entries: List[Any] = []
        for entry in entries:
            if not _materialized_exon_entry_is_empty(entry):
                refreshed_entries.append(entry)
                continue
            try:
                refreshed = materialize_entry(
                    structured_goal=structured_goal,
                    final_payload=final_payload,
                    run_dir=run_dir,
                    constraint=entry,
                    isoform_transcripts=isoforms,
                    iso_label_primary=iso_label_primary,
                )
            except Exception:
                refreshed = entry
            if (
                isinstance(refreshed, dict)
                and (
                    _normalize_region_rows(refreshed.get("materialized_rows"))
                    or _normalize_region_rows(refreshed.get("materialized_cdna_rows"))
                )
            ):
                refreshed_entries.append(refreshed)
                changed = True
            else:
                refreshed_entries.append(entry)
        return refreshed_entries

    materialized["global"] = _refresh_entries(materialized.get("global"))
    by_program = materialized.get("by_program")
    if isinstance(by_program, dict):
        for program_id, entries in list(by_program.items()):
            by_program[program_id] = _refresh_entries(entries)

    if changed:
        structured_goal["materialized_region_constraints"] = materialized
        final_payload["materialized_region_constraints"] = deepcopy(materialized)
    return changed


def _propagate_materialized_constraints_to_derived_programs(
    *,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    programs: List[Dict[str, Any]],
) -> None:
    if not isinstance(programs, list):
        return
    for scope in (structured_goal, final_payload):
        if not isinstance(scope, dict):
            continue
        materialized = scope.get("materialized_region_constraints")
        if not isinstance(materialized, dict):
            continue
        by_program = materialized.get("by_program")
        if not isinstance(by_program, dict):
            continue
        for program in programs:
            if not isinstance(program, dict):
                continue
            program_id = str(program.get("program_id") or "").strip()
            parent_program_id = str(program.get("parent_program_id") or "").strip()
            if not program_id or not parent_program_id or program_id == parent_program_id:
                continue
            if isinstance(by_program.get(program_id), list):
                continue
            inherited_entries = by_program.get(parent_program_id)
            if isinstance(inherited_entries, list) and inherited_entries:
                by_program[program_id] = deepcopy(inherited_entries)


def _collapse_redundant_steric_jobs(jobs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(jobs, list) or len(jobs) <= 1:
        return jobs

    # Reuse an exploratory job only when it is another materialization of the
    # same requested program. Identical genomic windows do not make distinct
    # requested programs semantically interchangeable.
    collapsible_policies = {"exploratory_derived"}
    grouped: Dict[Tuple[Tuple[str, int, int, str], ...], List[Dict[str, Any]]] = {}
    for job in jobs:
        if not isinstance(job, dict):
            continue
        targeting_policy = _normalize_steric_targeting_policy(
            job.get("targeting_policy") or job.get("steric_targeting_policy")
        )
        if targeting_policy not in collapsible_policies:
            continue
        signature = _region_rows_signature(job.get("region_rows"))
        if signature:
            grouped.setdefault(signature, []).append(job)

    collapsed_groups: Dict[Tuple[Tuple[str, int, int, str], ...], List[Dict[str, Any]]] = {}
    for signature, group in grouped.items():
        if len(group) <= 1:
            collapsed_groups[signature] = group
            continue
        policies = {
            _normalize_steric_targeting_policy(item.get("targeting_policy") or item.get("steric_targeting_policy"))
            for item in group
        }
        if len(policies) != 1:
            collapsed_groups[signature] = group
            continue
        targeting_policy = next(iter(policies))
        splice_eval_flags = {_coerce_bool(item.get("run_splice_eval")) for item in group}
        splice_router_flags = {_coerce_bool(item.get("run_splice_router")) for item in group}
        intents = {str(item.get("intent") or "").strip().lower() for item in group}
        target_regions = {_normalize_target_region(item.get("target_region")) for item in group}
        requested_lengths = {_coerce_positive_int(item.get("length")) for item in group}
        full_copy_flags = {bool(item.get("allow_full_copy")) for item in group}
        parent_program_ids = {
            str(item.get("parent_program_id") or "").strip()
            for item in group
            if str(item.get("parent_program_id") or "").strip()
        }
        inferred_site_kinds = {
            _infer_design_program_site_kind(item)
            for item in group
            if _infer_design_program_site_kind(item) in {"acceptor", "donor"}
        }
        if (
            len(splice_eval_flags) > 1
            or len(splice_router_flags) > 1
            or len(intents) > 1
            or len(target_regions) > 1
            or len(requested_lengths) > 1
            or len(full_copy_flags) > 1
            or len(parent_program_ids) > 1
            or len(inferred_site_kinds) > 1
        ):
            collapsed_groups[signature] = group
            continue

        preferred = sorted(
            group,
            key=lambda item: (
                0 if not _infer_design_program_site_kind(item) else 1,
                0 if not str(item.get("site_context") or "").strip() else 1,
                len(str(item.get("label") or item.get("objective") or item.get("program_id") or "")),
            ),
        )[0]
        merged = deepcopy(preferred)
        merged["region_rows"] = _dedupe_region_rows(preferred.get("region_rows"))

        site_kinds = {
            _infer_design_program_site_kind(item)
            for item in group
            if _infer_design_program_site_kind(item)
        }
        if len(site_kinds) > 1:
            merged["site_kind"] = "both"
        elif len(site_kinds) == 1:
            merged["site_kind"] = next(iter(site_kinds))

        site_contexts = {
            _normalize_design_program_site_context(item.get("site_context"))
            for item in group
            if _normalize_design_program_site_context(item.get("site_context"))
        }
        if len(site_contexts) > 1:
            merged.pop("site_context", None)
        elif len(site_contexts) == 1:
            merged["site_context"] = next(iter(site_contexts))

        merged_labels = list(
            dict.fromkeys(
                str(item.get("label") or item.get("objective") or item.get("program_id") or "").strip()
                for item in group
                if str(item.get("label") or item.get("objective") or item.get("program_id") or "").strip()
            )
        )
        merged_objectives = list(
            dict.fromkeys(
                str(item.get("objective") or item.get("label") or item.get("program_id") or "").strip()
                for item in group
                if str(item.get("objective") or item.get("label") or item.get("program_id") or "").strip()
            )
        )
        merged_candidate_sites = list(
            dict.fromkeys(
                str(label).strip()
                for item in group
                for label in (item.get("candidate_sites") if isinstance(item.get("candidate_sites"), list) else [])
                if str(label).strip()
            )
        )
        merged_routing_candidate_sites = list(
            dict.fromkeys(
                str(label).strip()
                for item in group
                for label in (
                    item.get("routing_candidate_sites")
                    if isinstance(item.get("routing_candidate_sites"), list)
                    else []
                )
                if str(label).strip()
            )
        )
        merged_window_summaries: List[Dict[str, Any]] = []
        seen_window_keys: Set[Tuple[Any, ...]] = set()
        for item in group:
            window_summaries = item.get("window_summaries") if isinstance(item.get("window_summaries"), list) else []
            for summary in window_summaries:
                if not isinstance(summary, dict):
                    continue
                window_key = (
                    str(summary.get("chrom") or "").strip(),
                    int(summary.get("start") or 0),
                    int(summary.get("end") or 0),
                    str(summary.get("strand") or "").strip(),
                    tuple(
                        str(label).strip()
                        for label in (summary.get("site_labels") if isinstance(summary.get("site_labels"), list) else [])
                        if str(label).strip()
                    ),
                )
                if window_key in seen_window_keys:
                    continue
                seen_window_keys.add(window_key)
                merged_window_summaries.append(dict(summary))
        if merged_candidate_sites:
            merged["candidate_sites"] = merged_candidate_sites
        if merged_routing_candidate_sites:
            merged["routing_candidate_sites"] = merged_routing_candidate_sites
        if merged_window_summaries:
            merged["window_summaries"] = merged_window_summaries
        if len(group) > 1:
            merged["merged_labels"] = merged_labels
            merged["merged_objectives"] = merged_objectives
        if targeting_policy == "exploratory_derived" and len(group) > 1:
            collapse_suffix = hashlib.sha256(repr(signature).encode("utf-8")).hexdigest()[:10]
            merged["job_id"] = f"shared_exploratory_{collapse_suffix}"
            merged["program_id"] = f"shared_exploratory_{collapse_suffix}"
            merged["label"] = "Shared exploratory steric windows"
            merged["objective"] = (
                "Shared exploratory steric windows reused across multiple splice objectives."
            )

        selection_meta = merged.get("selection_meta") if isinstance(merged.get("selection_meta"), dict) else {}
        selection_meta = dict(selection_meta)
        selection_meta["collapse_reason"] = f"identical_{targeting_policy}_region_rows"
        selection_meta["collapsed_job_ids"] = [
            str(item.get("job_id") or "").strip()
            for item in group
            if str(item.get("job_id") or "").strip()
        ]
        selection_meta["collapsed_program_ids"] = [
            str(item.get("program_id") or "").strip()
            for item in group
            if str(item.get("program_id") or "").strip()
        ]
        selection_meta["collapsed_labels"] = [
            str(item.get("label") or item.get("objective") or item.get("program_id") or "").strip()
            for item in group
            if str(item.get("label") or item.get("objective") or item.get("program_id") or "").strip()
        ]
        selection_meta["collapsed_targeting_policy"] = targeting_policy
        selection_meta["collapsed_count"] = len(group)
        merged["selection_meta"] = selection_meta
        collapsed_groups[signature] = [merged]

    collapsed: List[Dict[str, Any]] = []
    emitted_signatures: Set[Tuple[Tuple[str, int, int, str], ...]] = set()
    for job in jobs:
        if not isinstance(job, dict):
            continue
        targeting_policy = _normalize_steric_targeting_policy(
            job.get("targeting_policy") or job.get("steric_targeting_policy")
        )
        signature = _region_rows_signature(job.get("region_rows"))
        if targeting_policy not in collapsible_policies or not signature or signature not in collapsed_groups:
            collapsed.append(job)
            continue
        if signature in emitted_signatures:
            continue
        collapsed.extend(collapsed_groups.get(signature) or [])
        emitted_signatures.add(signature)
    return collapsed


def _derive_design_jobs(
    *,
    rows: Any,
    modality: str,
    run_dir: str,
    allow_empty: bool = False,
    empty_label: str = "all_targets",
) -> List[Dict[str, Any]]:
    normalized_rows = _normalize_region_rows(rows)
    grouped: Dict[str, List[List[Any]]] = {}
    label_order: List[str] = []
    for idx, row in enumerate(normalized_rows, start=1):
        label = str(row[3] or f"{modality}_target_{idx}")
        if label not in grouped:
            grouped[label] = []
            label_order.append(label)
        grouped[label].append(row)

    jobs: List[Dict[str, Any]] = []
    for idx, label in enumerate(label_order, start=1):
        job_id = _slugify_job_id(f"{modality}_{idx:02d}_{label}", f"{modality}_job")
        jobs.append(
            {
                "job_id": job_id,
                "label": label,
                "modality": modality,
                "region_rows": grouped[label],
                "region_count": len(grouped[label]),
                "output_dir": str(_write_run_path(run_dir, f"{modality}_jobs", job_id)),
            }
        )
    if not jobs and allow_empty:
        job_id = _slugify_job_id(f"{modality}_{empty_label}", f"{modality}_job")
        jobs.append(
            {
                "job_id": job_id,
                "label": empty_label,
                "modality": modality,
                "region_rows": [],
                "region_count": 0,
                "output_dir": str(_write_run_path(run_dir, f"{modality}_jobs", job_id)),
            }
        )
    return jobs


def _normalize_design_job_override(
    *,
    job: Dict[str, Any],
    modality: str,
    run_dir: str,
    ordinal: int,
) -> Optional[Dict[str, Any]]:
    if not isinstance(job, dict):
        return None
    label = str(job.get("label") or job.get("objective") or job.get("program_id") or f"{modality}_target_{ordinal}").strip()
    if not label:
        label = f"{modality}_target_{ordinal}"
    job_id_seed = job.get("job_id") or job.get("program_id") or label
    job_id = _slugify_job_id(job_id_seed, f"{modality}_job")
    output_dir = str(job.get("output_dir") or "").strip() or str(_write_run_path(run_dir, f"{modality}_jobs", job_id))
    region_rows = _normalize_region_rows(job.get("region_rows"))
    tile_filter_rows = _normalize_region_rows(job.get("tile_filter_rows"))
    if not tile_filter_rows and region_rows:
        tile_filter_rows = list(region_rows)
    normalized = dict(job)
    normalized["job_id"] = job_id
    normalized["label"] = label
    normalized["modality"] = modality
    normalized["output_dir"] = output_dir
    normalized["region_rows"] = region_rows
    normalized["region_count"] = len(region_rows)
    normalized["tile_filter_rows"] = tile_filter_rows
    normalized["tile_overlap_requirement"] = str(job.get("tile_overlap_requirement") or "").strip().lower() or "any_overlap"
    skip_reason = _design_job_skip_reason(normalized)
    if skip_reason:
        normalized["status"] = "skipped"
        normalized["reason"] = skip_reason
        normalized["skipped"] = True
    else:
        normalized.pop("skipped", None)
    return normalized


def _ensure_design_jobs_metadata(
    *,
    run_dir: str,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    modality: str,
    rows: Any,
    jobs_override: Optional[List[Dict[str, Any]]] = None,
    allow_empty: bool = False,
    empty_label: str = "all_targets",
) -> List[Dict[str, Any]]:
    jobs: List[Dict[str, Any]] = []
    if isinstance(jobs_override, list) and jobs_override:
        for ordinal, job in enumerate(jobs_override, start=1):
            normalized = _normalize_design_job_override(
                job=job,
                modality=modality,
                run_dir=run_dir,
                ordinal=ordinal,
            )
            if isinstance(normalized, dict):
                jobs.append(normalized)
    if not jobs:
        jobs = _derive_design_jobs(
            rows=rows,
            modality=modality,
            run_dir=run_dir,
            allow_empty=allow_empty,
            empty_label=empty_label,
        )
    jobs_key = _design_jobs_key(modality)
    final_payload[jobs_key] = jobs
    if isinstance(structured_goal, dict):
        structured_goal[jobs_key] = jobs
    return jobs


def _get_design_jobs(final_payload: Dict[str, Any], modality: str) -> List[Dict[str, Any]]:
    jobs = final_payload.get(_design_jobs_key(modality))
    if not isinstance(jobs, list):
        return []
    return [job for job in jobs if isinstance(job, dict) and str(job.get("job_id") or "").strip()]


def _active_design_jobs(final_payload: Dict[str, Any], modality: str) -> List[Dict[str, Any]]:
    return [job for job in _get_design_jobs(final_payload, modality) if not _design_job_is_skipped(job)]


def _mark_unresolved_splice_switch_gapmer_jobs_skipped(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Skip stale synthetic gapmer jobs whose target isoform is no longer resolved."""
    if not isinstance(structured_goal, dict) or not isinstance(final_payload, dict):
        return {"skipped_job_count": 0, "skipped_isoforms": []}
    jobs = final_payload.get(_design_jobs_key("gapmer"))
    if not isinstance(jobs, list) or not jobs:
        return {"skipped_job_count": 0, "skipped_isoforms": []}
    statuses, has_resolution_context = _isoform_resolution_status_by_label(structured_goal)
    if not has_resolution_context:
        return {"skipped_job_count": 0, "skipped_isoforms": []}

    support_plan = (
        structured_goal.get("splice_switch_gapmer_plan")
        if isinstance(structured_goal.get("splice_switch_gapmer_plan"), dict)
        else {}
    )
    omitted_labels = {
        str(item.get("isoform_label") or "").strip()
        for item in support_plan.get("omitted_target_isoforms") or []
        if isinstance(item, dict) and str(item.get("isoform_label") or "").strip()
    }
    skipped_count = 0
    skipped_isoforms: List[str] = []
    for job in jobs:
        if not isinstance(job, dict):
            continue
        selection_meta = job.get("selection_meta") if isinstance(job.get("selection_meta"), dict) else {}
        isoform_label = str(
            selection_meta.get("isoform_label") or job.get("isoform_label") or ""
        ).strip()
        uniqueness_mode = str(selection_meta.get("gapmer_uniqueness_mode") or "").strip().lower()
        target_role = str(selection_meta.get("gapmer_target_role") or "").strip().lower()
        synthetic_support_job = uniqueness_mode == "pathogenic_preferred" and target_role in {"", "pathogenic"}
        status = statuses.get(isoform_label, "unknown")
        if not synthetic_support_job:
            continue
        if isoform_label not in omitted_labels and status not in {"skipped", "unresolved", "pending"}:
            continue
        reason = f"Skipped splice-switching support branch because isoform '{isoform_label}' is {status}."
        job["status"] = "skipped"
        job["skipped"] = True
        job["reason"] = reason
        skipped_count += 1
        if isoform_label:
            skipped_isoforms.append(isoform_label)
    if skipped_count:
        structured_goal[_design_jobs_key("gapmer")] = jobs
        final_payload[_design_jobs_key("gapmer")] = jobs
    return {
        "skipped_job_count": skipped_count,
        "skipped_isoforms": list(dict.fromkeys(skipped_isoforms)),
    }


def _design_job_skip_reason(job: Optional[Dict[str, Any]]) -> str:
    if not isinstance(job, dict):
        return ""
    explicit_status = str(job.get("status") or "").strip().lower()
    explicit_reason = str(job.get("reason") or "").strip()
    if explicit_status == "skipped" and explicit_reason:
        return explicit_reason

    region_rows = _normalize_region_rows(job.get("region_rows"))
    if region_rows or bool(job.get("allow_full_copy")):
        return ""

    selection_meta = job.get("selection_meta") if isinstance(job.get("selection_meta"), dict) else {}
    region_constraints = (
        selection_meta.get("region_constraints")
        if isinstance(selection_meta.get("region_constraints"), dict)
        else {}
    )
    applied_constraints = (
        region_constraints.get("applied_constraints")
        if isinstance(region_constraints.get("applied_constraints"), list)
        else []
    )
    constraint_exhausted = bool(selection_meta.get("constraint_exhausted"))
    try:
        constraint_count = int(region_constraints.get("constraint_count") or 0)
    except Exception:
        constraint_count = 0

    if constraint_exhausted or constraint_count > 0:
        detail_parts: List[str] = []

        def _coerce_optional_int(value: Any) -> Optional[int]:
            if value in (None, ""):
                return None
            try:
                return int(value)
            except Exception:
                return None

        base_row_count = _coerce_optional_int(region_constraints.get("base_row_count"))
        constrained_row_count = _coerce_optional_int(region_constraints.get("constrained_row_count"))
        if base_row_count is not None or constrained_row_count is not None:
            start_count = base_row_count if base_row_count is not None else "unknown"
            end_count = constrained_row_count if constrained_row_count is not None else 0
            detail_parts.append(f"Constraint collapse: {start_count} starting region(s) to {end_count}.")

        constraint_summaries: List[str] = []
        for constraint in applied_constraints[:4]:
            if not isinstance(constraint, dict):
                continue
            label = str(constraint.get("label") or constraint.get("constraint_id") or "constraint").strip()
            if not label:
                label = "constraint"
            try:
                candidate_row_count = int(constraint.get("candidate_row_count") or 0)
            except Exception:
                candidate_row_count = 0
            try:
                source_row_count = int(constraint.get("source_row_count") or 0)
            except Exception:
                source_row_count = 0
            constraint_summaries.append(
                f"{label}: {candidate_row_count} candidate region(s) from {source_row_count} source row(s)"
            )
        if constraint_summaries:
            detail_parts.append("Constraint results: " + "; ".join(constraint_summaries) + ".")

        reason = "Requested region constraints left no targetable regions for this job."
        if detail_parts:
            return reason + " " + " ".join(detail_parts)
        return reason

    return "No targetable regions were derived for this job."


def _design_job_empty_reason_code(job: Optional[Dict[str, Any]]) -> str:
    """Classify why an empty design job cannot execute."""
    if not isinstance(job, dict):
        return "planning_missing"
    explicit = str(job.get("empty_reason_code") or job.get("skip_code") or "").strip().lower()
    if explicit:
        return explicit
    selection_meta = job.get("selection_meta") if isinstance(job.get("selection_meta"), dict) else {}
    region_constraints = (
        selection_meta.get("region_constraints")
        if isinstance(selection_meta.get("region_constraints"), dict)
        else {}
    )
    try:
        constraint_count = int(region_constraints.get("constraint_count") or 0)
    except Exception:
        constraint_count = 0
    if bool(selection_meta.get("constraint_exhausted")) or constraint_count > 0:
        return "constraints_exhausted"
    reason = str(job.get("reason") or "").strip().lower()
    if "user" in reason and any(token in reason for token in ("skip", "omit", "declin")):
        return "user_skipped"
    if not selection_meta and not str(job.get("program_id") or "").strip():
        return "planning_missing"
    return "region_build_failed"


def _design_job_is_skipped(
    job: Optional[Dict[str, Any]],
    job_result: Optional[Dict[str, Any]] = None,
) -> bool:
    for source in (job_result, job):
        if not isinstance(source, dict):
            continue
        status = str(source.get("status") or "").strip().lower()
        if status == "skipped":
            return True
        skipped = _coerce_bool(source.get("skipped"))
        if skipped is True:
            return True
    return bool(_design_job_skip_reason(job))


def _design_request_requires_splice_eval(
    request_meta: Optional[Dict[str, Any]],
    *,
    fallback_goal: Optional[Dict[str, Any]] = None,
) -> bool:
    if isinstance(request_meta, dict):
        intent = str(request_meta.get("intent") or (fallback_goal or {}).get("intent") or "").strip().lower()
        target_region = _normalize_target_region(request_meta.get("target_region") or (fallback_goal or {}).get("target_region"))
        if intent == "binding" and target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
            return False
        explicit = _coerce_bool(request_meta.get("run_splice_eval"))
        if explicit is not None:
            return explicit
        has_program_signal = any(
            request_meta.get(key) not in (None, "", [])
            for key in ("program_id", "intent", "target_region", "site_kind", "site_context")
        )
        if has_program_signal:
            if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
                return False
            if _has_splice_objective_signal(request_meta) or _has_splice_objective_signal(fallback_goal):
                return True
            return intent in {"splice_modulation", "knockdown"}
    if not isinstance(fallback_goal, dict):
        return False
    explicit_goal = _coerce_bool(fallback_goal.get("run_splice_eval"))
    if explicit_goal is not None:
        return explicit_goal
    target_region = _normalize_target_region(fallback_goal.get("target_region"))
    if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False
    if _has_splice_objective_signal(fallback_goal):
        return True
    intent = str(fallback_goal.get("intent") or "").strip().lower()
    return intent in {"splice_modulation", "knockdown"}


def _design_request_requires_splice_router(
    request_meta: Optional[Dict[str, Any]],
    *,
    fallback_goal: Optional[Dict[str, Any]] = None,
) -> bool:
    if isinstance(request_meta, dict):
        intent = str(request_meta.get("intent") or (fallback_goal or {}).get("intent") or "").strip().lower()
        target_region = _normalize_target_region(request_meta.get("target_region") or (fallback_goal or {}).get("target_region"))
        if intent == "binding" and target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
            return False
        explicit = _coerce_bool(request_meta.get("run_splice_router"))
        if explicit is not None:
            return explicit
        has_program_signal = any(
            request_meta.get(key) not in (None, "", [])
            for key in ("program_id", "intent", "target_region", "site_kind", "site_context")
        )
        if has_program_signal:
            if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
                return False
            if _has_splice_objective_signal(request_meta) or _has_splice_objective_signal(fallback_goal):
                return True
            return intent == "splice_modulation"
    if not isinstance(fallback_goal, dict):
        return False
    explicit_goal = _coerce_bool(fallback_goal.get("run_splice_router"))
    if explicit_goal is not None:
        return explicit_goal
    target_region = _normalize_target_region(fallback_goal.get("target_region"))
    if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False
    if _has_splice_objective_signal(fallback_goal):
        return True
    intent = str(fallback_goal.get("intent") or "").strip().lower()
    return intent == "splice_modulation"


def _design_request_requires_steric_uniqueness(
    request_meta: Optional[Dict[str, Any]],
    *,
    fallback_goal: Optional[Dict[str, Any]] = None,
) -> bool:
    explicit_keys = (
        "run_steric_uniqueness",
        "run_uniqueness_scoring",
        "export_uniqueness_csv",
    )
    if isinstance(request_meta, dict):
        for key in explicit_keys:
            explicit = _coerce_bool(request_meta.get(key))
            if explicit is not None:
                return explicit
        if _design_request_requires_splice_eval(request_meta, fallback_goal=fallback_goal):
            return False
        has_program_signal = any(
            request_meta.get(key) not in (None, "", [])
            for key in ("program_id", "intent", "target_region", "site_kind", "site_context")
        )
        if has_program_signal:
            return True
    if not isinstance(fallback_goal, dict):
        return False
    for key in explicit_keys:
        explicit_goal = _coerce_bool(fallback_goal.get(key))
        if explicit_goal is not None:
            return explicit_goal
    return not _design_request_requires_splice_eval(None, fallback_goal=fallback_goal)


def _steric_jobs_requiring_uniqueness(
    final_payload: Dict[str, Any],
    structured_goal: Optional[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    jobs = _get_design_jobs(final_payload, "steric")
    fallback_goal = structured_goal if isinstance(structured_goal, dict) else {}
    return [
        job
        for job in jobs
        if not _design_job_is_skipped(job)
        if _design_request_requires_steric_uniqueness(job, fallback_goal=fallback_goal)
    ]


def _steric_jobs_requiring_splice_eval(
    final_payload: Dict[str, Any],
    structured_goal: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    return [
        job
        for job in _get_design_jobs(final_payload, "steric")
        if not _design_job_is_skipped(job)
        if _design_request_requires_splice_eval(job, fallback_goal=structured_goal)
    ]


def _steric_jobs_requiring_splice_router(
    final_payload: Dict[str, Any],
    structured_goal: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    return [
        job
        for job in _get_design_jobs(final_payload, "steric")
        if not _design_job_is_skipped(job)
        if _design_request_requires_splice_router(job, fallback_goal=structured_goal)
    ]


def _ensure_design_results_map(
    *,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    modality: str,
) -> Dict[str, Dict[str, Any]]:
    results_key = _design_results_key(modality)
    results = final_payload.get(results_key)
    if not isinstance(results, dict):
        results = {}
        final_payload[results_key] = results
    if isinstance(structured_goal, dict):
        structured_goal[results_key] = results
    for key, value in list(results.items()):
        if not isinstance(value, dict):
            results[key] = {"raw": value}
    return results


def _tile_row_intervals(row: Dict[str, Any]) -> List[Tuple[str, int, int]]:
    intervals: List[Tuple[str, int, int]] = []

    def _append_interval(chrom_value: Any, start_value: Any, end_value: Any, *, one_based: bool = True) -> None:
        if chrom_value in (None, "") or start_value is None or end_value is None:
            return
        try:
            start_bp = int(start_value)
            end_bp = int(end_value)
        except Exception:
            return
        chrom_text = str(chrom_value)
        start0 = max(0, start_bp - int(one_based))
        if end_bp <= start0:
            return
        intervals.append((chrom_text, start0, end_bp))
        if chrom_text.startswith("chr"):
            alt = chrom_text[3:]
        else:
            alt = f"chr{chrom_text}"
        intervals.append((alt, start0, end_bp))

    _append_interval(
        row.get("Chrom") if row.get("Chrom") is not None else row.get("chrom"),
        row.get("Start") if row.get("Start") is not None else row.get("start"),
        row.get("End") if row.get("End") is not None else row.get("end"),
        one_based=(row.get("coordinate_system") == "1based_inclusive" or row.get("source") in {"gapmer_cdna", "junction_gapmer"}),
    )
    _append_interval(row.get("Genomic_chrom"), row.get("Genomic_start"), row.get("Genomic_end"))
    _append_interval(row.get("Genomic_chrom_2"), row.get("Genomic_start_2"), row.get("Genomic_end_2"))

    segments_raw = row.get("Genomic_segments")
    if isinstance(segments_raw, str) and segments_raw.strip():
        try:
            segments = json.loads(segments_raw)
        except Exception:
            segments = []
        if isinstance(segments, list):
            for segment in segments:
                if not isinstance(segment, dict):
                    continue
                _append_interval(segment.get("chrom"), segment.get("start"), segment.get("end"))
    return intervals


def _region_index_with_aliases(rows: List[List[Any]]) -> Dict[str, List[Tuple[int, int]]]:
    regions: Dict[str, List[Tuple[int, int]]] = {}
    for row in _normalize_region_rows(rows):
        chrom = str(row[0]) if row[0] is not None else ""
        if not chrom:
            continue
        start0 = int(row[1])
        end = int(row[2])
        regions.setdefault(chrom, []).append((start0, end))
        if chrom.startswith("chr"):
            alt = chrom[3:]
        else:
            alt = f"chr{chrom}"
        regions.setdefault(alt, []).append((start0, end))
    return regions


def _tile_row_dedupe_key(row: Dict[str, Any]) -> str:
    sequence = str(
        row.get("Sequence")
        or row.get("sequence")
        or row.get("ASO_sequence")
        or row.get("Seq")
        or ""
    ).strip().upper()
    strand = str(row.get("Strand") or row.get("strand") or "").strip()
    intervals = sorted({(chrom, start0, end0) for chrom, start0, end0 in _tile_row_intervals(row)})
    if sequence or intervals:
        return json.dumps(
            {
                "sequence": sequence,
                "strand": strand,
                "intervals": intervals,
            },
            sort_keys=True,
            ensure_ascii=False,
        )
    try:
        return json.dumps(row, sort_keys=True, default=str, ensure_ascii=False)
    except Exception:
        return str(row)


def _dedupe_tile_rows(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    deduped: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for row in rows:
        if not isinstance(row, dict):
            continue
        dedupe_key = _tile_row_dedupe_key(row)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        deduped.append(row)
    return deduped


def _filter_tiles_json_to_output(
    *,
    source_json_path: str,
    region_rows: List[List[Any]],
    output_path: str,
    allow_full_copy: bool = False,
    tile_overlap_requirement: str = "any_overlap",
    chemistry_group_id: str = "",
    allow_empty_subset: bool = False,
    constraint_filters: Optional[List[Dict[str, Any]]] = None,
    mature_binding_scope: Optional[Dict[str, Any]] = None,
    structured_goal: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    from .region_overlap import candidate_matches_regions, matches_constraint_filters
    source_path = Path(source_json_path).expanduser()
    output_obj = Path(output_path).expanduser()
    if not source_path.exists():
        return {"error": f"source_tiles_missing: {source_path}"}
    output_obj.parent.mkdir(parents=True, exist_ok=True)
    binding = None
    if mature_binding_scope:
        from .mature_binding import BindingContext
        binding = BindingContext(_goal_runtime_module(), structured_goal or {}, mature_binding_scope)
    if not region_rows:
        if binding:
            return {'error': 'mature_binding_search_rows_missing'}
        if not allow_full_copy:
            return {"error": "region_rows_missing"}
        try:
            payload = json.loads(source_path.read_text(encoding="utf-8"))
        except Exception as exc:
            return {"error": f"tiles_json_read_failed: {exc}"}
        rows = payload.get("rows") if isinstance(payload, dict) and isinstance(payload.get("rows"), list) else []
        payload["rows"] = _dedupe_tile_rows(rows)
        output_obj.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        return {"path": str(output_obj), "row_count": len(payload["rows"]), "copied": True}

    try:
        payload = json.loads(source_path.read_text(encoding="utf-8"))
    except Exception as exc:
        return {"error": f"tiles_json_read_failed: {exc}"}
    rows = payload.get("rows") if isinstance(payload, dict) and isinstance(payload.get("rows"), list) else []
    if not rows:
        if allow_empty_subset:
            payload["rows"] = []
            output_obj.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
            return {"path": str(output_obj), "row_count": 0, "empty_source": True}
        return {"error": "tiles_json_empty"}

    regions = _region_index_with_aliases(region_rows)
    filtered_rows: List[Dict[str, Any]] = []
    chemistry_group_id = str(chemistry_group_id or "").strip()
    for row in rows:
        if not isinstance(row, dict):
            continue
        row_group_id = str(row.get("chemistry_group_id") or "").strip()
        if chemistry_group_id and row_group_id and row_group_id != chemistry_group_id:
            continue
        if binding:
            evidence = binding.verify_row(row)
            if not evidence:
                continue
            row = {**row, 'mature_rna_binding': evidence}
        intervals = _tile_row_intervals(row)
        requirement = tile_overlap_requirement if tile_overlap_requirement != "mixed" else "any_overlap"
        matched = candidate_matches_regions(intervals, region_rows, requirement)
        if matched and matches_constraint_filters(intervals, constraint_filters or []):
            filtered_rows.append(row)

    if not filtered_rows:
        if allow_empty_subset:
            payload["rows"] = []
            output_obj.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
            return {"path": str(output_obj), "row_count": 0, "empty_subset": True}
        return {"error": "tile_subset_empty"}
    payload["rows"] = _dedupe_tile_rows(filtered_rows)
    output_obj.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"path": str(output_obj), "row_count": len(payload["rows"])}


def _tiles_json_row_count(json_path: str) -> int:
    path_obj = Path(str(json_path or "")).expanduser()
    if not path_obj.exists():
        return 0
    try:
        payload = json.loads(path_obj.read_text(encoding="utf-8"))
    except Exception:
        return 0
    rows = payload.get("rows") if isinstance(payload, dict) and isinstance(payload.get("rows"), list) else []
    return len(rows)


def _write_empty_tiles_json(
    *,
    output_path: str,
    source_json_path: Optional[str] = None,
    note: str = "",
    table: str = "tiles",
) -> Dict[str, Any]:
    output_obj = Path(output_path).expanduser()
    output_obj.parent.mkdir(parents=True, exist_ok=True)

    schema: Dict[str, Any] = {}
    if source_json_path:
        source_obj = Path(str(source_json_path)).expanduser()
        if source_obj.exists():
            try:
                source_payload = json.loads(source_obj.read_text(encoding="utf-8"))
            except Exception:
                source_payload = {}
            if isinstance(source_payload, dict) and isinstance(source_payload.get("schema"), dict):
                schema = deepcopy(source_payload.get("schema") or {})

    if not isinstance(schema, dict) or not schema:
        schema = {
            "table": table,
            "primary_key": "id",
            "columns": [],
            "notes": [],
        }
    else:
        schema = deepcopy(schema)
        schema.setdefault("table", table)
        schema.setdefault("primary_key", "id")
        schema.setdefault("columns", [])
        existing_notes = schema.get("notes")
        schema["notes"] = list(existing_notes) if isinstance(existing_notes, list) else []

    if note:
        notes = schema.setdefault("notes", [])
        if note not in notes:
            notes.append(note)

    payload = {"schema": schema, "rows": []}
    output_obj.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"path": str(output_obj), "row_count": 0}


def _widen_schema_type(existing: str, incoming: str) -> str:
    order = {"boolean": 0, "integer": 1, "number": 2, "string": 3}
    if existing not in order:
        return incoming
    if incoming not in order:
        return existing
    return existing if order[existing] >= order[incoming] else incoming


def _merge_tiles_json_outputs(
    *,
    source_paths: List[str],
    output_path: str,
    notes: str,
    source_annotations: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    unique_paths = [str(Path(path).expanduser()) for path in source_paths if isinstance(path, str) and path.strip()]
    if not unique_paths:
        return {"error": "no_source_paths"}
    if source_annotations is not None and len(source_annotations) != len(unique_paths):
        return {"error": "merge_source_annotation_count_mismatch"}

    merged_rows: List[Dict[str, Any]] = []
    merged_columns: Dict[str, str] = {}
    primary_key = "id"
    table_name = "aso_tiles"
    seen_rows: Set[str] = set()

    for idx, path in enumerate(unique_paths, start=1):
        path_obj = Path(path)
        if not path_obj.exists():
            return {"error": f"missing_merge_source: {path_obj}"}
        try:
            payload = json.loads(path_obj.read_text(encoding="utf-8"))
        except Exception as exc:
            return {"error": f"merge_source_read_failed: {exc}"}
        if not isinstance(payload, dict):
            continue
        schema = payload.get("schema") if isinstance(payload.get("schema"), dict) else {}
        if idx == 1:
            table_name = str(schema.get("table") or table_name)
            primary_key = str(schema.get("primary_key") or primary_key)
        columns = schema.get("columns") if isinstance(schema.get("columns"), dict) else {}
        for key, value in columns.items():
            incoming_type = str(value or "string")
            if key in merged_columns:
                merged_columns[key] = _widen_schema_type(merged_columns[key], incoming_type)
            else:
                merged_columns[key] = incoming_type
        rows = payload.get("rows") if isinstance(payload.get("rows"), list) else []
        for row in rows:
            if not isinstance(row, dict):
                continue
            if source_annotations is not None:
                # Attach the recorded producing job before merging. Never infer
                # ownership from a sequence name or overwrite existing lineage.
                row = dict(row)
                for field, value in source_annotations[idx - 1].items():
                    if row.get(field) in (None, ""):
                        row[field] = value
                    merged_columns.setdefault(field, "string")
            try:
                dedupe_key = json.dumps(row, sort_keys=True, default=str, ensure_ascii=False)
            except Exception:
                dedupe_key = str(row)
            if dedupe_key in seen_rows:
                continue
            seen_rows.add(dedupe_key)
            merged_rows.append(row)

    if not merged_rows:
        empty_result = _write_empty_tiles_json(
            output_path=output_path,
            source_json_path=unique_paths[0],
            note=notes,
            table=table_name,
        )
        empty_result["merged_empty"] = True
        return empty_result
    merged_payload = {
        "schema": {
            "table": table_name,
            "primary_key": primary_key,
            "columns": merged_columns,
            "notes": notes,
        },
        "rows": merged_rows,
    }
    output_obj = Path(output_path).expanduser()
    output_obj.parent.mkdir(parents=True, exist_ok=True)
    output_obj.write_text(json.dumps(merged_payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"path": str(output_obj), "row_count": len(merged_rows)}


def _file_sha256(path: str) -> str:
    file_path = Path(str(path or "")).expanduser()
    digest = hashlib.sha256()
    with file_path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _clone_splice_eval_result_for_job(job_eval: Dict[str, Any], job_output_dir: str) -> Dict[str, Any]:
    cloned = dict(job_eval) if isinstance(job_eval, dict) else {}
    output_dir = Path(str(job_output_dir or "")).expanduser()
    output_dir.mkdir(parents=True, exist_ok=True)
    rewritten_paths: Dict[str, str] = {}
    for key in ("scored_tiles_path", "scored_tiles_path_unfiltered"):
        src_path = str(cloned.get(key) or "").strip()
        if not src_path:
            continue
        src = Path(src_path).expanduser()
        if not src.exists():
            continue
        dest = output_dir / src.name
        if src.resolve() != dest.resolve():
            shutil.copyfile(src, dest)
        cloned[key] = str(dest)
        rewritten_paths[str(src)] = str(dest)
    splice_transformer = cloned.get("splice_transformer")
    if isinstance(splice_transformer, dict):
        transform_path = str(splice_transformer.get("path") or "").strip()
        if transform_path in rewritten_paths:
            cloned["splice_transformer"] = {
                **splice_transformer,
                "path": rewritten_paths[transform_path],
            }
    constraint_filtering = cloned.get("constraint_filtering")
    if isinstance(constraint_filtering, dict):
        output_path = str(constraint_filtering.get("output_path") or "").strip()
        if output_path in rewritten_paths:
            cloned["constraint_filtering"] = {
                **constraint_filtering,
                "output_path": rewritten_paths[output_path],
            }
    return cloned


def _export_job_tile_views(
    *,
    run_dir: str,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    modality: str,
    source_json_path: str,
    result_key: str,
    output_name: str,
    allow_full_copy_for_empty: bool = False,
    allow_empty_subset: bool = False,
) -> Dict[str, Dict[str, Any]]:
    jobs = _get_design_jobs(final_payload, modality)
    results_by_job = _ensure_design_results_map(
        structured_goal=structured_goal,
        final_payload=final_payload,
        modality=modality,
    )
    for job in jobs:
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            continue
        output_dir = str(job.get("output_dir") or str(_write_run_path(run_dir, f"{modality}_jobs", job_id))).strip()
        region_rows = job.get("region_rows") if isinstance(job.get("region_rows"), list) else []
        tile_filter_rows = job.get("tile_filter_rows") if isinstance(job.get("tile_filter_rows"), list) else region_rows
        tile_filter_rows = _normalize_region_rows(tile_filter_rows) or _normalize_region_rows(region_rows)
        tile_overlap_requirement = str(job.get("tile_overlap_requirement") or "any_overlap").strip().lower() or "any_overlap"
        allow_full_copy = bool(job.get("allow_full_copy")) or (allow_full_copy_for_empty and not region_rows)
        entry = results_by_job.setdefault(job_id, {})
        entry["job_id"] = job_id
        entry["label"] = str(job.get("label") or job_id)
        entry["output_dir"] = output_dir
        entry["modality"] = modality
        entry.pop(result_key, None)
        entry.pop(f"{result_key}_row_count", None)
        skip_reason = _design_job_skip_reason(job)
        if skip_reason:
            entry["status"] = "skipped"
            entry["reason"] = skip_reason
            entry["skipped"] = True
            continue
        entry.pop("skipped", None)
        if str(entry.get("status") or "").strip().lower() == "skipped":
            entry.pop("status", None)
            entry.pop("reason", None)
        subset_result = _filter_tiles_json_to_output(
            source_json_path=source_json_path,
            region_rows=tile_filter_rows,
            output_path=os.path.join(output_dir, output_name),
            allow_full_copy=allow_full_copy,
            tile_overlap_requirement=tile_overlap_requirement,
            chemistry_group_id=str(job.get("chemistry_group_id") or "").strip(),
            allow_empty_subset=allow_empty_subset,
            constraint_filters=((job.get("selection_meta") or {}).get("region_constraints") or {}).get("tile_constraint_filters"),
            mature_binding_scope=(((job.get("selection_meta") or {}).get("region_constraints") or {}).get("mature_rna") or {}).get("shared_binding"),
            structured_goal=structured_goal,
        )
        if subset_result.get("path"):
            entry[result_key] = subset_result["path"]
            entry[f"{result_key}_row_count"] = int(subset_result.get("row_count") or 0)
    return results_by_job


def _export_job_filter_bucket_views(
    *,
    run_dir: str,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    modality: str,
    filter_summary: Dict[str, Any],
    bucket_specs: List[Tuple[str, str, str]],
) -> Dict[str, Dict[str, Any]]:
    results_by_job = _ensure_design_results_map(
        structured_goal=structured_goal,
        final_payload=final_payload,
        modality=modality,
    )
    if not isinstance(filter_summary, dict):
        return results_by_job
    for summary_key, result_key, output_name in bucket_specs:
        for entry in results_by_job.values():
            if isinstance(entry, dict):
                entry.pop(result_key, None)
                entry.pop(f"{result_key}_row_count", None)
        bucket = filter_summary.get(summary_key)
        if not isinstance(bucket, dict):
            continue
        source_json_path = str(bucket.get("path") or "").strip()
        if not source_json_path or not Path(source_json_path).exists():
            continue
        _export_job_tile_views(
            run_dir=run_dir,
            structured_goal=structured_goal,
            final_payload=final_payload,
            modality=modality,
            source_json_path=source_json_path,
            result_key=result_key,
            output_name=output_name,
            allow_full_copy_for_empty=False,
            allow_empty_subset=True,
        )
    return results_by_job


def _candidate_row_identity_key(row: Dict[str, Any]) -> Tuple[str, str, str, str]:
    sequence = str(_normalize_aso_sequence(row.get("Sequence") or row.get("sequence") or row.get("seq") or "").get("sequence") or "").strip().upper()
    chrom = str(_candidate_row_chrom(row) or "").strip()
    start = str(_candidate_row_start(row) or "").strip()
    end = str(_candidate_row_end(row) or "").strip()
    return (sequence, chrom, start, end)


def _copy_offtarget_expression_annotations(
    *,
    source_json_path: str,
    target_json_path: str,
) -> Dict[str, Any]:
    source_path = Path(str(source_json_path or "")).expanduser()
    target_path = Path(str(target_json_path or "")).expanduser()
    if not source_path.exists() or not source_path.is_file():
        return {"status": "skipped", "reason": "source_missing", "source_json_path": str(source_path)}
    if not target_path.exists() or not target_path.is_file():
        return {"status": "skipped", "reason": "target_missing", "target_json_path": str(target_path)}
    try:
        source_payload = json.loads(source_path.read_text(encoding="utf-8"))
        target_payload = json.loads(target_path.read_text(encoding="utf-8"))
    except Exception as exc:
        return {"status": "error", "error": f"json_read_failed: {exc}", "target_json_path": str(target_path)}
    source_rows = source_payload.get("rows") if isinstance(source_payload, dict) and isinstance(source_payload.get("rows"), list) else []
    target_rows = target_payload.get("rows") if isinstance(target_payload, dict) and isinstance(target_payload.get("rows"), list) else []
    if not source_rows or not target_rows:
        return {"status": "skipped", "reason": "rows_missing", "target_json_path": str(target_path)}

    source_schema = source_payload.get("schema") if isinstance(source_payload.get("schema"), dict) else {}
    source_columns = source_schema.get("columns") if isinstance(source_schema.get("columns"), dict) else {}
    expression_fields = tuple(field for field in _OFF_TARGET_EXPRESSION_ROW_KEYS)
    by_identity: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
    by_sequence: Dict[str, List[Dict[str, Any]]] = {}
    for row in source_rows:
        if not isinstance(row, dict):
            continue
        expression_values = {
            field: deepcopy(row[field])
            for field in expression_fields
            if field in row and row.get(field) not in (None, "")
        }
        if not expression_values:
            continue
        identity = _candidate_row_identity_key(row)
        if all(identity):
            by_identity[identity] = expression_values
        sequence = identity[0]
        if sequence:
            by_sequence.setdefault(sequence, []).append(expression_values)

    changed = False
    updated_rows = 0
    for row in target_rows:
        if not isinstance(row, dict):
            continue
        identity = _candidate_row_identity_key(row)
        expression_values = by_identity.get(identity)
        if expression_values is None and identity[0]:
            sequence_matches = by_sequence.get(identity[0]) or []
            if len(sequence_matches) == 1:
                expression_values = sequence_matches[0]
        if not expression_values:
            continue
        row_changed = False
        for field, value in expression_values.items():
            if row.get(field) == value:
                continue
            row[field] = deepcopy(value)
            row_changed = True
        if row_changed:
            changed = True
            updated_rows += 1

    if not changed:
        return {"status": "unchanged", "target_json_path": str(target_path), "updated_rows": 0}

    target_schema = target_payload.get("schema") if isinstance(target_payload.get("schema"), dict) else {}
    target_columns = target_schema.get("columns") if isinstance(target_schema.get("columns"), dict) else {}
    for field in expression_fields:
        if field in source_columns:
            target_columns[field] = source_columns[field]
        elif field not in target_columns:
            if field in {
                "off_target_by_species",
                "off_target_search_provenance_by_species",
                "off_target_expression_by_species",
                "off_target_expression_risk_by_species",
            } or field.lower().endswith("details"):
                target_columns[field] = "object"
            elif field == "worst_species_off_target_expression_incomplete":
                target_columns[field] = "boolean"
            else:
                target_columns[field] = "number"
    target_schema["columns"] = target_columns
    target_payload["schema"] = target_schema
    target_payload["rows"] = target_rows
    try:
        target_path.write_text(json.dumps(target_payload, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as exc:
        return {"status": "error", "error": f"json_write_failed: {exc}", "target_json_path": str(target_path)}
    return {"status": "updated", "target_json_path": str(target_path), "updated_rows": updated_rows}


def _sync_offtarget_expression_to_design_result_tiles(
    *,
    source_json_path: str,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    modality: str,
    result_key: str,
) -> Dict[str, Any]:
    results_by_job = _ensure_design_results_map(
        structured_goal=structured_goal,
        final_payload=final_payload,
        modality=modality,
    )
    sync_results: Dict[str, Any] = {}
    updated_count = 0
    for job_id, job_result in results_by_job.items():
        if not isinstance(job_result, dict):
            continue
        target_json_path = str(job_result.get(result_key) or "").strip()
        if not target_json_path:
            continue
        result = _copy_offtarget_expression_annotations(
            source_json_path=source_json_path,
            target_json_path=target_json_path,
        )
        sync_results[str(job_id)] = result
        if isinstance(result, dict) and result.get("status") == "updated":
            updated_count += 1
    return {
        "status": "updated" if updated_count else "unchanged",
        "updated_job_count": updated_count,
        "jobs": sync_results,
    }


def _design_results_cover(final_payload: Dict[str, Any], modality: str, result_key: str) -> bool:
    jobs = _get_design_jobs(final_payload, modality)
    active_jobs = [job for job in jobs if not _design_job_is_skipped(job)]
    if not active_jobs:
        return True
    results = final_payload.get(_design_results_key(modality))
    if not isinstance(results, dict):
        return False
    for job in active_jobs:
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            continue
        job_result = results.get(job_id)
        if not isinstance(job_result, dict):
            return False
        result_path = str(job_result.get(result_key) or "").strip()
        if not result_path or not Path(result_path).exists():
            return False
    return True


def _design_results_cover_for_jobs(
    final_payload: Dict[str, Any],
    modality: str,
    result_key: str,
    jobs: List[Dict[str, Any]],
) -> bool:
    scoped_jobs = [job for job in jobs if isinstance(job, dict) and str(job.get("job_id") or "").strip()]
    active_jobs = [job for job in scoped_jobs if not _design_job_is_skipped(job)]
    if not active_jobs:
        return True
    results = final_payload.get(_design_results_key(modality))
    if not isinstance(results, dict):
        return False
    for job in active_jobs:
        job_id = str(job.get("job_id") or "").strip()
        job_result = results.get(job_id)
        if not isinstance(job_result, dict):
            return False
        if _design_job_is_skipped(job, job_result):
            continue
        result_path = str(job_result.get(result_key) or "").strip()
        if not result_path or not Path(result_path).exists():
            return False
    return True


def _collect_design_job_bundles(final_payload: Dict[str, Any], modality: str) -> List[Dict[str, Any]]:
    jobs = _get_design_jobs(final_payload, modality)
    results = final_payload.get(_design_results_key(modality))
    results_by_job = results if isinstance(results, dict) else {}
    bundles: List[Dict[str, Any]] = []
    for job in jobs:
        bundle = dict(job)
        job_id = str(job.get("job_id") or "").strip()
        job_result = results_by_job.get(job_id)
        if isinstance(job_result, dict):
            bundle["results"] = dict(job_result)
        bundles.append(bundle)
    return bundles


def _truncate_report_text(value: Any, max_chars: int = 12000) -> Optional[str]:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not text:
        return None
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 20].rstrip() + "\n...[truncated]"


def _site_label_for_report(entry: Any) -> Optional[str]:
    if not isinstance(entry, dict):
        return None
    for key in ("canonical_label", "label", "label_hint"):
        value = entry.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
    position = entry.get("position")
    try:
        if site_kind in {"acceptor", "donor"} and position is not None:
            return f"{site_kind}@{int(position)}"
    except Exception:
        return None
    return None


def _preview_site_labels(entries: Any, max_items: int = 8) -> List[str]:
    labels: List[str] = []
    if not isinstance(entries, list):
        return labels
    for entry in entries:
        label = _site_label_for_report(entry)
        if not label or label in labels:
            continue
        labels.append(label)
        if len(labels) >= max_items:
            break
    return labels


def _compact_structured_goal_for_report(structured_goal: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(structured_goal, dict):
        return {}
    compact: Dict[str, Any] = {}
    scalar_keys = [
        "gene_symbol",
        "gene_id",
        "species",
        "target_context",
        "intent",
        "desired_effect",
        "target_scope",
        "exon_label",
        "focus_exons_only",
        "transcript_policy",
        "steric_targeting_policy",
        "run_splice_router",
        "run_splice_eval",
        "snapgene_path",
    ]
    for key in scalar_keys:
        value = structured_goal.get(key)
        if value not in (None, "", [], {}):
            compact[key] = value

    isoform_objectives = structured_goal.get("splice_isoform_objectives")
    if isinstance(isoform_objectives, list):
        compact["splice_isoform_objectives"] = [
            {
                "isoform_label": item.get("isoform_label"),
                "desired_abundance": item.get("desired_abundance"),
                "role": item.get("role"),
                "rationale": item.get("rationale"),
            }
            for item in isoform_objectives
            if isinstance(item, dict)
        ]

    design_programs = _design_programs(structured_goal)
    if design_programs:
        compact["design_programs"] = [
            {
                "program_id": program.get("program_id"),
                "label": program.get("label"),
                "modality": program.get("modality"),
                "intent": program.get("intent"),
                "objective": program.get("objective"),
                "desired_delta": program.get("desired_delta"),
                "length": _coerce_positive_int(program.get("length")),
                "chemistry": _normalized_chemistry_label(program.get("chemistry")),
                "chemistry_platform": _chemistry_platform(program.get("chemistry")),
                "chemistry_length": _chemistry_length(program.get("chemistry")),
                "target_region": program.get("target_region"),
                "exon_label": program.get("exon_label"),
                "exon_labels": program.get("exon_labels"),
                "focus_exons_only": program.get("focus_exons_only"),
                "site_kind": program.get("site_kind"),
                "site_context": program.get("site_context"),
                "targeting_policy": program.get("targeting_policy"),
                "run_splice_eval": program.get("run_splice_eval"),
                "run_splice_router": program.get("run_splice_router"),
            }
            for program in design_programs
        ]

    region_constraints = structured_goal.get("region_constraints")
    if isinstance(region_constraints, list) and region_constraints:
        compact["region_constraints"] = [
            {
                key: item.get(key)
                for key in (
                    "constraint_id",
                    "label",
                    "source_type",
                    "operator",
                    "exon_label",
                    "transcript_id",
                    "aso_overlap_requirement",
                    "notes",
                )
                if isinstance(item, dict) and item.get(key) not in (None, "", [], {})
            }
            for item in region_constraints[:20]
            if isinstance(item, dict)
        ]

    alerts = structured_goal.get("pipeline_alerts")
    if isinstance(alerts, list) and alerts:
        compact["pipeline_alerts"] = alerts

    hints = structured_goal.get("site_direction_hints")
    if isinstance(hints, list) and hints:
        compact["site_direction_hints"] = [
            {
                "isoform_label": hint.get("isoform_label"),
                "site_hint": hint.get("site_hint"),
                "desired_delta": hint.get("desired_delta"),
                "exon_label": hint.get("exon_label"),
            }
            for hint in hints[:12]
            if isinstance(hint, dict)
        ]

    splice_site_plan = structured_goal.get("splice_site_plan")
    if isinstance(splice_site_plan, list) and splice_site_plan:
        preview: List[Dict[str, Any]] = []
        for entry in splice_site_plan[:12]:
            if not isinstance(entry, dict):
                continue
            preview_entry = {
                "label": _site_label_for_report(entry),
                "delta_direction": entry.get("delta_direction"),
                "site": entry.get("site"),
                "position": entry.get("position"),
                "chrom": entry.get("chrom"),
            }
            preview_entry = {
                key: value for key, value in preview_entry.items() if value not in (None, "", [], {})
            }
            if preview_entry:
                preview.append(preview_entry)
        compact["splice_site_plan_preview"] = {
            "count": len(splice_site_plan),
            "preview": preview,
        }
    return compact


def _compact_splicing_for_report(splicing: Any) -> Dict[str, Any]:
    if not isinstance(splicing, dict):
        return {}
    compact: Dict[str, Any] = {}
    model = splicing.get("model")
    if isinstance(model, str) and model.strip():
        compact["model"] = model.strip()
    analysis = _truncate_report_text(splicing.get("analysis"), max_chars=12000)
    if analysis:
        compact["analysis"] = analysis
    for key in ("unique_splice_site_count", "additional_site_count"):
        value = splicing.get(key)
        if isinstance(value, int):
            compact[key] = value
    context_payload = splicing.get("context_payload")
    if isinstance(context_payload, dict):
        context_summary: Dict[str, Any] = {
            "unique_splice_site_count": len(context_payload.get("unique_splice_sites") or []),
            "shared_splice_site_count": len(context_payload.get("shared_splice_sites") or []),
            "steric_site_candidate_count": len(context_payload.get("steric_site_candidates") or []),
            "safeguard_candidate_count": len(context_payload.get("safeguard_candidates") or []),
        }
        unique_preview = _preview_site_labels(context_payload.get("unique_splice_sites"), max_items=8)
        shared_preview = _preview_site_labels(context_payload.get("shared_splice_sites"), max_items=8)
        candidate_preview = _preview_site_labels(context_payload.get("steric_site_candidates"), max_items=8)
        safeguard_preview = _preview_site_labels(context_payload.get("safeguard_candidates"), max_items=8)
        if unique_preview:
            context_summary["unique_site_preview"] = unique_preview
        if shared_preview:
            context_summary["shared_site_preview"] = shared_preview
        if candidate_preview:
            context_summary["candidate_preview"] = candidate_preview
        if safeguard_preview:
            context_summary["safeguard_preview"] = safeguard_preview
        compact["context_summary"] = context_summary
    return compact


def _compact_route_goal_for_report(goal: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(goal, dict):
        return None
    compact: Dict[str, Any] = {}
    for key in (
        "rank",
        "goal_label",
        "primary_effect",
        "rationale",
        "ranking_confidence",
        "ranking_model",
        "routing_selection_source",
        "observed_max_abs_delta",
        "observed_mean_effect",
        "observed_support",
        "count",
        "threshold_used",
        "output_path",
        "csv_path",
        "excel_path",
        "job_id",
        "job_label",
        "job_output_dir",
        "job_summary_path",
        "notes",
        "csv_error",
        "selection_mode",
        "threshold_pass_count",
        "fallback_selection_used",
        "fallback_positive_count",
        "warning",
    ):
        value = goal.get(key)
        if value not in (None, "", [], {}):
            compact[key] = value
    primary_targets = goal.get("primary_targets")
    if isinstance(primary_targets, list) and primary_targets:
        compact["primary_targets"] = [
            item for item in primary_targets[:8] if isinstance(item, (str, int, float, bool))
        ]
    count_value = goal.get("count")
    try:
        count_int = int(count_value) if count_value is not None else None
    except Exception:
        count_int = None
    if count_int is not None:
        compact["status"] = "no_candidates_found" if count_int <= 0 else "candidates_found"
        if count_int <= 0 and not compact.get("warning"):
            compact["warning"] = "No ASO candidates met the routing threshold for this goal."
    safeguards = goal.get("safeguards_applied")
    if isinstance(safeguards, list):
        compact["safeguard_count"] = len(safeguards)
        preview: List[Dict[str, Any]] = []
        for item in safeguards[:5]:
            if not isinstance(item, dict):
                continue
            preview.append(
                {
                    "label": item.get("label"),
                    "max_abs_delta": item.get("max_abs_delta"),
                    "max_increase": item.get("max_increase"),
                    "max_decrease": item.get("max_decrease"),
                    "note": item.get("note"),
                }
            )
        if preview:
            compact["safeguard_preview"] = preview
    return compact


def _compact_strategy_routing_for_report(strategy_routing: Any) -> Dict[str, Any]:
    if not isinstance(strategy_routing, dict):
        return {}
    compact: Dict[str, Any] = {}
    planner_plan = strategy_routing.get("planner_plan")
    if isinstance(planner_plan, dict):
        compact_plan = {
            key: planner_plan.get(key)
            for key in ("plan_summary", "job_count", "goal_count", "router_max_steps", "max_steps")
            if planner_plan.get(key) not in (None, "", [], {})
        }
        ranking = planner_plan.get("ranking")
        if isinstance(ranking, dict):
            compact_ranking = {
                key: ranking.get(key)
                for key in ("mode", "model", "summary", "candidate_count")
                if ranking.get(key) not in (None, "", [], {})
            }
            if compact_ranking:
                compact_plan["ranking"] = compact_ranking
        if compact_plan:
            compact["planner_plan"] = compact_plan
    jobs = strategy_routing.get("jobs")
    if isinstance(jobs, list):
        compact["job_count"] = len(jobs)
        compact_jobs: List[Dict[str, Any]] = []
        for job in jobs[:100]:
            if not isinstance(job, dict):
                continue
            compact_jobs.append(
                {
                    "job_id": job.get("job_id"),
                    "job_label": job.get("job_label"),
                    "routes_dir": job.get("routes_dir"),
                    "summary_path": job.get("summary_path"),
                    "scored_tiles_path": job.get("scored_tiles_path"),
                    "goal_count": job.get("goal_count"),
                    "selected_tile_count": job.get("selected_tile_count"),
                }
            )
        compact["jobs"] = compact_jobs
    goals = strategy_routing.get("goals")
    if isinstance(goals, list):
        compact["goal_count"] = len(goals)
        compact_goals = [
            compact_goal
            for compact_goal in (_compact_route_goal_for_report(goal) for goal in goals[:120])
            if isinstance(compact_goal, dict)
        ]
        compact["goals"] = compact_goals
        zero_hit_goals = 0
        for goal in compact_goals:
            if str(goal.get("status") or "").strip().lower() == "no_candidates_found":
                zero_hit_goals += 1
        compact["zero_hit_goal_count"] = zero_hit_goals
        compact["nonzero_goal_count"] = max(0, len(compact_goals) - zero_hit_goals)
    output_dir = strategy_routing.get("output_dir")
    if isinstance(output_dir, str) and output_dir.strip():
        compact["output_dir"] = output_dir.strip()
    return compact


def _register_pipeline_alert(
    structured_goal: Optional[Dict[str, Any]],
    final_payload: Optional[Dict[str, Any]],
    message: str,
) -> None:
    if not message:
        return
    if isinstance(structured_goal, dict):
        alerts = structured_goal.setdefault("pipeline_alerts", [])
        if message not in alerts:
            alerts.append(message)
    if isinstance(final_payload, dict):
        alerts = final_payload.setdefault("pipeline_alerts", [])
        if message not in alerts:
            alerts.append(message)


def _collect_report_pipeline_alerts(structured_goal: Dict[str, Any], final_payload: Dict[str, Any]) -> List[str]:
    alerts: List[str] = []
    for source in (structured_goal, final_payload):
        existing = source.get("pipeline_alerts") if isinstance(source, dict) else None
        if isinstance(existing, list):
            for alert in existing:
                alert_text = str(alert or "").strip()
                if alert_text and alert_text not in alerts:
                    alerts.append(alert_text)
    for modality in ("steric", "gapmer"):
        for job in _get_design_jobs(final_payload, modality):
            if not isinstance(job, dict):
                continue
            job_label = str(job.get("label") or job.get("job_id") or modality).strip()
            region_constraints = (job.get("selection_meta") or {}).get("region_constraints")
            applied_constraints = region_constraints.get("applied_constraints") if isinstance(region_constraints, dict) else None
            if not isinstance(applied_constraints, list):
                continue
            for constraint in applied_constraints:
                if not isinstance(constraint, dict):
                    continue
                operator = str(constraint.get("operator") or "").strip().lower()
                if operator != "union":
                    continue
                try:
                    source_row_count = int(constraint.get("source_row_count") or 0)
                except Exception:
                    source_row_count = 0
                if source_row_count != 0:
                    continue
                constraint_label = str(constraint.get("label") or constraint.get("constraint_id") or "union source").strip()
                warning = f"{job_label}: requested union source '{constraint_label}' contributed 0 rows."
                if warning not in alerts:
                    alerts.append(warning)
    strategy_routing = final_payload.get("strategy_routing") if isinstance(final_payload, dict) else None
    goals = strategy_routing.get("goals") if isinstance(strategy_routing, dict) else None
    if isinstance(goals, list):
        for goal in goals:
            if not isinstance(goal, dict):
                continue
            warning_text = str(goal.get("warning") or "").strip()
            if not warning_text:
                continue
            goal_label = str(goal.get("goal_label") or goal.get("primary_label") or "routing goal").strip()
            combined = f"{goal_label}: {warning_text}"
            if combined not in alerts:
                alerts.append(combined)
    return alerts


def _summarize_skipped_design_jobs(jobs: List[Dict[str, Any]], modality: str) -> str:
    skipped_jobs = [job for job in jobs if _design_job_is_skipped(job)]
    if not skipped_jobs:
        return ""
    count = len(skipped_jobs)
    verb = "was" if count == 1 else "were"
    noun = f"{modality.lower()} design job" if count == 1 else f"{modality.lower()} design jobs"
    summary = f"{count} {noun} {verb} skipped."
    first_reason = str(skipped_jobs[0].get("reason") or _design_job_skip_reason(skipped_jobs[0]) or "").strip()
    if first_reason:
        summary += f" {first_reason}"
    return summary


def _empty_design_branch_status(jobs: List[Dict[str, Any]], *, constraints_exhausted: bool = False) -> str:
    """An absent plan is not evidence that a scientific search was exhausted."""
    reasons = {_design_job_empty_reason_code(job) for job in jobs if isinstance(job, dict)}
    if reasons == {"constraints_exhausted"} or (
        constraints_exhausted and reasons <= {"constraints_exhausted", "planning_missing"}
    ):
        return "no_candidates_after_constraints"
    if reasons == {"user_skipped"}:
        return "skipped"
    return "unknown"


def _build_branch_outcomes_for_report(
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
) -> Dict[str, Dict[str, Any]]:
    outcomes: Dict[str, Dict[str, Any]] = {}

    steric_jobs = _get_design_jobs(final_payload, "steric")
    gapmer_jobs = _get_design_jobs(final_payload, "gapmer")
    steric_requested = bool(
        steric_jobs
        or _design_programs(structured_goal, "steric")
        # Match planner precedence: an explicit gapmer-only program does not
        # request steric work merely because legacy run labels/flags remain.
        # Real steric programs and job records above still require accounting.
        or (
            not _design_programs_are_gapmer_only(structured_goal)
            and (
                str(structured_goal.get("intent") or "").strip().lower() in {"splice_modulation", "binding"}
                or _coerce_bool(final_payload.get("run_splice_eval"))
                or _coerce_bool(final_payload.get("run_splice_router"))
            )
        )
    )
    gapmer_requested = bool(
        gapmer_jobs
        or _effective_gapmer_design_programs(structured_goal)
        or _splice_switch_gapmer_support_policy(structured_goal, _design_programs(structured_goal)).get("enabled")
        or str(structured_goal.get("intent") or "").strip().lower() == "knockdown"
        or _coerce_bool((structured_goal.get("junction_gapmers") or {}).get("enabled"))
    )

    if steric_requested:
        steric_all_empty = bool(steric_jobs) and all(
            not _normalize_region_rows(job.get("region_rows")) for job in steric_jobs if isinstance(job, dict)
        )
        steric_skipped_summary = _summarize_skipped_design_jobs(steric_jobs, "steric")
        steric_constraints_exhausted = bool(
            _coerce_bool(final_payload.get("steric_constraints_exhausted"))
            or _coerce_bool(structured_goal.get("steric_constraints_exhausted"))
            or any(
                bool((job.get("selection_meta") or {}).get("constraint_exhausted"))
                for job in steric_jobs
                if isinstance(job, dict)
            )
        )
        strategy_routing = final_payload.get("strategy_routing")
        zero_hit_all_routes = False
        if isinstance(strategy_routing, dict):
            goals = strategy_routing.get("goals")
            if isinstance(goals, list) and goals:
                counts: List[int] = []
                for goal in goals:
                    if not isinstance(goal, dict):
                        continue
                    try:
                        counts.append(int(goal.get("count") or 0))
                    except Exception:
                        counts.append(0)
                zero_hit_all_routes = bool(counts) and all(count <= 0 for count in counts)
        if steric_all_empty and steric_skipped_summary:
            outcomes["steric"] = {
                "requested": True,
                "status": _empty_design_branch_status(steric_jobs, constraints_exhausted=steric_constraints_exhausted),
                "reason": steric_skipped_summary,
            }
        elif steric_constraints_exhausted and steric_all_empty:
            outcomes["steric"] = {
                "requested": True,
                "status": "no_candidates_after_constraints",
                "reason": "Requested steric region constraints exhausted the steric search space.",
            }
        elif zero_hit_all_routes:
            reason = "Steric routing completed, but no ASOs met the routing thresholds."
            if steric_skipped_summary:
                reason = steric_skipped_summary + " Remaining steric jobs completed routing, but no ASOs met the routing thresholds."
            outcomes["steric"] = {
                "requested": True,
                "status": "no_candidates_found",
                "reason": reason,
            }
        elif not steric_jobs and not (final_payload.get("tiling_results") or structured_goal.get("tiling_results")):
            outcomes["steric"] = {"requested": True, "status": "unknown", "reason": "No executed steric jobs or output records are present."}
        else:
            outcome = {"requested": True, "status": "outputs_present"}
            if steric_skipped_summary:
                outcome["reason"] = steric_skipped_summary + " Remaining steric jobs still produced outputs."
            outcomes["steric"] = outcome

    if gapmer_requested:
        gapmer_all_empty = bool(gapmer_jobs) and all(
            not _normalize_region_rows(job.get("region_rows")) for job in gapmer_jobs if isinstance(job, dict)
        )
        gapmer_skipped_summary = _summarize_skipped_design_jobs(gapmer_jobs, "gapmer")
        gapmer_region_filter = (
            final_payload.get("gapmer_region_filter")
            if isinstance(final_payload.get("gapmer_region_filter"), dict)
            else {}
        )
        gapmer_constraint_exhausted = bool(gapmer_region_filter.get("constraint_exhausted"))
        gapmer_results = (
            final_payload.get("gapmer_tiling_results")
            if isinstance(final_payload.get("gapmer_tiling_results"), dict)
            else {}
        )
        gapmer_results_by_job = (
            final_payload.get("gapmer_tiling_results_by_job")
            if isinstance(final_payload.get("gapmer_tiling_results_by_job"), dict)
            else {}
        )
        gapmer_empty_by_constraints = bool(gapmer_results.get("empty_by_constraints")) or any(
            isinstance(result, dict) and bool(result.get("empty_by_constraints"))
            for result in gapmer_results_by_job.values()
        )
        try:
            gapmer_row_count = int(gapmer_results.get("row_count") or 0)
        except Exception:
            gapmer_row_count = 0
        if gapmer_all_empty and gapmer_skipped_summary:
            outcomes["gapmer"] = {
                "requested": True,
                "status": _empty_design_branch_status(gapmer_jobs, constraints_exhausted=gapmer_constraint_exhausted or gapmer_empty_by_constraints),
                "reason": gapmer_skipped_summary,
            }
        elif (gapmer_constraint_exhausted or gapmer_empty_by_constraints) and gapmer_all_empty:
            outcomes["gapmer"] = {
                "requested": True,
                "status": "no_candidates_after_constraints",
                "reason": "Requested gapmer region constraints exhausted the gapmer search space.",
            }
        elif gapmer_jobs and gapmer_row_count <= 0:
            reason = "Gapmer scoring completed, but no candidate ASOs remained."
            if gapmer_skipped_summary:
                reason = gapmer_skipped_summary + " Remaining gapmer jobs completed scoring, but no candidate ASOs remained."
            outcomes["gapmer"] = {
                "requested": True,
                "status": "no_candidates_found",
                "reason": reason,
            }
        elif not gapmer_jobs and not gapmer_results and not gapmer_results_by_job:
            outcomes["gapmer"] = {"requested": True, "status": "skipped", "reason": "No gapmer branch was executed and no gapmer output records are present; a configured or conditional branch is not a completed design."}
        else:
            outcome = {"requested": True, "status": "outputs_present"}
            if gapmer_skipped_summary:
                outcome["reason"] = gapmer_skipped_summary + " Remaining gapmer jobs still produced outputs."
            outcomes["gapmer"] = outcome

    materialized = final_payload.get("materialized_region_constraints") or structured_goal.get("materialized_region_constraints") or {}
    for modality, outcome in outcomes.items():
        entries = list(materialized.get("global") or [])
        for program in _design_programs(structured_goal, modality):
            entries.extend((materialized.get("by_program") or {}).get(program.get("program_id")) or [])
        searches = [{"constraint_id": entry.get("constraint_id"), "source_type": entry.get("source_type"),
                     **deepcopy(entry["materialization_summary"])} for entry in entries
                    if isinstance(entry, dict) and isinstance(entry.get("materialization_summary"), dict)
                    and entry["materialization_summary"].get("search_status")]
        if searches:
            outcome["source_searches"] = searches
        failures = [entry.get("materialization_summary") for entry in entries
                    if isinstance(entry, dict) and isinstance(entry.get("materialization_summary"), dict)
                    and (entry["materialization_summary"].get("error")
                         or entry["materialization_summary"].get("status") in {"error", "unresolved", "unavailable"})]
        if failures and outcome.get("status") != "outputs_present":
            outcome.update(status="evidence_unavailable", reason="Requested search constraints could not be resolved.", source_failures=deepcopy(failures))
    rbp_result = final_payload.get("rbp_binding_result") or structured_goal.get("rbp_binding_result") or {}
    if steric_requested and isinstance(rbp_result, dict) and rbp_result.get("error"):
        outcomes["steric"].update(status="evidence_unavailable", reason=str(rbp_result["error"]),
                                  source_search=deepcopy(rbp_result))
    elif steric_requested and rbp_result.get("search_status") == "completed":
        outcomes["steric"]["source_search"] = deepcopy(rbp_result)
    return outcomes


def _compact_job_results_for_report(job_result: Any) -> Dict[str, Any]:
    if not isinstance(job_result, dict):
        return {}
    compact: Dict[str, Any] = {}
    for key, value in job_result.items():
        if key in {"splice_transformer", "strategy_routing"}:
            continue
        if isinstance(value, (str, int, float, bool)) or value is None:
            if value not in (None, ""):
                compact[key] = value
    splice_transformer = job_result.get("splice_transformer")
    if isinstance(splice_transformer, dict):
        sites = splice_transformer.get("sites")
        compact_splice = {
            "path": splice_transformer.get("path"),
            "evaluated": splice_transformer.get("evaluated"),
        }
        if isinstance(sites, list):
            compact_splice["site_count"] = len(sites)
            preview = [str(site) for site in sites[:12] if str(site).strip()]
            if preview:
                compact_splice["sites_preview"] = preview
        compact["splice_transformer"] = {
            key: value for key, value in compact_splice.items() if value not in (None, "", [], {})
        }
    strategy_routing = job_result.get("strategy_routing")
    if isinstance(strategy_routing, dict):
        compact["strategy_routing"] = _compact_strategy_routing_for_report(strategy_routing)
    return compact


def _compact_design_job_bundles_for_report(final_payload: Dict[str, Any], modality: str) -> List[Dict[str, Any]]:
    jobs = _get_design_jobs(final_payload, modality)
    results = final_payload.get(_design_results_key(modality))
    results_by_job = results if isinstance(results, dict) else {}
    compact_jobs: List[Dict[str, Any]] = []
    for job in jobs[:120]:
        if not isinstance(job, dict):
            continue
        job_id = str(job.get("job_id") or "").strip()
        job_result = results_by_job.get(job_id)
        job_status = str(job.get("status") or (job_result or {}).get("status") or "").strip()
        job_reason = str(job.get("reason") or (job_result or {}).get("reason") or "").strip()
        inferred_skip_reason = _design_job_skip_reason(job)
        if inferred_skip_reason:
            job_status = "skipped"
            job_reason = inferred_skip_reason
        compact_job = {
            "job_id": job.get("job_id"),
            "program_id": job.get("program_id"),
            "label": job.get("label"),
            "objective": job.get("objective"),
            "intent": job.get("intent"),
            "desired_effect": job.get("desired_effect"),
            "chemistry": job.get("chemistry_label") or _normalized_chemistry_label(job.get("chemistry")),
            "chemistry_platform": job.get("chemistry_platform") or _chemistry_platform(job.get("chemistry")),
            "chemistry_length": job.get("chemistry_length") or _chemistry_length(job.get("chemistry")),
            "target_region": job.get("target_region"),
            "exon_label": job.get("exon_label"),
            "focus_exons_only": job.get("focus_exons_only"),
            "site_kind": job.get("site_kind"),
            "site_context": job.get("site_context"),
            "targeting_policy": job.get("targeting_policy"),
            "tile_overlap_requirement": job.get("tile_overlap_requirement"),
            "region_rows": job.get("region_rows"),
            "tile_filter_rows": job.get("tile_filter_rows"),
            "run_splice_eval": job.get("run_splice_eval"),
            "run_splice_router": job.get("run_splice_router"),
            "output_dir": job.get("output_dir"),
            "region_count": job.get("region_count"),
            "modality": job.get("modality"),
            "status": job_status,
            "reason": job_reason,
        }
        compact_job = {key: value for key, value in compact_job.items() if value not in (None, "", [], {})}
        if isinstance(job_result, dict):
            compact_job["results"] = _compact_job_results_for_report(job_result)
        compact_jobs.append(compact_job)
    return compact_jobs


def _build_report_payload_manifest(
    *,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    run_dir: Optional[str] = None,
) -> Dict[str, Any]:
    compact_goal = _compact_structured_goal_for_report(structured_goal)
    effective_parameter_constraints = _merge_parameter_constraints(deepcopy(structured_goal))
    if not effective_parameter_constraints and isinstance(final_payload, dict):
        effective_parameter_constraints = (
            deepcopy(final_payload.get("parameter_constraints"))
            if isinstance(final_payload.get("parameter_constraints"), dict)
            else {}
        )
    splicing = _compact_splicing_for_report(
        structured_goal.get("splice_strategy_analysis") if isinstance(structured_goal, dict) else {}
    )
    strategy_routing = _compact_strategy_routing_for_report(final_payload.get("strategy_routing"))
    branch_outcomes = _build_branch_outcomes_for_report(structured_goal, final_payload)
    pipeline_alerts = _collect_report_pipeline_alerts(structured_goal, final_payload)
    reference_skip = final_payload.get("reference_preflight_skip") if isinstance(final_payload, dict) else None
    if isinstance(reference_skip, dict):
        skipped_species = ", ".join(
            str(item) for item in ((reference_skip.get("preflight") or {}).get("requested_species") or []) if str(item)
        )
        alert = "Reference preflight was skipped by user request"
        if skipped_species:
            alert += f" for species: {skipped_species}"
        if alert not in pipeline_alerts:
            pipeline_alerts.append(alert)
    for branch_name, outcome in branch_outcomes.items():
        if not isinstance(outcome, dict):
            continue
        status = str(outcome.get("status") or "").strip().lower()
        reason = str(outcome.get("reason") or "").strip()
        if status in {"no_candidates_after_constraints", "no_candidates_found"} and reason and reason not in pipeline_alerts:
            pipeline_alerts.append(reason)
    report_payload = {
        "payload_kind": "report_manifest",
        "payload_version": 2,
        "structured_goal": compact_goal,
        "transcript_recommendation": None,
        "bed": final_payload.get("steric_bed"),
        "steric_region_bed": final_payload.get("steric_region_bed"),
        "steric_merge_summary": final_payload.get("steric_merge_summary"),
        "gapmer_region_bed": final_payload.get("gapmer_region_bed"),
        "gapmer_region_filter": final_payload.get("gapmer_region_filter"),
        "materialized_region_constraints_summary": (
            (structured_goal.get("materialized_region_constraints") or {}).get("summary")
            if isinstance(structured_goal, dict)
            and isinstance(structured_goal.get("materialized_region_constraints"), dict)
            else None
        ),
        "pipeline_alerts": pipeline_alerts,
        "chemistry": final_payload.get("chemistry"),
        "chemistry_profiles": final_payload.get("chemistry_profiles"),
        "splicing": splicing,
        "strategy_routing": strategy_routing,
        "branch_outcomes": branch_outcomes,
        "splicing_eval": (
            (final_payload.get("tiling_results") or {}).get("splice_transformer")
            if isinstance(final_payload, dict)
            else {}
        ),
        "tiling": final_payload.get("tiling_results") or final_payload.get("tiling_config"),
        "steric_jobs": _compact_design_job_bundles_for_report(final_payload, "steric") if isinstance(final_payload, dict) else [],
        "gapmer_tiling": final_payload.get("gapmer_tiling_results") if isinstance(final_payload, dict) else None,
        "gapmer_jobs": _compact_design_job_bundles_for_report(final_payload, "gapmer") if isinstance(final_payload, dict) else [],
        "tiles_json_path": (
            (final_payload.get("tiling_results") or {}).get("json_path")
            if isinstance(final_payload, dict)
            else None
        ),
        "tiles_with_deltas_path": (
            (final_payload.get("tiling_results") or {}).get("scored_tiles_path")
            if isinstance(final_payload, dict)
            else None
        ),
        "filtered_tiles_path": (
            ((final_payload.get("tiling_results") or {}).get("initial_filtering") or {}).get("passed", {}).get("path")
            if isinstance(final_payload, dict)
            else None
        ),
        "gapmer_tiles_path": (
            (final_payload.get("gapmer_tiling_results") or {}).get("scored_tiles_path")
            if isinstance(final_payload, dict)
            else None
        ),
        "gapmer_csv_path": (
            (final_payload.get("gapmer_tiling_results") or {}).get("uniqueness_csv")
            if isinstance(final_payload, dict)
            else None
        ),
        "ranked_tiles_path": None,
        "ranking": final_payload.get("ranking") if isinstance(final_payload, dict) else None,
        "general_rationale": None,
        "filter_constraints": effective_parameter_constraints or None,
        "filtered_count": (
            ((final_payload.get("tiling_results") or {}).get("initial_filtering") or {}).get("passed", {}).get("count")
            if isinstance(final_payload, dict)
            else None
        ),
        "filter_rationale": None,
        "parameter_constraints": effective_parameter_constraints or None,
        "initial_filter_summary": (
            (final_payload.get("tiling_results") or {}).get("initial_filtering")
            if isinstance(final_payload, dict)
            else None
        ),
        "constraint_enforcement": (
            (final_payload.get("tiling_results") or {}).get("constraint_filtering")
            if isinstance(final_payload, dict)
            else None
        ),
        "conserved_exons": (
            (final_payload.get("gene_wide_exons") or {}).get("exons")
            if isinstance(final_payload, dict)
            else None
        ),
        "exon_frequency_map": None,
    }
    from .reference_provenance import design_reference_provenance
    report_payload["reference_provenance"] = design_reference_provenance(structured_goal, run_dir)
    from .binding_region_reports import build_binding_region_report, recorded_screening_summary
    report_payload["binding_region_candidate_sets"] = build_binding_region_report(
        structured_goal, final_payload, run_dir, _goal_runtime_module()._tile_row_overlap_intervals,
        effective_parameter_constraints)
    report_payload["recorded_screening_summary"] = recorded_screening_summary(structured_goal, final_payload)
    return report_payload


def _report_payload_tool_summary(report_payload: Dict[str, Any]) -> Dict[str, Any]:
    summary: Dict[str, Any] = {
        "payload_kind": report_payload.get("payload_kind"),
        "payload_version": report_payload.get("payload_version"),
        "payload_json_bytes": len(json.dumps(report_payload, ensure_ascii=False)),
        "steric_job_count": len(report_payload.get("steric_jobs") or []),
        "gapmer_job_count": len(report_payload.get("gapmer_jobs") or []),
        "branch_outcomes": deepcopy(report_payload.get("branch_outcomes") or {}),
        "pipeline_alerts": deepcopy(report_payload.get("pipeline_alerts") or []),
    }
    structured_goal = report_payload.get("structured_goal")
    if isinstance(structured_goal, dict):
        for key in ("gene_symbol", "intent", "target_context"):
            value = structured_goal.get(key)
            if value not in (None, "", [], {}):
                summary[key] = value
    routing = report_payload.get("strategy_routing")
    if isinstance(routing, dict):
        for key in ("job_count", "goal_count", "output_dir"):
            value = routing.get(key)
            if value not in (None, "", [], {}):
                summary[f"routing_{key}"] = value
    return summary


def _report_explainer_timeout_sec() -> float:
    raw = str(os.environ.get("AGENTIC_ASO_REPORT_EXPLAINER_TIMEOUT_SEC") or "").strip()
    if raw:
        try:
            value = float(raw)
            if value > 0:
                return value
        except ValueError:
            pass
    return 120.0


async def _run_report_explainer_with_timeout(prompt: str, timeout_sec: float) -> Any:
    return await asyncio.wait_for(
        Runner.run(report_explainer_agent, input=prompt, max_steps=6),
        timeout=timeout_sec,
    )


def _generate_report_explainer(
    *,
    run_dir: str,
    payload: Dict[str, Any],
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    report_payload: Dict[str, Any],
) -> Dict[str, Any]:
    context = build_report_explainer_context(
        run_dir=run_dir,
        payload=payload,
        structured_goal=structured_goal,
        final_payload=final_payload,
        report_payload=report_payload,
    )
    if report_payload.get("payload_kind") == "report_manifest":
        from .report_explainer import build_recorded_report_explainer
        return {"explainer": build_recorded_report_explainer(context), "context": context,
                "raw_output": "", "generation_error": "", "fallback_used": False,
                "source": "recorded_output_navigation"}
    prompt = (
        "Generate a structured, beginner-friendly explanation JSON for this ASO pipeline run.\n"
        "Use only the provided context.\n\n"
        f"{json.dumps(context, ensure_ascii=False)}"
    )
    raw_output = ""
    generation_error = ""
    timeout_sec = _report_explainer_timeout_sec()
    try:
        task = run_async_from_sync(
            lambda: _run_report_explainer_with_timeout(prompt, timeout_sec)
        )
    except asyncio.TimeoutError:
        task = None
        generation_error = f"report_explainer_generation_timeout: exceeded {timeout_sec:g}s"
    except Exception as exc:
        task = None
        generation_error = f"report_explainer_generation_failed: {exc}"

    if task is not None:
        raw_output = (
            task.final_output
            if isinstance(getattr(task, "final_output", None), str)
            else str(getattr(task, "final_output", ""))
        ).strip()
        parsed = parse_report_explainer_text(raw_output)
    else:
        parsed = None

    explainer = normalize_report_explainer(parsed, context)
    if not generation_error and not parsed:
        generation_error = "report_explainer_invalid_json"
    if not generation_error and not report_explainer_is_valid(explainer):
        generation_error = "report_explainer_invalid_or_incomplete"
    fallback_used = False
    if generation_error or not report_explainer_is_valid(explainer):
        fallback = normalize_report_explainer(build_fallback_report_explainer(context), context)
        if report_explainer_is_valid(fallback):
            explainer = fallback
            fallback_used = True
    return {
        "explainer": explainer,
        "context": context,
        "raw_output": raw_output,
        "generation_error": generation_error,
        "fallback_used": fallback_used,
    }


def _design_program_for_job(
    structured_goal: Dict[str, Any],
    modality: str,
    job: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    programs = _design_programs(structured_goal, modality)
    if not programs:
        return None
    selection_meta = job.get("selection_meta") if isinstance(job.get("selection_meta"), dict) else {}
    program_id = str(job.get("program_id") or selection_meta.get("program_id") or "").strip()
    if program_id:
        for program in programs:
            if not isinstance(program, dict):
                continue
            if str(program.get("program_id") or "").strip() == program_id:
                return program
    job_label = str(job.get("label") or "").strip().lower()
    if job_label:
        for program in programs:
            if not isinstance(program, dict):
                continue
            program_label = str(program.get("label") or program.get("objective") or "").strip().lower()
            if program_label and program_label == job_label:
                return program
    return None


def _resolve_gapmer_job_iso_label(
    *,
    job: Dict[str, Any],
    structured_goal: Dict[str, Any],
    isoform_transcripts: Dict[str, Dict[str, Any]],
    fallback_iso_label: Optional[str],
    runtime: Any,
) -> str:
    if not isinstance(isoform_transcripts, dict) or not isoform_transcripts:
        return str(fallback_iso_label or "")

    def _match_isoform_label(candidate: Any) -> str:
        text = str(candidate or "").strip()
        if not text:
            return ""
        if text in isoform_transcripts:
            return text
        for label, entry in isoform_transcripts.items():
            if not isinstance(entry, dict):
                continue
            transcript_id = str(entry.get("transcript_id") or entry.get("id") or "").strip()
            if transcript_id and transcript_id == text:
                return str(label)
        return ""

    selection_meta = job.get("selection_meta") if isinstance(job.get("selection_meta"), dict) else {}
    for candidate in (
        selection_meta.get("isoform_label"),
        job.get("isoform_label"),
        job.get("transcript_id"),
    ):
        matched = _match_isoform_label(candidate)
        if matched:
            return matched

    program = _design_program_for_job(structured_goal, "gapmer", job)
    selector = getattr(runtime, "_select_design_program_isoform_label", None)
    if callable(selector) and isinstance(program, dict):
        try:
            matched = _match_isoform_label(selector(isoform_transcripts, program, fallback_iso_label))
        except Exception:
            matched = ""
        if matched:
            return matched

    matched_fallback = _match_isoform_label(fallback_iso_label)
    if matched_fallback:
        return matched_fallback
    return str(next(iter(isoform_transcripts.keys()), ""))


def _merge_design_job_jsons(
    *,
    final_payload: Dict[str, Any],
    modality: str,
    result_key: str,
    output_path: str,
    notes: str,
) -> Dict[str, Any]:
    results = final_payload.get(_design_results_key(modality))
    results_by_job = results if isinstance(results, dict) else {}
    source_paths: List[str] = []
    source_annotations: List[Dict[str, Any]] = []
    for job in _get_design_jobs(final_payload, modality):
        if not isinstance(job, dict):
            continue
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            continue
        job_result = results_by_job.get(job_id)
        if not isinstance(job_result, dict):
            continue
        result_path = str(job_result.get(result_key) or "").strip()
        if result_path and Path(result_path).exists():
            source_paths.append(result_path)
            source_annotations.append({key: value for key, value in {
                "job_id": job_id, "program_id": job.get("program_id"),
                "job_label": job.get("label"), "source_modality": modality,
            }.items() if value not in (None, "")})
    if not source_paths:
        return {"error": f"no_{modality}_job_paths_for_{result_key}"}
    return _merge_tiles_json_outputs(
        source_paths=source_paths,
        output_path=output_path,
        notes=notes,
        source_annotations=source_annotations,
    )


def _routing_job_paths(job: Dict[str, Any], run_dir: str) -> Dict[str, str]:
    job_id = str(job.get("job_id") or "").strip() or "routing_job"
    job_root = str(job.get("output_dir") or str(_write_run_path(run_dir, "steric_jobs", job_id))).strip()
    routes_dir = os.path.join(job_root, "strategy_routes")
    debug_dir = os.path.join(job_root, "strategy_router_debug")
    summary_path = os.path.join(job_root, "strategy_router_summary.json")
    return {
        "job_root": job_root,
        "routes_dir": routes_dir,
        "debug_dir": debug_dir,
        "summary_path": summary_path,
    }


def _routing_candidate_direction(entry: Dict[str, Any]) -> str:
    if not isinstance(entry, dict):
        return ""
    for key in ("decision_direction", "delta_direction"):
        direction = str(entry.get(key) or "").strip().lower()
        if direction in {"increase", "decrease"}:
            return direction
    return ""


def _routing_candidate_label(entry: Dict[str, Any], runtime: Any) -> str:
    if not isinstance(entry, dict):
        return ""
    canonical = str(entry.get("canonical_label") or "").strip()
    if canonical:
        return canonical
    canonical_fn = getattr(runtime, "_canonical_site_label", None)
    if callable(canonical_fn):
        try:
            canonical = str(canonical_fn(entry) or "").strip()
        except Exception:
            canonical = ""
        if canonical:
            return canonical
    site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
    position = entry.get("position")
    if site_kind in {"acceptor", "donor"} and isinstance(position, int):
        return f"{site_kind}@{int(position)}"
    return ""


def _merge_routing_site_context(base: Dict[str, Any], extra: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(base) if isinstance(base, dict) else {}
    if not isinstance(extra, dict):
        return merged
    for key in (
        "chrom",
        "position",
        "site",
        "site_kind",
        "strand",
        "canonical_label",
        "label_hint",
        "uniqueness",
        "delta_direction",
        "conflict_between_objectives",
        "shared_with_beneficial",
        "unique_to_pathogenic",
        "unique_to_beneficial",
        "covers_all_isoforms",
        "all_coding",
    ):
        if merged.get(key) in (None, "", [], {}):
            value = extra.get(key)
            if value not in (None, "", [], {}):
                merged[key] = value
    for key in (
        "present_in",
        "absent_in",
        "beneficial_isoforms",
        "pathogenic_isoforms",
        "neutral_isoforms",
    ):
        values: List[str] = []
        for source in (merged.get(key), extra.get(key)):
            if not isinstance(source, list):
                continue
            values.extend(str(item).strip() for item in source if str(item).strip())
        if values:
            merged[key] = list(dict.fromkeys(values))
    exon_indices: Dict[str, Any] = {}
    for source in (merged.get("exon_indices"), extra.get("exon_indices")):
        if not isinstance(source, dict):
            continue
        for iso_label, exon_idx in source.items():
            text = str(iso_label or "").strip()
            if not text or text in exon_indices:
                continue
            exon_indices[text] = exon_idx
    if exon_indices:
        merged["exon_indices"] = exon_indices
    delta_per_isoform: Dict[str, Any] = {}
    for source in (merged.get("delta_per_isoform"), extra.get("delta_per_isoform")):
        if not isinstance(source, dict):
            continue
        for iso_label, direction in source.items():
            text = str(iso_label or "").strip()
            if not text or text in delta_per_isoform:
                continue
            delta_per_isoform[text] = direction
    if delta_per_isoform:
        merged["delta_per_isoform"] = delta_per_isoform
    return merged


def _build_route_site_context_lookup(structured_goal: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return {}
    runtime = _goal_runtime_module()
    lookup: Dict[str, Dict[str, Any]] = {}
    sources: List[Any] = [
        structured_goal.get("routing_local_steric_site_candidates"),
        structured_goal.get("routing_local_splice_site_plan"),
        structured_goal.get("steric_site_candidates"),
    ]
    strategy_analysis = structured_goal.get("splice_strategy_analysis")
    if isinstance(strategy_analysis, dict):
        context_payload = strategy_analysis.get("context_payload")
        if isinstance(context_payload, dict):
            sources.extend(
                [
                    context_payload.get("steric_site_candidates"),
                    context_payload.get("unique_splice_sites"),
                    context_payload.get("shared_splice_sites"),
                    context_payload.get("splice_site_plan"),
                ]
            )
    sources.extend(
        [
            structured_goal.get("splice_site_plan"),
        ]
    )
    for source in sources:
        if not isinstance(source, list):
            continue
        for entry in source:
            if not isinstance(entry, dict):
                continue
            label = _routing_candidate_label(entry, runtime)
            if not label:
                continue
            existing = lookup.get(label) or {}
            lookup[label] = _merge_routing_site_context(existing, entry)
    return lookup


def _routing_site_annotation(entry: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(entry, dict):
        return {}
    site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
    position = entry.get("position")
    present_in = [str(item).strip() for item in (entry.get("present_in") or []) if str(item).strip()]
    absent_in = [str(item).strip() for item in (entry.get("absent_in") or []) if str(item).strip()]
    exon_indices = entry.get("exon_indices") if isinstance(entry.get("exon_indices"), dict) else {}
    transcript_exon_labels: List[str] = []
    exon_index_pairs: List[str] = []
    for iso_label, exon_idx in exon_indices.items():
        iso_text = str(iso_label or "").strip()
        if not iso_text:
            continue
        try:
            exon_int = int(exon_idx)
        except Exception:
            transcript_exon_labels.append(iso_text)
            exon_index_pairs.append(f"{iso_text}:{exon_idx}")
            continue
        transcript_exon_labels.append(f"{iso_text}:exon{exon_int}")
        exon_index_pairs.append(f"{iso_text}:{exon_int}")
    annotation: Dict[str, Any] = {
        "site_kind": site_kind,
        "selected_site_kind": site_kind,
        "selected_present_in_transcripts": present_in,
        "selected_absent_in_transcripts": absent_in,
        "selected_exon_indices": exon_indices,
        "selected_transcript_exon_labels": transcript_exon_labels,
        "selected_exon_index_pairs": exon_index_pairs,
    }
    if isinstance(position, int):
        annotation["position"] = int(position)
        annotation["selected_site_position"] = int(position)
    canonical_exon_labels = sorted(
        {
            int(value)
            for value in exon_indices.values()
            if isinstance(value, int)
        }
    )
    if len(canonical_exon_labels) == 1:
        annotation["exon_label"] = canonical_exon_labels[0]
    chrom = str(entry.get("chrom") or "").strip()
    if chrom:
        annotation["selected_site_chrom"] = chrom
    strand = str(entry.get("strand") or "").strip()
    if strand:
        annotation["selected_site_strand"] = strand
    return annotation


def _annotate_route_json_with_site_context(
    *,
    json_path: str,
    structured_goal: Dict[str, Any],
) -> None:
    path = Path(str(json_path or "").strip())
    if not path.exists():
        return
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(payload, dict):
        return
    lookup = _build_route_site_context_lookup(structured_goal)
    if not lookup:
        return

    changed = False

    def _apply_to_target(target: Dict[str, Any], *, prefix: str = "") -> None:
        nonlocal changed
        if not isinstance(target, dict):
            return
        label = str(target.get("label") or target.get("selected_label") or "").strip()
        if not label:
            return
        context = lookup.get(label)
        if not isinstance(context, dict):
            return
        annotation = _routing_site_annotation(context)
        from .splice_reference_scope import scoped_splice_evidence
        evidence = scoped_splice_evidence({key: deepcopy(context[key]) for key in (
            "present_in", "absent_in", "uniqueness", "covers_all_isoforms") if key in context}, context, structured_goal)
        annotation.update({key: deepcopy(evidence.get(key)) for key in (
            "reference_scope", "selected_transcript_context", "shared_with_beneficial",
            "conflict_between_objectives")})
        reference = evidence["reference_scope"]
        if reference.get("compared_transcript_ids"):
            annotation["selected_present_in_transcripts"] = reference["present_in"]
            annotation["selected_absent_in_transcripts"] = reference["absent_in"]
        annotation["route_interpretation"] = (
            "Site-direction predictions; whole-isoform abundance effects and sparing of shared beneficial isoforms remain unestablished."
            if evidence.get("shared_with_beneficial") else
            "Site-direction predictions; cellular activity and whole-isoform abundance effects remain unestablished.")
        for key, value in annotation.items():
            target_key = f"{prefix}{key}" if prefix else key
            if target.get(target_key) == value:
                continue
            target[target_key] = deepcopy(value)
            changed = True

    primary_targets = payload.get("primary_targets")
    if isinstance(primary_targets, list):
        for target in primary_targets:
            _apply_to_target(target)

    def _annotate_guard(guard: Dict[str, Any]) -> None:
        nonlocal changed
        if not isinstance(guard, dict):
            return
        _apply_to_target(guard)
        uncovered = [direction for direction, field in (
            ("increase", "max_increase"), ("decrease", "max_decrease"))
            if guard.get("max_abs_delta") is None and guard.get(field) is None]
        annotations = {"unbounded_directions": uncovered,
            "assessment_scope": "Only configured site-perturbation bounds are assessed; a pass does not establish whole-isoform sparing or assess unbounded directions."}
        for key, value in annotations.items():
            if guard.get(key) != value:
                guard[key] = value
                changed = True

    for guard in payload.get("safeguards") or []:
        _annotate_guard(guard)

    rows = payload.get("rows")
    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, dict):
                continue
            selected_label = str(row.get("selected_label") or "").strip()
            if selected_label:
                temp_target = {"label": selected_label}
                _apply_to_target(temp_target)
                for key, value in temp_target.items():
                    if key == "label":
                        continue
                    if row.get(key) == value:
                        continue
                    row[key] = deepcopy(value)
                    changed = True
            row_primary_targets = row.get("primary_targets")
            if isinstance(row_primary_targets, list):
                for target in row_primary_targets:
                    _apply_to_target(target)
            for guard in row.get("safeguard_report") or []:
                _annotate_guard(guard)

    canonical_routes: List[Dict[str, Any]] = []
    if isinstance(primary_targets, list):
        for target in primary_targets:
            if not isinstance(target, dict):
                continue
            route = {
                key: deepcopy(target.get(key))
                for key in (
                    "label",
                    "direction",
                    "site_kind",
                    "position",
                    "exon_label",
                )
                if target.get(key) not in (None, "", [], {})
            }
            if route.get("label") and route.get("direction"):
                canonical_routes.append(route)
    if canonical_routes and payload.get("routes") != canonical_routes:
        payload["routes"] = canonical_routes
        changed = True

    if not changed:
        return
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def _routing_region_rows_overlap(entry: Dict[str, Any], region_rows: List[List[Any]]) -> bool:
    if not isinstance(entry, dict) or not region_rows:
        return False
    def _chrom_aliases(chrom_value: Any) -> Set[str]:
        text = str(chrom_value or "").strip()
        if not text:
            return set()
        aliases = {text}
        if text.lower().startswith("chr"):
            aliases.add(text[3:])
        else:
            aliases.add(f"chr{text}")
        return {alias for alias in aliases if alias}

    chrom = str(entry.get("chrom") or "").strip()
    position = entry.get("position")
    if not chrom or not isinstance(position, int):
        return False
    chrom_aliases = _chrom_aliases(chrom)
    for row in _normalize_region_rows(region_rows):
        row_chrom = str(row[0] or "").strip()
        row_aliases = _chrom_aliases(row_chrom)
        if not (chrom_aliases & row_aliases):
            continue
        try:
            start0 = int(row[1])
            end_bp = int(row[2])
        except Exception:
            continue
        if start0 < int(position) <= end_bp:
            return True
    return False


def _job_candidate_site_labels(job: Dict[str, Any]) -> Set[str]:
    labels: Set[str] = set()
    routing_sources = []
    for source in (
        job.get("routing_candidate_sites"),
        (job.get("selection_meta") or {}).get("routing_candidate_sites") if isinstance(job.get("selection_meta"), dict) else None,
    ):
        if isinstance(source, list):
            routing_sources.append(source)
    if routing_sources:
        for source in routing_sources:
            for item in source:
                text = str(item or "").strip()
                if text:
                    labels.add(text)
        return labels
    for source in (
        job.get("candidate_sites"),
        (job.get("selection_meta") or {}).get("candidate_sites") if isinstance(job.get("selection_meta"), dict) else None,
    ):
        if not isinstance(source, list):
            continue
        for item in source:
            text = str(item or "").strip()
            if text:
                labels.add(text)
    window_summaries = job.get("window_summaries")
    if not isinstance(window_summaries, list) and isinstance(job.get("selection_meta"), dict):
        window_summaries = job["selection_meta"].get("window_summaries")
    if isinstance(window_summaries, list):
        for window in window_summaries:
            if not isinstance(window, dict):
                continue
            for item in window.get("site_labels") or []:
                text = str(item or "").strip()
                if text:
                    labels.add(text)
    return labels


def _routing_job_requested_site_kind(job: Dict[str, Any]) -> str:
    inferred = _infer_design_program_site_kind(job)
    return inferred if inferred in {"acceptor", "donor"} else ""


def _routing_entry_site_kind(entry: Dict[str, Any]) -> str:
    if not isinstance(entry, dict):
        return ""
    site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
    return site_kind if site_kind in {"acceptor", "donor"} else ""


def _routing_entry_source_direction(entry: Dict[str, Any]) -> str:
    if not isinstance(entry, dict):
        return ""
    for key in ("source_delta_direction", "delta_direction"):
        direction = str(entry.get(key) or "").strip().lower()
        if direction:
            return direction
    return ""


def _routing_entry_is_direct_route_target(entry: Dict[str, Any]) -> bool:
    return _routing_entry_source_direction(entry) in {"increase", "decrease"}


def _prefer_direct_requested_route_entries(
    entries: List[Dict[str, Any]],
    requested_site_kind: str,
) -> List[Dict[str, Any]]:
    if requested_site_kind not in {"acceptor", "donor"} or not isinstance(entries, list) or not entries:
        return entries
    direct_entries = [
        entry
        for entry in entries
        if isinstance(entry, dict)
        if _routing_entry_site_kind(entry) in {"", requested_site_kind}
        if _routing_entry_is_direct_route_target(entry)
    ]
    return direct_entries or entries


def _splice_entry_has_route_signal(entry: Dict[str, Any]) -> bool:
    if not isinstance(entry, dict):
        return False
    direction = str(entry.get("delta_direction") or "").strip().lower()
    if direction in {"increase", "decrease"}:
        return True
    delta_per_isoform = entry.get("delta_per_isoform")
    if isinstance(delta_per_isoform, dict):
        directions = {
            str(value or "").strip().lower()
            for value in delta_per_isoform.values()
            if str(value or "").strip().lower() in {"increase", "decrease"}
        }
        if len(directions) >= 2:
            return True
    return False


def _splice_plan_objectives_from_goal(structured_goal: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    source = structured_goal.get("splice_isoform_objectives")
    direction_key = "desired_abundance"
    if not isinstance(source, list) or not source:
        source = structured_goal.get("evaluation_targets")
        direction_key = "desired_delta"
    objectives: List[Dict[str, Any]] = []
    for item in source if isinstance(source, list) else []:
        if not isinstance(item, dict):
            continue
        label = str(
            item.get("isoform_label")
            or item.get("transcript_id")
            or ""
        ).strip()
        direction = str(item.get(direction_key) or "").strip().lower()
        if direction not in {"increase", "decrease"}:
            direction = ""
        if not label and not direction:
            continue
        objective = dict(item)
        if label:
            objective["isoform_label"] = label
        if direction:
            objective["desired_abundance"] = direction
        objectives.append(objective)
    return objectives


def _repair_splice_site_plan_from_resolved_isoforms(structured_goal: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    existing_plan = structured_goal.get("splice_site_plan")
    if isinstance(existing_plan, list) and existing_plan:
        return existing_plan

    isoform_transcripts = (
        structured_goal.get("isoform_transcripts")
        if isinstance(structured_goal.get("isoform_transcripts"), dict)
        else {}
    )
    if not isoform_transcripts:
        return []

    try:
        runtime = _goal_runtime_module()
    except Exception:
        return []

    if structured_goal.get("explicit_splice_targets"):
        explicit_context_builder = getattr(runtime, "_ensure_explicit_splice_target_context", None)
        if callable(explicit_context_builder):
            try:
                explicit_context_builder(structured_goal, {})
            except Exception:
                pass
            isoform_transcripts = (
                structured_goal.get("isoform_transcripts")
                if isinstance(structured_goal.get("isoform_transcripts"), dict)
                else isoform_transcripts
            )

    compute_splice_plan = getattr(runtime, "_compute_splice_site_plan", None)
    if not callable(compute_splice_plan):
        return []
    objectives = _splice_plan_objectives_from_goal(structured_goal)
    try:
        repaired_plan, repaired_comparisons = compute_splice_plan(
            objectives,
            isoform_transcripts,
            structured_goal,
        )
    except Exception:
        return []
    if not isinstance(repaired_plan, list) or not repaired_plan:
        return []
    structured_goal["splice_site_plan"] = repaired_plan
    if isinstance(repaired_comparisons, list):
        structured_goal["splice_site_comparisons"] = repaired_comparisons
    return repaired_plan


def _explicit_splice_targets_have_coordinates(structured_goal: Any) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    raw_targets = structured_goal.get("explicit_splice_targets")
    targets = raw_targets if isinstance(raw_targets, list) else [raw_targets] if isinstance(raw_targets, dict) else []
    for target in targets:
        if not isinstance(target, dict):
            continue
        if not str(target.get("chrom") or "").strip():
            continue
        start = _coerce_positive_int(target.get("start"))
        end = _coerce_positive_int(target.get("end"))
        if start is not None and end is not None and start != end:
            return True
    return False


def _structured_goal_has_user_transcript_scope(structured_goal: Any) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    transcript_lock = structured_goal.get("transcript_lock")
    if isinstance(transcript_lock, dict) and str(transcript_lock.get("value") or "").strip():
        return True
    for key in ("transcript_id", "target_transcript_id", "reference_transcript_id", "requested_isoform_labels"):
        value = structured_goal.get(key)
        if isinstance(value, str) and re.search(r"\bENST\d+", value, flags=re.IGNORECASE):
            return True
        if isinstance(value, list) and any(re.search(r"\bENST\d+", str(item), flags=re.IGNORECASE) for item in value):
            return True
    for field in ("splice_isoform_objectives", "site_direction_hints"):
        entries = structured_goal.get(field)
        if not isinstance(entries, list):
            continue
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            for key in ("transcript_id", "isoform_label", "from_transcript_id", "to_transcript_id"):
                if re.search(r"\bENST\d+", str(entry.get(key) or ""), flags=re.IGNORECASE):
                    return True
    return False


def _seed_explicit_coordinate_splice_resolution(
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    runtime: Optional[Any] = None,
) -> Dict[str, Any]:
    if not _explicit_splice_targets_have_coordinates(structured_goal):
        return {}
    if _structured_goal_has_user_transcript_scope(structured_goal):
        return {}
    runtime = runtime or _goal_runtime_module()
    explicit_context_builder = getattr(runtime, "_ensure_explicit_splice_target_context", None)
    if callable(explicit_context_builder):
        try:
            explicit_context_builder(structured_goal, final_payload)
        except Exception:
            pass
    isoform_transcripts = (
        structured_goal.get("isoform_transcripts")
        if isinstance(structured_goal.get("isoform_transcripts"), dict)
        else {}
    )
    compute_splice_plan = getattr(runtime, "_compute_splice_site_plan", None)
    if not callable(compute_splice_plan):
        return {}
    try:
        splice_plan, splice_comparisons = compute_splice_plan(
            _splice_plan_objectives_from_goal(structured_goal),
            isoform_transcripts,
            structured_goal,
        )
    except Exception:
        return {}
    if not isinstance(splice_plan, list) or not splice_plan:
        return {}
    structured_goal["splice_site_plan"] = splice_plan
    final_payload["splice_site_plan"] = deepcopy(splice_plan)
    if isinstance(splice_comparisons, list):
        structured_goal["splice_site_comparisons"] = splice_comparisons
        final_payload["splice_site_comparisons"] = deepcopy(splice_comparisons)

    result: Dict[str, Any] = {
        "splice_site_plan": splice_plan,
        "resolved_transcript_strategy": {
            "mode": "explicit_coordinate_splice_target",
            "source": str(structured_goal.get("explicit_splice_targets_source") or "explicit_splice_targets"),
            "requires_transcript_scope": False,
        },
    }
    if isinstance(splice_comparisons, list):
        result["splice_site_comparisons"] = splice_comparisons
    if isoform_transcripts:
        final_payload["isoform_transcripts"] = deepcopy(isoform_transcripts)
        result["isoform_transcripts"] = deepcopy(isoform_transcripts)

    compute_steric_regions = getattr(runtime, "_compute_steric_regions", None)
    if callable(compute_steric_regions):
        try:
            steric_regions = compute_steric_regions(splice_plan, isoform_transcripts, structured_goal)
            if not steric_regions:
                steric_regions = compute_steric_regions([], isoform_transcripts, structured_goal)
        except Exception:
            steric_regions = None
        if isinstance(steric_regions, dict) and steric_regions:
            structured_goal["steric_regions"] = steric_regions
            final_payload["steric_regions"] = deepcopy(steric_regions)
            result["steric_regions"] = steric_regions

    notes = final_payload.setdefault("isoform_resolution_notes", {})
    if isinstance(notes, dict):
        notes["explicit_coordinate_splice_target"] = {
            "status": "seeded",
            "splice_site_count": len(splice_plan),
            "requires_transcript_scope": False,
        }
    return result


def _effective_routing_splice_site_plan(structured_goal: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    local_plan = structured_goal.get("routing_local_splice_site_plan")
    if isinstance(local_plan, list) and local_plan:
        return local_plan
    full_plan = structured_goal.get("splice_site_plan")
    return full_plan if isinstance(full_plan, list) and full_plan else []


def _job_scoped_routing_entries(
    entries: List[Dict[str, Any]],
    job: Dict[str, Any],
    runtime: Any,
) -> List[Dict[str, Any]]:
    if not isinstance(entries, list) or not entries:
        return []
    region_rows = _normalize_region_rows(job.get("region_rows"))
    candidate_labels = _job_candidate_site_labels(job)
    requested_site_kind = _routing_job_requested_site_kind(job)

    label_matches: List[Dict[str, Any]] = []
    overlap_matches: List[Dict[str, Any]] = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        entry_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
        if requested_site_kind and entry_kind and entry_kind != requested_site_kind:
            continue
        if candidate_labels:
            primary_label = _routing_candidate_label(entry, runtime)
            if primary_label in candidate_labels:
                label_matches.append(entry)
        if region_rows and _routing_region_rows_overlap(entry, region_rows):
            overlap_matches.append(entry)

    if candidate_labels and region_rows:
        overlap_ids = {id(entry) for entry in overlap_matches}
        intersected = [entry for entry in label_matches if id(entry) in overlap_ids]
        if intersected:
            return _prefer_direct_requested_route_entries(intersected, requested_site_kind)
    if label_matches:
        return _prefer_direct_requested_route_entries(label_matches, requested_site_kind)
    if overlap_matches:
        return _prefer_direct_requested_route_entries(overlap_matches, requested_site_kind)
    if not candidate_labels and not region_rows:
        filtered: List[Dict[str, Any]] = []
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            entry_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
            if requested_site_kind and entry_kind and entry_kind != requested_site_kind:
                continue
            filtered.append(entry)
        return _prefer_direct_requested_route_entries(filtered, requested_site_kind)
    return []


def _goal_for_routing_job(
    *,
    structured_goal: Dict[str, Any],
    job: Dict[str, Any],
) -> Dict[str, Any]:
    job_goal = deepcopy(structured_goal) if isinstance(structured_goal, dict) else {}
    if not isinstance(job_goal, dict):
        return {}

    runtime = _goal_runtime_module()
    splice_plan = _effective_routing_splice_site_plan(job_goal)
    strategy_analysis = (
        job_goal.get("splice_strategy_analysis")
        if isinstance(job_goal.get("splice_strategy_analysis"), dict)
        else {}
    )
    context_payload = (
        strategy_analysis.get("context_payload")
        if isinstance(strategy_analysis.get("context_payload"), dict)
        else {}
    )
    steric_candidates = context_payload.get("steric_site_candidates")
    if not isinstance(steric_candidates, list):
        steric_candidates = job_goal.get("steric_site_candidates") if isinstance(job_goal.get("steric_site_candidates"), list) else []

    requested_site_kind = _routing_job_requested_site_kind(job)
    routing_job_scope = dict(job)
    if requested_site_kind:
        routing_job_scope["site_kind"] = requested_site_kind
    local_splice_plan = _job_scoped_routing_entries(splice_plan, routing_job_scope, runtime)
    local_steric_candidates = _job_scoped_routing_entries(steric_candidates, routing_job_scope, runtime)
    routing_job = deepcopy(job)
    routing_job.update(
        {
            "job_id": str(job.get("job_id") or "").strip(),
            "job_label": str(job.get("label") or "").strip(),
            "program_id": str(job.get("program_id") or "").strip(),
            "site_kind": requested_site_kind,
            "targeting_policy": _normalize_steric_targeting_policy(
                job.get("targeting_policy") or job.get("steric_targeting_policy")
            ),
            "region_rows": _normalize_region_rows(job.get("region_rows")),
            "candidate_sites": sorted(_job_candidate_site_labels(job)),
        }
    )
    job_goal["routing_job"] = routing_job
    if local_splice_plan:
        scoped_splice_plan = deepcopy(local_splice_plan)
        for entry in scoped_splice_plan:
            if not isinstance(entry, dict):
                continue
            direction = _routing_context_expected_site_direction(entry, job_goal)
            if direction in {"increase", "decrease"}:
                entry["decision_direction"] = direction
        job_goal["routing_local_splice_site_plan"] = scoped_splice_plan
    else:
        job_goal.pop("routing_local_splice_site_plan", None)
    if local_steric_candidates:
        scoped_steric_candidates = deepcopy(local_steric_candidates)
        for entry in scoped_steric_candidates:
            if not isinstance(entry, dict):
                continue
            direction = _routing_context_expected_site_direction(entry, job_goal)
            if direction in {"increase", "decrease"}:
                entry["decision_direction"] = direction
        job_goal["routing_local_steric_site_candidates"] = scoped_steric_candidates
    else:
        job_goal.pop("routing_local_steric_site_candidates", None)
    return job_goal


def _routing_catalog_entries(structured_goal: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    sources: List[Any] = [
        structured_goal.get("routing_local_splice_site_plan"),
        structured_goal.get("routing_local_steric_site_candidates"),
        structured_goal.get("steric_site_candidates"),
    ]
    strategy_analysis = structured_goal.get("splice_strategy_analysis")
    if isinstance(strategy_analysis, dict):
        context_payload = strategy_analysis.get("context_payload")
        if isinstance(context_payload, dict):
            sources.extend(
                [
                    context_payload.get("steric_site_candidates"),
                    context_payload.get("splice_site_plan"),
                ]
            )
    sources.extend(
        [
            structured_goal.get("splice_site_plan"),
        ]
    )
    merged: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    runtime = _goal_runtime_module()
    for source in sources:
        if not isinstance(source, list):
            continue
        for entry in source:
            if not isinstance(entry, dict):
                continue
            label = _routing_candidate_label(entry, runtime)
            if not label:
                continue
            if label in seen:
                # A short candidate projection must not erase the provenance
                # that distinguishes requested abundance from predicted effect.
                prior = next(item for item in merged if _routing_candidate_label(item, runtime) == label)
                for key in ("delta_per_isoform_scope", "isoform_abundance_objectives",
                            "directional_evidence_status", "directional_evidence_note"):
                    if key in entry:
                        prior.setdefault(key, deepcopy(entry[key]))
                continue
            seen.add(label)
            merged.append(deepcopy(entry))
    return merged


def _parse_route_delta_labels(value: Any) -> List[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    if not isinstance(value, str):
        return []
    return [part.strip() for part in value.split(",") if part.strip()]


def _parse_route_delta_floats(value: Any) -> List[Optional[float]]:
    items: List[Any]
    if isinstance(value, list):
        items = value
    elif isinstance(value, str):
        items = [part.strip() for part in value.split(",")]
    else:
        return []
    parsed: List[Optional[float]] = []
    for item in items:
        if item in (None, "", "NA", "nan", "NaN"):
            parsed.append(None)
            continue
        try:
            parsed.append(float(item))
        except Exception:
            parsed.append(None)
    return parsed


def _route_site_effect_value(del_val: Optional[float], rep_val: Optional[float]) -> Optional[float]:
    candidates = [float(value) for value in (del_val, rep_val) if isinstance(value, (int, float))]
    if not candidates:
        return None
    return max(candidates, key=lambda value: abs(float(value)))


def _routing_label_site_parts(label: str) -> Tuple[str, Optional[int]]:
    text = str(label or "").strip()
    match = re.match(r"^(acceptor|donor)@(-?\d+)$", text)
    if not match:
        return "", None
    try:
        return match.group(1), int(match.group(2))
    except Exception:
        return "", None


def _routing_entry_exon_indices(entry: Dict[str, Any]) -> Set[int]:
    indices: Set[int] = set()
    if not isinstance(entry, dict):
        return indices
    exon_indices = entry.get("exon_indices")
    values: List[Any] = []
    if isinstance(exon_indices, dict):
        values = list(exon_indices.values())
    elif isinstance(exon_indices, list):
        values = list(exon_indices)
    for value in values:
        try:
            index = int(value)
        except Exception:
            continue
        if index >= 0:
            indices.add(index)
    return indices


def _routing_entry_position(entry: Dict[str, Any]) -> Optional[int]:
    if not isinstance(entry, dict):
        return None
    value = entry.get("position")
    try:
        return int(value)
    except Exception:
        return None


def _routing_anchor_source_entries(structured_goal: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    local_sources: List[Any] = [
        structured_goal.get("routing_local_splice_site_plan"),
        structured_goal.get("routing_local_steric_site_candidates"),
    ]
    sources: List[Any] = [
        structured_goal.get("steric_site_candidates"),
    ]
    strategy_analysis = structured_goal.get("splice_strategy_analysis")
    if isinstance(strategy_analysis, dict):
        context_payload = strategy_analysis.get("context_payload")
        if isinstance(context_payload, dict):
            sources.extend(
                [
                    context_payload.get("steric_site_candidates"),
                    context_payload.get("splice_site_plan"),
                ]
            )
    sources.extend(
        [
            structured_goal.get("splice_site_plan"),
        ]
    )
    # A local job is an execution boundary. Otherwise candidate projections
    # and the selected site plan are complementary: a projection of primary
    # sites must not erase an explicitly selected secondary route. Preserve
    # source order for same-site direction precedence and retain risk metadata.
    if any(isinstance(source, list) and source for source in local_sources):
        sources = local_sources
    runtime = _goal_runtime_module()
    anchors: List[Dict[str, Any]] = []
    seen_labels: Set[str] = set()
    for source in sources:
        if not isinstance(source, list):
            continue
        for entry in source:
            if not isinstance(entry, dict):
                continue
            label = _routing_candidate_label(entry, runtime)
            if not label or label in seen_labels:
                continue
            direction = _routing_candidate_direction(entry)
            delta_direction = str(entry.get("delta_direction") or "").strip().lower()
            if direction not in {"increase", "decrease"} and delta_direction not in {"increase", "decrease"}:
                continue
            seen_labels.add(label)
            anchors.append(dict(entry))
    return anchors


def _objective_exon_label_set(objective: Dict[str, Any]) -> Set[int]:
    labels: Set[int] = set()
    if not isinstance(objective, dict):
        return labels
    raw_values: List[Any] = []
    for key in ("exon_labels", "target_exons", "exons", "focus_exons"):
        value = objective.get(key)
        if isinstance(value, list):
            raw_values.extend(value)
        elif value not in (None, "", [], {}):
            raw_values.append(value)
    for key in ("exon_label", "target_exon", "focus_exon"):
        value = objective.get(key)
        if value not in (None, "", [], {}):
            raw_values.append(value)
    for value in raw_values:
        try:
            label = int(value)
        except Exception:
            continue
        if label >= 0:
            labels.add(label)
    return labels


def _strategy_label_for_exon_set(exon_labels: Set[int], objective: Dict[str, Any]) -> str:
    explicit = str(
        objective.get("strategy_label")
        or objective.get("route_strategy_label")
        or objective.get("label")
        or ""
    ).strip()
    if explicit:
        return explicit
    ordered = sorted(int(item) for item in exon_labels)
    if len(ordered) >= 2:
        return "exons " + "-".join(str(item) for item in ordered) + " co-skipping"
    if len(ordered) == 1:
        return f"exon {ordered[0]} skipping"
    return "explicit splice objective"


def _explicit_splice_objective_fallback_routing_entries(
    structured_goal: Dict[str, Any],
    runtime: Any,
) -> List[Dict[str, Any]]:
    """Build low-confidence route targets from explicit exon objectives when model deltas are flat."""
    if not isinstance(structured_goal, dict):
        return []
    splice_plan = _effective_routing_splice_site_plan(structured_goal)
    if not splice_plan:
        return []

    entries: List[Dict[str, Any]] = []
    entries_by_label_direction: Dict[Tuple[str, str], Dict[str, Any]] = {}
    objectives = _splice_plan_objectives_from_goal(structured_goal)
    for objective_index, objective in enumerate(objectives):
        if not isinstance(objective, dict):
            continue
        exon_labels = _objective_exon_label_set(objective)
        if not exon_labels:
            continue
        direction = str(
            objective.get("desired_abundance")
            or objective.get("desired_delta")
            or ""
        ).strip().lower()
        if direction not in {"increase", "decrease"}:
            effect = str(
                objective.get("desired_effect")
                or objective.get("direction")
                or objective.get("objective_kind")
                or ""
            ).strip().lower()
            direction = "decrease" if "skip" in effect or "decrease" in effect else ""
        if direction not in {"increase", "decrease"}:
            continue
        effect_text = " ".join(
            str(objective.get(key) or "")
            for key in ("desired_effect", "direction", "objective_kind", "rationale")
        ).lower()
        multi_exon = len(exon_labels) >= 2
        if not multi_exon:
            objective_kind = str(objective.get("objective_kind") or "").strip().lower()
            objective_scope = str(objective.get("objective_scope") or "").strip().lower()
            if objective_kind == "default_exon_splice_context" or objective_scope == "specific_transcript":
                continue
            if "skip" not in effect_text:
                continue
        strategy_label = _strategy_label_for_exon_set(exon_labels, objective)
        for plan_index, entry in enumerate(splice_plan):
            if not isinstance(entry, dict):
                continue
            entry_exons = _routing_entry_exon_indices(entry)
            if not entry_exons or not (entry_exons & exon_labels):
                continue
            label = _routing_candidate_label(entry, runtime)
            if not label:
                continue
            key = (label, direction)
            existing = entries_by_label_direction.get(key)
            if isinstance(existing, dict):
                strategy_labels = existing.get("target_strategy_labels")
                if not isinstance(strategy_labels, list):
                    strategy_labels = [str(existing.get("target_strategy_label") or "").strip()]
                strategy_labels = [item for item in strategy_labels if item]
                if strategy_label and strategy_label not in strategy_labels:
                    strategy_labels.append(strategy_label)
                if strategy_labels:
                    existing["target_strategy_labels"] = strategy_labels
                    existing["target_strategy_label"] = "; ".join(strategy_labels)
                existing_exons = set(_objective_exon_label_set({"exon_labels": existing.get("target_exon_labels")}))
                merged_exons = sorted(existing_exons | exon_labels)
                if merged_exons:
                    existing["target_exon_labels"] = merged_exons
                continue
            annotated = dict(entry)
            annotated["decision_direction"] = direction
            annotated["delta_direction"] = direction
            annotated["routing_selection_source"] = "explicit_splice_objective_fallback"
            annotated["explicit_objective_fallback"] = True
            annotated["allow_zero_delta_fallback"] = True
            annotated["target_strategy_label"] = strategy_label
            annotated["target_strategy_labels"] = [strategy_label] if strategy_label else []
            annotated["target_exon_labels"] = sorted(exon_labels)
            annotated["strategy_objective_index"] = objective_index
            annotated["strategy_plan_index"] = plan_index
            annotated.setdefault("observed_support", 0)
            annotated.setdefault("observed_directional_support", 0)
            annotated.setdefault("observed_opposite_support", 0)
            annotated.setdefault("observed_mean_effect", 0.0)
            annotated.setdefault("observed_max_abs_delta", 0.0)
            annotated.setdefault("observed_directional_max_delta", 0.0)
            annotated.setdefault("observed_opposite_max_delta", 0.0)
            annotated["ranking_confidence"] = "low"
            annotated["ranking_rationale"] = (
                f"Explicit user-requested {strategy_label} target retained even though "
                "the splice model produced flat local deltas; use route rows as a proximity/off-target audit."
            )
            entries.append(annotated)
            entries_by_label_direction[key] = annotated

    entries.sort(
        key=lambda entry: (
            int(entry.get("strategy_objective_index") or 0),
            int(entry.get("strategy_plan_index") or 0),
            str(_routing_candidate_label(entry, runtime) or ""),
        )
    )
    return entries


def _routing_anchor_priority_group(entry: Dict[str, Any]) -> int:
    if not isinstance(entry, dict):
        return 9
    direction = _routing_candidate_direction(entry)
    pathogenic_isoforms = entry.get("pathogenic_isoforms") if isinstance(entry.get("pathogenic_isoforms"), list) else []
    beneficial_isoforms = entry.get("beneficial_isoforms") if isinstance(entry.get("beneficial_isoforms"), list) else []
    unique_to_pathogenic = bool(entry.get("unique_to_pathogenic"))
    unique_to_beneficial = bool(entry.get("unique_to_beneficial"))
    net_effect_hint = str(entry.get("net_effect_hint") or "").strip().lower()
    if direction == "decrease" and (
        unique_to_pathogenic
        or pathogenic_isoforms
        or net_effect_hint in {"pathogenic_only", "pathogenic_shared"}
    ):
        return 0
    if direction == "increase" and (
        unique_to_beneficial
        or beneficial_isoforms
        or net_effect_hint in {"beneficial_only", "beneficial_shared"}
    ):
        return 2
    return 1


def _routing_contextual_distance_to_anchors(
    entry: Dict[str, Any],
    anchors: List[Dict[str, Any]],
) -> Tuple[Optional[int], Optional[int]]:
    if not isinstance(entry, dict) or not isinstance(anchors, list) or not anchors:
        return None, None
    entry_chrom = str(entry.get("chrom") or "").strip()
    entry_pos = _routing_entry_position(entry)
    entry_exons = _routing_entry_exon_indices(entry)
    best_exon_distance: Optional[int] = None
    best_position_distance: Optional[int] = None
    for anchor in anchors:
        if not isinstance(anchor, dict):
            continue
        anchor_chrom = str(anchor.get("chrom") or "").strip()
        if entry_chrom and anchor_chrom and entry_chrom != anchor_chrom:
            continue
        anchor_pos = _routing_entry_position(anchor)
        anchor_exons = _routing_entry_exon_indices(anchor)
        if entry_exons and anchor_exons:
            exon_distance = min(abs(int(a) - int(b)) for a in entry_exons for b in anchor_exons)
            if best_exon_distance is None or exon_distance < best_exon_distance:
                best_exon_distance = exon_distance
        if entry_pos is not None and anchor_pos is not None:
            pos_distance = abs(int(entry_pos) - int(anchor_pos))
            if best_position_distance is None or pos_distance < best_position_distance:
                best_position_distance = pos_distance
    return best_exon_distance, best_position_distance


def _objective_relevant_routing_entries(
    structured_goal: Dict[str, Any],
    observed_entries: List[Dict[str, Any]],
    runtime: Any,
) -> List[Dict[str, Any]]:
    if not isinstance(observed_entries, list) or not observed_entries:
        return []
    anchor_sources = _routing_anchor_source_entries(structured_goal)
    if not anchor_sources:
        return observed_entries

    observed_by_label: Dict[str, Dict[str, Any]] = {}
    for entry in observed_entries:
        if not isinstance(entry, dict):
            continue
        label = _routing_candidate_label(entry, runtime)
        if label and label not in observed_by_label:
            observed_by_label[label] = entry

    anchor_entries: List[Dict[str, Any]] = []
    for source_entry in anchor_sources:
        label = _routing_candidate_label(source_entry, runtime)
        if not label:
            continue
        if observed_by_label and label not in observed_by_label:
            continue
        merged = dict(observed_by_label.get(label) or source_entry)
        for key, value in source_entry.items():
            merged.setdefault(key, value)
        merged["routing_selection_source"] = "anchor_candidate"
        anchor_entries.append(merged)
    if not anchor_entries:
        return observed_entries

    anchor_entries = sorted(
        anchor_entries,
        key=lambda entry: (
            _routing_anchor_priority_group(entry),
            str(_routing_candidate_label(entry, runtime) or ""),
        ),
    )
    routing_job = structured_goal.get("routing_job") if isinstance(structured_goal.get("routing_job"), dict) else {}
    requested_site_kind = _routing_job_requested_site_kind(routing_job)
    direct_requested_anchor_entries = _prefer_direct_requested_route_entries(anchor_entries, requested_site_kind)
    suppress_contextual_fallback = (
        requested_site_kind in {"acceptor", "donor"}
        and any(_routing_entry_is_direct_route_target(entry) for entry in direct_requested_anchor_entries)
    )
    anchor_entries = direct_requested_anchor_entries
    primary_anchors = [entry for entry in anchor_entries if _routing_anchor_priority_group(entry) == 0]
    secondary_anchors = [entry for entry in anchor_entries if _routing_anchor_priority_group(entry) != 0]
    anchor_reference = primary_anchors or anchor_entries
    preferred_context_directions = {
        _routing_candidate_direction(entry)
        for entry in anchor_reference
        if _routing_candidate_direction(entry) in {"increase", "decrease"}
    }
    anchor_exon_indices: Set[int] = set()
    dominant_anchor_site_kind = ""
    for entry in anchor_reference:
        anchor_exon_indices.update(_routing_entry_exon_indices(entry))
    anchor_site_kinds = [
        str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
        for entry in anchor_reference
        if str(entry.get("site") or entry.get("site_kind") or "").strip().lower() in {"acceptor", "donor"}
    ]
    if len(set(anchor_site_kinds)) == 1 and anchor_site_kinds:
        dominant_anchor_site_kind = anchor_site_kinds[0]
    max_contextual_goals = _coerce_positive_int(structured_goal.get("routing_contextual_goal_limit")) or 3
    max_exon_distance = _coerce_positive_int(structured_goal.get("routing_contextual_exon_distance")) or 1
    max_position_distance = _coerce_positive_int(structured_goal.get("routing_contextual_position_window_bp")) or 1000
    anchor_labels = {
        _routing_candidate_label(entry, runtime)
        for entry in anchor_entries
        if _routing_candidate_label(entry, runtime)
    }

    contextual_groups: Dict[Any, List[Dict[str, Any]]] = {}
    contextual_group_order: Dict[Any, Tuple[int, int, str]] = {}
    for entry in observed_entries:
        if suppress_contextual_fallback:
            break
        if not isinstance(entry, dict):
            continue
        label = _routing_candidate_label(entry, runtime)
        if not label or label in anchor_labels:
            continue
        source_delta_direction = str(
            entry.get("source_delta_direction") or entry.get("delta_direction") or ""
        ).strip().lower()
        if source_delta_direction != "context":
            continue
        direction = _routing_candidate_direction(entry)
        if preferred_context_directions and direction not in preferred_context_directions:
            continue
        exon_distance, position_distance = _routing_contextual_distance_to_anchors(entry, anchor_reference)
        if exon_distance is None and position_distance is None:
            continue
        if exon_distance is not None and exon_distance > max_exon_distance:
            if position_distance is None or position_distance > max_position_distance:
                continue
        elif exon_distance is None and position_distance is not None and position_distance > max_position_distance:
            continue
        entry_with_meta = dict(entry)
        entry_with_meta["routing_selection_source"] = "contextual_fallback"
        entry_exons = _routing_entry_exon_indices(entry)
        if entry_exons and anchor_exon_indices:
            representative_exon = min(
                entry_exons,
                key=lambda idx: min(abs(int(idx) - int(anchor_idx)) for anchor_idx in anchor_exon_indices),
            )
            group_key: Any = ("exon", representative_exon)
            contextual_group_order[group_key] = (
                representative_exon,
                _routing_entry_position(entry) if _routing_entry_position(entry) is not None else 999999999,
                label,
            )
        else:
            group_key = ("label", label)
            contextual_group_order[group_key] = (
                exon_distance if exon_distance is not None else 999999,
                _routing_entry_position(entry) if _routing_entry_position(entry) is not None else 999999999,
                label,
            )
        contextual_groups.setdefault(group_key, []).append(entry_with_meta)

    contextual_entries: List[Dict[str, Any]] = []
    for group_key in sorted(contextual_groups.keys(), key=lambda item: contextual_group_order.get(item, (999999, 999999999, str(item)))):
        group_entries = contextual_groups.get(group_key) or []
        if not group_entries:
            continue
        representative_exon = group_key[1] if isinstance(group_key, tuple) and len(group_key) > 1 and group_key[0] == "exon" else None
        preferred_site_kind = ""
        if (
            isinstance(representative_exon, int)
            and dominant_anchor_site_kind in {"acceptor", "donor"}
            and anchor_exon_indices
        ):
            anchor_min_exon = min(anchor_exon_indices)
            if representative_exon < anchor_min_exon:
                preferred_site_kind = dominant_anchor_site_kind
            else:
                preferred_site_kind = "acceptor" if dominant_anchor_site_kind == "donor" else "donor"
        def _group_rank(entry: Dict[str, Any]) -> Tuple[int, float, float, str]:
            entry_exons = _routing_entry_exon_indices(entry)
            site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
            preferred_kind_rank = 1
            if preferred_site_kind and site_kind in {"acceptor", "donor"} and site_kind == preferred_site_kind:
                preferred_kind_rank = 0
            elif (
                dominant_anchor_site_kind
                and entry_exons
                and anchor_exon_indices
                and (entry_exons & anchor_exon_indices)
                and site_kind in {"acceptor", "donor"}
                and site_kind != dominant_anchor_site_kind
            ):
                preferred_kind_rank = 0
            return (
                preferred_kind_rank,
                -float(entry.get("observed_support") or 0.0),
                -float(entry.get("observed_max_abs_delta") or 0.0),
                str(_routing_candidate_label(entry, runtime) or ""),
            )
        contextual_entries.append(sorted(group_entries, key=_group_rank)[0])
        if len(contextual_entries) >= max_contextual_goals:
            break

    job_candidate_labels = _job_candidate_site_labels(routing_job)
    additional_job_candidate_entries: List[Dict[str, Any]] = []
    if job_candidate_labels:
        for entry in observed_entries:
            if not isinstance(entry, dict):
                continue
            label = _routing_candidate_label(entry, runtime)
            if not label or label in anchor_labels or label not in job_candidate_labels:
                continue
            direction = _routing_candidate_direction(entry)
            if direction not in {"increase", "decrease"}:
                continue
            entry_with_meta = dict(entry)
            entry_with_meta["routing_selection_source"] = "job_candidate_observed"
            additional_job_candidate_entries.append(entry_with_meta)
        additional_job_candidate_entries.sort(
            key=lambda entry: (
                -float(entry.get("observed_max_abs_delta") or 0.0),
                -int(entry.get("observed_support") or 0),
                str(_routing_candidate_label(entry, runtime) or ""),
            )
        )

    selected: List[Dict[str, Any]] = []
    seen_keys: Set[Tuple[str, str]] = set()
    for entry in [*primary_anchors, *contextual_entries, *additional_job_candidate_entries, *secondary_anchors]:
        if not isinstance(entry, dict):
            continue
        label = _routing_candidate_label(entry, runtime)
        direction = _routing_candidate_direction(entry)
        if not label or direction not in {"increase", "decrease"}:
            continue
        key = (label, direction)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        selected.append(entry)
    return selected


def _routing_effect_thresholds(structured_goal: Dict[str, Any]) -> Tuple[float, int]:
    min_abs = structured_goal.get("routing_site_effect_min_abs")
    min_support = structured_goal.get("routing_site_effect_min_support")
    try:
        min_abs_value = float(min_abs) if min_abs not in (None, "") else 0.001
    except Exception:
        min_abs_value = 0.001
    try:
        min_support_value = int(min_support) if min_support not in (None, "") else 2
    except Exception:
        min_support_value = 2
    return max(0.0, min_abs_value), max(1, min_support_value)


def _observed_routing_targets_from_scored_json(
    *,
    structured_goal: Dict[str, Any],
    scored_path: str,
    runtime: Any,
) -> List[Dict[str, Any]]:
    scored_obj = Path(str(scored_path or "")).expanduser()
    if not scored_obj.exists():
        return []
    try:
        payload = _read_json(scored_obj)
    except Exception:
        return []
    rows = payload.get("rows")
    if not isinstance(rows, list) or not rows:
        return []

    min_abs_effect, min_support = _routing_effect_thresholds(structured_goal)
    catalog_entries = _routing_catalog_entries(structured_goal)
    catalog_by_label: Dict[str, Dict[str, Any]] = {}
    for entry in catalog_entries:
        label = _routing_candidate_label(entry, runtime)
        if label and label not in catalog_by_label:
            catalog_by_label[label] = entry

    observed: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        labels = _parse_route_delta_labels(row.get("delta_names"))
        deltas_del = _parse_route_delta_floats(row.get("delta_deletion"))
        deltas_rep = _parse_route_delta_floats(row.get("delta_replacement"))
        for idx, label in enumerate(labels):
            del_val = deltas_del[idx] if idx < len(deltas_del) else None
            rep_val = deltas_rep[idx] if idx < len(deltas_rep) else None
            effect_value = _route_site_effect_value(del_val, rep_val)
            if effect_value is None:
                continue
            stats = observed.setdefault(
                label,
                {
                    "support": 0,
                    "positive_support": 0,
                    "negative_support": 0,
                    "sum_effect": 0.0,
                    "max_positive": 0.0,
                    "max_negative": 0.0,
                    "max_abs": 0.0,
                },
            )
            stats["support"] += 1
            stats["sum_effect"] += float(effect_value)
            stats["max_abs"] = max(float(stats["max_abs"]), abs(float(effect_value)))
            if float(effect_value) > 0:
                stats["positive_support"] += 1
                stats["max_positive"] = max(float(stats["max_positive"]), float(effect_value))
            elif float(effect_value) < 0:
                stats["negative_support"] += 1
                stats["max_negative"] = max(float(stats["max_negative"]), abs(float(effect_value)))

    routed_entries: List[Dict[str, Any]] = []
    for label, stats in observed.items():
        support = int(stats["support"])
        max_abs = float(stats["max_abs"])
        if max_abs < min_abs_effect:
            continue
        if support < min_support and max_abs < (min_abs_effect * 5.0):
            continue
        base_entry = dict(catalog_by_label.get(label) or {})
        preferred_direction = _routing_context_expected_site_direction(base_entry, structured_goal)
        if preferred_direction not in {"increase", "decrease"}:
            preferred_direction = _routing_candidate_direction(base_entry)
        original_delta_direction = str(base_entry.get("delta_direction") or "").strip().lower()
        max_positive = float(stats["max_positive"])
        max_negative = float(stats["max_negative"])
        mean_effect = float(stats["sum_effect"]) / max(1, support)
        direction = ""
        directional_max = 0.0
        opposite_max = 0.0
        directional_support = 0
        opposite_support = 0
        if preferred_direction == "increase" and max_positive >= min_abs_effect:
            direction = "increase"
            directional_max = max_positive
            opposite_max = max_negative
            directional_support = int(stats["positive_support"])
            opposite_support = int(stats["negative_support"])
        elif preferred_direction == "decrease" and max_negative >= min_abs_effect:
            direction = "decrease"
            directional_max = max_negative
            opposite_max = max_positive
            directional_support = int(stats["negative_support"])
            opposite_support = int(stats["positive_support"])
        elif preferred_direction in {"increase", "decrease"}:
            continue
        elif max_positive >= min_abs_effect and max_positive > (max_negative * 1.1):
            direction = "increase"
            directional_max = max_positive
            opposite_max = max_negative
            directional_support = int(stats["positive_support"])
            opposite_support = int(stats["negative_support"])
        elif max_negative >= min_abs_effect and max_negative > (max_positive * 1.1):
            direction = "decrease"
            directional_max = max_negative
            opposite_max = max_positive
            directional_support = int(stats["negative_support"])
            opposite_support = int(stats["positive_support"])
        elif abs(mean_effect) >= min_abs_effect:
            direction = "increase" if mean_effect > 0 else "decrease"
            if direction == "increase":
                directional_max = max_positive
                opposite_max = max_negative
                directional_support = int(stats["positive_support"])
                opposite_support = int(stats["negative_support"])
            else:
                directional_max = max_negative
                opposite_max = max_positive
                directional_support = int(stats["negative_support"])
                opposite_support = int(stats["positive_support"])
        if direction not in {"increase", "decrease"}:
            continue

        site_kind, position = _routing_label_site_parts(label)
        if "canonical_label" not in base_entry:
            base_entry["canonical_label"] = label
        if "label" not in base_entry:
            base_entry["label"] = label
        if site_kind:
            base_entry.setdefault("site", site_kind)
            base_entry.setdefault("site_kind", site_kind)
        if isinstance(position, int):
            base_entry.setdefault("position", position)
        base_entry["decision_direction"] = direction
        if original_delta_direction:
            base_entry["source_delta_direction"] = original_delta_direction
        else:
            base_entry["source_delta_direction"] = direction
            base_entry["delta_direction"] = direction
        base_entry["observed_support"] = support
        base_entry["observed_directional_support"] = directional_support
        base_entry["observed_opposite_support"] = opposite_support
        base_entry["observed_mean_effect"] = mean_effect
        base_entry["observed_max_abs_delta"] = max_abs
        base_entry["observed_directional_max_delta"] = directional_max
        base_entry["observed_opposite_max_delta"] = opposite_max
        routed_entries.append(base_entry)

    routed_entries.sort(
        key=lambda entry: (
            -float(entry.get("observed_directional_max_delta") or 0.0),
            -int(entry.get("observed_support") or 0),
            str(_routing_candidate_label(entry, runtime) or ""),
        )
    )
    return routed_entries


def _routing_target_entries(
    structured_goal: Dict[str, Any],
    *,
    scored_path: str = "",
) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    runtime = _goal_runtime_module()
    if isinstance(scored_path, str) and scored_path.strip():
        observed_entries = _observed_routing_targets_from_scored_json(
            structured_goal=structured_goal,
            scored_path=scored_path,
            runtime=runtime,
        )
        if observed_entries:
            prioritized = _objective_relevant_routing_entries(structured_goal, observed_entries, runtime)
            if prioritized:
                return prioritized
            if _routing_anchor_source_entries(structured_goal):
                return []
            return observed_entries
        fallback_entries = _explicit_splice_objective_fallback_routing_entries(structured_goal, runtime)
        if fallback_entries:
            return fallback_entries
        return []
    return _routing_catalog_entries(structured_goal)


def _routing_llm_excerpt(value: Any, limit: int = 1800) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if len(text) <= limit:
        return text
    return text[:limit].rstrip() + "..."


def _routing_goal_labels(labels: Any) -> List[str]:
    items = labels if isinstance(labels, list) else []
    normalized: List[str] = []
    for item in items:
        label = str(item or "").strip()
        if label and label not in normalized:
            normalized.append(label)
    return normalized


def _route_isoform_key(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip().lower())


def _route_isoform_objective_direction_map(structured_goal: Dict[str, Any]) -> Dict[str, str]:
    if not isinstance(structured_goal, dict):
        return {}
    objective_map: Dict[str, str] = {}
    for objective in _splice_plan_objectives_from_goal(structured_goal):
        if not isinstance(objective, dict):
            continue
        direction = str(objective.get("desired_abundance") or "").strip().lower()
        if direction not in {"increase", "decrease"}:
            continue
        for key in (
            objective.get("isoform_label"),
            objective.get("label"),
            objective.get("transcript_id"),
            objective.get("transcript"),
        ):
            normalized = _route_isoform_key(key)
            if normalized:
                objective_map[normalized] = direction
    for label in _routing_goal_labels(structured_goal.get("increase_isoforms")):
        objective_map[_route_isoform_key(label)] = "increase"
    for label in _routing_goal_labels(structured_goal.get("decrease_isoforms")):
        objective_map[_route_isoform_key(label)] = "decrease"
    return objective_map


def _route_goal_splice_effect(structured_goal: Dict[str, Any]) -> str:
    if not isinstance(structured_goal, dict):
        return ""
    for key in ("desired_effect", "desired_splice_effect", "desired_delta", "direction", "objective_type", "objective"):
        effect = _normalized_splice_effect(structured_goal.get(key))
        if effect:
            return effect

    containers: List[Any] = []
    for key in (
        "splice_isoform_objectives",
        "isoform_objectives",
        "isoform_modulation_objectives",
        "evaluation_targets",
        "exon_targets",
        "objectives",
        "splice_objectives",
    ):
        value = structured_goal.get(key)
        if isinstance(value, list):
            containers.extend(value)
        elif isinstance(value, dict):
            containers.append(value)
    for item in containers:
        if not isinstance(item, dict):
            continue
        for key in (
            "desired_splice_effect",
            "desired_effect",
            "desired_delta",
            "direction",
            "objective",
            "objective_kind",
            "objective_type",
            "type",
        ):
            effect = _normalized_splice_effect(item.get(key))
            if effect:
                return effect
    return ""


def _route_goal_exon_labels(structured_goal: Dict[str, Any]) -> Set[int]:
    labels: Set[int] = set()
    if not isinstance(structured_goal, dict):
        return labels
    sources: List[Any] = [structured_goal.get("exon_label"), structured_goal.get("exon_labels")]
    for key in ("evaluation_targets", "exon_targets", "splice_isoform_objectives", "objectives", "splice_objectives"):
        value = structured_goal.get(key)
        items = value if isinstance(value, list) else [value] if isinstance(value, dict) else []
        for item in items:
            if not isinstance(item, dict):
                continue
            sources.extend([item.get("exon_label"), item.get("exon_labels")])
    for source in sources:
        values = source if isinstance(source, list) else [source]
        for value in values:
            exon_int = _coerce_exon_label_int(value)
            if exon_int is not None:
                labels.add(int(exon_int))
    return labels


def _routing_context_expected_site_direction(
    entry: Dict[str, Any],
    structured_goal: Dict[str, Any],
) -> str:
    if not isinstance(entry, dict):
        return ""
    scoped_direction = str(entry.get("decision_direction") or "").strip().lower()
    source_direction = str(entry.get("source_delta_direction") or "").strip().lower()
    if scoped_direction in {"increase", "decrease"} and source_direction != "context":
        return scoped_direction
    routing_job = (
        structured_goal.get("routing_job")
        if isinstance(structured_goal.get("routing_job"), dict)
        else {}
    )
    delta_map = _route_delta_per_isoform(entry)
    normalized_delta_map = {
        _route_isoform_key(identity): direction
        for identity, direction in delta_map.items()
        if _route_isoform_key(identity)
    }
    selection_meta = (
        routing_job.get("selection_meta")
        if isinstance(routing_job.get("selection_meta"), dict)
        else {}
    )
    for source in (routing_job, selection_meta):
        for key in ("isoform_label", "transcript_id"):
            direction = normalized_delta_map.get(_route_isoform_key(source.get(key)))
            if direction in {"increase", "decrease"}:
                return direction

    # An exact per-isoform value is narrower than the aggregate site direction.
    # Without an exact job identity, the site's typed aggregate direction remains
    # authoritative for candidate routing.
    explicit_direction = str(entry.get("delta_direction") or "").strip().lower()
    if explicit_direction in {"increase", "decrease"}:
        return explicit_direction
    requested_direction = str(routing_job.get("desired_delta") or "").strip().lower()
    if requested_direction in {"increase", "decrease"}:
        return requested_direction

    directions = {direction for direction in delta_map.values() if direction in {"increase", "decrease"}}
    if len(directions) == 1:
        return next(iter(directions))

    site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
    if site_kind in {"acceptor", "donor"}:
        effect = _route_goal_splice_effect(structured_goal)
        goal_exons = _route_goal_exon_labels(structured_goal)
        entry_exons = _routing_entry_exon_indices(entry)
        hits_goal_exon = bool(goal_exons and entry_exons and (goal_exons & entry_exons))
        if hits_goal_exon:
            if effect == "inclusion":
                return "increase"
            if effect == "skipping":
                return "decrease"
    return ""


def _route_delta_per_isoform(entry: Dict[str, Any]) -> Dict[str, str]:
    if not isinstance(entry, dict):
        return {}
    if entry.get("delta_per_isoform_scope") == "desired_objectives_not_predicted_effects":
        return {}
    raw = entry.get("delta_per_isoform")
    if not isinstance(raw, dict):
        return {}
    normalized: Dict[str, str] = {}
    for isoform, direction_raw in raw.items():
        isoform_label = str(isoform or "").strip()
        direction = str(direction_raw or "").strip().lower()
        if not isoform_label or direction not in {"increase", "decrease"}:
            continue
        normalized[isoform_label] = direction
    return normalized


def _route_isoform_alignment(entry: Dict[str, Any], structured_goal: Dict[str, Any]) -> Dict[str, Any]:
    expected_site_direction = _routing_context_expected_site_direction(entry, structured_goal)
    candidate_direction = _routing_candidate_direction(entry)
    if (
        expected_site_direction in {"increase", "decrease"}
        and candidate_direction in {"increase", "decrease"}
        and candidate_direction != expected_site_direction
    ):
        conflicts = _routing_goal_labels(entry.get("present_in")) or list(_route_delta_per_isoform(entry).keys())
        return {
            "status": "conflicting",
            "matched_isoforms": [],
            "conflicting_isoforms": conflicts,
            "expected_site_direction": expected_site_direction,
        }

    objective_map = _route_isoform_objective_direction_map(structured_goal)
    delta_map = _route_delta_per_isoform(entry)
    matches: List[str] = []
    conflicts: List[str] = []
    for isoform, direction in delta_map.items():
        expected = objective_map.get(_route_isoform_key(isoform))
        if not expected:
            continue
        if direction == expected:
            matches.append(isoform)
        else:
            conflicts.append(isoform)
    if matches and not conflicts:
        status = "aligned"
    elif conflicts:
        status = "conflicting"
    else:
        status = "unknown"
    return {
        "status": status,
        "matched_isoforms": matches,
        "conflicting_isoforms": conflicts,
    }


def _strategy_priority_route_labels(structured_goal: Dict[str, Any]) -> List[str]:
    if not isinstance(structured_goal, dict):
        return []
    strategy_analysis = (
        structured_goal.get("splice_strategy_analysis")
        if isinstance(structured_goal.get("splice_strategy_analysis"), dict)
        else {}
    )
    text = str(strategy_analysis.get("analysis") or "").strip()
    if not text:
        return []
    section = text
    match = re.search(
        r"ranked\s+steric\s+hindrance\s+targets(?P<section>.*?)(?:\n\s*##\s+|\Z)",
        text,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if match:
        section = match.group("section")
    labels: List[str] = []
    seen: Set[str] = set()
    for found in re.finditer(r"\b(?:acceptor|donor)@\d+\b", section, flags=re.IGNORECASE):
        label = found.group(0).lower()
        site, position = _routing_label_site_parts(label)
        if not site or position is None:
            continue
        canonical = f"{site}@{position}"
        if canonical not in seen:
            seen.add(canonical)
            labels.append(canonical)
    return labels


def _serialize_routing_candidate_for_llm(
    entry: Dict[str, Any],
    *,
    runtime: Any,
    structured_goal: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    if not isinstance(entry, dict):
        return None
    label = _routing_candidate_label(entry, runtime)
    direction = _routing_candidate_direction(entry)
    if not label or direction not in {"increase", "decrease"}:
        return None
    payload: Dict[str, Any] = {
        "label": label,
        "direction": direction,
        "site_kind": str(entry.get("site") or entry.get("site_kind") or "").strip().lower() or None,
        "chrom": str(entry.get("chrom") or "").strip() or None,
        "position": _routing_entry_position(entry),
        "routing_selection_source": str(entry.get("routing_selection_source") or "").strip() or None,
        "observed_max_abs_delta": entry.get("observed_max_abs_delta"),
        "observed_directional_max_delta": entry.get("observed_directional_max_delta"),
        "observed_opposite_max_delta": entry.get("observed_opposite_max_delta"),
        "observed_mean_effect": entry.get("observed_mean_effect"),
        "observed_support": entry.get("observed_support"),
        "observed_directional_support": entry.get("observed_directional_support"),
        "observed_opposite_support": entry.get("observed_opposite_support"),
        "source_delta_direction": str(entry.get("source_delta_direction") or "").strip().lower() or None,
        "net_effect_hint": str(entry.get("net_effect_hint") or "").strip().lower() or None,
        "rationale_hint": str(entry.get("rationale") or "").strip() or None,
        "uniqueness": entry.get("uniqueness"),
        "all_coding": bool(entry.get("all_coding")) if entry.get("all_coding") is not None else None,
        "covers_all_isoforms": bool(entry.get("covers_all_isoforms")) if entry.get("covers_all_isoforms") is not None else None,
        "unique_to_pathogenic": bool(entry.get("unique_to_pathogenic")),
        "unique_to_beneficial": bool(entry.get("unique_to_beneficial")),
        "shared_with_beneficial": bool(entry.get("shared_with_beneficial")),
        "conflict_between_objectives": bool(entry.get("conflict_between_objectives")),
        "beneficial_isoforms": _routing_goal_labels(entry.get("beneficial_isoforms")),
        "pathogenic_isoforms": _routing_goal_labels(entry.get("pathogenic_isoforms")),
        "present_in": _routing_goal_labels(entry.get("present_in")),
        "absent_in": _routing_goal_labels(entry.get("absent_in")),
        "terminal_donor_isoforms": _routing_goal_labels(entry.get("terminal_donor_isoforms")),
        "exon_indices": sorted(_routing_entry_exon_indices(entry)),
    }
    delta_per_isoform = _route_delta_per_isoform(entry)
    if delta_per_isoform:
        payload["delta_per_isoform"] = delta_per_isoform
    for key in ("delta_per_isoform_scope", "isoform_abundance_objectives",
                "directional_evidence_status", "directional_evidence_note"):
        if key in entry:
            payload[key] = deepcopy(entry[key])
    alignment = _route_isoform_alignment(entry, structured_goal or {})
    if alignment.get("status") == "conflicting":
        return None
    if alignment.get("status") != "unknown":
        payload["isoform_objective_alignment"] = alignment
    from .splice_reference_scope import scoped_splice_evidence
    payload = scoped_splice_evidence(payload, entry, structured_goal or {})
    return {key: value for key, value in payload.items() if value not in (None, "", [], {})}


def _build_route_ranker_payload(
    *,
    structured_goal: Dict[str, Any],
    routing_entries: List[Dict[str, Any]],
    runtime: Any,
) -> Dict[str, Any]:
    routing_job = structured_goal.get("routing_job") if isinstance(structured_goal.get("routing_job"), dict) else {}
    splice_site_plan = (
        structured_goal.get("routing_local_splice_site_plan")
        if isinstance(structured_goal.get("routing_local_splice_site_plan"), list)
        else structured_goal.get("splice_site_plan")
    )
    compact_splice_plan: List[Dict[str, Any]] = []
    for entry in splice_site_plan or []:
        if not isinstance(entry, dict):
            continue
        label = _routing_candidate_label(entry, runtime)
        direction = _routing_candidate_direction(entry)
        from .splice_reference_scope import scoped_splice_evidence
        compact_splice_plan.append(
            scoped_splice_evidence({
                "label": label or entry.get("label"),
                "site_kind": entry.get("site") or entry.get("site_kind"),
                "direction": direction or entry.get("delta_direction"),
                "present_in": _routing_goal_labels(entry.get("present_in")),
                "absent_in": _routing_goal_labels(entry.get("absent_in")),
                "exon_indices": sorted(_routing_entry_exon_indices(entry)),
                "delta_per_isoform": _route_delta_per_isoform(entry),
                "covers_all_isoforms": bool(entry.get("covers_all_isoforms"))
                if entry.get("covers_all_isoforms") is not None
                else None,
            }, entry, structured_goal)
        )
    compact_splice_plan = [
        {key: value for key, value in entry.items() if value not in (None, "", [], {})}
        for entry in compact_splice_plan
        if entry.get("label")
    ]
    objective_entries = []
    for objective in _splice_plan_objectives_from_goal(structured_goal):
        if not isinstance(objective, dict):
            continue
        compact_objective = {
            "isoform_label": objective.get("isoform_label"),
            "transcript_id": objective.get("transcript_id"),
            "desired_abundance": objective.get("desired_abundance"),
            "role": objective.get("role"),
        }
        compact_objective = {
            key: value for key, value in compact_objective.items() if value not in (None, "", [], {})
        }
        if compact_objective:
            objective_entries.append(compact_objective)
    isoform_objectives = {
        "increase_isoforms": _routing_goal_labels(structured_goal.get("increase_isoforms")),
        "decrease_isoforms": _routing_goal_labels(structured_goal.get("decrease_isoforms")),
        "target_isoforms": _routing_goal_labels(structured_goal.get("target_isoforms")),
        "avoid_isoforms": _routing_goal_labels(structured_goal.get("avoid_isoforms")),
        "beneficial_isoforms": _routing_goal_labels(structured_goal.get("beneficial_isoforms")),
        "pathogenic_isoforms": _routing_goal_labels(structured_goal.get("pathogenic_isoforms")),
        "objectives": objective_entries,
    }
    strategy_analysis = (
        structured_goal.get("splice_strategy_analysis")
        if isinstance(structured_goal.get("splice_strategy_analysis"), dict)
        else {}
    )
    return {
        "gene_symbol": structured_goal.get("gene_symbol"),
        "gene_id": structured_goal.get("gene_id"),
        "user_request": structured_goal.get("user_request") or structured_goal.get("request"),
        "intent": structured_goal.get("intent"),
        "job": deepcopy(routing_job),
        "isoform_objectives": {key: value for key, value in isoform_objectives.items() if value},
        "splice_site_plan": compact_splice_plan[:24],
        "strategy_analysis_excerpt": _routing_llm_excerpt(strategy_analysis.get("analysis")),
        "candidates": [
            candidate
            for candidate in (
                _serialize_routing_candidate_for_llm(entry, runtime=runtime, structured_goal=structured_goal)
                for entry in routing_entries
            )
            if isinstance(candidate, dict)
        ],
    }


def _aligned_contextual_rescue_ranked_routes(
    *,
    structured_goal: Dict[str, Any],
    routing_entries: List[Dict[str, Any]],
    runtime: Any,
) -> List[Dict[str, Any]]:
    rescued: List[Dict[str, Any]] = []
    for entry in routing_entries:
        if not isinstance(entry, dict):
            continue
        alignment = _route_isoform_alignment(entry, structured_goal)
        if alignment.get("status") != "aligned":
            continue
        source_delta_direction = str(
            entry.get("source_delta_direction") or entry.get("delta_direction") or ""
        ).strip().lower()
        if source_delta_direction != "context" and str(entry.get("routing_selection_source") or "") != "contextual_fallback":
            continue
        label = _routing_candidate_label(entry, runtime)
        direction = _routing_candidate_direction(entry)
        if not label or direction not in {"increase", "decrease"}:
            continue
        if float(entry.get("observed_directional_max_delta") or entry.get("observed_max_abs_delta") or 0.0) <= 0:
            continue
        matched = ", ".join(str(item) for item in alignment.get("matched_isoforms") or [] if str(item).strip())
        rationale = (
            f"Contextual site aligns with requested isoform shifts ({matched}) and has strong observed leverage."
            if matched
            else "Contextual site aligns with requested isoform shifts and has strong observed leverage."
        )
        rescued.append(
            {
                "label": label,
                "direction": direction,
                "rationale": rationale[:180],
                "confidence": "medium" if bool(entry.get("covers_all_isoforms")) else "high",
                "_sort_max_delta": float(entry.get("observed_directional_max_delta") or entry.get("observed_max_abs_delta") or 0.0),
                "_sort_support": int(entry.get("observed_directional_support") or entry.get("observed_support") or 0),
            }
        )
    rescued.sort(key=lambda item: (-float(item.get("_sort_max_delta") or 0.0), -int(item.get("_sort_support") or 0), str(item.get("label") or "")))
    ranked: List[Dict[str, Any]] = []
    for rank, item in enumerate(rescued, start=1):
        clean_item = {key: value for key, value in item.items() if not str(key).startswith("_")}
        clean_item["rank"] = rank
        ranked.append(clean_item)
    return ranked


def _routing_job_is_explicit_user_requested(structured_goal: Dict[str, Any]) -> bool:
    if not isinstance(structured_goal, dict):
        return False
    routing_job = structured_goal.get("routing_job")
    if not isinstance(routing_job, dict):
        return False
    policy = _normalize_steric_targeting_policy(
        routing_job.get("targeting_policy") or routing_job.get("steric_targeting_policy")
    )
    if policy == "explicit_user_region":
        return True
    label_blob = " ".join(
        str(routing_job.get(key) or "")
        for key in ("job_label", "program_id", "job_id")
    ).lower()
    return bool(
        isinstance(structured_goal.get("per_site_window_program_preseed"), dict)
        and any(token in label_blob for token in ("window", "junction", "site", "route", "acceptor", "donor"))
    )


def _explicit_user_requested_rescue_ranked_routes(
    *,
    structured_goal: Dict[str, Any],
    routing_entries: List[Dict[str, Any]],
    excluded_routes: Any,
    runtime: Any,
) -> List[Dict[str, Any]]:
    if not _routing_job_is_explicit_user_requested(structured_goal):
        return []
    routing_job = structured_goal.get("routing_job") if isinstance(structured_goal, dict) else {}
    if not isinstance(routing_job, dict):
        routing_job = {}
    requested_site_kind = str(routing_job.get("site_kind") or "").strip().lower()
    excluded_reason_by_key: Dict[Tuple[str, str], str] = {}
    if isinstance(excluded_routes, list):
        for item in excluded_routes:
            if not isinstance(item, dict):
                continue
            label = str(item.get("label") or "").strip()
            direction = str(item.get("direction") or "").strip().lower()
            reason = str(item.get("reason") or "").strip()
            if label and direction in {"increase", "decrease"} and reason:
                excluded_reason_by_key[(label, direction)] = reason

    rescued: List[Dict[str, Any]] = []
    for entry in routing_entries:
        if not isinstance(entry, dict):
            continue
        label = _routing_candidate_label(entry, runtime)
        direction = _routing_candidate_direction(entry)
        if not label or direction not in {"increase", "decrease"}:
            continue
        entry_site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
        if requested_site_kind in {"acceptor", "donor"} and entry_site_kind and entry_site_kind != requested_site_kind:
            continue
        directional = float(entry.get("observed_directional_max_delta") or 0.0)
        opposite = float(entry.get("observed_opposite_max_delta") or 0.0)
        support = int(entry.get("observed_directional_support") or 0)
        total = int(entry.get("observed_support") or 0)
        reason = excluded_reason_by_key.get((label, direction))
        if not reason:
            reason = (
                f"Observed requested-direction support is weak "
                f"(max delta {directional:.4g}; {support}/{total} candidates), "
                f"with opposite-direction max delta {opposite:.4g}."
            )
        rescued.append(
            {
                "rank": len(rescued) + 1,
                "label": label,
                "direction": direction,
                "rationale": (
                    "User-requested explicit target window retained for per-site audit as a low-confidence route. "
                    + reason
                )[:260],
                "confidence": "low",
                "_sort_directional": directional,
                "_sort_support": support,
                "_sort_total": total,
            }
        )
    rescued.sort(
        key=lambda item: (
            -float(item.get("_sort_directional") or 0.0),
            -int(item.get("_sort_support") or 0),
            -int(item.get("_sort_total") or 0),
            str(item.get("label") or ""),
        )
    )
    ranked: List[Dict[str, Any]] = []
    for rank, item in enumerate(rescued, start=1):
        clean_item = {key: value for key, value in item.items() if not str(key).startswith("_")}
        clean_item["rank"] = rank
        ranked.append(clean_item)
    return ranked


def _explicit_objective_fallback_rescue_ranked_routes(
    *,
    routing_entries: List[Dict[str, Any]],
    runtime: Any,
) -> List[Dict[str, Any]]:
    rescued: List[Dict[str, Any]] = []
    for entry in routing_entries:
        if not isinstance(entry, dict):
            continue
        if not bool(entry.get("explicit_objective_fallback")):
            continue
        label = _routing_candidate_label(entry, runtime)
        direction = _routing_candidate_direction(entry)
        if not label or direction not in {"increase", "decrease"}:
            continue
        strategy_label = str(entry.get("target_strategy_label") or "").strip()
        rationale = str(entry.get("ranking_rationale") or "").strip()
        if not rationale:
            rationale = (
                f"Retained explicit {strategy_label or 'splice'} objective as a low-confidence route "
                "because evaluated splice deltas were flat."
            )
        rescued.append(
            {
                "rank": len(rescued) + 1,
                "label": label,
                "direction": direction,
                "rationale": rationale[:260],
                "confidence": "low",
                "_sort_strategy": int(entry.get("strategy_objective_index") or 0),
                "_sort_plan": int(entry.get("strategy_plan_index") or 0),
            }
        )
    rescued.sort(
        key=lambda item: (
            int(item.get("_sort_strategy") or 0),
            int(item.get("_sort_plan") or 0),
            str(item.get("label") or ""),
        )
    )
    ranked: List[Dict[str, Any]] = []
    for rank, item in enumerate(rescued, start=1):
        clean_item = {key: value for key, value in item.items() if not str(key).startswith("_")}
        clean_item["rank"] = rank
        ranked.append(clean_item)
    return ranked


def _omitted_objective_route_entries(
    *,
    structured_goal: Dict[str, Any],
    routing_entries: List[Dict[str, Any]],
    seen_keys: Set[Tuple[str, str]],
    excluded_routes: Any,
    runtime: Any,
) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict) or not isinstance(routing_entries, list):
        return []

    routing_job = structured_goal.get("routing_job") if isinstance(structured_goal.get("routing_job"), dict) else {}
    if not isinstance(routing_job, dict):
        routing_job = {}
    requested_site_kind = _routing_job_requested_site_kind(routing_job)
    job_candidate_labels = _job_candidate_site_labels(routing_job)
    explicit_user_scope = _routing_job_is_explicit_user_requested(structured_goal)
    objective_map = _route_isoform_objective_direction_map(structured_goal)
    has_mixed_isoform_objectives = {"increase", "decrease"}.issubset(set(objective_map.values()))
    if not explicit_user_scope and not has_mixed_isoform_objectives:
        return []

    excluded_reason_by_key: Dict[Tuple[str, str], str] = {}
    if isinstance(excluded_routes, list):
        for item in excluded_routes:
            if not isinstance(item, dict):
                continue
            label = str(item.get("label") or "").strip()
            direction = str(item.get("direction") or "").strip().lower()
            reason = str(item.get("reason") or "").strip()
            if label and direction in {"increase", "decrease"} and reason:
                excluded_reason_by_key[(label, direction)] = reason

    rescued: List[Dict[str, Any]] = []
    for entry in routing_entries:
        if not isinstance(entry, dict):
            continue
        label = _routing_candidate_label(entry, runtime)
        direction = _routing_candidate_direction(entry)
        if not label or direction not in {"increase", "decrease"}:
            continue
        key = (label, direction)
        if key in seen_keys:
            continue

        entry_site_kind = str(entry.get("site") or entry.get("site_kind") or "").strip().lower()
        if requested_site_kind in {"acceptor", "donor"} and entry_site_kind and entry_site_kind != requested_site_kind:
            continue

        alignment = _route_isoform_alignment(entry, structured_goal)
        explicit_candidate = explicit_user_scope or (bool(job_candidate_labels) and label in job_candidate_labels)
        objective_aligned = alignment.get("status") == "aligned"
        if not explicit_candidate and not objective_aligned:
            continue
        if has_mixed_isoform_objectives and not objective_aligned and not explicit_user_scope:
            continue

        directional = float(entry.get("observed_directional_max_delta") or entry.get("observed_max_abs_delta") or 0.0)
        support = int(entry.get("observed_directional_support") or entry.get("observed_support") or 0)
        if directional <= 0.0 or support <= 0:
            continue

        annotated = dict(entry)
        matched = ", ".join(str(item) for item in alignment.get("matched_isoforms") or [] if str(item).strip())
        reason = excluded_reason_by_key.get(key)
        if reason:
            rationale = f"Retained omitted objective-relevant route for audit; LLM exclusion: {reason}"
        elif matched:
            rationale = f"Retained omitted route because it aligns with requested isoform shifts ({matched})."
        elif explicit_user_scope:
            rationale = "Retained omitted explicit user-requested target window for per-site audit."
        else:
            rationale = "Retained omitted route because it is in the job candidate site set for a mixed isoform objective."
        annotated["ranking_rationale"] = rationale[:260]
        annotated["ranking_confidence"] = str(annotated.get("ranking_confidence") or "low").strip().lower() or "low"
        if annotated["ranking_confidence"] not in {"high", "medium", "low"}:
            annotated["ranking_confidence"] = "low"
        annotated["ranking_model"] = ROUTE_RANKER_MODEL
        annotated["routing_selection_source"] = str(
            annotated.get("routing_selection_source") or "omitted_objective_route_rescue"
        )
        annotated["_sort_directional"] = directional
        annotated["_sort_support"] = support
        rescued.append(annotated)

    rescued.sort(
        key=lambda entry: (
            -float(entry.get("_sort_directional") or 0.0),
            -int(entry.get("_sort_support") or 0),
            str(_routing_candidate_label(entry, runtime) or ""),
            str(_routing_candidate_direction(entry) or ""),
        )
    )
    return [
        {key: value for key, value in entry.items() if not str(key).startswith("_sort_")}
        for entry in rescued
    ]


def _routing_entry_observed_strength(entry: Dict[str, Any]) -> float:
    for key in ("observed_directional_max_delta", "observed_max_abs_delta"):
        try:
            value = float(entry.get(key) or 0.0)
        except Exception:
            value = 0.0
        if value > 0:
            return value
    return 0.0


def _strategy_priority_reorder_is_metric_consistent(
    *,
    current_entries: List[Dict[str, Any]],
    proposed_entries: List[Dict[str, Any]],
    runtime: Any,
) -> bool:
    current_index: Dict[str, int] = {}
    for idx, entry in enumerate(current_entries):
        label = str(_routing_candidate_label(entry, runtime) or "").strip().lower()
        direction = str(_routing_candidate_direction(entry) or "").strip().lower()
        if label and direction:
            current_index[f"{label}|{direction}"] = idx

    for proposed_idx, earlier_entry in enumerate(proposed_entries):
        earlier_label = str(_routing_candidate_label(earlier_entry, runtime) or "").strip().lower()
        earlier_direction = str(_routing_candidate_direction(earlier_entry) or "").strip().lower()
        earlier_key = f"{earlier_label}|{earlier_direction}"
        if earlier_key not in current_index:
            continue
        earlier_strength = _routing_entry_observed_strength(earlier_entry)
        for later_entry in proposed_entries[proposed_idx + 1 :]:
            later_label = str(_routing_candidate_label(later_entry, runtime) or "").strip().lower()
            later_direction = str(_routing_candidate_direction(later_entry) or "").strip().lower()
            later_key = f"{later_label}|{later_direction}"
            if later_key not in current_index:
                continue
            if current_index[later_key] >= current_index[earlier_key]:
                continue
            later_strength = _routing_entry_observed_strength(later_entry)
            if later_strength > max(earlier_strength * 1.25, earlier_strength + 0.05):
                return False
    return True


def _rank_routing_entries_with_llm(
    *,
    structured_goal: Dict[str, Any],
    routing_entries: List[Dict[str, Any]],
    debug_dir: str,
) -> Dict[str, Any]:
    runtime = _goal_runtime_module()
    ranking_model = get_provider_config().resolve_model(ROUTE_RANKER_MODEL)
    serialized_entries: List[Dict[str, Any]] = []
    entry_lookup: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for entry in routing_entries:
        serialized = _serialize_routing_candidate_for_llm(entry, runtime=runtime, structured_goal=structured_goal)
        if not isinstance(serialized, dict):
            continue
        key = (str(serialized.get("label") or "").strip(), str(serialized.get("direction") or "").strip().lower())
        if not key[0] or key[1] not in {"increase", "decrease"} or key in entry_lookup:
            continue
        serialized_entries.append(serialized)
        entry_lookup[key] = dict(entry)
    if not serialized_entries:
        return {"error": "router_llm_ranking_no_serializable_candidates"}

    payload = _build_route_ranker_payload(
        structured_goal=structured_goal,
        routing_entries=[entry_lookup[(entry["label"], entry["direction"])] for entry in serialized_entries],
        runtime=runtime,
    )
    prompt_path = ""
    output_path = ""
    if debug_dir:
        prompt_path = _write_json_artifact(
            os.path.join(debug_dir, "llm_route_ranking_input.json"),
            payload,
        ) or ""
    try:
        llm_result = rank_route_candidates_with_llm(payload)
    except Exception as exc:
        return {
            "error": f"router_llm_ranking_failed: {exc}",
            "prompt_path": prompt_path,
        }
    llm_output = {key: value for key, value in llm_result.items() if not str(key).startswith("_")}
    if debug_dir:
        output_path = _write_json_artifact(
            os.path.join(debug_dir, "llm_route_ranking_output.json"),
            llm_output,
        ) or ""
        responses = llm_result.get("_responses")
        if isinstance(responses, list):
            _write_json_artifact(
                os.path.join(debug_dir, "llm_route_ranking_responses.json"),
                {"responses": responses},
            )

    raw_ranked = llm_output.get("ranked_routes")
    if not isinstance(raw_ranked, list) or not raw_ranked:
        rescued_ranked = _aligned_contextual_rescue_ranked_routes(
            structured_goal=structured_goal,
            routing_entries=[entry_lookup[(entry["label"], entry["direction"])] for entry in serialized_entries],
            runtime=runtime,
        )
        if rescued_ranked:
            raw_ranked = rescued_ranked
            llm_output["ranked_routes"] = rescued_ranked
            llm_output["ranking_summary"] = (
                str(llm_output.get("ranking_summary") or "").strip()
                or "Rescued contextual route candidates whose isoform-level effects matched the requested objectives."
            )
            llm_output.setdefault("excluded_routes", [])
            llm_output["contextual_rescue_applied"] = True
        else:
            rescued_ranked = _explicit_user_requested_rescue_ranked_routes(
                structured_goal=structured_goal,
                routing_entries=[entry_lookup[(entry["label"], entry["direction"])] for entry in serialized_entries],
                excluded_routes=llm_output.get("excluded_routes"),
                runtime=runtime,
            )
            if not rescued_ranked:
                rescued_ranked = _explicit_objective_fallback_rescue_ranked_routes(
                    routing_entries=[entry_lookup[(entry["label"], entry["direction"])] for entry in serialized_entries],
                    runtime=runtime,
                )
        if rescued_ranked and not raw_ranked:
            raw_ranked = rescued_ranked
            llm_output["ranked_routes"] = rescued_ranked
            llm_output["ranking_summary"] = (
                str(llm_output.get("ranking_summary") or "").strip()
                or "Retained explicit user-requested route candidates as low-confidence per-site audit outputs."
            )
            llm_output.setdefault("excluded_routes", [])
            llm_output["explicit_user_requested_rescue_applied"] = True
        if rescued_ranked:
            if debug_dir:
                output_path = _write_json_artifact(
                    os.path.join(debug_dir, "llm_route_ranking_output.json"),
                    llm_output,
                ) or output_path
        else:
            excluded_routes = llm_output.get("excluded_routes")
            if isinstance(excluded_routes, list) and excluded_routes:
                return {
                    "error": "router_no_directional_targets",
                    "ranking_summary": str(llm_output.get("ranking_summary") or "").strip(),
                    "excluded_routes": excluded_routes,
                    "prompt_path": prompt_path,
                    "output_path": output_path,
                }
            return {
                "error": "router_llm_ranking_invalid: ranked_routes_missing",
                "prompt_path": prompt_path,
                "output_path": output_path,
            }

    ranked_items = sorted(
        [
            (idx, item)
            for idx, item in enumerate(raw_ranked)
            if isinstance(item, dict)
        ],
        key=lambda pair: (
            int(pair[1].get("rank")) if str(pair[1].get("rank") or "").strip().isdigit() else 999999,
            pair[0],
        ),
    )
    ordered_entries: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str]] = set()
    for _, item in ranked_items:
        label = str(item.get("label") or "").strip()
        direction = str(item.get("direction") or "").strip().lower()
        rationale = str(item.get("rationale") or "").strip()
        confidence = str(item.get("confidence") or "").strip().lower()
        key = (label, direction)
        if key in seen or key not in entry_lookup or not rationale:
            continue
        annotated = dict(entry_lookup[key])
        annotated["ranking_rationale"] = rationale
        if confidence in {"high", "medium", "low"}:
            annotated["ranking_confidence"] = confidence
        annotated["ranking_model"] = ROUTE_RANKER_MODEL
        ordered_entries.append(annotated)
        seen.add(key)

    if not ordered_entries:
        return {
            "error": "router_llm_ranking_invalid: no_ranked_candidates_accepted",
            "prompt_path": prompt_path,
            "output_path": output_path,
        }

    omitted_rescues = _omitted_objective_route_entries(
        structured_goal=structured_goal,
        routing_entries=[entry_lookup[(entry["label"], entry["direction"])] for entry in serialized_entries],
        seen_keys=seen,
        excluded_routes=llm_output.get("excluded_routes"),
        runtime=runtime,
    )
    if omitted_rescues:
        for entry in omitted_rescues:
            label = _routing_candidate_label(entry, runtime)
            direction = _routing_candidate_direction(entry)
            key = (label, direction)
            if not label or direction not in {"increase", "decrease"} or key in seen:
                continue
            ordered_entries.append(entry)
            seen.add(key)
        llm_output["omitted_objective_route_rescue_applied"] = True
        llm_output["omitted_objective_route_rescue_count"] = len(omitted_rescues)
        if debug_dir:
            output_path = _write_json_artifact(
                os.path.join(debug_dir, "llm_route_ranking_output.json"),
                llm_output,
            ) or output_path

    strategy_priority = _strategy_priority_route_labels(structured_goal)
    strategy_priority_applied = False
    # The plan predates measured route evidence. Keep it as context, not a
    # silent override of the accepted model ranking and its rationale.

    for idx, entry in enumerate(ordered_entries, 1):
        entry["llm_route_rank"] = idx
        entry["ranking_model"] = ranking_model

    ranking_summary = str(llm_output.get("ranking_summary") or "").strip()
    if strategy_priority_applied:
        ordered = ", ".join(strategy_priority[: min(4, len(strategy_priority))])
        ranking_summary = (
            f"Applied persisted splice-strategy target order ({ordered}) to LLM-accepted route candidates."
        )

    return {
        "ranked_entries": ordered_entries,
        "ranking_summary": ranking_summary,
        "excluded_routes": llm_output.get("excluded_routes") if isinstance(llm_output.get("excluded_routes"), list) else [],
        "ranking_model": ranking_model,
        "strategy_priority_applied": strategy_priority_applied,
        "strategy_priority_order": strategy_priority,
        "prompt_path": prompt_path,
        "output_path": output_path,
    }


def _routing_jobs_from_state(routing_state: Dict[str, Any], run_dir: str) -> List[Dict[str, Any]]:
    jobs = routing_state.get("jobs")
    normalized_jobs: List[Dict[str, Any]] = []
    if isinstance(jobs, list) and jobs:
        for job in jobs:
            if not isinstance(job, dict):
                continue
            planner_plan = job.get("planner_plan") if isinstance(job.get("planner_plan"), dict) else {}
            steps = planner_plan.get("steps") if isinstance(planner_plan.get("steps"), list) else []
            total_steps = int(job.get("total_steps") or len(steps) or 0)
            job_copy = dict(job)
            job_copy["planner_plan"] = planner_plan
            job_copy["total_steps"] = total_steps
            job_copy["next_goal_index"] = int(job_copy.get("next_goal_index") or 0)
            job_copy["goals"] = [entry for entry in (job_copy.get("goals") or []) if isinstance(entry, dict)]
            job_copy["step_results"] = [entry for entry in (job_copy.get("step_results") or []) if isinstance(entry, dict)]
            normalized_jobs.append(job_copy)
        if normalized_jobs:
            return normalized_jobs

    planner_plan = routing_state.get("planner_plan") if isinstance(routing_state.get("planner_plan"), dict) else {}
    steps = planner_plan.get("steps") if isinstance(planner_plan.get("steps"), list) else []
    total_steps = int(routing_state.get("total_steps") or len(steps) or 0)
    if total_steps <= 0 and not steps:
        return []
    return [
        {
            "job_id": str(routing_state.get("job_id") or "run_level_routing"),
            "job_label": str(routing_state.get("job_label") or "run-level routing"),
            "modality": str(routing_state.get("modality") or "steric"),
            "output_dir": str(routing_state.get("output_dir") or str(_write_run_path(run_dir, "strategy_routes"))).strip(),
            "summary_path": str(routing_state.get("summary_path") or str(_write_run_path(run_dir, "strategy_router_summary.json"))).strip(),
            "debug_dir": str(routing_state.get("debug_dir") or str(_write_run_path(run_dir, "strategy_router_debug"))).strip(),
            "scored_tiles_path": str(routing_state.get("scored_tiles_path") or "").strip(),
            "planner_plan": planner_plan,
            "total_steps": total_steps,
            "next_goal_index": int(routing_state.get("next_goal_index") or 0),
            "goals": [entry for entry in (routing_state.get("goals") or []) if isinstance(entry, dict)],
            "step_results": [entry for entry in (routing_state.get("step_results") or []) if isinstance(entry, dict)],
        }
    ]


def _routing_jobs_totals(routing_jobs: List[Dict[str, Any]]) -> Dict[str, int]:
    total_steps = 0
    completed_steps = 0
    completed_jobs = 0
    for job in routing_jobs:
        if not isinstance(job, dict):
            continue
        planner_plan = job.get("planner_plan") if isinstance(job.get("planner_plan"), dict) else {}
        steps = planner_plan.get("steps") if isinstance(planner_plan.get("steps"), list) else []
        job_total = int(job.get("total_steps") or len(steps) or 0)
        job_next = max(0, int(job.get("next_goal_index") or 0))
        total_steps += job_total
        completed_steps += min(job_next, job_total)
        if job_total > 0 and job_next >= job_total:
            completed_jobs += 1
    return {
        "total_steps": total_steps,
        "completed_steps": completed_steps,
        "completed_jobs": completed_jobs,
        "total_jobs": len([job for job in routing_jobs if isinstance(job, dict)]),
    }


def _attach_route_tabular_exports(
    *,
    runtime: Any,
    goals: List[Dict[str, Any]],
) -> None:
    if not isinstance(goals, list) or not goals:
        return
    writer = getattr(runtime, "_write_strategy_route_csv", None)
    if not callable(writer):
        return
    for goal in goals:
        if not isinstance(goal, dict):
            continue
        output_path = str(goal.get("output_path") or "").strip()
        if not output_path:
            continue
        csv_path, csv_error = writer(output_path)
        if csv_path:
            goal["csv_path"] = csv_path
            excel_path = os.path.splitext(csv_path)[0] + ".xlsx"
            if os.path.exists(excel_path):
                goal["excel_path"] = excel_path
        if csv_error:
            goal["csv_error"] = csv_error


def _flatten_routing_jobs(routing_jobs: List[Dict[str, Any]]) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    goals: List[Dict[str, Any]] = []
    step_results: List[Dict[str, Any]] = []
    for job in routing_jobs:
        if not isinstance(job, dict):
            continue
        for goal in job.get("goals") or []:
            if isinstance(goal, dict):
                goals.append(dict(goal))
        for step in job.get("step_results") or []:
            if isinstance(step, dict):
                step_results.append(dict(step))
    return goals, step_results


def _next_pending_routing_job_index(
    routing_jobs: List[Dict[str, Any]],
    *,
    start_index: int = 0,
) -> Optional[int]:
    idx = max(0, int(start_index or 0))
    while idx < len(routing_jobs):
        job = routing_jobs[idx]
        if not isinstance(job, dict):
            idx += 1
            continue
        planner_plan = job.get("planner_plan") if isinstance(job.get("planner_plan"), dict) else {}
        steps = planner_plan.get("steps") if isinstance(planner_plan.get("steps"), list) else []
        total_steps = int(job.get("total_steps") or len(steps) or 0)
        next_goal_index = int(job.get("next_goal_index") or 0)
        if total_steps > 0 and next_goal_index < total_steps:
            return idx
        idx += 1
    return None


def _routing_executor_errors(step_results: List[Dict[str, Any]]) -> List[str]:
    errors: List[str] = []
    for entry in step_results:
        if not isinstance(entry, dict):
            continue
        result = entry.get("result")
        if isinstance(result, dict) and result.get("error"):
            errors.append(str(result.get("error")))
    return errors


def _build_routing_job_summary(
    *,
    job_state: Dict[str, Any],
    flags: Dict[str, Any],
) -> Dict[str, Any]:
    job_id = str(job_state.get("job_id") or "").strip() or "routing_job"
    job_label = str(job_state.get("job_label") or job_id).strip() or job_id
    planner_plan = job_state.get("planner_plan") if isinstance(job_state.get("planner_plan"), dict) else {}
    ranking = planner_plan.get("ranking") if isinstance(planner_plan.get("ranking"), dict) else {}
    summary: Dict[str, Any] = {
        "job_id": job_id,
        "job_label": job_label,
        "modality": str(job_state.get("modality") or "").strip(),
        "steps": [entry for entry in (job_state.get("step_results") or []) if isinstance(entry, dict)],
        "goals": [entry for entry in (job_state.get("goals") or []) if isinstance(entry, dict)],
        "planner_plan": planner_plan,
        "output_dir": str(job_state.get("output_dir") or "").strip(),
        "scored_tiles_path": str(job_state.get("scored_tiles_path") or "").strip(),
        "max_steps": int(flags.get("router_max_steps", 25) or 25),
        "meta": {
            "deterministic_router": False,
            "atomic_routing": True,
            "per_job": True,
            "llm_ranked_routes": True,
            "ranking_model": ranking.get("model") or ROUTE_RANKER_MODEL,
        },
    }
    executor_errors = _routing_executor_errors(summary["steps"])
    if executor_errors:
        summary["executor_errors"] = executor_errors
        summary["error"] = "executor_step_errors"
    return summary


def _copy_routing_artifact(
    src_path: Any,
    dest_dir: Path,
    prefix: str,
    *,
    modality: str = "",
) -> Optional[str]:
    if not isinstance(src_path, str) or not src_path.strip():
        return None
    src = Path(src_path).expanduser()
    if not src.exists() or not src.is_file():
        return None
    safe_prefix = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(prefix or "").strip()).strip("._") or "route"
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / f"{safe_prefix}__{src.name}"
    shutil.copyfile(src, dest)
    modality_value = str(modality or "").strip().lower()
    if dest.suffix.lower() == ".json" and modality_value:
        try:
            payload = json.loads(dest.read_text(encoding="utf-8"))
        except Exception:
            payload = None
        if isinstance(payload, dict):
            payload["modality"] = modality_value
            routes = payload.get("routes")
            if isinstance(routes, list):
                for route in routes:
                    if isinstance(route, dict):
                        route["modality"] = modality_value
            dest.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
    return str(dest)


def _write_json_artifact(path: Any, payload: Dict[str, Any]) -> Optional[str]:
    if not isinstance(path, str) or not path.strip():
        return None
    target = Path(path).expanduser()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return str(target)


def _existing_routing_artifact_paths(root: Path) -> List[Path]:
    routing_paths: List[Path] = []
    steric_jobs_root = _run_path(root, "steric_jobs")
    if steric_jobs_root.exists():
        for job_dir in steric_jobs_root.iterdir():
            if not job_dir.is_dir():
                continue
            routing_paths.extend(
                [
                    job_dir / "strategy_router_summary.json",
                    job_dir / "strategy_routes",
                    job_dir / "strategy_router_debug",
                ]
            )
    return routing_paths


def _is_execution_tool_name(tool_name: str) -> bool:
    name = str(tool_name or "").strip()
    if not name:
        return False
    return name.startswith("tool_")


def _allowed_tools_after_last_tool(last_tool: Optional[str]) -> List[str]:
    def _inject_evaluate(tools: List[str], tool_name: str) -> List[str]:
        if _is_execution_tool_name(tool_name) and "evaluate_step_output" not in tools:
            return ["evaluate_step_output", *tools]
        return tools

    if isinstance(last_tool, str):
        key = last_tool.strip()
        if key in _TOOL_TRANSITIONS:
            return _inject_evaluate(list(_TOOL_TRANSITIONS[key]), key)
    return list(_DEFAULT_ALLOWED_NEXT_TOOLS)


