def _clarification_request_scope_schema(answer_count: int) -> Dict[str, Any]:
    bounded_count = max(0, int(answer_count))
    replacement_index_schema: Dict[str, Any] = {"type": ["integer", "null"]}
    if bounded_count:
        replacement_index_schema.update(
            {"minimum": 0, "maximum": bounded_count - 1}
        )
    return {
        "type": "object",
        "properties": {
            "decision": {
                "type": "string",
                "enum": [
                    "augment_current_request",
                    "replace_current_request",
                    "close_out_of_scope",
                ],
            },
            "replacement_answer_index": replacement_index_schema,
            "reason": {"type": "string", "minLength": 1},
        },
        "required": ["decision", "replacement_answer_index", "reason"],
        "additionalProperties": False,
    }


def _clarification_request_scope_contract_errors(
    payload: Dict[str, Any],
    *,
    answer_count: int,
    schema: Dict[str, Any],
) -> List[str]:
    errors = _json_schema_validation_errors(payload, schema)
    if errors:
        return errors
    decision = str(payload.get("decision") or "").strip().lower()
    index = payload.get("replacement_answer_index")
    if decision == "replace_current_request":
        if (
            not isinstance(index, int)
            or isinstance(index, bool)
            or index < 0
            or index >= max(0, int(answer_count))
        ):
            errors.append(
                "replace_current_request requires one supplied replacement answer index"
            )
    elif index is not None:
        errors.append(
            "non-replacement clarification scope decisions require a null replacement index"
        )
    return errors


async def _run_clarification_request_scope_agent_once(
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    answers = payload.get("answers") if isinstance(payload.get("answers"), list) else []
    schema = _clarification_request_scope_schema(len(answers))
    agent = _agent_with_strict_output_schema(
        clarification_request_scope_agent,
        schema_name="aso_clarification_request_scope",
        schema=schema,
    )
    return await _run_schema_validated_agent_once(
        agent=agent,
        prompt=json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
        schema=schema,
        error_prefix="clarification_request_scope_agent",
        contract_validator=lambda result: _clarification_request_scope_contract_errors(
            result,
            answer_count=len(answers),
            schema=schema,
        ),
    )


async def _run_goal_unresolved_adjudication_agent_once(
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    unresolved = payload.get("proposed_unresolved")
    item_count = len(unresolved) if isinstance(unresolved, list) else 0
    schema = _goal_unresolved_adjudication_schema(item_count)
    agent = _agent_with_strict_output_schema(
        goal_unresolved_adjudication_agent,
        schema_name="aso_goal_unresolved_adjudication",
        schema=schema,
    )
    result = await _run_schema_validated_agent_once(
        agent=agent,
        prompt=json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
        schema=schema,
        error_prefix="goal_unresolved_adjudication_agent",
        contract_validator=lambda result: (
            _goal_unresolved_adjudication_contract_errors(
                result,
                item_count=item_count,
                schema=schema,
            )
        ),
    )
    if result.get("error"):
        return result
    # The model can correctly identify the required value yet label that fact
    # as a repair even when the envelope already contains it. Do not force a
    # mutation in that case. This resolves only this proposed clarification;
    # canonical and execution validators and every other audit finding remain
    # active. Genuine changes still go through the existing evidence-bound
    # repair protocol. Raw model responses stay unchanged in the trace.
    result = deepcopy(result)
    envelope = payload.get("current_request_envelope")
    for verdict in result.get("verdicts") or []:
        if verdict.get("disposition") != "repair_from_evidence":
            continue
        exists, current = _json_pointer_value(
            envelope, _json_pointer_tokens(verdict.get("canonical_path"))
        )
        expected = _goal_adjudication_evidence_value(verdict["evidence_value_json"])
        if exists and json.dumps(current, sort_keys=True, allow_nan=False) == json.dumps(
            expected, sort_keys=True, allow_nan=False
        ):
            verdict.update(disposition="nonblocking", canonical_path=None,
                           evidence_value_json=None)
    return result


async def _run_goal_validation_issue_localization_agent_once(
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    issue_instances = (
        payload.get("validation_issue_instances")
        if isinstance(payload.get("validation_issue_instances"), list)
        else []
    )
    candidate_destinations = (
        payload.get("candidate_destinations")
        if isinstance(payload.get("candidate_destinations"), list)
        else []
    )
    schema = _goal_validation_issue_localization_schema(
        issue_instances,
        candidate_destinations,
    )
    agent = _agent_with_strict_output_schema(
        goal_validation_issue_localization_agent,
        schema_name="aso_goal_validation_issue_localization",
        schema=schema,
        instruction_suffix=(
            "\nThis invocation contains "
            + str(len(issue_instances))
            + " issue(s). Emit exactly that many compact verdicts and stop."
        ),
    )
    return await _run_schema_validated_agent_once(
        agent=agent,
        prompt=json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
        schema=schema,
        error_prefix="goal_validation_issue_localization_agent",
        contract_validator=lambda result: (
            _goal_validation_issue_localization_contract_errors(
                result,
                issue_instances=issue_instances,
                candidate_destinations=candidate_destinations,
                schema=schema,
            )
        ),
    )


async def _run_goal_contract_repair_agent_once(prompt: str) -> Dict[str, Any]:
    return await _run_schema_validated_agent_once(
        agent=goal_contract_repair_agent,
        prompt=prompt,
        schema=GOAL_CONTRACT_REPAIR_OUTPUT_SCHEMA,
        error_prefix="goal_contract_repair_agent",
    )


async def _run_workbench_response_agent_once(payload: Dict[str, Any], *, artifact_dir=None, initial_drafts=None, initial_findings=None) -> Dict[str, Any]:
    from .response_context import evaluation_response_batches, merge_evaluation_responses
    if artifact_dir is not None:
        from .response_artifacts import write_json, digest
        write_json(Path(artifact_dir) / ('response-input-' + digest(payload) + '.json'), payload)
    from .response_artifacts import digest
    initial_drafts = initial_drafts or {}
    initial_findings = initial_findings or {}
    batches = evaluation_response_batches(payload)
    if len(batches) == 1:
        return await _run_workbench_response_batch_once(batches[0], artifact_dir=artifact_dir, initial_response=initial_drafts.get(digest(batches[0])), initial_findings=initial_findings.get(digest(batches[0])))
    def compose(batch):
        # Runner.run wraps synchronous I/O; independent report components share
        # API admission while retaining their own complete evidence and history.
        return asyncio.run(_run_workbench_response_batch_once(batch, artifact_dir=artifact_dir, initial_response=initial_drafts.get(digest(batch)), initial_findings=initial_findings.get(digest(batch))))
    results = await asyncio.gather(
        *[asyncio.to_thread(compose, batch) for batch in batches], return_exceptions=True,
    )
    errors = [result for result in results if isinstance(result, BaseException)]
    if errors:
        raise RuntimeError('workbench_response_component_failed: ' + '; '.join(str(error) for error in errors))
    from .response_assembly import review_assembled_response
    return await review_assembled_response(payload, merge_evaluation_responses(results, payload),
        artifact_dir=Path(artifact_dir) / 'assembly' if artifact_dir is not None else None)


async def _run_workbench_response_batch_once(payload: Dict[str, Any], *, artifact_dir=None, initial_response=None, initial_findings=None) -> Dict[str, Any]:
    from .response_artifacts import ResponseArtifacts, report_configuration
    from .workbench_response_agent import (evaluation_evidence_audit_agent,
                                           orientation_evidence_audit_agent,
                                           panel_comparison_audit_agent,
                                           splice_metric_audit_agent,
                                           evaluation_evidence_repair_agent)
    archive = None
    if artifact_dir is not None:
        configuration = report_configuration((workbench_response_agent, evaluation_evidence_audit_agent,
                                               orientation_evidence_audit_agent, panel_comparison_audit_agent,
                                               splice_metric_audit_agent,
                                               evaluation_evidence_repair_agent))
        archive = ResponseArtifacts(artifact_dir, payload, configuration)
    try:
        accepted = archive.accepted() if archive else None
        if accepted is not None:
            return accepted
        response = await _compose_workbench_response_batch(payload, archive=archive, initial_response=initial_response, initial_findings=initial_findings)
        if archive:
            archive.accept(response)
        return response
    except Exception as exc:
        if archive:
            archive.record('failure', {'exception_type': type(exc).__name__, 'message': str(exc)})
        raise


async def _compose_workbench_response_batch(payload: Dict[str, Any], *, archive=None, initial_response=None, initial_findings=None) -> Dict[str, Any]:
    from .response_contracts import response_contract_errors
    from .response_context import render_response_context
    from .response_delivery import (evaluation_delivery_schema, normalize_evaluation_delivery,
                                    normalize_panel_ranking_rationales,
                                    normalize_structured_assessment_markdown)
    from .evaluation_response_audit import (
        response_audit_schema, response_audit_contract_errors, response_audit_repair_findings,
        response_audit_receipt, apply_bound_narrative_patch, narrative_repair_schema, response_audit_context,
        orientation_audit_packets, panel_comparison_audit_packet, panel_comparison_finding_errors,
        chemical_position_audit_packets, filter_chemical_position_findings,
        correct_native_chemical_position_claims,
        splice_metric_audit_packet, splice_metric_finding_errors, filter_splice_metric_findings,
    )
    from .workbench_response_agent import (evaluation_evidence_audit_agent,
                                           orientation_evidence_audit_agent,
                                           chemical_position_audit_agent,
                                           panel_comparison_audit_agent,
                                           splice_metric_audit_agent,
                                           evaluation_evidence_repair_agent)
    delivery_schema = evaluation_delivery_schema(payload)
    prompt = render_response_context({**payload, "output_schema": delivery_schema} if delivery_schema else payload)
    errors = []
    review_attempts = 0
    preceding_response = None
    bounded_repair_findings = []
    if initial_findings:
        if initial_response is None:
            raise ValueError('Saved review findings require their exact preceding draft.')
        preceding_response = deepcopy(initial_response)
        bounded_repair_findings = response_audit_repair_findings(
            {'findings': initial_findings}, preceding_response, payload)
        if archive:
            archive.record('retained-initial-draft', initial_response)
            archive.record('retained-unresolved-findings', bounded_repair_findings)
        prompt = render_response_context({
            'source': payload, 'preceding_response': preceding_response,
            'evidence_consistency_findings': bounded_repair_findings,
            'allowed_narrative_repair_paths': sorted({item['response_path'] for item in bounded_repair_findings}),
            'output_schema': narrative_repair_schema(bounded_repair_findings),
        })
    field_repairs = {}
    conservative_fields = set()
    rejected_focused_findings = 0
    rejected_metric_findings = 0
    serialization_attempts = 0
    attempt = -1
    while True:
        attempt += 1
        scoped = preceding_response is not None and bool(bounded_repair_findings)
        fallback_draft = None
        agent = workbench_response_agent
        if delivery_schema and not scoped:
            agent = _agent_with_strict_output_schema(
                agent, schema_name="aso_observation_response", schema=delivery_schema)
        if scoped:
            paths = {item['response_path'] for item in bounded_repair_findings}
            exhausted = sorted(path for path in paths if field_repairs.get(path, 0) >= 3)
            if exhausted:
                if conservative_fields.intersection(exhausted):
                    raise RuntimeError('workbench_response_contract_failed: conservative narrative still contradicted: '
                                       + ', '.join(exhausted) + '; ' + '; '.join(errors))
                # Preserve the computational evidence and every accepted
                # sibling component. A repeatedly contradicted narrative is
                # withheld explicitly, then independently audited again;
                # it must never be returned as an unchecked success.
                fallback_findings = [item for item in bounded_repair_findings
                                     if item['response_path'] in exhausted]
                fallback_text = ('Assessment withheld for this narrative field because its interpretation '
                                 'could not be reconciled with the recorded evidence. Consult the structured '
                                 'per-molecule results and their declared measurement scope.')
                fallback_draft = apply_bound_narrative_patch(
                    preceding_response,
                    {'corrections': {path: fallback_text for path in exhausted}},
                    fallback_findings, payload)
                # Markdown is a view of the structured assessments. Rebuild
                # it so a superseded claim cannot survive in that view.
                if isinstance(fallback_draft.get('markdown'), str):
                    fallback_draft['markdown'] = ''
                    fallback_draft = normalize_structured_assessment_markdown(fallback_draft)
                conservative_fields.update(exhausted)
                if archive:
                    archive.record(f'round-{attempt + 1}-conservative-narrative',
                                   {'paths': exhausted, 'response': fallback_draft})
                preceding_response = fallback_draft
                bounded_repair_findings = []
                scoped = False
            else:
                for path in paths:
                    field_repairs[path] = field_repairs.get(path, 0) + 1
                agent = _agent_with_strict_output_schema(
                    evaluation_evidence_repair_agent, schema_name='aso_evidence_narrative_corrections',
                    schema=narrative_repair_schema(bounded_repair_findings))
        if archive and fallback_draft is None:
            archive.record(f'round-{attempt + 1}-request', {'agent': agent.name, 'prompt': prompt})
        if fallback_draft is not None:
            raw_output = json.dumps(fallback_draft, ensure_ascii=False)
        elif attempt == 0 and initial_response is not None and not scoped:
            raw_output = json.dumps(initial_response, ensure_ascii=False)
            if archive:
                archive.record('retained-initial-draft', initial_response)
        else:
            if not scoped:
                if serialization_attempts >= 3:
                    raise RuntimeError('workbench_response_contract_failed: ' + '; '.join(errors))
                serialization_attempts += 1
            result = await Runner.run(agent, input=prompt, max_steps=4)
            raw_output = result.final_output
        if archive:
            archive.record(f'round-{attempt + 1}-raw-response', {'final_output': raw_output})
        response, rejected_repair_candidate = None, None
        try:
            candidate = _parse_llm_json_object(raw_output, 'workbench_response_agent')
            rejected_repair_candidate = candidate
            response = (apply_bound_narrative_patch(preceding_response, candidate, bounded_repair_findings, payload)
                        if scoped else normalize_evaluation_delivery(candidate, payload))
            if not scoped:
                response = normalize_panel_ranking_rationales(response, payload)
            if not scoped and payload.get('task_type') != 'evaluate_existing_aso_set':
                response = normalize_structured_assessment_markdown(response)
            if archive and not scoped and response != candidate:
                archive.record(f'round-{attempt + 1}-delivery-normalization', response)
            if scoped and response == preceding_response:
                raise ValueError('The scoped correction did not change the reviewed narrative.')
            errors = response_contract_errors(response, payload)
        except (RuntimeError, ValueError) as exc:
            errors = [str(exc)]
        next_repair_findings = []
        if errors and scoped:
            response = deepcopy(preceding_response)
            next_repair_findings = bounded_repair_findings
        if not errors and payload.get('task_type') in {
            'evaluate_existing_aso_set', 'compare_aso_sets', 'build_composite_report',
        }:
            if payload.get('task_type') == 'evaluate_existing_aso_set':
                corrected, chemical_corrections = correct_native_chemical_position_claims(
                    payload, response)
                if chemical_corrections:
                    if archive:
                        archive.record(f'round-{attempt + 1}-native-chemical-correction', {
                            'before': response, 'after': corrected,
                            'corrections': chemical_corrections})
                    response = corrected
                    errors = response_contract_errors(response, payload)
                    if errors:
                        raise RuntimeError('Native chemical correction broke response contract: '
                                           + '; '.join(errors))
            review_attempts += 1
            audit_schema = response_audit_schema(response)
            audit_agent = _agent_with_strict_output_schema(
                evaluation_evidence_audit_agent, schema_name='aso_evaluation_evidence_consistency', schema=audit_schema)
            audit_prompt = render_response_context(response_audit_context(payload, response))
            if archive:
                archive.record(f'round-{attempt + 1}-audited-draft', response)
                archive.record(f'round-{attempt + 1}-audit-request', {'prompt': audit_prompt})
            audit = await _run_schema_validated_agent_once(
                agent=audit_agent, prompt=audit_prompt, schema=audit_schema,
                error_prefix='evaluation_evidence_consistency_review',
                contract_validator=lambda result: _json_schema_validation_errors(result, audit_schema)
                    or response_audit_contract_errors(result, response, payload),
                attempt_observer=(lambda number, data: archive.record(f'round-{attempt + 1}-audit-call-{number}', data)) if archive else None,
            )
            if archive:
                archive.record(f'round-{attempt + 1}-audit', audit)
            if audit.get('error'):
                raise RuntimeError('evaluation_evidence_consistency_review_failed: ' + str(audit))
            findings = response_audit_repair_findings(audit, response, payload)
            if findings:
                next_repair_findings = findings
                errors = ['Evidence consistency finding: ' + json.dumps(finding, ensure_ascii=False) for finding in findings]
            else:
                orientation_packets = (orientation_audit_packets(payload, response)
                                       if not errors and payload.get('task_type') == 'evaluate_existing_aso_set' else [])
                for packet_index, packet in enumerate(orientation_packets, 1):
                    review_attempts += 1
                    focused_agent = _agent_with_strict_output_schema(
                        orientation_evidence_audit_agent,
                        schema_name='aso_orientation_evidence_consistency', schema=audit_schema)
                    focused_prompt = json.dumps(packet, ensure_ascii=False)
                    if archive:
                        archive.record(f'round-{attempt + 1}-orientation-audit-request-{packet_index}',
                                       {'prompt': focused_prompt})
                    focused = await _run_schema_validated_agent_once(
                        agent=focused_agent, prompt=focused_prompt, schema=audit_schema,
                        error_prefix='orientation_evidence_consistency_review',
                        contract_validator=lambda result: _json_schema_validation_errors(result, audit_schema)
                            or response_audit_contract_errors(result, response, payload),
                        attempt_observer=(lambda number, data, packet_index=packet_index:
                            archive.record(f'round-{attempt + 1}-orientation-audit-{packet_index}-call-{number}', data))
                            if archive else None,
                    )
                    if archive:
                        archive.record(f'round-{attempt + 1}-orientation-audit-{packet_index}', focused)
                    if focused.get('error'):
                        raise RuntimeError('orientation_evidence_consistency_review_failed: ' + str(focused))
                    focused_findings = response_audit_repair_findings(focused, response, payload)
                    if focused_findings:
                        next_repair_findings = focused_findings
                        errors = ['Orientation evidence consistency finding: ' + json.dumps(
                            finding, ensure_ascii=False) for finding in focused_findings]
                        break
            metric_packet = splice_metric_audit_packet(payload, response) if not errors else None
            if metric_packet:
                review_attempts += 1
                metric_agent = _agent_with_strict_output_schema(
                    splice_metric_audit_agent, schema_name='aso_splice_metric_identity', schema=audit_schema)
                if archive:
                    archive.record(f'round-{attempt + 1}-splice-metric-audit-request', metric_packet)
                metric_audit = await _run_schema_validated_agent_once(
                    agent=metric_agent, prompt=render_response_context(metric_packet), schema=audit_schema,
                    error_prefix='splice_metric_identity_review',
                    contract_validator=lambda result: _json_schema_validation_errors(result, audit_schema)
                        or splice_metric_finding_errors(result, response, payload),
                    attempt_observer=(lambda number, data: archive.record(
                        f'round-{attempt + 1}-splice-metric-audit-call-{number}', data)) if archive else None,
                )
                if archive:
                    archive.record(f'round-{attempt + 1}-splice-metric-audit', metric_audit)
                if metric_audit.get('error'):
                    raise RuntimeError('splice_metric_identity_review_failed: ' + str(metric_audit))
                admissible, rejected = filter_splice_metric_findings(metric_audit)
                rejected_metric_findings += len(rejected)
                if archive and rejected:
                    archive.record(f'round-{attempt + 1}-splice-metric-rejected-findings', rejected)
                metric_findings = response_audit_repair_findings({'findings': admissible}, response, payload)
                if metric_findings:
                    next_repair_findings = metric_findings
                    errors = ['Splice metric identity finding: ' + json.dumps(
                        finding, ensure_ascii=False) for finding in metric_findings]
            chemical_packets = (chemical_position_audit_packets(payload, response)
                                if not errors and payload.get('task_type') == 'evaluate_existing_aso_set' else [])
            for packet_index, packet in enumerate(chemical_packets, 1):
                review_attempts += 1
                focused_agent = _agent_with_strict_output_schema(
                    chemical_position_audit_agent,
                    schema_name='aso_chemical_position_consistency', schema=audit_schema)
                if archive:
                    archive.record(f'round-{attempt + 1}-chemical-position-audit-request-{packet_index}', packet)
                focused = await _run_schema_validated_agent_once(
                    agent=focused_agent, prompt=json.dumps(packet, ensure_ascii=False), schema=audit_schema,
                    error_prefix='chemical_position_consistency_review',
                    contract_validator=lambda result: _json_schema_validation_errors(result, audit_schema)
                        or response_audit_contract_errors(result, response, payload),
                    attempt_observer=(lambda number, data, packet_index=packet_index:
                        archive.record(f'round-{attempt + 1}-chemical-position-audit-{packet_index}-call-{number}', data))
                        if archive else None,
                )
                if archive:
                    archive.record(f'round-{attempt + 1}-chemical-position-audit-{packet_index}', focused)
                if focused.get('error'):
                    raise RuntimeError('chemical_position_consistency_review_failed: ' + str(focused))
                admissible, rejected = filter_chemical_position_findings(focused, response, payload)
                rejected_focused_findings += len(rejected)
                if archive and rejected:
                    archive.record(f'round-{attempt + 1}-chemical-position-audit-{packet_index}-rejected-findings', rejected)
                focused_findings = response_audit_repair_findings(
                    {'findings': admissible}, response, payload)
                if focused_findings:
                    next_repair_findings = focused_findings
                    errors = ['Chemical position consistency finding: ' + json.dumps(
                        finding, ensure_ascii=False) for finding in focused_findings]
                    break
            panel_packet = (panel_comparison_audit_packet(payload, response)
                            if not errors and payload.get('task_type') == 'evaluate_existing_aso_set' else None)
            if panel_packet:
                review_attempts += 1
                panel_schema = response_audit_schema(response)
                panel_schema['properties']['findings']['items']['properties']['response_path']['enum'] = list(
                    panel_packet['draft_narrative_fields'])
                panel_agent = _agent_with_strict_output_schema(
                    panel_comparison_audit_agent,
                    schema_name='aso_full_panel_comparison_consistency', schema=panel_schema)
                if archive:
                    archive.record(f'round-{attempt + 1}-panel-audit-request', {'packet': panel_packet})
                panel_audit = await _run_schema_validated_agent_once(
                    agent=panel_agent, prompt=render_response_context(panel_packet), schema=panel_schema,
                    error_prefix='full_panel_comparison_consistency_review',
                    contract_validator=lambda result: _json_schema_validation_errors(result, panel_schema)
                        or panel_comparison_finding_errors(result, response, payload),
                    attempt_observer=(lambda number, data: archive.record(
                        f'round-{attempt + 1}-panel-audit-call-{number}', data)) if archive else None,
                )
                if archive:
                    archive.record(f'round-{attempt + 1}-panel-audit', panel_audit)
                if panel_audit.get('error'):
                    raise RuntimeError('full_panel_comparison_consistency_review_failed: ' + str(panel_audit))
                panel_findings = response_audit_repair_findings(panel_audit, response, payload)
                if panel_findings:
                    next_repair_findings = panel_findings
                    errors = ['Full-panel comparison finding: ' + json.dumps(
                        finding, ensure_ascii=False) for finding in panel_findings]
            if not errors:
                response['native_consistency_review'] = response_audit_receipt(
                    response, payload, attempts=review_attempts, model=str(evaluation_evidence_audit_agent.model))
                response['native_consistency_review']['orientation_audit_packets'] = len(
                    orientation_packets if payload.get('task_type') == 'evaluate_existing_aso_set' else [])
                response['native_consistency_review']['chemical_position_audit_packets'] = len(chemical_packets)
                response['native_consistency_review']['chemical_position_findings_rejected_as_unverified'] = rejected_focused_findings
                response['native_consistency_review']['full_panel_comparison_audit'] = bool(panel_packet)
                response['native_consistency_review']['splice_metric_identity_audit'] = bool(metric_packet)
                response['native_consistency_review']['splice_metric_findings_rejected_outside_scope'] = rejected_metric_findings
                if conservative_fields:
                    response['native_consistency_review']['conservative_narrative_fields'] = sorted(conservative_fields)
        if errors and not scoped and all('Unknown evaluation measurement reference' in error for error in errors):
            from .evaluation_evidence import unsupported_measurement_reference_findings
            citation_findings = unsupported_measurement_reference_findings(response, payload)
            if citation_findings:
                next_repair_findings = response_audit_repair_findings(
                    {'findings': citation_findings}, response, payload)
        if archive:
            archive.record(f'round-{attempt + 1}-validation', {'errors': errors, 'findings': next_repair_findings, 'field_repair_attempts': dict(field_repairs)})
        if not errors:
            return response
        preceding_response = response
        bounded_repair_findings = next_repair_findings
        correction = {
            'source': payload, 'contract_errors': errors,
            'preceding_response': response if response is not None else raw_output,
            'rejected_repair_candidate': rejected_repair_candidate,
            'evidence_consistency_findings': bounded_repair_findings,
            'allowed_narrative_repair_paths': sorted({finding['response_path'] for finding in bounded_repair_findings}),
        }
        if bounded_repair_findings:
            correction['output_schema'] = narrative_repair_schema(bounded_repair_findings)
        else:
            if delivery_schema:
                correction['output_schema'] = delivery_schema
            correction['instruction'] = 'Correct only the listed serialization or citation errors in the preceding response. Preserve evidence, row identities and biological uncertainty. Return the complete response.'
        prompt = render_response_context(correction)


async def _run_sandbox_analysis_agent_once(payload: Dict[str, Any]) -> Dict[str, Any]:
    repair_context = payload.get("execution_repair")
    if isinstance(repair_context, dict) and repair_context.get("previous_code"):
        from .analysis_repair import repair_schema, apply_program_repair
        from .sandbox_analysis_agent import analysis_program_repair_agent
        code = repair_context["previous_code"]
        schema = repair_schema(code, repair_context.get("previous_plan") or {})
        agent = _agent_with_strict_output_schema(
            analysis_program_repair_agent, schema_name="aso_analysis_program_repair", schema=schema)
        def validate(candidate):
            errors = _json_schema_validation_errors(candidate, schema)
            if errors:
                return errors
            try:
                apply_program_repair(repair_context.get("previous_plan") or {}, code, candidate)
            except (ValueError, SyntaxError) as exc:
                return [str(exc)]
            return []
        repair = await _run_schema_validated_agent_once(
            agent=agent, prompt=json.dumps({**payload, "output_schema": schema,
                "source_lines": [{"line": index, "text": line} for index, line in enumerate(code.splitlines(), 1)]},
                ensure_ascii=False), schema=schema, error_prefix="analysis_program_repair",
            contract_validator=validate)
        if repair.get("error"):
            return {"python_code": "", "error": repair}
        return apply_program_repair(repair_context.get("previous_plan") or {}, code, repair)
    from .sandbox_analysis_agent import design_workbook_analysis_agent
    agent = design_workbook_analysis_agent if payload.get("source_bound_design_workbooks") else sandbox_analysis_agent
    result = await Runner.run(
        agent,
        input=json.dumps(payload, ensure_ascii=False, indent=2),
        max_steps=4,
    )
    return _parse_llm_json_object(result.final_output, "sandbox_analysis_agent")


async def _run_child_clarification_resolution_agent_once(payload: Dict[str, Any]) -> Dict[str, Any]:
    result = await Runner.run(
        child_clarification_resolution_agent,
        input=json.dumps(payload, ensure_ascii=False, indent=2),
        max_steps=4,
    )
    return _parse_llm_json_object(result.final_output, "child_clarification_resolution_agent")


async def _run_analysis_contract_review_agent_once(payload: Dict[str, Any]) -> Dict[str, Any]:
    from .analysis_review import review_schema
    from .sandbox_analysis_agent import analysis_contract_review_agent
    schema = review_schema(payload["program"])
    agent = _agent_with_strict_output_schema(
        analysis_contract_review_agent, schema_name="aso_analysis_contract_review", schema=schema)
    return await _run_schema_validated_agent_once(
        agent=agent, prompt=json.dumps(payload, ensure_ascii=False), schema=schema,
        error_prefix="analysis_contract_review")


async def _run_cross_species_ortholog_selection_agent_once(payload: Dict[str, Any]) -> Dict[str, Any]:
    result = await Runner.run(
        cross_species_ortholog_selection_agent,
        input=json.dumps(payload, ensure_ascii=False, indent=2),
        max_steps=4,
    )
    return _parse_llm_json_object(result.final_output, "cross_species_ortholog_selection_agent")


def _run_child_clarification_resolution_sync(payload: Dict[str, Any]) -> Dict[str, Any]:
    return run_async_from_sync(
        lambda: _run_child_clarification_resolution_agent_once(payload)
    )


def _run_cross_species_ortholog_selection_sync(payload: Dict[str, Any]) -> Dict[str, Any]:
    return run_async_from_sync(
        lambda: _run_cross_species_ortholog_selection_agent_once(payload)
    )


def _normalize_child_clarification_resolution(
    resolution: Any,
    child_questions: List[str],
) -> List[Dict[str, str]]:
    questions = _normalize_questions_input(child_questions)
    if not isinstance(resolution, dict) or not questions:
        return []
    status = str(resolution.get("status") or "").strip().lower()
    if status not in {"resolved", "ready"}:
        return []
    raw_answers = resolution.get("answers")
    normalized = _normalize_clarification_answers(raw_answers, questions)
    answers_by_question: Dict[str, str] = {}
    ordered_answers: List[str] = []
    for item in normalized:
        if not isinstance(item, dict):
            continue
        question = str(item.get("question") or "").strip()
        answer = str(item.get("answer") or "").strip()
        if answer:
            ordered_answers.append(answer)
        if question and answer:
            answers_by_question[question] = answer
    resolved: List[Dict[str, str]] = []
    for idx, question in enumerate(questions):
        answer = answers_by_question.get(question)
        if not answer and idx < len(ordered_answers):
            answer = ordered_answers[idx]
        if not answer:
            return []
        resolved.append({"question": question, "answer": answer})
    return resolved


def _resolve_child_clarification_from_inherited_context(
    *,
    parent_request: str,
    parent_qa_history: List[Dict[str, str]],
    task: Dict[str, Any],
    task_context: Dict[str, Any],
    child_questions: List[str],
    child_reason: str = "",
    child_context: str = "",
    direct_artifact_context: Optional[Dict[str, Any]] = None,
    completed_dependency_results: Optional[List[Dict[str, Any]]] = None,
    resolver: Optional[Any] = None,
) -> List[Dict[str, str]]:
    questions = _normalize_questions_input(child_questions)
    if not questions:
        return []
    inherited_target_context = _target_context_from_clarification_answers(parent_qa_history)
    if inherited_target_context and all(_clarification_question_mentions_target_context(question) for question in questions):
        return [{"question": question, "answer": inherited_target_context} for question in questions]
    context = task_context if isinstance(task_context, dict) else {}
    structured_goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
    payload = {
        "parent_request": str(parent_request or "").strip(),
        "parent_clarification_history": deepcopy(parent_qa_history if isinstance(parent_qa_history, list) else []),
        "task": deepcopy(task if isinstance(task, dict) else {}),
        "task_context": deepcopy(context),
        "task_structured_goal": deepcopy(structured_goal),
        "direct_artifact_context": deepcopy(
            direct_artifact_context
            if isinstance(direct_artifact_context, dict)
            else {}
        ),
        "completed_dependency_results": deepcopy(
            completed_dependency_results
            if isinstance(completed_dependency_results, list)
            else []
        ),
        "child_questions": questions,
        "child_reason": str(child_reason or "").strip(),
        "child_context": str(child_context or "").strip(),
    }
    try:
        resolution = resolver(payload) if callable(resolver) else _run_child_clarification_resolution_sync(payload)
    except Exception:
        return []
    return _normalize_child_clarification_resolution(resolution, questions)


def _normalize_clarification_answers(raw_answers: Any, pending_questions: Optional[List[str]] = None) -> List[Dict[str, Any]]:
    pending = [str(q).strip() for q in (pending_questions or []) if str(q).strip()]
    normalized: List[Dict[str, Any]] = []

    raw_answers = _decode_json_like(raw_answers)
    if isinstance(raw_answers, dict):
        candidate = raw_answers.get("answers")
        raw_answers = candidate if isinstance(candidate, list) else [raw_answers]

    if isinstance(raw_answers, str):
        raw_answers = _decode_json_like(raw_answers)
    if isinstance(raw_answers, dict):
        candidate = raw_answers.get("answers")
        raw_answers = candidate if isinstance(candidate, list) else [raw_answers]
    if isinstance(raw_answers, str):
        raw_answers = [raw_answers]

    if not isinstance(raw_answers, list):
        return []

    for idx, entry in enumerate(raw_answers):
        entry = _decode_json_like(entry)
        question = ""
        answer = ""
        evidence_refs: List[str] = []
        if isinstance(entry, dict):
            question = str(entry.get("question") or "").strip()
            answer = str(entry.get("answer") or "").strip()
            evidence_refs = _clarification_evidence_refs(entry)
            parsed_question = _decode_json_like(question)
            if isinstance(parsed_question, list):
                parsed_question_items = [str(item).strip() for item in parsed_question if str(item).strip()]
                if parsed_question_items:
                    if idx < len(parsed_question_items):
                        question = parsed_question_items[idx]
                    else:
                        question = parsed_question_items[0]
            elif isinstance(parsed_question, dict):
                for key in ("question", "text", "value", "label"):
                    candidate = str(parsed_question.get(key) or "").strip()
                    if candidate:
                        question = candidate
                        break
            parsed_answer = _decode_json_like(answer)
            if isinstance(parsed_answer, dict):
                nested_answer = str(parsed_answer.get("answer") or "").strip()
                nested_question = str(parsed_answer.get("question") or "").strip()
                if nested_answer:
                    answer = nested_answer
                if not question and nested_question:
                    question = nested_question
        else:
            answer = str(entry or "").strip()
        if not question and idx < len(pending):
            question = pending[idx]
        elif pending and question and question not in pending and idx < len(pending):
            question = pending[idx]
        # Drop malformed placeholder fragments that can appear from bad tool-call serialization.
        if answer and not re.search(r"[A-Za-z0-9]", answer):
            answer = ""
        if not answer:
            continue
        normalized_entry: Dict[str, Any] = {
            "question": question,
            "answer": answer,
        }
        if evidence_refs:
            normalized_entry["evidence_refs"] = evidence_refs
        normalized.append(normalized_entry)
    return normalized


def _match_transcript_confirmation_answer_label(
    answer_item: Any,
    pending_items: List[Dict[str, Any]],
) -> str:
    if not isinstance(answer_item, dict):
        return ""
    question_text = str(answer_item.get("question") or "").strip()
    if not question_text:
        return ""
    for pending_item in pending_items:
        if not isinstance(pending_item, dict):
            continue
        label = str(pending_item.get("isoform_label") or "").strip()
        if not label:
            continue
        quoted_variants = (
            f"'{label}'",
            f'"{label}"',
            f"`{label}`",
            f"‘{label}’",
            f"“{label}”",
        )
        if any(variant in question_text for variant in quoted_variants) or label in question_text:
            return label
    return ""


def _index_transcript_confirmation_answers(
    normalized_answers: List[Dict[str, str]],
    pending_items: List[Dict[str, Any]],
) -> Tuple[Dict[str, Dict[str, str]], List[Dict[str, str]], bool]:
    answers_by_label: Dict[str, Dict[str, str]] = {}
    positional_answers: List[Dict[str, str]] = []
    saw_question_text = False
    for answer_item in normalized_answers:
        if not isinstance(answer_item, dict):
            continue
        if str(answer_item.get("question") or "").strip():
            saw_question_text = True
        label = _match_transcript_confirmation_answer_label(answer_item, pending_items)
        if label:
            answers_by_label.setdefault(label, answer_item)
        else:
            positional_answers.append(answer_item)
    return answers_by_label, positional_answers, not saw_question_text


def _resolve_artifact_ref_paths(request_envelope: Dict[str, Any]) -> List[str]:
    refs = request_envelope.get("artifact_refs")
    if isinstance(refs, str):
        refs = [refs]
    if not isinstance(refs, list):
        return []
    resolved: List[str] = []
    seen: Set[str] = set()
    for item in refs:
        if isinstance(item, dict):
            raw = item.get("path") or item.get("run_dir") or item.get("ref")
        else:
            raw = item
        path = str(raw or "").strip()
        if not path or path in seen:
            continue
        seen.add(path)
        resolved.append(path)
    return resolved


def _artifact_ref_is_local_path(ref: str) -> bool:
    text = str(ref or "").strip()
    if not text:
        return False
    return re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", text) is None


def _artifact_ref_path(ref: str) -> Path:
    path = Path(str(ref or "").strip()).expanduser()
    if not path.is_absolute():
        path = (_repo_root() / path).resolve()
    return path


def _artifact_ref_availability(refs: List[str]) -> Dict[str, List[str]]:
    usable: List[str] = []
    missing_local: List[str] = []
    for ref in refs:
        text = str(ref or "").strip()
        if not text:
            continue
        if not _artifact_ref_is_local_path(text):
            usable.append(text)
            continue
        path = _artifact_ref_path(text)
        if path.exists():
            usable.append(text)
        else:
            missing_local.append(str(path))
    return {"usable": usable, "missing_local": missing_local}


def _missing_artifact_refs_question(missing_refs: Any = None) -> str:
    refs = [str(item).strip() for item in (missing_refs or []) if str(item).strip()]
    if refs:
        shown_refs = refs[:3]
        question = (
            "The referenced artifact path does not exist locally: "
            + "; ".join(shown_refs)
        )
        if len(refs) > len(shown_refs):
            question += f"; and {len(refs) - len(shown_refs)} more"
        question += (
            ". Please provide a valid run directory, artifact file, or ASO set source."
        )
        return question
    return (
        "The referenced artifact path does not exist locally. Please provide a valid run directory, "
        "artifact file, or ASO set source."
    )


_TEXT_ARTIFACT_SUFFIXES = {
    ".json",
    ".md",
    ".txt",
    ".csv",
    ".tsv",
    ".log",
    ".html",
    ".gb",
    ".gbk",
    ".genbank",
    ".fa",
    ".fasta",
    ".gtf",
    ".gff",
    ".gff3",
    ".bed",
}

_SNAPGENE_ARTIFACT_SUFFIXES = {".dna", ".gb", ".gbk", ".genbank", ".snapgene"}

_ARTIFACT_INDEX_TABLE_SUFFIXES = {".csv", ".tsv", ".tab", ".json", ".xlsx"}
_ARTIFACT_INDEX_MAX_FILES = 400
_ARTIFACT_INDEX_MAX_DEPTH = 8
_ARTIFACT_INDEX_SAMPLE_ROWS = 5
_ARTIFACT_INDEX_ROW_SCAN_LIMIT = 20000
_ARTIFACT_INDEX_MAX_CELL_CHARS = 180
_ARTIFACT_INDEX_EXCLUDED_DIRS = {
    ".git",
    ".pytest_cache",
    "__pycache__",
    ".mypy_cache",
    ".ruff_cache",
    ".venv",
    "node_modules",
    "controller",
    "state_snapshots",
}


def _artifact_excerpt(path: Path, max_chars: int = 5000) -> str:
    if path.is_dir():
        entries = sorted(child.name for child in path.iterdir())
        preview = "\n".join(entries[:80])
        if len(entries) > 80:
            preview += f"\n... ({len(entries) - 80} more entries)"
        return preview
    suffix = path.suffix.lower()
    if suffix in _TEXT_ARTIFACT_SUFFIXES:
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                text = handle.read(max_chars + 1)
        except Exception as exc:
            return f"<read failed: {exc}>"
        if len(text) > max_chars:
            return text[:max_chars] + "\n... <truncated>"
        return text
    return f"<binary_or_unsupported: {path.name}>"


def _artifact_index_rel_path(path: Path, root: Path) -> str:
    try:
        return str(path.relative_to(root))
    except Exception:
        return path.name


def _artifact_index_clean_cell(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, (int, float, bool)):
        return value
    text = str(value).replace("\r", " ").replace("\n", " ").strip()
    if len(text) > _ARTIFACT_INDEX_MAX_CELL_CHARS:
        return text[:_ARTIFACT_INDEX_MAX_CELL_CHARS] + "... <truncated>"
    return text


def _artifact_index_row_dict(headers: List[str], values: List[Any]) -> Dict[str, Any]:
    row: Dict[str, Any] = {}
    for idx, value in enumerate(values):
        header = headers[idx] if idx < len(headers) and headers[idx] else f"column_{idx + 1}"
        row[str(header)] = _artifact_index_clean_cell(value)
    return row


def _artifact_kind(path: Path, rel_path: str = "") -> str:
    name = path.name.lower()
    rel = str(rel_path or path.name).replace("\\", "/").lower()
    suffix = path.suffix.lower()
    if path.is_dir():
        return "directory"
    if name == "report.md":
        return "run_report"
    if name in {"goal_intake_report.html", "report.html"}:
        return "html_report"
    if name == "generated_aso_set.json":
        return "generated_aso_set"
    if name == "generated_filter_trace.json":
        return "filter_trace"
    if name == "request_envelope.json":
        return "request_envelope"
    if name == "goal_intake.json":
        return "goal_intake"
    if name == "structured_goal.json":
        return "structured_goal"
    if name == "task_index.json":
        return "task_index"
    if ".route." in name or rel.startswith("strategy_routes/") or "/strategy_routes/" in rel:
        return "strategy_route_table"
    if "splice" in rel and suffix in _ARTIFACT_INDEX_TABLE_SUFFIXES:
        return "splice_prediction_table"
    if "existing_aso_evaluation" in name or "provided_aso" in rel:
        return "provided_aso_evaluation"
    if "scored_uniqueness" in name or "uniqueness_ranked" in name or "scored_tiles" in name:
        return "ranked_candidate_table"
    if suffix == ".xlsx":
        return "spreadsheet"
    if suffix in {".csv", ".tsv", ".tab"}:
        return "table"
    if suffix == ".json":
        return "json"
    if suffix in {".md", ".txt", ".log"}:
        return "text"
    if suffix in {".html", ".htm"}:
        return "html"
    return "other"


def _artifact_delimited_table_summary(path: Path) -> Dict[str, Any]:
    delimiter = "\t" if path.suffix.lower() in {".tsv", ".tab"} else ","
    rows_seen = 0
    sample_rows: List[Dict[str, Any]] = []
    headers: List[str] = []
    try:
        # Exported evidence cells can contain complete alignment records.  The
        # csv module's 128 KiB default is smaller than a legitimate cell and
        # must not turn a completed analysis into a terminal report failure.
        csv.field_size_limit(max(csv.field_size_limit(), min(path.stat().st_size, 2**31 - 1)))
        with path.open("r", encoding="utf-8", errors="replace", newline="") as handle:
            sample_text = handle.read(8192)
            handle.seek(0)
            if path.suffix.lower() not in {".tsv", ".tab"}:
                try:
                    delimiter = csv.Sniffer().sniff(sample_text, delimiters="\t,;").delimiter
                except Exception:
                    delimiter = ","
            reader = csv.reader(handle, delimiter=delimiter)
            first = next(reader, None)
            if first is None:
                return {
                    "table_format": "delimited",
                    "delimiter": delimiter,
                    "row_count": 0,
                    "columns": [],
                    "sample_rows": [],
                }
            headers = [str(item or "").strip() or f"column_{idx + 1}" for idx, item in enumerate(first)]
            for raw_row in reader:
                rows_seen += 1
                if len(sample_rows) < _ARTIFACT_INDEX_SAMPLE_ROWS:
                    sample_rows.append(_artifact_index_row_dict(headers, list(raw_row)))
                if rows_seen >= _ARTIFACT_INDEX_ROW_SCAN_LIMIT:
                    break
    except Exception as exc:
        return {"table_format": "delimited", "error": str(exc)}
    return {
        "table_format": "delimited",
        "delimiter": "\\t" if delimiter == "\t" else delimiter,
        "row_count": rows_seen,
        "row_count_truncated": rows_seen >= _ARTIFACT_INDEX_ROW_SCAN_LIMIT,
        "columns": headers,
        "sample_rows": sample_rows,
    }


def _artifact_json_table_rows(payload: Any) -> Tuple[List[Dict[str, Any]], str, Dict[str, Any]]:
    metadata: Dict[str, Any] = {}
    if isinstance(payload, dict):
        metadata["top_level_keys"] = sorted(str(key) for key in payload.keys())[:80]
        for key in ("rows", "records", "candidates", "tiles", "results", "data"):
            rows = payload.get(key)
            if isinstance(rows, list):
                return [dict(row) for row in rows if isinstance(row, dict)], key, metadata
        return [], "", metadata
    if isinstance(payload, list):
        return [dict(row) for row in payload if isinstance(row, dict)], "<root>", metadata
    return [], "", metadata


def _artifact_json_summary(path: Path) -> Dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except Exception as exc:
        return {"table_format": "json", "error": str(exc)}
    rows, container_key, metadata = _artifact_json_table_rows(payload)
    columns: List[str] = []
    seen: Set[str] = set()
    for row in rows[:100]:
        for key in row.keys():
            text = str(key)
            if text not in seen:
                seen.add(text)
                columns.append(text)
    sample_rows = [
        {str(key): _artifact_index_clean_cell(value) for key, value in row.items()}
        for row in rows[:_ARTIFACT_INDEX_SAMPLE_ROWS]
    ]
    summary = {
        "table_format": "json",
        "row_container": container_key,
        "row_count": len(rows),
        "columns": columns,
        "sample_rows": sample_rows,
        **metadata,
    }
    if isinstance(payload, dict):
        summary["object_key_count"] = len(payload)
    return summary


def _artifact_xlsx_summary(path: Path) -> Dict[str, Any]:
    try:
        from openpyxl import load_workbook
    except Exception as exc:
        return {"table_format": "xlsx", "error": f"openpyxl_unavailable: {exc}"}
    try:
        workbook = load_workbook(path, read_only=True, data_only=True)
    except Exception as exc:
        return {"table_format": "xlsx", "error": str(exc)}
    sheets: List[Dict[str, Any]] = []
    try:
        for sheet_name in workbook.sheetnames[:12]:
            worksheet = workbook[sheet_name]
            rows_iter = worksheet.iter_rows(values_only=True)
            first = next(rows_iter, None)
            headers = [
                str(item).strip() if item not in (None, "") else f"column_{idx + 1}"
                for idx, item in enumerate(first or [])
            ]
            sample_rows: List[Dict[str, Any]] = []
            for row_idx, raw_row in enumerate(rows_iter, start=1):
                if row_idx > _ARTIFACT_INDEX_SAMPLE_ROWS:
                    break
                sample_rows.append(_artifact_index_row_dict(headers, list(raw_row or [])))
            sheets.append(
                {
                    "sheet_name": sheet_name,
                    "row_count": max(0, int(worksheet.max_row or 0) - 1),
                    "column_count": int(worksheet.max_column or len(headers) or 0),
                    "columns": headers,
                    "sample_rows": sample_rows,
                }
            )
    finally:
        try:
            workbook.close()
        except Exception:
            pass
    first_sheet = sheets[0] if sheets else {}
    return {
        "table_format": "xlsx",
        "sheet_count": len(sheets),
        "sheets": sheets,
        "row_count": first_sheet.get("row_count", 0),
        "columns": first_sheet.get("columns", []),
        "sample_rows": first_sheet.get("sample_rows", []),
    }


def _artifact_table_summary(path: Path) -> Optional[Dict[str, Any]]:
    suffix = path.suffix.lower()
    if suffix in {".csv", ".tsv", ".tab"}:
        return _artifact_delimited_table_summary(path)
    if suffix == ".json":
        return _artifact_json_summary(path)
    if suffix == ".xlsx":
        return _artifact_xlsx_summary(path)
    return None


def _artifact_text_summary(path: Path) -> Dict[str, Any]:
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return {"error": str(exc)}
    lines = text.splitlines()
    headings = [
        line.strip("# ").strip()
        for line in lines
        if line.lstrip().startswith("#") and line.strip("# ").strip()
    ][:12]
    return {
        "line_count": len(lines),
        "char_count": len(text),
        "headings": headings,
        "excerpt": text[:1200] + ("\n... <truncated>" if len(text) > 1200 else ""),
    }


def _iter_artifact_index_files(path: Path) -> Tuple[List[Path], bool]:
    if path.is_file():
        return [path], False
    if not path.exists() or not path.is_dir():
        return [], False
    root_depth = len(path.parts)
    files: List[Path] = []
    truncated = False
    for child in sorted(path.rglob("*")):
        if len(files) >= _ARTIFACT_INDEX_MAX_FILES:
            truncated = True
            break
        try:
            rel_parts = child.relative_to(path).parts
        except Exception:
            rel_parts = child.parts[root_depth:]
        if any(part in _ARTIFACT_INDEX_EXCLUDED_DIRS for part in rel_parts):
            continue
        if is_controller_rel(rel_parts):
            continue
        if len(rel_parts) > _ARTIFACT_INDEX_MAX_DEPTH:
            continue
        if not child.is_file():
            continue
        files.append(child)
    return files, truncated


def _artifact_index_entry(path: Path, root: Path) -> Dict[str, Any]:
    rel_path = _artifact_index_rel_path(path, root)
    entry: Dict[str, Any] = {
        "path": str(path),
        "rel_path": rel_path,
        "name": path.name,
        "suffix": path.suffix.lower(),
        "kind": _artifact_kind(path, rel_path),
    }
    try:
        stat = path.stat()
        entry["size_bytes"] = int(stat.st_size)
        entry["modified_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(stat.st_mtime))
    except Exception:
        pass
    table_summary = _artifact_table_summary(path) if path.suffix.lower() in _ARTIFACT_INDEX_TABLE_SUFFIXES else None
    if isinstance(table_summary, dict):
        entry["table_summary"] = table_summary
    elif path.suffix.lower() in {".md", ".txt", ".log"}:
        entry["text_summary"] = _artifact_text_summary(path)
    return entry


def _build_artifact_index_for_path(path: Path) -> Dict[str, Any]:
    resolved = path.expanduser()
    if not resolved.is_absolute():
        resolved = (_repo_root() / resolved).resolve()
    if not resolved.exists():
        return {"ref_path": str(path), "path": str(resolved), "exists": False}
    root = resolved if resolved.is_dir() else resolved.parent
    files, truncated = _iter_artifact_index_files(resolved)
    entries = [_artifact_index_entry(file_path, root) for file_path in files]
    by_kind: Dict[str, int] = {}
    for entry in entries:
        kind = str(entry.get("kind") or "other")
        by_kind[kind] = by_kind.get(kind, 0) + 1
    table_entries = [
        entry
        for entry in entries
        if isinstance(entry.get("table_summary"), dict)
        and not (entry["table_summary"].get("error") and not entry["table_summary"].get("columns"))
    ]
    key_kinds = {
        "run_report",
        "html_report",
        "generated_aso_set",
        "filter_trace",
        "strategy_route_table",
        "splice_prediction_table",
        "provided_aso_evaluation",
        "ranked_candidate_table",
        "spreadsheet",
        "request_envelope",
        "goal_intake",
    }
    key_artifacts = [
        {
            "rel_path": entry.get("rel_path"),
            "kind": entry.get("kind"),
            "size_bytes": entry.get("size_bytes"),
            "row_count": (entry.get("table_summary") or {}).get("row_count") if isinstance(entry.get("table_summary"), dict) else None,
            "columns": (entry.get("table_summary") or {}).get("columns", [])[:16] if isinstance(entry.get("table_summary"), dict) else [],
        }
        for entry in entries
        if str(entry.get("kind") or "") in key_kinds
    ]
    return {
        "ref_path": str(path),
        "path": str(resolved),
        "root_path": str(root),
        "exists": True,
        "is_dir": resolved.is_dir(),
        "file_count_indexed": len(entries),
        "file_count_truncated": truncated,
        "total_size_bytes_indexed": sum(int(entry.get("size_bytes") or 0) for entry in entries),
        "by_kind": dict(sorted(by_kind.items())),
        "files": entries,
        "tables": [
            {
                "rel_path": entry.get("rel_path"),
                "path": entry.get("path"),
                "kind": entry.get("kind"),
                "table_summary": entry.get("table_summary"),
            }
            for entry in table_entries
        ],
        "key_artifacts": key_artifacts,
    }


def _build_artifact_index(request_envelope: Dict[str, Any]) -> Dict[str, Any]:
    refs = _resolve_artifact_ref_paths(request_envelope)
    ref_indexes: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for ref in refs[:8]:
        path = _artifact_ref_path(ref) if _artifact_ref_is_local_path(ref) else Path(str(ref))
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        ref_indexes.append(_build_artifact_index_for_path(path))
    aggregate_kind_counts: Dict[str, int] = {}
    table_count = 0
    key_artifact_count = 0
    for item in ref_indexes:
        for kind, count in (item.get("by_kind") or {}).items():
            aggregate_kind_counts[str(kind)] = aggregate_kind_counts.get(str(kind), 0) + int(count or 0)
        table_count += len(item.get("tables") or [])
        key_artifact_count += len(item.get("key_artifacts") or [])
    return {
        "artifact_refs": refs,
        "ref_count": len(ref_indexes),
        "refs": ref_indexes,
        "aggregate": {
            "file_count_indexed": sum(int(item.get("file_count_indexed") or 0) for item in ref_indexes),
            "file_count_truncated": any(bool(item.get("file_count_truncated")) for item in ref_indexes),
            "table_count": table_count,
            "key_artifact_count": key_artifact_count,
            "by_kind": dict(sorted(aggregate_kind_counts.items())),
        },
    }


def _artifact_index_key_tables(artifact_index: Dict[str, Any], limit: int = 20) -> List[Dict[str, Any]]:
    tables: List[Dict[str, Any]] = []
    for ref in artifact_index.get("refs") or []:
        if not isinstance(ref, dict):
            continue
        root_path = str(ref.get("root_path") or ref.get("path") or "")
        for table in ref.get("tables") or []:
            if not isinstance(table, dict):
                continue
            summary = table.get("table_summary") if isinstance(table.get("table_summary"), dict) else {}
            tables.append(
                {
                    "root_path": root_path,
                    "rel_path": table.get("rel_path"),
                    "path": table.get("path"),
                    "kind": table.get("kind"),
                    "row_count": summary.get("row_count"),
                    "columns": summary.get("columns", [])[:20] if isinstance(summary.get("columns"), list) else [],
                    "sample_rows": summary.get("sample_rows", [])[:2] if isinstance(summary.get("sample_rows"), list) else [],
                    "table_format": summary.get("table_format"),
                }
            )
    tables.sort(
        key=lambda item: (
            0 if item.get("kind") in {"generated_aso_set", "strategy_route_table", "provided_aso_evaluation"} else 1,
            str(item.get("rel_path") or ""),
        )
    )
    return tables[:limit]


def _artifact_index_recommendation(kind: Any, rel_path: Any) -> str:
    kind_text = str(kind or "")
    rel = str(rel_path or "")
    if kind_text == "generated_aso_set":
        return "final generated ASO candidate table and top-level ranking fields"
    if kind_text == "strategy_route_table":
        return "route-specific splice-site candidates, splice deltas, coordinates, and off-target fields"
    if kind_text == "filter_trace":
        return "pass/fail/dropout reasons across generated candidate stages"
    if kind_text == "provided_aso_evaluation":
        return "provided-ASO ranking, off-target, isoform, and splice-evaluation outputs"
    if kind_text == "splice_prediction_table":
        return "splice-model predictions and per-site delta evidence"
    if kind_text == "ranked_candidate_table":
        return "ranked candidate spreadsheet/table with scoring and uniqueness fields"
    if kind_text == "run_report":
        return "human-readable run summary and chooser guidance"
    if kind_text == "spreadsheet" or rel.endswith(".xlsx"):
        return "human-readable spreadsheet version of a table"
    return "supporting run artifact"


def _artifact_index_request_wants_inventory(request_text: str) -> bool:
    text = str(request_text or "").lower()
    return bool(
        re.search(
            r"\b(?:where|which\s+files?|what\s+files?|look|inspect|readable|excel|xlsx|spreadsheet|jsons?|outputs?|artifacts?|summary|summari[sz]e|performance)\b",
            text,
        )
    )


def _artifact_analysis_request_prefers_inventory(request_text: str) -> bool:
    text = str(request_text or "").lower()
    return bool(
        re.search(r"\bwhere\s+(?:should|do|can)\s+i\s+look\b", text)
        or re.search(r"\b(?:which|what)\s+files?\b", text)
        or re.search(r"\b(?:excel|xlsx|spreadsheet|human[-\s]?readable|jsons?\s+are\s+not\s+readable)\b", text)
        or re.search(r"\bwhere\s+.*\b(?:choose|select|inspect|evaluate)\b", text)
    )


def _artifact_analysis_request_wants_generated_aso_ranking(request_text: str) -> bool:
    text = str(request_text or "").lower()
    if _artifact_analysis_request_prefers_inventory(text):
        return False
    return bool(
        re.search(r"\btop\s*\d*\b", text)
        or re.search(r"\b(?:rank|ranking|score|scoring|best|choose|select|prioriti[sz]e|likely\s+to\s+work|perform\s+well)\b", text)
        or (re.search(r"\b(?:asos?|candidates?|gapmers?)\b", text) and re.search(r"\b(?:return|list|show|evaluate)\b", text))
    )


def _build_artifact_index_analysis_response(
    *,
    artifact_context: Dict[str, Any],
    response_meta: Dict[str, Any],
    request_envelope: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    artifact_index = artifact_context.get("artifact_index") if isinstance(artifact_context.get("artifact_index"), dict) else {}
    if not artifact_index:
        return None
    request_text = " ".join(
        str(value or "").strip()
        for value in (
            response_meta.get("request_text"),
            response_meta.get("parent_request_text"),
            request_envelope.get("request_text"),
            request_envelope.get("parent_request_text"),
        )
        if str(value or "").strip()
    )
    if not _artifact_index_request_wants_inventory(request_text):
        return None
    aggregate = artifact_index.get("aggregate") if isinstance(artifact_index.get("aggregate"), dict) else {}
    key_tables = _artifact_index_key_tables(artifact_index, limit=18)
    if not key_tables and not aggregate.get("file_count_indexed"):
        return None
    lines = [
        "# Artifact Inventory",
        "",
        (
            f"Indexed {aggregate.get('file_count_indexed', 0)} file(s) across "
            f"{artifact_index.get('ref_count', 0)} referenced artifact root(s); "
            f"found {aggregate.get('table_count', 0)} table-like artifact(s)."
        ),
    ]
    if aggregate.get("file_count_truncated"):
        lines.append("Indexing hit the file-count cap, so the largest folder was summarized rather than exhaustively listed.")
    kind_counts = aggregate.get("by_kind") if isinstance(aggregate.get("by_kind"), dict) else {}
    if kind_counts:
        kind_text = ", ".join(f"{kind}: {count}" for kind, count in sorted(kind_counts.items()))
        lines.extend(["", f"Artifact classes: {kind_text}."])
    if key_tables:
        lines.extend(
            [
                "",
                "## Tables To Inspect",
                "",
                "| Artifact | Kind | Rows | Useful For | Key Columns |",
                "|---|---|---:|---|---|",
            ]
        )
        for table in key_tables:
            columns = [str(item) for item in table.get("columns") or [] if str(item).strip()]
            column_text = ", ".join(f"`{item}`" for item in columns[:8])
            if len(columns) > 8:
                column_text += f", +{len(columns) - 8} more"
            row_count = table.get("row_count")
            row_text = str(row_count) if row_count not in (None, "") else ""
            lines.append(
                "| `{rel}` | {kind} | {rows} | {useful} | {cols} |".format(
                    rel=table.get("rel_path") or table.get("path") or "",
                    kind=table.get("kind") or "",
                    rows=row_text,
                    useful=_artifact_index_recommendation(table.get("kind"), table.get("rel_path")),
                    cols=column_text,
                )
            )
    report_paths: List[str] = []
    for ref in artifact_index.get("refs") or []:
        for artifact in (ref.get("key_artifacts") or []) if isinstance(ref, dict) else []:
            if isinstance(artifact, dict) and artifact.get("kind") in {"run_report", "html_report"}:
                rel = str(artifact.get("rel_path") or "").strip()
                if rel:
                    report_paths.append(rel)
    if report_paths:
        lines.extend(["", "## Human-Readable Reports"])
        for rel in report_paths[:8]:
            lines.append(f"- `{rel}`")
    response = {
        "task_type": "analyze_artifact",
        "analysis_method": "deterministic_artifact_index",
        "request_text": response_meta.get("request_text"),
        "request_summary": response_meta.get("request_summary"),
        "answer_summary": f"Indexed {aggregate.get('file_count_indexed', 0)} artifact files and summarized {aggregate.get('table_count', 0)} table-like outputs.",
        "markdown": "\n".join(lines).strip() + "\n",
        "artifact_index": artifact_index,
        "artifact_context": artifact_context,
        "request_envelope": request_envelope,
        "evidence_refs": [str(table.get("rel_path") or table.get("path") or "") for table in key_tables if table.get("rel_path") or table.get("path")],
    }
    return response


def _artifact_feature_qualifier_values(feature: Any, keys: Tuple[str, ...]) -> List[str]:
    qualifiers = getattr(feature, "qualifiers", {}) or {}
    values: List[str] = []
    for key in keys:
        raw = qualifiers.get(key)
        if raw is None:
            continue
        if isinstance(raw, list):
            values.extend(str(item).strip() for item in raw if str(item).strip())
        else:
            text = str(raw).strip()
            if text:
                values.append(text)
    return values


def _artifact_isoform_group_from_texts(texts: List[str]) -> str:
    for text in texts:
        match = re.search(r"\bisoform\s*:\s*([^;]+)", text, flags=re.IGNORECASE)
        if match:
            return match.group(1).strip()
    for text in texts:
        match = re.search(r"\bexon[\s_-]*(\d+)\b", text, flags=re.IGNORECASE)
        if match:
            prefix = text[: match.start()].strip(" \t\r\n-_:;")
            if prefix:
                return prefix
    return ""


def _summarize_snapgene_genbank_artifact(path: Path) -> Optional[Dict[str, Any]]:
    suffix = path.suffix.lower()
    if suffix not in _SNAPGENE_ARTIFACT_SUFFIXES:
        return None
    try:
        if suffix in {".gb", ".gbk", ".genbank"}:
            from Bio import SeqIO

            record = SeqIO.read(str(path), "genbank")
            feature_iterable = list(getattr(record, "features", []) or [])
            format_name = "genbank"
        else:
            from snapgene_reader import snapgene_file_to_dict, snapgene_file_to_seqrecord

            snap_dict = snapgene_file_to_dict(str(path))
            record = snapgene_file_to_seqrecord(str(path))
            feature_iterable = []
            for feature in snap_dict.get("features") or []:
                name = str(feature.get("name") or feature.get("label") or "").strip()
                note = str(feature.get("notes") or feature.get("note") or "").strip()
                feature_iterable.append(
                    {
                        "name": name,
                        "note": note,
                        "start": int(feature.get("start", 0) or 0),
                        "end": int(feature.get("end", 0) or 0),
                        "strand": feature.get("strand", 1),
                    }
                )
            format_name = "snapgene"
    except Exception as exc:
        return {
            "path": str(path),
            "format": "snapgene_or_genbank",
            "parseable": False,
            "error": str(exc),
        }

    exon_groups: Dict[str, Dict[str, Any]] = {}
    strategy_counts: Dict[str, int] = {}
    feature_count = 0

    for feature in feature_iterable:
        feature_count += 1
        if isinstance(feature, dict):
            label_values = [str(feature.get("name") or "").strip()]
            note_values = [str(feature.get("note") or "").strip()]
            texts = [item for item in (label_values + note_values) if item]
            start = int(feature.get("start", 0) or 0) + 1
            end = int(feature.get("end", 0) or 0)
            strand_raw = feature.get("strand", 1)
            strand = "-" if str(strand_raw).strip() in {"-", "-1"} else "+"
        else:
            label_values = _artifact_feature_qualifier_values(feature, ("label",))
            note_values = _artifact_feature_qualifier_values(feature, ("note",))
            texts = _artifact_feature_qualifier_values(feature, ("label", "note", "gene", "product"))
            start = int(feature.location.start) + 1
            end = int(feature.location.end)
            strand = "-" if int(feature.location.strand or 1) < 0 else "+"

        joined_text = " ".join(texts)
        exon_match = re.search(r"\bexon[\s_-]*(\d+)\b", joined_text, flags=re.IGNORECASE)
        if exon_match:
            group = _artifact_isoform_group_from_texts(texts) or "ungrouped"
            entry = exon_groups.setdefault(
                group,
                {
                    "isoform_label": group,
                    "exon_feature_count": 0,
                    "exon_numbers": set(),
                    "span_start": start,
                    "span_end": end,
                    "strand": strand,
                    "example_labels": [],
                },
            )
            entry["exon_feature_count"] += 1
            entry["span_start"] = min(int(entry["span_start"]), start)
            entry["span_end"] = max(int(entry["span_end"]), end)
            entry["strand"] = strand
            try:
                entry["exon_numbers"].add(int(exon_match.group(1)))
            except Exception:
                pass
            if label_values and len(entry["example_labels"]) < 3:
                entry["example_labels"].append(label_values[0])

        for note in note_values:
            match = re.search(r"\bStrategy\s*:\s*([^;\n\r]+)", note, flags=re.IGNORECASE)
            if match:
                strategy = match.group(1).strip()
                if strategy:
                    strategy_counts[strategy] = strategy_counts.get(strategy, 0) + 1

    selected_group: Optional[Dict[str, Any]] = None
    try:
        from aso_agents.snapgene_ingestion import load_snapgene_exons

        selected_df = load_snapgene_exons(path)
        selected_names = [str(item) for item in selected_df.get("exon_name", []).tolist()]
        selected_group = {
            "exon_feature_count": int(len(selected_df)),
            "first_exon": selected_names[0] if selected_names else None,
            "last_exon": selected_names[-1] if selected_names else None,
        }
        if selected_names:
            selected_group["isoform_label"] = _artifact_isoform_group_from_texts(selected_names) or None
    except Exception as exc:
        selected_group = {"parse_error": str(exc)}

    normalized_groups: List[Dict[str, Any]] = []
    for entry in exon_groups.values():
        item = dict(entry)
        numbers = sorted(int(num) for num in item.get("exon_numbers") or [])
        item["exon_numbers"] = numbers
        normalized_groups.append(item)
    normalized_groups.sort(key=lambda item: (-int(item.get("exon_feature_count") or 0), str(item.get("isoform_label") or "")))

    return {
        "path": str(path),
        "format": format_name,
        "parseable": True,
        "record_id": str(getattr(record, "id", "") or ""),
        "description": str(getattr(record, "description", "") or ""),
        "sequence_length": len(str(getattr(record, "seq", "") or "")),
        "feature_count": feature_count,
        "exon_groups": normalized_groups,
        "selected_exon_group": selected_group,
        "strategy_feature_counts": [
            {"strategy": strategy, "feature_count": count}
            for strategy, count in sorted(strategy_counts.items(), key=lambda item: (-item[1], item[0]))
        ],
    }


def _build_snapgene_artifact_analysis_response(
    *,
    artifact_context: Dict[str, Any],
    response_meta: Dict[str, Any],
    request_envelope: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    entries = artifact_context.get("entries") if isinstance(artifact_context.get("entries"), list) else []
    summaries: List[Dict[str, Any]] = []
    for entry in entries:
        if not isinstance(entry, dict) or not entry.get("exists") or entry.get("is_dir"):
            continue
        path_text = str(entry.get("path") or "").strip()
        if not path_text:
            continue
        summary = _summarize_snapgene_genbank_artifact(Path(path_text))
        if summary is not None:
            summaries.append(summary)
    if not summaries:
        return None

    parseable = [summary for summary in summaries if summary.get("parseable")]
    first_parseable = parseable[0] if parseable else summaries[0]
    summary_text = (
        f"Parsed {len(parseable)} SnapGene/GenBank artifact"
        f"{'' if len(parseable) == 1 else 's'}."
    )
    lines = ["# Artifact Analysis", "", summary_text]
    for summary in summaries:
        lines.extend(["", f"## {Path(str(summary.get('path') or '')).name}"])
        lines.append(f"- Path: {summary.get('path')}")
        if not summary.get("parseable"):
            lines.append(f"- Status: not parseable ({summary.get('error') or 'unknown error'})")
            continue
        description = str(summary.get("description") or "").strip()
        record_id = str(summary.get("record_id") or "").strip()
        lines.append(
            f"- Format: {summary.get('format')}; record: {record_id or 'unknown'}; "
            f"sequence length: {summary.get('sequence_length')} bp; features: {summary.get('feature_count')}"
        )
        if description and description != record_id:
            lines.append(f"- Description: {description}")
        groups = summary.get("exon_groups") if isinstance(summary.get("exon_groups"), list) else []
        if groups:
            group_bits = []
            for group in groups[:8]:
                label = str(group.get("isoform_label") or "ungrouped")
                count = int(group.get("exon_feature_count") or 0)
                numbers = group.get("exon_numbers") if isinstance(group.get("exon_numbers"), list) else []
                number_text = f" exons {numbers[0]}-{numbers[-1]}" if numbers else ""
                group_bits.append(f"{label} ({count}{number_text})")
            lines.append("- Exon groups: " + "; ".join(group_bits))
        selected = summary.get("selected_exon_group") if isinstance(summary.get("selected_exon_group"), dict) else {}
        if selected and not selected.get("parse_error"):
            label = str(selected.get("isoform_label") or "").strip()
            label_text = f" {label}," if label else ""
            lines.append(
                f"- Direct SnapGene exon parser selected:{label_text} "
                f"{selected.get('exon_feature_count')} exon features."
            )
        strategies = summary.get("strategy_feature_counts") if isinstance(summary.get("strategy_feature_counts"), list) else []
        if strategies:
            strategy_bits = [
                f"{item.get('strategy')} ({item.get('feature_count')})"
                for item in strategies[:8]
                if isinstance(item, dict)
            ]
            if strategy_bits:
                lines.append("- Strategy annotations: " + "; ".join(strategy_bits))

    response: Dict[str, Any] = {
        "task_type": "analyze_artifact",
        "analysis_method": "deterministic_snapgene_genbank_parser",
        "request_text": response_meta.get("request_text"),
        "request_summary": response_meta.get("request_summary"),
        "answer_summary": summary_text,
        "markdown": "\n".join(lines).strip() + "\n",
        "artifact_summaries": summaries,
        "artifact_context": artifact_context,
        "request_envelope": request_envelope,
    }
    if first_parseable.get("exon_groups"):
        response["primary_exon_groups"] = first_parseable.get("exon_groups")
    return response


def _directory_key_artifact_excerpts(path: Path) -> Dict[str, str]:
    candidates: List[Path] = [
        _run_path(path, "report.md"),
        _run_path(path, "composite_report.md"),
        _run_path(path, "existing_aso_evaluation.md"),
        _run_path(path, "answer_question.md"),
        _run_path(path, "artifact_analysis.md"),
        _run_path(path, "request_envelope.json"),
        _run_path(path, "goal_intake.json"),
        _run_path(path, "generated_aso_set.json"),
        _run_path(path, "generated_filter_trace.json"),
        _run_path(path, "gapmer_tiling", "gapmer_uniqueness_ranked.csv"),
        _run_path(path, "gapmer_tiling", "gapmer_scored_uniqueness.json"),
        _run_path(path, "tiling", "steric_uniqueness_ranked.csv"),
        _run_path(path, "tiling", "steric_scored_uniqueness.json"),
        _run_path(path, "splice_site_comparisons.csv"),
    ]
    strategy_routes_dir = _run_path(path, "strategy_routes")
    if strategy_routes_dir.exists() and strategy_routes_dir.is_dir():
        for child in sorted(strategy_routes_dir.iterdir()):
            if child.suffix.lower() in {".csv", ".json"}:
                candidates.append(child)
    # A supplied directory need not be a previous MODAL-ASO run. Surface ordinary
    # reference/data files by format, without depending on any conventional name.
    candidates.extend(child for child in sorted(path.iterdir())
                      if not child.name.startswith(".") and not child.is_symlink()
                      and child.is_file() and child.suffix.lower() in _TEXT_ARTIFACT_SUFFIXES)
    excerpts: Dict[str, str] = {}
    for candidate in candidates:
        if not candidate.exists() or candidate.is_dir():
            continue
        rel = str(candidate.relative_to(path))
        if rel in excerpts:
            continue
        excerpts[rel] = _artifact_excerpt(candidate, max_chars=2500)
        if len(excerpts) >= 8:
            break
    return excerpts


def _artifact_float(value: Any, default: Optional[float] = None) -> Optional[float]:
    try:
        if value in (None, "", [], {}):
            return default
        text = str(value).strip()
        if not text or text.lower() in {"none", "nan", "na", "n/a"}:
            return default
        return float(text)
    except Exception:
        return default


def _artifact_int(value: Any, default: int = 0) -> int:
    number = _artifact_float(value, None)
    if number is None:
        return default
    try:
        return int(number)
    except Exception:
        return default


def _artifact_truthy_or_missing(value: Any) -> bool:
    if value in (None, "", [], {}):
        return True
    return str(value).strip().lower() in {"1", "true", "yes", "y", "pass", "passed", "ok"}


def _artifact_first_value(*values: Any) -> Any:
    for value in values:
        if value not in (None, "", [], {}):
            return value
    return None


def _artifact_route_rank_from_text(*values: Any) -> Optional[int]:
    for value in values:
        text = str(value or "")
        match = re.search(r"rank[_-]?0*([0-9]+)", text, flags=re.IGNORECASE)
        if match:
            return _artifact_int(match.group(1), 999)
    return None


def _artifact_list_text(value: Any) -> str:
    if isinstance(value, list):
        return ";".join(str(item) for item in value if str(item).strip())
    if isinstance(value, dict):
        parts = []
        for key, item in value.items():
            if isinstance(item, list):
                rendered = ",".join(str(x) for x in item if str(x).strip())
            else:
                rendered = str(item)
            if rendered.strip():
                parts.append(f"{key}:{rendered}")
        return ";".join(parts)
    return str(value or "").strip()


def _load_generated_aso_rows_from_artifact(path: Path) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    try:
        if path.is_dir():
            generated_path = _run_path(path, "generated_aso_set.json")
            if generated_path.exists():
                rows.extend(_load_generated_aso_rows_from_artifact(generated_path))
            route_dir = _run_path(path, "strategy_routes")
            if route_dir.exists() and route_dir.is_dir():
                rows.extend(_load_generated_aso_rows_from_artifact(route_dir))
            return rows
        if path.name == "generated_aso_set.json" and path.suffix.lower() == ".json":
            payload = json.loads(path.read_text(encoding="utf-8"))
            raw_rows = payload.get("rows") if isinstance(payload, dict) else []
            if isinstance(raw_rows, list):
                for row in raw_rows:
                    if isinstance(row, dict):
                        enriched = dict(row)
                        enriched.setdefault("_artifact_source_path", str(path))
                        rows.append(enriched)
            return rows
        if path.is_dir():
            return rows
        if path.suffix.lower() == ".csv" and path.name.endswith(".route.csv"):
            with path.open(newline="", encoding="utf-8", errors="replace") as handle:
                for row in csv.DictReader(handle):
                    enriched = dict(row)
                    enriched.setdefault("_artifact_source_path", str(path))
                    rows.append(enriched)
            return rows
        if path.is_dir() or path.name != "strategy_routes":
            return rows
    except Exception:
        return rows
    return rows


def _load_strategy_route_rows_from_dir(path: Path) -> List[Dict[str, Any]]:
    if not path.exists() or not path.is_dir():
        return []
    rows: List[Dict[str, Any]] = []
    for route_path in sorted(path.glob("*.route.csv")):
        rows.extend(_load_generated_aso_rows_from_artifact(route_path))
    return rows


def _artifact_candidate_record(row: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    annotations = row.get("source_annotations") if isinstance(row.get("source_annotations"), dict) else {}
    source_path = str(
        _artifact_first_value(
            row.get("_artifact_source_path"),
            row.get("source_path"),
            annotations.get("source_path"),
        )
        or ""
    )
    target_sequence = str(
        _artifact_first_value(
            row.get("sequence"),
            row.get("Sequence"),
            row.get("target_site_sequence"),
            row.get("Target_sequence"),
            annotations.get("target_site_sequence"),
        )
        or ""
    ).strip().upper()
    synthesis_sequence = str(
        _artifact_first_value(
            row.get("reverse_complement_sequence"),
            row.get("Synthesis"),
            row.get("synthesis_antisense_sequence"),
            row.get("chemistry_synthesis"),
            row.get("Chemistry_synthesis"),
            annotations.get("chemistry_synthesis"),
        )
        or ""
    ).strip().upper()
    if target_sequence and not synthesis_sequence:
        synthesis_sequence = _dna_reverse_complement(target_sequence)
    if not target_sequence and synthesis_sequence:
        target_sequence = _dna_reverse_complement(synthesis_sequence)
    if not target_sequence and not synthesis_sequence:
        return None

    route_label = str(
        _artifact_first_value(
            row.get("route_label"),
            row.get("selected_label"),
            row.get("shared_context_label"),
            row.get("primary_label"),
            annotations.get("primary_label"),
            annotations.get("selected_label"),
        )
        or ""
    ).strip()
    route_rank = _artifact_int(row.get("route_rank"), 0) or _artifact_route_rank_from_text(source_path, route_label) or 999

    direction = str(
        _artifact_first_value(
            row.get("selected_direction"),
            annotations.get("primary_direction"),
            row.get("primary_direction"),
        )
        or "decrease"
    ).strip().lower()
    delta_deletion = _artifact_float(
        _artifact_first_value(
            row.get("selected_delta_deletion"),
            row.get("primary_delta_deletion"),
            annotations.get("primary_delta_deletion"),
            row.get("shared_context_delta"),
        ),
        0.0,
    ) or 0.0
    delta_replacement = _artifact_float(
        _artifact_first_value(
            row.get("selected_delta_replacement"),
            row.get("primary_delta_replacement"),
            annotations.get("primary_delta_replacement"),
        ),
        0.0,
    ) or 0.0
    values = [delta_deletion, delta_replacement]
    if direction == "increase":
        directional_effect = max([value for value in values if value > 0] or [0.0])
    else:
        directional_effect = max([-value for value in values if value < 0] or [0.0])

    off_target_total = _artifact_int(
        _artifact_first_value(
            row.get("Off_target_total_upto_mismatch_count"),
            row.get("off_target_total_upto_mismatch_count"),
            annotations.get("off_target_total_upto_mismatch_count"),
        ),
        0,
    )
    off_target_weighted = _artifact_float(
        _artifact_first_value(
            row.get("Off_target_weighted_risk_score"),
            row.get("off_target_weighted_risk_score"),
            annotations.get("off_target_weighted_risk_score"),
        ),
        0.0,
    ) or 0.0
    gc_fraction = _artifact_float(
        _artifact_first_value(row.get("gc_fraction"), row.get("GC"), annotations.get("gc_fraction")),
        None,
    )
    if gc_fraction is not None and gc_fraction > 1:
        gc_fraction = gc_fraction / 100.0
    tile_score = _artifact_float(
        _artifact_first_value(row.get("Score"), row.get("tile_score"), annotations.get("tile_score")),
        0.0,
    ) or 0.0
    repeat_risk = str(
        _artifact_first_value(row.get("repeat_risk_class"), annotations.get("repeat_risk_class"))
        or "none"
    ).strip().lower()
    safeguard_status = _artifact_first_value(row.get("safeguards_passed"), row.get("safeguards_status"), annotations.get("safeguards_status"))
    pass_basic = (
        repeat_risk in {"", "none", "no_repeat_hits"}
        and _artifact_truthy_or_missing(_artifact_first_value(row.get("No_homopolymer"), row.get("no_homopolymer"), annotations.get("no_homopolymer")))
        and _artifact_truthy_or_missing(_artifact_first_value(row.get("No_secondary_structure"), row.get("no_secondary_structure"), annotations.get("no_secondary_structure")))
        and (safeguard_status == "not_configured" or _artifact_truthy_or_missing(safeguard_status))
    )
    if gc_fraction is not None and not (0.20 <= gc_fraction <= 0.80):
        pass_basic = False

    composite_rank_score = (
        directional_effect * 1000.0
        - float(off_target_total) * 8.0
        - off_target_weighted * 0.2
        + tile_score * 0.01
        - float(route_rank) * 0.001
    )
    return {
        "route_rank": route_rank,
        "route_label": route_label,
        "target_site_sequence": target_sequence,
        "synthesis_antisense_sequence": synthesis_sequence,
        "chrom": str(_artifact_first_value(row.get("chrom"), row.get("Chrom"), row.get("selected_site_chrom"), annotations.get("selected_site_chrom")) or "").strip(),
        "start": str(_artifact_first_value(row.get("start"), row.get("Start"), row.get("start_bp"), annotations.get("start_bp")) or "").strip(),
        "end": str(_artifact_first_value(row.get("end"), row.get("End"), row.get("end_bp"), annotations.get("end_bp")) or "").strip(),
        "strand": str(_artifact_first_value(row.get("strand"), row.get("Strand"), row.get("selected_site_strand"), annotations.get("selected_site_strand")) or "").strip(),
        "selected_exon_labels": _artifact_list_text(
            _artifact_first_value(
                annotations.get("selected_transcript_exon_labels"),
                row.get("selected_transcript_exon_labels"),
                row.get("selected_exon_index_pairs"),
                annotations.get("selected_exon_index_pairs"),
            )
        ),
        "selected_delta_deletion": round(delta_deletion, 4),
        "selected_delta_replacement": round(delta_replacement, 4),
        "directional_effect": round(directional_effect, 4),
        "tile_score": round(tile_score, 4),
        "gc_fraction": round(gc_fraction, 4) if gc_fraction is not None else None,
        "off_target_total_upto_mismatch_count": off_target_total,
        "off_target_weighted_risk_score": round(off_target_weighted, 4),
        "off_target_expression_sum": _artifact_float(
            _artifact_first_value(
                row.get("Off_target_expression_sum"),
                row.get("off_target_expression_sum"),
                annotations.get("off_target_expression_sum"),
            ),
            None,
        ),
        "off_target_expression_ratio": _artifact_float(
            _artifact_first_value(
                row.get("Off_target_expression_ratio"),
                row.get("off_target_expression_ratio"),
                annotations.get("off_target_expression_ratio"),
            ),
            None,
        ),
        "repeat_risk_class": repeat_risk or "none",
        "source_path": source_path,
        "passes_basic_filters": pass_basic,
        "composite_rank_score": round(composite_rank_score, 4),
    }


def _collect_artifact_aso_candidate_records(artifact_context: Dict[str, Any]) -> List[Dict[str, Any]]:
    entries = artifact_context.get("entries") if isinstance(artifact_context.get("entries"), list) else []
    raw_rows: List[Dict[str, Any]] = []
    for entry in entries:
        if not isinstance(entry, dict) or not entry.get("exists"):
            continue
        path_text = str(entry.get("path") or "").strip()
        if not path_text:
            continue
        path = Path(path_text)
        if path.is_dir() and path.name == "strategy_routes":
            raw_rows.extend(_load_strategy_route_rows_from_dir(path))
        else:
            raw_rows.extend(_load_generated_aso_rows_from_artifact(path))

    records: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str, str, str, str]] = set()
    for row in raw_rows:
        record = _artifact_candidate_record(row)
        if not record:
            continue
        key = (
            str(record.get("route_label") or ""),
            str(record.get("target_site_sequence") or ""),
            str(record.get("chrom") or ""),
            str(record.get("start") or ""),
            str(record.get("end") or ""),
        )
        if key in seen:
            continue
        seen.add(key)
        records.append(record)
    return records


def _select_top_artifact_asos(
    records: List[Dict[str, Any]],
    *,
    request_text: str,
    limit: int = 10,
) -> List[Dict[str, Any]]:
    eligible = [record for record in records if record.get("passes_basic_filters")]
    if not eligible:
        eligible = list(records)
    eligible.sort(
        key=lambda record: (
            int(record.get("route_rank") or 999),
            -float(record.get("composite_rank_score") or 0.0),
            int(record.get("off_target_total_upto_mismatch_count") or 0),
        )
    )
    route_labels = {str(record.get("route_label") or "") for record in eligible if str(record.get("route_label") or "")}
    request_lower = str(request_text or "").lower()
    has_strategy_route_artifacts = any("strategy_routes" in str(record.get("source_path") or "") for record in eligible)
    diversify_routes = len(route_labels) > 1 and (
        has_strategy_route_artifacts
        or any(token in request_lower for token in ("co-skipping", "co skipping", "pair", "strategy", "route", "junction"))
    )
    selected: List[Dict[str, Any]] = []
    seen_sequences: Set[Tuple[str, str]] = set()
    if diversify_routes:
        by_route: Dict[str, List[Dict[str, Any]]] = {}
        for record in eligible:
            by_route.setdefault(str(record.get("route_label") or ""), []).append(record)
        for route_label in sorted(
            by_route,
            key=lambda label: min(int(item.get("route_rank") or 999) for item in by_route[label]),
        ):
            for record in sorted(
                by_route[route_label],
                key=lambda item: (-float(item.get("composite_rank_score") or 0.0), int(item.get("off_target_total_upto_mismatch_count") or 0)),
            )[:2]:
                key = (str(record.get("route_label") or ""), str(record.get("target_site_sequence") or ""))
                if key in seen_sequences:
                    continue
                selected.append(record)
                seen_sequences.add(key)
                if len(selected) >= limit:
                    break
            if len(selected) >= limit:
                break
    if len(selected) < limit:
        for record in sorted(
            eligible,
            key=lambda item: (-float(item.get("composite_rank_score") or 0.0), int(item.get("route_rank") or 999)),
        ):
            key = (str(record.get("route_label") or ""), str(record.get("target_site_sequence") or ""))
            if key in seen_sequences:
                continue
            selected.append(record)
            seen_sequences.add(key)
            if len(selected) >= limit:
                break
    return [dict(record, top_rank=index + 1) for index, record in enumerate(selected[:limit])]


def _build_generated_aso_artifact_analysis_response(
    *,
    artifact_context: Dict[str, Any],
    response_meta: Dict[str, Any],
    request_envelope: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    request_text = " ".join(
        str(value or "").strip()
        for value in (
            response_meta.get("request_text"),
            response_meta.get("parent_request_text"),
            request_envelope.get("request_text"),
            request_envelope.get("parent_request_text"),
        )
        if str(value or "").strip()
    )
    if not _artifact_analysis_request_wants_generated_aso_ranking(request_text):
        return None
    records = _collect_artifact_aso_candidate_records(artifact_context)
    if not records:
        return None
    top_asos = _select_top_artifact_asos(records, request_text=request_text, limit=10)
    if not top_asos:
        return None

    markdown_lines = [
        "# Artifact ASO Ranking",
        "",
        f"Loaded {len(records)} sequence-bearing ASO candidate row(s) from referenced artifacts.",
        "Ranking used route-passing candidates when available, direction-aware splice effect, off-target burden, repeat-risk fields, route rank, and tile score.",
        "",
        "| Rank | Route | Exon | Target-site sequence | Synthesis antisense | Coord | Effect | Del | Repl | OT <=mm | GC |",
        "|---:|---|---|---|---|---|---:|---:|---:|---:|---:|",
    ]
    for record in top_asos:
        coord_bits = [str(record.get("chrom") or ""), f"{record.get('start')}-{record.get('end')}".strip("-")]
        coord = ":".join(bit for bit in coord_bits if bit)
        strand = str(record.get("strand") or "").strip()
        if strand:
            coord = f"{coord}({strand})" if coord else f"({strand})"
        gc_value = record.get("gc_fraction")
        gc_text = f"{float(gc_value):.2f}" if isinstance(gc_value, (int, float)) else ""
        markdown_lines.append(
            "| {rank} | {route} | {exon} | `{target}` | `{synth}` | {coord} | {effect:.4f} | {delv:.4f} | {repl:.4f} | {ot} | {gc} |".format(
                rank=record.get("top_rank"),
                route=record.get("route_label") or "",
                exon=record.get("selected_exon_labels") or "",
                target=record.get("target_site_sequence") or "",
                synth=record.get("synthesis_antisense_sequence") or "",
                coord=coord,
                effect=float(record.get("directional_effect") or 0.0),
                delv=float(record.get("selected_delta_deletion") or 0.0),
                repl=float(record.get("selected_delta_replacement") or 0.0),
                ot=int(record.get("off_target_total_upto_mismatch_count") or 0),
                gc=gc_text,
            )
        )

    source_paths = sorted({str(record.get("source_path") or "") for record in top_asos if str(record.get("source_path") or "").strip()})
    response: Dict[str, Any] = {
        "task_type": "analyze_artifact",
        "analysis_method": "deterministic_generated_aso_ranker",
        "request_text": response_meta.get("request_text"),
        "request_summary": response_meta.get("request_summary"),
        "answer_summary": f"Ranked {len(top_asos)} ASO candidates from {len(records)} artifact row(s).",
        "markdown": "\n".join(markdown_lines).strip() + "\n",
        "top_ranked_asos": top_asos,
        "candidate_row_count": len(records),
        "source_paths": source_paths,
        "artifact_context": artifact_context,
        "request_envelope": request_envelope,
    }
    return response


def _build_artifact_context(request_envelope: Dict[str, Any]) -> Dict[str, Any]:
    refs = _resolve_artifact_ref_paths(request_envelope)
    artifact_index = _build_artifact_index(request_envelope)
    entries: List[Dict[str, Any]] = []
    for ref in refs[:8]:
        path = Path(ref).expanduser()
        if not path.is_absolute():
            path = (_repo_root() / path).resolve()
        if not path.exists():
            entries.append({"path": str(path), "exists": False})
            continue
        entries.append(
            {
                "path": str(path),
                "exists": True,
                "is_dir": path.is_dir(),
                "excerpt": _artifact_excerpt(path),
                "key_file_excerpts": _directory_key_artifact_excerpts(path) if path.is_dir() else {},
            }
        )
    return {"artifact_refs": refs, "entries": entries, "artifact_index": artifact_index}


def _dna_reverse_complement(sequence: str) -> str:
    normalized = str(sequence or "").strip().upper()
    if not normalized:
        return ""
    return normalized.translate(str.maketrans("ACGTUN", "TGCAAN"))[::-1]


def _extract_bases_from_annotated_aso(value: Any) -> str:
    raw = str(value or "").strip().upper()
    if not raw:
        return ""
    tokens = [token for token in re.split(r"[/\*\s,\-]+", raw) if token]
    if not tokens:
        return ""
    bases: List[str] = []
    for token in tokens:
        clean = re.sub(r"[^A-Z0-9+]", "", token)
        if not clean:
            continue
        if re.fullmatch(r"[ACGTUN]+", clean):
            bases.append(clean)
            continue
        match = re.search(r"([ACGTUN])$", clean)
        if match and re.search(r"[0-9]|[A-Z]{2,}", clean):
            bases.append(match.group(1))
    return "".join(bases).replace("U", "T")


def _normalize_aso_sequence(value: Any) -> Dict[str, Any]:
    raw = str(value or "").strip()
    compact = re.sub(r"[\s\-]+", "", raw).upper().replace("U", "T")
    invalid = sorted({ch for ch in compact if ch not in {"A", "C", "G", "T", "N"}})
    parse_mode = "plain_sequence"
    if raw and invalid and any(marker in raw.upper() for marker in ("/", "*", "MOE", "LNA", "PMO", "PS", "2OM", "2MOE", "RNA", "DNA")):
        extracted = _extract_bases_from_annotated_aso(raw)
        if extracted:
            compact = extracted
            invalid = sorted({ch for ch in compact if ch not in {"A", "C", "G", "T", "N"}})
            parse_mode = "annotated_sequence"
    valid = bool(compact) and not invalid
    gc_count = sum(1 for ch in compact if ch in {"G", "C"})
    length = len(compact)
    gc_fraction = round(gc_count / length, 4) if length else None
    return {
        "raw_sequence": raw,
        "sequence": compact,
        "length": length,
        "gc_fraction": gc_fraction,
        "valid_bases": valid,
        "invalid_bases": invalid,
        "sequence_parse_mode": parse_mode,
    }


_PROVIDED_ASO_FILE_FIELDS: Tuple[str, ...] = (
    "provided_aso_files",
    "provided_aso_file",
    "aso_files",
    "aso_file",
    "aso_table",
    "aso_tables",
    "provided_aso_table",
    "provided_aso_tables",
)

_PROVIDED_ASO_TABLE_SUFFIXES: Set[str] = {".csv", ".tsv", ".txt", ".tab", ".json"}
_PROVIDED_ASO_FILE_CACHE: Dict[Tuple[str, float, int], List[Dict[str, Any]]] = {}

_ASO_SEQUENCE_COLUMN_KEYS: Set[str] = {
    "sequence",
    "seq",
    "aso_sequence",
    "oligo_sequence",
    "oligonucleotide_sequence",
    "target_sequence",
    "target_site_sequence",
    "bases",
}
_ASO_NAME_COLUMN_KEYS: Set[str] = {
    "name",
    "id",
    "aso_id",
    "aso_name",
    "oligo_id",
    "oligo_name",
    "identifier",
    "candidate_id",
    "molecule_id",
}
_ASO_CHEMISTRY_COLUMN_KEYS: Set[str] = {
    "chemistry",
    "chem",
    "modification",
    "modifications",
    "chemistry_string",
    "modified_sequence",
    "synthesis",
    "idt",
    "intended_chemistry",
}


def _normalize_aso_table_column_key(value: Any) -> str:
    text = str(value or "").strip().lower()
    return re.sub(r"[^a-z0-9]+", "_", text).strip("_")


def _aso_sequence_candidate_score(value: Any) -> int:
    payload = _normalize_aso_sequence(value)
    if not payload.get("valid_bases") or int(payload.get("length") or 0) < 8:
        return 0
    raw = str(value or "").strip().upper().replace("U", "T")
    plain = bool(raw) and all(ch in {"A", "C", "G", "T", "N"} for ch in raw)
    return 3 if plain else 1


def _looks_like_aso_table_file_ref(value: Any) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    path = Path(text).expanduser()
    if path.suffix.lower() in _PROVIDED_ASO_TABLE_SUFFIXES:
        return True
    if path.is_absolute():
        return path.exists() and path.is_file()
    repo_path = (_repo_root() / path).resolve()
    return repo_path.exists() and repo_path.is_file()


def _provided_aso_file_path_from_spec(spec: Any) -> str:
    if isinstance(spec, dict):
        for key in ("path", "file", "file_path", "csv_path", "tsv_path", "txt_path", "source", "ref", "uri"):
            value = spec.get(key)
            if value not in (None, "", [], {}):
                return str(value).strip()
        return ""
    return str(spec or "").strip()


def _normalize_provided_aso_file_specs(value: Any) -> List[Any]:
    if isinstance(value, (str, dict)):
        value = [value]
    if not isinstance(value, list):
        return []
    return [deepcopy(item) for item in value if item not in (None, "", [], {})]


def _collect_provided_aso_file_specs(request_envelope: Dict[str, Any]) -> List[Any]:
    specs: List[Any] = []
    seen: Set[str] = set()

    def _add(spec: Any) -> None:
        path_text = _provided_aso_file_path_from_spec(spec)
        if not path_text or path_text in seen:
            return
        seen.add(path_text)
        specs.append(deepcopy(spec))

    for field in _PROVIDED_ASO_FILE_FIELDS:
        for spec in _normalize_provided_aso_file_specs(request_envelope.get(field)):
            _add(spec)

    provided = request_envelope.get("provided_asos")
    provided_items = provided if isinstance(provided, list) else [provided] if isinstance(provided, (str, dict)) else []
    for item in provided_items:
        if isinstance(item, dict):
            has_sequence = any(item.get(key) not in (None, "", [], {}) for key in ("sequence", "aso_sequence", "oligo_sequence", "target_sequence"))
            if not has_sequence and _provided_aso_file_path_from_spec(item):
                _add(item)
        elif isinstance(item, str) and _looks_like_aso_table_file_ref(item):
            _add(item)

    artifact_refs = request_envelope.get("artifact_refs")
    artifact_items = artifact_refs if isinstance(artifact_refs, list) else [artifact_refs] if isinstance(artifact_refs, (str, dict)) else []
    for item in artifact_items:
        artifact_type = ""
        role = ""
        if isinstance(item, dict):
            artifact_type = str(item.get("artifact_type") or item.get("type") or "").strip().lower()
            role = str(item.get("role") or item.get("source_kind") or "").strip().lower()
        path_text = _provided_aso_file_path_from_spec(item)
        if not path_text:
            continue
        # A file extension or sequence-looking content is not an input role.
        # In particular, references and manifests must not become observations.
        panel_roles = {"provided_asos", "provided_aso_set", "provided_aso_file",
                       "submitted_sets_csv", "submitted_aso_sets", "submitted_aso_set",
                       "aso_set", "aso_panel", "aso_table", "oligo_set", "oligo_panel",
                       "oligo_table", "candidate_asos"}
        if artifact_type in panel_roles or role in panel_roles:
            _add(item)

    return specs


def _provided_aso_file_path(spec: Any) -> Optional[Path]:
    path_text = _provided_aso_file_path_from_spec(spec)
    if not path_text:
        return None
    path = Path(path_text).expanduser()
    if not path.is_absolute():
        path = (_repo_root() / path).resolve()
    try:
        if path.exists() and path.is_file():
            return path
    except OSError:
        return None
    return None


def _header_looks_like_aso_table_header(fields: List[str]) -> bool:
    normalized = [_normalize_aso_table_column_key(field) for field in fields]
    known = _ASO_SEQUENCE_COLUMN_KEYS | _ASO_NAME_COLUMN_KEYS | _ASO_CHEMISTRY_COLUMN_KEYS
    if any(key in known for key in normalized):
        return True
    return any("sequence" in key or "chem" in key or key in {"aso", "oligo"} for key in normalized)


def _infer_aso_row_columns(fields: List[str]) -> Dict[str, int]:
    best_idx = -1
    best_score = 0
    for idx, value in enumerate(fields):
        score = _aso_sequence_candidate_score(value)
        if score > best_score:
            best_idx = idx
            best_score = score
    if best_idx < 0:
        return {}

    result: Dict[str, int] = {"sequence": best_idx}
    for idx, value in enumerate(fields):
        if idx == best_idx:
            continue
        text = str(value or "").strip()
        if not text:
            continue
        if "name" not in result and idx < best_idx and _aso_sequence_candidate_score(text) == 0:
            result["name"] = idx
        upper = text.upper()
        if "chemistry" not in result and any(marker in upper for marker in ("/", "*", "MOE", "LNA", "PMO", "PS", "2OM", "2MOE")):
            result["chemistry"] = idx
    if "name" not in result:
        for idx, value in enumerate(fields):
            if idx == best_idx:
                continue
            text = str(value or "").strip()
            if text and _aso_sequence_candidate_score(text) == 0:
                result["name"] = idx
                break
    return result


def _headered_aso_row_columns(headers: List[str], fields: List[str]) -> Dict[str, int]:
    keys = [_normalize_aso_table_column_key(header) for header in headers]

    def _find(candidates: Set[str]) -> Optional[int]:
        for idx, key in enumerate(keys):
            if key in candidates:
                return idx
        return None

    columns: Dict[str, int] = {}
    sequence_idx = _find(_ASO_SEQUENCE_COLUMN_KEYS)
    name_idx = _find(_ASO_NAME_COLUMN_KEYS)
    chemistry_idx = _find(_ASO_CHEMISTRY_COLUMN_KEYS)
    if sequence_idx is None:
        inferred = _infer_aso_row_columns(fields)
        sequence_idx = inferred.get("sequence")
    if sequence_idx is not None:
        columns["sequence"] = sequence_idx
    if name_idx is not None:
        columns["name"] = name_idx
    if chemistry_idx is not None:
        columns["chemistry"] = chemistry_idx
    role_idx = _find({"sequence_role"})
    if role_idx is not None:
        columns["sequence_role"] = role_idx
    return columns


def _safe_field(fields: List[str], idx: Optional[int]) -> str:
    if idx is None or idx < 0 or idx >= len(fields):
        return ""
    return str(fields[idx] or "").strip()


def _provided_aso_entry_from_fields(
    *,
    fields: List[str],
    headers: Optional[List[str]],
    source_path: Path,
    source_row: int,
) -> Optional[Dict[str, Any]]:
    if not fields:
        return None
    columns = (
        _headered_aso_row_columns(headers, fields)
        if headers
        else _infer_aso_row_columns(fields)
    )
    sequence_idx = columns.get("sequence")
    sequence = _safe_field(fields, sequence_idx)
    seq_payload = _normalize_aso_sequence(sequence)
    if not seq_payload.get("valid_bases") or int(seq_payload.get("length") or 0) < 8:
        return None
    name = _safe_field(fields, columns.get("name")) or f"{source_path.stem}_row_{source_row}"
    chemistry = _safe_field(fields, columns.get("chemistry"))
    metadata: Dict[str, Any] = {}
    if headers:
        for idx, header in enumerate(headers):
            if idx >= len(fields) or idx in {columns.get("sequence"), columns.get("name"), columns.get("chemistry")}:
                continue
            header_text = str(header or "").strip()
            if header_text:
                metadata[header_text] = fields[idx]
    entry = {
        "name": name,
        "sequence": sequence,
        "chemistry": chemistry or None,
        "source_file": str(source_path),
        "source_row": source_row,
        "input_metadata": metadata or None,
    }
    role = _safe_field(fields, columns.get("sequence_role"))
    if role:
        entry["sequence_role"] = role
    elif headers and sequence_idx is not None:
        selected_header = _normalize_aso_table_column_key(headers[sequence_idx])
        if selected_header in {"aso_sequence", "oligo_sequence"}:
            entry["sequence_role"] = "antisense_oligo_sequence"
        elif selected_header in {"target_sequence", "target_site_sequence"}:
            entry["sequence_role"] = "target_site_sequence"
    return entry


def _read_provided_aso_json_file(path: Path) -> List[Dict[str, Any]]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return []
    if isinstance(payload, list):
        items = payload
    elif isinstance(payload, dict):
        items = []
        for key in ("provided_asos", "asos", "rows", "data"):
            value = payload.get(key)
            if isinstance(value, list):
                items = value
                break
    else:
        items = []
    rows: List[Dict[str, Any]] = []
    for idx, item in enumerate(items, start=1):
        if not isinstance(item, dict):
            continue
        row = dict(item)
        # Physical source identity belongs to ingestion, not generated JSON fields.
        for field, value in (("source_file", str(path)), ("source_row", idx)):
            if row.get(field) not in (None, value):
                metadata = dict(row.get("input_metadata") or {})
                metadata["declared_" + field] = row[field]
                row["input_metadata"] = metadata
            row[field] = value
        rows.append(row)
    return rows


def _read_provided_aso_delimited_file(path: Path) -> List[Dict[str, Any]]:
    try:
        text = path.read_text(encoding="utf-8-sig")
    except Exception:
        return []
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        return []
    sample = "\n".join(lines[:20])
    delimiter: Optional[str]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters="\t,;")
        delimiter = dialect.delimiter
    except Exception:
        delimiter = "\t" if any("\t" in line for line in lines[:10]) else "," if any("," in line for line in lines[:10]) else None
    if delimiter:
        reader_rows = [row for row in csv.reader(lines, delimiter=delimiter)]
    else:
        reader_rows = [line.split() for line in lines]
    reader_rows = [[str(field or "").strip() for field in row] for row in reader_rows if any(str(field or "").strip() for field in row)]
    if not reader_rows:
        return []
    headers: Optional[List[str]] = None
    data_rows = reader_rows
    if _header_looks_like_aso_table_header(reader_rows[0]):
        headers = reader_rows[0]
        data_rows = reader_rows[1:]
    rows: List[Dict[str, Any]] = []
    offset = 2 if headers else 1
    for idx, fields in enumerate(data_rows, start=offset):
        row = _provided_aso_entry_from_fields(
            fields=fields,
            headers=headers,
            source_path=path,
            source_row=idx,
        )
        if row:
            rows.append(row)
    return rows


def _read_provided_asos_from_file(path: Path) -> List[Dict[str, Any]]:
    try:
        stat = path.stat()
    except OSError:
        return []
    cache_key = (str(path.resolve()), float(stat.st_mtime), int(stat.st_size))
    cached = _PROVIDED_ASO_FILE_CACHE.get(cache_key)
    if cached is not None:
        return deepcopy(cached)
    if path.suffix.lower() == ".json":
        rows = _read_provided_aso_json_file(path)
    else:
        rows = _read_provided_aso_delimited_file(path)
    _PROVIDED_ASO_FILE_CACHE[cache_key] = deepcopy(rows)
    return rows


def _load_provided_asos_from_files(request_envelope: Dict[str, Any]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    seen_paths: Set[Path] = set()
    for spec in _collect_provided_aso_file_specs(request_envelope):
        path = _provided_aso_file_path(spec)
        if path is None or path.resolve() in seen_paths:
            continue
        path = path.resolve()
        seen_paths.add(path)
        rows.extend(_read_provided_asos_from_file(path))
    return rows


def _normalize_provided_asos(request_envelope: Dict[str, Any]) -> List[Dict[str, Any]]:
    provided = request_envelope.get("provided_asos")
    if isinstance(provided, (str, dict)):
        provided = [provided]
    if not isinstance(provided, list):
        provided = []
    file_rows = _load_provided_asos_from_files(request_envelope)
    normalized: List[Dict[str, Any]] = []
    inline_items: List[Any] = []
    for item in provided:
        if isinstance(item, dict):
            has_sequence = any(
                item.get(key) not in (None, "", [], {})
                for key in ("sequence", "aso_sequence", "oligo_sequence", "target_sequence", "Sequence", "seq")
            )
            if not has_sequence and _provided_aso_file_path_from_spec(item):
                continue
        elif isinstance(item, str) and _looks_like_aso_table_file_ref(item):
            continue
        inline_items.append(item)

    file_rows, inline_items = reconcile_file_row_references(
        file_rows, inline_items, lambda value: _normalize_aso_sequence(value)['valid_bases'],
        request_text=request_envelope.get("request_text"))
    for idx, item in enumerate(file_rows + inline_items, start=1):
        if isinstance(item, dict):
            base = dict(item)
            sequence_value = (
                base.get("sequence")
                or base.get("aso_sequence")
                or base.get("oligo_sequence")
                or base.get("target_sequence")
                or base.get("Sequence")
                or base.get("seq")
                or ""
            )
            seq_payload = _normalize_aso_sequence(sequence_value)
            name = str(base.get("name") or base.get("id") or base.get("aso_id") or base.get("Name") or f"provided_aso_{idx:02d}").strip()
            entry = {
                "aso_id": name or f"provided_aso_{idx:02d}",
                "name": name or f"provided_aso_{idx:02d}",
                "source": "provided",
                "chemistry": str(base.get("chemistry") or base.get("Chemistry") or "").strip() or None,
                "platform": str(base.get("platform") or base.get("Platform") or "").strip() or None,
                "notes": str(base.get("notes") or base.get("Notes") or "").strip() or None,
                **seq_payload,
            }
            # Preserve explicit row roles independently of mapping outcomes.
            # A task-wide declaration applies only to rows without their own
            # declaration; chemistry is a weaker, legacy input-role hint.
            target_string_was_selected = (
                base.get("target_sequence") not in (None, "", [], {})
                and all(base.get(key) in (None, "", [], {}) for key in (
                    "sequence", "aso_sequence", "oligo_sequence", "Sequence", "seq",
                ))
            )
            if target_string_was_selected:
                entry["declared_sequence_role"] = "target_site_sequence"
            elif any(base.get(key) not in (None, "", [], {}) for key in ("aso_sequence", "oligo_sequence")):
                entry["declared_sequence_role"] = "antisense_oligo_sequence"
            if base.get("sequence_role") in SEQUENCE_ROLES:
                entry["declared_sequence_role"] = base["sequence_role"]
            if "declared_sequence_role" in entry:
                entry["sequence_role_source"] = "supplied_row"
            for field in ("source_file", "source_row", "input_metadata", "input_origin", "input_reconciliation"):
                if base.get(field) not in (None, "", [], {}):
                    entry[field] = deepcopy(base.get(field))
            identity_keys = {"name", "id", "aso_id", "Name", "sequence", "aso_sequence",
                "oligo_sequence", "target_sequence", "Sequence", "seq", "chemistry", "Chemistry",
                "platform", "Platform", "notes", "Notes", "source_file", "source_row",
                "input_metadata", "input_origin", "input_row_id", "input_reconciliation", "sequence_role"}
            extra_metadata = {k: deepcopy(v) for k, v in base.items() if k not in identity_keys}
            if extra_metadata:
                entry["input_metadata"] = {**extra_metadata, **(entry.get("input_metadata") or {})}
            normalized.append(entry)
        else:
            seq_payload = _normalize_aso_sequence(item)
            normalized.append(
                {
                    "aso_id": f"provided_aso_{idx:02d}",
                    "name": f"provided_aso_{idx:02d}",
                    "source": "provided",
                    "chemistry": None,
                    "platform": None,
                    "notes": None,
                    **seq_payload,
                }
            )
    normalized = reconcile_file_expansions(normalized, len(file_rows), request_envelope.get("request_text"))
    assign_input_row_ids(normalized)
    for entry in normalized:
        shared_role = request_envelope.get("provided_sequence_role")
        if "declared_sequence_role" not in entry:
            if shared_role in SEQUENCE_ROLES:
                entry["declared_sequence_role"] = shared_role
                entry["sequence_role_source"] = "task_context"
            elif entry.get("chemistry") or entry.get("platform"):
                entry["declared_sequence_role"] = "antisense_oligo_sequence"
                entry["sequence_role_source"] = "supplied_row_chemistry"
        sequence = str(entry.get("sequence") or "")
        entry["reverse_complement_sequence"] = _dna_reverse_complement(sequence) if sequence else ""
        entry["comparison_sequence"] = (
            entry["reverse_complement_sequence"]
            if entry.get("declared_sequence_role") == "antisense_oligo_sequence" else sequence
        )
    return normalized


def _entry_sequence_variants(entry: Dict[str, Any]) -> List[Dict[str, str]]:
    variants: List[Dict[str, str]] = []
    seen: Set[str] = set()

    def _push(sequence: Any, orientation: str) -> None:
        normalized = _normalize_aso_sequence(sequence).get("sequence")
        sequence_text = str(normalized or "").strip().upper()
        if not sequence_text or sequence_text in seen:
            return
        seen.add(sequence_text)
        variants.append({"sequence": sequence_text, "orientation": orientation})

    _push(entry.get("comparison_sequence"), "comparison_sequence")
    _push(entry.get("normalized_sequence"), "normalized_sequence")
    _push(entry.get("sequence"), "input_sequence")
    _push(entry.get("reverse_complement_sequence"), "reverse_complement")
    return variants


def _match_entry_against_sequence_set(
    entry: Dict[str, Any],
    sequence_set: Set[str],
) -> Dict[str, Any]:
    for variant in _entry_sequence_variants(entry):
        if variant["sequence"] in sequence_set:
            return {
                "matched": True,
                "matched_sequence": variant["sequence"],
                "match_orientation": variant["orientation"],
            }
    return {"matched": False, "matched_sequence": "", "match_orientation": ""}


def _display_match_orientation(
    input_sequence: Any,
    matched_sequence: Any,
    raw_orientation: Any,
) -> str:
    input_text = str(input_sequence or "").strip().upper()
    matched_text = str(matched_sequence or "").strip().upper()
    orientation = str(raw_orientation or "").strip().lower()
    if input_text and matched_text and input_text != matched_text and _dna_reverse_complement(input_text) == matched_text:
        return "reverse_complement"
    return orientation


def _provided_aso_orientation_interpretation(entry: Dict[str, Any]) -> Dict[str, Any]:
    return interpret_orientation(entry)


def _provided_aso_orientation_markdown(payload: Dict[str, Any]) -> str:
    provided_asos = payload.get("provided_asos") if isinstance(payload.get("provided_asos"), list) else []
    lines: List[str] = []
    for entry in provided_asos:
        if not isinstance(entry, dict):
            continue
        orientation = entry.get("orientation_interpretation")
        if not isinstance(orientation, dict) or not orientation:
            continue
        name = str(entry.get("name") or entry.get("aso_id") or "provided ASO").strip()
        role = str(orientation.get("provided_sequence_role") or "").strip()
        input_sequence = str(orientation.get("input_sequence") or "").strip()
        target_sequence = str(orientation.get("matched_target_sequence") or "").strip()
        antisense_sequence = str(orientation.get("synthesized_antisense_sequence") or "").strip()
        note = str(orientation.get("interpretation_note") or "").strip()
        if not input_sequence or not target_sequence:
            continue
        role_text = role.replace("_", " ") if role else "unknown orientation"
        line = (
            f"- `{name}` input `{input_sequence}` is interpreted as `{role_text}`; "
            f"transcript-oriented target site `{target_sequence}`"
        )
        if antisense_sequence:
            line += f"; synthesized antisense sequence `{antisense_sequence}`"
        line += "."
        if note:
            line += f" {note}"
        lines.append(line)
    if not lines:
        return ""
    return "\n".join(["## Sequence Orientation", *lines]).strip()


def _provided_aso_reference_metrics_markdown(payload: Dict[str, Any]) -> str:
    """Render measured molecule and alignment annotations before prose assessment."""
    entries = payload.get("provided_asos") if isinstance(payload.get("provided_asos"), list) else []
    lines: List[str] = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        name = str(entry.get("name") or entry.get("aso_id") or "provided ASO").strip()
        maximum = entry.get("maximum_homopolymer_run_nt")
        membership = entry.get("principal_reference_exon_membership")
        if not isinstance(membership, dict):
            membership = {}
        fragments = []
        if isinstance(maximum, int):
            fragments.append(f"maximum homopolymer run {maximum} nt")
        if membership.get("status") == "resolved":
            exons = membership.get("exons") if isinstance(membership.get("exons"), list) else []
            ordinals = [str(item.get("transcript_exon_ordinal")) for item in exons
                        if isinstance(item, dict) and item.get("transcript_exon_ordinal") is not None]
            if ordinals:
                mismatch = int(membership.get("alignment_mismatches") or 0)
                fragments.append(
                    f"principal {'exact' if mismatch == 0 else f'{mismatch}-mismatch'} antisense alignment "
                    f"on transcript `{membership.get('transcript_id')}` overlaps annotated exon ordinal(s) {', '.join(ordinals)}"
                )
        elif membership.get("reason"):
            fragments.append(f"exon assignment unmeasured ({membership['reason']})")
        if fragments:
            lines.append(f"- `{name}`: {'; '.join(fragments)}.")
    return "\n".join(["## Supplied-Molecule Reference Checks", *lines]).strip() if lines else ""


def _request_envelope_task_types(request_envelope: Dict[str, Any]) -> Set[str]:
    return _request_task_type_set(request_envelope.get("tasks"))


def _task_context_from_request_envelope(
    request_envelope: Dict[str, Any],
    task: Dict[str, Any],
) -> Dict[str, Any]:
    task_context = task.get("context") if isinstance(task.get("context"), dict) else {}
    default_context = request_envelope.get("default_context") if isinstance(request_envelope.get("default_context"), dict) else {}
    context = deepcopy(default_context)
    context.update(_extract_request_context_fields(request_envelope))
    context.update(_extract_request_context_fields(task))
    context.update(deepcopy(task_context))
    task_deps = {
        str(dep).strip()
        for dep in (task.get("depends_on") or [])
        if str(dep).strip()
    }
    if task_deps:
        artifact_refs = deepcopy(context.get("artifact_refs")) if isinstance(context.get("artifact_refs"), list) else []
        seen_refs = {
            json.dumps(ref, sort_keys=True, default=str) if isinstance(ref, dict) else str(ref)
            for ref in artifact_refs
        }
        for upstream_task in request_envelope.get("tasks") or []:
            if not isinstance(upstream_task, dict) or str(upstream_task.get("task_id") or "").strip() not in task_deps:
                continue
            upstream_context = upstream_task.get("context") if isinstance(upstream_task.get("context"), dict) else {}
            upstream_refs = upstream_context.get("artifact_refs") or upstream_task.get("artifact_refs")
            if not isinstance(upstream_refs, list):
                continue
            for ref in upstream_refs:
                if ref in (None, "", [], {}):
                    continue
                key = json.dumps(ref, sort_keys=True, default=str) if isinstance(ref, dict) else str(ref)
                if key in seen_refs:
                    continue
                artifact_refs.append(deepcopy(ref))
                seen_refs.add(key)
        if artifact_refs:
            context["artifact_refs"] = artifact_refs
    return context


def _task_has_target_context(context: Dict[str, Any]) -> bool:
    for field in ("gene_symbol", "gene_id", "transcript_id", "species", "target_context"):
        value = context.get(field)
        if isinstance(value, str) and value.strip():
            return True
    for field in ("species_targets", "evaluation_targets"):
        value = context.get(field)
        if value not in (None, "", [], {}):
            return True
    return False


def _single_design_structured_goal_from_request_envelope(request_envelope: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(request_envelope, dict):
        return {}
    design_tasks = [
        task
        for task in (request_envelope.get("tasks") or [])
        if isinstance(task, dict) and str(task.get("task_type") or "").strip().lower() == "design_new_asos"
    ]
    if len(design_tasks) != 1:
        return {}

    task = deepcopy(design_tasks[0])
    context = _task_context_from_request_envelope(request_envelope, task)
    goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
    if not goal:
        return {}

    context = deepcopy(context)
    context["structured_goal"] = deepcopy(goal)
    task["context"] = context
    finalized = _finalize_design_task_contract(
        task,
        request_envelope.get("default_context") if isinstance(request_envelope.get("default_context"), dict) else {},
    )
    finalized_context = finalized.get("context") if isinstance(finalized.get("context"), dict) else {}
    finalized_goal = finalized_context.get("structured_goal") if isinstance(finalized_context.get("structured_goal"), dict) else {}
    if not finalized_goal:
        return {}
    return deepcopy(finalized_goal)


def _task_context_provided_asos(context: Dict[str, Any]) -> List[Dict[str, Any]]:
    return _normalize_provided_asos(
        {
            "provided_asos": deepcopy(context.get("provided_asos")),
            "provided_sequence_role": context.get("provided_sequence_role"),
            "provided_aso_files": deepcopy(context.get("provided_aso_files")),
            "artifact_refs": deepcopy(context.get("artifact_refs")),
        }
    )


def _task_context_artifact_refs(context: Dict[str, Any]) -> List[str]:
    structured_goal = (
        context.get("structured_goal")
        if isinstance(context.get("structured_goal"), dict)
        else {}
    )
    refs = _resolve_artifact_ref_paths(
        {"artifact_refs": deepcopy(context.get("artifact_refs"))}
    )
    for ref in _resolve_artifact_ref_paths(
        {"artifact_refs": deepcopy(structured_goal.get("artifact_refs"))}
    ):
        if ref not in refs:
            refs.append(ref)
    return refs


def _iter_structured_aso_set_specs(*containers: Any) -> List[Dict[str, Any]]:
    specs: List[Dict[str, Any]] = []
    for container in containers:
        if not isinstance(container, dict):
            continue
        for field in ("source_sets", "aso_sets", "comparison_sets"):
            value = container.get(field)
            items = value if isinstance(value, list) else [value] if isinstance(value, dict) else []
            for item in items:
                if isinstance(item, dict):
                    specs.append(item)
        for field in ("set_a", "set_b", "left_set", "right_set"):
            value = container.get(field)
            if isinstance(value, dict):
                specs.append(value)
    return specs


def _task_declares_upstream_aso_set_inputs(task: Dict[str, Any], context: Dict[str, Any]) -> bool:
    source_ids: Set[str] = set()
    inputs = task.get("inputs") if isinstance(task.get("inputs"), list) else []
    for item in inputs:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("kind") or "").strip().lower()
        if kind != "aso_set":
            continue
        source_task_id = str(item.get("from_task_id") or item.get("source_task_id") or "").strip()
        if source_task_id:
            source_ids.add(source_task_id)

    structured_goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
    for spec in _iter_structured_aso_set_specs(context, structured_goal):
        source_task_id = str(spec.get("source_task_id") or spec.get("from_task_id") or "").strip()
        if source_task_id:
            source_ids.add(source_task_id)
    return len(source_ids) >= 2


def _task_generated_branch_input_count(task: Dict[str, Any]) -> int:
    inputs = task.get("inputs") if isinstance(task.get("inputs"), list) else []
    count = 0
    for item in inputs:
        if isinstance(item, dict):
            kind = str(item.get("kind") or "").strip().lower()
            source_output = str(item.get("output_key") or item.get("source_output") or item.get("label") or "").strip().lower()
            if kind == "aso_set" or (
                any(token in source_output for token in ("candidate", "aso_set", "aso table", "aso_table"))
                and "report" not in source_output
            ):
                count += 1
        elif isinstance(item, str):
            text = item.strip().lower()
            if (
                any(token in text for token in ("candidate", "aso_set", "aso table", "aso_table"))
                and "report" not in text
            ):
                count += 1
    return count


def _design_task_declares_multiple_generated_sets(task: Dict[str, Any]) -> bool:
    if not isinstance(task, dict) or _normalize_task_type_value(task.get("task_type")) != "design_new_asos":
        return False
    merged_from = task.get("merged_from_task_ids")
    if isinstance(merged_from, list) and len([item for item in merged_from if str(item).strip()]) >= 2:
        return True
    context = task.get("context") if isinstance(task.get("context"), dict) else {}
    goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
    programs = [program for program in goal.get("design_programs") or [] if isinstance(program, dict)]
    if len(programs) >= 2:
        return True
    modalities = {
        str(program.get("modality") or "").strip().lower()
        for program in programs
        if str(program.get("modality") or "").strip()
    }
    return len(modalities) >= 2


def _is_placeholder_default_design_task(request_envelope: Dict[str, Any], task: Dict[str, Any], context: Dict[str, Any]) -> bool:
    if str(task.get("task_type") or "").strip().lower() != "design_new_asos":
        return False
    if str(task.get("task_id") or "").strip() != "task_design_new_asos":
        return False
    if _task_context_has_design_signal(context):
        return False
    structured_goal = request_envelope.get("structured_goal") if isinstance(request_envelope.get("structured_goal"), dict) else {}
    if structured_goal:
        return False
    for field in _REQUEST_CONTEXT_SCALAR_FIELDS + _REQUEST_CONTEXT_COLLECTION_FIELDS:
        value = request_envelope.get(field)
        if value not in (None, "", [], {}):
            return False
    return True


def _explicit_blocked_tasks_by_id(
    request_envelope: Dict[str, Any],
    valid_task_ids: Set[str],
) -> Dict[str, Dict[str, Any]]:
    blocked_entries = request_envelope.get("blocked_tasks")
    if not isinstance(blocked_entries, list):
        return {}
    blocked_by_id: Dict[str, Dict[str, Any]] = {}
    for item in blocked_entries:
        if not isinstance(item, dict):
            continue
        task_id = str(item.get("task_id") or "").strip()
        if not task_id or task_id not in valid_task_ids:
            continue
        existing = blocked_by_id.setdefault(
            task_id,
            {
                "task_id": task_id,
                "label": str(item.get("label") or "").strip(),
                "missing_fields": [],
                "questions": [],
                "reason": "",
            },
        )
        if not existing.get("label"):
            existing["label"] = str(item.get("label") or "").strip()
        for field in _normalize_text_list(item.get("missing_fields") or item.get("issues")):
            if field not in existing["missing_fields"]:
                existing["missing_fields"].append(field)
        for question in _normalize_questions_input(item.get("questions")):
            if question not in existing["questions"]:
                existing["questions"].append(question)
        reason = str(item.get("reason") or "").strip()
        if reason and not existing.get("reason"):
            existing["reason"] = reason
    return blocked_by_id


def _orphan_blocked_tasks(request_envelope: Dict[str, Any], valid_task_ids: Set[str]) -> List[Dict[str, Any]]:
    blocked_entries = request_envelope.get("blocked_tasks")
    if not isinstance(blocked_entries, list):
        return []
    return [
        deepcopy(item)
        for item in blocked_entries
        if isinstance(item, dict)
        and str(item.get("task_id") or "").strip()
        and str(item.get("task_id") or "").strip() not in valid_task_ids
    ]


def _validation_has_blocked_design_tasks(validation: Dict[str, Any]) -> bool:
    task_entries = validation.get("tasks") if isinstance(validation.get("tasks"), dict) else {}
    return any(
        isinstance(entry, dict)
        and _normalize_task_type_value(entry.get("task_type")) == "design_new_asos"
        and str(entry.get("status") or "").strip().lower() == "blocked"
        for entry in task_entries.values()
    )


def _explicit_block_resolved_by_available_inputs(
    explicit_block: Dict[str, Any],
    *,
    task_type: str,
    has_usable_artifact_refs: bool,
    has_artifact_dependency: bool,
) -> bool:
    if not isinstance(explicit_block, dict):
        return False
    fields = _normalize_text_list(explicit_block.get("missing_fields") or explicit_block.get("issues"))
    questions = _normalize_questions_input(explicit_block.get("questions"))
    reason = str(explicit_block.get("reason") or "").strip()
    text = " ".join([*fields, *questions, reason]).lower()

    if task_type == "analyze_artifact" and has_usable_artifact_refs:
        return bool(
            any(
                token in field.lower()
                for field in fields
                for token in ("artifact", "file", "uri", "path", "content")
            )
            or "upload/provide" in text
            or "local filesystem" in text
        )

    if task_type == "design_new_asos" and has_artifact_dependency:
        return bool(
            any(
                token in field.lower()
                for field in fields
                for token in ("snapgene", "genbank", "artifact", "isoform_definition")
            )
            or ("snapgene" in text and ("identified" in text or "artifact" in text or "genbank" in text))
        )

    return False


def _normalize_genome_build_label(value: Any) -> str:
    text = str(value or "").strip().lower().replace("_", "").replace("-", "")
    if text in {"hg19", "grch37", "b37", "human37"}:
        return "GRCh37"
    if text in {"hg38", "grch38", "b38", "human38"}:
        return "GRCh38"
    return ""


def _genome_builds_from_text(value: Any) -> Set[str]:
    text = str(value or "")
    if not text.strip():
        return set()
    return {
        build
        for build in (_normalize_genome_build_label(match.group(0)) for match in re.finditer(r"\b(?:hg19|hg38|grch37|grch38)\b", text, flags=re.IGNORECASE))
        if build
    }


def _collect_genome_builds_from_object(value: Any) -> Set[str]:
    """Collect operative build declarations, excluding narrative evidence.

    An accession-identification rationale can cite a different assembly's
    archive without importing any coordinates from that assembly. Treating
    every build name in such prose as a coordinate frame creates an
    unresolvable clarification loop even when all design data use one build.
    """
    builds: Set[str] = set()
    if isinstance(value, dict):
        for key, nested in value.items():
            key_norm = str(key or "").strip().lower()
            if key_norm in {
                "rationale", "reason", "notes", "description", "evidence",
                "evidence_refs", "citations", "provenance", "source_quote",
                "source_quotes", "resolution_notes", "mapping_notes",
            }:
                continue
            if key_norm in {
                "genome_build",
                "assembly",
                "assembly_name",
                "reference_build",
                "reference_genome",
                "coordinate_build",
                "platform",
            }:
                build = _normalize_genome_build_label(nested)
                if build:
                    builds.add(build)
                builds.update(_genome_builds_from_text(nested))
            builds.update(_collect_genome_builds_from_object(nested))
    elif isinstance(value, list):
        for nested in value:
            builds.update(_collect_genome_builds_from_object(nested))
    elif isinstance(value, str):
        # Free-text coordinate specifications remain relevant; unrelated
        # build mentions in labels, summaries, and history do not.
        if re.search(
            r"\b(?:chr[0-9A-Za-z_.]+|[0-9]{1,2}|X|Y|MT|M)\s*:\s*\d[\d,]*",
            value,
            flags=re.IGNORECASE,
        ):
            builds.update(_genome_builds_from_text(value))
    return builds


def _mixed_genome_build_validation_entry(
    request_envelope: Dict[str, Any],
    task: Dict[str, Any],
    context: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    from .coordinate_conversion import conversion_plan_builds, assembly_name
    active_goal = context.get("structured_goal") or request_envelope.get("structured_goal") or {}
    conversion = conversion_plan_builds(active_goal)
    if conversion:
        source_builds, cleaned, target_build = conversion
        remaining = {assembly_name(v) for v in _collect_genome_builds_from_object(cleaned)}
        requested = {assembly_name(v) for v in _genome_builds_from_text(request_envelope.get("request_text"))}
        if remaining.issubset({target_build}) and requested.issubset(source_builds):
            # Original build labels stay in source constraints. Only the later
            # materializer may emit target-build rows, backed by actual chains.
            return None
    builds = set()
    builds.update(_genome_builds_from_text(request_envelope.get("request_text")))
    builds.update(_collect_genome_builds_from_object(request_envelope.get("structured_goal")))
    builds.update(_collect_genome_builds_from_object(task))
    builds.update(_collect_genome_builds_from_object(context))
    if len(builds) <= 1:
        return None
    display = "/".join(sorted(builds))
    return {
        "issue": "mixed_genome_build_coordinates",
        "question": (
            "This request includes coordinates from multiple genome builds "
            f"({display}; e.g. hg19/GRCh37 and hg38/GRCh38). Which single coordinate "
            "build should I use for design, or should specific intervals be converted before tiling? "
            "Are the written intervals zero-based half-open (BED) or one-based inclusive?"
        ),
        "reason": "Design execution cannot safely combine genomic coordinates from different genome builds.",
    }


def _canonical_design_goal_contract_issues(
    structured_goal: Dict[str, Any],
) -> List[str]:
    """Return schema paths that require an evidence-backed model repair."""
    from .goal_contract import CANONICAL_TARGET_TYPES
    if not isinstance(structured_goal, dict):
        return ["context.structured_goal"]
    programs = structured_goal.get("design_programs")
    if not isinstance(programs, list) or not programs:
        return ["context.structured_goal.design_programs"]

    from .species_targets import scope_contract_errors
    issues = [f"context.structured_goal.{field}" for field in scope_contract_errors(structured_goal)]
    from .transcript_roles import knockdown_preservation_conflicts
    issues.extend(f"context.structured_goal.{field}"
                  for field in knockdown_preservation_conflicts(structured_goal))
    issues.extend(f"context.structured_goal.{field}"
                  for field in _chemistry_policy_conflicts(structured_goal))
    if (structured_goal.get('aso_overlap_requirement') is not None
            and structured_goal['aso_overlap_requirement'] not in {'any_overlap', 'full_containment', 'contains_feature'}):
        issues.append('context.structured_goal.aso_overlap_requirement')
    for index, program in enumerate(programs):
        prefix = f"context.structured_goal.design_programs[{index}]"
        if not isinstance(program, dict):
            issues.append(prefix)
            continue
        for field in ("program_id", "label", "modality", "intent", "objective"):
            if program.get(field) in (None, "", [], {}):
                issues.append(f"{prefix}.{field}")
        modality = str(program.get("modality") or "").strip().lower()
        if modality and modality not in {"steric", "gapmer"}:
            issues.append(f"{prefix}.modality")
        intent = str(program.get("intent") or "").strip().lower()
        if intent == 'binding' and ('start' in program or 'end' in program):
            for field in ('start', 'end', 'coordinate_space', 'coordinate_convention'):
                if program.get(field) is None:
                    issues.append(f'{prefix}.{field}')
        if intent and intent not in {"knockdown", "splice_modulation", "binding"}:
            issues.append(f"{prefix}.intent")
        desired_delta = str(program.get("desired_delta") or "").strip().lower()
        if desired_delta and desired_delta not in {"increase", "decrease"}:
            issues.append(f"{prefix}.desired_delta")
        elif intent in {"knockdown", "splice_modulation"} and desired_delta not in {
            "increase",
            "decrease",
        }:
            issues.append(f"{prefix}.desired_delta")
        if "length" in program and _coerce_positive_int(program.get("length")) is None:
            issues.append(f"{prefix}.length")
        if program.get("target_type") and (not isinstance(program["target_type"], str) or program["target_type"] not in CANONICAL_TARGET_TYPES):
            issues.append(f"{prefix}.target_type")
        from .transcript_chooser_agent import extract_transcript_accessions
        if len(extract_transcript_accessions(program.get('transcript_id'))) > 1:
            issues.append(f'{prefix}.transcript_id')
        desired_effect = str(program.get("desired_effect") or "").strip().lower()
        if desired_effect and desired_effect not in {"inclusion", "skipping"}:
            issues.append(f"{prefix}.desired_effect")
        if desired_effect in {"inclusion", "skipping"}:
            expected_delta = (
                "increase" if desired_effect == "inclusion" else "decrease"
            )
            if (
                _design_program_direction_is_exon_level(program)
                and desired_delta != expected_delta
            ):
                issues.append(f"{prefix}.desired_delta")
            if program.get("run_splice_router") is not True:
                issues.append(f"{prefix}.run_splice_router")
            if program.get("run_splice_eval") is not True:
                issues.append(f"{prefix}.run_splice_eval")
            site_kind = str(program.get("site_kind") or "").strip().lower()
            if site_kind not in {"acceptor", "donor", "both"}:
                issues.append(f"{prefix}.site_kind")
        if intent == "splice_modulation":
            window_anchors: Set[str] = set()
            raw_constraints = program.get("region_constraints")
            for constraint in (
                raw_constraints if isinstance(raw_constraints, list) else []
            ):
                if not isinstance(constraint, dict):
                    continue
                window = constraint.get("splice_relative_window")
                if not isinstance(window, dict):
                    continue
                anchor = str(window.get("anchor_site") or "").strip().lower()
                if anchor in {"acceptor", "donor"}:
                    window_anchors.add(anchor)
            if window_anchors:
                expected_site_kind = (
                    next(iter(window_anchors))
                    if len(window_anchors) == 1
                    else "both"
                )
                if str(program.get("site_kind") or "").strip().lower() != expected_site_kind:
                    issues.append(f"{prefix}.site_kind")

    evaluation_targets = structured_goal.get("evaluation_targets")
    target_types = {
        str(target.get("target_type") or "").strip().lower()
        for target in evaluation_targets
        if isinstance(target, dict)
    } if isinstance(evaluation_targets, list) else set()
    constraints = (
        structured_goal.get("constraints")
        if isinstance(structured_goal.get("constraints"), dict)
        else {}
    )
    allele_specific = (
        constraints.get("allele_specific")
        if isinstance(constraints.get("allele_specific"), dict)
        else {}
    )
    patient_variant = (
        structured_goal.get("patient_variant")
        if isinstance(structured_goal.get("patient_variant"), dict)
        else {}
    )
    has_allele_specific_signal = bool(
        allele_specific
        or target_types.intersection({"mutant_variant", "wildtype_variant"})
    )
    if has_allele_specific_signal:
        for field in ("notation", "kind"):
            if patient_variant.get(field) in (None, "", [], {}):
                issues.append(f"context.structured_goal.patient_variant.{field}")
        for field in (
            "target_allele",
            "non_target_allele",
            "require_variant_overlap",
        ):
            value = allele_specific.get(field)
            if value in (None, "", [], {}) and value is not False:
                issues.append(
                    f"context.structured_goal.constraints.allele_specific.{field}"
                )
        overlap_path = (
            "context.structured_goal.constraints.allele_specific."
            "require_variant_overlap"
        )
        if (
            allele_specific.get("require_variant_overlap") is not True
            and overlap_path not in issues
        ):
            issues.append(overlap_path)

    valid_programs = [
        program
        for program in programs
        if isinstance(program, dict)
    ]
    program_intents = {
        str(program.get("intent") or "").strip().lower()
        for program in valid_programs
        if str(program.get("intent") or "").strip().lower()
        in {"knockdown", "splice_modulation", "binding"}
    }
    top_level_intent = str(structured_goal.get("intent") or "").strip().lower()

    evaluation_targets = structured_goal.get("evaluation_targets")
    if isinstance(evaluation_targets, list):
        for index, target in enumerate(evaluation_targets):
            if not isinstance(target, dict):
                issues.append(
                    f"context.structured_goal.evaluation_targets[{index}]"
                )
                continue
            if target.get("target_type") and (not isinstance(target["target_type"], str) or target["target_type"] not in CANONICAL_TARGET_TYPES):
                issues.append(f"context.structured_goal.evaluation_targets[{index}].target_type")
                # The existing evidence-backed repair loop resolves this field.
                # Do not infer a different biological entity from an unknown
                # category and then report an unrelated isoform-objective error.
                continue
            for field in evaluation_target_direction_issues(target):
                issues.append(
                    f"context.structured_goal.evaluation_targets[{index}].{field}"
                )
            desired_delta = str(target.get("desired_delta") or "").strip().lower()
            desired_effect = str(target.get("desired_effect") or "").strip().lower()
            if desired_effect and desired_effect not in {"inclusion", "skipping"}:
                issues.append(
                    f"context.structured_goal.evaluation_targets[{index}].desired_effect"
                )
            if (
                desired_effect in {"inclusion", "skipping"}
                and _evaluation_target_direction_is_exon_level(target)
            ):
                expected_delta = (
                    "increase" if desired_effect == "inclusion" else "decrease"
                )
                if desired_delta != expected_delta:
                    issues.append(
                        "context.structured_goal.evaluation_targets"
                        f"[{index}].desired_delta"
                    )
    splice_objectives = structured_goal.get("splice_isoform_objectives")
    if isinstance(splice_objectives, list):
        for index, objective in enumerate(splice_objectives):
            if not isinstance(objective, dict):
                issues.append(
                    f"context.structured_goal.splice_isoform_objectives[{index}]"
                )
                continue
            desired_abundance = str(
                objective.get("desired_abundance") or ""
            ).strip().lower()
            if desired_abundance not in {"increase", "decrease"}:
                issues.append(
                    "context.structured_goal.splice_isoform_objectives"
                    f"[{index}].desired_abundance"
                )
            desired_effect = str(
                objective.get("desired_effect") or ""
            ).strip().lower()
            if desired_effect and desired_effect not in {"inclusion", "skipping"}:
                issues.append(
                    "context.structured_goal.splice_isoform_objectives"
                    f"[{index}].desired_effect"
                )
            objective_scope = str(
                objective.get("objective_scope") or ""
            ).strip().lower()
            if (
                objective_scope == "default_exon_context"
                and desired_effect in {"inclusion", "skipping"}
            ):
                expected_abundance = (
                    "increase" if desired_effect == "inclusion" else "decrease"
                )
                if desired_abundance != expected_abundance:
                    issues.append(
                        "context.structured_goal.splice_isoform_objectives"
                        f"[{index}].desired_abundance"
                    )
            role = str(objective.get("role") or "").strip().lower()
            if role and role not in {"beneficial", "pathogenic", "context"}:
                issues.append(
                    "context.structured_goal.splice_isoform_objectives"
                    f"[{index}].role"
                )

    route_targets = [
        target
        for target in (
            evaluation_targets if isinstance(evaluation_targets, list) else []
        )
        if isinstance(target, dict)
        and str(target.get("objective_type") or "").strip().lower() == "route_target"
        and (not target.get("target_type") or (isinstance(target.get("target_type"), str) and target["target_type"] in CANONICAL_TARGET_TYPES))
    ]
    objective_rows = (
        [
            (index, item)
            for index, item in enumerate(splice_objectives)
            if isinstance(item, dict)
        ]
        if isinstance(splice_objectives, list)
        else []
    )
    for program in valid_programs:
        if str(program.get("intent") or "").strip().lower() != "splice_modulation":
            continue
        if program.get("target_type") in {
            "exon", "splice_junction", "splice_acceptor", "splice_donor",
            "splice_site", "splice_site_window",
        }:
            # A neighboring knockdown branch may name the same transcript as
            # an abundance target. It does not turn this structural program's
            # exon reference into a specific-transcript abundance objective.
            continue
        # A transcript accession is the narrower executable identity when a
        # program also carries a human-readable isoform label. Requiring one
        # objective to be both ``specific_transcript`` and ``specific_isoform``
        # makes the canonical contract impossible to satisfy. Validate the
        # strongest available identity; the descriptive label remains useful
        # for route matching and reporting without changing objective scope.
        identity_requirements = (
            [("transcript_id", "specific_transcript")]
            if str(program.get("transcript_id") or "").strip()
            else [("isoform_label", "specific_isoform")]
        )
        for identity_field, expected_scope in identity_requirements:
            identity = str(program.get(identity_field) or "").strip()
            if not identity:
                continue
            normalized_identity = identity.casefold()
            has_matching_route_target = any(
                str(target.get(identity_field) or "").strip().casefold()
                == normalized_identity
                and not _evaluation_target_uses_reference_transcript(
                    target, structured_goal
                )
                for target in route_targets
            )
            if not has_matching_route_target:
                continue
            matching_objectives = [
                (index, objective)
                for index, objective in objective_rows
                if str(objective.get(identity_field) or "").strip().casefold()
                == normalized_identity
            ]
            if not matching_objectives:
                issues.append("context.structured_goal.splice_isoform_objectives")
                continue
            desired_delta = str(program.get("desired_delta") or "").strip().lower()
            for objective_index, objective in matching_objectives:
                if (
                    str(objective.get("objective_scope") or "").strip().lower()
                    != expected_scope
                ):
                    issues.append(
                        "context.structured_goal.splice_isoform_objectives"
                        f"[{objective_index}].objective_scope"
                    )
                if desired_delta in {"increase", "decrease"} and (
                    str(objective.get("desired_abundance") or "").strip().lower()
                    != desired_delta
                ):
                    issues.append(
                        "context.structured_goal.splice_isoform_objectives"
                        f"[{objective_index}].desired_abundance"
                    )

    if (
        len(program_intents) == 1
        and top_level_intent
        and top_level_intent != next(iter(program_intents))
    ):
        issues.append("context.structured_goal.intent")

    return list(dict.fromkeys(issues))


def _evaluation_target_uses_reference_transcript(
    target: Dict[str, Any], structured_goal: Dict[str, Any]
) -> bool:
    """Distinguish a feature's transcript reference from an abundance target.

    Typed exon/junction targets use their transcript accession to locate the
    feature. Legacy targets without a type need both an exact reference lock
    and a matching, explicitly structural objective before that interpretation
    is safe. A named transcript/isoform outcome keeps its abundance contract.
    """
    target_type = str(target.get("target_type") or "").strip().lower()
    if target_type in {
        "exon", "splice_junction", "splice_acceptor", "splice_donor",
        "splice_site", "splice_site_window",
    }:
        return True
    if target_type or target.get("isoform_label"):
        return False
    transcript = str(target.get("transcript_id") or "").strip()
    lock = structured_goal.get("transcript_lock")
    if not (
        transcript
        and isinstance(lock, dict)
        and lock.get("kind") == "explicit_id"
        and str(lock.get("value") or "").strip().casefold()
        == transcript.casefold()
    ):
        return False
    exon = target.get("exon_label")
    if exon in (None, "", [], {}):
        return False
    effect = str(target.get("desired_effect") or "").strip().lower()
    if effect not in {"inclusion", "skipping"}:
        return False
    for objective in structured_goal.get("splice_isoform_objectives") or []:
        if not isinstance(objective, dict):
            continue
        if objective.get("objective_scope") != "default_exon_context":
            continue
        if any(objective.get(key) for key in (
            "transcript_id", "isoform_label", "reference_accession"
        )):
            continue
        if (
            str(objective.get("exon_label") or "").strip() == str(exon).strip()
            and objective.get("desired_effect") == effect
            and objective.get("desired_abundance") == target.get("desired_delta")
        ):
            return True
    return False


def _evaluation_target_direction_is_exon_level(
    target: Dict[str, Any],
) -> bool:
    """Return whether ``desired_delta`` describes usage of the exon itself.

    A splice effect and an abundance outcome can legitimately point in opposite
    directions: skipping a poison exon can increase a productive transcript or
    isoform cohort.  The deterministic pairing between ``desired_effect`` and
    ``desired_delta`` is therefore sound only when the target identity is the
    exon, not when the target is a transcript or isoform abundance outcome.

    Prefer the explicit target type over context fields. An exon target may
    carry a transcript accession to locate that exon. Without a target type,
    transcript/isoform identity retains the conservative abundance interpretation.
    """

    target_type = str(target.get("target_type") or "").strip().lower()
    if target_type == "exon":
        return True
    if any(
        target.get(field) not in (None, "", [], {})
        for field in ("transcript_id", "isoform_label")
    ):
        return False
    if target_type in {
        "transcript",
        "transcript_cohort",
        "isoform",
        "isoform_cohort",
    }:
        return False
    return any(
        target.get(field) not in (None, "", [], {})
        for field in (
            "exon_label",
            "requested_exon_label",
            "resolved_transcript_exon_index",
        )
    )


def _design_program_direction_is_exon_level(
    program: Dict[str, Any],
) -> bool:
    """Return whether a program's delta denotes usage of the exon itself.

    ``desired_effect`` is the requested exon-level outcome. ``desired_delta``
    is the direction of the feature targeted by one design branch.  A branch
    that decreases an alternative splice site can increase inclusion of the
    requested exon, so the two directions are coupled only when the program
    explicitly targets exon usage rather than a transcript, isoform, or splice
    site.  This mirrors the identity-scoped validation used for evaluation
    targets and prevents a valid route from being rewritten to match an
    unrelated top-level outcome.
    """

    if any(
        program.get(field) not in (None, "", [], {})
        for field in ("transcript_id", "isoform_label")
    ):
        return False
    target_type = str(program.get("target_type") or "").strip().lower()
    if target_type in {
        "transcript",
        "transcript_cohort",
        "isoform",
        "isoform_cohort",
        "splice_acceptor",
        "splice_donor",
        "splice_site",
        "splice_site_window",
    }:
        return False
    site_kind = str(program.get("site_kind") or "").strip().lower()
    if site_kind in {"acceptor", "donor"}:
        return False
    if target_type == "exon":
        return True
    if any(
        program.get(field) not in (None, "", [], {})
        for field in (
            "exon_label",
            "exon_labels",
            "requested_exon_label",
            "resolved_transcript_exon_index",
        )
    ):
        return True
    # With no narrower structured identity, a splice program's inclusion or
    # skipping effect is necessarily the exon-level outcome represented by the
    # program itself.
    return True


def _design_goal_execution_contract_issues(
    structured_goal: Dict[str, Any],
) -> List[str]:
    """Return canonical paths still required by the child design runtime.

    The sparse canonical schema intentionally permits goals while they are being
    synthesized.  Before a design task is declared runnable, however, the parent
    contract must guarantee that child-runtime required fields can be
    materialized.  A structured multi-species scope is sufficient because the
    contract finalizer deterministically selects one member as the scalar anchor.
    """

    if not isinstance(structured_goal, dict):
        return []
    # Species becomes a concrete child-runtime obligation once the goal has a
    # resolvable biological target.  Goals still awaiting target materialization
    # are handled by their own target-resolution boundary.
    if not (
        str(structured_goal.get("gene_symbol") or "").strip()
        or str(structured_goal.get("gene_id") or "").strip()
    ):
        return []
    if _request_contract_anchor_species({}, structured_goal):
        return []
    return ["context.structured_goal.species"]


def _request_validation_summary(request_envelope: Dict[str, Any]) -> Dict[str, Any]:
    tasks = [task for task in (request_envelope.get("tasks") or []) if isinstance(task, dict)]
    design_task_count = sum(1 for task in tasks if _normalize_task_type_value(task.get("task_type")) == "design_new_asos")
    task_ids = {str(task.get("task_id") or "").strip() for task in tasks if str(task.get("task_id") or "").strip()}
    task_type_by_id = {
        str(task.get("task_id") or "").strip(): _normalize_task_type_value(task.get("task_type"))
        for task in tasks
        if str(task.get("task_id") or "").strip()
    }
    dependency_map: Dict[str, Set[str]] = {}
    for dep in _normalize_request_dependencies(request_envelope.get("task_dependencies"), task_ids, tasks):
        dependency_map.setdefault(str(dep.get("downstream_task_id") or "").strip(), set()).add(str(dep.get("upstream_task_id") or "").strip())

    task_validation: Dict[str, Dict[str, Any]] = {}
    blocked_task_ids: List[str] = []
    invalid_task_ids: List[str] = []
    clarification_queue: List[Dict[str, Any]] = []
    runnable_task_ids: List[str] = []
    explicit_blocked_by_id = _explicit_blocked_tasks_by_id(request_envelope, task_ids)
    orphan_blocked_tasks = _orphan_blocked_tasks(request_envelope, task_ids)

    for task in tasks:
        task_id = str(task.get("task_id") or "").strip()
        task_type = _normalize_task_type_value(task.get("task_type"))
        context = _task_context_from_request_envelope(request_envelope, task)
        artifact_refs = _task_context_artifact_refs(context)
        artifact_availability = _artifact_ref_availability(artifact_refs)
        usable_artifact_refs = artifact_availability.get("usable") or []
        missing_artifact_refs = artifact_availability.get("missing_local") or []
        has_usable_artifact_refs = bool(usable_artifact_refs)
        provided_asos = _task_context_provided_asos(context)
        has_target_context = _task_has_target_context(context)
        deps = sorted(dependency_map.get(task_id, set()))
        design_dependency_ids = [dep for dep in deps if task_type_by_id.get(dep) == "design_new_asos"]
        has_design_dependency = bool(design_dependency_ids)
        has_generated_design_output = has_design_dependency and any(
            isinstance(output, dict)
            and str(output.get("task_id") or "").strip() in design_dependency_ids
            and str(output.get("path") or "").strip()
            for output in request_envelope.get("final_outputs") or []
        )
        has_multiset_design_dependency = any(
            _design_task_declares_multiple_generated_sets(upstream_task)
            for upstream_task in tasks
            if isinstance(upstream_task, dict)
            and str(upstream_task.get("task_id") or "").strip() in design_dependency_ids
        )
        has_artifact_dependency = any(task_type_by_id.get(dep) == "analyze_artifact" for dep in deps)
        evaluation_dependency_ids = [dep for dep in deps if task_type_by_id.get(dep) == 'evaluate_existing_aso_set']
        issues: List[str] = []
        repairable_issues: List[str] = []
        questions: List[str] = []
        reason = ""
        status = "runnable"

        if task_type not in _SUPPORTED_V3_TASK_TYPES:
            issues.append("unsupported_task_type")
            questions.append(
                "This request includes an unsupported task type. Please restate that step as one of: "
                + ", ".join(sorted(_SUPPORTED_V3_TASK_TYPES))
                + "."
            )
            reason = f"Unsupported task type `{task_type}` in request graph."
            status = "blocked"
        elif task_type == "design_new_asos":
            structured_goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
            if _is_placeholder_default_design_task(request_envelope, task, context):
                status = "runnable"
            else:
                build_issue = _mixed_genome_build_validation_entry(request_envelope, task, context)
                if build_issue:
                    issues.append(str(build_issue["issue"]))
                    questions.append(str(build_issue["question"]))
                    reason = str(build_issue["reason"])
                    status = "blocked"
                context_goal = deepcopy(structured_goal) if isinstance(structured_goal, dict) else {}
                for field in ("gene_symbol", "gene_id", "species", "target_context"):
                    value = context.get(field)
                    if value not in (None, "", [], {}) and context_goal.get(field) in (None, "", [], {}):
                        context_goal[field] = deepcopy(value)
                context_issue = _target_context_validation_issue(context_goal)
                if context_issue:
                    issues.append(context_issue)
                    questions.append(_target_context_clarification_question(context_goal))
                    if not reason:
                        reason = "Design execution requires a concrete biological target context."
                    status = "blocked"
                elif not (structured_goal or has_target_context):
                    issues.append("design_context_missing")
                    questions.append("What gene, species, or target objective should I use for this design task?")
                    if not reason:
                        reason = "Scoped design execution needs task-local target context or a structured goal."
                    status = "blocked"
                if structured_goal:
                    from .species_targets import anchor_conflict
                    if anchor_conflict(context, structured_goal):
                        repairable_issues.append("context.species")
                    repairable_issues.extend(
                        _canonical_design_goal_contract_issues(structured_goal)
                    )
                    repairable_issues.extend(
                        _design_goal_execution_contract_issues(context_goal)
                    )
        elif task_type == "analyze_artifact":
            if not artifact_refs and not has_generated_design_output:
                issues.append("artifact_refs_missing")
                questions.append("Which run directory or artifact path should I inspect?")
                reason = "Artifact analysis requires a concrete artifact or run reference."
                status = "blocked"
            elif missing_artifact_refs and not has_usable_artifact_refs:
                issues.append("artifact_refs_unavailable")
                questions.append(_missing_artifact_refs_question(missing_artifact_refs))
                reason = "Artifact analysis cannot run until the referenced local path exists or is replaced."
                status = "blocked"
        elif task_type == "evaluate_existing_aso_set":
            if not provided_asos and not has_design_dependency:
                issues.append("provided_asos_missing")
                questions.append("Please provide the ASO sequence or sequences you want me to evaluate.")
            if artifact_refs and missing_artifact_refs and not has_usable_artifact_refs:
                issues.append("artifact_refs_unavailable")
                questions.append(_missing_artifact_refs_question(missing_artifact_refs))
            if not (has_target_context or has_usable_artifact_refs or design_task_count > 0 or has_design_dependency or has_artifact_dependency):
                issues.append("evaluation_context_missing")
                questions.append("What target gene, transcript, or species should I use to evaluate these ASOs?")
            if issues:
                reason = "Existing-ASO evaluation is missing required context."
                status = "blocked"
        elif task_type in {"compare_aso_sets", "trace_filter_decisions"}:
            has_upstream_aso_sets = (
                task_type == "compare_aso_sets"
                and _task_declares_upstream_aso_set_inputs(task, context)
            )
            has_generated_set_pair = task_type == "compare_aso_sets" and (
                has_upstream_aso_sets
                or len(design_dependency_ids) >= 2
                or has_multiset_design_dependency
                or _task_generated_branch_input_count(task) >= 2
                # A native evaluation produces the submitted observations for
                # comparison. They need not be duplicated in this task's input.
                or (has_design_dependency and len(evaluation_dependency_ids) == 1)
            )
            if not provided_asos and not has_generated_set_pair:
                issues.append("provided_asos_missing")
                questions.append("Please provide the ASO sequence or sequences you want me to compare and trace.")
            if (
                artifact_refs
                and missing_artifact_refs
                and not has_usable_artifact_refs
                and not (has_generated_set_pair or has_design_dependency)
            ):
                issues.append("artifact_refs_unavailable")
                questions.append(_missing_artifact_refs_question(missing_artifact_refs))
            if not (has_usable_artifact_refs or design_task_count > 0 or has_design_dependency or has_artifact_dependency or has_upstream_aso_sets):
                issues.append("comparison_reference_missing")
                questions.append("What generated candidate source should I compare against: a new design request or an existing run/artifact path?")
            if issues:
                reason = "Comparison or filter tracing is missing a provided ASO set or candidate reference source."
                status = "blocked"

        explicit_block = explicit_blocked_by_id.get(task_id)
        deferred_explicit_block: Dict[str, Any] = {}
        explicit_block_resolved = _explicit_block_resolved_by_available_inputs(
            explicit_block,
            task_type=task_type,
            has_usable_artifact_refs=has_usable_artifact_refs,
            has_artifact_dependency=has_artifact_dependency,
        )
        defer_until_retrieval = (
            bool(explicit_block)
            and not explicit_block_resolved
            and task_type == "answer_question"
            and _answer_web_retrieval_requested(context)
        )
        if explicit_block and not explicit_block_resolved and status != "invalid":
            if defer_until_retrieval:
                deferred_explicit_block = deepcopy(explicit_block)
            else:
                for issue in explicit_block.get("missing_fields") or []:
                    text = str(issue or "").strip()
                    if text and text not in issues:
                        issues.append(text)
                for question in explicit_block.get("questions") or []:
                    text = str(question or "").strip()
                    if text and text not in questions:
                        questions.append(text)
                explicit_reason = str(explicit_block.get("reason") or "").strip()
                if explicit_reason:
                    reason = explicit_reason
                elif not reason:
                    reason = "Task has explicit blocking clarification requirements."
                status = "blocked"

        task_validation[task_id] = {
            "task_id": task_id,
            "task_type": task_type,
            "label": str(task.get("label") or "").strip() or task_type,
            "context": context,
            "status": status,
            "issues": issues,
            "repairable_issues": list(dict.fromkeys(repairable_issues)),
            "questions": questions,
            "reason": reason,
            "depends_on": deps,
        }
        if deferred_explicit_block:
            task_validation[task_id]["post_retrieval_clarification"] = deferred_explicit_block
        if status == "blocked":
            blocked_task_ids.append(task_id)
            clarification_queue.append(
                {
                    "task_id": task_id,
                    "label": str(task.get("label") or "").strip() or task_type,
                    "missing_fields": issues,
                    "questions": questions,
                    "reason": reason or "task_context_missing",
                }
            )
        elif status == "invalid":
            invalid_task_ids.append(task_id)
        else:
            runnable_task_ids.append(task_id)

    return {
        "tasks": task_validation,
        "blocked_task_ids": blocked_task_ids,
        "invalid_task_ids": invalid_task_ids,
        "clarification_queue": clarification_queue,
        "runnable_task_ids": runnable_task_ids,
        "orphan_blocked_tasks": orphan_blocked_tasks,
        "orphan_blocked_task_ids": [
            str(item.get("task_id") or "").strip()
            for item in orphan_blocked_tasks
            if str(item.get("task_id") or "").strip()
        ],
    }


def _request_envelope_validation_issues(request_envelope: Dict[str, Any]) -> List[str]:
    issues: List[str] = []
    summary = _request_validation_summary(request_envelope)
    if summary.get("orphan_blocked_tasks"):
        issues.append("blocked_task_missing_from_task_graph")
    task_entries = summary.get("tasks") if isinstance(summary.get("tasks"), dict) else {}
    for entry in task_entries.values():
        if not isinstance(entry, dict):
            continue
        for issue in entry.get("issues") or []:
            text = str(issue or "").strip()
            if text and text not in issues:
                issues.append(text)
        for issue in entry.get("repairable_issues") or []:
            text = str(issue or "").strip()
            if text and text not in issues:
                issues.append(text)
    return issues


def _clarification_questions_for_request_issues(
    issues: List[str],
    request_envelope: Dict[str, Any],
) -> List[str]:
    summary = _request_validation_summary(request_envelope)
    queue = summary.get("clarification_queue") if isinstance(summary.get("clarification_queue"), list) else []
    orphan_queue = summary.get("orphan_blocked_tasks") if isinstance(summary.get("orphan_blocked_tasks"), list) else []
    questions: List[str] = []
    for item in queue:
        if not isinstance(item, dict):
            continue
        for question in item.get("questions") or []:
            text = str(question or "").strip()
            if text:
                questions.append(text)
    for item in orphan_queue:
        if not isinstance(item, dict):
            continue
        for question in _normalize_questions_input(item.get("questions")):
            if question:
                questions.append(question)
    if not questions:
        for issue in issues:
            if issue == "artifact_refs_missing":
                questions.append("Which run directory or artifact path should I inspect?")
            elif issue == "artifact_refs_unavailable":
                questions.append(_missing_artifact_refs_question())
            elif issue == "provided_asos_missing":
                questions.append("Please provide the ASO sequence or sequences you want me to evaluate.")
            elif issue == "evaluation_context_missing":
                questions.append("What target gene, transcript, or species should I use to evaluate these ASOs?")
            elif issue.startswith("context.structured_goal"):
                questions.append(
                    "Please provide the missing design detail required at the canonical JSON path "
                    f"{issue}."
                )
            elif issue == "comparison_reference_missing":
                questions.append("What generated candidate source should I compare against: a new design request or an existing run/artifact path?")
    return _dedupe_clarification_questions(questions)


def _validation_issue_topic_keywords(issue: str) -> Tuple[str, ...]:
    text = str(issue or "").strip().lower()
    if "target_context" in text or "target context" in text:
        return ("target context", "target_context", "biological target context", "cell type", "tissue")
    if text.startswith("artifact_refs"):
        return ("artifact", "path", "run directory", "prior run", "aso set source")
    if "gene_symbol" in text or "gene_id" in text:
        return ("gene", "symbol")
    if "isoform" in text or "splice" in text:
        return ("isoform", "splice", "exon")
    if "transcript" in text:
        return ("transcript",)
    if text == "provided_asos_missing":
        return ("aso sequence", "aso set", "provided aso")
    if text == "comparison_reference_missing":
        return ("compare", "candidate source", "generated", "artifact", "run")
    if text == "evaluation_context_missing":
        return ("target gene", "transcript", "species")
    return ()


def _merge_validation_questions_into_intake(
    intake_questions: List[str],
    validation: Dict[str, Any],
) -> List[str]:
    merged = [str(item).strip() for item in intake_questions if str(item).strip()]
    existing_text = "\n".join(merged).lower()
    queue = validation.get("clarification_queue") if isinstance(validation.get("clarification_queue"), list) else []
    for item in queue:
        if not isinstance(item, dict):
            continue
        issues = [str(issue or "").strip() for issue in item.get("missing_fields") or [] if str(issue or "").strip()]
        if issues:
            covered = True
            for issue in issues:
                keywords = _validation_issue_topic_keywords(issue)
                if keywords and not any(keyword in existing_text for keyword in keywords):
                    covered = False
                    break
            if covered:
                continue
        for question in _normalize_questions_input(item.get("questions")):
            text = str(question or "").strip()
            if not text or text in merged:
                continue
            merged.append(text)
            existing_text = "\n".join(merged).lower()
    return _dedupe_clarification_questions(merged)


def _canonical_goal_path_tokens(path: Any) -> List[Any]:
    prefix = "context.structured_goal."
    text = str(path or "").strip()
    if not text.startswith(prefix):
        return []
    remainder = text[len(prefix):]
    tokens: List[Any] = []
    buffer = ""
    index = 0
    while index < len(remainder):
        character = remainder[index]
        if character == ".":
            if not buffer:
                return []
            tokens.append(buffer)
            buffer = ""
            index += 1
            continue
        if character == "[":
            if buffer:
                tokens.append(buffer)
                buffer = ""
            close_index = remainder.find("]", index + 1)
            if close_index < 0:
                return []
            raw_index = remainder[index + 1:close_index]
            if not raw_index.isdigit():
                return []
            tokens.append(int(raw_index))
            index = close_index + 1
            if index < len(remainder) and remainder[index] == ".":
                index += 1
            continue
        buffer += character
        index += 1
    if buffer:
        tokens.append(buffer)
    return tokens


def _task_canonical_goal_path_is_resolved(
    task: Dict[str, Any],
    path: Any,
) -> bool:
    tokens = _canonical_goal_path_tokens(path)
    if not tokens or not isinstance(task, dict):
        return False
    context = task.get("context") if isinstance(task.get("context"), dict) else {}
    goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
    if str(path or "").strip() in _canonical_design_goal_contract_issues(goal):
        return False
    value: Any = goal
    for token in tokens:
        if isinstance(token, int):
            if not isinstance(value, list) or token >= len(value):
                return False
            value = value[token]
        else:
            if not isinstance(value, dict) or token not in value:
                return False
            value = value[token]
    return value not in (None, "", [], {})


def _resolved_declared_contract_blocks(
    request_envelope: Dict[str, Any],
) -> Tuple[Dict[str, Any], bool]:
    envelope = deepcopy(request_envelope)
    tasks = {
        str(task.get("task_id") or "").strip(): task
        for task in envelope.get("tasks") or []
        if isinstance(task, dict) and str(task.get("task_id") or "").strip()
    }
    declared_contract_paths = 0
    resolved_contract_paths = 0
    retained: List[Dict[str, Any]] = []
    for raw_block in envelope.get("blocked_tasks") or []:
        if not isinstance(raw_block, dict):
            continue
        block = deepcopy(raw_block)
        task = tasks.get(str(block.get("task_id") or "").strip())
        unresolved_fields: List[str] = []
        for raw_path in block.get("missing_fields") or []:
            path = str(raw_path or "").strip()
            if not path:
                continue
            if path.startswith("context.structured_goal."):
                declared_contract_paths += 1
                if isinstance(task, dict) and _task_canonical_goal_path_is_resolved(
                    task,
                    path,
                ):
                    resolved_contract_paths += 1
                    continue
            unresolved_fields.append(path)
        if unresolved_fields:
            block["missing_fields"] = unresolved_fields
            retained.append(block)
    if retained:
        envelope["blocked_tasks"] = retained
    else:
        envelope.pop("blocked_tasks", None)
    all_declared_resolved = bool(
        declared_contract_paths
        and declared_contract_paths == resolved_contract_paths
    )
    return envelope, all_declared_resolved


def _json_pointer_escape(value: Any) -> str:
    return str(value).replace("~", "~0").replace("/", "~1")


def _json_pointer_tokens(path: Any) -> List[str]:
    text = str(path or "")
    if not text.startswith("/"):
        return []
    tokens: List[str] = []
    for raw_token in text[1:].split("/"):
        token = ""
        index = 0
        while index < len(raw_token):
            character = raw_token[index]
            if character != "~":
                token += character
                index += 1
                continue
            if index + 1 >= len(raw_token):
                return []
            escaped = raw_token[index + 1]
            if escaped == "0":
                token += "~"
            elif escaped == "1":
                token += "/"
            else:
                return []
            index += 2
        tokens.append(token)
    return tokens


def _canonical_issue_expected_schema(path: str) -> Dict[str, Any]:
    field = str(path or "").rsplit(".", 1)[-1]
    return deepcopy(
        CANONICAL_GOAL_FIELD_SCHEMAS.get(field)
        or {"required": True}
    )


def _goal_contract_issue_records(
    request_envelope: Dict[str, Any],
    validation: Dict[str, Any],
) -> List[Dict[str, Any]]:
    task_validation = (
        validation.get("tasks")
        if isinstance(validation.get("tasks"), dict)
        else {}
    )
    from .transcript_roles import knockdown_preservation_conflicts
    records: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for task_index, task in enumerate(request_envelope.get("tasks") or []):
        if not isinstance(task, dict):
            continue
        task_id = str(task.get("task_id") or "").strip()
        entry = task_validation.get(task_id)
        if not isinstance(entry, dict):
            continue
        context = task.get("context") or {}
        role_conflicts = knockdown_preservation_conflicts(context.get("structured_goal"))
        chemistry_conflicts = _chemistry_policy_conflicts(context.get("structured_goal"))
        if "unsupported_task_type" in {
            str(issue or "").strip() for issue in entry.get("issues") or []
        }:
            pointer = f"/tasks/{task_index}/task_type"
            if pointer not in seen:
                seen.add(pointer)
                records.append(
                    {
                        "task_id": task_id,
                        "validation_issue": "unsupported_task_type",
                        "canonical_path": "task_type",
                        "json_pointer": pointer,
                        "required_operation": "replace",
                        "expected_schema": {
                            "type": "string",
                            "enum": sorted(CANONICAL_TASK_TYPES),
                        },
                    }
                )
        for issue in entry.get("repairable_issues") or []:
            issue_text = str(issue or "").strip()
            relative_tokens = _canonical_goal_path_tokens(issue_text)
            context_field = issue_text.removeprefix("context.")
            context_schema = canonical_task_context_schema().get("properties", {}).get(context_field)
            if relative_tokens:
                pointer_tokens: List[Any] = ["tasks", task_index, "context", "structured_goal", *relative_tokens]
                expected_schema = _canonical_issue_expected_schema(issue_text)
            elif issue_text.startswith("context.") and isinstance(context_schema, dict):
                pointer_tokens = ["tasks", task_index, "context", context_field]
                expected_schema = deepcopy(context_schema)
            else:
                continue
            pointer = "/" + "/".join(
                _json_pointer_escape(token) for token in pointer_tokens
            )
            if pointer in seen:
                continue
            seen.add(pointer)
            exists, _current_value = _json_pointer_value(
                request_envelope,
                [str(token) for token in pointer_tokens],
            )
            role_conflict = role_conflicts.get(issue_text.removeprefix("context.structured_goal."))
            semantic_conflict = role_conflict or chemistry_conflicts.get(
                issue_text.removeprefix("context.structured_goal.")
            )
            if role_conflict and isinstance(expected_schema, dict):
                expected_schema = deepcopy(expected_schema)
                value_schema = expected_schema.get("items") if expected_schema.get("type") == "array" else expected_schema
                if isinstance(value_schema, dict):
                    value_schema["not"] = {"enum": role_conflict["conflicting_target_values"]}
            records.append(
                {
                    "task_id": task_id,
                    "validation_issue": issue_text,
                    "canonical_path": issue_text,
                    "json_pointer": pointer,
                    "required_operation": "replace" if exists else "add",
                    "expected_schema": expected_schema,
                    **({"semantic_conflict": deepcopy(semantic_conflict)} if semantic_conflict else {}),
                }
            )
    return records


def _goal_validation_issue_instances(
    validation: Dict[str, Any],
    represented_issue_records: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    represented = {
        (
            str(record.get("task_id") or "").strip(),
            str(record.get("validation_issue") or "").strip(),
        )
        for record in represented_issue_records
        if isinstance(record, dict)
        and str(record.get("task_id") or "").strip()
        and str(record.get("validation_issue") or "").strip()
    }
    task_validation = (
        validation.get("tasks")
        if isinstance(validation.get("tasks"), dict)
        else {}
    )
    instances: List[Dict[str, Any]] = []
    for task_id, entry in task_validation.items():
        if not isinstance(entry, dict):
            continue
        normalized_task_id = str(task_id or "").strip()
        questions = [
            str(question or "").strip()
            for question in entry.get("questions") or []
            if str(question or "").strip()
        ]
        for issue in entry.get("issues") or []:
            issue_text = str(issue or "").strip()
            if (
                not issue_text
                or (normalized_task_id, issue_text) in represented
            ):
                continue
            instances.append(
                {
                    "issue_index": len(instances),
                    "task_id": normalized_task_id,
                    "task_type": str(entry.get("task_type") or "").strip(),
                    "validation_issue": issue_text,
                    "questions": questions,
                    "reason": str(entry.get("reason") or "").strip(),
                }
            )
    return instances


def _compact_localization_schema(schema: Dict[str, Any]) -> Dict[str, Any]:
    summary = {
        key: deepcopy(schema[key])
        for key in ("type", "enum", "const", "minimum", "maximum")
        if key in schema
    }
    required = schema.get("required")
    if isinstance(required, list) and required:
        summary["required"] = [str(item) for item in required]
    items = schema.get("items")
    if isinstance(items, dict):
        item_properties = items.get("properties")
        if isinstance(item_properties, dict):
            summary["item_fields"] = sorted(str(key) for key in item_properties)
        item_required = items.get("required")
        if isinstance(item_required, list) and item_required:
            summary["item_required"] = [str(item) for item in item_required]
    return summary


def _goal_validation_candidate_destinations(
    request_envelope: Dict[str, Any],
    issue_instances: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    issue_task_ids = {
        str(instance.get("task_id") or "").strip()
        for instance in issue_instances
        if isinstance(instance, dict)
        and str(instance.get("task_id") or "").strip()
    }
    goal_semantics = {
        str(entry.get("path_pattern") or "").strip(): str(
            entry.get("semantic_role") or ""
        ).strip()
        for entry in canonical_goal_field_registry()
        if isinstance(entry, dict)
    }
    context_semantics = {
        str(entry.get("path_pattern") or "").strip(): str(
            entry.get("semantic_role") or ""
        ).strip()
        for entry in canonical_task_context_field_registry()
        if isinstance(entry, dict)
    }
    goal_properties = canonical_structured_goal_schema().get("properties")
    context_properties = canonical_task_context_schema().get("properties")
    candidates: List[Dict[str, Any]] = []
    for task_index, task in enumerate(request_envelope.get("tasks") or []):
        if not isinstance(task, dict):
            continue
        task_id = str(task.get("task_id") or "").strip()
        if task_id not in issue_task_ids:
            continue
        is_design = (
            _normalize_task_type_value(task.get("task_type"))
            == "design_new_asos"
        )
        properties = goal_properties if is_design else context_properties
        if not isinstance(properties, dict):
            continue
        for field in sorted(properties):
            field_schema = properties.get(field)
            if not isinstance(field_schema, dict):
                continue
            if is_design:
                canonical_path = f"context.structured_goal.{field}"
                json_pointer = (
                    f"/tasks/{task_index}/context/structured_goal/"
                    f"{_json_pointer_escape(field)}"
                )
                semantic_role = goal_semantics.get(canonical_path, "")
                destination_scope = "structured_goal"
            else:
                canonical_path = f"tasks[*].context.{field}"
                json_pointer = (
                    f"/tasks/{task_index}/context/"
                    f"{_json_pointer_escape(field)}"
                )
                semantic_role = context_semantics.get(canonical_path, "")
                destination_scope = "task_context"
            candidates.append(
                {
                    "candidate_index": len(candidates),
                    "task_id": task_id,
                    "destination_scope": destination_scope,
                    "field_name": field,
                    "canonical_path": canonical_path,
                    "json_pointer": json_pointer,
                    "semantic_role": semantic_role,
                    "schema": _compact_localization_schema(field_schema),
                }
            )
    return candidates


def _goal_validation_localization_records(
    request_envelope: Dict[str, Any],
    issue_instances: List[Dict[str, Any]],
    candidate_destinations: List[Dict[str, Any]],
    localization: Dict[str, Any],
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    candidate_by_index = {
        candidate.get("candidate_index"): candidate
        for candidate in candidate_destinations
        if isinstance(candidate, dict)
        and isinstance(candidate.get("candidate_index"), int)
        and not isinstance(candidate.get("candidate_index"), bool)
    }
    verdict_by_issue = {
        verdict.get("issue_index"): verdict
        for verdict in localization.get("verdicts") or []
        if isinstance(verdict, dict)
        and isinstance(verdict.get("issue_index"), int)
        and not isinstance(verdict.get("issue_index"), bool)
    }
    goal_properties = canonical_structured_goal_schema().get("properties")
    context_properties = canonical_task_context_schema().get("properties")
    records: List[Dict[str, Any]] = []
    ledger: List[Dict[str, Any]] = []
    seen_pointers: Set[str] = set()
    for issue_index, issue in enumerate(issue_instances):
        verdict = verdict_by_issue.get(issue_index)
        selected_indexes = (
            verdict.get("candidate_indexes")
            if isinstance(verdict, dict)
            and str(verdict.get("resolution") or "").strip() == "localized"
            and isinstance(verdict.get("candidate_indexes"), list)
            else []
        )
        localized_pointers: List[str] = []
        for candidate_index in selected_indexes:
            candidate = candidate_by_index.get(candidate_index)
            if not isinstance(candidate, dict):
                continue
            pointer = str(candidate.get("json_pointer") or "").strip()
            field_name = str(candidate.get("field_name") or "").strip()
            scope = str(candidate.get("destination_scope") or "").strip()
            properties = (
                goal_properties
                if scope == "structured_goal"
                else context_properties
            )
            expected_schema = (
                properties.get(field_name)
                if isinstance(properties, dict)
                else None
            )
            if (
                not pointer
                or not isinstance(expected_schema, dict)
            ):
                continue
            localized_pointers.append(pointer)
            if pointer in seen_pointers:
                continue
            seen_pointers.add(pointer)
            exists, _current_value = _json_pointer_value(
                request_envelope,
                _json_pointer_tokens(pointer),
            )
            records.append(
                {
                    "task_id": str(issue.get("task_id") or "").strip(),
                    "validation_issue": str(
                        issue.get("validation_issue") or ""
                    ).strip(),
                    "canonical_path": str(
                        candidate.get("canonical_path") or ""
                    ).strip(),
                    "json_pointer": pointer,
                    "required_operation": "replace" if exists else "add",
                    "expected_schema": deepcopy(expected_schema),
                }
            )
        ledger.append(
            {
                **deepcopy(issue),
                "localization": (
                    "localized" if localized_pointers else "unlocalized"
                ),
                "localized_json_pointers": localized_pointers,
                "localization_reason": str(
                    verdict.get("reason") if isinstance(verdict, dict) else ""
                ).strip(),
            }
        )
    return records, ledger


def _noncanonical_goal_field_findings(
    request_envelope: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Locate unknown goal keys without assigning alias semantics to them."""

    findings: List[Dict[str, Any]] = []
    root_schema = canonical_structured_goal_schema()

    def _walk(
        value: Any,
        schema: Dict[str, Any],
        pointer_tokens: List[Any],
        *,
        task_id: str,
    ) -> None:
        if isinstance(value, dict):
            properties = schema.get("properties")
            if not isinstance(properties, dict):
                return
            if schema.get("additionalProperties") is False:
                for key in sorted(value):
                    if key in properties:
                        continue
                    source_tokens = [*pointer_tokens, key]
                    findings.append(
                        {
                            "finding_index": len(findings),
                            "task_id": task_id,
                            "source_path": "/"
                            + "/".join(
                                _json_pointer_escape(token)
                                for token in source_tokens
                            ),
                            "parent_path": "/"
                            + "/".join(
                                _json_pointer_escape(token)
                                for token in pointer_tokens
                            ),
                            "field_name": str(key),
                            "value": deepcopy(value[key]),
                            "reason": "field_is_not_defined_in_canonical_goal_schema",
                        }
                    )
            for key, nested_value in value.items():
                nested_schema = properties.get(key)
                if isinstance(nested_schema, dict):
                    _walk(
                        nested_value,
                        nested_schema,
                        [*pointer_tokens, key],
                        task_id=task_id,
                    )
            return
        if isinstance(value, list) and isinstance(schema.get("items"), dict):
            for index, item in enumerate(value):
                _walk(
                    item,
                    schema["items"],
                    [*pointer_tokens, index],
                    task_id=task_id,
                )

    for task_index, task in enumerate(request_envelope.get("tasks") or []):
        if not isinstance(task, dict):
            continue
        if _normalize_task_type_value(task.get("task_type")) != "design_new_asos":
            continue
        context = task.get("context") if isinstance(task.get("context"), dict) else {}
        goal = context.get("structured_goal")
        if not isinstance(goal, dict):
            continue
        _walk(
            goal,
            root_schema,
            ["tasks", task_index, "context", "structured_goal"],
            task_id=str(task.get("task_id") or "").strip(),
        )
    return findings


def _goal_audit_evidence_sources(
    request_text: str,
    qa_history: List[Dict[str, Any]],
) -> List[Dict[str, str]]:
    sources: List[Dict[str, str]] = []
    request_source = str(request_text or "").strip()
    if request_source:
        sources.append(
            {
                "evidence_id": "request",
                "kind": "user_request",
                "text": request_source,
            }
        )
    for index, entry in enumerate(qa_history or []):
        if not isinstance(entry, dict):
            continue
        for field in ("question", "answer"):
            text = str(entry.get(field) or "").strip()
            if not text:
                continue
            sources.append(
                {
                    "evidence_id": f"clarification.{index}.{field}",
                    "kind": f"clarification_{field}",
                    "text": text,
                }
            )
        for ref_index, evidence in enumerate(
            _resolved_clarification_evidence([entry])
        ):
            sources.append(
                {
                    "evidence_id": (
                        f"clarification.{index}.evidence.{ref_index}"
                    ),
                    "kind": "clarification_source_evidence",
                    "text": json.dumps(
                        evidence,
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    ),
                }
            )
    return sources


def _extend_goal_audit_evidence_from_declared_artifacts(
    evidence_sources: List[Dict[str, str]],
    request_envelope: Dict[str, Any],
) -> None:
    """Expose declared local artifact contents as provenance-bound audit evidence."""

    declared_paths: List[str] = []
    for task in request_envelope.get("tasks") or []:
        if not isinstance(task, dict):
            continue
        context = task.get("context") if isinstance(task.get("context"), dict) else {}
        for ref in _task_context_artifact_refs(context):
            if ref not in declared_paths:
                declared_paths.append(ref)

    existing_texts = {
        str(item.get("text") or "")
        for item in evidence_sources
        if isinstance(item, dict)
    }
    next_index = sum(
        1
        for item in evidence_sources
        if isinstance(item, dict)
        and str(item.get("kind") or "") == "declared_task_artifact"
    )
    for ref in declared_paths:
        if not _artifact_ref_is_local_path(ref):
            continue
        path = _artifact_ref_path(ref)
        if not path.exists():
            continue
        artifact_entry = {
            "declared_ref": ref,
            "resolved_path": str(path),
            "is_dir": path.is_dir(),
            "excerpt": _artifact_excerpt(path, max_chars=20_000),
            "key_file_excerpts": (
                _directory_key_artifact_excerpts(path)
                if path.is_dir()
                else {}
            ),
        }
        text = json.dumps(
            artifact_entry,
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
        if text in existing_texts:
            continue
        evidence_sources.append(
            {
                "evidence_id": f"artifact.{next_index}",
                "kind": "declared_task_artifact",
                "text": text,
            }
        )
        existing_texts.add(text)
        next_index += 1


def _goal_audit_prompt(
    *,
    request_envelope: Dict[str, Any],
    validation_issues: List[str],
    issue_records: List[Dict[str, Any]],
    evidence_sources: List[Dict[str, str]],
    validation_issue_ledger: Optional[List[Dict[str, Any]]] = None,
    semantic_audit: bool,
    post_repair_verification: bool = False,
    repair_feedback: Optional[List[Dict[str, Any]]] = None,
    unresolved_feedback: Optional[List[Dict[str, Any]]] = None,
    repair_cycle_history: Optional[List[Dict[str, Any]]] = None,
    latest_repair_transition: Optional[Dict[str, Any]] = None,
    required_goal_fields: Optional[List[str]] = None,
    semantic_scope_pointers: Optional[List[str]] = None,
) -> str:
    design_goal_locations = []
    task_context_locations = []
    for task_index, task in enumerate(request_envelope.get("tasks") or []):
        if not isinstance(task, dict):
            continue
        task_type = _normalize_task_type_value(task.get("task_type"))
        if task_type != "design_new_asos":
            task_context_locations.append(
                {
                    "task_index": task_index,
                    "task_id": str(task.get("task_id") or "").strip(),
                    "task_type": task_type,
                    "json_pointer": f"/tasks/{task_index}/context",
                }
            )
            continue
        design_goal_locations.append(
            {
                "task_index": task_index,
                "task_id": str(task.get("task_id") or "").strip(),
                "json_pointer": (
                    f"/tasks/{task_index}/context/structured_goal"
                ),
            }
        )
    noncanonical_findings = (
        []
        if issue_records
        else _noncanonical_goal_field_findings(request_envelope)
    )
    missing_design_goal = any(
        _normalize_task_type_value(task.get("task_type")) == "design_new_asos"
        and not (
            isinstance(task.get("context"), dict)
            and isinstance(task["context"].get("structured_goal"), dict)
            and task["context"]["structured_goal"]
        )
        for task in (request_envelope.get("tasks") or [])
        if isinstance(task, dict)
    )
    allowed_nonempty_channels: List[str] = ["unresolved"]
    if noncanonical_findings:
        allowed_nonempty_channels.append("field_dispositions")
    else:
        if issue_records or (semantic_audit and not missing_design_goal):
            allowed_nonempty_channels.append("patches")
        if missing_design_goal:
            allowed_nonempty_channels.append("goal_replacements")
    requirement_catalog = canonical_goal_requirement_catalog()
    if required_goal_fields:
        requirement_catalog["context.structured_goal"] = sorted(
            set(requirement_catalog["context.structured_goal"]) | set(required_goal_fields))
    from .region_overlap import constraint_execution_summary, effective_program_constraint_summary
    from .goal_contract import REGION_CONSTRAINT_SCOPE_INSTRUCTIONS
    from .coordinate_contract import coordinate_execution_summary, COORDINATE_ORIGIN_INSTRUCTIONS
    audit_input = {
        "required_goal_fields": required_goal_fields or [],
        "audit_mode": (
            "post_repair_semantic_verification"
            if post_repair_verification
            else "semantic_completeness_and_contract_repair"
            if semantic_audit
            else "contract_repair"
        ),
        "allowed_nonempty_channels": allowed_nonempty_channels,
        "evidence_sources": _evidence_sources_with_quote_spans(
            evidence_sources
        ),
        "validation_issues": validation_issues,
        "validation_issue_ledger": validation_issue_ledger or [],
        "canonical_contract_issues": issue_records,
        "canonical_task_types": sorted(CANONICAL_TASK_TYPES),
        "noncanonical_field_findings": noncanonical_findings,
        "canonical_task_context_registry": (
            [] if issue_records else canonical_task_context_field_registry()
        ),
        "canonical_destination_catalog": (
            [] if issue_records else canonical_goal_destination_catalog()
        ),
        "overlap_semantics": {
            "full_containment": "The complete ASO lies inside the feature interval.",
            "contains_feature": "The complete feature lies inside the ASO; the ASO may extend on either side.",
            "any_overlap": "The ASO intersects the feature by minimum_overlap_bp (default one).",
            "junction_crossing": "At least U bases before and D after a junction requires contains_feature over the U+D base core: acceptor offsets -U..D-1, donor offsets 1-U..D, both in transcript orientation. Do not place a longer ASO fully inside this core.",
        },
        "reference_scope_semantics": "A transcript supplied only to locate an exon does not imply an isoform-abundance objective. Preserve its identity in transcript_lock and the program; default_exon_context remains valid for the structural splice objective.",
        "region_scope_semantics": REGION_CONSTRAINT_SCOPE_INSTRUCTIONS,
        "effective_program_region_constraints": [
            {"goal_pointer": location["json_pointer"], "programs": effective_program_constraint_summary(
                request_envelope["tasks"][location["task_index"]].get("context", {}).get("structured_goal") or {})}
            for location in design_goal_locations
        ],
        "coordinate_origin_semantics": COORDINATE_ORIGIN_INSTRUCTIONS,
        "coordinate_execution": [
            {"goal_pointer": location["json_pointer"], **summary}
            for location in design_goal_locations
            if (summary := coordinate_execution_summary(
                request_envelope["tasks"][location["task_index"]].get("context", {}).get("structured_goal") or {}))
        ],
        "canonical_requirement_catalog": (
            [] if issue_records else requirement_catalog
        ),
        "canonical_field_registry": (
            canonical_goal_field_registry()
            if noncanonical_findings
            else []
        ),
        "task_context_locations": task_context_locations,
        "design_goal_locations": design_goal_locations,
        "prior_rejected_patches": repair_feedback or [],
        "unresolved_adjudication_feedback": unresolved_feedback or [],
        "repair_cycle_history": repair_cycle_history or [],
        "latest_repair_transition": latest_repair_transition or {},
        "current_request_envelope": request_envelope,
        "region_constraint_execution": [
            {"goal_pointer": location["json_pointer"], "scopes": constraint_execution_summary(
                request_envelope["tasks"][location["task_index"]].get("context", {}).get("structured_goal") or {})}
            for location in design_goal_locations
        ],
    }
    if semantic_scope_pointers:
        # The complete request and envelope stay available as evidence/context.
        # Only the edit surface and unrelated schema catalogs are partitioned.
        audit_input["semantic_scope_pointers"] = semantic_scope_pointers
        audit_input["canonical_destination_catalog"] = []
        audit_input["canonical_task_context_registry"] = []
        audit_input["task_context_locations"] = []
        audit_input["canonical_field_registry"] = []
        audit_input["region_constraint_execution"] = [
            {"goal_pointer": entry["goal_pointer"], "scopes": [scope
                for scope in entry["scopes"] if
                entry["goal_pointer"] + scope["scope"].rstrip("/") + "/region_constraints"
                in semantic_scope_pointers]}
            for entry in audit_input["region_constraint_execution"]
        ]
        if is_focused_region_audit(audit_input):
            audit_input["region_scope_checks_required"] = region_audit_obligations(audit_input)
    length_obligations = program_length_audit_obligations(audit_input)
    if length_obligations:
        audit_input["program_length_checks_required"] = length_obligations
    return (
        "Audit the supplied request envelope. Return only the compact audit object "
        "defined by your response schema. Use canonical_contract_issues.json_pointer "
        "as the exact patch path and canonical_contract_issues.required_operation as "
        "the add or replace operation for listed violations. Every item in "
        "validation_issue_ledger is still open and must be discharged by a canonical "
        "repair or an unresolved item; status='valid' is unavailable while that ledger "
        "is non-empty. You may instead remove an "
        "existing optional causal field when that removal resolves the listed issue. Every other structured-goal "
        "patch path must start with its design_goal_locations.json_pointer; there is "
        "no root /structured_goal patch path. Non-design task fact patches must use "
        "the exact task_context_locations.json_pointer and a field from "
        "canonical_task_context_registry. Resolve invented field placement from the "
        "semantic registries; never infer aliases from spelling. For semantic repairs, "
        "choose an exact operation/path branch exposed by the response schema and make "
        "the most specific field edit. Use an offered /- path to append a missing "
        "collection member; do not replace an existing object or collection wholesale. "
        "Only arrays listed "
        "in allowed_nonempty_channels may contain items; set every other response "
        "array to []. The canonical_requirement_catalog is authoritative for schema "
        "requiredness. An absent optional field is not a blocking omission merely "
        "because it could hold a value; omit or remove it when evidence does not "
        "assign that value to that exact object scope. Emit an unresolved user "
        "question only when the request cannot be fulfilled without a user-specific "
        "choice, never to populate an optional route mapping that the request did "
        "not make. Never add an optional object or collection and simultaneously ask "
        "the user to supply one of its required children. If the complete object is not "
        "supported, omit the optional structure. When unresolved_adjudication_feedback is non-empty, resolve every "
        "listed item with the requested canonical repair or removal; do not repeat "
        "the rejected unresolved item. Source coordinates or interval rows do not alone "
        "prove that an executable overlap filter was requested. Create or restore an "
        "optional region_constraints entry only when request or clarification evidence "
        "requires that execution semantics and supports every required child; otherwise "
        "keep the optional entry absent and preserve coordinates in target identity/context. "
        "Never invent a least-restrictive overlap policy. When latest_repair_transition is present, "
        "verify its host-observed before/after changes against the original evidence_sources. "
        "These are the actual values after patch application and canonical normalization; "
        "applied_repairs.reason is only the earlier model's claim, not evidence that its edit "
        "was correct. Check that each changed value preserves the requested mechanism, scope, "
        "constraints and outputs. A reason that says to preserve a value does not justify an "
        "actual change to a different value. Correct unsupported changes through the normal "
        "evidence-bound patch protocol; do not revert supported corrections merely because "
        "they differ from the earlier envelope. In a focused audit, review changes within "
        "semantic_scope_pointers using the complete transition as context. "
        "When repair_cycle_history is non-empty, the repair "
        "sequence revisited an earlier envelope. Resolve the disputed paths from evidence in "
        "one internally consistent direction, remove unsupported optional causal fields, and "
        "do not repeat a repair that the history shows was subsequently reversed. Complete one finite evidence comparison and emit JSON "
        "immediately.\n\n"
        + json.dumps(
            audit_input,
            ensure_ascii=False,
            indent=2,
        )
    )


def _goal_audit_model_failure(payload: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(payload, dict):
        return {
            "status": "model_failure",
            "reason": "goal_contract_audit_invalid_payload",
        }
    error = str(payload.get("error") or "").strip()
    if not error:
        return None
    result: Dict[str, Any] = {
        "status": "model_failure",
        "reason": f"goal_contract_audit_{error}",
    }
    response_reason = str(payload.get("reason") or "").strip()
    if response_reason:
        result["model_reason"] = response_reason
    return result


def _run_goal_audit_sync(prompt: str) -> Dict[str, Any]:
    async def _invoke() -> Dict[str, Any]:
        return await _run_goal_contract_audit_agent_once(prompt)

    try:
        payload = asyncio.run(_invoke())
    except RuntimeError as exc:
        if "running event loop" not in str(exc).lower():
            return {
                "status": "model_failure",
                "reason": f"goal_contract_audit_failed: {exc}",
            }
        loop = asyncio.new_event_loop()
        try:
            payload = loop.run_until_complete(_invoke())
        except Exception as nested_exc:
            return {
                "status": "model_failure",
                "reason": f"goal_contract_audit_failed: {nested_exc}",
            }
        finally:
            loop.close()
    except Exception as exc:
        return {
            "status": "model_failure",
            "reason": f"goal_contract_audit_failed: {exc}",
        }
    failure = _goal_audit_model_failure(payload)
    return payload if failure is None else failure


