def _v2_excel_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", (value or "").strip().lower()).strip("_")


def _v2_excel_should_flatten_dict(key: str, value: Any) -> bool:
    if not isinstance(value, dict):
        return False
    normalized = _v2_excel_key(key)
    if normalized in _V2_EXCEL_FLATTEN_DICT_FIELDS:
        return True
    signal_terms = ("splice", "splicing", "nmd", "ptc", "premature_stop", "prediction", "consequence")
    return any(term in normalized for term in signal_terms)


def _v2_excel_has_splice_delta(row: Dict[str, Any]) -> bool:
    for key in (
        "delta_inclusion_deletion",
        "delta_inclusion_replacement",
        "delta_deletion",
        "delta_replacement",
        "shared_context_delta",
    ):
        value = row.get(key)
        if value not in (None, "", "NA", "N/A"):
            return True
    return False


def _v2_excel_expand_row(row: Dict[str, Any]) -> Dict[str, Any]:
    expanded = dict(row)
    for key, value in row.items():
        if not _v2_excel_should_flatten_dict(key, value):
            continue
        for nested_key, nested_value in value.items():
            if nested_key not in expanded:
                expanded[nested_key] = nested_value
                continue
            prefixed_key = f"{key}_{nested_key}"
            if prefixed_key not in expanded:
                expanded[prefixed_key] = nested_value
    if not expanded.get("splice_eval_status") and _v2_excel_has_splice_delta(expanded):
        expanded["splice_eval_status"] = "scored"
    if not expanded.get("splice_eval_status"):
        stage_results = row.get("stage_results") if isinstance(row.get("stage_results"), dict) else {}
        splice_stage = stage_results.get("splice_eval") if isinstance(stage_results.get("splice_eval"), dict) else {}
        stage_status = str(splice_stage.get("status") or "").strip()
        if stage_status:
            expanded["splice_eval_status"] = stage_status
        stage_reason = str(splice_stage.get("reason_code") or splice_stage.get("details") or "").strip()
        if stage_reason and not expanded.get("splice_eval_skip_reason"):
            expanded["splice_eval_skip_reason"] = stage_reason
    return expanded


def _v2_excel_columns(rows: List[Dict[str, Any]]) -> List[str]:
    columns: List[str] = []
    seen: Set[str] = set()
    for row in rows:
        for key in row.keys():
            if key not in seen:
                seen.add(key)
                columns.append(key)
    return columns


def _v2_excel_cell_value(value: Any) -> Any:
    if value is None:
        return ""
    if isinstance(value, (str, int, float, bool)):
        return value
    try:
        return json.dumps(value, ensure_ascii=True)
    except Exception:
        return str(value)


def _v2_excel_sheet_has_non_identity_columns(columns: List[str]) -> bool:
    for col in columns:
        normalized = _v2_excel_key(col)
        if normalized not in _V2_EXCEL_IDENTITY_COLUMNS:
            return True
    return False


def _write_v2_rows_excel(
    rows: List[Dict[str, Any]],
    output_path: Path,
    *,
    sheet_groups: Optional[List[Tuple[str, List[str]]]] = None,
) -> Tuple[Optional[str], Optional[str]]:
    if not rows:
        return None, "excel_no_rows"
    try:
        import openpyxl
    except Exception as exc:
        return None, f"excel_dependency_missing: {exc}"

    excel_rows = [_v2_excel_expand_row(row) for row in rows]
    columns = _v2_excel_columns(excel_rows)
    if not columns:
        return None, "excel_no_columns"
    output_path.parent.mkdir(parents=True, exist_ok=True)
    workbook = openpyxl.Workbook()
    workbook.remove(workbook.active)
    norm_map = {_v2_excel_key(col): col for col in columns}
    from .excel_values import LosslessExcelValues
    long_values = LosslessExcelValues(workbook, columns, ['All', *(name for name, _ in (sheet_groups or []))])

    def _write_sheet(sheet_name: str, sheet_columns: List[str]) -> None:
        if not sheet_columns:
            return
        worksheet = workbook.create_sheet(title=(sheet_name or "Sheet")[:31])
        worksheet.append(sheet_columns)
        for row_index, row in enumerate(excel_rows):
            long_values.append(worksheet, row_index, sheet_columns,
                               [_v2_excel_cell_value(row.get(col, "")) for col in sheet_columns])
        worksheet.freeze_panes = "A2"

    _write_sheet("All", columns)
    for sheet_name, requested_columns in sheet_groups or []:
        resolved: List[str] = []
        for col in requested_columns:
            actual = norm_map.get(_v2_excel_key(col))
            if actual and actual not in resolved:
                resolved.append(actual)
        if sheet_name == "Splice" and not _v2_excel_sheet_has_non_identity_columns(resolved):
            continue
        if resolved:
            _write_sheet(sheet_name, resolved)
    long_values.finish()
    try:
        workbook.save(output_path)
    except Exception as exc:
        return None, f"excel_write_failed: {exc}"
    return str(output_path), None


def _load_v2_rows_json(path: Path) -> Tuple[List[Dict[str, Any]], Optional[str]]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return [], "json_not_found"
    except json.JSONDecodeError as exc:
        return [], f"json_invalid: {exc}"
    except Exception as exc:
        return [], f"json_read_failed: {exc}"
    rows = payload.get("rows") if isinstance(payload, dict) else None
    if isinstance(payload, list):
        rows = payload
    if not isinstance(rows, list):
        return [], "json_rows_missing"
    dict_rows = [row for row in rows if isinstance(row, dict)]
    return dict_rows, None if dict_rows else "json_rows_empty"


def _write_v2_table_excel_from_json(path_value: Any) -> Tuple[Optional[str], Optional[str]]:
    path_text = _summary_text(path_value)
    if not path_text:
        return None, "json_path_missing"
    path = Path(path_text).expanduser()
    rows, error = _load_v2_rows_json(path)
    if error:
        return None, error
    return _write_v2_rows_excel(rows, path.with_suffix(".xlsx"), sheet_groups=_V2_EXCEL_SHEETS)


def _write_v2_excel_outputs(run_dir: str, response_payload: Dict[str, Any], response_basename: str) -> Dict[str, str]:
    run_path = Path(run_dir)
    outputs: Dict[str, str] = {}
    evaluation = response_payload.get("evaluation_summary") if isinstance(response_payload.get("evaluation_summary"), dict) else {}
    if isinstance(evaluation.get("provided_asos"), list):
        provided_rows = [row for row in evaluation.get("provided_asos") if isinstance(row, dict)]
        xlsx_path, error = _write_v2_rows_excel(
            provided_rows,
            _write_run_path(run_path, f"{response_basename}.xlsx"),
            sheet_groups=_V2_EXCEL_SHEETS,
        )
        if xlsx_path:
            outputs[f"{response_basename}_xlsx"] = xlsx_path
        elif error:
            outputs[f"{response_basename}_xlsx_error"] = error
        scoring = evaluation.get("provided_aso_scoring") if isinstance(evaluation.get("provided_aso_scoring"), dict) else {}
        path_candidates: List[Any] = [
            scoring.get("scored_tiles_path"),
            scoring.get("tiles_json_path"),
        ]
        path_candidates.extend(str(path) for path in sorted(_glob_run_paths(run_path, "v2_tasks/*/scored_tiles.json")))
        path_candidates.extend(str(path) for path in sorted(_glob_run_paths(run_path, "v2_tasks/*/scored_tiles.constraint_filtered.json")))
        seen_paths: Set[str] = set()
        for path_value in path_candidates:
            path_text = _summary_text(path_value)
            if not path_text or path_text in seen_paths:
                continue
            seen_paths.add(path_text)
            xlsx_path, error = _write_v2_table_excel_from_json(path_text)
            key = "xlsx_" + _v2_excel_key(_summary_rel_path(path_text, run_dir))
            if xlsx_path:
                outputs[key] = xlsx_path
            elif error:
                outputs[f"{key}_error"] = error
    return outputs


def _summary_rel_path(value: Any, run_dir: str) -> str:
    text = _summary_text(value)
    if not text:
        return ""
    path = Path(text).expanduser()
    run_path = Path(run_dir).expanduser()
    try:
        return path.relative_to(run_path).as_posix()
    except Exception:
        pass
    if path.is_absolute():
        try:
            return path.relative_to(run_path).as_posix()
        except Exception:
            pass
        try:
            resolved_run = run_path.resolve()
            return path.resolve().relative_to(resolved_run).as_posix()
        except Exception:
            pass
    run_name = run_path.name
    if run_name:
        parts = path.parts
        if run_name in parts:
            idx = parts.index(run_name)
            if idx + 1 < len(parts):
                return Path(*parts[idx + 1:]).as_posix()
    if "/runs/" in text:
        suffix = text.split("/runs/", 1)[1]
        parts = suffix.split("/", 1)
        if len(parts) == 2:
            return parts[1]
    return text


def _summary_sanitize_paths(markdown_text: str, run_dir: str) -> str:
    text = str(markdown_text or "")
    if not text:
        return ""
    run_path = Path(run_dir).expanduser()
    candidates: List[str] = []
    for candidate in (run_path, run_path.resolve() if run_path.exists() else None):
        if candidate is None:
            continue
        candidate_text = str(candidate)
        if candidate_text and candidate_text not in candidates:
            candidates.append(candidate_text)
    for root_text in sorted(candidates, key=len, reverse=True):
        text = text.replace(root_text + "/", "")
        text = text.replace(root_text, ".")
    run_name = run_path.name
    if run_name:
        text = text.replace(f"runs/{run_name}/", "")
        text = text.replace(f"runs/{run_name}", ".")
    return text


def _summary_detail_markdown(markdown_text: str) -> str:
    text = str(markdown_text or "").strip()
    if not text:
        return ""
    if text.startswith("# Run Output Summary"):
        marker = "\n## Detailed Response\n"
        if marker in text:
            return text.rsplit(marker, 1)[1].strip()
        return ""
    return text


def _summary_run_request(run_dir: str) -> str:
    request_path = _run_path(run_dir, "request.txt")
    if not request_path.exists():
        return ""
    try:
        return request_path.read_text(encoding="utf-8", errors="replace").strip()
    except Exception:
        return ""


def _summary_float(value: Any) -> Optional[float]:
    if value in (None, "", [], {}):
        return None
    try:
        return float(value)
    except Exception:
        return None


def _summary_fmt_float(value: Any, digits: int = 4) -> str:
    numeric = _summary_float(value)
    return f"{numeric:.{digits}f}" if numeric is not None else "NA"


def _summary_candidate_name(row: Dict[str, Any]) -> str:
    return _summary_text(row.get("name") or row.get("Name") or row.get("aso_id") or row.get("id"))


def _summary_candidate_sequence(row: Dict[str, Any]) -> str:
    return _summary_text(
        row.get("sequence")
        or row.get("provided_input_sequence")
        or row.get("Sequence")
        or row.get("comparison_sequence")
    )


def _summary_candidate_rank(row: Dict[str, Any]) -> int:
    rank = _optional_int(row.get("selection_rank"))
    return int(rank) if rank is not None else 10**9


def _summary_offtarget_count(row: Dict[str, Any]) -> Optional[int]:
    """Distinct gene counts only; exact loci and repeat loci are different units."""
    for key in ("off_target_gene_count", "Times_mapped_off_target_genes", "times_mapped_off_target_genes"):
        value = _optional_int(row.get(key))
        if value is not None:
            return int(value)
    if row.get("off_target_exact_count_unit") == "genes":
        for key in ("Off_target_exact_count", "off_target_exact_count"):
            value = _optional_int(row.get(key))
            if value is not None:
                return int(value)
    return None


def _summary_isoform_hit_count(row: Dict[str, Any]) -> Optional[int]:
    for key in ("isoform_uniqueness_count", "isoform_hit_count"):
        value = _optional_int(row.get(key))
        if value is not None:
            return int(value)
    return None


def _summary_ranked_rows(rows: List[Dict[str, Any]], limit: int = 10) -> List[Dict[str, Any]]:
    candidates = [row for row in rows if isinstance(row, dict) and _summary_candidate_sequence(row)]
    return sorted(
        candidates,
        key=lambda row: (
            _summary_candidate_rank(row),
            _summary_offtarget_count(row) if _summary_offtarget_count(row) is not None else 10**9,
            _summary_candidate_name(row),
        ),
    )[:limit]


def _summary_candidate_table(rows: List[Dict[str, Any]]) -> List[str]:
    if not rows:
        return []
    lines = [
        "| rank | ASO/candidate | sequence | isoform score class | isoform score | matched / catalog isoforms | coverage fraction | off-target genes |",
        "|---:|---|---|---|---:|---:|---:|---:|",
    ]
    for row in rows:
        rank = _summary_candidate_rank(row)
        off_count = _summary_offtarget_count(row)
        isoform_hits = _summary_isoform_hit_count(row)
        lines.append(
            f"| {rank if rank != 10**9 else 'NA'} | {_summary_candidate_name(row) or 'candidate'} | "
            f"{_summary_candidate_sequence(row)} | {row.get('isoform_uniqueness_class') or 'unknown'} | "
            f"{_summary_fmt_float(row.get('isoform_uniqueness_score'))} | "
            f"{isoform_hits if isoform_hits is not None else 'NA'} / {row.get('isoform_catalog_size') if row.get('isoform_catalog_size') is not None else 'NA'} | "
            f"{_summary_fmt_float(row.get('isoform_coverage_fraction'))} | "
            f"{off_count if off_count is not None else 'NA'} |"
        )
    return lines


_SPLICE_DELTA_KEYS = (
    "delta_inclusion_deletion",
    "delta_inclusion_replacement",
    "delta_deletion",
    "delta_replacement",
    "primary_delta_deletion",
    "primary_delta_replacement",
    "selected_delta_deletion",
    "selected_delta_replacement",
)


def _summary_primary_delta(value: Any) -> Optional[float]:
    parsed = [item for item in _parse_route_delta_floats(value) if item is not None]
    if parsed:
        return max(parsed, key=lambda item: abs(float(item)))
    return _summary_float(value)


def _summary_effect_size_label(delta: Optional[float]) -> str:
    if delta is None:
        return "unknown"
    magnitude = abs(float(delta))
    if magnitude >= 0.8:
        return "very strong"
    if magnitude >= 0.5:
        return "strong"
    if magnitude >= 0.2:
        return "moderate"
    if magnitude >= 0.05:
        return "weak"
    return "negligible"


def _summary_unique_text_items(items: Any, limit: int = 12) -> List[str]:
    seen: Set[str] = set()
    out: List[str] = []
    if not isinstance(items, list):
        return out
    for item in items:
        text = _summary_text(item)
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(text)
        if len(out) >= limit:
            break
    return out


def _summary_markdown_answer_lead(markdown_text: str) -> str:
    collected: List[str] = []
    started = False
    for raw in str(markdown_text or "").splitlines():
        line = raw.strip()
        if not started:
            if line.startswith("# "):
                started = True
            continue
        if line.startswith("#"):
            break
        if not line:
            if collected:
                break
            continue
        collected.append(line)
        if len(" ".join(collected)) >= 120:
            break
    return " ".join(collected).strip()


def _summary_splice_lookup(row: Dict[str, Any], key: str) -> Any:
    if row.get(key) not in (None, "", [], {}):
        return row.get(key)
    summary = row.get("splice_eval_summary") if isinstance(row.get("splice_eval_summary"), dict) else {}
    return summary.get(key)


def _summary_splice_delta(row: Dict[str, Any], key: str) -> Optional[float]:
    return _summary_primary_delta(_summary_splice_lookup(row, key))


def _summary_row_has_splice_score(row: Dict[str, Any]) -> bool:
    return any(_summary_splice_delta(row, key) is not None for key in _SPLICE_DELTA_KEYS)


def _summary_row_skip_delta(row: Dict[str, Any]) -> Optional[float]:
    return _summary_row_skip_measurement(row)[1]


def _summary_row_skip_measurement(row: Dict[str, Any]) -> Tuple[Optional[str], Optional[float]]:
    present = [(key, _summary_splice_delta(row, key)) for key in _SPLICE_DELTA_KEYS]
    present = [(key, value) for key, value in present if value is not None]
    return min(present, key=lambda item: item[1]) if present else (None, None)


def _summary_splice_site_label(row: Dict[str, Any]) -> str:
    for key in ("primary_label", "selected_label", "delta_names", "nearest_splice_site_label", "shared_context_label"):
        value = _summary_text(_summary_splice_lookup(row, key))
        if value:
            return value
    return ""


def _summary_genomic_span_text(row: Dict[str, Any]) -> str:
    span = row.get("genomic_span") if isinstance(row.get("genomic_span"), dict) else {}
    if not span:
        hits = row.get("mapping_hits") if isinstance(row.get("mapping_hits"), list) else []
        first_hit = hits[0] if hits and isinstance(hits[0], dict) else {}
        span = first_hit.get("genomic_span") if isinstance(first_hit.get("genomic_span"), dict) else {}
    chrom = span.get("chrom") or span.get("Chrom") or span.get("chr")
    start = span.get("start") if span.get("start") not in (None, "", [], {}) else span.get("Start")
    end = span.get("end") if span.get("end") not in (None, "", [], {}) else span.get("End")
    if chrom in (None, "", [], {}) or start in (None, "", [], {}) or end in (None, "", [], {}):
        return ""
    chrom_text = str(chrom)
    if not chrom_text.lower().startswith("chr"):
        chrom_text = f"chr{chrom_text}"
    return f"{chrom_text}:{start}–{end}"


def _summary_splice_rows_from_payload(payload: Dict[str, Any], run_dir: str) -> List[Dict[str, Any]]:
    """Use only the delivered evaluation's rows, preserving each input identity.

    A parent run can hold several evaluations of the same physical ASO at
    different requested sites. Name/sequence equality cannot bind their score
    or skip status to this evaluation. Missing fields stay unrecorded.
    """
    provided = payload.get("provided_asos")
    return [row for row in provided if isinstance(row, dict)] if isinstance(provided, list) else []


def _summary_top_splice_rows(rows: List[Dict[str, Any]], limit: int = 6) -> List[Dict[str, Any]]:
    candidates = [row for row in rows if _summary_row_has_splice_score(row)]
    if not candidates:
        return []
    return sorted(candidates, key=lambda row: (_summary_row_skip_delta(row) if _summary_row_skip_delta(row) is not None else 0.0))[:limit]


def _summary_splice_table(rows: List[Dict[str, Any]]) -> List[str]:
    if not rows:
        return []
    lines = [
        "| ASO | splice site | delta_deletion | delta_replacement | delta_inclusion_deletion | delta_inclusion_replacement |",
        "|---|---|---:|---:|---:|---:|",
    ]
    for row in rows:
        lines.append(
            f"| {_summary_candidate_name(row) or 'candidate'} | {_summary_splice_site_label(row) or 'NA'} | "
            f"{_summary_fmt_float(_summary_splice_delta(row, 'delta_deletion'), digits=6)} | "
            f"{_summary_fmt_float(_summary_splice_delta(row, 'delta_replacement'), digits=6)} | "
            f"{_summary_fmt_float(_summary_splice_delta(row, 'delta_inclusion_deletion'), digits=6)} | "
            f"{_summary_fmt_float(_summary_splice_delta(row, 'delta_inclusion_replacement'), digits=6)} |"
        )
    return lines


def _provided_aso_is_splice_request(payload: Dict[str, Any]) -> bool:
    if payload.get("splice_related_request"):
        return True
    targets = payload.get("evaluation_targets") if isinstance(payload.get("evaluation_targets"), list) else []
    for target in targets:
        if not isinstance(target, dict):
            continue
        blob = " ".join(
            _summary_text(target.get(key)).lower()
            for key in ("target_type", "desired_effect", "site_kind")
        )
        if any(token in blob for token in ("splic", "skip", "inclu", "acceptor", "donor")):
            return True
    return False


def _provided_aso_primary_target(payload: Dict[str, Any]) -> Dict[str, Any]:
    targets = [
        target
        for target in (payload.get("evaluation_targets") if isinstance(payload.get("evaluation_targets"), list) else [])
        if isinstance(target, dict)
    ]
    return targets[0] if targets else {}


def _provided_aso_exon_phrase(target: Dict[str, Any]) -> str:
    label = target.get("exon_label")
    if label in (None, "", [], {}):
        return "the requested exon"
    return f"exon {label}"


def _provided_aso_site_kind(row: Dict[str, Any], target: Dict[str, Any]) -> str:
    kind = _summary_text(target.get("site_kind")).lower()
    if kind:
        return kind
    label = _summary_splice_site_label(row).lower()
    if label.startswith("acceptor"):
        return "acceptor"
    if label.startswith("donor"):
        return "donor"
    return ""


def _provided_aso_site_phrase(row: Dict[str, Any], target: Dict[str, Any]) -> str:
    kind = _provided_aso_site_kind(row, target)
    label = _summary_splice_site_label(row)
    if kind == "acceptor":
        kind_text = "3' splice acceptor"
    elif kind == "donor":
        kind_text = "5' splice donor"
    else:
        kind_text = "splice site"
    if label:
        return f"{kind_text} (`{label}`)"
    return kind_text


def _provided_aso_orientation(row: Dict[str, Any]) -> Dict[str, Any]:
    value = row.get("orientation_interpretation")
    return value if isinstance(value, dict) else {}


def _provided_aso_splice_verdict(row: Dict[str, Any], target: Dict[str, Any]) -> str:
    desired = _summary_text(target.get("desired_effect")).lower()
    exon_phrase = _provided_aso_exon_phrase(target)
    skip_delta = _summary_row_skip_delta(row)
    size = _summary_effect_size_label(skip_delta)
    skip_intent = (not desired) or ("skip" in desired)
    if skip_delta is None:
        reason = _summary_text(
            _summary_splice_lookup(row, "splice_eval_skip_reason") or _summary_splice_lookup(row, "splice_eval_status")
        )
        extra = f" ({reason})" if reason else ""
        return f"Unscored: splice evaluation did not return a usable delta{extra}."
    if skip_intent:
        if skip_delta <= -0.2:
            return (
                f"Yes: it is predicted to decrease {exon_phrase} inclusion and increase skipping "
                f"({size} effect in this model)."
            )
        if skip_delta <= -0.05:
            return f"Only weakly: the model predicts a {size} decrease in {exon_phrase} inclusion."
        if skip_delta >= 0.2:
            return (
                f"No: the scored splice effect is not in the skipping direction for {exon_phrase} "
                f"({size} opposite-direction signal)."
            )
        return f"Little predicted effect on {exon_phrase} inclusion ({size})."
    if skip_delta >= 0.2:
        return f"Yes: it is predicted to increase {exon_phrase} inclusion ({size} effect in this model)."
    if skip_delta <= -0.2:
        return f"No: the model predicts decreased {exon_phrase} inclusion rather than increased inclusion."
    return f"Little predicted effect on {exon_phrase} inclusion ({size})."


def _provided_aso_splice_answer_paragraphs(
    row: Dict[str, Any],
    *,
    gene: str,
    transcript_id: str,
    target: Dict[str, Any],
) -> List[str]:
    sequence = _summary_candidate_sequence(row)
    mapping = _summary_text(row.get("mapping_status")).lower()
    if mapping and mapping != "mapped":
        return [
            f"The provided sequence `{sequence}` did not map to the requested {gene} context "
            f"(`{mapping}`), so this run cannot score a splice effect at {_provided_aso_exon_phrase(target)}."
        ]
    skip_delta = _summary_row_skip_delta(row)
    size = _summary_effect_size_label(skip_delta)
    inc_del = _summary_splice_delta(row, "delta_inclusion_deletion")
    inc_rep = _summary_splice_delta(row, "delta_inclusion_replacement")
    site_del = _summary_splice_delta(row, "delta_deletion")
    site_rep = _summary_splice_delta(row, "delta_replacement")
    transcript = _summary_text(transcript_id or row.get("transcript_id") or row.get("isoform_label"))
    span = _summary_genomic_span_text(row)
    chemistry = _summary_text(row.get("chemistry"))
    where_bits = [bit for bit in (f"transcript `{transcript}`" if transcript else "", span, _provided_aso_site_phrase(row, target)) if bit]
    score_bits = []
    if inc_del is not None:
        score_bits.append(f"`delta_inclusion_deletion` = {inc_del:.4f}")
    if inc_rep is not None:
        score_bits.append(f"`delta_inclusion_replacement` = {inc_rep:.4f}")
    if site_del is not None:
        score_bits.append(f"`delta_deletion` = {site_del:.4f}")
    if site_rep is not None:
        score_bits.append(f"`delta_replacement` = {site_rep:.4f}")
    first = f"{_provided_aso_splice_verdict(row, target)} `{sequence}` maps to {', '.join(where_bits) or gene}."
    if score_bits:
        first += f" Qualitative effect size: {size} ({'; '.join(score_bits)})."
    if chemistry:
        first += f" Chemistry assumed: {chemistry}."
    paragraphs = [first]
    kind = _provided_aso_site_kind(row, target)
    exon_phrase = _provided_aso_exon_phrase(target)
    if skip_delta is not None and skip_delta < 0:
        if kind == "acceptor":
            paragraphs.append(
                f"The mapped window overlaps the {exon_phrase} acceptor junction. A negative acceptor delta means "
                "the model predicts loss of 3' splice-site usage, which is the expected steric-blocking route to exon skipping."
            )
        elif kind == "donor":
            paragraphs.append(
                f"The mapped window overlaps the {exon_phrase} donor junction. A negative donor delta means "
                "the model predicts loss of 5' splice-site usage, which can increase skipping of that exon."
            )
    orientation = _provided_aso_orientation(row)
    role = _summary_text(orientation.get("provided_sequence_role") or row.get("provided_sequence_role"))
    antisense = _summary_text(
        orientation.get("synthesized_antisense_sequence") or row.get("reverse_complement_sequence")
    )
    if role == "target_site_sequence":
        oligo = f" `{antisense}`" if antisense else " the reverse complement of the provided string"
        paragraphs.append(
            "The provided string is the transcript-oriented target-site (sense) sequence, not the oligo to synthesize. "
            f"The antisense sequence to order is{oligo}."
        )
    elif role == "antisense_oligo_sequence":
        paragraphs.append("The provided string is interpreted as the antisense oligo sequence to synthesize.")
    off_count = _summary_offtarget_count(row)
    if off_count == 0:
        paragraphs.append("Exact other-gene off-targets in this run's 0-mismatch model: 0.")
    elif off_count is not None:
        paragraphs.append(f"Exact other-gene off-targets in this run's 0-mismatch model: {off_count}.")
    hits = row.get("mapping_hits") if isinstance(row.get("mapping_hits"), list) else []
    unique_spans = []
    for hit in hits:
        if not isinstance(hit, dict):
            continue
        span_text = _summary_genomic_span_text({"genomic_span": hit.get("genomic_span")})
        if span_text and span_text not in unique_spans:
            unique_spans.append(span_text)
    if len(hits) > 1 and len(unique_spans) == 1:
        paragraphs.append(
            f"The sequence also matches {len(hits)} annotated isoforms, but they share the same genomic window ({unique_spans[0]}); this is not {len(hits)} distinct genomic target sites."
        )
    paragraphs.append(
        "These splice deltas are in-silico scores, not an experimental skipping measurement, and they do not by themselves prove a PTC or NMD outcome."
    )
    return paragraphs


def _provided_aso_knockdown_answer_paragraphs(
    provided_rows: List[Dict[str, Any]],
    *,
    gene: str,
    species: str,
    target_context: str,
    splice_rows: List[Dict[str, Any]],
) -> List[str]:
    mapped = sum(1 for row in provided_rows if _summary_text(row.get("mapping_status")).lower() == "mapped")
    zero_off = sum(1 for row in provided_rows if _summary_offtarget_count(row) == 0)
    location = gene
    if species:
        location += f" ({species})"
    paragraphs = [
        f"This run evaluated {len(provided_rows)} provided ASO(s) for {location}"
        f"{f' in {target_context}' if target_context else ''}."
        f" {mapped}/{len(provided_rows)} mapped; {zero_off}/{len(provided_rows)} had 0 exact other-gene off-targets."
    ]
    top_rows = _summary_ranked_rows(provided_rows, limit=1)
    if top_rows:
        top = top_rows[0]
        off_count = _summary_offtarget_count(top)
        rank = _summary_candidate_rank(top)
        paragraphs.append(
            f"The top-ranked sequence is `{_summary_candidate_sequence(top)}` (`{_summary_candidate_name(top) or 'candidate'}`): "
            f"`selection_rank` {rank if rank != 10**9 else 'NA'}, isoform uniqueness {_summary_fmt_float(top.get('isoform_uniqueness_score'))}, "
            f"exact other-gene off-targets {off_count if off_count is not None else 'NA'}."
        )
    splice_top = _summary_top_splice_rows(splice_rows, limit=1)
    if splice_top:
        row = splice_top[0]
        metric, skip_delta = _summary_row_skip_measurement(row)
        paragraphs.append(
            f"The strongest splice signal is `{_summary_candidate_name(row) or 'candidate'}` at "
            f"{_summary_splice_site_label(row) or 'the scored splice site'}: "
            f"{_summary_effect_size_label(skip_delta)} predicted perturbation"
            f"{f' (`{metric}` = {skip_delta:.4f})' if skip_delta is not None else ''}."
        )
    return paragraphs


def _provided_aso_next_steps(
    *,
    splice_request: bool,
    merged_rows: List[Dict[str, Any]],
    target: Dict[str, Any],
    target_context: str,
    followups: List[str],
) -> List[str]:
    steps: List[str] = []
    if splice_request and merged_rows:
        row = merged_rows[0]
        orientation = _provided_aso_orientation(row)
        role = _summary_text(orientation.get("provided_sequence_role") or row.get("provided_sequence_role"))
        antisense = _summary_text(
            orientation.get("synthesized_antisense_sequence") or row.get("reverse_complement_sequence")
        )
        if role == "target_site_sequence" and antisense:
            steps.append(f"Synthesize the antisense oligo `{antisense}` if the provided string was the target-site sequence.")
        elif role == "antisense_oligo_sequence":
            sequence = _summary_candidate_sequence(row)
            if sequence:
                steps.append(f"Use the provided antisense sequence `{sequence}` as the oligo to synthesize.")
        exon_phrase = _provided_aso_exon_phrase(target)
        system = f" in {target_context}" if target_context else ""
        steps.append(
            f"Measure {exon_phrase} inclusion vs skipping{system} (RT-PCR or targeted RNA-seq). Do not treat the model delta as a percent-skipped prediction."
        )
    else:
        steps.append("Open the provided-ASO scoring spreadsheet and start from low `selection_rank`, 0 exact other-gene off-targets, and high isoform-uniqueness score.")
        if _summary_top_splice_rows(merged_rows, limit=1):
            steps.append("If splice perturbation is also of interest, inspect the splice-scored table and exclude skipped rows.")
        steps.append("Cross-check the caveats before treating any sequence as experimentally ready.")
    seen = {step.lower() for step in steps}
    orientation_answered = any("antisense" in step.lower() and "synthesize" in step.lower() for step in steps)
    for item in followups:
        text = _summary_text(item)
        if not text or text.lower() in seen:
            continue
        lowered = text.lower()
        if orientation_answered and ("confirm whether" in lowered or "if it is the target-site" in lowered) and (
            "target-site" in lowered or "target site" in lowered or "reverse-complement" in lowered or "reverse complement" in lowered
        ):
            continue
        steps.append(text)
        seen.add(lowered)
        if len(steps) >= 8:
            break
    return steps


def _provided_aso_file_lines(
    *,
    payload: Dict[str, Any],
    response_basename: str,
    run_dir: str,
) -> List[str]:
    scoring = payload.get("provided_aso_scoring") if isinstance(payload.get("provided_aso_scoring"), dict) else {}
    lines = [
        f"- `{response_basename}.md`: this human-readable summary.",
        f"- `{response_basename}.xlsx`: spreadsheet version of the full provided-ASO evaluation table.",
        f"- `{response_basename}.json`: full evaluation payload.",
    ]
    scored_path = _summary_rel_path(scoring.get("scored_tiles_path"), run_dir)
    if scored_path:
        scored_xlsx = _summary_rel_path(str((Path(run_dir) / scored_path).with_suffix(".xlsx")), run_dir)
        if (Path(run_dir) / scored_xlsx).exists():
            lines.append(f"- `{scored_xlsx}`: spreadsheet version of the normal ranking/off-target/isoform table.")
        lines.append(f"- `{scored_path}`: normal ranking, exact off-target scoring, and isoform-conservation scoring.")
    for path in sorted(_glob_run_paths(run_dir, "v2_tasks/*/scored_tiles.json"))[:3]:
        xlsx_path = path.with_suffix(".xlsx")
        if xlsx_path.exists():
            lines.append(f"- `{_summary_rel_path(str(xlsx_path), run_dir)}`: spreadsheet version of splice-evaluation output.")
        lines.append(f"- `{_summary_rel_path(str(path), run_dir)}`: splice-evaluation output, including splice deltas and skip reasons.")
        constraint_path = path.with_name("scored_tiles.constraint_filtered.json")
        if constraint_path.exists():
            constraint_xlsx = constraint_path.with_suffix(".xlsx")
            if constraint_xlsx.exists():
                lines.append(f"- `{_summary_rel_path(str(constraint_xlsx), run_dir)}`: spreadsheet version of the constraint-filtered splice table.")
            lines.append(f"- `{_summary_rel_path(str(constraint_path), run_dir)}`: splice-scored table after constraint filtering.")
    return lines


def _summary_design_outcomes(response_payload: Dict[str, Any], run_dir: str) -> List[Dict[str, Any]]:
    deterministic = response_payload.get("deterministic_summary") if isinstance(response_payload.get("deterministic_summary"), dict) else {}
    raw_outcomes = deterministic.get("design_outcomes") if isinstance(deterministic.get("design_outcomes"), list) else []
    rows: List[Dict[str, Any]] = []
    for item in raw_outcomes:
        if not isinstance(item, dict):
            continue
        outcome = item.get("design_outcome") if isinstance(item.get("design_outcome"), dict) else {}
        child_dir_text = _summary_text(item.get("child_run_dir"))
        child_dir = Path(child_dir_text).expanduser() if child_dir_text else None
        best_path = ""
        if child_dir:
            for relative in (
                "artifacts/candidates/gapmer_scored_uniqueness.xlsx",
                "artifacts/candidates/gapmer_uniqueness_ranked.csv",
                "artifacts/candidates/gapmer_scored_uniqueness.json",
                "artifacts/candidates/generated_aso_set.json",
                "gapmer_tiling/gapmer_scored_uniqueness.xlsx",
                "gapmer_tiling/gapmer_uniqueness_ranked.csv",
                "gapmer_tiling/gapmer_scored_uniqueness.json",
                "report.md",
                "generated_aso_set.json",
            ):
                candidate = _run_path(child_dir, *Path(relative).parts)
                if candidate.exists():
                    best_path = _summary_rel_path(str(candidate), run_dir)
                    break
        artifacts = outcome.get("artifacts") if isinstance(outcome.get("artifacts"), dict) else {}
        if not best_path:
            best_path = _summary_rel_path(artifacts.get("generated_aso_set_json") or artifacts.get("generated_filter_trace_json") or child_dir_text, run_dir)
        evidence_details = outcome.get("evidence_details") if isinstance(outcome.get("evidence_details"), dict) else {}
        cross_species = evidence_details.get("cross_species") if isinstance(evidence_details.get("cross_species"), dict) else {}
        observations = evidence_details.get("conservation_observations")
        observations = observations if isinstance(observations, dict) else {}
        rows.append(
            {
                "gene": _summary_text(item.get("gene")),
                "label": _summary_text(item.get("label")),
                "status": _summary_text(outcome.get("outcome_status") or "unknown"),
                "candidate_count": outcome.get("candidate_count"),
                "unique_sequence_count": outcome.get("unique_sequence_count"),
                "no_candidate_reason": _summary_text(outcome.get("no_candidate_reason") or outcome.get("failure_reason")),
                "checked_candidate_count": cross_species.get("checked_candidate_count"),
                "passing_candidate_count": cross_species.get("passing_candidate_count"),
                "conservation_observations": observations,
                "requested_species": ", ".join(observations.get("requested_species") or cross_species.get("requested_species") or []),
                "best_path": best_path,
            }
        )
    return rows


def _summary_design_status_table(rows: List[Dict[str, Any]]) -> List[str]:
    if not rows:
        return []
    lines = [
        "| gene | outcome | retained | unique | species compared | conservation evidence | where to choose/review |",
        "|---|---|---:|---:|---|---|---|",
    ]
    for row in rows:
        checked = _optional_int(row.get("checked_candidate_count"))
        passing = _optional_int(row.get("passing_candidate_count"))
        cross_text = "NA"
        observations = row.get("conservation_observations") or {}
        if observations.get("active"):
            cross_text = (f"{observations['exact']} exact; {observations['nonmatching']} nonmatching; "
                          f"{observations['unknown']} unknown")
        elif checked is not None and passing is not None:
            cross_text = f"{passing} exact / {checked} checked (recorded filter scope)"
        lines.append(
            f"| {row.get('gene') or 'target'} | `{row.get('status') or 'unknown'}` | "
            f"{_summary_text(row.get('candidate_count')) or '0'} | {_summary_text(row.get('unique_sequence_count')) or '0'} | "
            f"{row.get('requested_species') or 'not recorded'} | {cross_text} | `{row.get('best_path') or 'see child run'}` |"
        )
    if any((row.get("conservation_observations") or {}).get("active") for row in rows):
        lines.extend(["", "Conservation observations describe retained candidate rows within the recorded reference scope. Unknown or missing species evidence does not establish nonconservation. Optional conservation preserves otherwise eligible primary-species candidates; required conservation is an additional eligibility rule. Exact sequence matches do not establish cross-species biological activity."])
    return lines


def _summary_child_design_panels(response_payload: Dict[str, Any], run_dir: str) -> List[str]:
    """Include trusted selected-panel evidence in a requested parent report."""
    deterministic = response_payload.get("deterministic_summary")
    outcomes = deterministic.get("design_outcomes") if isinstance(deterministic, dict) else None
    if not isinstance(outcomes, list):
        return []
    run_root = Path(run_dir).resolve()
    lines: List[str] = []
    seen: Set[Path] = set()
    for item in outcomes:
        if not isinstance(item, dict):
            continue
        outcome = item.get("design_outcome")
        if not isinstance(outcome, dict) or outcome.get("outcome_status") != "completed_with_candidates":
            continue
        child_text = _summary_text(item.get("child_run_dir"))
        if not child_text:
            continue
        child = Path(child_text).resolve()
        if not child.is_relative_to(run_root):
            continue
        panel = child / "artifacts/candidates/design_panel.md"
        if panel in seen or not panel.is_file():
            continue
        seen.add(panel)
        from .report_presentation import read_markdown_fragment
        content = read_markdown_fragment(panel, run_dir).strip()
        if not content:
            continue
        if not lines:
            lines.extend(["## Selected physical candidate panels", "",
                          "The following candidate details come from the completed native child runs, including recorded reference positions and screening scope. Experimental effects remain unmeasured.", ""])
        label = _summary_text(item.get("label") or item.get("gene") or child.name)
        lines.extend([f"### {label}", "",
                      f"Full child panel: `{_summary_rel_path(str(panel), run_dir)}`.", ""])
        for line in content.splitlines():
            if line.startswith("# Candidate panel"):
                continue
            lines.append("#" + line if line.startswith("## ") else line)
        lines.append("")
    return lines


def _provided_aso_summary_markdown(
    *,
    payload: Dict[str, Any],
    response_basename: str,
    run_dir: str,
    response_payload: Optional[Dict[str, Any]] = None,
) -> str:
    rows = payload.get("provided_asos") if isinstance(payload.get("provided_asos"), list) else []
    provided_rows = [row for row in rows if isinstance(row, dict)]
    if not provided_rows:
        return ""
    response_payload = response_payload if isinstance(response_payload, dict) else {}
    context = payload.get("context_summary") if isinstance(payload.get("context_summary"), dict) else {}
    gene = _summary_text(context.get("gene_symbol") or context.get("gene_id") or "target")
    species = _summary_text(context.get("species"))
    target_context = _summary_text(context.get("target_context"))
    transcript_id = _summary_text(context.get("transcript_id") or context.get("isoform_label"))
    target = _provided_aso_primary_target(payload)
    splice_request = _provided_aso_is_splice_request(payload)
    splice_rows = _summary_splice_rows_from_payload(payload, run_dir)
    merged_rows = splice_rows
    request_text = _summary_run_request(run_dir)
    limitations = _summary_unique_text_items(
        [
            *(payload.get("limitations") if isinstance(payload.get("limitations"), list) else []),
            *(response_payload.get("limitations") if isinstance(response_payload.get("limitations"), list) else []),
        ],
        limit=12,
    )
    assumptions = _summary_unique_text_items(response_payload.get("assumptions"), limit=8)
    followups = _summary_unique_text_items(response_payload.get("suggested_followups"), limit=8)

    lines: List[str] = ["# Answer", ""]
    if splice_request:
        if len(merged_rows) == 1:
            lines.extend(_provided_aso_splice_answer_paragraphs(
                merged_rows[0],
                gene=gene,
                transcript_id=transcript_id,
                target=target,
            ))
        else:
            location = gene + (f" ({species})" if species else "")
            lines.append(
                f"This run evaluated {len(merged_rows)} provided ASO(s) for {location} as splice-switching sequences."
            )
            for row in merged_rows[:8]:
                name = _summary_candidate_name(row) or "provided ASO"
                verdict = _provided_aso_splice_verdict(row, target)
                lines.append(f"- `{name}` (`{_summary_candidate_sequence(row)}`): {verdict}")
            lines.extend(_provided_aso_splice_answer_paragraphs(
                merged_rows[0],
                gene=gene,
                transcript_id=transcript_id,
                target=target,
            )[1:])
        lines.append("")
    else:
        lines.extend(
            _provided_aso_knockdown_answer_paragraphs(
                provided_rows,
                gene=gene,
                species=species,
                target_context=target_context,
                splice_rows=merged_rows,
            )
        )
        lines.append("")

    next_steps = _provided_aso_next_steps(
        splice_request=splice_request,
        merged_rows=merged_rows,
        target=target,
        target_context=target_context,
        followups=followups,
    )
    if next_steps:
        lines.append("## What To Do Next")
        for item in next_steps:
            lines.append(f"- {item}")
        lines.append("")

    mapped = sum(1 for row in provided_rows if _summary_text(row.get("mapping_status")).lower() == "mapped")
    gene_wide = sum(1 for row in provided_rows if _summary_text(row.get("isoform_uniqueness_class")).lower() == "gene_wide")
    zero_off = sum(1 for row in provided_rows if _summary_offtarget_count(row) == 0)
    ranked = sum(1 for row in provided_rows if _summary_candidate_rank(row) != 10**9)
    splice_skipped = sum(1 for row in splice_rows if _summary_text(_summary_splice_lookup(row, "splice_eval_status")).startswith("skipped"))
    splice_scored = sum(1 for row in splice_rows if _summary_row_has_splice_score(row))
    lines.extend(
        [
            "## Evidence",
            f"- {len(provided_rows)} provided ASO(s) loaded.",
            f"- {mapped}/{len(provided_rows)} ASO(s) mapped to the target context.",
            f"- {ranked}/{len(provided_rows)} ASO(s) received `selection_rank`.",
            f"- {gene_wide}/{len(provided_rows)} ASO(s) were scored as `gene_wide` for isoform conservation.",
            f"- {zero_off}/{len(provided_rows)} ASO(s) had 0 off-target gene hits in this run's exact-match model.",
        ]
    )
    if splice_rows:
        lines.append(
            f"- Splice evaluation scored {splice_scored}/{len(splice_rows)} row(s) and skipped {splice_skipped}/{len(splice_rows)} row(s)."
        )
        unrecorded = sum(1 for row in splice_rows if not _summary_row_has_splice_score(row)
                         and not _summary_text(_summary_splice_lookup(row, "splice_eval_status")).startswith("skipped"))
        if unrecorded:
            lines.append(f"- {unrecorded}/{len(splice_rows)} row(s) have neither a usable splice delta nor a recorded skip status in this evaluation.")
    run_name = Path(run_dir).name
    if run_name:
        lines.append(f"- Output folder: `{run_name}`.")
    lines.append("")

    if not splice_request:
        top_rows = _summary_ranked_rows(provided_rows, limit=8)
        if top_rows:
            lines.append("## Top Normal-Ranking Candidates")
            lines.extend(_summary_candidate_table(top_rows))
            lines.append("")
    splice_top = _summary_top_splice_rows(merged_rows if splice_request else splice_rows, limit=6)
    if splice_top:
        lines.append("## Strongest Splice-Perturbation Candidates")
        lines.extend(_summary_splice_table(splice_top))
        lines.append("")

    if splice_request:
        lines.extend(
            [
                "## How To Read These Scores",
                "- Negative `delta_deletion` / `delta_replacement` at an acceptor means predicted loss of 3' splice-site usage.",
                "- `delta_inclusion_deletion` / `delta_inclusion_replacement` are exon-inclusion scores when available. Site-level deltas still count as a scored splice evaluation.",
                "- Exact off-target counts are 0-mismatch only. `isoform_uniqueness_*` is a knockdown coverage metric and is not the splice-decision score.",
                "",
            ]
        )
    else:
        lines.extend(
            [
                "## How To Read The Rankings",
                "- `selection_rank`: lower is better. Start here for a general knockdown shortlist.",
                "- `isoform_uniqueness_class`: `gene_wide` means standard knockdown candidates were scored for pan-isoform coverage.",
                "- " + ISOFORM_SCORE_DEFINITION,
                "- `isoform_uniqueness_count` / `isoform_hit_count`: number of annotated target-gene isoforms containing the site. Higher is better for pan-isoform knockdown. This is not an off-target count.",
                "- `Times_mapped`: legacy alias for that same target-isoform hit count on gapmer cDNA tiles. Do not read it as other-gene off-targets.",
                "- `off_target_gene_count`: distinct off-target genes. `Off_target_exact_count` counts workflow-specific exact hits; inspect `off_target_exact_count_unit` and the source loci/gene lists. `repeat_hit_count_exact` counts alternate exact repeat loci. These units are not interchangeable.",
                "- Splice deltas are model scores, not direct proof of PTC/NMD.",
                "",
            ]
        )

    lines.append("## Main Files To Open")
    lines.extend(_provided_aso_file_lines(payload=payload, response_basename=response_basename, run_dir=run_dir))
    lines.append("")

    if request_text:
        lines.extend(["## Original Request", "", _summary_sanitize_paths(request_text, run_dir), ""])

    caveat_items = _summary_unique_text_items([*assumptions, *limitations], limit=12)
    explained_shared_window = any("share the same genomic window" in line for line in lines)
    if caveat_items:
        lines.append("## Caveats")
        for item in caveat_items:
            lowered = item.lower()
            if explained_shared_window and "mapping_hit_count" in lowered and "ambiguity" in lowered:
                continue
            lines.append(f"- {item}")
        lines.append("")
    return "\n".join(lines).strip() + "\n"


def _composite_summary_markdown(
    *,
    response_payload: Dict[str, Any],
    response_basename: str,
    run_dir: str,
    original_markdown: str,
) -> str:
    completed_tasks = response_payload.get("completed_tasks") if isinstance(response_payload.get("completed_tasks"), list) else []
    design_rows = _summary_design_outcomes(response_payload, run_dir)
    if not completed_tasks and response_basename != "composite_report":
        return ""
    lines: List[str] = ["# Run Output Summary", ""]
    answer = _summary_text(response_payload.get("answer_summary"))
    if answer:
        lines.append(answer)
        lines.append("")
    lines.extend(
        [
            "## Main Files To Open",
            "- `report.md`: this top-level summary.",
            f"- `{response_basename}.md`: task-specific markdown output.",
            f"- `{response_basename}.json`: machine-readable response payload.",
        ]
    )
    if design_rows:
        lines.append("- `child_runs/`: per-gene child run folders; each child contains its own ranked files and report.")
    lines.extend(["", "## General Result"])
    report_status = _summary_text(response_payload.get("report_status"))
    if report_status:
        lines.append(f"- Report status: `{report_status}`.")
    lines.append(f"- Completed task outputs included: {len(completed_tasks)}.")
    limitations = response_payload.get("limitations") if isinstance(response_payload.get("limitations"), list) else []
    if limitations:
        lines.append(f"- Limitations reported: {len(limitations)}.")
    if design_rows:
        with_candidates = sum(1 for row in design_rows if row.get("status") == "completed_with_candidates")
        no_candidates = sum(1 for row in design_rows if row.get("status") == "completed_no_candidates")
        total_candidates = sum(int(row.get("candidate_count") or 0) for row in design_rows)
        lines.append(f"- Design child runs summarized: {len(design_rows)}.")
        lines.append(f"- Runs with candidates: {with_candidates}; runs with no candidates: {no_candidates}; total retained candidate rows: {total_candidates}.")
    lines.append("")

    if design_rows:
        lines.extend(
            [
                "## Where Users Should Look To Choose ASOs",
                "- Use this parent report to decide which genes/runs succeeded and which need follow-up.",
                "- For each candidate-producing run, open the child run path below and inspect the recorded ranking, requested constraints, off-target evidence and species coverage.",
                "- Do not choose ASOs from a child run marked `completed_no_candidates`; use its reason to decide whether to rerun with changed constraints.",
                "",
                "## Design Run Status",
            ]
        )
        lines.extend(_summary_design_status_table(design_rows))
        lines.append("")
        lines.extend(_summary_child_design_panels(response_payload, run_dir))
        attention = [row for row in design_rows if row.get("status") != "completed_with_candidates"]
        if attention:
            lines.append("## Runs Needing Attention")
            for row in attention:
                reason = row.get("no_candidate_reason") or (
                    f"{row['candidate_count']} candidate row(s) were retained; inspect the reported evidence limitations."
                    if row.get("candidate_count") else "No retained candidate set was available.")
                lines.append(f"- {row.get('gene') or 'target'}: `{row.get('status')}`. {reason}")
            lines.append("")
    elif completed_tasks:
        lines.append("## Task Outcomes")
        lines.extend(["| task | type | where to look |", "|---|---|---|"])
        for task in completed_tasks[:20]:
            if not isinstance(task, dict):
                continue
            task_id = _summary_text(task.get("task_id") or task.get("label") or "task")
            task_type = _summary_text(task.get("task_type") or "unknown")
            artifacts = task.get("artifacts") if isinstance(task.get("artifacts"), dict) else {}
            best_path = (
                artifacts.get("response_md")
                or artifacts.get("markdown")
                or artifacts.get("json")
                or artifacts.get("response_json")
                or task.get("child_run_dir")
            )
            lines.append(f"| {task_id} | {task_type} | `{_summary_rel_path(best_path, run_dir) or 'see task artifacts'}` |")
        lines.append("")
    if limitations:
        lines.append("## Caveats")
        for item in limitations[:10]:
            lines.append(f"- {_summary_text(item)}")
        lines.append("")
    detail_markdown = _summary_detail_markdown(original_markdown)
    if detail_markdown:
        lines.append("## Detailed Response")
        lines.append(_summary_sanitize_paths(detail_markdown, run_dir))
        lines.append("")
    return "\n".join(lines).strip() + "\n"


def _chooser_focused_v2_markdown(
    *,
    run_dir: str,
    markdown_text: str,
    response_payload: Dict[str, Any],
    response_basename: str,
) -> str:
    evaluation_payload = response_payload.get("evaluation_summary") if isinstance(response_payload.get("evaluation_summary"), dict) else {}
    if isinstance(evaluation_payload.get("provided_asos"), list):
        return _provided_aso_summary_markdown(
            payload=evaluation_payload,
            response_basename=response_basename,
            run_dir=run_dir,
            response_payload=response_payload,
        )
    composite = _composite_summary_markdown(
        response_payload=response_payload,
        response_basename=response_basename,
        run_dir=run_dir,
        original_markdown=markdown_text,
    )
    return composite


def _provided_aso_export_rows(response_payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Retain every molecule and all measured data alongside attributed assessments."""
    if response_payload.get("source_backed_reference_projection"):
        return deepcopy(response_payload.get("reference_projection_rows") or [])
    evaluation = response_payload.get("evaluation_summary") or {}
    context = evaluation.get("context_summary") or {}
    assessments = response_payload.get("evaluation_assessments") or []
    source_rows = [row for row in evaluation.get("provided_asos") or [] if isinstance(row, dict)]
    resolve = assessment_row_lookup(source_rows)
    by_row: Dict[int, List[Dict[str, Any]]] = {}
    for assessment in assessments if isinstance(assessments, list) else []:
        row = resolve(assessment)
        if row is not None:
            by_row.setdefault(id(row), []).append(assessment)
    rows = []
    for row in source_rows:
        if not isinstance(row, dict):
            continue
        exported = _v2_excel_expand_row(deepcopy(row))
        metadata = row.get("input_metadata") if isinstance(row.get("input_metadata"), dict) else {}
        if metadata.get("set_id") is not None:
            exported.setdefault("set_id", metadata["set_id"])
        for key, value in context.items():
            exported.setdefault("context_" + key, value)
        matching = by_row.get(id(row), [])
        # Never let generated assessment fields replace a sequence or measurement.
        exported["model_assessment_status"] = "provided" if len(matching) == 1 else "missing_or_ambiguous"
        if len(matching) == 1:
            exported["model_assessment"] = matching[0]
        rows.append(exported)
    return rows


def _native_evaluation_table_rows(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Bounded, one-row-per-physical-molecule view of recorded evaluation facts."""
    result = []
    for row in payload.get("provided_asos") or []:
        if not isinstance(row, dict):
            continue
        sequence = str(row.get("sequence") or "").upper()
        exact = [hit for hit in row.get("mapping_hits") or [] if isinstance(hit, dict)
                 and hit.get("match_orientation") == "reverse_complement"]
        same_strand = [hit for hit in row.get("mapping_hits") or [] if isinstance(hit, dict)
                       and hit.get("match_orientation") == "input_sequence"]
        near = [hit for hit in row.get("near_match_candidates") or [] if isinstance(hit, dict)
                and type(hit.get("mismatch_count")) is int]
        metadata = row.get("input_metadata") if isinstance(row.get("input_metadata"), dict) else {}
        orientation = _provided_aso_orientation_interpretation(row)
        target_site_input = orientation.get("provided_sequence_role") == "target_site_sequence"
        physical_orientation = "input_sequence" if target_site_input else "reverse_complement"
        physical_exact = same_strand if target_site_input else exact
        alternative_exact = exact if target_site_input else same_strand
        physical_near = sorted(
            (hit for hit in near if hit.get("match_orientation") == physical_orientation),
            key=lambda hit: hit["mismatch_count"],
        )
        site = physical_exact[0] if physical_exact else physical_near[0] if physical_near else {}
        identity = site.get("reference_identity") if isinstance(site.get("reference_identity"), dict) else {}
        alternative_sequence = sequence if target_site_input else row.get("reverse_complement_sequence")
        result.append({
            "set_id": metadata.get("set_id"),
            "aso_id": row.get("aso_id") or row.get("name"),
            "input_row_id": row.get("input_row_id"),
            "source_row": row.get("source_row"),
            "sequence": sequence,
            "evaluated_molecule_5to3": orientation.get("evaluated_molecule_sequence"),
            "chemistry": row.get("chemistry"),
            "length": row.get("length") if row.get("length") is not None else len(sequence),
            "gc_fraction": row.get("gc_fraction"),
            "maximum_homopolymer_run_nt": row.get("maximum_homopolymer_run_nt"),
            "declared_sequence_role": orientation.get("provided_sequence_role"),
            "physical_exact_antisense_hit_count": len(physical_exact),
            "physical_best_antisense_mismatch_count": 0 if physical_exact else physical_near[0]["mismatch_count"] if physical_near else None,
            "exact_same_strand_hit_count": len(same_strand),
            "opposite_orientation_alternative_5to3": alternative_sequence,
            "opposite_orientation_alternative_exact_antisense_hit_count": len(alternative_exact),
            "reverse_complement_alternative_5to3": row.get("reverse_complement_sequence") if not target_site_input else None,
            "reverse_complement_alternative_exact_antisense_hit_count": len(same_strand) if not target_site_input else None,
            "hit_count_unit": "recorded_transcript_hits",
            "mapping_transcript_id": identity.get("transcript_id") or site.get("transcript_id"),
            "mapping_scope": site.get("mapping_scope"),
            "mature_cdna_start_1based": site.get("cdna_start"),
            "mature_cdna_end_1based": site.get("cdna_end"),
            "genomic_segments_1based_inclusive": json.dumps(site.get("genomic_segments") or [], sort_keys=True),
            "target_genomic_strand": site.get("strand") or row.get("strand"),
            "off_target_observed_gene_count": row.get("off_target_observed_gene_count"),
            "off_target_count_status": row.get("off_target_count_status"),
            "selection_rank": row.get("selection_rank"),
        })
    return result


def _requested_output_paths(run_dir: str, requested_outputs: Optional[List[Dict[str, Any]]]) -> List[Path]:
    """Resolve filenames or explicit directories without inferring table semantics."""
    from .requested_artifacts import requested_file_destination
    paths: List[Path] = []
    for item in requested_outputs or []:
        if not isinstance(item, dict):
            continue
        explicit = str(item.get("path") or "").strip()
        candidates = [explicit] if explicit else []
        if not explicit:
            for field in ("kind", "label"):
                text = str(item.get(field) or "")
                candidates.extend(re.findall(r"(?<![\w/])(?:[\w./-]+\.(?:csv|tsv|md|markdown|json|xlsx))\b", text, re.I))
        for name in candidates:
            path = Path(name).expanduser()
            if not path.is_absolute():
                path = Path(run_dir) / path
            if explicit:
                path = requested_file_destination(item, path)
            if path not in paths:
                paths.append(path)
    return paths


def _write_requested_evaluation_exports(
    run_dir: str, response_payload: Dict[str, Any], markdown_text: str,
    requested_outputs: Optional[List[Dict[str, Any]]],
    evidence_outputs: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    """Honor explicit evaluation filenames without guessing from the input paths."""
    paths = _requested_output_paths(run_dir, requested_outputs)
    outputs: Dict[str, str] = {}
    rows = _provided_aso_export_rows(response_payload)
    for index, path in enumerate(paths, 1):
        suffix = path.suffix.lower()
        if suffix not in {".csv", ".tsv", ".md", ".markdown", ".json", ".xlsx"}:
            raise ValueError(f"unsupported_evaluation_export: {path}")
        path.parent.mkdir(parents=True, exist_ok=True)
        if suffix in {".csv", ".tsv"}:
            if not rows:
                raise ValueError("evaluation_export_has_no_rows")
            with path.open("w", encoding="utf-8", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=_v2_excel_columns(rows), delimiter="\t" if suffix == ".tsv" else ",")
                writer.writeheader()
                writer.writerows({key: _v2_excel_cell_value(value) for key, value in row.items()} for row in rows)
        elif suffix in {".md", ".markdown"}:
            from .evaluation_report import package_evaluation_evidence
            exported_markdown, assets = package_evaluation_evidence(
                markdown_text, path, evidence_outputs or {},
            )
            path.write_text(exported_markdown, encoding="utf-8")
            for asset_name, asset_path in assets.items():
                outputs[f"requested_export_{index}_asset_{asset_name}"] = asset_path
        elif suffix == ".json":
            path.write_text(json.dumps(response_payload, ensure_ascii=False, indent=2), encoding="utf-8")
        else:
            written, error = _write_v2_rows_excel(rows, path, sheet_groups=_V2_EXCEL_SHEETS)
            if error or not written:
                raise ValueError(f"evaluation_export_failed: {error}")
        outputs["requested_export_" + str(index)] = str(path)
    return outputs


def _native_design_producer(state: Dict[str, Any], run_dir: str, task_id: str) -> Optional[Path]:
    """Resolve one completed design's root from its own recorded task result."""
    envelope = state.get("request_envelope") or {}
    tasks = envelope.get("tasks") or []
    task = next((item for item in tasks if item.get("task_id") == task_id), None)
    if task is None or task.get("task_type") != "design_new_asos":
        return None
    producer = Path(run_dir).resolve()
    root_name = "v3_tasks" if envelope.get("schema_version") == "v3" else "v2_tasks"
    result_path = _run_path(run_dir, root_name, task_id, "design_task_result.json")
    if result_path.is_file():
        result = _read_json(result_path)
        child = Path(result.get("child_run_dir") or "").resolve()
        child_root = producer / "child_runs"
        if (result.get("task_id") != task_id or child == child_root
                or not child.is_relative_to(child_root)
                or result.get("child_status") not in {"run_complete", "completed"}):
            raise ValueError("requested_output_native_producer_invalid:" + task_id)
        return child
    return producer if len(tasks) == 1 else None


def _native_export_catalog(state: Dict[str, Any], run_dir: str, task_id: str) -> Dict[str, str]:
    """Bind artifacts to their recorded producer, without selecting a sibling."""
    envelope = state.get("request_envelope") or {}
    tasks = envelope.get("tasks") or []
    task = next((item for item in tasks if item.get("task_id") == task_id), None)
    if task is None:
        return {}
    producer = Path(run_dir).resolve()
    if task.get("task_type") == "design_new_asos":
        producer = _native_design_producer(state, run_dir, task_id)
        if producer is None:
            return {}
    elif task.get("task_type") == "compare_aso_sets" or (
        task.get("task_type") != "build_composite_report" and len(tasks) != 1
    ):
        # Native analytical tasks can own their own Markdown result. A final
        # output bound to that task must not silently borrow a sibling's or
        # the parent's report.
        root_name = "v3_tasks" if envelope.get("schema_version") == "v3" else "v2_tasks"
        task_root = _run_path(run_dir, root_name, task_id)
        manifest = task_root / "task_outputs_manifest.json"
        if not manifest.is_file():
            return {}
        record = _read_json(manifest)
        candidate = Path((record.get("artifacts") or {}).get("markdown") or "").resolve()
        if record.get("task_id") != task_id or not candidate.is_relative_to(task_root.resolve()) or not candidate.is_file():
            return {}
        catalog = {"report_md": str(candidate)}
        if task.get("task_type") in {"compare_aso_sets", "evaluate_existing_aso_set"}:
            table = Path((record.get("artifacts") or {}).get("comparison_table_csv") or "").resolve()
            if table.is_relative_to(task_root.resolve()) and table.is_file():
                catalog["comparison_table_csv"] = str(table)
        return catalog
    artifacts = _discover_core_artifacts(str(producer))["paths"]
    from .requested_artifacts import NATIVE_EXPORT_FORMATS
    catalog = {key: artifacts[key] for key in NATIVE_EXPORT_FORMATS if key in artifacts}
    if "generated_aso_set_json" in artifacts:
        catalog["design_panel_csv"] = str(Path(artifacts["generated_aso_set_json"]).with_name("design_panel.csv"))
    catalog = {key: path for key, path in catalog.items() if Path(path).is_file()}
    if task.get("task_type") == "build_composite_report":
        # A composite owns its report, while a design dependency owns its panel.
        # Inherit a native role only if exactly one completed direct design
        # dependency supplies it. Distinct child panels must stay distinct.
        child_catalogs = [
            _native_export_catalog(state, run_dir, child_id)
            for child_id in task.get("depends_on") or []
            if any(item.get("task_id") == child_id and item.get("task_type") == "design_new_asos"
                   for item in tasks)
        ]
        for key in ("design_panel_csv", "generated_aso_set_json"):
            if key in catalog:
                continue
            sources = {child[key] for child in child_catalogs if key in child}
            if len(sources) == 1:
                catalog[key] = sources.pop()
    return catalog


def _composite_design_output_producer(task, tasks_by_id, spec, destination, key):
    """Resolve a design panel bound to a composite only with unique typed identity."""
    if (not isinstance(task, dict) or task.get("task_type") != "build_composite_report"
            or key not in {"design_panel_csv", "generated_aso_set_json"}):
        return None
    candidates = []
    for task_id in task.get("depends_on") or []:
        child = tasks_by_id.get(task_id)
        if not isinstance(child, dict) or child.get("task_type") != "design_new_asos":
            continue
        context = child.get("context") if isinstance(child.get("context"), dict) else {}
        structured = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
        symbol = str(context.get("gene_symbol") or structured.get("gene_symbol") or "").strip()
        if symbol:
            candidates.append((task_id, symbol))
    if len(candidates) < 2 or len({symbol.casefold() for _, symbol in candidates}) != len(candidates):
        return None

    def mentions(symbol, text):
        symbol, text = symbol.casefold(), str(text or "").casefold()
        offset = 0
        while (index := text.find(symbol, offset)) >= 0:
            before = text[index - 1] if index else ""
            end = index + len(symbol)
            after = text[end] if end < len(text) else ""
            if not before.isalnum() and not after.isalnum():
                return True
            offset = index + 1
        return False

    label_matches = {task_id for task_id, symbol in candidates if mentions(symbol, spec.get("label"))}
    path_matches = {task_id for task_id, symbol in candidates if mentions(symbol, destination.stem)}
    if len(label_matches) > 1 or len(path_matches) > 1:
        return None
    if label_matches and path_matches and label_matches != path_matches:
        return None
    selected = label_matches or path_matches
    return next(iter(selected)) if len(selected) == 1 else None


def _bounded_completed_evaluation_evidence(
    state: Dict[str, Any], *, evidence_directory: Optional[Path] = None,
) -> List[Dict[str, Any]]:
    """Carry attested per-molecule measurements to downstream report writers."""
    _, completed_tasks = _collect_completed_task_outputs(state)
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    evaluation_evidence = []
    for task in completed_tasks:
        if task.get("task_type") != "evaluate_existing_aso_set":
            continue
        payload = task.get("payload") if isinstance(task.get("payload"), dict) else {}
        source = payload.get("evaluation_summary") if isinstance(payload.get("evaluation_summary"), dict) else payload
        if not isinstance(source.get("provided_asos"), list):
            continue
        from .reference_report_projection import evaluation_projection, alignment_export_observation
        projection = evaluation_projection(source)
        rows = []
        for row in source["provided_asos"][:100]:
            if not isinstance(row, dict):
                continue
            hits = row.get("mapping_hits") if isinstance(row.get("mapping_hits"), list) else []
            near = row.get("near_match_candidates") if isinstance(row.get("near_match_candidates"), list) else []
            rows.append({
                "name": row.get("name") or row.get("aso_id"),
                "input_row_id": row.get("input_row_id"),
                "source_file": row.get("source_file"), "source_row": row.get("source_row"),
                "input_metadata": row.get("input_metadata"),
                "sequence": row.get("sequence"),
                "length": row.get("length"),
                "gc_fraction": row.get("gc_fraction"),
                "maximum_homopolymer_run_nt": row.get("maximum_homopolymer_run_nt"),
                "orientation_interpretation": row.get("orientation_interpretation"),
                "principal_reference_exon_membership": row.get("principal_reference_exon_membership"),
                "mapping_hits": [alignment_export_observation(hit)
                    for hit in hits[:5] if isinstance(hit, dict)],
                "mapping_hits_total": len(hits),
                "mapping_hits_preview_truncated": len(hits) > 5,
                "near_match_candidates": [alignment_export_observation(hit)
                    for hit in near[:3] if isinstance(hit, dict)],
                "near_match_candidates_total": len(near),
                "near_match_candidates_preview_truncated": len(near) > 3,
                "off_target_count_scope": row.get("off_target_count_scope"),
            })
        entry = {
            "task_id": task.get("task_id"),
            "context_summary": source.get("context_summary"),
            "total_rows": len(source["provided_asos"]),
            "rows_truncated": len(source["provided_asos"]) > len(rows),
            "source_json_path": str(
                (task_artifacts.get(task.get("task_id")) or {}).get("json")
                or (task_artifacts.get(task.get("task_id")) or {}).get("response_json") or ""
            ),
            "rows": rows,
            "reference_projection_is_complete": True,
            "reference_projection_scope": "All supplied observations and all retained alignment records. This does not establish exhaustive reference search coverage; retain each recorded search_scope.",
            "preview_count_scope": "Counts describe recorded observations across reference groups, RNA contexts, orientations and mismatch criteria. They are not the expected count for a requested subset or a newly computed search.",
        }
        if evidence_directory is None:
            entry["reference_projection"] = projection
        else:
            from .output_evidence import store_reference_projection
            entry["reference_projection_file"] = store_reference_projection(projection, evidence_directory)
        evaluation_evidence.append(entry)
    return evaluation_evidence


def _materialize_requested_final_outputs(state: Dict[str, Any], run_dir: str) -> Dict[str, Any]:
    """Render explicit files from native results without replacing those results."""
    from .analysis_execution import execute_analysis_program
    from .requested_artifacts import (
        requested_artifact_errors, requested_artifact_sha256,
        native_export_key, copy_native_export,
    )
    envelope = state.get("request_envelope") or {}
    requested = _requested_output_paths(run_dir, envelope.get("final_outputs"))
    directory = _write_run_path(run_dir, "requested_artifacts")
    receipt_path = directory / "delivery.json"
    prior_delivery = _read_json(receipt_path) if receipt_path.is_file() else {}
    # A generic exporter or failed program may already have created these
    # paths without satisfying the custom output contract. Reuse requires a
    # completed analysis task or a successful delivery of the same bytes for
    # this request. File existence alone must not bypass content review.
    contract_sha256 = hashlib.sha256(json.dumps({
        "request_text": str(state.get("request") or ""),
        "request_envelope": envelope,
    }, sort_keys=True).encode()).hexdigest()
    prior_verified = (prior_delivery.get("ok") is True
                      and prior_delivery.get("contract_sha256") == contract_sha256)
    completed_native_paths: Set[str] = set()
    tasks_by_id = {
        str(task.get("task_id") or ""): task
        for task in envelope.get("tasks") or [] if isinstance(task, dict)
    }
    for spec in envelope.get("final_outputs") or []:
        if not isinstance(spec, dict):
            continue
        task_id = str(spec.get("task_id") or "")
        task = tasks_by_id.get(task_id)
        if not task or str(task.get("task_type") or "") != "sandbox_analysis":
            continue
        task_root = _run_path(run_dir,
                              "v3_tasks" if envelope.get("schema_version") == "v3" else "v2_tasks",
                              task_id)
        status_path = task_root / "task_status.json"
        status = _read_json(status_path) if status_path.is_file() else {}
        if (status.get("task_id") != task_id
                or status.get("status") not in {"sandbox_analysis_ready", "report_ready", "completed"}):
            continue
        artifact_paths = {
            str(value) for key, value in (status.get("artifacts") or {}).items()
            if key.startswith("requested_export_") and isinstance(value, str)
        }
        for path in _requested_output_paths(run_dir, [spec]):
            if str(path) in artifact_paths and not requested_artifact_errors([path]):
                completed_native_paths.add(str(path))
    current_hashes = {str(path): requested_artifact_sha256(path) for path in requested
                      if not requested_artifact_errors([path])}
    pending = [path for path in requested if str(path) not in current_hashes
               or (str(path) not in completed_native_paths
                   and (not prior_verified or (prior_delivery.get("output_sha256") or {}).get(str(path))
                        != current_hashes[str(path)]))]
    if not requested or not pending:
        return {"ok": True, "already_present": True, "paths": [str(path) for path in requested]}
    directory.mkdir(parents=True, exist_ok=True)
    native_exports, native_sources, bindings = [], {}, {}
    for spec in envelope.get("final_outputs") or []:
        if not isinstance(spec, dict):
            continue
        for path in _requested_output_paths(run_dir, [spec]):
            if path not in pending:
                continue
            key = native_export_key(spec, path)
            task_id = str(spec.get("task_id") or "")
            task = tasks_by_id.get(task_id)
            if (key is None and isinstance(task, dict)
                    and task.get("task_type") == "compare_aso_sets"
                    and path.suffix.lower() == ".csv"
                    and "comparison_table_csv" in _native_export_catalog(state, run_dir, task_id)):
                key = "comparison_table_csv"
            producer = _composite_design_output_producer(task, tasks_by_id, spec, path, key)
            if producer:
                task_id = producer
            scope = spec.get("source_scope") or {}
            if scope and key != "design_panel_csv":
                raise ValueError(f"requested_output_scope_unsupported:{key}:{path}")
            binding = (task_id, key, json.dumps(scope, sort_keys=True))
            if path in bindings and bindings[path] != binding:
                raise ValueError(f"requested_output_ambiguous_producer:{path}")
            bindings[path] = binding
    for path, (task_id, key, scope_json) in bindings.items():
        catalog = _native_export_catalog(state, run_dir, task_id)
        native_sources[task_id] = catalog
        if key:
            if key not in catalog:
                raise ValueError(f"requested_output_native_source_unavailable:{task_id}:{key}")
            native_exports.append(copy_native_export(Path(catalog[key]), path, scope=json.loads(scope_json),
                                                     source_root=Path(run_dir)))
    attempted_paths = list(pending)
    copied = {item["destination"] for item in native_exports}
    pending = [path for path in pending if str(path) not in copied]
    if not pending:
        receipt = {"ok": True, "paths": [str(path) for path in requested],
                   "attempted_paths": [str(path) for path in attempted_paths],
                   "native_exports": native_exports, "execution_attempts": [], "validation_errors": []}
        receipt.update(contract_sha256=contract_sha256,
                       output_sha256={str(path): requested_artifact_sha256(path) for path in requested})
        receipt_path.write_text(json.dumps(receipt, indent=2))
        return receipt
    prior_attempts = [p for p in (directory / "execution_attempts").glob("*") if p.is_dir() and p.name.isdigit()]
    if len(prior_attempts) >= 3:
        return {"ok": False, "error": "requested_output_execution_budget_exhausted"}
    declared = _build_sandbox_declared_inputs(state, envelope)
    # Inputs can belong to individual task contexts rather than the outer
    # envelope. Retain those producer boundaries and actual source schemas;
    # the writer must not reconstruct them from a prose result or a sibling.
    declared["task_inputs"] = [
        {"task_id": task_id, "task_type": task.get("task_type"),
         "declared_inputs": _build_sandbox_declared_inputs(
             {}, _task_scoped_request_envelope(envelope, task))}
        for task_id, task in tasks_by_id.items()
    ]
    # Generated code reads this manifest at runtime. Keep its task-scoped
    # native catalog identical to the catalog supplied to the model below;
    # core-artifact inventories need not contain every final export source.
    declared["native_export_sources"] = native_sources
    # The generated program sees the same public request contract at runtime
    # as the coder saw in its payload, without guessing it from source reports.
    declared["request_text"] = str(state.get("request") or "")
    declared["request_envelope"] = deepcopy(envelope)
    # Keep the source paths and a bounded inventory. Large completed runs can
    # have hundreds of intermediate files; sending every indexed sample to the
    # report provider can exceed its context window before export begins.
    completed_context = _build_artifact_context({"artifact_refs": [{"path": run_dir}]})
    completed_index = completed_context.get("artifact_index") or {}
    declared["completed_run"] = {
        "run_dir": run_dir,
        "artifacts": _discover_core_artifacts(run_dir),
        "artifact_context": {
            "artifact_refs": completed_context.get("artifact_refs", []),
            "entries": completed_context.get("entries", []),
            "key_tables": _artifact_index_key_tables(completed_index, limit=20),
            "key_artifacts": [
                item for ref in completed_index.get("refs", [])
                for item in (ref.get("key_artifacts") or [])
            ][:40],
            "indexed_file_count": (completed_index.get("aggregate") or {}).get("file_count_indexed", 0),
            "index_truncated": (completed_index.get("aggregate") or {}).get("file_count_truncated", False),
        },
    }
    # Give the output writer measured task evidence directly. A file inventory
    # and prose report can omit reference identity, exon membership or exact
    # mapping coordinates even though the completed evaluation recorded them.
    # Keep this bounded per molecule; full alignment catalogs stay on disk.
    evaluation_evidence = _bounded_completed_evaluation_evidence(
        state, evidence_directory=directory / "evaluation_observations")
    if evaluation_evidence:
        declared["completed_run"]["evaluation_evidence"] = evaluation_evidence
    evaluation_sources = [Path(entry["reference_projection_file"]["path"])
                          for entry in evaluation_evidence if entry.get("reference_projection_file")]
    supplied_sources = [
        Path(item["path"])
        for inputs in [declared, *(entry["declared_inputs"] for entry in declared["task_inputs"])]
        for key in ("artifact_refs", "provided_input_files")
        for item in inputs.get(key) or []
        if isinstance(item, dict) and item.get("path") and Path(item["path"]).is_file()
        and (key != "artifact_refs" or Path(item["path"]) not in requested)
    ]
    from .design_export_evidence import design_export_evidence
    from .design_observation_tables import write_design_observations
    design_evidence = []
    for task_id, task in tasks_by_id.items():
        if task.get("task_type") != "design_new_asos":
            continue
        try:
            producer = _native_design_producer(state, run_dir, task_id)
        except ValueError as exc:
            design_evidence.append({"task_id": task_id, "sources": [], "resolution_error": str(exc)})
            continue
        if producer is not None:
            evidence = design_export_evidence(task_id, producer, _run_path)
            observations = write_design_observations(
                evidence, directory / "design_observations",
                _goal_runtime_module()._tile_row_overlap_intervals)
            if observations:
                evidence["observations"] = observations
                evidence["sources"].append(observations)
            design_evidence.append(evidence)
    if design_evidence:
        declared["completed_run"]["design_evidence"] = design_evidence
    # The file inventory identifies the native report but does not convey its
    # scientific statements to the output writer. Include bounded source text
    # so chemistry, screening scope, unknown bins and ranking provenance can
    # be carried into requested exports without being guessed from filenames.
    native_report = Path(run_dir) / "report.md"
    if native_report.is_file():
        report_text = native_report.read_text(encoding="utf-8", errors="replace")
        report_limit = 60000
        declared["completed_run"]["native_report"] = {
            "path": str(native_report),
            "text": report_text if len(report_text) <= report_limit else
                report_text[:report_limit // 2] + "\n[Middle omitted; read the source file for complete evidence.]\n" + report_text[-report_limit // 2:],
            "truncated": len(report_text) > report_limit,
        }
    resolved_goal = _read_json(Path(run_dir) / "artifacts/intake/structured_goal.json")
    if isinstance(resolved_goal, dict):
        chemistry = resolved_goal.get("chemistry")
        declared["completed_run"]["resolved_design_context"] = {
            "intent": resolved_goal.get("intent"),
            "target_region": resolved_goal.get("target_region"),
            "transcript_lock": resolved_goal.get("transcript_lock"),
            "chemistry": chemistry.get("recommendation") if isinstance(chemistry, dict) else chemistry,
            "candidate_selection_policy": resolved_goal.get("candidate_selection_policy"),
            "candidate_minimum_genomic_gap_nt": resolved_goal.get("candidate_minimum_genomic_gap_nt"),
            "candidate_panel_objectives": resolved_goal.get("candidate_panel_objectives"),
            "candidate_role_selection": resolved_goal.get("candidate_role_selection"),
        }
    bound_design_tasks = {entry["task_id"] for entry in design_evidence if entry.get("observations")}
    source_bound_workbooks = [str(path) for path in pending if path.suffix.lower() == ".xlsx"
                              and bindings.get(path, (None,))[0] in bound_design_tasks]
    design_catalog = None
    if source_bound_workbooks:
        from .design_workbooks import write_design_catalog
        design_catalog = write_design_catalog(declared, directory / "design_catalog.json")
        declared["completed_run"]["design_catalog"] = design_catalog
        declared["requested_design_workbooks"] = [{"path": path, "task_id": bindings[Path(path)][0]}
                                                   for path in source_bound_workbooks]
    (directory / "declared_inputs.json").write_text(json.dumps(declared, indent=2))
    result = execute_analysis_program(
        directory=directory,
        payload={"operation": "render_requested_outputs", "task_type": "sandbox_analysis",
                 "request_text": str(state.get("request") or ""), "request_envelope": envelope,
                 "declared_inputs": declared, "execution_root": str(directory),
                 "source_bound_design_workbooks": source_bound_workbooks,
                 "native_export_sources": native_sources,
                 "resource_limits": {"timeout_seconds": None}, "require_tabular_report_views": True},
        generate=_run_sandbox_analysis_sync, required_outputs=pending,
        review_program=_run_analysis_contract_review_sync,
        first_review_repair=True,
        readonly_outputs=list(dict.fromkeys(
            [path for path in requested if path not in pending]
            + [Path(path) for catalog in native_sources.values() for path in catalog.values()
               if Path(path) not in pending]
            + [Path(source["path"]) for evidence in design_evidence for source in evidence["sources"]]
            + evaluation_sources + supplied_sources
            + ([Path(design_catalog["path"])] if design_catalog else []))),
        max_attempts=3 - len(prior_attempts),
    )
    fallback_exports = []
    if not result["ok"] and len(prior_attempts) + len(result["attempts"]) >= 3:
        # A failed custom writer must not make an otherwise completed native
        # design disappear. For an unambiguous single design producer, deliver
        # its existing panel/report under the requested filenames. This is a
        # delivery fallback only: retain every failed writer attempt and let
        # scientific review assess whether the native files meet the request.
        tasks = [task for task in envelope.get("tasks") or [] if isinstance(task, dict)]
        if len(tasks) == 1 and tasks[0].get("task_type") == "design_new_asos":
            task_id = str(tasks[0].get("task_id") or "")
            catalog = native_sources.get(task_id) or _native_export_catalog(state, run_dir, task_id)
            for spec in envelope.get("final_outputs") or []:
                if not isinstance(spec, dict) or str(spec.get("task_id") or "") != task_id:
                    continue
                if str(spec.get("kind") or "") != "file" or spec.get("source_artifact"):
                    continue
                for path in _requested_output_paths(run_dir, [spec]):
                    if path not in pending:
                        continue
                    key = {".csv": "design_panel_csv", ".md": "report_md",
                           ".markdown": "report_md"}.get(path.suffix.lower())
                    source = catalog.get(key) if key else None
                    if source and Path(source).is_file():
                        fallback_exports.append(copy_native_export(Path(source), path, source_root=Path(run_dir)))
    errors = requested_artifact_errors(requested)
    fallback_complete = bool(fallback_exports) and not errors and all(
        str(path) in {item["destination"] for item in fallback_exports}
        for path in pending
    )
    receipt = {"ok": bool((result["ok"] or fallback_complete) and not errors),
               "paths": [str(path) for path in requested],
               "attempted_paths": [str(path) for path in pending],
               "native_exports": native_exports + fallback_exports,
               "native_fallback_after_writer_failure": fallback_complete,
               "execution_attempts": result["attempts"], "validation_errors": errors,
               "error": result.get("error"),
               "limitation": ("Native files delivered after custom writer failure; requested custom "
                              "content remains subject to scientific review.") if fallback_complete else None,
               "result_path": str(directory / "sandbox_result.json")}
    if receipt["ok"]:
        receipt.update(contract_sha256=contract_sha256,
                       output_sha256={str(path): requested_artifact_sha256(path) for path in requested})
    (directory / "delivery.json").write_text(json.dumps(receipt, indent=2))
    return receipt


def _write_v2_response_outputs(
    *,
    run_dir: str,
    markdown_text: str,
    response_payload: Dict[str, Any],
    response_basename: str,
    title: str,
    requested_outputs: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, str]:
    run_path = Path(run_dir)
    excel_outputs = _write_v2_excel_outputs(run_dir, response_payload, response_basename)
    if excel_outputs:
        response_payload = dict(response_payload)
        response_payload["excel_outputs"] = excel_outputs
        evaluation_payload = response_payload.get("evaluation_summary") if isinstance(response_payload.get("evaluation_summary"), dict) else None
        if isinstance(evaluation_payload, dict):
            response_payload["evaluation_summary"] = dict(evaluation_payload)
            response_payload["evaluation_summary"]["excel_outputs"] = excel_outputs
    evaluation = response_payload.get("evaluation_summary") or {}
    evidence_outputs = {}
    if isinstance(evaluation.get("provided_asos"), list):
        from .evaluation_report import write_evaluation_evidence
        evidence_outputs = write_evaluation_evidence(run_path, response_payload)
    preserve_assessment = (isinstance(evaluation.get("provided_asos"), list)
                           or response_payload.get("source_backed_reference_projection")) and bool(markdown_text.strip())
    chooser_markdown = "" if preserve_assessment else _chooser_focused_v2_markdown(
        run_dir=run_dir,
        markdown_text=markdown_text,
        response_payload=response_payload,
        response_basename=response_basename,
    )
    if chooser_markdown:
        markdown_text = chooser_markdown
        response_payload = dict(response_payload)
        response_payload["markdown"] = markdown_text
        answer_lead = _summary_markdown_answer_lead(markdown_text)
        if answer_lead:
            response_payload["answer_summary"] = answer_lead
    from .oligoai import append_report_evaluations
    markdown_text = append_report_evaluations(markdown_text, response_payload, report_dir=run_dir)
    response_payload = {**response_payload, "markdown": markdown_text}
    requested_exports = _write_requested_evaluation_exports(
        run_dir, response_payload, markdown_text, requested_outputs, evidence_outputs,
    ) if (isinstance(evaluation.get("provided_asos"), list)
          or response_payload.get("source_backed_reference_projection")) else {}
    if requested_exports:
        response_payload["requested_exports"] = requested_exports
    from .report_presentation import append_requested_downloads, link_child_report_excerpts
    if not preserve_assessment:
        markdown_text = link_child_report_excerpts(markdown_text, response_payload, run_dir)
    html_markdown_text = append_requested_downloads(markdown_text, run_dir, requested_outputs)
    # An accepted evidence-bound assessment is retained byte-for-byte in its
    # Markdown/JSON exports. Navigation can surround it in the HTML without
    # rewriting the scientific assessment or its separately packaged evidence.
    if not preserve_assessment:
        markdown_text = html_markdown_text
    response_payload = {**response_payload, 'markdown': markdown_text}
    report_md_path = _write_run_path(run_path, "report.md")
    report_html_path = _write_run_path(run_path, "report.html")
    response_json_path = _write_run_path(run_path, f"{response_basename}.json")
    response_md_path = _write_run_path(run_path, f"{response_basename}.md")
    ensure_run_parent(report_md_path)
    ensure_run_parent(report_html_path)
    ensure_run_parent(response_json_path)
    ensure_run_parent(response_md_path)
    report_md_path.write_text(markdown_text, encoding="utf-8")
    response_md_path.write_text(markdown_text, encoding="utf-8")
    response_json_path.write_text(json.dumps(response_payload, ensure_ascii=False, indent=2), encoding="utf-8")
    html_document = (
        _composite_html_document(
            title=title,
            body_markdown=html_markdown_text,
            response_payload=response_payload,
            run_dir=run_dir,
        )
        if response_basename == "composite_report"
        else _basic_html_document(title, html_markdown_text, run_dir=run_dir)
    )
    report_html_path.write_text(html_document, encoding="utf-8")
    return {
        "report_md": str(report_md_path),
        "report_html": str(report_html_path),
        "response_json": str(response_json_path),
        "response_md": str(response_md_path),
        **excel_outputs,
        **evidence_outputs,
        **requested_exports,
    }


def _store_task_artifacts(state: Dict[str, Any], task_id: str, artifacts: Dict[str, Any]) -> None:
    task_artifacts = state.get("task_artifacts")
    if not isinstance(task_artifacts, dict):
        task_artifacts = {}
        state["task_artifacts"] = task_artifacts
    entry = task_artifacts.get(task_id)
    if not isinstance(entry, dict):
        entry = {}
        task_artifacts[task_id] = entry
    entry.update(deepcopy(artifacts))


def _apply_clarification_request_to_state(
    state: Dict[str, Any],
    clarification_request: Dict[str, Any],
) -> None:
    questions = _normalize_questions_input(clarification_request.get("questions"))
    clarification = state.get("clarification")
    if not isinstance(clarification, dict):
        clarification = {"isoform_scope_confirmed": False}
        state["clarification"] = clarification
    clarification["kind"] = str(clarification_request.get("kind") or "general").strip().lower() or "general"
    clarification["reason"] = str(clarification_request.get("reason") or "").strip()
    clarification["restart_stage"] = (
        str(clarification_request.get("restart_stage") or "resolution").strip().lower() or "resolution"
    )
    clarification["requested_at"] = _timestamp()
    clarification["questions_count"] = len(questions)
    for field in ("context", "why_this_matters", "recommendation"):
        text = str(clarification_request.get(field) or "").strip()
        if text:
            clarification[field] = text
        else:
            clarification.pop(field, None)
    suggested_answers = _normalize_text_items(clarification_request.get("suggested_answers"))
    if suggested_answers:
        clarification["suggested_answers"] = suggested_answers
    else:
        clarification.pop("suggested_answers", None)


def _block_v2_task_for_clarification(
    *,
    state: Dict[str, Any],
    state_path: str,
    tool_name: str,
    run_dir: str,
    task_id: str,
    questions: List[str],
    reason: str,
    missing_fields: Optional[List[str]] = None,
    artifacts: Optional[Dict[str, Any]] = None,
    clarification_kind: str = "general",
    restart_stage: str = "intake",
    context: str = "",
    why_this_matters: str = "",
    recommendation: str = "",
    suggested_answers: Optional[List[str]] = None,
) -> Dict[str, Any]:
    normalized_questions = _normalize_questions_input(questions)
    if not normalized_questions:
        return {"status": "fatal_error", "error": "no_questions_provided"}
    normalized_suggested_answers = _normalize_text_items(suggested_answers)
    task_validation = state.get("task_validation")
    if not isinstance(task_validation, dict):
        task_validation = {}
        state["task_validation"] = task_validation
    task_payload = _task_payload_by_id(state, task_id)
    issues = _normalize_text_list(missing_fields)
    validation_entry = task_validation.get(task_id)
    if not isinstance(validation_entry, dict):
        validation_entry = {
            "task_id": task_id,
            "task_type": str(task_payload.get("task_type") or "").strip(),
            "label": str(task_payload.get("label") or task_id).strip() or task_id,
        }
        task_validation[task_id] = validation_entry
    validation_entry["status"] = "blocked"
    validation_entry["issues"] = issues
    validation_entry["missing_fields"] = issues
    validation_entry["questions"] = normalized_questions
    validation_entry["reason"] = str(reason or "task_clarification_required").strip() or "task_clarification_required"
    if normalized_suggested_answers:
        validation_entry["suggested_answers"] = normalized_suggested_answers
    else:
        validation_entry.pop("suggested_answers", None)

    task_statuses = state.get("task_statuses")
    if not isinstance(task_statuses, dict):
        task_statuses = {}
        state["task_statuses"] = task_statuses
    status_entry = task_statuses.get(task_id)
    if not isinstance(status_entry, dict):
        status_entry = {}
        task_statuses[task_id] = status_entry
    status_entry["task_type"] = str(task_payload.get("task_type") or status_entry.get("task_type") or "").strip()
    status_entry["native"] = bool(task_payload.get("native", True))
    status_entry["status"] = "blocked"
    status_entry["updated_at"] = _timestamp()

    if isinstance(artifacts, dict) and artifacts:
        _store_task_artifacts(state, task_id, artifacts)

    state["blocked_task_ids"] = [
        str(task_key)
        for task_key, payload in task_validation.items()
        if isinstance(payload, dict) and str(payload.get("status") or "").strip().lower() == "blocked"
    ]
    blocked_set = set(state["blocked_task_ids"])
    state["clarification_queue"] = [
        {
            "task_id": str(task_key),
            "label": str(payload.get("label") or payload.get("task_type") or task_key).strip(),
            "missing_fields": _normalize_text_list(payload.get("missing_fields") or payload.get("issues")),
            "questions": _normalize_questions_input(payload.get("questions")),
            "reason": str(payload.get("reason") or "task_clarification_required").strip(),
            "suggested_answers": _normalize_text_items(payload.get("suggested_answers")),
        }
        for task_key, payload in task_validation.items()
        if isinstance(payload, dict) and str(task_key) in blocked_set
    ]
    state["pending_questions"] = list(normalized_questions)
    _apply_clarification_request_to_state(
        state,
        {
            "kind": clarification_kind,
            "reason": reason,
            "restart_stage": restart_stage,
            "context": context,
            "why_this_matters": why_this_matters,
            "recommendation": recommendation,
            "suggested_answers": normalized_suggested_answers,
            "questions": normalized_questions,
        },
    )
    state["status"] = "needs_user_input"
    state["phase"] = "task_waiting_for_clarification"
    state["last_error"] = None
    state["artifacts"] = _discover_core_artifacts(run_dir)
    _mark_last_tool(state, tool_name, "ok")
    _event(state, "task_waiting_for_clarification", f"Clarification required for task {task_id}.")
    _save_state(state_path, state, snapshot_reason=f"{tool_name}_clarification_required")
    return {
        "status": "ok",
        "state_path": str(_state_path_to_obj(state_path)),
        "run_dir": run_dir,
        "task_id": task_id,
        "needs_user_input": True,
        "pending_questions": normalized_questions,
        "questions": normalized_questions,
        "reason": reason,
        "suggested_answers": normalized_suggested_answers,
        "artifacts": artifacts or {},
    }


def _block_task_for_child_clarification(
    *,
    state: Dict[str, Any],
    task_id: str,
    questions: List[str],
    reason: str,
    child_state_path: str = "",
    child_run_dir: str = "",
    clarification_kind: str = "general",
    restart_stage: str = "resolution",
    context: str = "",
    why_this_matters: str = "",
    recommendation: str = "",
    suggested_answers: Optional[List[str]] = None,
) -> None:
    normalized_questions = _normalize_questions_input(questions)
    task_statuses = state.get("task_statuses")
    if not isinstance(task_statuses, dict):
        task_statuses = {}
        state["task_statuses"] = task_statuses
    task_entry = task_statuses.get(task_id)
    if not isinstance(task_entry, dict):
        task_entry = {}
        task_statuses[task_id] = task_entry
    task_entry["status"] = "blocked"
    task_entry["updated_at"] = _timestamp()

    task_validation = state.get("task_validation")
    if not isinstance(task_validation, dict):
        task_validation = {}
        state["task_validation"] = task_validation
    validation_entry = task_validation.get(task_id)
    if not isinstance(validation_entry, dict):
        validation_entry = {"task_id": task_id}
        task_validation[task_id] = validation_entry
    validation_entry["status"] = "blocked"
    validation_entry["issues"] = ["child_design_clarification_needed"]
    validation_entry["questions"] = list(normalized_questions)
    validation_entry["reason"] = reason or "Child design run requires clarification before it can resume."

    artifact_update: Dict[str, Any] = {
        "child_state_path": str(child_state_path or "").strip() or None,
        "child_run_dir": str(child_run_dir or "").strip() or None,
        "child_pending_questions": list(normalized_questions),
        "child_status": "needs_user_input",
    }
    _store_task_artifacts(state, task_id, artifact_update)

    blocked_task_ids = [
        str(task_key)
        for task_key, payload in task_validation.items()
        if isinstance(payload, dict) and str(payload.get("status") or "").strip().lower() == "blocked"
    ]
    state["blocked_task_ids"] = blocked_task_ids
    clarification_queue = [
        deepcopy(payload)
        for task_key, payload in task_validation.items()
        if isinstance(payload, dict)
        and str(task_key or "").strip() in set(blocked_task_ids)
    ]
    for payload in clarification_queue:
        payload.setdefault("missing_fields", payload.get("issues") or [])
    state["clarification_queue"] = clarification_queue
    state["pending_questions"] = list(normalized_questions)
    _apply_clarification_request_to_state(
        state,
        {
            "kind": clarification_kind,
            "reason": reason,
            "restart_stage": restart_stage,
            "context": context,
            "why_this_matters": why_this_matters,
            "recommendation": recommendation,
            "suggested_answers": suggested_answers or [],
            "questions": normalized_questions,
        },
    )
    state["status"] = "needs_user_input"
    state["phase"] = "task_waiting_for_clarification"
    state["last_error"] = None


def _load_task_payload_by_type(state: Dict[str, Any], task_type: str, *, task_ids: Optional[Set[str]] = None) -> Dict[str, Any]:
    normalized = str(task_type or "").strip().lower()
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    for task in _task_graph_tasks(state):
        if not isinstance(task, dict):
            continue
        if str(task.get("task_type") or "").strip().lower() != normalized:
            continue
        task_id = str(task.get("task_id") or "").strip()
        if not task_id or (task_ids is not None and task_id not in task_ids):
            continue
        artifact_entry = task_artifacts.get(task_id)
        if not isinstance(artifact_entry, dict):
            if normalized == "evaluate_existing_aso_set":
                payload = _fallback_evaluate_existing_task_payload(state, task)
                if payload:
                    return payload
            continue
        json_path = artifact_entry.get("json") or artifact_entry.get("response_json")
        if not isinstance(json_path, str) or not Path(json_path).exists():
            if normalized == "evaluate_existing_aso_set":
                payload = _fallback_evaluate_existing_task_payload(state, task)
                if payload:
                    return payload
            continue
        try:
            payload = json.loads(Path(json_path).read_text(encoding="utf-8"))
        except Exception:
            if normalized == "evaluate_existing_aso_set":
                payload = _fallback_evaluate_existing_task_payload(state, task)
                if payload:
                    return payload
            continue
        if isinstance(payload, dict):
            return payload
    return {}


def _find_completed_context_payload(completed_context: Dict[str, Any], task_type: str) -> Dict[str, Any]:
    payload = completed_context.get(task_type)
    return payload if isinstance(payload, dict) else {}


def _load_task_artifact_payload(artifact_entry: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(artifact_entry, dict):
        return {}
    json_path = (
        artifact_entry.get("json")
        or artifact_entry.get("response_json")
        or artifact_entry.get("result_json")
    )
    if not isinstance(json_path, str) or not Path(json_path).exists():
        return {}
    try:
        payload = json.loads(Path(json_path).read_text(encoding="utf-8"))
    except Exception:
        return {"path": json_path}
    return payload if isinstance(payload, dict) else {"path": json_path}


def _completed_dependency_results_for_task(
    state: Dict[str, Any],
    task: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Return direct, completed upstream results in a stable execution wrapper."""

    task_id = str(task.get("task_id") or "").strip()
    dependency_ids = list(_task_depends_on(task))
    task_graph = state.get("task_graph") if isinstance(state.get("task_graph"), dict) else {}
    for edge in task_graph.get("dependencies") or []:
        if not isinstance(edge, dict):
            continue
        if str(edge.get("downstream_task_id") or "").strip() != task_id:
            continue
        upstream_id = str(edge.get("upstream_task_id") or "").strip()
        if upstream_id and upstream_id not in dependency_ids:
            dependency_ids.append(upstream_id)

    task_statuses = state.get("task_statuses") if isinstance(state.get("task_statuses"), dict) else {}
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    results: List[Dict[str, Any]] = []
    for upstream_id in dependency_ids:
        status_entry = task_statuses.get(upstream_id)
        if not isinstance(status_entry, dict) or str(status_entry.get("status") or "").strip().lower() != "completed":
            continue
        upstream_task = _task_payload_by_id(state, upstream_id)
        artifact_entry = task_artifacts.get(upstream_id)
        if not isinstance(upstream_task, dict) or not isinstance(artifact_entry, dict):
            continue
        output_payload = _load_task_artifact_payload(artifact_entry)
        if not output_payload:
            continue
        output_artifacts = {
            str(key): value
            for key, value in artifact_entry.items()
            if isinstance(value, str) and value.strip()
        }
        results.append(
            {
                "upstream_task_id": upstream_id,
                "task_type": _normalize_task_type_value(upstream_task.get("task_type")),
                "label": str(upstream_task.get("label") or "").strip(),
                "status": "completed",
                "output_payload": deepcopy(output_payload),
                "output_artifacts": output_artifacts,
            }
        )
    return results


def _report_summary_line(markdown_text: str) -> str:
    for raw_line in str(markdown_text or "").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        return line
    return ""


def _design_program_key_from_structured_goal(
    structured_goal: Optional[Dict[str, Any]],
    task_context: Optional[Dict[str, Any]] = None,
) -> str:
    goal = structured_goal if isinstance(structured_goal, dict) else {}
    context = task_context if isinstance(task_context, dict) else {}
    design_programs = goal.get("design_programs") if isinstance(goal.get("design_programs"), list) else []
    modalities = {
        str(program.get("modality") or "").strip().lower()
        for program in design_programs
        if isinstance(program, dict) and str(program.get("modality") or "").strip()
    }
    intent = str(goal.get("intent") or "").strip().lower()
    if not intent:
        intent = str((context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}).get("design_intent") or "").strip().lower()
    mechanism = str((context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}).get("mechanism") or "").strip().lower()
    if "gapmer" in modalities or intent == "knockdown":
        return "gapmer_knockdown"
    if "steric" in modalities or intent == "splice_modulation" or mechanism == "steric_blocking":
        return "splice_switching"
    return ""


def _design_chemistry_summary(structured_goal: Optional[Dict[str, Any]]) -> str:
    goal = structured_goal if isinstance(structured_goal, dict) else {}
    chemistry = goal.get("chemistry") if isinstance(goal.get("chemistry"), dict) else {}
    recommendation = chemistry.get("recommendation") if isinstance(chemistry.get("recommendation"), dict) else {}
    chemistry_name = str(recommendation.get("CHEMISTRY") or "").strip()
    platform = str(recommendation.get("platform") or "").strip()
    length = recommendation.get("length")
    parts: List[str] = []
    if platform:
        parts.append(platform)
    if chemistry_name and chemistry_name.lower() not in {part.lower() for part in parts}:
        parts.append(chemistry_name)
    if isinstance(length, int) and length > 0:
        parts.append(f"{length} nt")
    return ", ".join(parts)


def _child_design_task_completed(artifact_entry: Dict[str, Any]) -> bool:
    if not isinstance(artifact_entry, dict):
        return False
    child_run_dir = str(artifact_entry.get("child_run_dir") or "").strip()
    if child_run_dir:
        report_md = _run_path(child_run_dir, "report.md")
        report_html = _run_path(child_run_dir, "report.html")
        if report_md.exists() and report_html.exists():
            return True
    child_state_path = str(artifact_entry.get("child_state_path") or "").strip()
    if child_state_path and Path(child_state_path).exists():
        try:
            child_state = json.loads(Path(child_state_path).read_text(encoding="utf-8"))
        except Exception:
            child_state = {}
        if isinstance(child_state, dict) and str(child_state.get("status") or "").strip().lower() == "completed":
            return True
    return False


def _fallback_design_task_payload(task: Dict[str, Any], artifact_entry: Dict[str, Any]) -> Dict[str, Any]:
    if not _child_design_task_completed(artifact_entry):
        return {}
    child_run_dir = str(artifact_entry.get("child_run_dir") or "").strip()
    if not child_run_dir:
        return {}
    task_context = deepcopy(task.get("context") if isinstance(task.get("context"), dict) else {})
    child_goal_context = _goal_payload_context(child_run_dir)
    child_structured_goal = (
        child_goal_context.get("structured_goal")
        if isinstance(child_goal_context.get("structured_goal"), dict)
        else {}
    )
    child_request_envelope = (
        child_goal_context.get("request_envelope")
        if isinstance(child_goal_context.get("request_envelope"), dict)
        else {}
    )
    child_artifacts = _discover_core_artifacts(child_run_dir)
    child_integrity = _extract_pipeline_integrity(
        child_run_dir,
        child_artifacts,
        skip_router=not _resolve_run_splice_router(child_run_dir),
    )
    if child_integrity.get("ok") is not True:
        # Recovery must obey the same delivery gate as ordinary child execution.
        # Report files alone do not establish a completed design task.
        return {}
    report_md_path = _run_path(child_run_dir, "report.md")
    report_excerpt = _artifact_excerpt(report_md_path, max_chars=2400) if report_md_path.exists() else ""
    child_status = str(artifact_entry.get("child_status") or "").strip() or "run_complete"
    child_state_path = str(artifact_entry.get("child_state_path") or "").strip()
    if child_state_path and Path(child_state_path).exists():
        try:
            child_state = json.loads(Path(child_state_path).read_text(encoding="utf-8"))
        except Exception:
            child_state = {}
        if isinstance(child_state, dict):
            child_status = str(child_state.get("status") or child_status).strip()
    generated_artifacts = _emit_v2_generated_design_artifacts(child_run_dir)
    design_outcome = _classify_design_outcome(
        child_run_dir=child_run_dir,
        task_context=task_context,
        child_status=child_status,
        generated_artifacts=generated_artifacts,
    )
    return {
        "task_type": "design_new_asos",
        "task_id": str(task.get("task_id") or "").strip(),
        "task_label": str(task.get("label") or "").strip(),
        "task_context": task_context,
        "child_status": child_status,
        "child_run_dir": child_run_dir,
        "child_state_path": child_state_path or None,
        "child_structured_goal": deepcopy(child_structured_goal),
        "child_request_envelope": deepcopy(child_request_envelope),
        "child_artifacts": deepcopy(child_artifacts),
        "child_integrity": deepcopy(child_integrity),
        "generated_artifacts": deepcopy(generated_artifacts),
        "design_outcome": deepcopy(design_outcome),
        "report_excerpt": report_excerpt,
    }


def _fallback_evaluate_existing_task_payload(
    state: Dict[str, Any],
    task: Dict[str, Any],
) -> Dict[str, Any]:
    task_id = str(task.get("task_id") or "").strip()
    task_type = str(task.get("task_type") or "").strip().lower()
    if task_type != "evaluate_existing_aso_set" or not task_id:
        return {}
    task_statuses = state.get("task_statuses") if isinstance(state.get("task_statuses"), dict) else {}
    task_entry = task_statuses.get(task_id) if isinstance(task_statuses.get(task_id), dict) else {}
    if str(task_entry.get("status") or "").strip().lower() != "completed":
        return {}
    request_envelope = state.get("request_envelope") if isinstance(state.get("request_envelope"), dict) else {}
    run_dir = str(state.get("run_dir") or "").strip()
    if not request_envelope or not run_dir:
        return {}
    task_request_envelope = _task_scoped_request_envelope(request_envelope, task)
    try:
        payload = _evaluate_existing_asos_payload(
            state=state,
            request_envelope=task_request_envelope,
            run_dir=run_dir,
            task_id=task_id,
        )
    except Exception:
        return {}
    if not isinstance(payload, dict) or payload.get("error"):
        return {}
    return payload


def _collect_completed_task_outputs(
    state: Dict[str, Any],
    *,
    exclude_task_id: str = "",
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    completed_context: Dict[str, Any] = {}
    completed_tasks: List[Dict[str, Any]] = []
    single_by_type: Dict[str, Dict[str, Any]] = {}
    type_counts: Dict[str, int] = {}
    excluded = str(exclude_task_id or "").strip()
    for task in _task_graph_tasks(state):
        other_task_id = str(task.get("task_id") or "").strip()
        other_task_type = str(task.get("task_type") or "").strip().lower()
        if not other_task_id or other_task_id == excluded:
            continue
        artifact_entry = task_artifacts.get(other_task_id)
        if not isinstance(artifact_entry, dict):
            continue
        payload = _load_task_artifact_payload(artifact_entry)
        if other_task_type == "design_new_asos":
            refreshed_design_payload = _fallback_design_task_payload(task, artifact_entry)
            if refreshed_design_payload:
                if not isinstance(payload, dict):
                    payload = {}
                payload.update(refreshed_design_payload)
        elif not payload and other_task_type == "evaluate_existing_aso_set":
            payload = _fallback_evaluate_existing_task_payload(state, task)
        if not isinstance(payload, dict) or not payload:
            continue
        task_record = {
            "task_id": other_task_id,
            "task_type": other_task_type,
            "label": str(task.get("label") or "").strip(),
            "context": deepcopy(task.get("context") if isinstance(task.get("context"), dict) else {}),
            "payload": deepcopy(payload),
        }
        completed_tasks.append(task_record)
        completed_context[other_task_id] = payload
        type_counts[other_task_type] = int(type_counts.get(other_task_type) or 0) + 1
        single_by_type[other_task_type] = payload
    for task_type, count in type_counts.items():
        if count == 1 and isinstance(single_by_type.get(task_type), dict):
            completed_context[task_type] = single_by_type[task_type]
    return completed_context, completed_tasks


def _task_payloads_by_type(completed_tasks: List[Dict[str, Any]], task_type: str) -> List[Dict[str, Any]]:
    normalized = str(task_type or "").strip().lower()
    payloads: List[Dict[str, Any]] = []
    for item in completed_tasks:
        if not isinstance(item, dict):
            continue
        if str(item.get("task_type") or "").strip().lower() != normalized:
            continue
        payload = item.get("payload")
        if isinstance(payload, dict):
            payload_copy = deepcopy(payload)
            payload_copy.setdefault("task_id", item.get("task_id"))
            payload_copy.setdefault("task_label", item.get("label"))
            payloads.append(payload_copy)
    return payloads


def _design_program_key_from_run_dir(run_dir: str) -> str:
    run_dir_text = str(run_dir or "").strip()
    if not run_dir_text:
        return ""
    context = _goal_payload_context(run_dir_text)
    structured_goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
    return _design_program_key_from_structured_goal(structured_goal)


def _sequence_row_lookup(rows: Any) -> Dict[str, Dict[str, Any]]:
    lookup: Dict[str, Dict[str, Any]] = {}
    if not isinstance(rows, list):
        return lookup
    for row in rows:
        if not isinstance(row, dict):
            continue
        key = str(row.get("sequence") or row.get("comparison_sequence") or row.get("raw_sequence") or "").strip().upper()
        if key and key not in lookup:
            lookup[key] = row
    return lookup


def _build_deterministic_question_response(
    request_text: str,
    request_summary: str,
    completed_tasks: List[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    # A question requires its own scoped assessment. Do not substitute a fixed
    # chemistry answer based on keywords or a particular pair of modalities.
    # The caller uses the normal evidence-bound workbench response path.
    return None


def _design_outcome_summary_counts(design_payloads: List[Dict[str, Any]]) -> Dict[str, int]:
    counts: Dict[str, int] = {
        "completed_with_candidates": 0,
        "completed_no_candidates": 0,
        "completed_missing_required_evidence": 0,
        "skipped": 0,
        "failed": 0,
        "unknown": 0,
    }
    for payload in design_payloads:
        outcome = payload.get("design_outcome") if isinstance(payload.get("design_outcome"), dict) else {}
        status = str(outcome.get("outcome_status") or "unknown").strip()
        counts[status if status in counts else "unknown"] = int(counts.get(status if status in counts else "unknown") or 0) + 1
    return counts


def _design_outputs_are_partial(design_payloads: List[Dict[str, Any]]) -> bool:
    complete_statuses = {"completed_with_candidates", "completed_no_candidates"}
    for payload in design_payloads:
        outcome = payload.get("design_outcome") if isinstance(payload.get("design_outcome"), dict) else {}
        if str(outcome.get("outcome_status") or "").strip() not in complete_statuses:
            return True
    return False


def _comparison_payload_is_generated_set_overlap(payload: Dict[str, Any]) -> bool:
    if not isinstance(payload, dict):
        return False
    mode = str(payload.get("comparison_mode") or "").strip().lower()
    if mode not in {"generated_set_exact_sequence_overlap", "multi_set_exact_sequence_overlap"}:
        return False
    sets = payload.get("sets") if isinstance(payload.get("sets"), list) else []
    if sets:
        return all(str(item.get("source_type") or "").strip().lower() == "generated" for item in sets if isinstance(item, dict))
    for key in ("set_a", "set_b"):
        set_payload = payload.get(key) if isinstance(payload.get(key), dict) else {}
        if set_payload and str(set_payload.get("source_type") or "").strip().lower() != "generated":
            return False
    return not bool(payload.get("provided_count"))


def _comparison_payload_is_sequence_set_overlap(payload: Dict[str, Any]) -> bool:
    if not isinstance(payload, dict):
        return False
    mode = str(payload.get("comparison_mode") or "").strip().lower()
    if mode == "comparison_unavailable":
        return True
    if mode not in {"generated_set_exact_sequence_overlap", "multi_set_exact_sequence_overlap"}:
        return False
    if isinstance(payload.get("sets"), list) and payload.get("sets"):
        return True
    return isinstance(payload.get("set_a"), dict) and isinstance(payload.get("set_b"), dict)


def _generated_set_comparison_overlap_count(payload: Dict[str, Any]) -> int:
    if not isinstance(payload, dict):
        return 0
    mode = str(payload.get("comparison_mode") or "").strip().lower()
    if mode == "generated_set_exact_sequence_overlap":
        return int(payload.get("overlap_count") or payload.get("shared_count") or 0)
    pairwise = payload.get("pairwise_overlaps") if isinstance(payload.get("pairwise_overlaps"), list) else []
    total = 0
    for item in pairwise:
        if isinstance(item, dict):
            total += int(item.get("shared_count") or 0)
    return total


def _generated_set_comparison_summary_lines(payload: Dict[str, Any]) -> List[str]:
    label = str(payload.get("task_label") or payload.get("task_id") or "comparison task").strip()
    prefix = f"- {label}: " if label else "- "
    mode = str(payload.get("comparison_mode") or "").strip().lower()
    if mode == "comparison_unavailable":
        reason = str(payload.get("reason") or "fewer than two sequence-bearing ASO sets were available").strip()
        loaded = payload.get("loaded_sources") if isinstance(payload.get("loaded_sources"), list) else []
        unavailable = payload.get("unavailable_sources") if isinstance(payload.get("unavailable_sources"), list) else []
        loaded_bits = [
            f"{item.get('label') or item.get('set_id')} ({int(item.get('count') or 0)} sequence(s))"
            for item in loaded
            if isinstance(item, dict)
        ]
        unavailable_bits = [
            f"{item.get('label') or item.get('source_task_id')}: {item.get('reason') or item.get('outcome_status') or 'unavailable'}"
            for item in unavailable
            if isinstance(item, dict)
        ]
        line = f"{prefix}comparison unavailable because {reason}."
        if loaded_bits:
            line += " Loaded: " + "; ".join(loaded_bits) + "."
        if unavailable_bits:
            line += " Unavailable: " + "; ".join(unavailable_bits) + "."
        return [line]
    if mode == "generated_set_exact_sequence_overlap":
        set_a = payload.get("set_a") if isinstance(payload.get("set_a"), dict) else {}
        set_b = payload.get("set_b") if isinstance(payload.get("set_b"), dict) else {}
        set_a_label = str(set_a.get("label") or set_a.get("set_id") or "set A").strip()
        set_b_label = str(set_b.get("label") or set_b.get("set_id") or "set B").strip()
        set_a_count = int(set_a.get("count") or 0)
        set_b_count = int(set_b.get("count") or 0)
        overlap_count = int(payload.get("overlap_count") or 0)
        set_a_specific_count = int(payload.get("set_a_specific_count") or 0)
        set_b_specific_count = int(payload.get("set_b_specific_count") or 0)
        return [
            (
                f"{prefix}compared `{set_a_label}` ({set_a_count} sequence(s)) vs "
                f"`{set_b_label}` ({set_b_count} sequence(s)); exact shared sequences: "
                f"**{overlap_count}**; set-specific counts: {set_a_specific_count} and {set_b_specific_count}."
            )
        ]
    pairwise = payload.get("pairwise_overlaps") if isinstance(payload.get("pairwise_overlaps"), list) else []
    lines = [f"{prefix}compared {int(payload.get('set_count') or 0)} ASO set(s)."]
    for item in pairwise[:12]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- {item.get('set_a_label') or item.get('set_a_id')} vs "
            f"{item.get('set_b_label') or item.get('set_b_id')}: "
            f"**{int(item.get('shared_count') or 0)}** exact shared sequence(s)."
        )
    return lines


def _build_deterministic_composite_response(
    request_envelope: Dict[str, Any],
    completed_context: Dict[str, Any],
    completed_tasks: Optional[List[Dict[str, Any]]] = None,
    blocked_tasks: Optional[List[Dict[str, Any]]] = None,
) -> Optional[Dict[str, Any]]:
    completed_task_list = completed_tasks if isinstance(completed_tasks, list) else []
    from .reference_report_projection import metric_evaluation_response
    reference_response = metric_evaluation_response(completed_task_list, blocked_tasks or [], request_envelope)
    if reference_response:
        return reference_response
    comparison_payloads = _task_payloads_by_type(completed_task_list, "compare_aso_sets")
    contracted = [payload for payload in comparison_payloads
                  if isinstance(payload.get("pooled_ranking_contract"), dict)]
    if len(contracted) == 1 and len(comparison_payloads) == 1 and not blocked_tasks:
        # The comparison table and narrative share one deterministic result.
        # Free-form synthesis must not reinterpret a user-specified rank rule.
        from .pooled_report import render_pooled_report
        comparison = contracted[0]
        rows = comparison.get("pooled_ranked_observations") or []
        contract = comparison["pooled_ranking_contract"]
        markdown = render_pooled_report(rows, contract)
        return {
            "answer_summary": f"Ranked {sum(bool(row.get('eligible')) for row in rows)} of {len(rows)} pooled ASO observations.",
            "markdown": markdown,
            "assumptions": [],
            "limitations": ["Sequence-metric rank is not an efficacy prediction."],
            "evidence_refs": [str(item.get("artifact_path")) for item in comparison.get("sets") or []
                              if item.get("artifact_path")],
            "suggested_followups": [],
            "pooled_ranking_contract": deepcopy(contract),
            "pooled_ranked_observations": deepcopy(rows),
        }
    filter_trace_payloads = _task_payloads_by_type(completed_task_list, "trace_filter_decisions")
    evaluation_payload = _find_completed_context_payload(completed_context, "evaluate_existing_aso_set")
    design_payloads: List[Dict[str, Any]] = []
    seen_design_keys: Set[str] = set()
    for payload in _task_payloads_by_type(completed_task_list, "design_new_asos"):
        design_key = str(payload.get("child_run_dir") or payload.get("task_id") or "").strip()
        if not design_key or design_key in seen_design_keys:
            continue
        seen_design_keys.add(design_key)
        design_payloads.append(payload)
    # A completed comparison of distinct submitted physical sets already has a
    # source-backed per-molecule response. Do not wrap it in the older
    # supplied-versus-generated summary, whose counts can describe only one
    # upstream evaluation task and imply a generated set the user never asked for.
    if (not design_payloads and not filter_trace_payloads and not blocked_tasks
            and len(comparison_payloads) == 1
            and all(str(task.get("task_type") or "").strip().lower()
                    in {"evaluate_existing_aso_set", "compare_aso_sets"}
                    for task in completed_task_list if isinstance(task, dict))):
        assessment = comparison_payloads[0].get("comparison_assessment") or {}
        if (isinstance(assessment, dict) and isinstance(assessment.get("submitted_set_evidence"), list)
                and assessment["submitted_set_evidence"] and assessment.get("markdown")):
            return {key: deepcopy(assessment.get(key)) for key in (
                "answer_summary", "markdown", "assumptions", "limitations", "evidence_refs",
                "suggested_followups", "submitted_set_evidence")}
    other_completed_work = any(
        str(task.get("task_type") or "").strip().lower() != "design_new_asos"
        for task in completed_task_list
        if isinstance(task, dict)
    )
    if not comparison_payloads and not filter_trace_payloads:
        if not design_payloads:
            return None
        # A design-only summary drops completed analyses in a mixed request.
        # Keep the generic composition path responsible for every task result.
        if other_completed_work:
            return None
        markdown_lines: List[str] = ["## Designed Runs"]
        evidence_refs: List[str] = []
        outcome_summaries: List[Dict[str, Any]] = []
        for payload in design_payloads:
            label = str(payload.get("task_label") or payload.get("task_id") or "design task").strip()
            child_run_dir = str(payload.get("child_run_dir") or "").strip()
            task_context = payload.get("task_context") if isinstance(payload.get("task_context"), dict) else {}
            child_structured_goal = payload.get("child_structured_goal") if isinstance(payload.get("child_structured_goal"), dict) else {}
            gene = str(child_structured_goal.get("gene_symbol") or child_structured_goal.get("gene_id") or task_context.get("gene_symbol") or "").strip()
            species = str(child_structured_goal.get("species") or task_context.get("species") or "").strip()
            scope_bits = [bit for bit in (gene, species) if bit]
            scope_text = f" ({' / '.join(scope_bits)})" if scope_bits else ""
            outcome = payload.get("design_outcome") if isinstance(payload.get("design_outcome"), dict) else {}
            outcome_status = str(outcome.get("outcome_status") or "unknown").strip()
            candidate_count = int(outcome.get("candidate_count") or 0)
            unique_sequence_count = int(outcome.get("unique_sequence_count") or 0)
            missing_evidence = outcome.get("missing_required_evidence") if isinstance(outcome.get("missing_required_evidence"), list) else []
            no_candidate_reason = str(outcome.get("no_candidate_reason") or "").strip()
            failure_reason = str(outcome.get("failure_reason") or "").strip()
            line = (
                f"- {label}{scope_text}: {outcome_status}; "
                f"{candidate_count} candidate row(s), {unique_sequence_count} unique sequence(s)"
            )
            if missing_evidence:
                line += f"; missing evidence: {', '.join(str(item) for item in missing_evidence)}"
            if no_candidate_reason:
                line += f"; reason: {no_candidate_reason}"
            if failure_reason:
                line += f"; failure: {failure_reason}"
            if child_run_dir:
                line += f"; child run `{child_run_dir}`"
            markdown_lines.append(line + ".")
            outcome_summaries.append(
                {
                    "task_id": payload.get("task_id"),
                    "label": label,
                    "gene": gene,
                    "child_run_dir": child_run_dir,
                    "design_outcome": deepcopy(outcome),
                }
            )
            if child_run_dir and child_run_dir not in evidence_refs:
                evidence_refs.append(child_run_dir)
        blocked_entries = blocked_tasks if isinstance(blocked_tasks, list) else []
        if blocked_entries:
            markdown_lines.extend(["", "## Still Blocked"])
            for item in blocked_entries:
                if not isinstance(item, dict):
                    continue
                label = str(item.get("label") or item.get("task_id") or "task").strip()
                reason = str(item.get("reason") or "additional context required").strip()
                questions = item.get("questions") if isinstance(item.get("questions"), list) else []
                question_text = f" Question: {questions[0]}" if questions else ""
                markdown_lines.append(f"- {label}: {reason}.{question_text}")
        counts = _design_outcome_summary_counts(design_payloads)
        answer_parts = [
            f"{counts.get('completed_with_candidates', 0)} design run(s) produced candidates",
            f"{counts.get('completed_no_candidates', 0)} produced no candidates",
            f"{counts.get('completed_missing_required_evidence', 0)} are missing required evidence",
            f"{counts.get('skipped', 0)} were skipped",
            f"{counts.get('failed', 0)} failed",
        ]
        if blocked_entries:
            answer_parts.append(f"{len(blocked_entries)} task(s) remain blocked")
        answer_summary = "; ".join(answer_parts) + "."
        limitations: List[str] = []
        if blocked_entries:
            limitations.append("Some tasks remain blocked pending clarification.")
        if counts.get("completed_no_candidates"):
            limitations.append("Some completed child runs produced no ASO candidates.")
        if counts.get("completed_missing_required_evidence"):
            limitations.append("Some candidate-producing child runs are missing required evidence.")
        if counts.get("skipped"):
            limitations.append("Some child design runs were skipped before candidate generation.")
        if counts.get("failed"):
            limitations.append("Some child design runs failed before completing candidate generation.")
        return {
            "answer_summary": answer_summary,
            "markdown": "\n".join(markdown_lines).strip(),
            "assumptions": [
                "Each design_new_asos task executes as its own child design run and is summarized at the parent request level.",
            ],
            "limitations": limitations,
            "evidence_refs": evidence_refs[:12],
            "suggested_followups": [],
            "deterministic_summary": {
                "design_task_count": len(design_payloads),
                "design_outcome_counts": counts,
                "design_outcomes": outcome_summaries,
                "child_run_dirs": evidence_refs[:12],
            },
        }

    # Preserve every supported task's recorded result. Unsupported mixed task
    # types fall through to the existing evidence-bound workbench composer.
    supported = {"design_new_asos", "compare_aso_sets", "trace_filter_decisions", "evaluate_existing_aso_set"}
    if any(str(task.get("task_type") or "").strip().lower() not in supported
           for task in completed_task_list if isinstance(task, dict)):
        return None
    from .composite_comparison_report import compose_comparison_report
    evaluation_payloads = _task_payloads_by_type(completed_task_list, "evaluate_existing_aso_set")
    if not evaluation_payloads and evaluation_payload:
        evaluation_payloads = [evaluation_payload]
    return compose_comparison_report(
        design_payloads, comparison_payloads, filter_trace_payloads,
        evaluation_payloads, blocked_tasks if isinstance(blocked_tasks, list) else [],
    )


def _build_sandbox_declared_inputs(
    state: Dict[str, Any],
    request_envelope: Dict[str, Any],
) -> Dict[str, Any]:
    declared: Dict[str, Any] = {"artifact_refs": [], "task_artifacts": [],
        "completed_design_candidates": [],
        "provided_asos": _normalize_provided_asos(request_envelope)}
    for ref in _resolve_artifact_ref_paths(request_envelope):
        path = Path(ref).expanduser()
        if not path.is_absolute():
            path = (_repo_root() / path).resolve()
        declared["artifact_refs"].append({"path": str(path), "exists": path.exists()})
    artifact_context = _build_artifact_context(request_envelope)
    artifact_index = artifact_context.get("artifact_index", {})
    if artifact_index.get("refs"):
        declared["artifact_index"] = artifact_index
    declared["artifact_contents"] = artifact_context.get("entries", [])
    # Intake may identify supplied molecule tables separately from artifact
    # references. Show generated analysis the actual input path and columns;
    # output filenames in artifact_refs are not a substitute for source data.
    provided_files: List[Dict[str, Any]] = []
    for spec in _collect_provided_aso_file_specs(request_envelope):
        path = _provided_aso_file_path(spec)
        if path is None or any(item["path"] == str(path) for item in provided_files):
            continue
        index = _build_artifact_index_for_path(path)
        table = (index.get("tables") or [{}])[0]
        provided_files.append({
            "path": str(path),
            "name": path.name,
            "table_summary": table.get("table_summary") or {},
        })
    if provided_files:
        declared["provided_input_files"] = provided_files
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    for task in _task_graph_tasks(state):
        task_id = str(task.get("task_id") or "").strip()
        if not task_id:
            continue
        artifact_entry = task_artifacts.get(task_id)
        if not isinstance(artifact_entry, dict):
            continue
        declared["task_artifacts"].append(
            {
                "task_id": task_id,
                "task_type": str(task.get("task_type") or "").strip(),
                "artifacts": deepcopy(artifact_entry),
            }
        )
        if str(task.get("task_type") or "") == "design_new_asos":
            source = Path(str(artifact_entry.get("generated_aso_set_json") or ""))
            panel = Path(str(artifact_entry.get("design_panel_csv") or ""))
            child = Path(str(artifact_entry.get("child_run_dir") or ""))
            if (artifact_entry.get("child_status") in {"run_complete", "completed"}
                    and child.is_dir() and source.is_file() and source.resolve().is_relative_to(child.resolve())):
                source_payload = _read_json(source)
                rows = source_payload.get("rows") if isinstance(source_payload, dict) else None
                if isinstance(rows, list):
                    reference_path = child / "artifacts/intake/structured_goal.json"
                    reference_bytes = reference_path.read_bytes() if reference_path.is_file() else None
                    reference_goal = json.loads(reference_bytes) if reference_bytes is not None else {}
                    if not isinstance(reference_goal, dict):
                        raise ValueError(f"Recorded design contract must be a JSON object: {reference_path}")
                    native_report_path = child / "report.md"
                    native_report_text = native_report_path.read_text(encoding="utf-8", errors="replace") if native_report_path.is_file() else ""
                    evidence_fields = (
                        "synthesized_antisense_sequence", "target_binding_sequence", "sequence",
                        "length", "gc_fraction", "chrom", "start", "end", "strand",
                        "site_label", "selection_rank", "program_id", "source_modality",
                        "off_target_exact_count_unit", "Off_target_exact_count",
                        "Off_target_mismatch_budget", "off_target_count_status",
                        "off_target_screening_status_by_species",
                    )
                    declared["completed_design_candidates"].append({
                        "task_id": task_id,
                        "source_json_path": str(source),
                        "source_row_count": len(rows),
                        "source_field_names": list(rows[0]) if rows and isinstance(rows[0], dict) else [],
                        "rows": [
                            {field: row.get(field) for field in evidence_fields if field in row}
                            for row in rows[:100] if isinstance(row, dict)
                        ],
                        "rows_truncated": len(rows) > 100,
                        "source_csv_path": str(panel) if panel.is_file() and panel.resolve().is_relative_to(child.resolve()) else None,
                        "source_design_contract": {
                            "source_path": str(reference_path) if reference_bytes is not None else None,
                            "source_sha256": hashlib.sha256(reference_bytes).hexdigest() if reference_bytes is not None else None,
                            "structured_goal": deepcopy(reference_goal) if reference_bytes is not None else None,
                            "scope": "Recorded source-run requirements and configuration. Current analysis instructions may explicitly request different criteria; keep those separate.",
                        },
                        "reference_context": {
                            "gene_symbol": reference_goal.get("gene_symbol"),
                            "species": reference_goal.get("species"),
                            "transcript_id": reference_goal.get("transcript_id"),
                            "transcript_policy": reference_goal.get("transcript_policy"),
                        },
                        "native_report": {"path": str(native_report_path),
                            "text": native_report_text[:12000],
                            "truncated": len(native_report_text) > 12000},
                    })
    return declared


def _task_output_dir(run_dir: str, task_id: str, request_envelope: Optional[Dict[str, Any]] = None) -> Path:
    schema_version = str((request_envelope or {}).get("schema_version") or "").strip().lower()
    root_name = "v3_tasks" if schema_version == "v3" else "v2_tasks"
    path = _write_run_path(run_dir, root_name, task_id)
    path.mkdir(parents=True, exist_ok=True)
    return path


def _safe_path_component(value: Any, default: str = "item") -> str:
    text = str(value or "").strip()
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", text).strip("._-")
    return safe or default


def _child_task_run_dir(run_dir: str, task_id: str, task: Optional[Dict[str, Any]] = None) -> str:
    root = Path(run_dir) / "child_runs"
    task_payload = task if isinstance(task, dict) else {}
    task_id_safe = _safe_path_component(task_id, "task")
    label_safe = _safe_path_component(task_payload.get("label") or "", "")
    if label_safe and label_safe.lower() != task_id_safe.lower():
        dir_name = f"{task_id_safe}_{label_safe[:24]}".rstrip("_")
    else:
        dir_name = task_id_safe
    path = root / dir_name
    path.mkdir(parents=True, exist_ok=True)
    return str(path)


def _find_agentic_state_for_run_dir(run_dir: str) -> Optional[str]:
    run_dir_text = str(run_dir or "").strip()
    if not run_dir_text:
        return None
    candidates: List[Path] = []
    run_path = Path(run_dir_text).expanduser()
    try:
        if run_path.is_dir():
            candidates.extend(sorted(run_path.glob("agentic_*/run_state.json"), reverse=True))
            controller_dir = run_path / ARTIFACTS_DIRNAME / CONTROLLER_DIRNAME
            if controller_dir.exists():
                candidates.extend(sorted(controller_dir.glob("agentic_*/run_state.json"), reverse=True))
            nested_alias = _run_path(run_path, "agentic_state", "run_state.json")
            if nested_alias.exists():
                candidates.append(nested_alias)
    except Exception:
        pass
    try:
        candidates.extend(sorted((managed_runs_root()).glob("agentic_*/run_state.json"), reverse=True))
    except Exception:
        pass
    seen: Set[str] = set()
    for state_path in candidates:
        resolved = str(state_path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = _read_json(state_path)
        except Exception:
            continue
        payload_run_dir = str(payload.get("run_dir") or "").strip() if isinstance(payload, dict) else ""
        if payload_run_dir == run_dir_text:
            return resolved
        try:
            state_path.resolve().relative_to(run_path.resolve())
            return resolved
        except Exception:
            continue
    return None


def _task_graph_tasks(state: Dict[str, Any]) -> List[Dict[str, Any]]:
    task_graph = state.get("task_graph") if isinstance(state.get("task_graph"), dict) else {}
    tasks = task_graph.get("tasks") if isinstance(task_graph.get("tasks"), list) else []
    return [task for task in tasks if isinstance(task, dict)]


def _has_task_type(state: Dict[str, Any], task_type: str) -> bool:
    normalized = str(task_type or "").strip().lower()
    return any(str(task.get("task_type") or "").strip().lower() == normalized for task in _task_graph_tasks(state))


def _incomplete_task_ids(state: Dict[str, Any]) -> List[str]:
    incomplete: List[str] = []
    current_task_id = str(state.get("current_task_id") or "").strip()
    for task in _task_graph_tasks(state):
        task_id = str(task.get("task_id") or "").strip()
        if not task_id:
            continue
        task_type = str(task.get("task_type") or "").strip().lower()
        if task_id == current_task_id and _task_is_logically_complete(state, task_type):
            continue
        entry = (state.get("task_statuses") or {}).get(task_id) if isinstance(state.get("task_statuses"), dict) else {}
        status = str(entry.get("status") or "").strip().lower() if isinstance(entry, dict) else ""
        if status not in {"completed", "invalid"}:
            incomplete.append(task_id)
    return incomplete


def _should_finalize_current_task(state: Dict[str, Any], current_task_id: str) -> bool:
    remaining = [task_id for task_id in _incomplete_task_ids(state) if task_id != str(current_task_id or "").strip()]
    return not remaining


def _candidate_run_dirs_for_task(state: Dict[str, Any], request_envelope: Dict[str, Any]) -> List[str]:
    candidates: List[str] = []
    explicit_refs = _resolve_artifact_ref_paths(request_envelope)
    task_context = request_envelope.get("task_context") if isinstance(request_envelope.get("task_context"), dict) else {}
    for ref in explicit_refs:
        path = Path(ref).expanduser()
        if not path.is_absolute():
            path = (_repo_root() / path).resolve()
        if path.is_dir():
            candidates.append(str(path))
        elif path.parent.exists():
            candidates.append(str(path.parent))
    current_task_id = str(state.get("current_task_id") or request_envelope.get("active_task_id") or "").strip()
    dependency_task_ids: List[str] = []
    current_task = _task_payload_by_id(state, current_task_id) if current_task_id else {}
    if current_task:
        dependency_task_ids.extend(_task_depends_on(current_task))
    dependency_candidates = _collect_task_artifact_run_dirs(
        state,
        task_ids=list(dict.fromkeys(dependency_task_ids)),
        target_context=task_context,
    )
    if dependency_candidates:
        candidates.extend(dependency_candidates)
    elif not explicit_refs:
        upstream_design_ids = [
            str(task.get("task_id") or "").strip()
            for task in _task_graph_tasks(state)
            if str(task.get("task_type") or "").strip().lower() in {"design_new_asos", "analyze_artifact"}
            and str(task.get("task_id") or "").strip()
            and str(task.get("task_id") or "").strip() != current_task_id
        ]
        candidates.extend(
            _collect_task_artifact_run_dirs(
                state,
                task_ids=upstream_design_ids,
                target_context=task_context,
            )
        )
    run_dir = state.get("run_dir")
    if isinstance(run_dir, str) and run_dir.strip() and not explicit_refs and not candidates:
        candidates.append(run_dir.strip())
    deduped: List[str] = []
    seen: Set[str] = set()
    for candidate in candidates:
        if candidate not in seen:
            seen.add(candidate)
            deduped.append(candidate)
    return deduped


def _normalize_eval_site_kind(value: Any) -> Optional[str]:
    text = str(value or "").strip().lower()
    if not text:
        return None
    if text in {"splice", "splicing", "splice_site", "junction", "region", "exon", "intron"}:
        return None
    if "accept" in text or text in {"3ss", "three_prime_splice_site", "3_prime_splice_site"}:
        return "acceptor"
    if "don" in text or text in {"5ss", "five_prime_splice_site", "5_prime_splice_site"}:
        return "donor"
    return text


def _stringify_request_context(value: Any) -> Optional[str]:
    if value in (None, "", [], {}):
        return None
    if isinstance(value, str):
        text = value.strip()
        return text or None
    if isinstance(value, dict):
        bits: List[str] = []
        for key, raw in value.items():
            rendered = _stringify_request_context(raw)
            if not rendered:
                continue
            label = str(key or "").strip().replace("_", " ")
            bits.append(f"{label}: {rendered}" if label else rendered)
        if bits:
            return "; ".join(bits)
    if isinstance(value, list):
        bits = [rendered for rendered in (_stringify_request_context(item) for item in value) if rendered]
        if bits:
            return "; ".join(bits)
    text = str(value).strip()
    return text or None


def _transcript_entry_strand_char(transcript_entry: Dict[str, Any]) -> str:
    raw = transcript_entry.get("strand")
    if raw is None and isinstance(transcript_entry.get("metadata"), dict):
        raw = transcript_entry["metadata"].get("strand")
    text = str(raw or "").strip()
    return "-" if text in {"-", "-1"} else "+"


def _transcript_entry_exons(transcript_entry: Dict[str, Any]) -> List[Dict[str, Any]]:
    exons_tx = transcript_entry.get("exons_tx") if isinstance(transcript_entry.get("exons_tx"), list) else []

    def _sort_key(exon: Dict[str, Any]) -> Tuple[int, int]:
        try:
            return (int(exon.get("index")), 0)
        except Exception:
            pass
        try:
            start = int(exon.get("start"))
            end = int(exon.get("end"))
            return (min(start, end), 1)
        except Exception:
            return (10**12, 2)

    return [dict(exon) for exon in sorted((exon for exon in exons_tx if isinstance(exon, dict)), key=_sort_key)]


def _transcript_locus_descriptor(
    transcript_entry: Dict[str, Any],
    *,
    isoform_label: Optional[str] = None,
) -> Dict[str, Any]:
    if not isinstance(transcript_entry, dict):
        return {}
    exons = _transcript_entry_exons(transcript_entry)
    if not exons:
        return {}
    coords: List[int] = []
    chrom = str(
        transcript_entry.get("chrom")
        or transcript_entry.get("seq_region_name")
        or transcript_entry.get("metadata", {}).get("seq_region_name")
        or exons[0].get("seq_region_name")
        or ""
    ).strip()
    for exon in exons:
        try:
            coords.extend([int(exon.get("start")), int(exon.get("end"))])
        except Exception:
            continue
    if not coords or not chrom:
        return {}
    locus_start = min(coords)
    locus_end = max(coords)
    if locus_end < locus_start:
        locus_start, locus_end = locus_end, locus_start
    transcript_id = str(
        transcript_entry.get("transcript_id")
        or transcript_entry.get("id")
        or transcript_entry.get("metadata", {}).get("id")
        or isoform_label
        or ""
    ).strip()
    return {
        "isoform_label": str(isoform_label or transcript_id or "").strip() or None,
        "transcript_id": transcript_id or None,
        "chrom": chrom,
        "strand": _transcript_entry_strand_char(transcript_entry),
        "locus_start": int(locus_start),
        "locus_end": int(locus_end),
        "locus_length": int(locus_end - locus_start + 1),
        "exons": exons,
    }


def _normalize_evaluation_targets(value: Any) -> List[Dict[str, Any]]:
    items = value if isinstance(value, list) else [value] if isinstance(value, dict) else []
    normalized: List[Dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        target: Dict[str, Any] = {}
        for field in (
            "label",
            "gene_symbol",
            "transcript_id",
            "isoform_label",
            "desired_delta",
            "desired_effect",
            "desired_splice_effect",
            "target_type",
            "objective_type",
            "chrom",
            "strand",
            "coordinate_system",
            "exon_numbering_reference_transcript_id",
            "exon_numbering_transcript_id",
            "reference_transcript_id",
        ):
            text = str(item.get(field) or "").strip()
            if text:
                target[field] = text
        site_kind = _normalize_eval_site_kind(item.get("site_kind"))
        if site_kind:
            target["site_kind"] = site_kind
        raw_exon_label = item.get("exon_label")
        parsed_exon_label = _coerce_exon_label_int(raw_exon_label)
        if parsed_exon_label is not None:
            target["exon_label"] = parsed_exon_label
        elif isinstance(raw_exon_label, str) and raw_exon_label.strip():
            # Named features remain intact; a length or a custom label is not
            # an exon ordinal and must not be silently converted into one.
            target["exon_label"] = raw_exon_label.strip()
        for field in ("start", "end", "position", "exon_index"):
            raw = item.get(field)
            try:
                if raw is not None and str(raw).strip():
                    target[field] = int(raw)
            except Exception:
                continue
        window = item.get("splice_relative_window")
        if isinstance(window, dict):
            # This is a separate coordinate frame, not an absolute start/end pair.
            target["splice_relative_window"] = deepcopy(window)
        if target:
            normalized.append(target)
    return normalized


def _normalized_splice_effect(value: Any) -> str:
    text = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if text in {
        "skip",
        "skipping",
        "skipped",
        "exclude",
        "excluded",
        "exclusion",
        "decrease_inclusion",
        "decrease_exon_inclusion",
        "reduce_inclusion",
        "reduce_exon_inclusion",
        "increase_skipping",
        "promote_skipping",
        "exon_skipping",
    }:
        return "skipping"
    if text in {
        "include",
        "included",
        "inclusion",
        "retain",
        "retained",
        "retention",
        "increase_inclusion",
        "increase_exon_inclusion",
        "promote_inclusion",
        "exon_inclusion",
    }:
        return "inclusion"
    return ""


def _merge_ordered_exon_target(
    ordered_targets: List[Dict[str, Any]],
    target_index: Dict[int, int],
    exon_label: Any,
    desired_effect: Any = None,
) -> None:
    exon_int = _coerce_exon_label_int(exon_label)
    if exon_int is None:
        return
    effect = _normalized_splice_effect(desired_effect)
    existing_idx = target_index.get(exon_int)
    if existing_idx is None:
        entry: Dict[str, Any] = {"exon_label": exon_int}
        if effect:
            entry["desired_effect"] = effect
        target_index[exon_int] = len(ordered_targets)
        ordered_targets.append(entry)
        return
    existing = ordered_targets[existing_idx]
    existing_effect = _normalized_splice_effect(existing.get("desired_effect"))
    if not existing_effect and effect:
        existing["desired_effect"] = effect
    elif existing_effect and effect and existing_effect != effect:
        existing.pop("desired_effect", None)


def _collect_structured_exon_targets(
    structured_goal: Any,
    task_context: Any = None,
) -> List[Dict[str, Any]]:
    ordered_targets: List[Dict[str, Any]] = []
    target_index: Dict[int, int] = {}

    def _region_constraint_exon_label(entry: Any) -> Optional[int]:
        if not isinstance(entry, dict):
            return None
        hint = str(
            entry.get("source_type")
            or entry.get("constraint_type")
            or entry.get("constraint_kind")
            or entry.get("type")
            or entry.get("kind")
            or ""
        ).strip().lower().replace("-", "_").replace(" ", "_")
        exon_hint = hint in {
            "exon",
            "exons",
            "target_exon",
            "target_exons",
            "transcript_exon",
            "exon_region",
            "exonic_region",
            "exon_constraint",
        }
        containers = [entry]
        for nested_key in ("region", "target_region", "region_definition", "target"):
            nested = entry.get(nested_key)
            if isinstance(nested, dict):
                containers.append(nested)
        for container in containers:
            for key in (
                "exon_label",
                "target_exon",
                "exon",
                "exon_number",
                "exon_index",
                "target_exon_label",
            ):
                exon_int = _coerce_standard_exon_constraint_label(container.get(key))
                if exon_int is not None and (exon_hint or key in {"exon_label", "target_exon", "target_exon_label"}):
                    return exon_int
        return None

    def _add_from_region_constraints(goal: Any, fallback_effect: Any = None) -> None:
        if not isinstance(goal, dict):
            return
        constraints = goal.get("region_constraints")
        if not isinstance(constraints, list):
            return
        for entry in constraints:
            if not isinstance(entry, dict):
                continue
            exon_label = _region_constraint_exon_label(entry)
            if exon_label is None:
                continue
            _merge_ordered_exon_target(
                ordered_targets,
                target_index,
                exon_label,
                entry.get("desired_effect")
                or entry.get("desired_splice_effect")
                or entry.get("objective_type")
                or fallback_effect,
            )

    def _add_from_goal(goal: Any) -> None:
        if not isinstance(goal, dict):
            return
        goal_effect = goal.get("desired_effect")
        for source in (goal.get("exon_labels"), goal.get("exon_label")):
            values = source if isinstance(source, list) else [source]
            for exon_label in values:
                _merge_ordered_exon_target(ordered_targets, target_index, exon_label, goal_effect)
        evaluation_targets = goal.get("evaluation_targets")
        eval_items = (
            evaluation_targets
            if isinstance(evaluation_targets, list)
            else [evaluation_targets]
            if isinstance(evaluation_targets, dict)
            else []
        )
        for target in eval_items:
            if not isinstance(target, dict):
                continue
            _merge_ordered_exon_target(
                ordered_targets,
                target_index,
                target.get("exon_label"),
                target.get("desired_splice_effect")
                or target.get("desired_effect")
                or target.get("desired_delta")
                or target.get("objective_type"),
            )
        objectives: List[Any] = []
        for objective_field in ("objectives", "splice_objectives", "splice_isoform_objectives"):
            field_value = goal.get(objective_field)
            if isinstance(field_value, list):
                objectives.extend(field_value)
            elif isinstance(field_value, dict):
                objectives.append(field_value)
        for objective in objectives:
            if isinstance(objective, dict):
                _merge_ordered_exon_target(
                    ordered_targets,
                    target_index,
                    objective.get("exon_label"),
                    objective.get("desired_splice_effect")
                    or objective.get("desired_effect")
                    or objective.get("desired_delta")
                    or objective.get("direction")
                    or objective.get("objective")
                    or objective.get("objective_kind")
                    or objective.get("objective_type")
                    or objective.get("type"),
                )
        _add_from_region_constraints(goal, goal_effect)
        design_programs = goal.get("design_programs")
        if isinstance(design_programs, list):
            for program in design_programs:
                if not isinstance(program, dict):
                    continue
                program_effect = program.get("desired_effect") or goal_effect
                for source in (program.get("exon_labels"), program.get("exon_label")):
                    values = source if isinstance(source, list) else [source]
                    for exon_label in values:
                        _merge_ordered_exon_target(ordered_targets, target_index, exon_label, program_effect)
                _add_from_region_constraints(program, program_effect)

    _add_from_goal(structured_goal)
    if isinstance(task_context, dict):
        _add_from_goal(task_context.get("structured_goal"))
        evaluation_targets = task_context.get("evaluation_targets")
        eval_items = (
            evaluation_targets
            if isinstance(evaluation_targets, list)
            else [evaluation_targets]
            if isinstance(evaluation_targets, dict)
            else []
        )
        for target in eval_items:
            if not isinstance(target, dict):
                continue
            _merge_ordered_exon_target(
                ordered_targets,
                target_index,
                target.get("exon_label"),
                target.get("desired_splice_effect")
                or target.get("desired_effect")
                or target.get("desired_delta")
                or target.get("objective_type"),
            )
    return ordered_targets


def _apply_structured_exon_targets_to_goal(
    goal: Dict[str, Any],
    exon_targets: Any,
    *,
    force_focus: bool = False,
) -> int:
    if not isinstance(goal, dict):
        return 0

    ordered_labels: List[int] = []
    seen_labels: Set[int] = set()

    def _append_label(value: Any) -> None:
        exon_int = _coerce_exon_label_int(value)
        if exon_int is None or exon_int in seen_labels:
            return
        seen_labels.add(exon_int)
        ordered_labels.append(exon_int)

    for source in (goal.get("exon_labels"), goal.get("exon_label")):
        values = source if isinstance(source, list) else [source]
        for value in values:
            _append_label(value)

    normalized_targets = _collect_structured_exon_targets({"evaluation_targets": exon_targets})
    added_exons = 0
    for target in normalized_targets:
        exon_int = _coerce_exon_label_int(target.get("exon_label"))
        if exon_int is None or exon_int in seen_labels:
            continue
        seen_labels.add(exon_int)
        ordered_labels.append(exon_int)
        added_exons += 1

    changes = 0
    if len(ordered_labels) > 1:
        current_labels = (
            [_coerce_exon_label_int(item) for item in (goal.get("exon_labels") or [])]
            if isinstance(goal.get("exon_labels"), list)
            else []
        )
        current_labels = [item for item in current_labels if item is not None]
        if current_labels != ordered_labels:
            goal["exon_labels"] = ordered_labels
            changes += 1

    first_exon = ordered_labels[0] if ordered_labels else None
    current_exon = _coerce_exon_label_int(goal.get("exon_label"))
    if first_exon is not None and current_exon is None:
        goal["exon_label"] = first_exon
        changes += 1

    if not str(goal.get("desired_effect") or "").strip():
        desired_effects = {
            str(target.get("desired_effect") or "").strip()
            for target in normalized_targets
            if str(target.get("desired_effect") or "").strip()
        }
        if len(desired_effects) == 1:
            goal["desired_effect"] = next(iter(desired_effects))
            changes += 1

    if force_focus and ordered_labels and _coerce_bool(goal.get("focus_exons_only")) is not True:
        goal["focus_exons_only"] = True
        changes += 1

    return changes if changes else added_exons


def _objective_text_fragment(value: Any) -> str:
    if value in (None, "", [], {}):
        return ""
    if isinstance(value, (dict, list, tuple, set)):
        try:
            return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
        except Exception:
            return str(value)
    return str(value)


def _normalized_objective_text(*values: Any) -> str:
    text = " ".join(_objective_text_fragment(value) for value in values if value not in (None, "", [], {}))
    return text.strip().lower().replace("-", "_").replace(" ", "_")


def _splice_effect_direction_from_text(*values: Any) -> str:
    text = _normalized_objective_text(*values)
    if not text:
        return ""
    if any(
        token in text
        for token in (
            "decrease_poison_exon_inclusion",
            "decrease_exon_inclusion",
            "decreased_exon_inclusion",
            "decrease_inclusion",
            "decreased_inclusion",
            "reduce_exon_inclusion",
            "reduced_exon_inclusion",
            "reduce_inclusion",
            "reduced_inclusion",
            "promote_skipping",
            "increase_skipping",
            "exon_skipping",
            "skipping",
            "skip",
            "exclusion",
            "exclude",
        )
    ):
        return "decrease"
    if any(
        token in text
        for token in (
            "increase_exon_inclusion",
            "increase_inclusion",
            "promote_inclusion",
            "exon_inclusion",
            "include",
            "inclusion",
            "retention",
            "retain",
        )
    ):
        return "increase"
    return ""


def _generic_abundance_direction_from_text(*values: Any) -> str:
    text = _normalized_objective_text(*values)
    if not text:
        return ""
    if any(token in text for token in ("decrease", "reduce", "suppress", "knock_down", "knockdown", "down")):
        return "decrease"
    if any(token in text for token in ("increase", "promote", "favor", "up")):
        return "increase"
    return ""


def _infer_isoform_objective_desired_abundance(objective: Dict[str, Any]) -> str:
    if not isinstance(objective, dict):
        return ""
    explicit_direction = str(
        objective.get("desired_abundance")
        or objective.get("desired_delta")
        or ""
    ).strip().lower()
    if explicit_direction in {"increase", "decrease"}:
        return explicit_direction
    splice_effect_direction = _splice_effect_direction_from_text(
        objective.get("desired_splice_effect"),
        objective.get("desired_effect"),
        objective.get("objective"),
        objective.get("action"),
        objective.get("type"),
        objective.get("intended_effects"),
        objective.get("target_type"),
        objective.get("objective_type"),
    )
    if splice_effect_direction:
        return splice_effect_direction
    inferred_direction = _generic_abundance_direction_from_text(
        objective.get("direction"),
        objective.get("goal"),
    )
    if inferred_direction:
        return inferred_direction
    return _generic_abundance_direction_from_text(
        objective.get("objective"),
        objective.get("action"),
        objective.get("type"),
        objective.get("rationale"),
        objective.get("notes"),
    )


def _normalize_splice_objective_scope_value(value: Any) -> str:
    text = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "transcript": "specific_transcript",
        "specific": "specific_isoform",
        "specific_isoform_label": "specific_isoform",
        "isoform": "specific_isoform",
        "aggregate": "aggregate_class",
        "aggregate_isoforms": "aggregate_class",
        "aggregate_isoform_class": "aggregate_class",
        "group": "aggregate_class",
        "class": "aggregate_class",
        "default": "default_exon_context",
        "default_context": "default_exon_context",
        "default_transcript_context": "default_exon_context",
        "default_exon_splice_context": "default_exon_context",
        "exon_only": "default_exon_context",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {
        "specific_transcript",
        "specific_isoform",
        "aggregate_class",
        "default_exon_context",
    } else ""


def _normalized_design_objective_preseed(value: Any) -> Dict[str, Any]:
    normalized: Dict[str, Any] = {}

    def _has_structured_splice_program_signal(container: Any) -> bool:
        if not isinstance(container, dict):
            return False
        if str(container.get("intent") or "").strip().lower() == "splice_modulation":
            return True
        programs = (
            container.get("design_programs")
            if isinstance(container.get("design_programs"), list)
            else []
        )
        return any(
            isinstance(program, dict)
            and (
                str(program.get("intent") or "").strip().lower()
                == "splice_modulation"
                or (
                    isinstance(program.get("objectives"), list)
                    and bool(program.get("objectives"))
                )
                or program.get("desired_effect") not in (None, "", [], {})
                or _coerce_bool(program.get("run_splice_router")) is True
                or _coerce_bool(program.get("run_splice_eval")) is True
            )
            for program in programs
        )

    def _normalize_isoform_objectives(raw: Any) -> List[Dict[str, Any]]:
        if not isinstance(raw, list):
            return []
        normalized_objectives: List[Dict[str, Any]] = []

        def _conversion_transcript_objectives(item: Dict[str, Any]) -> List[Dict[str, Any]]:
            isoform_definitions = item.get("isoform_definitions") if isinstance(item.get("isoform_definitions"), dict) else {}

            def _definition_transcript_id(*keys: str) -> str:
                for key in keys:
                    value = isoform_definitions.get(key)
                    if isinstance(value, dict):
                        text = str(value.get("transcript_id") or value.get("id") or value.get("ensembl_transcript_id") or "").strip()
                    else:
                        text = str(value or "").strip()
                    if text:
                        return text
                return ""

            def _directionality_transcript_id(direction: str) -> str:
                directionality = item.get("directionality") if isinstance(item.get("directionality"), dict) else {}
                value = directionality.get(direction)
                values = value if isinstance(value, list) else [value]
                for candidate in values:
                    text = str(candidate or "").strip()
                    if text:
                        return text
                return ""

            from_tx = str(
                item.get("from_transcript_id")
                or item.get("source_transcript_id")
                or item.get("starting_transcript_id")
                or item.get("transcript_id_decrease")
                or item.get("decrease_transcript_id")
                or item.get("transcript_to_decrease_id")
                or item.get("alternative_isoform_transcript_id")
                or item.get("skipped_isoform_transcript_id")
                or item.get("excluded_isoform_transcript_id")
                or _directionality_transcript_id("decrease")
                or isoform_definitions.get("skipping_isoform_transcript_id")
                or isoform_definitions.get("skipped_isoform_transcript_id")
                or isoform_definitions.get("exclusion_isoform_transcript_id")
                or isoform_definitions.get("alternative_isoform_transcript_id")
                or _definition_transcript_id(
                    "undesired_isoform",
                    "skipped_isoform",
                    "skipping_isoform",
                    "exclusion_isoform",
                    "alternative_isoform",
                )
                or ""
            ).strip()
            to_tx = str(
                item.get("to_transcript_id")
                or item.get("target_transcript_id")
                or item.get("destination_transcript_id")
                or item.get("desired_transcript_id")
                or item.get("transcript_id_increase")
                or item.get("increase_transcript_id")
                or item.get("transcript_to_increase_id")
                or item.get("reference_isoform_transcript_id")
                or item.get("full_length_isoform_transcript_id")
                or item.get("included_isoform_transcript_id")
                or _directionality_transcript_id("increase")
                or isoform_definitions.get("inclusion_isoform_transcript_id")
                or isoform_definitions.get("included_isoform_transcript_id")
                or isoform_definitions.get("full_length_isoform_transcript_id")
                or isoform_definitions.get("reference_isoform_transcript_id")
                or _definition_transcript_id(
                    "desired_isoform",
                    "included_isoform",
                    "inclusion_isoform",
                    "full_length_isoform",
                    "reference_isoform",
                )
                or ""
            ).strip()
            if not from_tx and not to_tx:
                return []

            def _label(*keys: str, fallback: str) -> str:
                for key in keys:
                    text = str(item.get(key) or "").strip()
                    if text:
                        return text
                return fallback

            shared_fields = {
                key: deepcopy(item[key])
                for key in (
                    "event",
                    "exon_label",
                    "exon_labels",
                    "exon_numbering_transcript_id",
                    "objective_scope",
                    "aggregate_class",
                    "desired_splice_effect",
                    "event_type",
                    "intended_effects",
                    "objective",
                    "objective_kind",
                    "objective_type",
                    "action",
                    "type",
                    "direction",
                    "transcripts_to_decrease_description",
                    "transcripts_to_increase_description",
                    "rationale",
                    "notes",
                )
                if item.get(key) not in (None, "", [], {})
            }
            conversion_pair = {
                "from_transcript_id": from_tx or None,
                "to_transcript_id": to_tx or None,
            }
            objectives: List[Dict[str, Any]] = []
            if from_tx:
                objectives.append(
                    {
                        **shared_fields,
                        "isoform_label": _label(
                            "from_isoform_label",
                            "source_isoform_label",
                            "starting_isoform_label",
                            fallback=from_tx,
                        ),
                        "transcript_id": from_tx,
                        "desired_abundance": "decrease",
                        "role": explicit_biological_role(item.get("from_role")),
                        "conversion_role": "from",
                        "conversion_pair": deepcopy(conversion_pair),
                    }
                )
            if to_tx and to_tx != from_tx:
                objectives.append(
                    {
                        **shared_fields,
                        "isoform_label": _label(
                            "to_isoform_label",
                            "target_isoform_label",
                            "destination_isoform_label",
                            "desired_isoform_label",
                            fallback=to_tx,
                        ),
                        "transcript_id": to_tx,
                        "desired_abundance": "increase",
                        "role": explicit_biological_role(item.get("to_role")),
                        "conversion_role": "to",
                        "conversion_pair": deepcopy(conversion_pair),
                    }
                )
            return objectives

        for item in raw:
            if not isinstance(item, dict):
                continue
            expanded_conversion = _conversion_transcript_objectives(item)
            if expanded_conversion and not (
                str(item.get("transcript_id") or "").strip()
                or str(item.get("isoform_label") or item.get("label") or "").strip()
            ):
                normalized_objectives.extend(expanded_conversion)
                continue
            objective = deepcopy(item)
            transcript_id = str(
                objective.get("transcript_id")
                or objective.get("target_transcript_id")
                or ""
            ).strip()
            isoform_label = str(objective.get("isoform_label") or objective.get("label") or "").strip()
            objective_scope = _normalize_splice_objective_scope_value(objective.get("objective_scope"))
            if objective_scope:
                objective["objective_scope"] = objective_scope
            aggregate_class = objective.get("aggregate_class")
            if isinstance(aggregate_class, dict) and aggregate_class:
                objective["objective_scope"] = "aggregate_class"
            source = objective.get("source")
            source_text = json.dumps(source, sort_keys=True, default=str) if isinstance(source, dict) else str(source or "")
            artifact_ref_task_id = str(
                objective.get("artifact_ref_task_id")
                or objective.get("artifact_task_id")
                or objective.get("artifact_task_ref")
                or objective.get("source_artifact_task")
                or objective.get("source_artifact_task_id")
                or ""
            ).strip()
            if isinstance(source, dict):
                artifact_ref_task_id = artifact_ref_task_id or str(
                    source.get("artifact_ref_task_id")
                    or source.get("artifact_task_id")
                    or source.get("artifact_task_ref")
                    or source.get("source_artifact_task")
                    or source.get("source_artifact_task_id")
                    or ""
                ).strip()
            if (
                not isoform_label
                and (
                    artifact_ref_task_id
                    or "snapgene" in source_text.lower()
                    or "genbank" in source_text.lower()
                    or "artifact" in source_text.lower()
                )
            ):
                isoform_label = "SnapGene/GenBank artifact isoform"
                objective["isoform_label"] = isoform_label
            if not isoform_label and transcript_id:
                isoform_label = transcript_id
                objective["isoform_label"] = isoform_label
            if transcript_id and not str(objective.get("transcript_id") or "").strip():
                objective["transcript_id"] = transcript_id
            direction = _infer_isoform_objective_desired_abundance(objective)
            if direction == "decrease":
                objective["desired_abundance"] = "decrease"
                objective.setdefault("role", "context")
            elif direction == "increase":
                objective["desired_abundance"] = "increase"
                objective.setdefault("role", "context")
            if not isoform_label and objective.get("objective_scope") not in {"aggregate_class", "default_exon_context"}:
                continue
            definition_source = str(objective.get("definition_source") or "").strip()
            if definition_source.lower().startswith("artifact:"):
                artifact_path = definition_source.split(":", 1)[1].strip()
                if artifact_path.lower().endswith((".dna", ".gb", ".gbk", ".genbank", ".snapgene")):
                    objective.setdefault("snapgene_path", artifact_path)
                    objective.setdefault("source", "snapgene")
            direct_artifact_path = str(
                objective.get("artifact_ref")
                or objective.get("artifact_ref_path")
                or objective.get("snapgene_path")
                or ""
            ).strip()
            if direct_artifact_path.lower().endswith((".dna", ".gb", ".gbk", ".genbank", ".snapgene")):
                objective["snapgene_path"] = direct_artifact_path
                objective["source"] = "snapgene"
            if isinstance(source, dict):
                artifact_path = str(source.get("artifact_ref") or source.get("path") or "").strip()
                if artifact_path.lower().endswith((".dna", ".gb", ".gbk", ".genbank", ".snapgene")):
                    objective.setdefault("snapgene_path", artifact_path)
                    objective["source"] = "snapgene"
            normalized_objectives.append(objective)
        return normalized_objectives

    def _objectives_from_evaluation_targets(raw: Any) -> List[Dict[str, Any]]:
        targets = _normalize_evaluation_targets(raw)
        objectives: List[Dict[str, Any]] = []
        for target in targets:
            if not isinstance(target, dict) or not target.get("isoform_label"):
                continue
            desired_delta = _infer_isoform_objective_desired_abundance(target)
            if desired_delta not in {"increase", "decrease"}:
                continue
            objective = {
                "isoform_label": target.get("isoform_label"),
                "desired_abundance": desired_delta,
                "role": explicit_biological_role(target.get("biological_role") or target.get("role")),
            }
            if target.get("transcript_id"):
                objective["transcript_id"] = target.get("transcript_id")
            if target.get("rationale"):
                objective["rationale"] = target.get("rationale")
            objectives.append(objective)
        return objectives

    def _objectives_from_isoform_modulation(raw: Any) -> List[Dict[str, Any]]:
        if isinstance(raw, list):
            return _normalize_isoform_objectives(raw)
        if not isinstance(raw, dict):
            return []
        raw_objectives: List[Dict[str, Any]] = []
        for key, item in raw.items():
            if not isinstance(item, dict):
                continue
            objective = deepcopy(item)
            key_text = str(key or "").strip().lower()
            if not any(objective.get(field) for field in ("desired_abundance", "desired_delta", "direction", "objective", "type", "action")):
                if "decrease" in key_text or "reduce" in key_text or "suppress" in key_text:
                    objective["direction"] = "decrease"
                elif "increase" in key_text or "promote" in key_text or "favor" in key_text:
                    objective["direction"] = "increase"
            raw_objectives.append(objective)
        return _normalize_isoform_objectives(raw_objectives)

    def _objectives_from_design_programs(raw: Any) -> List[Dict[str, Any]]:
        if not isinstance(raw, list):
            return []
        objectives: List[Dict[str, Any]] = []
        for program in raw:
            if not isinstance(program, dict):
                continue
            nested_objectives = _normalize_isoform_objectives(program.get("objectives"))
            if nested_objectives:
                objectives.extend(nested_objectives)
                continue
            text = " ".join(
                str(program.get(key) or "")
                for key in ("objective", "program_goal", "label", "notes", "program_id")
            ).strip()
            direction = _splice_effect_direction_from_text(text) or _generic_abundance_direction_from_text(text)
            if not direction:
                continue

            isoform_target = program.get("isoform_target") if isinstance(program.get("isoform_target"), dict) else {}
            isoform_label = str(
                program.get("isoform_label")
                or isoform_target.get("isoform_label")
                or isoform_target.get("label")
                or isoform_target.get("transcript_label")
                or ""
            ).strip()
            transcript_id = str(
                program.get("target_transcript_id")
                or program.get("transcript_id")
                or isoform_target.get("transcript_id")
                or isoform_target.get("id")
                or ""
            ).strip()
            source = program.get("target_isoform_source")
            if source in (None, "", [], {}) and isoform_target.get("source") not in (None, "", [], {}):
                source = isoform_target.get("source")
            artifact_path = ""
            if isinstance(source, dict):
                artifact_path = str(source.get("artifact_ref") or source.get("path") or "").strip()
                if not isoform_label and str(source.get("type") or "").strip().lower() == "artifact":
                    isoform_label = "SnapGene/GenBank artifact isoform"
            elif str(source or "").strip().lower() in {"artifact", "snapgene", "genbank"} and not isoform_label:
                isoform_label = "SnapGene/GenBank artifact isoform"
            if not artifact_path:
                artifact_path = str(
                    isoform_target.get("artifact_ref")
                    or isoform_target.get("artifact_ref_path")
                    or isoform_target.get("snapgene_path")
                    or isoform_target.get("path")
                    or ""
                ).strip()
            if not isoform_label and transcript_id:
                isoform_label = transcript_id
            if not isoform_label:
                continue

            objective = {
                "isoform_label": isoform_label,
                "desired_abundance": direction,
                "role": explicit_biological_role(program.get("biological_role") or program.get("role")),
            }
            if transcript_id:
                objective["transcript_id"] = transcript_id
            if text:
                objective["rationale"] = text
            artifact_task_id = str(
                isoform_target.get("artifact_task_id")
                or isoform_target.get("artifact_ref_task_id")
                or isoform_target.get("source_artifact_task_id")
                or ""
            ).strip()
            if artifact_task_id:
                objective["artifact_task_id"] = artifact_task_id
            if artifact_path.lower().endswith((".dna", ".gb", ".gbk", ".genbank", ".snapgene")):
                objective["snapgene_path"] = artifact_path
                objective["source"] = "snapgene"
            elif str(source or "").strip().lower() in {"artifact", "snapgene", "genbank"}:
                objective["source"] = str(source or "").strip().lower()
            objectives.append(objective)
        return objectives

    if isinstance(value, list):
        objectives = _normalize_isoform_objectives(value)
        if not objectives:
            objectives = _objectives_from_evaluation_targets(value)
        if not objectives:
            objectives = _objectives_from_design_programs(value)
        if objectives:
            normalized["splice_isoform_objectives"] = deepcopy(objectives)
        return normalized
    if not isinstance(value, dict):
        return normalized

    objectives = _normalize_isoform_objectives(value.get("splice_isoform_objectives"))
    if not objectives:
        objectives = _normalize_isoform_objectives(value.get("isoform_objectives"))
    if not objectives:
        objectives = _normalize_isoform_objectives(value.get("isoform_modulation_objectives"))
    if not objectives:
        objectives = _normalize_isoform_objectives(value.get("isoform_targets"))
    if not objectives:
        objectives = _objectives_from_isoform_modulation(value.get("isoform_modulation"))
    if not objectives:
        objectives = _normalize_isoform_objectives(value.get("prioritized_objectives"))
    if not objectives:
        objectives = _normalize_isoform_objectives(value.get("objectives"))
    if not objectives and _has_structured_splice_program_signal(value):
        objectives = _objectives_from_evaluation_targets(value.get("evaluation_targets"))
    if not objectives and _has_structured_splice_program_signal(value):
        objectives = _objectives_from_design_programs(value.get("design_programs"))
    if objectives:
        normalized["splice_isoform_objectives"] = deepcopy(objectives)

    exon_targets = _collect_structured_exon_targets({"evaluation_targets": value.get("exon_targets")})
    if not exon_targets:
        exon_targets = _collect_structured_exon_targets({"evaluation_targets": value.get("evaluation_targets")})
    if exon_targets:
        normalized["exon_targets"] = deepcopy(exon_targets)

    evaluation_targets = _normalize_evaluation_targets(value.get("evaluation_targets"))
    if evaluation_targets:
        normalized["evaluation_targets"] = deepcopy(evaluation_targets)

    if _coerce_bool(value.get("focus_exons_only")) is True:
        normalized["focus_exons_only"] = True

    overlay: Dict[str, Any] = {}
    structured_goal_overlay = value.get("structured_goal_overlay")
    if isinstance(structured_goal_overlay, dict):
        overlay = {
            str(key): deepcopy(field_value)
            for key, field_value in structured_goal_overlay.items()
            if str(key).strip() and field_value not in (None, "")
        }

    for field in (
        "constraints",
        "num_mismatches",
        "parameter_constraints",
        "sequence_filters",
        "sequence_constraints",
        "design_constraints",
        "filter_constraints",
        "offtarget_constraints",
        "off_target_constraints",
        "offtarget_filtering",
        "off_target_filtering",
        "region_constraints",
        "gc_min",
        "gc_max",
        "homopolymer_max_run",
        "homopolymers",
        "homopolymer_limits",
    ):
        if field not in overlay and value.get(field) not in (None, "", [], {}):
            overlay[field] = deepcopy(value.get(field))

    task_target_context = str(overlay.get("target_context") or "").strip()
    if task_target_context:
        expression_settings = overlay.get("off_target_expression")
        if not isinstance(expression_settings, dict):
            expression_settings = {}
        expression_settings.setdefault("target_context", task_target_context)
        overlay["off_target_expression"] = expression_settings
    if overlay:
        normalized["structured_goal_overlay"] = overlay

    return normalized


def _structured_goal_is_binding_interval_context(structured_goal: Any, context_text: str = "") -> bool:
    if not isinstance(structured_goal, dict):
        return False
    intent = str(structured_goal.get("intent") or "").strip().lower()
    programs = structured_goal.get("design_programs") if isinstance(structured_goal.get("design_programs"), list) else []
    program_binding = any(
        isinstance(program, dict) and str(program.get("intent") or "").strip().lower() == "binding"
        for program in programs
    )
    constraints = structured_goal.get("region_constraints")
    constraint_items = constraints if isinstance(constraints, list) else []
    has_explicit_intervals = False
    for constraint in constraint_items:
        if not isinstance(constraint, dict):
            continue
        source = str(constraint.get("source") or constraint.get("source_type") or "").strip().lower().replace("-", "_").replace(" ", "_")
        if source in {
            "user_provided_bed_intervals",
            "user_provided_intervals",
            "explicit_bed_intervals",
            "explicit_intervals",
            "bed_intervals",
        }:
            has_explicit_intervals = True
        if isinstance(constraint.get("bed_intervals"), list) or isinstance(constraint.get("intervals_bed0_half_open"), list):
            has_explicit_intervals = True
    if not has_explicit_intervals:
        return False
    blob = f"{json.dumps(structured_goal, ensure_ascii=False, default=str)} {context_text}".lower()
    has_binding_language = any(
        token in blob
        for token in ("target-site", "target site", "binding", "eclip", "mir-", "mirna", "3' utr", "3 utr", "utr3")
    )
    has_splice_language = any(
        token in blob
        for token in ("splice", "splicing", "junction", "donor", "acceptor", "exon skipping")
    )
    return bool((intent == "binding" or program_binding or has_binding_language) and not has_splice_language)


def _prepare_design_objective_preseed(
    structured_goal: Any,
    task_context: Any,
) -> Optional[Dict[str, Any]]:
    goal = structured_goal if isinstance(structured_goal, dict) else {}
    context = task_context if isinstance(task_context, dict) else {}
    binding_interval_context = _structured_goal_is_binding_interval_context(
        {**deepcopy(goal), **{key: deepcopy(value) for key, value in context.items() if key not in {"structured_goal"}}}
    )
    normalized_goal_objectives = (
        []
        if binding_interval_context
        else _normalized_design_objective_preseed(goal).get("splice_isoform_objectives")
    )
    objectives = normalized_goal_objectives if isinstance(normalized_goal_objectives, list) else []
    snapgene_path = str(goal.get("snapgene_path") or "").strip()
    if not snapgene_path:
        for ref in _resolve_artifact_ref_paths({"artifact_refs": context.get("artifact_refs")}):
            if str(ref).strip().lower().endswith((".dna", ".gb", ".gbk", ".genbank")):
                snapgene_path = str(ref).strip()
                break
    declared_intents = {
        str(item.get("intent") or "").strip().lower()
        for item in [goal, *(p for p in goal.get("design_programs") or [] if isinstance(p, dict))]
        if str(item.get("intent") or "").strip()
    }
    # A transcript used to locate a knockdown or binding target does not
    # become an isoform-abundance splice objective merely because the intended
    # downstream effect has a direction. Preserve explicit splice objectives
    # above, but do not synthesize one from these typed non-splicing intents.
    non_splicing_intent = bool(declared_intents) and declared_intents <= {"knockdown", "binding"}
    if not objectives and not binding_interval_context and not non_splicing_intent:
        direction_context = " ".join(
            part
            for part in (
                json.dumps(goal.get("design_programs") or [], ensure_ascii=False, default=str),
                str(goal.get("objective") or ""),
                str(goal.get("target_context") or ""),
                str(context.get("target_context") or ""),
            )
            if part
        ).lower()
        direction = ""
        direction = _splice_effect_direction_from_text(direction_context) or _generic_abundance_direction_from_text(direction_context)
        context_transcript = str(context.get("transcript_id") or goal.get("transcript_id") or "").strip()
        context_label = str(context.get("isoform_label") or goal.get("isoform_label") or "").strip()
        if direction and context_transcript:
            objectives = [
                {
                    "isoform_label": context_label or context_transcript,
                    "transcript_id": context_transcript,
                    "desired_abundance": direction,
                    "role": explicit_biological_role(goal.get("biological_role")),
                }
            ]
        elif direction and snapgene_path and any(token in direction_context for token in ("artifact", "snapgene", "genbank", "file", "construct")):
            objectives = [
                {
                    "isoform_label": context_label or "SnapGene/GenBank artifact isoform",
                    "desired_abundance": direction,
                    "role": explicit_biological_role(goal.get("biological_role")),
                    "snapgene_path": snapgene_path,
                    "source": "snapgene",
                }
            ]

    prepared: List[Dict[str, Any]] = []
    for objective in objectives:
        if not isinstance(objective, dict):
            continue
        obj = deepcopy(objective)
        label = str(obj.get("isoform_label") or "").strip().lower()
        if (
            snapgene_path
            and any(token in label for token in ("snapgene", "genbank", "artifact"))
            and not str(obj.get("snapgene_path") or "").strip()
        ):
            obj["snapgene_path"] = snapgene_path
            obj["source"] = "snapgene"
        explicit_direction = str(obj.get("desired_abundance") or obj.get("desired_delta") or "").strip().lower()
        if explicit_direction in {"increase", "decrease"}:
            obj["desired_abundance"] = explicit_direction
        if not _isoform_objective_key(obj):
            continue
        prepared.append(obj)

    payload: Dict[str, Any] = {}
    if prepared:
        payload["splice_isoform_objectives"] = prepared

    exon_targets = _collect_structured_exon_targets(goal, context)
    if exon_targets and not binding_interval_context:
        payload["exon_targets"] = deepcopy(exon_targets)
        payload["focus_exons_only"] = True

    evaluation_targets = _normalize_evaluation_targets(
        context.get("evaluation_targets") or goal.get("evaluation_targets")
    )
    if evaluation_targets and not binding_interval_context:
        payload["evaluation_targets"] = deepcopy(evaluation_targets)

    structured_goal_overlay: Dict[str, Any] = deepcopy(goal)
    for field in (
        "num_mismatches",
        "gene_symbol",
        "gene_id",
        "species",
        "target_context",
        "chemistry",
        "platform",
        "intent",
        "target_region",
        "target_scope",
        "run_splice_eval",
        "run_splice_router",
        "aso_overlap_requirement",
        "rbp_binding",
        "rbp_region_operator",
        "mirna_binding",
        "motif_tiling",
        "binding_site_tiling",
        "target_features",
        "region_constraints",
        "constraints",
        "parameter_constraints",
        "sequence_filters",
        "sequence_constraints",
        "design_constraints",
        "filter_constraints",
        "offtarget_constraints",
        "off_target_constraints",
        "offtarget_filtering",
        "off_target_filtering",
    ):
        field_value = context.get(field)
        if field_value not in (None, "", [], {}) and structured_goal_overlay.get(field) in (None, "", [], {}):
            structured_goal_overlay[field] = deepcopy(field_value)
    task_target_context = str(context.get("target_context") or "").strip()
    if task_target_context:
        expression_settings = structured_goal_overlay.get("off_target_expression")
        if not isinstance(expression_settings, dict):
            expression_settings = {}
        expression_settings.setdefault("target_context", task_target_context)
        structured_goal_overlay["off_target_expression"] = expression_settings
    if prepared:
        intent_text = str(structured_goal_overlay.get("intent") or "").strip().lower()
        context_text = json.dumps(structured_goal_overlay, ensure_ascii=False).lower()
        if intent_text in {"", "binding"} and ("splice" in context_text or "isoform" in context_text):
            structured_goal_overlay["intent"] = "splice_modulation"
    if structured_goal_overlay:
        payload["structured_goal_overlay"] = structured_goal_overlay

    return payload or None


def _isoform_objective_key(objective: Dict[str, Any]) -> str:
    label = str(objective.get("isoform_label") or "").strip().lower()
    transcript = str(objective.get("transcript_id") or "").strip().lower()
    if transcript or label:
        return transcript or label
    scope = _normalize_splice_objective_scope_value(objective.get("objective_scope"))
    if scope == "aggregate_class" or isinstance(objective.get("aggregate_class"), dict):
        return "aggregate:" + json.dumps(
            {
                "aggregate_class": objective.get("aggregate_class") if isinstance(objective.get("aggregate_class"), dict) else {},
                "desired_abundance": str(objective.get("desired_abundance") or objective.get("desired_delta") or "").strip().lower(),
                "role": str(objective.get("role") or "").strip().lower(),
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
    if scope == "default_exon_context":
        return "default_exon_context:" + json.dumps(
            {
                "exon_label": objective.get("exon_label"),
                "exon_labels": objective.get("exon_labels"),
                "desired_abundance": str(objective.get("desired_abundance") or objective.get("desired_delta") or "").strip().lower(),
                "desired_effect": str(objective.get("desired_effect") or objective.get("direction") or "").strip().lower(),
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
    return ""


def _merge_preseeded_isoform_objectives(
    structured_goal: Dict[str, Any],
    preseed: Any,
) -> int:
    normalized_preseed = _normalized_design_objective_preseed(preseed)
    preseed_objectives = [
        obj
        for obj in (normalized_preseed.get("splice_isoform_objectives") or [])
        if isinstance(obj, dict) and _isoform_objective_key(obj)
    ]
    if not preseed_objectives:
        return 0
    parsed = structured_goal.get("splice_isoform_objectives")
    parsed_list = [obj for obj in parsed if isinstance(obj, dict)] if isinstance(parsed, list) else []
    original_count = len(parsed_list)
    parsed_list = [obj for obj in parsed_list if _isoform_objective_key(obj)]
    filtered_placeholders = len(parsed_list) != original_count
    existing_keys = {_isoform_objective_key(obj) for obj in parsed_list}
    added = 0
    for objective in preseed_objectives:
        key = _isoform_objective_key(objective)
        if key and key not in existing_keys:
            parsed_list.append(deepcopy(objective))
            existing_keys.add(key)
            added += 1
    if added or filtered_placeholders:
        structured_goal["splice_isoform_objectives"] = parsed_list
    return added + int(filtered_placeholders)


def _merge_preseeded_exon_targets(
    structured_goal: Dict[str, Any],
    preseed: Any,
) -> int:
    normalized_preseed = _normalized_design_objective_preseed(preseed)
    changes = 0
    exon_targets = normalized_preseed.get("exon_targets")
    if exon_targets:
        changes += _apply_structured_exon_targets_to_goal(
            structured_goal,
            exon_targets,
            force_focus=bool(normalized_preseed.get("focus_exons_only")),
        )
    evaluation_targets = normalized_preseed.get("evaluation_targets")
    if evaluation_targets:
        existing_targets = (
            [item for item in structured_goal.get("evaluation_targets") if isinstance(item, dict)]
            if isinstance(structured_goal.get("evaluation_targets"), list)
            else []
        )
        merged_targets: List[Dict[str, Any]] = []
        seen_target_keys: Set[str] = set()
        for item in existing_targets + [item for item in evaluation_targets if isinstance(item, dict)]:
            key = json.dumps(item, ensure_ascii=False, sort_keys=True, default=str)
            if key in seen_target_keys:
                continue
            seen_target_keys.add(key)
            merged_targets.append(deepcopy(item))
        if merged_targets != existing_targets:
            structured_goal["evaluation_targets"] = merged_targets
            changes += 1
    return changes


def _explicit_target_interval_identity(target: Any) -> Optional[Tuple[int, int]]:
    if not isinstance(target, dict):
        return None
    start = target.get("start")
    end = target.get("end")
    if isinstance(start, bool) or isinstance(end, bool):
        return None
    try:
        start_value = int(start)
        end_value = int(end)
    except (TypeError, ValueError):
        return None
    if start_value == end_value:
        return None
    return min(start_value, end_value), max(start_value, end_value)


def _explicit_target_transcript_identities(target: Any) -> Set[str]:
    if not isinstance(target, dict):
        return set()
    from .explicit_target_identity import target_references
    return target_references(target)


def _explicit_targets_share_structural_identity(left: Any, right: Any) -> bool:
    """Match source and parsed targets by typed identity, never display text."""

    left_interval = _explicit_target_interval_identity(left)
    right_interval = _explicit_target_interval_identity(right)
    if left_interval is None or left_interval != right_interval:
        return False

    left_chromosomes = {alias.casefold() for alias in _chrom_aliases(left.get("chrom"))}
    right_chromosomes = {alias.casefold() for alias in _chrom_aliases(right.get("chrom"))}
    if left_chromosomes and right_chromosomes and not left_chromosomes.intersection(right_chromosomes):
        return False

    left_strand = str(left.get("strand") or "").strip()
    right_strand = str(right.get("strand") or "").strip()
    if left_strand in {"+", "-"} and right_strand in {"+", "-"} and left_strand != right_strand:
        return False

    left_transcripts = _explicit_target_transcript_identities(left)
    right_transcripts = _explicit_target_transcript_identities(right)
    from .explicit_target_identity import compatible_references
    if left_transcripts and right_transcripts and not all(
        any(compatible_references(left_id, right_id) for right_id in right_transcripts)
        for left_id in left_transcripts
    ):
        return False
    return True


def _merge_structurally_identical_explicit_target(
    source_target: Dict[str, Any],
    parsed_target: Dict[str, Any],
) -> Dict[str, Any]:
    """Retain source provenance while preserving richer parsed target fields."""

    from .explicit_target_identity import apply_clarified_target, inferred_target
    if source_target.get("source") == "clarification_answers" and inferred_target(parsed_target):
        # Preserve the existing same-strand merge's descriptive detail, but a
        # missing clarification strand must not inherit a parsed guess.
        clarified = apply_clarified_target(source_target, parsed_target)
        for key in ("label", "exon_label", "notes"):
            if parsed_target.get(key) not in (None, "", [], {}):
                clarified[key] = deepcopy(parsed_target[key])
        return clarified

    merged = deepcopy(parsed_target)
    for key, value in source_target.items():
        if key == "evidence_refs":
            merged_refs = _normalize_text_list(
                [
                    *_normalize_text_list(value),
                    *_normalize_text_list(merged.get(key)),
                ]
            )
            if merged_refs:
                merged[key] = merged_refs
            continue
        if merged.get(key) in (None, "", [], {}):
            merged[key] = deepcopy(value)
    return merged


def _merge_explicit_splice_target_lists(
    source_targets: Any,
    parsed_targets: Any,
) -> List[Dict[str, Any]]:
    source_items = (
        [item for item in source_targets if isinstance(item, dict)]
        if isinstance(source_targets, list)
        else []
    )
    parsed_items = (
        [item for item in parsed_targets if isinstance(item, dict)]
        if isinstance(parsed_targets, list)
        else []
    )
    merged_targets: List[Dict[str, Any]] = []
    consumed_source_indexes: Set[int] = set()
    for parsed_target in parsed_items:
        matching_index = next(
            (
                index
                for index, source_target in enumerate(source_items)
                if index not in consumed_source_indexes
                and _explicit_targets_share_structural_identity(source_target, parsed_target)
            ),
            None,
        )
        if matching_index is None:
            merged_targets.append(deepcopy(parsed_target))
            continue
        consumed_source_indexes.add(matching_index)
        merged_targets.append(
            _merge_structurally_identical_explicit_target(
                source_items[matching_index],
                parsed_target,
            )
        )
    merged_targets.extend(
        deepcopy(source_target)
        for index, source_target in enumerate(source_items)
        if index not in consumed_source_indexes
    )
    from .explicit_target_identity import reconcile_clarified_targets
    return reconcile_clarified_targets(merged_targets)


def _merge_preseeded_structured_goal_overlay(
    structured_goal: Dict[str, Any],
    preseed: Any,
) -> int:
    normalized_preseed = _normalized_design_objective_preseed(preseed)
    overlay = normalized_preseed.get("structured_goal_overlay")
    if not isinstance(overlay, dict) or not overlay:
        return 0
    def _merge(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
        merged = deepcopy(base)
        for key, value in override.items():
            if key == "explicit_splice_targets" and isinstance(value, list):
                merged[key] = _merge_explicit_splice_target_lists(merged.get(key), value)
            elif isinstance(value, dict) and isinstance(merged.get(key), dict):
                merged[key] = _merge(merged[key], value)
            else:
                merged[key] = deepcopy(value)
        return merged

    merged_goal = _merge(overlay, structured_goal)
    changed_fields = sum(1 for key, value in merged_goal.items() if structured_goal.get(key) != value)
    if set(structured_goal) != set(merged_goal):
        changed_fields += len(set(merged_goal) - set(structured_goal))
    if changed_fields:
        structured_goal.clear()
        structured_goal.update(merged_goal)
    return changed_fields


def _restore_design_objective_preseed_to_payload(
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    preseed: Any,
) -> int:
    if not isinstance(structured_goal, dict) or not isinstance(final_payload, dict):
        return 0
    if not isinstance(preseed, dict) or not preseed:
        return 0
    changes = 0
    changes += _merge_preseeded_structured_goal_overlay(structured_goal, preseed)
    changes += _merge_preseeded_isoform_objectives(structured_goal, preseed)
    changes += _merge_preseeded_exon_targets(structured_goal, preseed)
    if changes:
        final_payload["structured_goal"] = structured_goal
        for field in ("splice_isoform_objectives", "evaluation_targets", "exon_targets", "focus_exons_only"):
            if field in structured_goal:
                final_payload[field] = deepcopy(structured_goal[field])
    return changes


def _reference_goal_context_for_request(candidate_run_dirs: List[str]) -> Dict[str, Any]:
    for candidate in candidate_run_dirs:
        candidate_path = Path(candidate)
        goal_path = _run_path(candidate_path, "goal_intake.json")
        if not goal_path.exists():
            continue
        try:
            context = _goal_payload_context(str(candidate_path))
        except Exception:
            continue
        structured_goal = context.get("structured_goal") if isinstance(context.get("structured_goal"), dict) else {}
        final_payload = context.get("final_payload") if isinstance(context.get("final_payload"), dict) else {}
        if structured_goal and any(
            str(structured_goal.get(field) or "").strip()
            for field in ("gene_symbol", "gene_id", "species", "intent", "target_context")
        ):
            return {
                "run_dir": str(candidate_path),
                "structured_goal": deepcopy(structured_goal),
                "final_payload": deepcopy(final_payload),
            }
    return {}


def _generated_trace_contexts(candidate_run_dirs):
    """Keep every actual dependency's trace under its recorded run identity."""
    contexts = []
    for candidate in dict.fromkeys(candidate_run_dirs):
        collected = _collect_generated_stage_sets(candidate)
        if not any(collected.get('sources', {}).values()):
            continue
        reference = _reference_goal_context_for_request([candidate])
        goal = reference.get('structured_goal') or {}
        contexts.append({'run_dir': candidate, **collected,
            'reference_identity': {key: goal.get(key) for key in ('species', 'gene_symbol', 'gene_id')}})
    return contexts


def _overlay_request_context_on_goal(
    base_goal: Dict[str, Any],
    request_envelope: Dict[str, Any],
    request_text: str,
) -> Dict[str, Any]:
    goal = deepcopy(base_goal) if isinstance(base_goal, dict) else {}
    # A previous evaluation may supply reference context, but its permission
    # to perform an external search is not a policy for this task.
    goal.pop("off_target_screening", None)
    for field in ("gene_symbol", "gene_id", "species", "target_context", "platform", "chemistry", "oligoai_evaluation", "num_mismatches", "off_target_screening"):
        value = request_envelope.get(field)
        if value not in (None, "", [], {}):
            goal[field] = deepcopy(value)
    transcript_id = str(request_envelope.get("transcript_id") or "").strip()
    if transcript_id:
        goal["transcript_policy"] = "user_locked"
        goal["transcript_lock"] = {"kind": "explicit_id", "value": transcript_id}
    evaluation_targets = _normalize_evaluation_targets(request_envelope.get("evaluation_targets"))
    if evaluation_targets:
        goal["evaluation_targets"] = deepcopy(evaluation_targets)
        _apply_structured_exon_targets_to_goal(goal, evaluation_targets, force_focus=True)
        explicit_splice_targets: List[Dict[str, Any]] = []
        for item in evaluation_targets:
            chrom = str(item.get("chrom") or "").strip()
            start = item.get("start")
            end = item.get("end")
            if chrom and isinstance(start, int) and isinstance(end, int):
                explicit_target = {
                    "chrom": chrom,
                    "start": int(start),
                    "end": int(end),
                }
                for field in ("strand", "isoform_label", "site_kind", "label", "desired_delta"):
                    text = str(item.get(field) or "").strip()
                    if text:
                        explicit_target[field] = text
                if item.get("exon_label") not in (None, "", [], {}):
                    explicit_target["requested_exon_label"] = deepcopy(item.get("exon_label"))
                explicit_splice_targets.append(explicit_target)
        if explicit_splice_targets:
            goal["explicit_splice_targets"] = explicit_splice_targets
    # Evaluation dispatch uses declared intent, classifications and outcome
    # targets. References, exclusions and unrelated tasks in the full request
    # must not create an additional biological mechanism here.
    return goal


def _ensure_eval_transcript_catalog(goal: Dict[str, Any], runtime: Any) -> Tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]], List[str]]:
    notes: List[str] = []
    isoform_transcripts = goal.get("isoform_transcripts") if isinstance(goal.get("isoform_transcripts"), dict) else {}
    all_transcripts_full = goal.get("all_transcripts_full") if isinstance(goal.get("all_transcripts_full"), dict) else {}
    if not isoform_transcripts and all_transcripts_full:
        isoform_transcripts = deepcopy(all_transcripts_full)
    if not all_transcripts_full:
        loader = getattr(runtime, "_load_all_transcripts_for_gene", None)
        gene_symbol = str(goal.get("gene_symbol") or "").strip()
        species = str(goal.get("species") or "").strip()
        if callable(loader) and gene_symbol and species:
            try:
                loaded = loader(goal)
            except Exception as exc:
                notes.append(f"load_all_transcripts_failed:{exc}")
                loaded = {}
            if isinstance(loaded, dict) and loaded:
                all_transcripts_full = deepcopy(loaded)
                goal["all_transcripts_full"] = deepcopy(loaded)
                if not isoform_transcripts:
                    isoform_transcripts = deepcopy(loaded)
    if not isoform_transcripts:
        isoform_transcripts = goal.get("isoform_transcripts") if isinstance(goal.get("isoform_transcripts"), dict) else {}
    requested_ids = [str((goal.get("transcript_lock") or {}).get("value") or goal.get("transcript_id") or "")]
    requested_ids.extend(str(t.get("transcript_id") or "") for t in (goal.get("evaluation_targets") or []) if isinstance(t, dict))
    for target in goal.get("evaluation_targets") or []:
        if isinstance(target, dict):
            requested_ids.append(str(target.get("reference_transcript_id") or ""))
            window = target.get("splice_relative_window") or {}
            if isinstance(window, dict):
                requested_ids.append(str(window.get("reference_transcript_id") or ""))
    for requested in dict.fromkeys(requested_ids):
        if not requested or "." not in requested:
            continue
        try:
            structure = runtime.get_transcript_structure(requested)
        except Exception as exc:
            structure = {"error":f"requested_transcript_resolution_failed:{requested}:{exc}"}
        if not structure.get("error"):
            versioned = structure.get("versioned_id") or (f"{requested.split('.')[0]}.{structure['version']}" if structure.get("version") is not None else structure.get("id"))
            if versioned != requested:
                structure = {"error":f"requested_transcript_version_not_attested:{requested}:{versioned}"}
        if structure.get("error"):
            notes.append(str(structure["error"]))
            # A different version must not satisfy an explicit version lock.
            for catalog in (isoform_transcripts, all_transcripts_full):
                for label in list(catalog):
                    if str(catalog[label].get("transcript_id") or label).split(".")[0] == requested.split(".")[0]:
                        del catalog[label]
            continue
        stable = requested.split(".")[0]
        resolved = {"transcript_id":stable, "chrom":structure.get("seq_region_name"), "strand":structure.get("strand"),
                    "exons_tx":structure.get("exons_tx"), "metadata":{key:structure.get(key) for key in
                        ("versioned_id","version","reference_source","reference_annotation","species","assembly_name","seq_region_name","strand","gene_id","gene_symbol")}}
        for catalog in (isoform_transcripts, all_transcripts_full):
            aliases = [label for label, entry in catalog.items() if str(entry.get("transcript_id") or label).split(".")[0] == stable]
            for label in aliases or [stable]:
                catalog[label] = deepcopy(resolved)
    goal["all_transcripts_full"] = deepcopy(all_transcripts_full)
    if isinstance(isoform_transcripts, dict):
        goal["isoform_transcripts"] = deepcopy(isoform_transcripts)
    return (
        isoform_transcripts if isinstance(isoform_transcripts, dict) else {},
        all_transcripts_full if isinstance(all_transcripts_full, dict) else {},
        notes,
    )


def _choose_eval_transcript(
    goal: Dict[str, Any],
    isoform_transcripts: Dict[str, Dict[str, Any]],
    all_transcripts_full: Dict[str, Dict[str, Any]],
    runtime: Any,
) -> Tuple[Optional[str], Optional[str], Optional[Dict[str, Any]]]:
    primary_ids = {str(target.get("transcript_id")) for target in goal.get("evaluation_targets") or []
                   if isinstance(target, dict) and target.get("transcript_id")
                   and target.get("objective_type") == "primary_outcome"}
    primary_id = next(iter(primary_ids)) if len(primary_ids) == 1 else None
    requested = str((goal.get("transcript_lock") or {}).get("value") or primary_id or goal.get("transcript_id") or "")
    if requested:
        for label, entry in {**all_transcripts_full, **isoform_transcripts}.items():
            tid = str(entry.get("transcript_id") or entry.get("id") or label)
            if tid.split(".")[0] == requested.split(".")[0]:
                metadata = entry.get("metadata") or {}
                versioned = metadata.get("versioned_id") or (f"{tid.split('.')[0]}.{metadata['version']}" if metadata.get("version") is not None else tid)
                if "." not in requested or versioned == requested:
                    return tid, label, deepcopy(entry)
        return requested, None, None
    selector = getattr(runtime, "_select_primary_transcript", None)
    transcript_id: Optional[str] = None
    iso_label: Optional[str] = None
    if callable(selector):
        try:
            transcript_id, iso_label = selector(goal, all_transcripts_full or None)
        except Exception:
            transcript_id, iso_label = None, None
    if not transcript_id:
        transcript_id = (
            str(
                goal.get("transcript_lock", {}).get("value")
                if isinstance(goal.get("transcript_lock"), dict)
                else ""
            ).strip()
            or None
        )
    if not transcript_id:
        for label, entry in isoform_transcripts.items():
            if not isinstance(entry, dict):
                continue
            transcript_id = str(entry.get("transcript_id") or entry.get("id") or "").strip() or None
            iso_label = str(label).strip() or transcript_id
            if transcript_id:
                break
    transcript_entry = None
    if transcript_id:
        if iso_label and isinstance(isoform_transcripts.get(iso_label), dict):
            transcript_entry = isoform_transcripts.get(iso_label)
        elif isinstance(isoform_transcripts.get(transcript_id), dict):
            transcript_entry = isoform_transcripts.get(transcript_id)
            iso_label = transcript_id
        elif isinstance(all_transcripts_full.get(transcript_id), dict):
            transcript_entry = all_transcripts_full.get(transcript_id)
            iso_label = transcript_id
    return transcript_id, iso_label, deepcopy(transcript_entry) if isinstance(transcript_entry, dict) else None


def _find_sequence_occurrences(haystack: str, needle: str) -> List[int]:
    if not haystack or not needle or len(needle) > len(haystack):
        return []
    positions: List[int] = []
    start = 0
    while True:
        idx = haystack.find(needle, start)
        if idx < 0:
            break
        positions.append(idx + 1)
        start = idx + 1
    return positions


def _mapping_hit_sort_key(
    item: Dict[str, Any],
    *,
    preferred_transcript_id: Optional[str],
) -> Tuple[int, int, int, int, str, int]:
    transcript_match = 0 if preferred_transcript_id and str(item.get("transcript_id") or "").strip() == preferred_transcript_id else 1
    orientation_rank = 0 if str(item.get("match_orientation") or "") == "input_sequence" else 1
    scope = str(item.get("mapping_scope") or "").strip().lower()
    scope_rank = 0 if scope == "spliced_cdna" else 1 if scope == "pre_mrna_locus" else 2
    contiguous_rank = 0 if bool(item.get("is_contiguous_genomic_span")) else 1
    span = item.get("genomic_span") if isinstance(item.get("genomic_span"), dict) else {}
    span_start = int(span.get("start")) if isinstance(span.get("start"), int) else 10**12
    return (
        transcript_match,
        scope_rank,
        orientation_rank,
        contiguous_rank,
        str(item.get("transcript_id") or ""),
        span_start,
    )


def _mapping_conservation_summary(
    *,
    species: str,
    segments: List[Tuple[str, int, int]],
) -> Dict[str, Any]:
    if not segments:
        return {}
    try:
        import pyBigWig  # type: ignore
    except Exception:
        return {}
    try:
        species_cfg = get_species_config(normalize_species(species))
    except Exception:
        return {}
    phast_path = Path(species_cfg.phastcons_path)
    phylop_path = Path(species_cfg.phylop_path)
    if not phast_path.exists() or not phylop_path.exists():
        return {}

    def _avg_over_segments(bw: Any) -> Optional[float]:
        total = 0.0
        count = 0
        for chrom, start, end in segments:
            if not chrom or end < start:
                continue
            start0 = max(0, int(start) - 1)
            end0 = int(end)
            values = None
            try:
                values = bw.values(str(chrom), start0, end0)
            except Exception:
                alt = str(chrom)[3:] if str(chrom).startswith("chr") else f"chr{chrom}"
                try:
                    values = bw.values(alt, start0, end0)
                except Exception:
                    values = None
            if not values:
                continue
            for value in values:
                if value is None:
                    continue
                try:
                    numeric = float(value)
                except Exception:
                    continue
                if numeric != numeric:
                    continue
                total += numeric
                count += 1
        if count <= 0:
            return None
        return float(total / count)

    phast_bw = None
    phylop_bw = None
    try:
        phast_bw = pyBigWig.open(os.fspath(phast_path))
        phylop_bw = pyBigWig.open(os.fspath(phylop_path))
        phast_avg = _avg_over_segments(phast_bw)
        phylop_avg = _avg_over_segments(phylop_bw)
    except Exception:
        return {}
    finally:
        try:
            if phast_bw is not None:
                phast_bw.close()
        except Exception:
            pass
        try:
            if phylop_bw is not None:
                phylop_bw.close()
        except Exception:
            pass
    summary: Dict[str, Any] = {}
    if phast_avg is not None:
        summary["phastcons"] = round(float(phast_avg), 6)
    if phylop_avg is not None:
        summary["phylop"] = round(float(phylop_avg), 6)
    return summary


def _fetch_transcript_locus_sequence(
    *,
    transcript_entry: Dict[str, Any],
    isoform_label: Optional[str],
    runtime: Any,
    genome: Any,
) -> Dict[str, Any]:
    if genome is None or not isinstance(transcript_entry, dict):
        return {}
    descriptor = _transcript_locus_descriptor(transcript_entry, isoform_label=isoform_label)
    if not descriptor:
        return {}
    fetch_slice = getattr(runtime, "_fetch_genome_slice", None)
    revcomp = getattr(runtime, "_revcomp", None)
    if not callable(fetch_slice):
        return {}
    locus_start = int(descriptor["locus_start"])
    locus_end = int(descriptor["locus_end"])
    seq = fetch_slice(genome, str(descriptor["chrom"]), max(0, locus_start - 1), locus_end)
    if not isinstance(seq, str) or not seq:
        return {}
    seq = seq.upper()
    if str(descriptor.get("strand") or "+") == "-":
        if callable(revcomp):
            seq = str(revcomp(seq) or "").upper()
        else:
            seq = _dna_reverse_complement(seq)
    descriptor["transcript_oriented_sequence"] = seq
    descriptor["transcript_oriented_length"] = len(seq)
    return descriptor


def _span_distance(start: int, end: int, position: int) -> int:
    if position < start:
        return start - position
    if position > end:
        return position - end
    return 0


def _build_sequence_mapping_hits(
    *,
    entry: Dict[str, Any],
    isoform_transcripts: Dict[str, Dict[str, Any]],
    cdna_map: Dict[str, str],
    runtime: Any,
    species: str,
    preferred_transcript_id: Optional[str],
    genome: Any,
    genomes_by_label: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    query_sequence = str(entry.get("sequence") or "").strip().upper()
    reverse_complement = str(entry.get("reverse_complement_sequence") or "").strip().upper()
    if not query_sequence:
        return []
    map_cdna_range = getattr(runtime, "_map_cdna_range_to_genomic_segments", None)
    continuous_span = getattr(runtime, "_continuous_genomic_span_from_segments", None)
    hits: List[Dict[str, Any]] = []
    search_terms: List[Tuple[str, str]] = [("input_sequence", query_sequence)]
    if reverse_complement and reverse_complement != query_sequence:
        search_terms.append(("reverse_complement", reverse_complement))
    for iso_label, cdna_sequence in cdna_map.items():
        if not isinstance(cdna_sequence, str) or not cdna_sequence:
            continue
        transcript_entry = isoform_transcripts.get(iso_label) if isinstance(isoform_transcripts.get(iso_label), dict) else {}
        reference_species = (transcript_entry.get("reference_binding") or {}).get("species") or species
        transcript_id = str(
            transcript_entry.get("transcript_id")
            or transcript_entry.get("id")
            or transcript_entry.get("metadata", {}).get("id")
            or iso_label
        ).strip()
        strand = _transcript_entry_strand_char(transcript_entry)
        for orientation, search_sequence in search_terms:
            for cdna_start in _find_sequence_occurrences(cdna_sequence.upper(), search_sequence):
                cdna_end = cdna_start + len(search_sequence) - 1
                segments = []
                if callable(map_cdna_range):
                    try:
                        segments = map_cdna_range(cdna_start, cdna_end, transcript_entry) or []
                    except Exception:
                        segments = []
                genomic_segments = [
                    {"chrom": str(chrom), "start": int(start), "end": int(end)}
                    for chrom, start, end in segments
                ]
                span_summary = None
                if callable(continuous_span):
                    try:
                        span_summary = continuous_span(segments)
                    except Exception:
                        span_summary = None
                contiguous = bool(
                    isinstance(span_summary, tuple)
                    and len(span_summary) == 4
                    and isinstance(span_summary[3], int)
                    and int(span_summary[3]) == len(search_sequence)
                )
                hit = {
                    "isoform_label": iso_label,
                    "transcript_id": transcript_id,
                    "match_orientation": orientation,
                    "matched_target_sequence": search_sequence,
                    "mapping_scope": "spliced_cdna",
                    "cdna_start": cdna_start,
                    "cdna_end": cdna_end,
                    "strand": strand,
                    "genomic_segments": genomic_segments,
                    "is_contiguous_genomic_span": contiguous,
                }
                if isinstance(span_summary, tuple) and len(span_summary) == 4:
                    hit["genomic_span"] = {
                        "chrom": span_summary[0],
                        "start": int(span_summary[1]),
                        "end": int(span_summary[2]),
                        "length": int(span_summary[3]),
                    }
                    if contiguous and genomic_segments:
                        hit.update(_mapping_conservation_summary(species=reference_species, segments=segments))
                hits.append(hit)
    search_terms = [("input_sequence", query_sequence)]
    if reverse_complement and reverse_complement != query_sequence:
        search_terms.append(("reverse_complement", reverse_complement))
    if genome is not None or genomes_by_label is not None:
        for iso_label, transcript_entry in isoform_transcripts.items():
            if not isinstance(transcript_entry, dict):
                continue
            local_genome = genomes_by_label.get(iso_label) if genomes_by_label is not None else genome
            if local_genome is None:
                continue
            reference_species = (transcript_entry.get("reference_binding") or {}).get("species") or species
            locus = _fetch_transcript_locus_sequence(
                transcript_entry=transcript_entry,
                isoform_label=iso_label,
                runtime=runtime,
                genome=local_genome,
            )
            locus_sequence = str(locus.get("transcript_oriented_sequence") or "").strip().upper()
            if not locus_sequence:
                continue
            transcript_id = str(locus.get("transcript_id") or iso_label or "").strip()
            strand = str(locus.get("strand") or transcript_entry.get("strand") or "+").strip() or "+"
            chrom = str(locus.get("chrom") or "").strip()
            locus_start = int(locus.get("locus_start") or 0)
            locus_end = int(locus.get("locus_end") or 0)
            if not transcript_id or not chrom or locus_start <= 0 or locus_end <= 0:
                continue
            for orientation, search_sequence in search_terms:
                for locus_pos in _find_sequence_occurrences(locus_sequence, search_sequence):
                    pos0 = locus_pos - 1
                    if strand == "-":
                        genomic_end = locus_end - pos0
                        genomic_start = genomic_end - len(search_sequence) + 1
                    else:
                        genomic_start = locus_start + pos0
                        genomic_end = genomic_start + len(search_sequence) - 1
                    if genomic_end < genomic_start:
                        genomic_start, genomic_end = genomic_end, genomic_start
                    segments = [(chrom, int(genomic_start), int(genomic_end))]
                    hit = {
                        "isoform_label": str(locus.get("isoform_label") or iso_label or transcript_id).strip() or transcript_id,
                        "transcript_id": transcript_id,
                        "match_orientation": orientation,
                        "matched_target_sequence": search_sequence,
                        "mapping_scope": "pre_mrna_locus",
                        "strand": strand,
                        "locus_relative_start": int(locus_pos),
                        "locus_relative_end": int(locus_pos + len(search_sequence) - 1),
                        "locus_span": {
                            "chrom": chrom,
                            "start": locus_start,
                            "end": locus_end,
                            "length": int(locus.get("locus_length") or len(locus_sequence)),
                        },
                        "genomic_segments": [{"chrom": chrom, "start": int(genomic_start), "end": int(genomic_end)}],
                        "is_contiguous_genomic_span": True,
                        "genomic_span": {
                            "chrom": chrom,
                            "start": int(genomic_start),
                            "end": int(genomic_end),
                            "length": int(genomic_end - genomic_start + 1),
                        },
                    }
                    hit.update(_mapping_conservation_summary(species=reference_species, segments=segments))
                    hits.append(hit)

    deduped: List[Dict[str, Any]] = []
    seen = set()
    for hit in hits:
        span = hit.get("genomic_span") if isinstance(hit.get("genomic_span"), dict) else {}
        key = (
            str(hit.get("transcript_id") or ""),
            str(hit.get("match_orientation") or ""),
            str(hit.get("mapping_scope") or ""),
            int(span.get("start")) if isinstance(span.get("start"), int) else -1,
            int(span.get("end")) if isinstance(span.get("end"), int) else -1,
            str(span.get("chrom") or ""),
            hit.get("strand"), hit.get("cdna_start"), hit.get("cdna_end"),
            tuple((segment.get("chrom"), segment.get("start"), segment.get("end"))
                  for segment in hit.get("genomic_segments") or []),
        )
        if key in seen:
            continue
        seen.add(key)
        deduped.append(hit)
    deduped.sort(key=lambda item: _mapping_hit_sort_key(item, preferred_transcript_id=preferred_transcript_id))
    return deduped


def _best_locus_near_matches(
    *,
    entry: Dict[str, Any],
    isoform_transcripts: Dict[str, Dict[str, Any]],
    runtime: Any,
    genome: Any,
    preferred_transcript_id: Optional[str],
    max_results: int = 5,
    genomes_by_label: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    query_sequence = str(entry.get("sequence") or "").strip().upper()
    reverse_complement = str(entry.get("reverse_complement_sequence") or "").strip().upper()
    if not query_sequence or (genome is None and genomes_by_label is None):
        return []
    search_terms: List[Tuple[str, str]] = [("input_sequence", query_sequence)]
    if reverse_complement and reverse_complement != query_sequence:
        search_terms.append(("reverse_complement", reverse_complement))
    candidates: List[Dict[str, Any]] = []
    for iso_label, transcript_entry in isoform_transcripts.items():
        if not isinstance(transcript_entry, dict):
            continue
        local_genome = genomes_by_label.get(iso_label) if genomes_by_label is not None else genome
        if local_genome is None:
            continue
        locus = _fetch_transcript_locus_sequence(
            transcript_entry=transcript_entry,
            isoform_label=iso_label,
            runtime=runtime,
            genome=local_genome,
        )
        locus_sequence = str(locus.get("transcript_oriented_sequence") or "").strip().upper()
        if not locus_sequence:
            continue
        transcript_id = str(locus.get("transcript_id") or iso_label or "").strip()
        strand = str(locus.get("strand") or transcript_entry.get("strand") or "+").strip() or "+"
        chrom = str(locus.get("chrom") or "").strip()
        locus_start = int(locus.get("locus_start") or 0)
        locus_end = int(locus.get("locus_end") or 0)
        for orientation, search_sequence in search_terms:
            if len(search_sequence) > len(locus_sequence):
                continue
            best_local: Optional[Dict[str, Any]] = None
            from .mapping_evidence import nearest_windows, mismatch_annotations
            for pos0, mismatches in nearest_windows(locus_sequence, search_sequence, limit=1):
                window = locus_sequence[pos0:pos0 + len(search_sequence)]
                if best_local is None or mismatches < int(best_local["mismatch_count"]):
                    if strand == "-":
                        genomic_end = locus_end - pos0
                        genomic_start = genomic_end - len(search_sequence) + 1
                    else:
                        genomic_start = locus_start + pos0
                        genomic_end = genomic_start + len(search_sequence) - 1
                    best_local = {
                        "isoform_label": str(locus.get("isoform_label") or iso_label or transcript_id).strip() or transcript_id,
                        "transcript_id": transcript_id,
                        "mapping_scope": "pre_mrna_locus",
                        "search_scope": "Best ungapped window per transcript/orientation; first tied position. Up to the declared number of transcripts per orientation, plus the requested transcript, are retained. No indels or activity threshold.",
                        "match_orientation": orientation,
                        "binding_interpretation": (
                            "antisense_binding_hypothesis_for_supplied_5prime_to_3prime_oligo"
                            if orientation == "reverse_complement" else
                            "same_strand_similarity_only; binding_requires_input_to_be_a_target_site_sequence"
                        ),
                        **mismatch_annotations(window, search_sequence, orientation),
                        "coordinate_system": "1based_inclusive",
                        "mismatch_count": int(mismatches),
                        "matched_window_sequence": window,
                        "locus_relative_start": int(pos0 + 1),
                        "locus_relative_end": int(pos0 + len(search_sequence)),
                        "genomic_span": {
                            "chrom": chrom,
                            "start": int(min(genomic_start, genomic_end)),
                            "end": int(max(genomic_start, genomic_end)),
                            "length": int(len(search_sequence)),
                        },
                        "strand": strand,
                    }
                    if mismatches == 0:
                        break
            if best_local:
                candidates.append(best_local)
    candidates.sort(
        key=lambda item: (
            int(item["mismatch_count"]),
            0 if preferred_transcript_id and str(item.get("transcript_id") or "").strip() == preferred_transcript_id else 1,
            0 if str(item.get("match_orientation") or "") == "reverse_complement" else 1,
            str(item.get("transcript_id") or ""),
            int((item.get("genomic_span") or {}).get("start") or 10**12),
        )
    )
    # Same-strand exact overlaps must not crowd out the independently searched
    # antisense hypotheses. Preserve the requested reference in each orientation
    # even when other catalog transcripts have closer windows.
    retained: List[Dict[str, Any]] = []
    preferred_base = str(preferred_transcript_id or "").split(".")[0]
    for orientation, _ in search_terms:
        group = [item for item in candidates if item["match_orientation"] == orientation]
        selected = group[:max_results]
        requested = next((item for item in group if preferred_base and
                          str(item.get("transcript_id") or "").split(".")[0] == preferred_base), None)
        if requested is not None and requested not in selected:
            selected.append(requested)
        retained.extend(selected)
    return retained


def _build_transcript_splice_sites_for_eval(
    transcript_entry: Optional[Dict[str, Any]],
    window_bp: int = 10,
    *,
    include_terminal_boundaries: bool = True,
) -> List[Dict[str, Any]]:
    if not isinstance(transcript_entry, dict):
        return []
    exons_tx = _transcript_entry_exons(transcript_entry)
    if not exons_tx:
        return []
    chrom = str(
        transcript_entry.get("chrom")
        or transcript_entry.get("seq_region_name")
        or transcript_entry.get("metadata", {}).get("seq_region_name")
        or exons_tx[0].get("seq_region_name")
        or ""
    ).strip()
    if not chrom:
        return []
    strand = _transcript_entry_strand_char(transcript_entry)
    sites: List[Dict[str, Any]] = []
    for ordinal, exon in enumerate(exons_tx):
        try:
            exon_index = int(exon.get("index"))
            exon_start = int(exon.get("start"))
            exon_end = int(exon.get("end"))
        except Exception:
            continue
        if strand == "-":
            acceptor_pos = max(exon_start, exon_end)
            donor_pos = min(exon_start, exon_end)
        else:
            acceptor_pos = min(exon_start, exon_end)
            donor_pos = max(exon_start, exon_end)
        for site_kind, position in (("acceptor", acceptor_pos), ("donor", donor_pos)):
            if not include_terminal_boundaries and (
                (site_kind == "acceptor" and ordinal == 0)
                or (site_kind == "donor" and ordinal == len(exons_tx) - 1)
            ):
                continue
            sites.append(
                {
                    "label": f"{site_kind}@{position}",
                    "display_label": f"{site_kind}@{position}",
                    "canonical_label": f"{site_kind}@{position}",
                    "site_kind": site_kind,
                    "transcript_id": (transcript_entry.get("metadata") or {}).get("versioned_id")
                    or transcript_entry.get("versioned_id") or transcript_entry.get("transcript_id") or transcript_entry.get("id"),
                    "exon_index": exon_index,
                    "window_bp": window_bp,
                    "acceptor": {
                        "chrom": chrom,
                        "position": acceptor_pos,
                        "start": max(1, acceptor_pos - window_bp),
                        "end": acceptor_pos + window_bp,
                        "window_bp": window_bp,
                        "strand": strand,
                    },
                    "donor": {
                        "chrom": chrom,
                        "position": donor_pos,
                        "start": max(1, donor_pos - window_bp),
                        "end": donor_pos + window_bp,
                        "window_bp": window_bp,
                        "strand": strand,
                    },
                }
            )
    return sites


def _filter_splice_sites_by_targets(
    splice_sites: List[Dict[str, Any]],
    evaluation_targets: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    from .evaluation_feature_identity import is_resolved_feature_identity
    if not splice_sites or not evaluation_targets:
        return []
    matched: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, int, str]] = set()
    for site in splice_sites:
        exon_index = site.get("exon_index")
        site_kind = _normalize_eval_site_kind(site.get("site_kind")) or str(site.get("site_kind") or "").strip().lower()
        acceptor = site.get("acceptor") if isinstance(site.get("acceptor"), dict) else {}
        donor = site.get("donor") if isinstance(site.get("donor"), dict) else {}
        chrom = str(acceptor.get("chrom") or donor.get("chrom") or "").strip()
        strand = str(acceptor.get("strand") or donor.get("strand") or "").strip()
        position = acceptor.get("position") if site_kind == "acceptor" else donor.get("position")
        for target in evaluation_targets:
            if isinstance(target.get("splice_relative_window"), dict):
                relative = target.get("relative_window_resolution") or {}
                if relative.get("status") != "resolved":
                    continue
                # The window identifies a feature anchored to this boundary;
                # its interval endpoints are not splice-site coordinates.
                target = {
                    "transcript_id": target.get("transcript_id"),
                    "site_kind": relative["anchor_site"],
                    "exon_identity_resolution": relative["anchor_identity_resolution"],
                }
            target_tid = str(target.get("transcript_id") or "")
            site_tid = str(site.get("transcript_id") or "")
            if target_tid:
                if not site_tid or target_tid.split(".")[0] != site_tid.split(".")[0]:
                    continue
                if "." in target_tid and target_tid != site_tid:
                    continue
            target_site_kind = _normalize_eval_site_kind(target.get("site_kind"))
            target_exon = target.get("exon_index", target.get("exon_label"))
            target_chrom = str(target.get("chrom") or "").strip()
            target_strand = str(target.get("strand") or "").strip()
            target_position = target.get("position")
            identity = target.get("exon_identity_resolution")
            if isinstance(identity, dict):
                target_exon = None
                if is_resolved_feature_identity(identity):
                    feature_start, feature_end = identity.get("start"), identity.get("end")
                    if not isinstance(feature_start, int) or not isinstance(feature_end, int):
                        continue
                    negative = identity.get("strand") == "-"
                    identity_position = (feature_start if negative else feature_end) if site_kind == "donor" else (feature_end if negative else feature_start)
                    identity_chrom = str(identity.get("chrom") or "")
                    identity_strand = str(identity.get("strand") or "")
                    # Every explicit constraint must agree with the resolved
                    # feature; a name must not replace a conflicting position.
                    if isinstance(target_position, int) and target_position != identity_position:
                        continue
                    if target_chrom and identity_chrom and target_chrom.removeprefix("chr") != identity_chrom.removeprefix("chr"):
                        continue
                    if target_strand and identity_strand and target_strand != identity_strand:
                        continue
                    target_position = identity_position
                    target_chrom = target_chrom or identity_chrom
                    target_strand = target_strand or identity_strand
                elif not isinstance(target_position, int):
                    continue  # An unresolved biological name selects no ordinal boundary.
            # A transcript-level outcome or an unresolved named feature does
            # not select every boundary in that transcript.
            if not (target_site_kind or isinstance(target_exon, int) or isinstance(target_position, int)):
                continue
            if target_site_kind and target_site_kind != site_kind:
                continue
            if isinstance(target_exon, int) and exon_index != target_exon:
                continue
            if target_chrom and chrom and target_chrom.removeprefix("chr") != chrom.removeprefix("chr"):
                continue
            if target_strand and strand and target_strand != strand:
                continue
            if isinstance(target_position, int) and isinstance(position, int) and target_position != position:
                continue
            key = (str(site.get("canonical_label") or site.get("label") or ""), int(exon_index or -1), site_kind)
            if key in seen:
                break
            seen.add(key)
            matched.append(site)
            break
    return matched


def _select_relevant_splice_sites(
    *,
    splice_sites: List[Dict[str, Any]],
    evaluation_targets: List[Dict[str, Any]],
    entries: List[Dict[str, Any]],
    max_sites_per_entry: int = 2,
) -> List[Dict[str, Any]]:
    from .splicing_agent import SPLICE_EVAL_NEARBY_SITE_RADIUS_BP
    if not splice_sites:
        return []
    targeted_sites = _filter_splice_sites_by_targets(splice_sites, evaluation_targets)
    selected: List[Dict[str, Any]] = []
    seen: Set[Tuple[Any, ...]] = set()

    def include(site: Dict[str, Any]) -> None:
        kind = _normalize_eval_site_kind(site.get("site_kind"))
        point = site.get(kind) if kind else None
        if not isinstance(point, dict) or not isinstance(point.get("position"), int):
            return
        key = (str(point.get("chrom") or "").removeprefix("chr"),
               str(point.get("strand") or ""), str(site.get("transcript_id") or ""),
               kind, point["position"])
        if key not in seen:
            seen.add(key)
            selected.append(site)

    for site in targeted_sites:
        include(site)
    for entry in entries:
        genomic_span = entry.get("genomic_span") if isinstance(entry.get("genomic_span"), dict) else {}
        start = genomic_span.get("start")
        end = genomic_span.get("end")
        chrom = str(genomic_span.get("chrom") or "").strip()
        if not isinstance(start, int) or not isinstance(end, int) or not chrom:
            continue
        # Match the scoring backend's midpoint convention (input span is 1-based).
        midpoint = (start - 1 + end) // 2 + 1
        entry_tid = str(entry.get("transcript_id") or "")
        entry_strand = str(entry.get("strand") or "")
        ranked: List[Tuple[int, int, str, Dict[str, Any]]] = []
        for site in splice_sites:
            site_kind = _normalize_eval_site_kind(site.get("site_kind")) or str(site.get("site_kind") or "").strip().lower()
            site_payload = site.get("acceptor") if site_kind == "acceptor" else site.get("donor")
            if not isinstance(site_payload, dict):
                continue
            site_chrom = str(site_payload.get("chrom") or "").strip()
            site_position = site_payload.get("position")
            if site_chrom.removeprefix("chr") != chrom.removeprefix("chr") or not isinstance(site_position, int):
                continue
            site_tid = str(site.get("transcript_id") or "")
            if entry_tid and (not site_tid or entry_tid.split(".")[0] != site_tid.split(".")[0]
                              or ("." in entry_tid and entry_tid != site_tid)):
                continue
            if entry_strand and site_payload.get("strand") and entry_strand != str(site_payload["strand"]):
                continue
            ranked.append(
                (
                    abs(midpoint - site_position),
                    0 if site_kind == "acceptor" else 1,
                    str(site.get("canonical_label") or site.get("label") or ""),
                    site,
                )
            )
        ranked.sort(key=lambda item: (item[0], item[1], item[2]))
        # Requested outcomes do not replace collateral binding-site context.
        # Retain every boundary the backend can score, plus nearest boundaries
        # for an explicit distance observation when all are outside its radius.
        for rank, (distance, _kind_rank, _label, site) in enumerate(ranked):
            if rank < max_sites_per_entry or distance <= SPLICE_EVAL_NEARBY_SITE_RADIUS_BP:
                include(site)
    return selected


def _fallback_splice_sites_for_eval(
    transcript_entry: Optional[Dict[str, Any]],
    evaluation_targets: List[Dict[str, Any]],
    window_bp: int = 10,
) -> List[Dict[str, Any]]:
    return _build_transcript_splice_sites_for_eval(
        transcript_entry, window_bp=window_bp, include_terminal_boundaries=False,
    )


def _provided_splice_site_context(
    transcript_entry: Optional[Dict[str, Any]],
    transcript_id: str,
    planned_sites: List[Dict[str, Any]],
    evaluation_targets: List[Dict[str, Any]],
    entries: List[Dict[str, Any]],
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    from .splicing_agent import SPLICE_EVAL_NEARBY_SITE_RADIUS_BP
    from .explicit_target_identity import chromosome, strand_symbol

    reference_tid = str(((transcript_entry or {}).get("metadata") or {}).get("versioned_id")
                        or (transcript_entry or {}).get("versioned_id")
                        or (transcript_entry or {}).get("transcript_id")
                        or (transcript_entry or {}).get("id") or transcript_id)
    reference_compatible = (reference_tid.split(".")[0] == transcript_id.split(".")[0]
                            and ("." not in transcript_id or reference_tid == transcript_id))
    annotated = (_fallback_splice_sites_for_eval(transcript_entry, evaluation_targets)
                 if reference_compatible else [])
    locus = _transcript_locus_descriptor(transcript_entry) if transcript_entry else {}
    planned = []
    for site in planned_sites:
        if not isinstance(site, dict):
            continue
        tid = str(site.get("transcript_id") or reference_tid)
        if not reference_compatible or tid.split(".")[0] != reference_tid.split(".")[0] or ("." in tid and tid != reference_tid):
            continue
        points = [site.get(kind) for kind in ("acceptor", "donor")]
        if not all(isinstance(point, dict) for point in points):
            continue
        if locus and any(
            chromosome(point.get("chrom")) != chromosome(locus.get("chrom"))
            or strand_symbol(point.get("strand")) not in (None, strand_symbol(locus.get("strand")))
            for point in points
        ):
            continue
        planned.append({**site, "transcript_id": reference_tid})
    sites = _select_relevant_splice_sites(
        splice_sites=[*planned, *annotated], evaluation_targets=evaluation_targets, entries=entries,
    )
    scope = {
        "transcript_id": reference_tid if reference_compatible else transcript_id,
        "reference_identity_compatible": reference_compatible,
        "coordinate_system": "1based_inclusive",
        "annotated_internal_boundary_count": len(annotated),
        "planned_site_count": len(planned),
        "excluded_incompatible_planned_site_count": len(planned_sites) - len(planned),
        "nearby_radius_from_aso_midpoint_bp": SPLICE_EVAL_NEARBY_SITE_RADIUS_BP,
        "selection_policy": "Requested target boundaries plus all annotated internal exon boundaries within the scoring radius of each mapped ASO, and its two nearest available boundaries. Transcript terminal ends are not added as annotated splice junctions. Explicit planned sites may also be present.",
        "selected_sites": [{
            "label": site.get("canonical_label") or site.get("label"),
            "site_kind": site.get("site_kind"), "exon_index": site.get("exon_index"),
            "transcript_id": site.get("transcript_id"),
            **{key: (site.get(site.get("site_kind")) or {}).get(key)
               for key in ("chrom", "strand", "position")},
        } for site in sites],
        "coverage": "annotated_transcript_and_planned_sites" if annotated else "planned_sites_only" if planned else "unavailable",
        "interpretation": "Scope of candidate measurement sites, not proof that every site was scored for every ASO. Use each row's recorded deltas and skip reason; unannotated cryptic sites and unsearched transcripts are not exhaustively assessed.",
    }
    return sites, scope


def _record_provided_splice_skip(entry: Dict[str, Any], reason: str) -> None:
    summary = {"splice_eval_status": f"skipped_{reason}", "splice_eval_skip_reason": reason}
    entry["splice_eval_summary"] = summary
    stages = entry.setdefault("stage_results", {})
    stages["splice_eval"] = _splice_stage_from_scored_row(summary)


