def _maybe_resolve_eval_gene_id(
    eval_goal: Dict[str, Any],
    runtime: Any,
) -> Dict[str, Any]:
    if str(eval_goal.get("gene_id") or "").strip():
        return {"status": "already_available", "gene_id": str(eval_goal.get("gene_id") or "").strip()}
    if not str(eval_goal.get("gene_symbol") or "").strip():
        return {"status": "not_run", "reason": "gene_symbol_missing"}
    resolve_gene_id = getattr(runtime, "_resolve_gene_id", None)
    if not callable(resolve_gene_id):
        return {"status": "not_run", "reason": "runtime_gene_resolver_missing"}
    final_payload: Dict[str, Any] = {}
    try:
        resolved = resolve_gene_id(eval_goal, final_payload, allow_interactive=False)
    except Exception as exc:
        return {"status": "error", "error": f"gene_resolution_failed:{exc}"}
    resolved_text = str(resolved or eval_goal.get("gene_id") or final_payload.get("gene_id") or "").strip()
    if not resolved_text:
        return {"status": "not_resolved", "reason": "gene_id_lookup_empty"}
    if isinstance(final_payload.get("gene_id_resolution"), dict) and not isinstance(eval_goal.get("gene_id_resolution"), dict):
        eval_goal["gene_id_resolution"] = deepcopy(final_payload["gene_id_resolution"])
    eval_goal["gene_id"] = resolved_text
    return {"status": "resolved", "gene_id": resolved_text}


def _provided_aso_scoring_sequence(entry: Dict[str, Any]) -> str:
    role = interpret_orientation(entry).get("provided_sequence_role")
    if role in {"antisense_oligo_sequence", "target_site_sequence"}:
        sequence = str(_normalize_aso_sequence(entry.get("sequence")).get("sequence") or "")
        if sequence:
            return _dna_reverse_complement(sequence) if role == "antisense_oligo_sequence" else sequence
    for field in ("comparison_sequence", "normalized_sequence", "target_sequence", "sequence"):
        sequence = _normalize_aso_sequence(entry.get(field)).get("sequence")
        text = str(sequence or "").strip().upper()
        if text:
            return text
    return ""


def _build_provided_aso_scoring_tiles(rows: List[Dict[str, Any]]) -> Tuple[List[Dict[str, Any]], Dict[int, Dict[str, Any]]]:
    tile_rows: List[Dict[str, Any]] = []
    row_by_index: Dict[int, Dict[str, Any]] = {}
    for idx, entry in enumerate(rows):
        if not isinstance(entry, dict):
            continue
        sequence = _provided_aso_scoring_sequence(entry)
        if not sequence:
            continue
        name = str(entry.get("name") or entry.get("aso_id") or f"provided_aso_{idx + 1:02d}").strip()
        seq_payload = _normalize_aso_sequence(sequence)
        genomic_span = entry.get("genomic_span") if isinstance(entry.get("genomic_span"), dict) else {}
        chrom = str(genomic_span.get("chrom") or "").strip()
        start = _optional_int(genomic_span.get("start"))
        end = _optional_int(genomic_span.get("end"))
        role = interpret_orientation(entry).get("provided_sequence_role")
        query_role = (
            "Transcript-oriented reverse complement of the supplied antisense molecule; an exact binding site need not be established."
            if role == "antisense_oligo_sequence" else
            "Supplied transcript-oriented target-site sequence."
            if role == "target_site_sequence" else
            "Input role unresolved; junction interpretation is conditional on the recorded query's orientation."
        )
        tile_row: Dict[str, Any] = {
            "id": f"provided_{idx + 1:05d}",
            "Name": name or f"provided_aso_{idx + 1:02d}",
            "name": name or f"provided_aso_{idx + 1:02d}",
            "provided_row_index": idx,
            "provided_input_sequence": entry.get("sequence"),
            "Sequence": sequence,
            "off_target_query_role": query_role,
            "GC": seq_payload.get("gc_fraction"),
            "source": "provided_aso_evaluation",
            "mapping_status": entry.get("mapping_status"),
            "mapping_scope": entry.get("mapping_scope"),
            "transcript_id": entry.get("transcript_id"),
            "isoform_label": entry.get("isoform_label"),
        }
        if entry.get("chemistry") not in (None, "", [], {}):
            tile_row["Chemistry"] = entry.get("chemistry")
        if entry.get("source_file") not in (None, "", [], {}):
            tile_row["source_file"] = entry.get("source_file")
        if entry.get("source_row") not in (None, "", [], {}):
            tile_row["source_row"] = entry.get("source_row")
        if chrom:
            tile_row["Chrom"] = chrom
        if start is not None:
            tile_row["Start"] = max(0, int(start) - 1)
        if end is not None:
            tile_row["End"] = int(end)
        if entry.get("strand") not in (None, "", [], {}):
            tile_row["Strand"] = entry.get("strand")
        if entry.get("phastcons") is not None:
            tile_row["Phastcon"] = entry.get("phastcons")
        if entry.get("phylop") is not None:
            tile_row["PhyloP"] = entry.get("phylop")
        tile_rows.append(tile_row)
        row_by_index[idx] = entry
    return tile_rows, row_by_index


def _write_provided_aso_tiles_json(
    *,
    output_dir: Path,
    tile_rows: List[Dict[str, Any]],
) -> Path:
    columns: Dict[str, str] = {
        "id": "string",
        "Name": "string",
        "name": "string",
        "provided_row_index": "integer",
        "provided_input_sequence": "string",
        "Sequence": "string",
        "off_target_query_role": "string",
        "GC": "number",
        "source": "string",
        "mapping_status": "string",
        "mapping_scope": "string",
        "transcript_id": "string",
        "isoform_label": "string",
        "Chemistry": "string",
        "source_file": "string",
        "source_row": "integer",
        "Chrom": "string",
        "Start": "integer",
        "End": "integer",
        "Strand": "string",
        "Phastcon": "number",
        "PhyloP": "number",
    }
    output_dir.mkdir(parents=True, exist_ok=True)
    path = output_dir / "provided_aso_scoring_tiles.json"
    payload = {
        "schema": {
            "table": "provided_aso_scoring_tiles",
            "primary_key": "id",
            "columns": columns,
            "notes": "Synthetic tile table built from user-provided ASOs for generic scoring stages.",
        },
        "rows": tile_rows,
    }
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return path


def _enrich_exact_off_target_bins_for_tiles(tiles_json_path: str, count_scope=None) -> Dict[str, Any]:
    from .mismatch_screening import annotate_mismatch_bins
    path = Path(str(tiles_json_path or ""))
    if not path.exists():
        return {"status": "not_run", "error": "tiles_json_missing"}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        return {"status": "error", "error": f"tiles_json_read_failed:{exc}"}
    rows = payload.get("rows") if isinstance(payload, dict) else []
    if not isinstance(rows, list):
        return {"status": "error", "error": "tiles_json_rows_invalid"}
    updated = 0
    for row in rows:
        if not isinstance(row, dict):
            continue
        gene_ids = _normalize_text_list(row.get("Off_target_gene_ids") or row.get("off_target_gene_ids"))
        gene_names = _normalize_text_list(row.get("Off_target_genes") or row.get("off_target_genes"))
        gene_count = _optional_int(row.get("off_target_gene_count"))
        junction = (count_scope or {}).get("junction_search_summary") or {}
        incomplete = bool(row.get("off_target_mapping_capped") or row.get("off_target_unclassified_alignments")
                          or junction.get("error") or junction.get("skipped_chrom")
                          or junction.get("skipped_ambiguous_windows"))
        budget = (count_scope or {}).get("mismatch_budget", 0)
        if budget:
            annotate_mismatch_bins(row, budget, incomplete)
            row["off_target_query_sequence"] = row.get("Sequence")
            row["off_target_count_scope"] = deepcopy(count_scope)
            updated += 1
            continue
        row["off_target_observed_gene_count"] = gene_count
        row["off_target_count_status"] = "incomplete" if incomplete else "complete_within_declared_scope" if gene_count is not None else "unavailable"
        if incomplete:
            gene_count = None
            row["off_target_gene_count"] = None
            row["Times_mapped_off_target_genes"] = None
        row["Off_target_exact_count"] = gene_count
        row["off_target_exact_count_unit"] = "genes"
        row["Off_target_total_upto_mismatch_count"] = gene_count
        row["Off_target_mismatch_budget"] = 0
        row["Off_target_weighted_risk_score"] = float(gene_count) if gene_count is not None else None
        row["Off_target_0mm_gene_ids"] = gene_ids
        row["Off_target_0mm_genes"] = gene_names
        row["Off_target_gene_ids_by_mismatch"] = {"0mm": gene_ids, "1mm": None, "2mm": None, "3mm": None}
        row["Off_target_genes_by_mismatch"] = {"0mm": gene_names, "1mm": None, "2mm": None, "3mm": None}
        row["off_target_query_sequence"] = row.get("Sequence")
        row.setdefault("off_target_query_role", "Mapped transcript-oriented target site when available; otherwise the supplied sequence as received. Genomic matching tests both strands; junction interpretation is conditional on the recorded query's role.")
        if count_scope:
            row["off_target_count_scope"] = deepcopy(count_scope)
        updated += 1
    schema = payload.setdefault("schema", {})
    columns = schema.setdefault("columns", {})
    if isinstance(columns, dict):
        columns["Off_target_exact_count"] = "number"
        columns["Off_target_total_upto_mismatch_count"] = "number"
        columns["Off_target_mismatch_budget"] = "number"
        columns["Off_target_weighted_risk_score"] = "number"
        columns["Off_target_0mm_gene_ids"] = "string"
        columns["Off_target_0mm_genes"] = "string"
        columns["Off_target_gene_ids_by_mismatch"] = "object"
        columns["Off_target_genes_by_mismatch"] = "object"
        columns["off_target_count_scope"] = "object"
        columns["off_target_count_status"] = "string"
        columns["off_target_query_sequence"] = "string"
        columns["off_target_query_role"] = "string"
        columns["off_target_observed_gene_count"] = "number"
        for mm in (1, 2, 3):
            columns[f"Off_target_{mm}mm_count"] = "number"
    try:
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception as exc:
        return {"status": "error", "error": f"tiles_json_write_failed:{exc}"}
    return {"status": "complete", "updated_rows": updated}


def _merge_scored_tiles_into_provided_asos(
    rows: List[Dict[str, Any]],
    scored_rows: List[Dict[str, Any]],
) -> Dict[str, Any]:
    by_index: Dict[int, Dict[str, Any]] = {}
    for scored in scored_rows:
        if not isinstance(scored, dict):
            continue
        idx = _optional_int(scored.get("provided_row_index"))
        if idx is None:
            continue
        by_index[int(idx)] = scored

    merged = 0
    ranked = 0
    off_target_scored = 0
    uniqueness_scored = 0
    for idx, entry in enumerate(rows):
        if not isinstance(entry, dict):
            continue
        scored = by_index.get(idx)
        if not scored:
            continue
        for field in _PROVIDED_ASO_SCORED_TILE_FIELDS:
            if scored.get(field) not in (None, "", [], {}):
                entry[field] = deepcopy(scored[field])
        if scored.get("off_target_count_status") in {"incomplete", "unavailable", "not_run"}:
            for field in ("off_target_gene_count", "Off_target_exact_count", "Times_mapped_off_target_genes",
                          "Off_target_total_upto_mismatch_count", "Off_target_weighted_risk_score",
                          "Off_target_1mm_count", "Off_target_2mm_count", "Off_target_3mm_count"):
                entry[field] = None
        if scored.get("off_target_gene_count") is not None or scored.get("Off_target_exact_count") is not None:
            off_target_scored += 1
        if scored.get("isoform_uniqueness_score") is not None or scored.get("isoform_uniqueness_count") is not None:
            uniqueness_scored += 1
        if scored.get("selection_rank") is not None:
            ranked += 1
        stage_results = entry.get("stage_results") if isinstance(entry.get("stage_results"), dict) else {}
        if scored.get("off_target_gene_count") is not None or scored.get("Off_target_exact_count") is not None:
            stage_results["off_target_mapping"] = {
                "status": "pass",
                "reason_code": "provided_aso_scoped_offtarget",
                "method": "ungapped_genome_exon_junction_mapping",
                "mismatch_budget": scored.get("Off_target_mismatch_budget", 0),
            }
        elif scored.get("off_target_count_status") == "not_run":
            stage_results["off_target_mapping"] = {
                "status": "not_run", "reason_code": "excluded_by_task_scope"}
        elif scored.get("off_target_count_status") in {"incomplete", "unavailable"}:
            stage_results["off_target_mapping"] = {"status": scored["off_target_count_status"],
                "reason_code": "count_search_incomplete_or_unavailable", "method": "ungapped_genome_exon_junction_mapping"}
        if scored.get("isoform_uniqueness_score") is not None or scored.get("isoform_uniqueness_count") is not None:
            stage_results["uniqueness_scoring"] = {
                "status": "pass",
                "reason_code": "provided_aso_isoform_uniqueness",
            }
        if scored.get("selection_rank") is not None:
            stage_results["ranking"] = {
                "status": "pass",
                "reason_code": "provided_aso_selection_rank",
                "method": "lexicographic_required_evidence_then_offtarget_then_uniqueness_then_sequence_proxies",
            }
        entry["stage_results"] = stage_results
        merged += 1
    return {
        "merged_rows": merged,
        "off_target_scored_rows": off_target_scored,
        "uniqueness_scored_rows": uniqueness_scored,
        "ranked_rows": ranked,
    }


def _splice_summary_from_scored_row(scored_row: Dict[str, Any]) -> Dict[str, Any]:
    """Keep each prediction under its recorded metric and reference identity.

    Primary/selected deltas can describe an individual donor or acceptor. They
    are not substitutes for an absent paired exon-inclusion proxy. Preserve
    the per-site records so report composition can resolve that distinction.
    """
    summary: Dict[str, Any] = {
        "delta_inclusion_deletion": scored_row.get("delta_inclusion_deletion"),
        "delta_inclusion_replacement": scored_row.get("delta_inclusion_replacement"),
        "delta_names": scored_row.get("delta_names"),
        "delta_deletion": scored_row.get("delta_deletion"),
        "delta_replacement": scored_row.get("delta_replacement"),
        "shared_context_label": scored_row.get("shared_context_label"),
        "shared_context_delta": scored_row.get("shared_context_delta"),
    }
    for key in (
        "splice_site_deltas",
        "primary_label",
        "primary_direction",
        "primary_delta_deletion",
        "primary_delta_replacement",
        "selected_label",
        "selected_direction",
        "selected_site_kind",
        "selected_site_position",
        "selected_delta_deletion",
        "selected_delta_replacement",
        "splice_eval_status",
        "splice_eval_skip_reason",
        "nearest_splice_site_distance_bp",
        "nearest_splice_site_kind",
        "nearest_splice_site_position",
        "nearest_splice_site_label",
        "nearest_splice_site_exon_index",
        "nearest_splice_site_isoform_label",
        "aso_mid",
        "aso_start",
        "aso_end",
    ):
        if scored_row.get(key) not in (None, "", [], {}):
            summary[key] = deepcopy(scored_row[key])
    return summary


def _splice_stage_from_scored_row(scored_row: Dict[str, Any]) -> Dict[str, Any]:
    status = str(scored_row.get("splice_eval_status") or "").strip().lower()
    if status.startswith("skipped"):
        stage: Dict[str, Any] = {
            "status": "skipped",
            "reason_code": status,
        }
        reason = str(scored_row.get("splice_eval_skip_reason") or "").strip()
        if reason:
            stage["details"] = reason
        return stage
    if status in {"failed", "error"}:
        return {"status": "fail", "reason_code": status}
    if (
        scored_row.get("delta_inclusion_deletion") is not None
        or scored_row.get("delta_inclusion_replacement") is not None
        or scored_row.get("delta_names") not in (None, "", [], {})
    ):
        return {"status": "pass", "reason_code": "splice_eval_scored"}
    return {"status": "not_run"}


def _scope_splice_proxy_ranks(rows):
    for row in rows:
        for old, new in (("selection_rank", "knockdown_proxy_rank"), ("selection_score_components", "knockdown_proxy_score_components")):
            if old in row:
                row[new] = row.pop(old)
        row["ranking_scope"] = "knockdown_proxy_only; not a splice efficacy ranking"


def _score_provided_asos_with_existing_pipeline(
    *,
    rows: List[Dict[str, Any]],
    eval_goal: Dict[str, Any],
    cdna_map: Dict[str, str],
    iso_label: Optional[str],
    runtime: Any,
    run_dir: str,
    task_id: str,
    splice_related: bool = False,
    reference_transcript_id: Optional[str] = None,
) -> Dict[str, Any]:
    scoring_summary: Dict[str, Any] = {
        "status": "not_run",
        "method": "provided_sequence_measurements_with_chemistry_scoped_ranking",
        "notes": [
            "Sequences are scored using their mapped transcript-oriented target-site sequence when available.",
            "Gene-screening counts combine exon-contained genomic matches and adjacent annotated junction matches at the recorded substitution budget under off_target_count_scope. The entire target gene is excluded. Higher mismatch budgets, indels and intronic-only selectivity are not established; this is not a genome-wide binding count.",
        ],
    }
    if not rows:
        scoring_summary["reason"] = "no_rows"
        return scoring_summary

    output_dir = _task_output_dir(run_dir, task_id) / "provided_aso_scoring"
    tile_rows, _row_lookup = _build_provided_aso_scoring_tiles(rows)
    if not tile_rows:
        scoring_summary["reason"] = "no_scoring_sequences"
        return scoring_summary
    screen_off_targets = eval_goal.get("off_target_screening") != "disabled"
    if not screen_off_targets:
        scoring_summary["notes"] = [
            "External off-target gene screening is excluded by this task's explicit scope. "
            "Unsearched counts are unknown, not zero; requested reference matching is separate."
        ]
        for row in tile_rows:
            row["off_target_count_status"] = "not_run"
            for field in ("off_target_gene_count", "Off_target_exact_count", "Times_mapped_off_target_genes",
                          "Off_target_total_upto_mismatch_count", "Off_target_weighted_risk_score",
                          "Off_target_1mm_count", "Off_target_2mm_count", "Off_target_3mm_count"):
                row[field] = None
    try:
        annotate_rnafold = getattr(runtime, "_annotate_tile_rows_with_rnafold", None)
        if callable(annotate_rnafold):
            scoring_summary["rnafold_annotation"] = {"annotated_rows": annotate_rnafold(tile_rows)}
    except Exception as exc:
        scoring_summary["rnafold_annotation"] = {"error": f"rnafold_failed:{exc}"}

    tiles_path = _write_provided_aso_tiles_json(output_dir=output_dir, tile_rows=tile_rows)
    scoring_summary["tiles_json_path"] = str(tiles_path)
    scoring_summary["row_count"] = len(tile_rows)

    gene_resolution = (_maybe_resolve_eval_gene_id(eval_goal, runtime) if screen_off_targets else
                       {"status": "not_run", "reason": "excluded_by_task_scope"})
    scoring_summary["gene_resolution"] = gene_resolution

    parameter_constraints = eval_goal.get("constraints") if isinstance(eval_goal.get("constraints"), dict) else None
    off_target_summary: Optional[Dict[str, Any]] = None
    annotate_off_targets = getattr(runtime, "_annotate_gapmer_off_targets", None)
    if not screen_off_targets:
        off_target_summary = {"status": "not_run", "reason": "excluded_by_task_scope"}
    elif callable(annotate_off_targets):
        try:
            off_target_summary = annotate_off_targets(str(tiles_path), eval_goal, parameter_constraints)
        except Exception as exc:
            off_target_summary = {"error": f"off_target_annotation_failed:{exc}"}
    else:
        off_target_summary = {"error": "runtime_off_target_annotator_missing"}
    if isinstance(off_target_summary, dict):
        scoring_summary["off_target_mapping"] = off_target_summary
        if screen_off_targets and not off_target_summary.get("error"):
            count_scope = exact_gene_count_scope(
                get_species_config(normalize_species(eval_goal.get("species"))),
                eval_goal.get("gene_id"), off_target_summary,
            )
            scoring_summary["off_target_count_scope"] = count_scope
            scoring_summary["exact_off_target_bins"] = _enrich_exact_off_target_bins_for_tiles(str(tiles_path), count_scope)

    expression_summary: Optional[Dict[str, Any]] = None
    if not screen_off_targets:
        expression_summary = {"status": "not_run", "reason": "off_target_screening_not_run"}
    elif isinstance(off_target_summary, dict) and not off_target_summary.get("error") and int(off_target_summary.get("rows_with_hits") or 0) > 0:
        try:
            expression_summary = annotate_off_target_expression(
                initial_filter_json_path=str(tiles_path),
                structured_goal_json=json.dumps(eval_goal, ensure_ascii=False),
            )
        except Exception as exc:
            expression_summary = {"error": f"off_target_expression_failed:{exc}"}
    elif isinstance(off_target_summary, dict) and not off_target_summary.get("error"):
        expression_summary = {"status": "not_run", "reason": "no_off_target_hits_within_recorded_scope"}
    if isinstance(expression_summary, dict):
        scoring_summary["off_target_expression"] = expression_summary

    scored_path = str(tiles_path)
    lengths = sorted(
        {
            int(len(str(row.get("Sequence") or "")))
            for row in tile_rows
            if isinstance(row, dict) and str(row.get("Sequence") or "")
        }
    )
    build_kmer_index = getattr(runtime, "_build_gapmer_kmer_index_by_len", None)
    annotate_uniqueness = getattr(runtime, "_annotate_gapmer_uniqueness", None)
    if callable(build_kmer_index) and callable(annotate_uniqueness) and isinstance(cdna_map, dict) and cdna_map and lengths:
        try:
            kmer_index_by_len = build_kmer_index(cdna_map, lengths)
            uniqueness_context = {}
            resolve_uniqueness_context = getattr(runtime, "_resolve_gapmer_uniqueness_context", None)
            if callable(resolve_uniqueness_context):
                uniqueness_context = resolve_uniqueness_context(eval_goal, iso_label) or {}
            target_label_for_uniqueness = uniqueness_context.get("target_label") if isinstance(uniqueness_context, dict) else iso_label
            if isinstance(uniqueness_context, dict):
                scoring_summary["isoform_uniqueness_context"] = {
                    "mode": uniqueness_context.get("mode"),
                    "target_label": target_label_for_uniqueness,
                    "beneficial_labels": uniqueness_context.get("beneficial_labels") or [],
                    "pathogenic_labels": uniqueness_context.get("pathogenic_labels") or [],
                }
            uniq_path = annotate_uniqueness(
                str(tiles_path),
                kmer_index_by_len,
                target_label_for_uniqueness,
                total_isoforms=len(cdna_map),
                beneficial_isoform_labels=(
                    uniqueness_context.get("beneficial_labels") if isinstance(uniqueness_context, dict) else None
                ),
                pathogenic_isoform_labels=(
                    uniqueness_context.get("pathogenic_labels") if isinstance(uniqueness_context, dict) else None
                ),
                output_name="provided_aso_scored_uniqueness.json",
                transcript_catalog={label: (eval_goal.get('all_transcripts_full') or {}).get(label)
                                    or (eval_goal.get('isoform_transcripts') or {}).get(label) or {}
                                    for label in cdna_map},
                resolved_transcripts=eval_goal.get('isoform_transcripts') or {},
            )
            if uniq_path:
                scored_path = str(uniq_path)
                scoring_summary["isoform_uniqueness"] = {
                    "status": "complete",
                    "scored_tiles_path": scored_path,
                    "target_label": target_label_for_uniqueness,
                    "mode": uniqueness_context.get("mode") if isinstance(uniqueness_context, dict) else None,
                    "isoform_count": len(cdna_map),
                }
            else:
                scoring_summary["isoform_uniqueness"] = {"error": "uniqueness_output_missing"}
        except Exception as exc:
            scoring_summary["isoform_uniqueness"] = {"error": f"uniqueness_failed:{exc}"}
    else:
        scoring_summary["isoform_uniqueness"] = {
            "status": "not_run",
            "reason": "cdna_kmer_context_or_runtime_annotator_missing",
        }

    from .provided_aso_ranking import evaluation_ranking_policy, suppress_incomparable_ranks
    ranking_policy = evaluation_ranking_policy(rows)
    scoring_summary["ranking_policy"] = ranking_policy
    ranker = getattr(runtime, "_annotate_gapmer_selection_ranks", None)
    if ranking_policy["allow_shared_ranking"] and callable(ranker) and scored_path:
        try:
            scoring_summary["selection_ranking"] = ranker(scored_path)
        except Exception as exc:
            scoring_summary["selection_ranking"] = {"error": f"selection_ranking_failed:{exc}"}

    try:
        scored_payload = json.loads(Path(scored_path).read_text(encoding="utf-8"))
        scored_rows = scored_payload.get("rows") if isinstance(scored_payload, dict) else []
    except Exception as exc:
        scoring_summary["merge"] = {"error": f"scored_tiles_read_failed:{exc}"}
        return scoring_summary
    if not isinstance(scored_rows, list):
        scoring_summary["merge"] = {"error": "scored_tiles_rows_invalid"}
        return scoring_summary
    if not splice_related and ranking_policy["allow_shared_ranking"]:
        from .provided_aso_ranking import rank_scored_provided_rows
        old_ranking = scoring_summary.get("selection_ranking")
        binding_ranking = rank_scored_provided_rows(
            scored_rows, rows, str(reference_transcript_id or ""))
        if binding_ranking.get("status") == "complete":
            binding_ranking["secondary_generic_ranking"] = old_ranking
            scoring_summary["selection_ranking"] = binding_ranking
            Path(scored_path).write_text(
                json.dumps(scored_payload, ensure_ascii=False, indent=2), encoding="utf-8")
    if not ranking_policy["allow_shared_ranking"]:
        for path in output_dir.glob("provided_aso*.json"):
            artifact = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(artifact, dict) or not isinstance(artifact.get("rows"), list):
                continue
            suppress_incomparable_ranks(artifact["rows"], ranking_policy)
            columns = (artifact.get("schema") or {}).get("columns", artifact.get("columns"))
            if isinstance(columns, dict):
                for key in ("selection_rank", "knockdown_proxy_rank"):
                    columns.pop(key, None)
                columns.update(ranking_scope="string", ranking_status="string")
            path.write_text(json.dumps(artifact, ensure_ascii=False, indent=2), encoding="utf-8")
        suppress_incomparable_ranks(scored_rows, ranking_policy)
        suppress_incomparable_ranks(rows, ranking_policy)
        scoring_summary["selection_ranking"] = {"status": "not_run", "reason": ranking_policy["reason"]}
        scoring_summary["selection_ranking_scope"] = ranking_policy["scope"]
    elif splice_related:
        for path in output_dir.glob("provided_aso*.json"):
            artifact = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(artifact, dict) or not isinstance(artifact.get("rows"), list):
                continue
            _scope_splice_proxy_ranks(artifact["rows"])
            columns = artifact.get("columns")
            if isinstance(columns, dict):
                for old, new in (("selection_rank", "knockdown_proxy_rank"), ("selection_score_components", "knockdown_proxy_score_components")):
                    if old in columns:
                        columns[new] = columns.pop(old)
            path.write_text(json.dumps(artifact, ensure_ascii=False, indent=2), encoding="utf-8")
        _scope_splice_proxy_ranks(scored_rows)
        _scope_splice_proxy_ranks(rows)
        scoring_summary["selection_ranking_scope"] = "knockdown_proxy_only; task-specific splice assessment is in model_assessment"
    scoring_summary["merge"] = _merge_scored_tiles_into_provided_asos(rows, scored_rows)
    scoring_summary["scored_tiles_path"] = scored_path
    scoring_summary["status"] = "complete"
    return scoring_summary


def _generated_evaluation_inputs(state: Dict[str, Any], task_id: str) -> Dict[str, Any]:
    """Bind a downstream evaluation to its declared design outputs, in ASO orientation."""
    tasks = {str(task.get("task_id")): task for task in _task_graph_tasks(state)}
    task = tasks.get(task_id) or {}
    dependencies = set(_task_depends_on(task))
    envelope = state.get("request_envelope") or {}
    for edge in envelope.get("task_dependencies") or []:
        if edge.get("downstream_task_id") == task_id:
            dependencies.add(edge.get("upstream_task_id"))
    rows = []
    for upstream in sorted(dependencies):
        if (tasks.get(upstream) or {}).get("task_type") != "design_new_asos":
            continue
        path = _generated_aso_set_path_for_task(state, upstream)
        if path is None:
            return {"error": "upstream_design_candidates_unavailable", "source_task_id": upstream}
        source_rows = _load_generated_aso_set_rows(path)
        if not source_rows:
            return {"error": "upstream_design_candidates_empty", "source_task_id": upstream}
        for index, row in enumerate(source_rows, 1):
            identity = generated_sequence_fields(row)
            molecule = identity.get("synthesized_antisense_sequence")
            if not molecule:
                return {"error": "upstream_candidate_synthesis_identity_unresolved", "source_task_id": upstream,
                        "source_file": str(path), "source_row": index}
            annotations = row.get("source_annotations") or {}
            rows.append({"name": f"{upstream}_{index}", "sequence": molecule,
                         "chemistry": row.get("chemistry") or row.get("IDT") or annotations.get("IDT") or annotations.get("chemistry_idt"),
                         "source_task_id": upstream, "source_file": str(path), "source_row": index,
                         "source_sequence_identity": identity})
    return {"rows": rows}


def _evaluate_existing_asos_payload(
    *,
    state: Dict[str, Any],
    request_envelope: Dict[str, Any],
    run_dir: str,
    task_id: str,
    provided_asos_override: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    provided_asos = (deepcopy(provided_asos_override) if provided_asos_override is not None
                     else _normalize_provided_asos(request_envelope))
    if not provided_asos:
        generated_inputs = _generated_evaluation_inputs(state, task_id)
        if generated_inputs.get("error"):
            return generated_inputs
        provided_asos = _normalize_provided_asos({"provided_asos": generated_inputs.get("rows") or []})
    if not provided_asos:
        return {"error": "provided_asos_missing"}

    candidate_run_dirs = _candidate_run_dirs_for_task(state, request_envelope)
    reference_context = _reference_goal_context_for_request(candidate_run_dirs)
    base_goal = reference_context.get("structured_goal") if isinstance(reference_context.get("structured_goal"), dict) else {}
    eval_goal = _overlay_request_context_on_goal(base_goal, request_envelope, str(state.get("request") or ""))
    species = normalize_species(
        request_envelope.get("species")
        or eval_goal.get("species")
        or (base_goal.get("species") if isinstance(base_goal, dict) else None)
        or "human"
    )
    eval_goal["species"] = species
    runtime = _goal_runtime_module()
    reconcile_mane = getattr(runtime, "_reconcile_inferred_mane_reference", None)
    if callable(reconcile_mane):
        user_evidence = [str(state.get("request") or "")]
        for answer in _clarification_qa_history(state):
            if answer.get("answer_source") == "external_user":
                user_evidence.append(str(answer.get("answer") or ""))
        reference_note: Dict[str, Any] = {}
        if reconcile_mane(eval_goal, reference_note, "\n".join(user_evidence)):
            note = (reference_note.get("isoform_resolution_notes") or {}).get("mane_reference_attested") or {}
            selected = str(note.get("selected_transcript_id") or "")
            discarded = {
                str(item).casefold() for item in note.get("discarded_model_accessions") or []
                if str(item).strip()
            }
            if selected and discarded:
                def _sync_evaluation_reference(value: Any) -> Any:
                    if isinstance(value, dict):
                        return {key: _sync_evaluation_reference(item) for key, item in value.items()}
                    if isinstance(value, list):
                        return [_sync_evaluation_reference(item) for item in value]
                    return selected if isinstance(value, str) and value.casefold() in discarded else value
                request_envelope = _sync_evaluation_reference(request_envelope)
            request_envelope["transcript_id"] = selected
            if isinstance(eval_goal.get("evaluation_targets"), list):
                request_envelope["evaluation_targets"] = deepcopy(eval_goal["evaluation_targets"])
    evaluation_targets = _normalize_evaluation_targets(
        request_envelope.get("evaluation_targets") or eval_goal.get("evaluation_targets")
    )
    eval_goal["evaluation_targets"] = deepcopy(evaluation_targets)
    isoform_transcripts, all_transcripts_full, catalog_notes = _ensure_eval_transcript_catalog(eval_goal, runtime)
    transcript_id, iso_label, transcript_entry = _choose_eval_transcript(
        eval_goal,
        isoform_transcripts,
        all_transcripts_full,
        runtime,
    )
    from .evaluation_identity import (
        declared_evaluation_context, bind_primary_evaluation_identity, screening_catalog_labels,
    )
    declared_context, declared_basis = declared_evaluation_context(state, request_envelope, task_id)
    try:
        identity_binding = bind_primary_evaluation_identity(eval_goal, transcript_entry, declared_context)
    except ValueError as exc:
        return {"error": str(exc), "task_type": "evaluate_existing_aso_set",
                "transcript_id": transcript_id, "declared_context_basis": declared_basis}
    identity_binding["declared_context_basis"] = declared_basis
    species = normalize_species(eval_goal.get("species"))
    if identity_binding.get("inherited_identity_changed"):
        loader = getattr(runtime, "_load_all_transcripts_for_gene", None)
        refresh_goal = deepcopy(eval_goal)
        refresh_goal.pop("isoform_transcripts", None)
        refresh_goal.pop("all_transcripts_full", None)
        try:
            refreshed = loader(refresh_goal) if callable(loader) and eval_goal.get("gene_id") else {}
        except Exception as exc:
            refreshed = {}
            catalog_notes.append(f"primary_evaluation_catalog_refresh_failed:{exc}")
        accepted = screening_catalog_labels(refreshed or {}, None, eval_goal, identity_binding)
        # Existing explicitly resolved records retain their version and geometry.
        for label in accepted:
            all_transcripts_full.setdefault(label, deepcopy(refreshed[label]))
        identity_binding["refreshed_catalog_labels"] = sorted(accepted)
    primary_catalog_labels = screening_catalog_labels(
        {**all_transcripts_full, **isoform_transcripts}, iso_label, eval_goal, identity_binding,
    )
    eval_goal["isoform_transcripts"] = {label: deepcopy(entry) for label, entry in
        {**all_transcripts_full, **isoform_transcripts}.items() if label in primary_catalog_labels}
    eval_goal["all_transcripts_full"] = deepcopy(eval_goal["isoform_transcripts"])
    identity_binding["screening_catalog_labels"] = sorted(primary_catalog_labels)
    from .evaluation_feature_identity import resolve_evaluation_target_identities
    evaluation_targets = resolve_evaluation_target_identities(
        evaluation_targets, {**all_transcripts_full, **isoform_transcripts}, transcript_id,
        resolver=getattr(runtime, "_cached_authoritative_exon_nomenclature_mapping", None),
    )
    eval_goal["evaluation_targets"] = deepcopy(evaluation_targets)
    load_genome = getattr(runtime, "_load_genome_fasta", None)
    genome = None
    if callable(load_genome):
        try:
            genome = load_genome(species)
        except Exception:
            genome = None

    patient_reference_fasta = None
    patient_ref_payload = eval_goal.get("patient_reference") if isinstance(eval_goal.get("patient_reference"), dict) else None
    if isinstance(patient_ref_payload, dict):
        patient_reference_fasta = patient_ref_payload.get("fasta_path")
    if not patient_reference_fasta:
        resolve_patient_reference_fasta = getattr(runtime, "_resolve_patient_reference_fasta", None)
        if callable(resolve_patient_reference_fasta):
            try:
                patient_reference_fasta = resolve_patient_reference_fasta(eval_goal)
            except Exception:
                patient_reference_fasta = None

    build_cdna = getattr(runtime, "_build_isoform_cdna_sequences", None)
    mapping_catalog = {**all_transcripts_full, **isoform_transcripts}
    from .dependency_references import requested_dependency_contexts, merge_reference_catalog
    dependency_contexts, reference_context_coverage = requested_dependency_contexts(
        candidate_run_dirs, request_envelope, _reference_goal_context_for_request, normalize_species)
    dependency_catalog_sources = []
    for dependency in dependency_contexts:
        dependency_goal = deepcopy(dependency['structured_goal'])
        if dependency.get('run_dir') == reference_context.get('run_dir'):
            incoming = {**all_transcripts_full, **isoform_transcripts}
        else:
            dependency_isoforms, dependency_all, dependency_notes = _ensure_eval_transcript_catalog(dependency_goal, runtime)
            incoming = {**dependency_all, **dependency_isoforms}
            catalog_notes.extend(dependency_notes)
        merge_reference_catalog(mapping_catalog, incoming, dependency_goal, normalize_species)
        dependency_catalog_sources.append({'run_dir': dependency.get('run_dir'),
            'species': dependency_goal.get('species'), 'gene_symbol': dependency_goal.get('gene_symbol'),
            'gene_id': dependency_goal.get('gene_id'), 'catalog_labels': list(incoming)})
    cdna_source = mapping_catalog
    cdna_map = {}
    if callable(build_cdna) and isinstance(cdna_source, dict) and cdna_source:
        try:
            cdna_map = build_cdna(cdna_source, species, reference_fasta=patient_reference_fasta) or {}
        except Exception:
            cdna_map = {}

    trace_context = None
    for candidate in candidate_run_dirs:
        collected = _collect_generated_stage_sets(candidate)
        if any(collected.get("sources", {}).values()):
            trace_context = {"run_dir": candidate, **collected}
            break
    reference_candidate_rows = _collect_generated_candidate_rows(str(trace_context.get("run_dir"))) if isinstance(trace_context, dict) and trace_context.get("run_dir") else []

    request_text = str(state.get("request") or "")
    request_classifications = _normalize_text_list(request_envelope.get("request_classifications"))
    splice_related = bool(
        str(eval_goal.get("intent") or "").strip().lower() == "splice_modulation"
        or any(item.lower() in {"splice_modification", "splice_modulation"}
               for item in request_classifications)
        or any(target.get("desired_delta") not in (None, "", "unspecified")
               or target.get("desired_outcome") not in (None, "", "unspecified")
               for target in evaluation_targets if isinstance(target, dict))
    )
    from .transcript_reference import catalog_genomes
    genomes_by_label = catalog_genomes(mapping_catalog, species, runtime, patient_reference_fasta)
    primary_reference_entry = mapping_catalog.get(iso_label) or transcript_entry or {}
    primary_reference_binding = primary_reference_entry.get("reference_binding") or {}
    primary_reference_species = primary_reference_binding.get("species") or species
    target_context_text = _stringify_request_context(eval_goal.get("target_context"))
    rows: List[Dict[str, Any]] = []
    splice_groups: Dict[str, Dict[str, Any]] = {}
    limitations: List[str] = []
    for coverage in reference_context_coverage:
        if coverage['status'] != 'resolved':
            limitations.append('Requested dependency reference is unavailable: ' + json.dumps(coverage['requested_identity'], sort_keys=True))
    near_match_budget = len(provided_asos) if len(provided_asos) <= 20 else 0
    near_match_skipped_count = 0

    for row in provided_asos:
        entry = dict(row)
        entry["species"] = species
        entry["gene_symbol"] = str(eval_goal.get("gene_symbol") or "").strip() or None
        entry["target_context"] = target_context_text
        entry["normalized_sequence"] = str(entry.get("sequence") or "")
        confirmation = (state.get("provided_sequence_role_confirmations") or {}).get(molecule_key(entry))
        if isinstance(confirmation, dict):
            entry["sequence_role_confirmation"] = deepcopy(confirmation)
        mapping_hits = _build_sequence_mapping_hits(
            entry=entry,
            isoform_transcripts=mapping_catalog,
            cdna_map=cdna_map if isinstance(cdna_map, dict) else {},
            runtime=runtime,
            species=species,
            preferred_transcript_id=transcript_id,
            genome=genome,
            genomes_by_label=genomes_by_label,
        )
        reference_hits = _match_reference_candidate_rows(entry, reference_candidate_rows)
        entry["reference_candidate_hits"] = reference_hits[:8]
        entry["reference_candidate_hit_count"] = len(reference_hits)
        binding_hits = preferred_binding_hits(entry, mapping_hits)
        binding_reference_hits = preferred_binding_hits(entry, reference_hits)
        # Keep both search hypotheses, but never use a sense match as evidence
        # for the supplied physical ASO without the user's role confirmation.
        entry["mapping_hits"] = mapping_hits
        entry["mapping_hit_count"] = len(mapping_hits)
        entry["binding_hit_count"] = len(binding_hits)
        preferred_hit = binding_hits[0] if binding_hits else {}
        preferred_reference_hit = binding_reference_hits[0] if binding_reference_hits else {}
        if preferred_hit:
            entry["mapping_status"] = "mapped"
            entry["comparison_sequence"] = str(preferred_hit.get("matched_target_sequence") or entry.get("comparison_sequence") or entry.get("sequence") or "")
            entry["normalized_sequence"] = entry["comparison_sequence"]
            entry["transcript_id"] = str(preferred_hit.get("transcript_id") or "").strip() or None
            entry["isoform_label"] = str(preferred_hit.get("isoform_label") or "").strip() or None
            entry["mapping_scope"] = str(preferred_hit.get("mapping_scope") or "").strip() or None
            entry["cdna_start"] = preferred_hit.get("cdna_start")
            entry["cdna_end"] = preferred_hit.get("cdna_end")
            entry["locus_relative_start"] = preferred_hit.get("locus_relative_start")
            entry["locus_relative_end"] = preferred_hit.get("locus_relative_end")
            if isinstance(preferred_hit.get("locus_span"), dict):
                entry["locus_span"] = deepcopy(preferred_hit["locus_span"])
            entry["genomic_segments"] = deepcopy(preferred_hit.get("genomic_segments") or [])
            entry["strand"] = preferred_hit.get("strand")
            if isinstance(preferred_hit.get("genomic_span"), dict):
                entry["genomic_span"] = deepcopy(preferred_hit["genomic_span"])
            for field in ("phastcons", "phylop"):
                if preferred_hit.get(field) is not None:
                    entry[field] = preferred_hit.get(field)
        elif preferred_reference_hit:
            entry["mapping_status"] = "matched_reference_candidate"
            entry["comparison_sequence"] = str(preferred_reference_hit.get("matched_target_sequence") or entry.get("comparison_sequence") or entry.get("sequence") or "")
            entry["normalized_sequence"] = entry["comparison_sequence"]
            entry["transcript_id"] = transcript_id
            entry["isoform_label"] = iso_label
            chrom = str(
                preferred_reference_hit.get("Chrom")
                or preferred_reference_hit.get("chrom")
                or preferred_reference_hit.get("chr")
                or ""
            ).strip()
            start_raw = preferred_reference_hit.get("Start") or preferred_reference_hit.get("start") or preferred_reference_hit.get("start_bp")
            end_raw = preferred_reference_hit.get("End") or preferred_reference_hit.get("end") or preferred_reference_hit.get("end_bp")
            try:
                span_start = int(start_raw)
                span_end = int(end_raw)
            except Exception:
                span_start = None
                span_end = None
            if span_start is not None and span_end is not None:
                if str(start_raw) == str(preferred_reference_hit.get("start_bp") or ""):
                    span_start += 1
                entry["genomic_segments"] = [{"chrom": chrom, "start": int(span_start), "end": int(span_end)}] if chrom else []
                entry["genomic_span"] = {
                    "chrom": chrom or None,
                    "start": int(span_start),
                    "end": int(span_end),
                    "length": abs(int(span_end) - int(span_start)) + 1,
                }
            entry["strand"] = preferred_reference_hit.get("Strand") or preferred_reference_hit.get("strand")
            if preferred_reference_hit.get("Phastcon") is not None:
                try:
                    entry["phastcons"] = float(preferred_reference_hit.get("Phastcon"))
                except Exception:
                    pass
            if preferred_reference_hit.get("PhyloP") is not None or preferred_reference_hit.get("phylop") is not None:
                try:
                    entry["phylop"] = float(preferred_reference_hit.get("PhyloP") or preferred_reference_hit.get("phylop"))
                except Exception:
                    pass
            primary_label = (
                preferred_reference_hit.get("primary_label")
                or preferred_reference_hit.get("selected_label")
                or preferred_reference_hit.get("shared_context_label")
            )
            primary_direction = preferred_reference_hit.get("primary_direction") or preferred_reference_hit.get("selected_direction")
            entry["splice_eval_summary"] = {
                **_splice_summary_from_scored_row(preferred_reference_hit),
                "primary_label": primary_label,
                "primary_direction": primary_direction,
            }
            entry["stage_results"] = {
                **(entry.get("stage_results") if isinstance(entry.get("stage_results"), dict) else {}),
                "mapping": {"status": "pass", "reason_code": "matched_reference_candidate"},
            }
        else:
            entry["mapping_status"] = "unmapped"
            entry["genomic_segments"] = []
            entry["strand"] = None

        if trace_context and _entry_sequence_variants(entry):
            entry.update(_sequence_stage_trace(entry, trace_context.get("stage_sets") or {}, stage_sources=trace_context.get('sources')))
        else:
            entry["stage_presence"] = {}
            entry["stage_matches"] = {}
            entry["first_drop_stage"] = ""
            entry["first_drop_reason"] = "no_generated_reference_context"
            entry["terminal_classification"] = "no_generated_reference_context"
            entry["terminal_status"] = "no_generated_reference_context"
            entry["entered_pipeline"] = False
            entry["stage_results"] = {
                "normalization": {"status": "pass"},
                "mapping": {"status": "pass" if preferred_hit else "fail"},
                "region_membership": {"status": "not_run"},
                "sequence_filters": {"status": "not_run"},
                "expression_annotation": {"status": "not_run"},
                "splice_eval": {"status": "not_run"},
                "uniqueness_scoring": {"status": "not_run"},
                "routing_eligibility": {"status": "not_run"},
                "ranking": {"status": "not_run"},
            }
        entry["near_match_search"] = {"status": "not_run", "reason": "exact_binding_mapping_available"}
        if preferred_reference_hit:
            stage_results = entry.get("stage_results") if isinstance(entry.get("stage_results"), dict) else {}
            mapping_stage = stage_results.get("mapping") if isinstance(stage_results.get("mapping"), dict) else {}
            mapping_stage["status"] = "pass"
            mapping_stage["reason_code"] = "matched_reference_candidate"
            stage_results["mapping"] = mapping_stage
            if isinstance(entry.get("splice_eval_summary"), dict):
                splice_stage = stage_results.get("splice_eval") if isinstance(stage_results.get("splice_eval"), dict) else {}
                splice_stage["status"] = "pass"
                splice_stage["reason_code"] = "matched_reference_candidate"
                stage_results["splice_eval"] = splice_stage
            entry["stage_results"] = stage_results
        alternative_contexts = alternative_transcripts_without_exact_binding(
            mapping_catalog, [*binding_hits, *binding_reference_hits]
        )
        if (not preferred_hit and not preferred_reference_hit) or alternative_contexts:
            if near_match_budget > 0:
                near_matches = _best_locus_near_matches(
                    entry=entry,
                    isoform_transcripts=mapping_catalog,
                    runtime=runtime,
                    genome=genome,
                    preferred_transcript_id=transcript_id,
                    genomes_by_label=genomes_by_label,
                )
                from .mapping_evidence import cdna_near_matches
                mature_matches = cdna_near_matches(entry, mapping_catalog, cdna_map,
                    getattr(runtime, "_map_cdna_range_to_genomic_segments", None), transcript_id)
                near_matches = mature_matches + near_matches
                entry["near_match_search"] = {
                    "status": "performed",
                    "rna_contexts": (["mature_spliced_cdna"] if cdna_map else []) +
                                    (["unspliced_transcript_locus_pre_mrna"] if any(value is not None for value in genomes_by_label.values()) else []),
                    "orientations": ["input_sequence", "reverse_complement"],
                    "cdna_tied_position_limit_per_transcript_orientation": 5,
                    "locus_tied_position_limit_per_transcript_orientation": 1,
                    "retained_locus_transcripts_per_orientation": 5,
                    "requested_locus_transcript_retained_separately": True,
                    "mismatch_metric": "ungapped Hamming distance over the full oligo length",
                    "indels_searched": False, "genome_wide_search": False,
                    "alternative_transcripts_without_exact_binding": alternative_contexts,
                }
                near_match_budget -= 1
            else:
                near_matches = []
                near_match_skipped_count += 1
                entry["near_match_skipped_reason"] = "large_provided_aso_set"
                entry["near_match_search"] = {"status": "not_run", "reason": "large_provided_aso_set"}
            entry["near_match_candidates"] = near_matches
        else:
            entry["near_match_candidates"] = []

        if splice_related and preferred_hit and bool(preferred_hit.get("is_contiguous_genomic_span")):
            row_transcript_id = str(preferred_hit.get("transcript_id") or "").strip()
            if row_transcript_id:
                group = splice_groups.setdefault(
                    row_transcript_id,
                    {
                        "entries": [],
                        "isoform_label": preferred_hit.get("isoform_label"),
                        "transcript_id": row_transcript_id,
                    },
                )
                group["entries"].append(entry)
        elif splice_related and preferred_reference_hit and isinstance(entry.get("splice_eval_summary"), dict):
            stage_results = entry.get("stage_results") if isinstance(entry.get("stage_results"), dict) else {}
            splice_stage = stage_results.get("splice_eval") if isinstance(stage_results.get("splice_eval"), dict) else {}
            splice_stage["status"] = "pass"
            splice_stage["reason_code"] = "matched_reference_candidate"
            stage_results["splice_eval"] = splice_stage
            entry["stage_results"] = stage_results
        elif splice_related and preferred_hit and not bool(preferred_hit.get("is_contiguous_genomic_span")):
            _record_provided_splice_skip(entry, "discontinuous_genomic_mapping")
            limitations.append(
                f"{entry.get('name') or entry.get('aso_id')}: mapping spans discontinuous genomic segments, so splice scoring was skipped."
            )
        elif splice_related and not preferred_hit and not preferred_reference_hit:
            _record_provided_splice_skip(entry, "no_exact_binding_mapping")
            near_matches = entry.get("near_match_candidates") if isinstance(entry.get("near_match_candidates"), list) else []
            if near_matches:
                best_near = near_matches[0] if isinstance(near_matches[0], dict) else {}
                mismatch_count = best_near.get("mismatch_count")
                transcript_text = str(best_near.get("transcript_id") or "").strip()
                limitations.append(
                    f"{entry.get('name') or entry.get('aso_id')}: no exact match was found across the annotated transcript pre-mRNA locus, so splice scoring was skipped. Near-match candidates have explicit orientation hypotheses; same-strand similarity alone does not establish binding of a supplied antisense oligo."
                )
            elif entry.get("near_match_skipped_reason") == "large_provided_aso_set":
                limitations.append(
                    f"{entry.get('name') or entry.get('aso_id')}: no exact transcript-locus match was found, so splice scoring was skipped; exhaustive near-match scanning was skipped for this large provided-ASO table."
                )
            else:
                limitations.append(
                    f"{entry.get('name') or entry.get('aso_id')}: transcript mapping was not found across the annotated transcript pre-mRNA locus, so splice scoring was skipped."
                )
        orientation_interpretation = _provided_aso_orientation_interpretation(entry)
        if orientation_interpretation:
            entry["orientation_interpretation"] = orientation_interpretation
        rows.append(entry)

    if splice_related and splice_groups:
        output_dir = _task_output_dir(run_dir, task_id)
        build_splice_sites = getattr(runtime, "_build_splice_sites_for_eval", None)
        isoform_catalog = mapping_catalog
        for group_transcript_id, group in splice_groups.items():
            group_entries = group.get("entries") if isinstance(group.get("entries"), list) else []
            if not group_entries:
                continue
            local_iso_label = str(group.get("isoform_label") or "").strip() or None
            local_transcript_entry = None
            if local_iso_label and isinstance(isoform_catalog.get(local_iso_label), dict):
                local_transcript_entry = isoform_catalog.get(local_iso_label)
            elif isinstance(isoform_catalog.get(group_transcript_id), dict):
                local_transcript_entry = isoform_catalog.get(group_transcript_id)
            local_goal = deepcopy(eval_goal)
            local_binding = (local_transcript_entry or {}).get("reference_binding") or {}
            local_goal["species"] = local_binding.get("species") or species
            local_patient_reference = patient_reference_fasta if local_binding.get("patient_reference_applied") else None
            local_goal["transcript_policy"] = "user_locked"
            local_goal["transcript_lock"] = {"kind": "explicit_id", "value": group_transcript_id}
            if local_transcript_entry and local_iso_label:
                local_goal["isoform_transcripts"] = {local_iso_label: deepcopy(local_transcript_entry)}
            splice_sites = []
            if callable(build_splice_sites):
                try:
                    splice_sites = build_splice_sites(local_goal, local_iso_label, window_bp=10) or []
                except Exception:
                    splice_sites = []
            splice_sites, site_scope = _provided_splice_site_context(
                local_transcript_entry, group_transcript_id, splice_sites,
                evaluation_targets, group_entries,
            )
            for entry in group_entries:
                entry.setdefault("splice_eval_summary", {})["site_search_scope"] = deepcopy(site_scope)
            if not splice_sites:
                for entry in group_entries:
                    _record_provided_splice_skip(entry, "splice_site_context_unavailable")
                    entry["splice_eval_summary"]["site_search_scope"] = deepcopy(site_scope)
                limitations.append(f"{group_transcript_id}: no compatible splice-site coordinates were available for scoring.")
                continue
            splice_sites_json = json.dumps({"sites": splice_sites}, ensure_ascii=False) if splice_sites else None

            tiles_rows: List[Dict[str, Any]] = []
            by_name: Dict[str, Dict[str, Any]] = {}
            for entry in group_entries:
                genomic_span = entry.get("genomic_span") if isinstance(entry.get("genomic_span"), dict) else {}
                chrom = str(genomic_span.get("chrom") or "").strip()
                start = genomic_span.get("start")
                end = genomic_span.get("end")
                if not chrom or not isinstance(start, int) or not isinstance(end, int):
                    continue
                name = str(entry.get("aso_id") or entry.get("name") or "").strip() or f"aso_{len(tiles_rows)+1}"
                tiles_rows.append(
                    {
                        "name": name,
                        "Chrom": chrom,
                        "Start": int(start) - 1,
                        "End": int(end),
                        "Strand": entry.get("strand") or "+",
                        "Sequence": entry.get("comparison_sequence") or entry.get("sequence"),
                    }
                )
                by_name[name] = entry
            if not tiles_rows:
                continue
            tiles_payload = {"rows": tiles_rows, "schema": {"columns": {}}}
            tiles_json_path = output_dir / f"{task_id}_{group_transcript_id}_splice_tiles.json"
            tiles_json_path.write_text(json.dumps(tiles_payload, ensure_ascii=False, indent=2), encoding="utf-8")
            splice_eval = _run_splice_eval_on_tiles_json(
                initial_tiles_path=str(tiles_json_path),
                structured_goal=local_goal,
                transcript_id=group_transcript_id,
                patient_reference_fasta=local_patient_reference,
                splice_sites_json=splice_sites_json,
                runtime=runtime,
            )
            if splice_eval.get("error"):
                limitations.append(f"{group_transcript_id}: splice evaluation failed ({splice_eval.get('error')}).")
                continue
            skipped_count = _optional_int(splice_eval.get("skipped_count"))
            result_count = _optional_int(splice_eval.get("count")) or _optional_int(splice_eval.get("evaluated"))
            if skipped_count:
                denominator = f"/{result_count}" if result_count else ""
                limitations.append(
                    f"{group_transcript_id}: splice evaluation skipped {skipped_count}{denominator} submitted ASOs; consult each ASO's recorded splice_eval_skip_reason and site_search_scope."
                )
            scored_tiles_path = str(splice_eval.get("scored_tiles_path") or "").strip()
            if not scored_tiles_path or not Path(scored_tiles_path).exists():
                continue
            try:
                scored_payload = json.loads(Path(scored_tiles_path).read_text(encoding="utf-8"))
            except Exception:
                continue
            for scored_row in scored_payload.get("rows") or []:
                if not isinstance(scored_row, dict):
                    continue
                name = str(scored_row.get("name") or scored_row.get("Name") or "").strip()
                if not name or name not in by_name:
                    continue
                entry = by_name[name]
                entry["splice_eval_summary"] = _splice_summary_from_scored_row(scored_row)
                entry["splice_eval_summary"]["site_search_scope"] = deepcopy(site_scope)
                stage_results = entry.get("stage_results") if isinstance(entry.get("stage_results"), dict) else {}
                stage_results["splice_eval"] = _splice_stage_from_scored_row(scored_row)
                entry["stage_results"] = stage_results

    provided_aso_scoring = _score_provided_asos_with_existing_pipeline(
        rows=rows,
        eval_goal=eval_goal,
        cdna_map={label: sequence for label, sequence in cdna_map.items() if label in primary_catalog_labels}
                 if isinstance(cdna_map, dict) else {},
        iso_label=iso_label,
        runtime=runtime,
        run_dir=run_dir,
        task_id=task_id,
        splice_related=splice_related,
        reference_transcript_id=transcript_id,
    )
    requested_sites = _filter_splice_sites_by_targets(
        _build_transcript_splice_sites_for_eval(transcript_entry), evaluation_targets
    )
    from .mapping_evidence import (
        requested_feature_membership, annotate_reference_junctions,
        supplied_molecule_sequence_metrics, principal_reference_exon_membership,
    )
    feature_targets = evaluation_targets or ([{"exon_label":eval_goal.get("exon_label"), "transcript_id":transcript_id}] if eval_goal.get("exon_label") else [])
    # These are canonical validated biological target objects, whose contract is
    # one-based inclusive. Keep the standalone geometry helper strict for raw input.
    feature_targets = [{**target, "coordinate_system": target.get("coordinate_system") or "1based_inclusive"}
                       for target in feature_targets if isinstance(target, dict)]
    from .reference_provenance import evaluation_catalog_provenance
    # This attests each alignment's exact reference identity and exon geometry.
    # Membership must be computed afterwards or valid primary alignments appear
    # unresolved despite the geometry being present in the delivered payload.
    reference_catalog = evaluation_catalog_provenance(mapping_catalog, cdna_map, rows,
        _task_output_dir(run_dir, task_id, request_envelope=request_envelope))
    for entry in rows:
        entry.update(supplied_molecule_sequence_metrics(entry.get("sequence")))
        entry["principal_reference_exon_membership"] = principal_reference_exon_membership(
            entry, transcript_id,
        )
        annotate_binding_evidence(entry, requested_sites, transcript_id)
        entry["requested_feature_membership"] = requested_feature_membership(
            entry, feature_targets, transcript_entry, transcript_id, catalog=mapping_catalog,
        )
        annotate_reference_junctions(entry, mapping_catalog)
    if isinstance(provided_aso_scoring, dict):
        off_target_result = provided_aso_scoring.get("off_target_mapping")
        if isinstance(off_target_result, dict) and off_target_result.get("error"):
            limitations.append(f"Provided-ASO exact off-target scoring failed ({off_target_result.get('error')}).")
        uniqueness_result = provided_aso_scoring.get("isoform_uniqueness")
        if isinstance(uniqueness_result, dict):
            if uniqueness_result.get("error"):
                limitations.append(f"Provided-ASO isoform uniqueness scoring failed ({uniqueness_result.get('error')}).")
            elif str(uniqueness_result.get("status") or "").strip().lower() == "not_run":
                reason = str(uniqueness_result.get("reason") or "not_available").strip()
                limitations.append(f"Provided-ASO isoform uniqueness scoring was not run ({reason}).")
        ranking_result = provided_aso_scoring.get("selection_ranking")
        if isinstance(ranking_result, dict) and ranking_result.get("error"):
            limitations.append(f"Provided-ASO normal ranking failed ({ranking_result.get('error')}).")

    payload = {
        "task_type": "evaluate_existing_aso_set",
        "reference_catalog": reference_catalog,
        "request_summary": request_envelope.get("request_summary"),
        "provided_aso_count": len(rows),
        "provided_asos": rows,
        "evaluation_targets": evaluation_targets,
        "reference_context_run_dir": reference_context.get("run_dir"),
        "reference_context_coverage": reference_context_coverage,
        "dependency_catalog_sources": dependency_catalog_sources,
        "generated_reference_run_dir": trace_context.get("run_dir") if isinstance(trace_context, dict) else None,
        "generated_reference_sources": trace_context.get("sources") if isinstance(trace_context, dict) else {},
        "context_summary": {
            "gene_symbol": str(eval_goal.get("gene_symbol") or "").strip() or None,
            "gene_id": str(eval_goal.get("gene_id") or "").strip() or None,
            "species": species,
            "transcript_id": transcript_id,
            "isoform_label": iso_label,
            "target_context": target_context_text,
            "primary_identity_binding": identity_binding,
            **evaluation_reference_context(
                get_species_config(primary_reference_species), genomes_by_label.get(iso_label), transcript_id, primary_reference_entry,
                request_envelope.get("transcript_id")
                or next((t.get("transcript_id") for t in evaluation_targets if t.get("transcript_id")), None)
                or (eval_goal.get("transcript_lock") or {}).get("value"),
                patient_reference_fasta if primary_reference_binding.get("patient_reference_applied") else None,
                searched_cdna=bool(cdna_map),
                searched_premrna=any(value is not None for value in genomes_by_label.values()),
            ),
        },
        "mapping_strategy": {
            "searched_spliced_cdna": bool(cdna_map),
            "searched_transcript_premrna_locus": any(value is not None for value in genomes_by_label.values()),
            "reference_searches": {label: {
                "reference_binding": item.get("reference_binding"),
                "mature_cdna_searched": label in cdna_map,
                "premrna_searched": genomes_by_label.get(label) is not None,
                "sequence_resolution_error": item.get("sequence_resolution_error"),
                "genomic_reference_resolution_error": item.get("genomic_reference_resolution_error"),
            } for label, item in mapping_catalog.items()},
            "reference_scope": "Organism, assembly and sequence evidence are per transcript. Context summary and off-target gene screening describe the primary request organism; do not extend those results to other organisms. An unavailable reference has unknown binding, not a negative result.",
            "preferred_transcript_id": transcript_id,
            "transcript_catalog_size": len(mapping_catalog) if isinstance(mapping_catalog, dict) else 0,
        },
        "catalog_notes": catalog_notes,
        "limitations": limitations,
        "splice_related_request": splice_related,
        "provided_aso_scoring": provided_aso_scoring,
    }
    if near_match_skipped_count:
        payload["near_match_scanning"] = {
            "skipped_unmapped_entries": near_match_skipped_count,
            "reason": "large_provided_aso_set",
        }
    if not cdna_map:
        payload["limitations"].append("Transcript cDNA context was unavailable, so mapping-dependent evaluation may be incomplete.")
    from .oligoai import evaluate_candidates, target_references
    # Preserve the original physical input and existing mapping. OligoAI only
    # admits independently attested supported chemistry and an exact target site.
    try:
        references = target_references(eval_goal, runtime, catalog=mapping_catalog,
                                      cdna=cdna_map, genomes=genomes_by_label)
    except Exception:
        references = []
    oligoai_evaluation = evaluate_candidates(rows, eval_goal, _task_output_dir(run_dir, task_id),
                                          references=references, runtime=runtime)
    if oligoai_evaluation:
        payload["oligoai_evaluation"] = oligoai_evaluation
    return payload


def _prepare_v2_task_execution(
    *,
    state_path: str,
    tool_name: str,
    task_type: str,
) -> Dict[str, Any]:
    try:
        state = _load_state(state_path)
    except Exception as exc:
        return {"status": "fatal_error", "error": f"state_read_failed: {exc}"}
    if state.get('status') == 'failed' and (state.get('last_error') or {}).get('retryable') is False:
        return {'status': 'fatal_error', 'error': 'nonretryable_task_failure',
                'message': 'The failed task requires an explicit recovery; automatic full reevaluation is disabled.',
                'last_error': deepcopy(state.get('last_error')), 'state_path': state_path}
    reference_data_root = str(state.get("reference_data_root") or "").strip()
    if reference_data_root:
        try:
            state["reference_data_root"] = _apply_reference_data_root_choice(reference_data_root)
        except Exception as exc:
            return {"status": "fatal_error", "error": f"reference_data_root_apply_failed: {exc}"}
    disallowed = _reject_disallowed_tool_call(
        state_path=state_path,
        state=state,
        tool_name=tool_name,
    )
    if isinstance(disallowed, dict):
        return disallowed
    _mark_last_tool(state, tool_name, "started")
    task = _activate_task_by_type(state, task_type)
    if not task:
        _mark_last_tool(state, tool_name, "fatal_error")
        _save_state(state_path, state, snapshot_reason=f"{tool_name}_missing_task")
        return {"status": "fatal_error", "error": f"task_not_available:{task_type}"}
    run_dir = state.get("run_dir")
    if not isinstance(run_dir, str) or not run_dir.strip():
        runtime = _goal_runtime_module()
        make_run_dir = getattr(runtime, "_make_run_dir", None)
        if not callable(make_run_dir):
            return {"status": "fatal_error", "error": "runtime_make_run_dir_missing"}
        run_dir = str(make_run_dir(None))
        state["run_dir"] = run_dir
        state_path = _relocate_agentic_state_into_run_dir(state, state_path, run_dir)
    else:
        state_path = _relocate_agentic_state_into_run_dir(state, state_path, str(run_dir).strip())
    request_envelope = (
        state.get("request_envelope")
        if isinstance(state.get("request_envelope"), dict)
        else {}
    )
    task_id = str(task.get("task_id") or state.get("current_task_id") or "").strip()
    task_request_envelope = _task_scoped_child_preseed_envelope(
        state,
        request_envelope,
        task,
    )
    return {
        "status": "ok",
        "state": state,
        "run_dir": str(run_dir).strip(),
        "task": task,
        "task_id": task_id,
        "request_envelope": request_envelope,
        "task_request_envelope": task_request_envelope,
        "task_context": deepcopy(task_request_envelope.get("task_context") if isinstance(task_request_envelope.get("task_context"), dict) else {}),
        "state_path": str(_state_path_to_obj(state_path)),
    }


def _write_v2_task_result_files(
    *,
    run_dir: str,
    task_id: str,
    basename: str,
    payload: Dict[str, Any],
    markdown_text: str = "",
    request_envelope: Optional[Dict[str, Any]] = None,
    task_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    output_dir = _task_output_dir(run_dir, task_id, request_envelope=request_envelope)
    json_path = output_dir / f"{basename}.json"
    json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    artifacts: Dict[str, str] = {"json": str(json_path), "dir": str(output_dir)}
    if isinstance(task_context, dict) and task_context:
        context_path = output_dir / "task_context.json"
        context_path.write_text(json.dumps(task_context, ensure_ascii=False, indent=2), encoding="utf-8")
        artifacts["task_context_json"] = str(context_path)
    if markdown_text:
        md_path = output_dir / f"{basename}.md"
        md_path.write_text(markdown_text, encoding="utf-8")
        artifacts["markdown"] = str(md_path)
    if payload.get("task_type") == "evaluate_existing_aso_set" and isinstance(payload.get("provided_asos"), list):
        # A supplied-set evaluation owns a complete per-record native table.
        # Keep duplicate physical submissions as separate rows.
        rows = _native_evaluation_table_rows(payload)
        if rows:
            table_path = output_dir / f"{basename}.csv"
            with table_path.open("w", encoding="utf-8", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=_v2_excel_columns(rows))
                writer.writeheader()
                writer.writerows({key: _v2_excel_cell_value(value) for key, value in row.items()} for row in rows)
            artifacts["comparison_table_csv"] = str(table_path)
    manifest_path = output_dir / "task_outputs_manifest.json"
    manifest_path.write_text(json.dumps({"task_id": task_id, "basename": basename, "artifacts": artifacts}, ensure_ascii=False, indent=2), encoding="utf-8")
    artifacts["manifest_json"] = str(manifest_path)
    return artifacts


def _native_evaluation_task_markdown(payload: Dict[str, Any]) -> str:
    """Render a self-contained summary of computed task evidence, without efficacy claims."""
    rows = payload.get("provided_asos") if isinstance(payload.get("provided_asos"), list) else []
    lines = ["# ASO evaluation", "",
             str(payload.get("request_summary") or "Computed candidate evaluation.").strip(), "",
             "These are computational mapping and screening observations, not measured activity.", ""]
    targets = payload.get("evaluation_targets") if isinstance(payload.get("evaluation_targets"), list) else []
    if targets:
        lines.extend(["## Requested targets", ""])
        for target in targets:
            if not isinstance(target, dict):
                continue
            identity = target.get("exon_identity_resolution") if isinstance(target.get("exon_identity_resolution"), dict) else {}
            label = str(target.get("label") or target.get("transcript_id") or "Target")
            location = ""
            if all(identity.get(key) is not None for key in ("chrom", "start", "end")):
                location = f"; annotated interval {identity['chrom']}:{identity['start']}-{identity['end']} ({identity.get('coordinate_system') or 'coordinate convention unspecified'})"
            lines.append(f"- {label}: transcript {target.get('transcript_id') or 'unresolved'}, exon {target.get('exon_label') or 'unresolved'}{location}.")
        lines.append("")
    lines.extend(["## Candidate evidence", "",
                  "| Candidate | Antisense 5′→3′ | Recorded mapping hits | Recorded screening gene count | Count status |",
                  "|---|---|---:|---:|---|"])
    for index, row in enumerate(rows, 1):
        if not isinstance(row, dict):
            continue
        name = str(row.get("aso_id") or row.get("name") or f"candidate_{index}").replace("|", "\\|")
        sequence = str(row.get("sequence") or "unavailable").replace("|", "\\|")
        hits = row.get("mapping_hits") if isinstance(row.get("mapping_hits"), list) else []
        count = row.get("off_target_gene_count")
        count_display = str(count) if isinstance(count, int) else "not established"
        status = str(row.get("off_target_count_status") or "not established").replace("|", "\\|")
        lines.append(f"| {name} | {sequence} | {len(hits)} | {count_display} | {status} |")
    if not rows:
        lines.append("| No candidates evaluated | — | — | — | — |")
    scoring = payload.get("provided_aso_scoring") if isinstance(payload.get("provided_aso_scoring"), dict) else {}
    scope = scoring.get("off_target_count_scope")
    if isinstance(scope, dict) and scope:
        lines.extend(["", "## Screening scope", ""])
        if scope.get("metric"):
            lines.append(f"- Declared screening metric (nominal; actual exclusion status determines whether the count includes the target): {scope['metric']}")
        for key in ("count_unit", "assembly", "excluded_gene_id", "exclusion_applied", "genomic_search", "junction_search", "limitations"):
            value = scope.get(key)
            if key in scope and value not in ("", [], {}):
                lines.append(f"- {key.replace('_', ' ')}: {value}")
        if scope.get("exclusion_applied") is False:
            lines.append("- Target exclusion was not applied; the raw screening count can include the intended target. It is not an other-gene count.")
    limitations = payload.get("limitations")
    if isinstance(limitations, list) and limitations:
        lines.extend(["", "## Limitations", ""])
        lines.extend(f"- {item}" for item in limitations if str(item).strip())
    return "\n".join(lines).strip() + "\n"


def _complete_v2_task(
    *,
    state_path: str,
    state: Dict[str, Any],
    tool_name: str,
    run_dir: str,
    task_id: str,
    status: str,
    phase: str,
    message: str,
    artifacts: Dict[str, Any],
    extra: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    state["status"] = status
    state["phase"] = phase
    state["last_error"] = None
    state["pending_questions"] = []
    state["artifacts"] = _discover_core_artifacts(run_dir)
    _store_task_artifacts(state, task_id, artifacts)
    task_statuses = state.get("task_statuses")
    if not isinstance(task_statuses, dict):
        task_statuses = {}
        state["task_statuses"] = task_statuses
    status_entry = task_statuses.get(task_id)
    if not isinstance(status_entry, dict):
        status_entry = {}
        task_statuses[task_id] = status_entry
    if isinstance(extra, dict) and isinstance(extra.get("design_outcome"), dict):
        status_entry["design_outcome"] = deepcopy(extra["design_outcome"])
    status_entry["status"] = "completed"
    status_entry["updated_at"] = _timestamp()
    request_envelope = state.get("request_envelope") if isinstance(state.get("request_envelope"), dict) else {}
    task_payload = _task_payload_by_id(state, task_id)
    output_dir = _task_output_dir(run_dir, task_id, request_envelope=request_envelope)
    task_status_path = output_dir / "task_status.json"
    task_status_payload = {
        "task_id": task_id,
        "task_type": str(task_payload.get("task_type") or "").strip(),
        "label": str(task_payload.get("label") or "").strip(),
        "status": status,
        "phase": phase,
        "message": message,
        "artifacts": artifacts,
    }
    if isinstance(extra, dict) and isinstance(extra.get("design_outcome"), dict):
        task_status_payload["design_outcome"] = deepcopy(extra["design_outcome"])
    task_status_path.write_text(
        json.dumps(task_status_payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    task_entry = task_artifacts.get(task_id) if isinstance(task_artifacts.get(task_id), dict) else {}
    if isinstance(task_entry, dict):
        task_entry["task_status_json"] = str(task_status_path)
    _mark_last_tool(state, tool_name, "ok")
    _event(state, phase, message)
    _save_state(state_path, state, snapshot_reason=phase)
    response: Dict[str, Any] = {
        "status": "ok",
        "state_path": str(_state_path_to_obj(state_path)),
        "run_dir": run_dir,
        "task_id": task_id,
        "task_status": status,
        "artifacts": artifacts,
    }
    if isinstance(extra, dict):
        response.update(extra)
    return response


def _coerce_bool(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        text = value.strip().lower()
        if text in {"1", "true", "yes", "y", "on"}:
            return True
        if text in {"0", "false", "no", "n", "off"}:
            return False
    return None


def _goal_payload_context(run_dir: str) -> Dict[str, Any]:
    payload = _load_goal_intake_payload(run_dir)
    final_payload = payload.get("final_payload") if isinstance(payload.get("final_payload"), dict) else {}
    structured_goal = final_payload.get("structured_goal") if isinstance(final_payload.get("structured_goal"), dict) else {}
    request_envelope = (
        payload.get("request_envelope")
        if isinstance(payload.get("request_envelope"), dict)
        else final_payload.get("request_envelope")
        if isinstance(final_payload.get("request_envelope"), dict)
        else {}
    )
    return {
        "payload": payload,
        "final_payload": final_payload,
        "structured_goal": structured_goal,
        "request_envelope": request_envelope,
    }


def _routing_required_after_splice_eval(run_dir: str) -> bool:
    context = _goal_payload_context(run_dir)
    final_payload = context["final_payload"]
    structured_goal = context["structured_goal"]
    if _routing_skipped_for_run(final_payload, structured_goal).get("skipped"):
        return False
    tiling_results = final_payload.get("tiling_results") if isinstance(final_payload.get("tiling_results"), dict) else {}
    splice_eval = tiling_results.get("splice_transformer") if isinstance(tiling_results, dict) else None
    splice_eval_executed = bool(isinstance(splice_eval, dict) and splice_eval and not splice_eval.get("skipped"))
    router_present = bool(_artifact_markers_for_run(run_dir).get("has_routing"))
    return bool(splice_eval_executed and not router_present)


def _routing_skipped_for_run(
    final_payload: Dict[str, Any],
    structured_goal: Dict[str, Any],
) -> Dict[str, Any]:
    for source in (final_payload, structured_goal):
        if not isinstance(source, dict):
            continue
        skipped = source.get("strategy_routing_skipped")
        if isinstance(skipped, dict) and bool(skipped.get("skipped")):
            return skipped
    return {}


def _normalize_isoform_scope_source(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "user": "user_specified",
        "explicit": "user_specified",
        "explicit_user": "user_specified",
        "user_locked": "user_specified",
        "resolver": "resolver_inferred",
        "inferred": "resolver_inferred",
        "resolved": "resolver_inferred",
        "auto": "resolver_inferred",
        "default": "resolver_inferred",
    }
    normalized = aliases.get(text, text)
    return normalized if normalized in {"user_specified", "resolver_inferred"} else ""


def _normalize_isoform_transcript_confirmation_items(raw: Any) -> List[Dict[str, Any]]:
    if isinstance(raw, dict):
        items = list(raw.values())
    elif isinstance(raw, list):
        items = raw
    else:
        return []

    normalized: List[Dict[str, Any]] = []
    for entry in items:
        if not isinstance(entry, dict):
            continue
        isoform_label = str(entry.get("isoform_label") or "").strip()
        if not isoform_label:
            continue
        item: Dict[str, Any] = {"isoform_label": isoform_label}
        for field in (
            "decision",
            "transcript_id",
            "suggested_transcript_id",
            "method",
            "confidence",
            "rationale",
            "evidence_summary",
            "display_name",
            "description",
            "note",
            "raw_answer",
            "error",
        ):
            value = entry.get(field)
            if value is None:
                continue
            text = str(value).strip()
            if text:
                item[field] = text
        evidence_refs = entry.get("evidence_refs")
        if isinstance(evidence_refs, list):
            refs = list(
                dict.fromkeys(
                    str(value).strip()
                    for value in evidence_refs
                    if str(value).strip()
                )
            )
            if refs:
                item["evidence_refs"] = refs
        normalized.append(item)
    return normalized


def _load_transcript_confirmation_candidates(structured_goal: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(structured_goal, dict):
        return []
    gene_symbol = str(structured_goal.get("gene_symbol") or "").strip()
    if not gene_symbol:
        return []
    species = normalize_species(structured_goal.get("species"))
    gene_id = str(structured_goal.get("gene_id") or "").strip() or None
    try:
        listing = list_transcripts(symbol=gene_symbol, species=species, gene_id=gene_id)
    except Exception:
        return []
    transcripts = listing.get("transcripts") if isinstance(listing, dict) else None
    return transcripts if isinstance(transcripts, list) else []


def _clarification_request_from_state(state: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    run_dir_raw = state.get("run_dir")
    if not isinstance(run_dir_raw, str) or not run_dir_raw.strip():
        return None
    run_dir = run_dir_raw.strip()
    context = _goal_payload_context(run_dir)
    final_payload = context["final_payload"]
    structured_goal = context["structured_goal"]
    if not isinstance(structured_goal, dict):
        return None

    pending_transcript_confirmations = _normalize_isoform_transcript_confirmation_items(
        structured_goal.get("pending_isoform_transcript_confirmations")
        or final_payload.get("pending_isoform_transcript_confirmations")
    )
    if pending_transcript_confirmations:
        context_lines: List[str] = []
        questions: List[str] = []
        for item in pending_transcript_confirmations[:8]:
            isoform_label = str(item.get("isoform_label") or "isoform").strip()
            transcript_id = str(
                item.get("suggested_transcript_id") or item.get("transcript_id") or "unknown"
            ).strip()
            method = str(item.get("method") or "auto").strip()
            confidence = str(item.get("confidence") or "unknown").strip()
            detail_bits = [f"{isoform_label}: suggested transcript {transcript_id}"]
            if method:
                detail_bits.append(f"method={method}")
            if confidence:
                detail_bits.append(f"confidence={confidence}")
            display_name = str(item.get("display_name") or "").strip()
            description = str(item.get("description") or "").strip()
            rationale = str(item.get("rationale") or "").strip()
            evidence_summary = str(item.get("evidence_summary") or "").strip()
            error = str(item.get("error") or "").strip()
            if display_name:
                detail_bits.append(f"name={display_name}")
            if description:
                detail_bits.append(f"description={description}")
            if rationale:
                detail_bits.append(f"rationale={rationale}")
            if evidence_summary:
                detail_bits.append(f"evidence={evidence_summary}")
            if error:
                detail_bits.append(f"issue={error}")
            context_lines.append("; ".join(detail_bits))
            if error:
                questions.append(f"For isoform '{isoform_label}': {error}")
            else:
                questions.append(
                    f"For isoform '{isoform_label}', should I use transcript {transcript_id}? "
                    "Reply naturally: accept it, skip it, upload a SnapGene reference, paste an ENST ID, or describe the transcript you want."
                )
        return {
            "kind": "isoform_transcript_confirmation",
            "reason": "Transcript resolution found one or more auto-matched isoform transcripts that need your confirmation before continuation.",
            "context": " | ".join(context_lines),
            "why_this_matters": (
                "Transcript choice changes exon structure, splice-site mapping, and downstream ASO ranking."
            ),
            "recommendation": (
                "Reply naturally. You can accept, skip, upload, paste an ENST ID, or describe the transcript you want."
            ),
            "suggested_answers": ["accept" for _question in questions],
            "restart_stage": "resolution",
            "questions": questions,
        }

    clarification = state.get("clarification") if isinstance(state.get("clarification"), dict) else {}
    iso_scope_confirmed = bool(clarification.get("isoform_scope_confirmed"))
    if iso_scope_confirmed:
        return None

    intent = str(structured_goal.get("intent") or "").strip().lower()
    objectives = structured_goal.get("splice_isoform_objectives")
    objective_count = len(objectives) if isinstance(objectives, list) else 0
    isoform_scope_source = _normalize_isoform_scope_source(structured_goal.get("isoform_scope_source"))
    isoform_transcripts = structured_goal.get("isoform_transcripts")
    resolved_isoform_count = len(isoform_transcripts) if isinstance(isoform_transcripts, dict) else 0
    transcript_policy = str(structured_goal.get("transcript_policy") or "").strip().lower()
    transcript_lock = structured_goal.get("transcript_lock")
    requested_isoforms = structured_goal.get("requested_isoform_labels")
    requested_isoform_count = len(requested_isoforms) if isinstance(requested_isoforms, list) else 0
    exon_label = structured_goal.get("exon_label")

    should_request_isoform_scope = (
        intent == "splice_modulation"
        and isoform_scope_source == "resolver_inferred"
        and resolved_isoform_count > 1
        and objective_count > 1
        and not isinstance(exon_label, int)
        and transcript_policy != "user_locked"
        and not (isinstance(transcript_lock, dict) and str(transcript_lock.get("value") or "").strip())
        and requested_isoform_count == 0
    )

    if should_request_isoform_scope:
        gene = str(structured_goal.get("gene_symbol") or "").strip() or "the target gene"
        exon_text = f"exon {exon_label}" if isinstance(exon_label, int) else "the requested exon"
        target_context = str(structured_goal.get("target_context") or "").strip()

        objective_lines: List[str] = []
        if isinstance(objectives, list):
            for idx, item in enumerate(objectives, start=1):
                if idx > 6:
                    objective_lines.append(f"{idx}) additional objective not shown.")
                    break
                if isinstance(item, dict):
                    label = ""
                    for key in ("label", "isoform_label", "transcript_id", "transcript", "name", "id"):
                        candidate = str(item.get(key) or "").strip()
                        if candidate:
                            label = candidate
                            break
                    direction = ""
                    for key in ("direction", "desired_direction", "desired_effect", "effect"):
                        candidate = str(item.get(key) or "").strip()
                        if candidate:
                            direction = candidate
                            break
                    objective_exon = item.get("exon_label")
                    parts: List[str] = []
                    if label:
                        parts.append(label)
                    if isinstance(objective_exon, int):
                        parts.append(f"exon {objective_exon}")
                    if direction:
                        parts.append(f"direction {direction}")
                    objective_desc = ", ".join(parts).strip() or json.dumps(item, ensure_ascii=False)
                else:
                    objective_desc = str(item).strip() or "unspecified objective"
                objective_lines.append(f"{idx}) {objective_desc}")

        context_bits = [f"You asked to modulate {exon_text} for {gene}."]
        if target_context:
            context_bits.append(f"Context: {target_context}.")
        context_bits.append("I inferred multiple isoform objectives from your request.")
        if objective_lines:
            context_bits.append("Inferred objectives: " + " | ".join(objective_lines))

        questions = [
            (
                "Should I optimize one primary isoform objective, or keep a multi-objective design?"
            )
        ]
        if objective_lines:
            questions.append(
                "If primary-objective mode, which inferred objective should be primary? Reply with its number."
            )
        else:
            questions.append(
                "If primary-objective mode, specify the primary isoform/transcript and desired direction."
            )

        suggested_answers = [
            "Use one primary objective (recommended for a clearer optimization target).",
        ]
        if objective_lines:
            suggested_answers.append("Primary objective: 1")
        else:
            suggested_answers.append("Primary objective: <isoform/transcript> with desired direction.")

        return {
            "kind": "isoform_scope",
            "reason": "I found multiple isoform objectives and need your preference before ranking candidates.",
            "context": " ".join(context_bits),
            "why_this_matters": (
                "Primary-vs-multi objective changes how ASOs are prioritized and can lead to different top candidates."
            ),
            "recommendation": (
                "If you are unsure, choose one primary objective first; we can expand to multi-objective afterward."
            ),
            "suggested_answers": suggested_answers,
            "restart_stage": "resolution",
            "questions": questions,
        }
    return None


def _child_task_clarification_request_from_state(
    state: Dict[str, Any],
    preferred_task_id: str = "",
) -> Optional[Dict[str, Any]]:
    task_artifacts = state.get("task_artifacts") if isinstance(state.get("task_artifacts"), dict) else {}
    task_validation = state.get("task_validation") if isinstance(state.get("task_validation"), dict) else {}
    ordered_task_ids: List[str] = []
    preferred = str(preferred_task_id or "").strip()
    if preferred:
        ordered_task_ids.append(preferred)
    ordered_task_ids.extend(
        [
            str(task.get("task_id") or "").strip()
            for task in _task_graph_tasks(state)
            if isinstance(task, dict) and str(task.get("task_id") or "").strip()
        ]
    )
    for task_id in task_artifacts.keys():
        task_id_text = str(task_id or "").strip()
        if task_id_text:
            ordered_task_ids.append(task_id_text)
    seen: Set[str] = set()
    for task_id in ordered_task_ids:
        task_id_text = str(task_id or "").strip()
        if not task_id_text or task_id_text in seen:
            continue
        seen.add(task_id_text)
        artifact_entry = task_artifacts.get(task_id_text)
        if not isinstance(artifact_entry, dict):
            continue
        child_status = str(artifact_entry.get("child_status") or "").strip().lower()
        fallback_questions = _normalize_questions_input(artifact_entry.get("child_pending_questions"))
        if child_status != "needs_user_input" or not fallback_questions:
            continue
        validation_entry = task_validation.get(task_id_text) if isinstance(task_validation.get(task_id_text), dict) else {}
        child_state_path = str(artifact_entry.get("child_state_path") or "").strip()
        child_run_dir = str(artifact_entry.get("child_run_dir") or "").strip()
        payload: Dict[str, Any] = {
            "kind": "general",
            "reason": str(validation_entry.get("reason") or "").strip(),
            "restart_stage": "resolution",
            "questions": fallback_questions,
            "task_id": task_id_text,
        }
        if child_state_path:
            child_state_obj = Path(child_state_path).expanduser()
            if child_state_obj.exists():
                try:
                    child_state = json.loads(child_state_obj.read_text(encoding="utf-8"))
                except Exception:
                    child_state = {}
                if isinstance(child_state, dict):
                    clarification = child_state.get("clarification") if isinstance(child_state.get("clarification"), dict) else {}
                    child_questions = _normalize_questions_input(child_state.get("pending_questions"))
                    if child_questions:
                        payload["questions"] = child_questions
                    payload["kind"] = str(clarification.get("kind") or payload.get("kind") or "general").strip().lower() or "general"
                    payload["reason"] = str(clarification.get("reason") or payload.get("reason") or "").strip()
                    payload["restart_stage"] = (
                        str(clarification.get("restart_stage") or payload.get("restart_stage") or "resolution").strip().lower()
                        or "resolution"
                    )
                    for field in ("context", "why_this_matters", "recommendation"):
                        text = str(clarification.get(field) or "").strip()
                        if text:
                            payload[field] = text
                    suggested_answers = _normalize_text_items(clarification.get("suggested_answers"))
                    if suggested_answers:
                        payload["suggested_answers"] = suggested_answers
        if not str(payload.get("reason") or "").strip():
            task_payload = _task_payload_by_id(state, task_id_text)
            task_label = str(task_payload.get("label") or task_id_text).strip() or task_id_text
            payload["reason"] = f"Design task '{task_label}' is waiting for clarification from its child design run."
        if child_state_path:
            payload["child_state_path"] = child_state_path
        if child_run_dir:
            payload["child_run_dir"] = child_run_dir
        questions = _normalize_questions_input(payload.get("questions"))
        if questions:
            payload["questions"] = questions
            return payload
    return None


def _pending_clarification_request_from_state(
    state: Dict[str, Any],
    pending_questions: List[str],
) -> Optional[Dict[str, Any]]:
    if not pending_questions:
        return None
    clarification = state.get("clarification")
    if not isinstance(clarification, dict):
        clarification = {}
    payload: Dict[str, Any] = {
        "kind": str(clarification.get("kind") or "general").strip().lower() or "general",
        "reason": str(clarification.get("reason") or "").strip(),
        "restart_stage": str(clarification.get("restart_stage") or "resolution").strip().lower() or "resolution",
        "questions": pending_questions,
    }
    for field in ("context", "why_this_matters", "recommendation"):
        text = str(clarification.get(field) or "").strip()
        if text:
            payload[field] = text
    suggested_answers = _normalize_text_items(clarification.get("suggested_answers"))
    if suggested_answers:
        payload["suggested_answers"] = suggested_answers
    return payload


def _update_goal_intake_clarification_from_payload(
    clarification: Dict[str, Any],
    final_payload: Dict[str, Any],
    intake_questions: List[str],
) -> Dict[str, Any]:
    clarification["kind"] = str(final_payload.get("kind") or final_payload.get("clarification_kind") or "goal_intake").strip().lower() or "goal_intake"
    clarification["reason"] = (
        str(final_payload.get("reason") or clarification.get("reason") or "").strip()
        or "Goal intake returned clarification questions that require user input."
    )
    clarification["restart_stage"] = (
        str(final_payload.get("restart_stage") or clarification.get("restart_stage") or "intake").strip().lower()
        or "intake"
    )
    clarification["requested_at"] = _timestamp()
    clarification["questions_count"] = len(intake_questions)
    requirements = [
        deepcopy(item)
        for item in final_payload.get("clarification_requirements", [])
        if isinstance(item, dict)
        and str(item.get("missing_field") or "").strip()
        and str(item.get("question") or "").strip()
        and str(item.get("reason") or "").strip()
    ]
    if requirements:
        existing_requirements = [
            deepcopy(item)
            for item in clarification.get("requirement_history", [])
            if isinstance(item, dict)
        ]
        for requirement in requirements:
            if requirement not in existing_requirements:
                existing_requirements.append(requirement)
        clarification["requirement_history"] = existing_requirements
        clarification["missing_fields"] = list(
            dict.fromkeys(
                str(item.get("missing_field") or "").strip()
                for item in existing_requirements
                if str(item.get("missing_field") or "").strip()
            )
        )
    for field in ("context", "why_this_matters", "recommendation"):
        text = str(final_payload.get(field) or "").strip()
        if text:
            clarification[field] = text
        else:
            clarification.pop(field, None)
    suggested_answers = _normalize_text_items(final_payload.get("suggested_answers"))
    if suggested_answers:
        clarification["suggested_answers"] = suggested_answers
    else:
        clarification.pop("suggested_answers", None)
    return clarification


def _clarification_request_allowed_for_state(
    state: Dict[str, Any],
    planning: Optional[Dict[str, Any]] = None,
    direct_questions: Optional[List[str]] = None,
) -> bool:
    active_runner = state.get("active_runner") if isinstance(state.get("active_runner"), dict) else {}
    active_tool = str(active_runner.get("tool") or "").strip()
    if (
        isinstance(direct_questions, list)
        and any(str(item).strip() for item in direct_questions)
        and active_tool
        and active_tool != "request_clarification"
        and _is_execution_tool_name(active_tool)
    ):
        return True
    planning_payload = planning if isinstance(planning, dict) else _derive_next_actions(state)
    if not isinstance(planning_payload, dict):
        return False
    allowed_next_tools = planning_payload.get("allowed_next_tools")
    if isinstance(allowed_next_tools, list) and "request_clarification" not in allowed_next_tools:
        return False
    clarification_request = planning_payload.get("clarification_request")
    pending_questions = planning_payload.get("pending_questions")
    return bool(
        isinstance(clarification_request, dict)
        or (isinstance(pending_questions, list) and any(str(item).strip() for item in pending_questions))
    )


def _scoped_design_integrity(run_dir: str, task: Dict[str, Any], envelope: Dict[str, Any], *, skip_router: bool) -> Optional[Dict[str, Any]]:
    """Validate an executed child where a task delegates its design pipeline."""
    task_id = str(task.get("task_id") or "")
    root_name = "v3_tasks" if envelope.get("schema_version") == "v3" else "v2_tasks"
    result_path = _run_path(run_dir, root_name, task_id, "design_task_result.json")
    if not result_path.is_file():
        return None
    try:
        result = _read_json(result_path)
        if not isinstance(result, dict):
            raise ValueError("child_record_not_an_object")
        child_dir = Path(result.get("child_run_dir") or "").resolve()
        child_root = (Path(run_dir) / "child_runs").resolve()
        if result.get("task_id") != task_id or child_dir == child_root or not child_dir.is_relative_to(child_root):
            raise ValueError("child_identity_or_scope_mismatch")
        if result.get("child_status") not in {"run_complete", "completed"}:
            raise ValueError("child_not_completed")
        integrity = _extract_pipeline_integrity(str(child_dir), _discover_core_artifacts(str(child_dir)), skip_router=skip_router)
        if "design_delivery" not in integrity and "scoped_design_integrity" not in integrity:
            raise ValueError("child_design_contract_missing")
        return integrity
    except (ValueError, OSError, TypeError) as exc:
        return {"ok": False, "blocking_errors": [f"scoped_design_record_invalid:{exc}"]}


def _extract_pipeline_integrity(
    run_dir: str,
    artifacts: Dict[str, Any],
    *,
    skip_router: bool,
) -> Dict[str, Any]:
    exists = artifacts.get("exists") if isinstance(artifacts, dict) else {}
    markers = artifacts.get("markers") if isinstance(artifacts, dict) else {}
    report_md_exists = bool(isinstance(exists, dict) and exists.get("report_md"))
    report_html_exists = bool(isinstance(exists, dict) and exists.get("report_html"))
    summary: Dict[str, Any] = {
        "report_md_exists": report_md_exists,
        "report_html_exists": report_html_exists,
        "report_exists": bool(report_md_exists and report_html_exists),
        "router_expected": False,
        "router_executed": bool(isinstance(markers, dict) and markers.get("has_routing")),
        "tiling_ok": True,
        "blocking_errors": [],
        "warnings": [],
    }
    if not report_md_exists:
        summary["blocking_errors"].append("report_md_missing")
    if not report_html_exists:
        summary["blocking_errors"].append("report_html_missing")

    goal_payload = _load_goal_intake_payload(run_dir)
    final_payload = goal_payload.get("final_payload") if isinstance(goal_payload.get("final_payload"), dict) else {}
    # Native writers persist the current goal inside final_payload. A legacy
    # top-level copy may be absent or stale and must not bypass delivery checks.
    structured_goal = final_payload.get("structured_goal")
    if not isinstance(structured_goal, dict) or not structured_goal:
        structured_goal = goal_payload.get("structured_goal")
    if not isinstance(structured_goal, dict) or not structured_goal:
        structured_goal = _load_goal_context_from_run_dir(run_dir)["structured_goal"]
    request_envelope = (
        goal_payload.get("request_envelope")
        if isinstance(goal_payload.get("request_envelope"), dict)
        else final_payload.get("request_envelope")
        if isinstance(final_payload.get("request_envelope"), dict)
        else {}
    )
    from .requested_artifacts import requested_artifact_errors
    requested_paths = _requested_output_paths(run_dir, request_envelope.get("final_outputs"))
    for literal_path in _explicit_output_artifact_paths(
        str(goal_payload.get("request") or "")
    ):
        if literal_path not in requested_paths:
            requested_paths.append(literal_path)
    summary["requested_output_paths"] = [str(path) for path in requested_paths]
    summary["blocking_errors"].extend(requested_artifact_errors(requested_paths))
    delivery_receipt = _run_path(run_dir, "requested_artifacts") / "delivery.json"
    if delivery_receipt.is_file():
        try:
            prior_delivery = _read_json(delivery_receipt)
            if prior_delivery.get("ok") is not True:
                summary["blocking_errors"].append("requested_output_delivery_incomplete")
        except (OSError, ValueError, AttributeError):
            summary["blocking_errors"].append("requested_output_delivery_receipt_invalid")
    workflow_name = str(request_envelope.get("workflow_name") or "").strip().lower()
    request_mode = _normalize_request_mode(request_envelope.get("request_mode"))
    response_mode = _normalize_response_mode(request_envelope.get("response_mode"))
    request_tasks = [task for task in (request_envelope.get("tasks") or []) if isinstance(task, dict)]
    has_design_task = any(
        str(task.get("task_type") or "").strip().lower() == "design_new_asos"
        for task in request_tasks
    )
    has_composite_task = any(
        str(task.get("task_type") or "").strip().lower() == "build_composite_report"
        for task in request_tasks
    )
    composite_required = (
        request_mode == "composite"
        or (response_mode == "composite" and (len(request_tasks) > 1 or has_composite_task))
    )
    if response_mode == "composite" and not composite_required:
        summary["warnings"].append("stale_single_task_composite_response_mode_ignored")

    # The task graph, not a legacy workflow label, determines whether design
    # artifacts are required. A compare/evaluate/analysis-only request may
    # inherit workflow_name="design_new_asos" from its controller while its
    # completed task has no structured design goal or strategy router.
    if not composite_required and not has_design_task and (
        request_tasks or (workflow_name and workflow_name != "design_new_asos")
    ):
        summary["ok"] = bool(summary["report_exists"] and not summary["blocking_errors"])
        return summary

    if not composite_required and has_design_task and len(request_tasks) == 1:
        scoped = _scoped_design_integrity(run_dir, request_tasks[0], request_envelope, skip_router=skip_router)
        if scoped is not None:
            summary["scoped_design_integrity"] = scoped
            if scoped.get("ok") is not True:
                summary["blocking_errors"].append("scoped_design_delivery_incomplete")
            summary["ok"] = bool(summary["report_exists"] and not summary["blocking_errors"])
            return summary

    if composite_required:
        composite_md_exists = bool(isinstance(exists, dict) and exists.get("composite_report_md"))
        composite_json_exists = bool(isinstance(exists, dict) and exists.get("composite_report_json"))
        task_index_exists = bool(isinstance(exists, dict) and exists.get("task_index_json"))
        summary.update(
            {
                "composite_report_md_exists": composite_md_exists,
                "composite_report_json_exists": composite_json_exists,
                "task_index_exists": task_index_exists,
                "completed_task_count": 0,
                "requested_task_count": len(
                    request_tasks
                ),
            }
        )
        if not composite_md_exists:
            summary["blocking_errors"].append("composite_report_md_missing")
        if not composite_json_exists:
            summary["blocking_errors"].append("composite_report_json_missing")
        if not task_index_exists:
            summary["blocking_errors"].append("task_index_missing")

        composite_payload: Dict[str, Any] = {}
        if composite_json_exists:
            try:
                composite_payload = _read_json(_run_path(run_dir, "composite_report.json"))
            except Exception:
                summary["blocking_errors"].append("composite_report_json_invalid")
            if isinstance(composite_payload, dict):
                summary["composite_report_status"] = str(
                    composite_payload.get("report_status") or ""
                ).strip().lower()
                if summary["composite_report_status"] == "partial":
                    summary["warnings"].append("composite_report_partial")

        indexed_tasks: Dict[str, Dict[str, Any]] = {}
        if task_index_exists:
            try:
                task_index_payload = _read_json(_run_path(run_dir, "task_index.json"))
            except Exception:
                task_index_payload = {}
                summary["blocking_errors"].append("task_index_invalid")
            for task_entry in task_index_payload.get("tasks") or []:
                if not isinstance(task_entry, dict):
                    continue
                task_id = str(task_entry.get("task_id") or "").strip()
                if task_id:
                    indexed_tasks[task_id] = task_entry

        completed_task_count = 0
        for requested_task in request_tasks:
            task_id = str(requested_task.get("task_id") or "").strip()
            task_type = str(requested_task.get("task_type") or "").strip().lower()
            indexed_task = indexed_tasks.get(task_id)
            if not task_id or not isinstance(indexed_task, dict):
                summary["blocking_errors"].append(f"task_index_entry_missing:{task_id or 'unknown'}")
                continue
            if str(indexed_task.get("status") or "").strip().lower() != "completed":
                summary["blocking_errors"].append(f"task_not_completed:{task_id}")
                continue
            completed_task_count += 1
            if task_type != "design_new_asos":
                continue
            scoped = _scoped_design_integrity(run_dir, requested_task, request_envelope, skip_router=skip_router)
            if scoped is not None and scoped.get("ok") is not True:
                summary["blocking_errors"].append(f"scoped_design_delivery_incomplete:{task_id}")
            outcome = indexed_task.get("design_outcome")
            if not isinstance(outcome, dict):
                summary["blocking_errors"].append(f"design_outcome_missing:{task_id}")
                continue
            outcome_status = str(outcome.get("outcome_status") or "").strip().lower()
            if outcome_status == "completed_missing_required_evidence":
                summary["warnings"].append(f"design_outcome_partial:{task_id}")
            elif outcome_status == "skipped":
                summary["warnings"].append(f"design_outcome_skipped:{task_id}")
            elif outcome_status not in {"completed_with_candidates", "completed_no_candidates"}:
                summary["blocking_errors"].append(f"design_outcome_incomplete:{task_id}")
            if outcome.get("missing_required_evidence"):
                summary["warnings"].append(f"design_evidence_missing:{task_id}")
            if outcome_status == "skipped":
                continue
            outcome_artifacts = outcome.get("artifacts") if isinstance(outcome.get("artifacts"), dict) else {}
            for artifact_key in ("generated_aso_set_json", "generated_filter_trace_json"):
                artifact_path = str(outcome_artifacts.get(artifact_key) or "").strip()
                if not artifact_path or not Path(artifact_path).is_file():
                    summary["blocking_errors"].append(
                        f"design_artifact_missing:{task_id}:{artifact_key}"
                    )
        summary["completed_task_count"] = completed_task_count
        summary["ok"] = bool(summary["report_exists"] and not summary["blocking_errors"])
        return summary

    if (has_design_task or workflow_name == "design_new_asos") and not structured_goal:
        summary["blocking_errors"].append("design_goal_missing")
    router_expected = False
    if not skip_router:
        router_expected = _resolve_run_splice_router(run_dir)
    summary["router_expected"] = router_expected
    routing_skip = _routing_skipped_for_run(final_payload, structured_goal)
    if routing_skip.get("skipped"):
        summary["router_skipped"] = True
        reason = str(routing_skip.get("reason") or "routing_skipped").strip()
        if reason:
            summary["warnings"].append(reason)

    if router_expected and not summary["router_executed"] and not routing_skip.get("skipped"):
        summary["blocking_errors"].append("router_missing_when_expected")

    if _routing_required_after_splice_eval(run_dir) and not routing_skip.get("skipped"):
        summary["blocking_errors"].append("routing_missing_after_splice_eval")
        summary["router_executed"] = False

    tiling_results = final_payload.get("tiling_results") if isinstance(final_payload.get("tiling_results"), dict) else {}
    if isinstance(tiling_results, dict) and tiling_results.get("error"):
        summary["tiling_ok"] = False
        summary["blocking_errors"].append("tiling_failed")

    from aso_agents.design_delivery import design_delivery
    branches = _build_branch_outcomes_for_report(structured_goal, final_payload)
    if has_design_task and not any(branch.get("requested") for branch in branches.values()):
        summary["blocking_errors"].append("design_branch_contract_missing")
    if any(branch.get("requested") for branch in branches.values()):
        binding_path = Path(run_dir) / "requested_binding_site_sets.json"
        binding_sets = json.loads(binding_path.read_text()) if binding_path.is_file() else {}
        delivery = design_delivery(structured_goal,
            _load_generated_set_payload(str(_run_path(run_dir, "generated_aso_set.json"))), branches,
            binding_sets=binding_sets,
            intervals_for_row=_goal_runtime_module()._tile_row_overlap_intervals)
        summary["design_delivery"] = delivery
        summary["blocking_errors"].extend(delivery["errors"])

    summary["ok"] = bool(summary["report_exists"] and not summary["blocking_errors"])
    return summary


def _required_tiling_reference_files(species: Optional[str]) -> List[str]:
    species_key = normalize_species(species)
    species_cfg = get_species_config(species_key)
    bowtie_prefix = Path(species_cfg.bowtie_prefix)
    required = [
        str(species_cfg.genome_fasta),
        str(species_cfg.chrom_sizes_path),
        str(species_cfg.gtf_path),
        f"{bowtie_prefix}.1.ebwt",
        f"{bowtie_prefix}.2.ebwt",
        f"{bowtie_prefix}.3.ebwt",
        f"{bowtie_prefix}.4.ebwt",
        f"{bowtie_prefix}.rev.1.ebwt",
        f"{bowtie_prefix}.rev.2.ebwt",
    ]
    if str(getattr(species_cfg, "conservation_mode", "available") or "available") != "disabled":
        required.extend([str(species_cfg.phastcons_path), str(species_cfg.phylop_path)])
    return required


def _tiling_reference_requirement_groups(species: Optional[str]) -> List[Tuple[str, List[str]]]:
    species_key = normalize_species(species)
    species_cfg = get_species_config(species_key)
    bowtie_prefix = Path(species_cfg.bowtie_prefix)
    groups = [
        (f"{species_key} genome FASTA", [str(species_cfg.genome_fasta)]),
        (f"{species_cfg.ucsc_build} chrom sizes", [str(species_cfg.chrom_sizes_path)]),
        (f"{species_key} GTF annotation", [str(species_cfg.gtf_path)]),
        (
            f"{species_cfg.ucsc_build} Bowtie 1 index set",
            [
                f"{bowtie_prefix}.1.ebwt",
                f"{bowtie_prefix}.2.ebwt",
                f"{bowtie_prefix}.3.ebwt",
                f"{bowtie_prefix}.4.ebwt",
                f"{bowtie_prefix}.rev.1.ebwt",
                f"{bowtie_prefix}.rev.2.ebwt",
            ],
        ),
    ]
    if str(getattr(species_cfg, "conservation_mode", "available") or "available") != "disabled":
        groups.insert(2, (f"{species_cfg.ucsc_build} phastCons bigWig", [str(species_cfg.phastcons_path)]))
        groups.insert(3, (f"{species_cfg.ucsc_build} phyloP bigWig", [str(species_cfg.phylop_path)]))
    return groups


def _extract_species_from_run(run_dir: str) -> Optional[str]:
    context = _goal_payload_context(run_dir)
    structured_goal = context["structured_goal"]
    species = structured_goal.get("species")
    if not isinstance(species, str):
        return None
    value = species.strip().lower()
    return value or None


def _normalize_target_region(region: Any) -> str:
    if not isinstance(region, str):
        return ""
    normalized = region.strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "utr_3": "utr3",
        "3utr": "utr3",
        "utr_5": "utr5",
        "5utr": "utr5",
    }
    return aliases.get(normalized, normalized)


def _scoped_steric_splice_requirement(final_payload, structured_goal, stage):
    """Aggregate per-branch requirements before consulting a legacy run flag."""
    jobs = _get_design_jobs(final_payload, "steric")
    programs = _design_programs(structured_goal, "steric")
    if not jobs and not programs:
        if canonical_gapmer_programs_exclude_splicing(structured_goal):
            return False
        return None
    resolver = (_design_request_requires_splice_eval if stage == "eval"
                else _design_request_requires_splice_router)
    return any(resolver(branch, fallback_goal=structured_goal)
               for branch in (jobs or programs)
               if str(branch.get("status") or "").lower() != "skipped"
               and _coerce_bool(branch.get("skipped")) is not True)


def _resolve_run_splice_eval(run_dir: str) -> bool:
    context = _goal_payload_context(run_dir)
    final_payload = context["final_payload"]
    structured_goal = context["structured_goal"]
    steric_jobs = final_payload.get("steric_design_jobs") if isinstance(final_payload.get("steric_design_jobs"), list) else []
    if _coerce_bool(final_payload.get("steric_constraints_exhausted")) or _coerce_bool(structured_goal.get("steric_constraints_exhausted")):
        if steric_jobs and not any(_normalize_region_rows(job.get("region_rows")) for job in steric_jobs if isinstance(job, dict)):
            return False

    scoped = _scoped_steric_splice_requirement(final_payload, structured_goal, "eval")
    if scoped is not None:
        return scoped

    target_region = _normalize_target_region(structured_goal.get("target_region"))
    intent = str(structured_goal.get("intent") or "").strip().lower()
    if intent == "binding" and target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False

    explicit = _coerce_bool(final_payload.get("run_splice_eval"))
    if explicit is None:
        explicit = _coerce_bool(structured_goal.get("run_splice_eval"))
    if explicit is not None:
        return explicit
    if _design_programs_are_gapmer_only(structured_goal):
        return False
    if _has_splice_objective_signal(structured_goal):
        return True

    runtime = _goal_runtime_module()
    resolver = getattr(runtime, "_resolve_run_splice_eval", None)
    if callable(resolver):
        try:
            return bool(resolver(structured_goal))
        except Exception:
            pass

    if target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False

    if intent == "binding":
        return False

    return True


def _resolve_run_splice_router(run_dir: str) -> bool:
    context = _goal_payload_context(run_dir)
    payload = context["payload"]
    final_payload = context["final_payload"]
    structured_goal = context["structured_goal"]
    steric_jobs = final_payload.get("steric_design_jobs") if isinstance(final_payload.get("steric_design_jobs"), list) else []
    if _coerce_bool(final_payload.get("steric_constraints_exhausted")) or _coerce_bool(structured_goal.get("steric_constraints_exhausted")):
        if steric_jobs and not any(_normalize_region_rows(job.get("region_rows")) for job in steric_jobs if isinstance(job, dict)):
            return False
    scoped = _scoped_steric_splice_requirement(final_payload, structured_goal, "router")
    if scoped is not None:
        return scoped
    target_region = _normalize_target_region(structured_goal.get("target_region"))
    intent = str(structured_goal.get("intent") or "").strip().lower()
    if intent == "binding" and target_region in {"utr3", "utr5", "utrs", "translation_start", "cds"}:
        return False
    explicit = _coerce_bool(final_payload.get("run_splice_router"))
    if explicit is None:
        explicit = _coerce_bool(structured_goal.get("run_splice_router"))
    if explicit is not None:
        return explicit
    if _design_programs_are_gapmer_only(structured_goal):
        return False
    if _has_splice_objective_signal(structured_goal):
        return True

    runtime = _goal_runtime_module()
    resolver = getattr(runtime, "_resolve_run_splice_router", None)
    if callable(resolver):
        try:
            return bool(resolver(structured_goal, str(payload.get("request") or "")))
        except Exception:
            pass
    if _resolve_run_splice_eval(run_dir):
        return True
    return False


def _resolve_intent_knockdown(run_dir: str) -> bool:
    context = _goal_payload_context(run_dir)
    structured_goal = context["structured_goal"]
    if _coerce_bool((structured_goal.get("junction_gapmers") or {}).get("enabled")) is True:
        return True
    gapmer_programs = _effective_gapmer_design_programs(structured_goal)
    if gapmer_programs:
        has_steric_primary = bool(_design_programs(structured_goal, "steric") or _has_splice_objective_signal(structured_goal))
        if has_steric_primary and _gapmer_programs_are_conditional_fallback_only(structured_goal):
            return _run_needs_conditional_gapmer_fallback(run_dir)
        return True
    if _splice_switch_gapmer_support_policy(structured_goal, _design_programs(structured_goal)).get("enabled"):
        return True
    intent = str(structured_goal.get("intent") or "").strip().lower()
    return intent == "knockdown"


def _resolve_intent_steric(run_dir: str) -> bool:
    context = _goal_payload_context(run_dir)
    final_payload = context["final_payload"]
    structured_goal = context["structured_goal"]
    steric_jobs = final_payload.get("steric_design_jobs") if isinstance(final_payload.get("steric_design_jobs"), list) else []
    if _coerce_bool(final_payload.get("steric_constraints_exhausted")) or _coerce_bool(structured_goal.get("steric_constraints_exhausted")):
        if steric_jobs and not any(_normalize_region_rows(job.get("region_rows")) for job in steric_jobs if isinstance(job, dict)):
            return False
    steric_programs = _design_programs(structured_goal, "steric")
    if steric_programs:
        return True
    if _design_programs_are_gapmer_only(structured_goal):
        return False
    if _resolve_intent_knockdown(run_dir):
        if not _resolve_run_splice_eval(run_dir) and not _resolve_run_splice_router(run_dir):
            return False
        return True
    intent = str(structured_goal.get("intent") or "").strip().lower()
    return intent in {"splice_modulation", "binding"}


def _artifact_markers_for_run(run_dir: str) -> Dict[str, Any]:
    artifacts = _discover_core_artifacts(run_dir)
    markers = artifacts.get("markers") if isinstance(artifacts.get("markers"), dict) else {}
    return markers if isinstance(markers, dict) else {}


def _next_status_after_steric_uniqueness(run_dir: str) -> Tuple[str, str]:
    markers = _artifact_markers_for_run(run_dir)
    if markers.get("has_routing"):
        return "routing_ready", "routing_ready"
    if markers.get("has_splice_eval"):
        return "splice_eval_ready", "splice_eval_ready"
    return "steric_scoring_ready", "steric_scoring_ready"


def _clear_steric_uniqueness_outputs(
    *,
    run_dir: str,
    structured_goal: Dict[str, Any],
    final_payload: Dict[str, Any],
    jobs: Optional[List[Dict[str, Any]]] = None,
    clear_aggregate: bool = False,
) -> None:
    run_root = Path(run_dir).expanduser().resolve()

    def _safe_remove(raw_path: Any) -> None:
        if not isinstance(raw_path, str) or not raw_path.strip():
            return
        candidate = Path(raw_path).expanduser()
        try:
            resolved = candidate.resolve()
        except Exception:
            resolved = candidate
        if not _is_within(run_root, resolved):
            return
        try:
            if resolved.exists() and not resolved.is_dir():
                resolved.unlink()
        except Exception:
            pass

    def _clear_result_payload(result_payload: Dict[str, Any], output_dir: str = "") -> None:
        for key in ("uniqueness_scored_path", "uniqueness_scored_path_unfiltered", "uniqueness_csv"):
            _safe_remove(result_payload.get(key))
            result_payload.pop(key, None)
        result_payload.pop("uniqueness_constraint_filtering", None)
        if output_dir:
            for name in (
                "steric_scored_uniqueness.json",
                "steric_scored_uniqueness.filtered.json",
                "steric_scored_uniqueness.unfiltered.json",
                "steric_uniqueness_ranked.csv",
                "steric_uniqueness_ranked.xlsx",
            ):
                _safe_remove(os.path.join(output_dir, name))

    if clear_aggregate:
        tiling_results = final_payload.get("tiling_results")
        if isinstance(tiling_results, dict):
            _clear_result_payload(tiling_results, str(_write_run_path(run_dir, "tiling")))
            for name in (
                "steric_scored_uniqueness.json",
                "steric_scored_uniqueness.filtered.json",
                "steric_uniqueness_ranked.csv",
                "steric_uniqueness_ranked.xlsx",
                "scored_tiles.json",
                "scored_tiles.filtered.json",
            ):
                _safe_remove(str(_write_run_path(run_dir, "tiling", name)))

    steric_results_by_job = _ensure_design_results_map(
        structured_goal=structured_goal,
        final_payload=final_payload,
        modality="steric",
    )
    scoped_jobs = jobs if isinstance(jobs, list) else _get_design_jobs(final_payload, "steric")
    for job in scoped_jobs:
        if not isinstance(job, dict):
            continue
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            continue
        job_result = steric_results_by_job.get(job_id)
        if isinstance(job_result, dict):
            _clear_result_payload(job_result, str(job_result.get("output_dir") or job.get("output_dir") or ""))


